  /**
   * Determines if a given href matches the current route.
   * Handles exact matches, query-param–based sub-tabs,
   * and nested paths (properties/pending etc.).
   */
  const isActive = (href: string): boolean => {
    const currentPath = router.pathname;
    const currentStatus = router.query.status as string | undefined;

    // Exact dashboard match
    if (href === '/admin') return currentPath === '/admin';

    // Simple exact-match routes
    const exactRoutes = [
      '/admin/users',
      '/admin/inquiries',
      '/admin/leads',
      '/admin/reports',
      '/admin/analytics',
      '/admin/cities',
      '/admin/settings',
      '/admin/comments',
      '/admin/chats',
    ];
    if (exactRoutes.includes(href)) return currentPath === href;

    // Applications — combined inbox (type + status query params)
    if (href.startsWith('/admin/applications')) {
      if (!currentPath.startsWith('/admin/applications')) return false;
      // Detail page: /admin/applications/[id]
      if (currentPath !== '/admin/applications') return false;
      const hrefParams = new URL(href, 'http://x').searchParams;
      const hrefType = hrefParams.get('type');
      const hrefStatus = hrefParams.get('status');
      const currentType = router.query.type as string | undefined;
      // All Applications (no filters)
      if (!hrefType && !hrefStatus) {
        return !currentType && (!currentStatus || currentStatus === 'all');
      }
      // Filtered tab
      if (hrefType && hrefStatus) {
        return currentType === hrefType && currentStatus === hrefStatus;
      }
      return false;
    }

    // Societies admin — nested path + query-param status
    if (href.startsWith('/admin/societies')) {
      if (!currentPath.startsWith('/admin/societies')) return false;
      if (currentPath !== '/admin/societies') return false;
      const hrefStatus = new URL(href, 'http://x').searchParams.get('status');
      if (!hrefStatus) return !currentStatus || currentStatus === 'all';
      return currentStatus === hrefStatus;
    }

    // Developers — handle query-param tabs
    if (href.startsWith('/admin/developers')) {
      if (currentPath !== '/admin/developers') return false;
      const hrefStatus = new URL(href, 'http://x').searchParams.get('status');
      if (!hrefStatus) return !currentStatus || currentStatus === 'all';
      return currentStatus === hrefStatus;
    }

    // Agents — handle query-param tabs
    if (href.startsWith('/admin/agents')) {
      if (currentPath !== '/admin/agents') return false;
      const hrefStatus = new URL(href, 'http://x').searchParams.get('status');
      if (!hrefStatus) return !currentStatus || currentStatus === 'all';
      return currentStatus === hrefStatus;
    }

    // Verified Owners — handle query-param tabs + detail pages
    if (href.startsWith('/admin/owners')) {
      if (!currentPath.startsWith('/admin/owners')) return false;
      
      // If we are on a detail page like /admin/owners/123, keep the parent menu active
      if (currentPath.split('/').length > 3) return href === '/admin/owners';

      const hrefStatus = new URL(href, 'http://x').searchParams.get('status');
      if (!hrefStatus) return !currentStatus || currentStatus === 'all';
      return currentStatus === hrefStatus;
    }

    // Properties — nested paths
    if (href.startsWith('/admin/properties')) {
      if (!currentPath.startsWith('/admin/properties')) return false;
      return currentPath === href;
    }

    // Projects — nested paths
    if (href.startsWith('/admin/projects')) {
      if (!currentPath.startsWith('/admin/projects')) return false;
      return currentPath === href;
    }

    // Content, Marketing, and other simple sub-pages
    return currentPath === href;
  };

  const isMenuGroupActive = (item: MenuItem): boolean => {
    if (item.href && isActive(item.href)) return true;
    return (
      item.children?.some((child) => child.href && isActive(child.href)) ??
      false
    );
  };

  const handleLogout = async () => {
    await signOut({ callbackUrl: '/auth/login' });
  };

  const handleNotificationClick = (item: NotificationItem) => {
    // Clear local unread count for inquiries immediately (optimistic UI)
    if (item.id === 'inquiries-new') {
      setSidebarStats((prev) => ({ ...prev, unreadInquiries: 0 }));
    }
    setShowNotifications(false);

    // If already on developers page, dispatch tab-change event instead of navigate
    if (
      item.id === 'developers-pending' &&
      router.pathname === '/admin/developers'
    ) {
      window.dispatchEvent(
        new CustomEvent('changeDevTab', { detail: 'pending' })
      );
      return;
    }

    void router.push(item.href);
  };

  // ── Render helpers ──────────────────────────────────────────────────────────

  const renderMenuItem = (
    item: MenuItem,
    isChild = false
  ): React.ReactElement => {
    const hasChildren = (item.children?.length ?? 0) > 0;
    const isExpanded = expandedMenus.includes(item.name);
    const groupActive = isMenuGroupActive(item);

    if (hasChildren) {
      return (
        <div key={item.name}>
          <button
            onClick={() => toggleSubmenu(item.name)}
            className={`w-full flex items-center justify-between px-3 py-2.5 rounded-xl text-sm font-medium transition-colors duration-150 ${
              groupActive
                ? 'bg-[#029bba]/10 text-[#029bba]'
                : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'
            }`}
          >
            <div className="flex items-center gap-3">
              {item.icon}
              {sidebarOpen && <span>{item.name}</span>}
            </div>
            {sidebarOpen && (
              <ChevronDown
                className={`w-4 h-4 transition-transform duration-200 ${
                  isExpanded ? 'rotate-180' : 'rotate-0'
                }`}
              />
            )}
          </button>

          {/* 
            Tailwind max-height transition replaces framer-motion.
            max-h-0 → max-h-96 with overflow-hidden gives smooth
            expand/collapse without any animation library.
          */}
          <div
            className={`ml-4 mt-1 space-y-1 overflow-hidden transition-all duration-200 ease-in-out ${
              isExpanded && sidebarOpen ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'
            }`}
          >
            {item.children?.map((child) => renderMenuItem(child, true))}
          </div>
        </div>
      );
    }

    const href = item.href ?? '#';
    const active = isActive(href);

    return (
      <Link key={item.name} href={href}>
        <div
          className={`flex items-center justify-between px-3 py-2.5 rounded-xl text-sm font-medium transition-colors duration-150 cursor-pointer ${
            active
              ? 'bg-[#029bba] text-white shadow-md shadow-[#029bba]/20'
              : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'
          } ${isChild ? 'ml-2' : ''}`}
        >
          <div className="flex items-center gap-3">
            {item.icon}
            {sidebarOpen && <span>{item.name}</span>}
          </div>

          {/* Badge — only shown when sidebar is expanded */}
          {typeof item.badge === 'number' &&
            item.badge > 0 &&
            sidebarOpen && (
              <span
                className={`px-2 py-0.5 text-xs font-semibold rounded-full ${
                  active
                    ? 'bg-white/20 text-white'
                    : 'bg-red-100 text-red-600'
                }`}
              >
                {item.badge}
              </span>
            )}
        </div>
      </Link>
    );
  };

  // ── Render ──────────────────────────────────────────────────────────────────

  return (
    <div className="min-h-screen bg-gray-50">
      {/* ── Mobile overlay (replaces framer-motion AnimatePresence) ── */}
      <div
        className={`fixed inset-0 bg-black/50 z-40 lg:hidden transition-opacity duration-300 ${
          mobileSidebarOpen
            ? 'opacity-100 pointer-events-auto'
            : 'opacity-0 pointer-events-none'
        }`}
        onClick={() => setMobileSidebarOpen(false)}
      />

      {/* ── Sidebar ── */}
      <aside
        className={`fixed top-0 left-0 h-full bg-white border-r border-gray-200 z-50 flex flex-col
          transition-all duration-300 ease-in-out
          ${sidebarOpen ? 'w-64' : 'w-20'}
          ${mobileSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        `}
      >
        {/* Logo row */}
        <div className="h-16 flex items-center justify-between px-4 border-b border-gray-200 shrink-0">
          <Link href="/admin" className="flex items-center gap-2 min-w-0">
            <div className="w-10 h-10 rounded-xl bg-[#029bba] flex items-center justify-center shrink-0">
              <Shield className="w-6 h-6 text-white" />
            </div>
            {sidebarOpen && (
              <div className="min-w-0">
                <p className="font-bold text-gray-900 leading-tight truncate">
                  Highrise.pk
                </p>
                <p className="text-xs text-gray-500 leading-tight">
                  Admin Panel
                </p>
              </div>
            )}
          </Link>

          {/* Desktop collapse toggle */}
          <button
            onClick={() => setSidebarOpen((o) => !o)}
            className="hidden lg:flex p-1.5 rounded-lg hover:bg-gray-100 transition-colors shrink-0"
            aria-label={sidebarOpen ? 'Collapse sidebar' : 'Expand sidebar'}
          >
            <Menu className="w-5 h-5 text-gray-500" />
          </button>

          {/* Mobile close */}
          <button
            onClick={() => setMobileSidebarOpen(false)}
            className="lg:hidden p-1.5 rounded-lg hover:bg-gray-100 transition-colors shrink-0"
            aria-label="Close sidebar"
          >
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto p-4 space-y-1">
          {menuItems.map((item) => renderMenuItem(item))}
        </nav>

        {/* User footer */}
        <div className="shrink-0 p-4 border-t border-gray-200">
          <div className="flex items-center gap-3">
            {/* Avatar */}
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-[#029bba] to-[#004063] flex items-center justify-center text-white font-semibold shrink-0">
              {authUser?.name?.charAt(0)?.toUpperCase() ?? 'A'}
            </div>

            {sidebarOpen && (
              <>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-900 truncate">
                    {authUser?.name ?? 'Admin User'}
                  </p>
                  <p className="text-xs text-gray-500 truncate">
                    {authUser?.email ?? 'admin@highrise.pk'}
                  </p>
                </div>
                <button
                  onClick={handleLogout}
                  className="p-2 rounded-lg hover:bg-red-50 text-gray-400 hover:text-red-500 transition-colors shrink-0"
                  title="Logout"
                  aria-label="Logout"
                >
                  <LogOut className="w-5 h-5" />
                </button>
              </>
            )}
          </div>
        </div>
      </aside>

      {/* ── Main content area ── */}
      <div
        className={`transition-all duration-300 ease-in-out ${
          sidebarOpen ? 'lg:ml-64' : 'lg:ml-20'
        }`}
      >
        {/* ── Top header ── */}
        <header className="h-16 bg-white border-b border-gray-200 sticky top-0 z-30">
          <div className="h-full px-4 flex items-center justify-between gap-4">
            {/* Mobile menu button */}
            <button
              onClick={() => setMobileSidebarOpen(true)}
              className="lg:hidden p-2 rounded-lg hover:bg-gray-100 transition-colors shrink-0"
              aria-label="Open sidebar"
            >
              <Menu className="w-5 h-5 text-gray-600" />
            </button>

            {/* Search — visual placeholder (wired in Section 10) */}
            <div className="hidden md:flex items-center flex-1 max-w-md">
              <div className="relative w-full">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  type="text"
                  placeholder="Search properties, users, projects..."
                  disabled
                  className="w-full pl-10 pr-4 py-2 rounded-xl border border-gray-200 bg-gray-50 text-sm text-gray-400 cursor-not-allowed outline-none"
                  aria-label="Global search (coming soon)"
                />
              </div>
            </div>

            {/* Right actions */}
            <div className="flex items-center gap-2 shrink-0">
              {/* Help dropdown */}
              <div className="relative" ref={helpRef}>
                <button
                  onClick={() => {
                    setShowHelp((v) => !v);
                    setShowNotifications(false);
                  }}
                  className="p-2 rounded-xl hover:bg-gray-100 text-gray-500 transition-colors"
                  aria-label="Help"
                >
                  <HelpCircle className="w-5 h-5" />
                </button>

                {showHelp && (
                  <div className="absolute right-0 mt-2 w-72 bg-white border border-gray-100 rounded-2xl shadow-lg z-40 p-4">
                    <h3 className="text-sm font-semibold text-gray-900 mb-1">
                      Need help?
                    </h3>
                    <p className="text-xs text-gray-500 mb-3">
                      For support or questions about the Highrise.pk Admin
                      Panel, contact the team below.
                    </p>
                    <div className="space-y-2 text-xs">
                      <a
                        href="mailto:info@highrise.pk"
                        className="flex items-center justify-between px-3 py-2 rounded-xl bg-gray-50 hover:bg-gray-100 text-gray-700 transition-colors"
                      >
                        <span>Email support</span>
                        <span className="text-[11px] text-gray-500">
                          info@highrise.pk
                        </span>
                      </a>
                      <p className="text-[11px] text-gray-500">
                        Urgent issues:{' '}
                        <span className="font-medium">
                          admin@highrise.pk
                        </span>
                      </p>
                    </div>
                  </div>
                )}
              </div>

              {/* Notifications dropdown */}
              <div className="relative" ref={notifRef}>
                <button
                  onClick={() => {
                    setShowNotifications((v) => !v);
                    setShowHelp(false);
                  }}
                  className="relative p-2 rounded-xl hover:bg-gray-100 text-gray-500 transition-colors"
                  aria-label={`Notifications${notificationsCount > 0 ? ` — ${notificationsCount} pending` : ''}`}
                >
                  <Bell className="w-5 h-5" />
                  {notificationsCount > 0 && (
                    <span className="absolute top-1 right-1 w-4 h-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
                      {notificationsCount > 99 ? '99+' : notificationsCount}
                    </span>
                  )}
                </button>

                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-96 bg-white border border-gray-100 rounded-2xl shadow-2xl z-40 overflow-hidden">
                    {/* Enhanced header with gradient */}
                    <div className="px-5 py-4 bg-gradient-to-r from-[#029bba] to-[#004063] text-white">
                      <div className="flex items-center justify-between mb-1">
                        <h3 className="text-base font-bold text-white flex items-center gap-2">
                          <Bell className="w-4 h-4" />
                          Notifications
                        </h3>
                        {notificationsCount > 0 && (
                          <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-white/20 text-white text-xs font-bold">
                            {notificationsCount}
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-white/80">
                        {notificationsCount > 0
                          ? `${notificationsCount} item${notificationsCount > 1 ? 's' : ''} need attention`
                          : 'All caught up — great work!'}
                      </p>
                    </div>

                    <div className="max-h-[420px] overflow-y-auto">
                      {notifications.some((n) => n.count > 0) ? (
                        <div className="divide-y divide-gray-50">
                          {notifications
                            .filter((n) => n.count > 0)
                            .map((n) => (
                              <button
                                key={n.id}
                                type="button"
                                onClick={() => handleNotificationClick(n)}
                                className="w-full text-left flex items-start gap-3 px-4 py-3.5 hover:bg-gray-50 transition-colors group"
                              >
                                <div
                                  className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${n.colorClass} group-hover:scale-110 transition-transform`}
                                >
                                  {n.icon}
                                </div>
                                <div className="flex-1 min-w-0">
                                  <div className="flex items-center justify-between gap-2 mb-0.5">
                                    <p className="text-sm font-semibold text-gray-900 truncate group-hover:text-[#029bba] transition-colors">
                                      {n.label}
                                    </p>
                                    <span className="inline-flex items-center justify-center min-w-[24px] h-5 px-2 text-[11px] font-bold rounded-full bg-red-500 text-white shrink-0">
                                      {n.count > 99 ? '99+' : n.count}
                                    </span>
                                  </div>
                                  <p className="text-xs text-gray-500 line-clamp-1">
                                    {n.description}
                                  </p>
                                </div>
                              </button>
                            ))}
                        </div>
                      ) : (
                        <div className="px-6 py-12 text-center">
                          <div className="w-16 h-16 rounded-2xl bg-emerald-50 flex items-center justify-center mx-auto mb-3">
                            <CheckCircle className="w-8 h-8 text-emerald-500" />
                          </div>
                          <p className="text-sm font-bold text-gray-800 mb-1">
                            You&apos;re all caught up!
                          </p>
                          <p className="text-xs text-gray-500">
                            No pending items need attention right now.
                          </p>
                        </div>
                      )}
                    </div>

                    {/* Footer with auto-refresh indicator */}
                    <div className="px-4 py-2.5 bg-gray-50 border-t border-gray-100 flex items-center justify-between">
                      <p className="text-[10px] text-gray-500 flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                        Auto-refreshes every 30s
                      </p>
                      <button
                        type="button"
                        onClick={() => {
                          setShowNotifications(false);
                          void fetchSidebarStats();
                        }}
                        className="text-[11px] text-[#029bba] font-semibold hover:underline"
                      >
                        Refresh now
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* View Site */}
              <Link
                href="/"
                target="_blank"
                rel="noopener noreferrer"
                className="hidden sm:flex items-center gap-2 px-4 py-2 rounded-xl bg-gray-100 hover:bg-gray-200 text-gray-700 text-sm font-medium transition-colors"
              >
                <Home className="w-4 h-4" />
                View Site
              </Link>
            </div>
          </div>
        </header>

        {/* ── Page content ── */}
        <main className="p-4 md:p-6">{children}</main>
      </div>
    </div>
  );
}

// components/admin/BuildingFloorPlansSection.tsx

import React, { useState } from 'react';
import {
  Building2,
  Plus,
  Trash2,
  ChevronDown,
  ChevronUp,
  GripVertical,
  Info,
  Layers,
} from 'lucide-react';
import FileUploader from './FileUploader';

// Type for a single floor plan
export interface BuildingFloorPlan {
  floorName: string;
  floorNumber?: number;
  floorType?: 'parking' | 'commercial' | 'residential' | 'amenity' | 'rooftop' | 'mixed';
  imageUrl?: string;
  imagePublicId?: string;
  pdfUrl?: string;
  pdfPublicId?: string;
  description?: string;
  unitsOnFloor?: string[];
}

interface BuildingFloorPlansSectionProps {
  floorPlans: BuildingFloorPlan[];
  onChange: (floorPlans: BuildingFloorPlan[]) => void;
  projectSlug?: string;
  disabled?: boolean;
}

// Predefined floor names for quick selection
const COMMON_FLOOR_NAMES = [
  'Basement 2',
  'Basement 1',
  'Ground Floor',
  'Mezzanine',
  '1st Floor',
  '2nd Floor',
  '3rd Floor',
  '4th Floor',
  '5th Floor',
  '6th Floor',
  '7th Floor',
  '8th Floor',
  '9th Floor',
  '10th Floor',
  '11th to 15th Floor (Typical)',
  '16th to 20th Floor (Typical)',
  '21st to 25th Floor (Typical)',
  '26th to 30th Floor (Typical)',
  'Penthouse Floor',
  'Rooftop',
];

const FLOOR_TYPES = [
  { value: 'parking', label: '🅿️ Parking' },
  { value: 'commercial', label: '🏪 Commercial' },
  { value: 'residential', label: '🏠 Residential' },
  { value: 'amenity', label: '✨ Amenity' },
  { value: 'rooftop', label: '🌆 Rooftop' },
  { value: 'mixed', label: '🔀 Mixed Use' },
];

export default function BuildingFloorPlansSection({
  floorPlans,
  onChange,
  projectSlug = 'general',
  disabled = false,
}: BuildingFloorPlansSectionProps) {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);

  // Add new floor plan
  const addFloorPlan = () => {
    const newFloor: BuildingFloorPlan = {
      floorName: '',
      floorNumber: floorPlans.length,
      floorType: 'residential',
      description: '',
    };
    onChange([...floorPlans, newFloor]);
    setExpandedIndex(floorPlans.length); // Expand new floor
  };

  // Remove floor plan
  const removeFloorPlan = (index: number) => {
    const updated = floorPlans.filter((_, i) => i !== index);
    onChange(updated);
    if (expandedIndex === index) {
      setExpandedIndex(null);
    }
  };

  // Update a specific floor plan
  const updateFloorPlan = (index: number, updates: Partial<BuildingFloorPlan>) => {
    const updated = floorPlans.map((floor, i) =>
      i === index ? { ...floor, ...updates } : floor
    );
    onChange(updated);
  };

  // Move floor up
  const moveUp = (index: number) => {
    if (index === 0) return;
    const updated = [...floorPlans];
    [updated[index - 1], updated[index]] = [updated[index], updated[index - 1]];
    onChange(updated);
    setExpandedIndex(index - 1);
  };

  // Move floor down
  const moveDown = (index: number) => {
    if (index === floorPlans.length - 1) return;
    const updated = [...floorPlans];
    [updated[index], updated[index + 1]] = [updated[index + 1], updated[index]];
    onChange(updated);
    setExpandedIndex(index + 1);
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 bg-gradient-to-r from-emerald-500/10 to-transparent border-b border-gray-200">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500 flex items-center justify-center">
              <Building2 className="w-5 h-5 text-white" />
            </div>
            <div>
              <h3 className="text-lg font-semibold text-gray-900">
                Building Floor Plans
              </h3>
              <p className="text-sm text-gray-500">
                Add floor plans for each level of the building
              </p>
            </div>
          </div>

          {!disabled && (
            <button
              type="button"
              onClick={addFloorPlan}
              className="flex items-center gap-2 px-4 py-2 bg-emerald-500 text-white rounded-xl hover:bg-emerald-600 transition-colors text-sm font-medium"
            >
              <Plus className="w-4 h-4" />
              Add Floor
            </button>
          )}
        </div>
      </div>

      {/* Info Banner */}
      {floorPlans.length === 0 && (
        <div className="mx-6 mt-4 p-4 bg-gray-50 border border-gray-200 rounded-xl flex items-start gap-3">
          <Layers className="w-5 h-5 text-gray-400 flex-shrink-0 mt-0.5" />
          <div className="text-sm text-gray-600">
            <p className="font-medium text-gray-700">No floor plans added yet</p>
            <p className="mt-1">
              Click "Add Floor" to add floor plans for Ground Floor, 1st Floor, 2nd Floor, etc.
              You can upload an image or PDF for each floor.
            </p>
          </div>
        </div>
      )}

      {/* Floor Plans List */}
      <div className="p-6 space-y-4">
        {floorPlans.map((floor, index) => (
          <div
            key={index}
            className="border border-gray-200 rounded-xl overflow-hidden bg-gray-50"
          >
            {/* Floor Header (Clickable) */}
            <div
              onClick={() =>
                setExpandedIndex(expandedIndex === index ? null : index)
              }
              className="px-4 py-3 bg-white flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors"
            >
              <div className="flex items-center gap-3">
                <GripVertical className="w-4 h-4 text-gray-400" />
                <div className="w-8 h-8 rounded-lg bg-emerald-100 flex items-center justify-center">
                  <span className="text-sm font-bold text-emerald-600">
                    {index + 1}
                  </span>
                </div>
                <div>
                  <p className="font-medium text-gray-900">
                    {floor.floorName || `Floor ${index + 1}`}
                  </p>
                  <p className="text-xs text-gray-500">
                    {floor.floorType
                      ? FLOOR_TYPES.find((t) => t.value === floor.floorType)?.label
                      : 'No type selected'}
                    {(floor.imageUrl || floor.pdfUrl) && (
                      <span className="ml-2 text-emerald-600">
                        • {floor.imageUrl && floor.pdfUrl ? 'Image + PDF' : floor.imageUrl ? 'Image' : 'PDF'}
                      </span>
                    )}
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                {/* Move Up/Down */}
                {!disabled && (
                  <>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        moveUp(index);
                      }}
                      disabled={index === 0}
                      className="p-1.5 rounded-lg hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed"
                      title="Move up"
                    >
                      <ChevronUp className="w-4 h-4 text-gray-500" />
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        moveDown(index);
                      }}
                      disabled={index === floorPlans.length - 1}
                      className="p-1.5 rounded-lg hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed"
                      title="Move down"
                    >
                      <ChevronDown className="w-4 h-4 text-gray-500" />
                    </button>
                  </>
                )}

                {/* Delete */}
                {!disabled && (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      removeFloorPlan(index);
                    }}
                    className="p-1.5 rounded-lg hover:bg-red-100 text-red-500"
                    title="Delete floor"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}

                {/* Expand/Collapse Icon */}
                <ChevronDown
                  className={`w-5 h-5 text-gray-400 transition-transform ${
                    expandedIndex === index ? 'rotate-180' : ''
                  }`}
                />
              </div>
            </div>

            {/* Floor Details (Expandable) */}
            {expandedIndex === index && (
              <div className="px-4 py-4 border-t border-gray-200 space-y-4">
                {/* Floor Name & Type Row */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {/* Floor Name */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Floor Name <span className="text-red-500">*</span>
                    </label>
                    <select
                      value={floor.floorName}
                      onChange={(e) => {
                        const value = e.target.value;
                        if (value === '__custom__') {
                          updateFloorPlan(index, { floorName: '' });
                        } else {
                          updateFloorPlan(index, { floorName: value });
                        }
                      }}
                      className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none"
                      disabled={disabled}
                    >
                      <option value="">Select floor name</option>
                      {COMMON_FLOOR_NAMES.map((name) => (
                        <option key={name} value={name}>
                          {name}
                        </option>
                      ))}
                      <option value="__custom__">-- Custom Name --</option>
                    </select>

                    {/* Custom Floor Name Input */}
                    {floor.floorName !== '' &&
                      !COMMON_FLOOR_NAMES.includes(floor.floorName) && (
                        <input
                          type="text"
                          value={floor.floorName}
                          onChange={(e) =>
                            updateFloorPlan(index, { floorName: e.target.value })
                          }
                          placeholder="Enter custom floor name"
                          className="w-full mt-2 px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none"
                          disabled={disabled}
                        />
                      )}
                  </div>

                  {/* Floor Type */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Floor Type
                    </label>
                    <select
                      value={floor.floorType || ''}
                      onChange={(e) =>
                        updateFloorPlan(index, {
                          floorType: e.target.value as BuildingFloorPlan['floorType'],
                        })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none"
                      disabled={disabled}
                    >
                      <option value="">Select type</option>
                      {FLOOR_TYPES.map((type) => (
                        <option key={type.value} value={type.value}>
                          {type.label}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                {/* Description */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Description (Optional)
                  </label>
                  <textarea
                    value={floor.description || ''}
                    onChange={(e) =>
                      updateFloorPlan(index, { description: e.target.value })
                    }
                    placeholder="E.g., Contains 4 apartments, lobby, and service area..."
                    rows={2}
                    className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none resize-none"
                    disabled={disabled}
                  />
                </div>

                {/* File Uploads */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {/* Floor Plan Image */}
                  <FileUploader
                    label="Floor Plan Image"
                    accept="image"
                    folder={`projects/${projectSlug}/floor-plans`}
                    value={
                      floor.imageUrl && floor.imagePublicId
                        ? { url: floor.imageUrl, publicId: floor.imagePublicId }
                        : null
                    }
                    onChange={(file) =>
                      updateFloorPlan(index, {
                        imageUrl: file?.url || '',
                        imagePublicId: file?.publicId || '',
                      })
                    }
                    helpText="Upload floor plan image (JPG, PNG)"
                    disabled={disabled}
                  />

                  {/* Floor Plan PDF */}
                  <FileUploader
                    label="Floor Plan PDF"
                    accept="pdf"
                    folder={`projects/${projectSlug}/floor-plans`}
                    value={
                      floor.pdfUrl && floor.pdfPublicId
                        ? { url: floor.pdfUrl, publicId: floor.pdfPublicId }
                        : null
                    }
                    onChange={(file) =>
                      updateFloorPlan(index, {
                        pdfUrl: file?.url || '',
                        pdfPublicId: file?.publicId || '',
                      })
                    }
                    helpText="Upload detailed PDF (optional)"
                    disabled={disabled}
                  />
                </div>
              </div>
            )}
          </div>
        ))}

        {/* Add Floor Button (when list is not empty) */}
        {floorPlans.length > 0 && !disabled && (
          <button
            type="button"
            onClick={addFloorPlan}
            className="w-full py-3 border-2 border-dashed border-gray-300 rounded-xl text-gray-500 hover:border-emerald-500 hover:text-emerald-500 transition-colors flex items-center justify-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Add Another Floor
          </button>
        )}
      </div>

      {/* Footer Stats */}
      <div className="px-6 py-3 bg-gray-50 border-t border-gray-200">
        <div className="flex items-center justify-between text-sm">
          <span className="text-gray-500">
            Total floors:{' '}
            <span className="font-medium text-gray-700">{floorPlans.length}</span>
          </span>
          <span className="text-gray-400">
            {floorPlans.filter((f) => f.imageUrl || f.pdfUrl).length} with media
          </span>
        </div>
      </div>
    </div>
  );
}

// components/admin/DocumentsSection.tsx

import React from 'react';
import { FileText, Info } from 'lucide-react';
import FileUploader from './FileUploader';

// Type for a single document
interface DocumentFile {
  url: string;
  publicId: string;
}

// Type for all project documents
export interface ProjectDocuments {
  brochureUrl?: string;
  brochurePublicId?: string;
  priceListUrl?: string;
  priceListPublicId?: string;
  paymentPlanUrl?: string;
  paymentPlanPublicId?: string;
  masterPlanUrl?: string;
  masterPlanPublicId?: string;
  nocDocumentUrl?: string;
  nocDocumentPublicId?: string;
}

interface DocumentsSectionProps {
  documents: ProjectDocuments;
  onChange: (documents: ProjectDocuments) => void;
  projectSlug?: string; // For folder organization
  disabled?: boolean;
}

export default function DocumentsSection({
  documents,
  onChange,
  projectSlug = 'general',
  disabled = false,
}: DocumentsSectionProps) {
  
  // Helper to update a specific document
  const updateDocument = (
    urlKey: keyof ProjectDocuments,
    publicIdKey: keyof ProjectDocuments,
    file: { url: string; publicId: string } | null
  ) => {
    onChange({
      ...documents,
      [urlKey]: file?.url || '',
      [publicIdKey]: file?.publicId || '',
    });
  };

  // Helper to get document value for FileUploader
  const getDocumentValue = (
    urlKey: keyof ProjectDocuments,
    publicIdKey: keyof ProjectDocuments
  ): { url: string; publicId: string } | null => {
    const url = documents[urlKey];
    const publicId = documents[publicIdKey];
    
    if (url && publicId) {
      return { url: url as string, publicId: publicId as string };
    }
    return null;
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 bg-gradient-to-r from-[#029bba]/10 to-transparent border-b border-gray-200">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-[#029bba] flex items-center justify-center">
            <FileText className="w-5 h-5 text-white" />
          </div>
          <div>
            <h3 className="text-lg font-semibold text-gray-900">
              Project Documents
            </h3>
            <p className="text-sm text-gray-500">
              Upload brochures, price lists, and other important documents
            </p>
          </div>
        </div>
      </div>

      {/* Info Banner */}
      <div className="mx-6 mt-4 p-3 bg-blue-50 border border-blue-100 rounded-xl flex items-start gap-3">
        <Info className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
        <div className="text-sm text-blue-700">
          <p className="font-medium">Tip: Upload PDF files for best results</p>
          <p className="text-blue-600 mt-0.5">
            These documents will be available for download on the project page.
            Maximum file size: 10MB per file.
          </p>
        </div>
      </div>

      {/* Documents Grid */}
      <div className="p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Brochure */}
          <FileUploader
            label="Project Brochure"
            accept="pdf"
            folder={`projects/${projectSlug}/documents`}
            value={getDocumentValue('brochureUrl', 'brochurePublicId')}
            onChange={(file) =>
              updateDocument('brochureUrl', 'brochurePublicId', file)
            }
            helpText="Main project brochure with all details"
            disabled={disabled}
          />

          {/* Price List */}
          <FileUploader
            label="Price List"
            accept="pdf"
            folder={`projects/${projectSlug}/documents`}
            value={getDocumentValue('priceListUrl', 'priceListPublicId')}
            onChange={(file) =>
              updateDocument('priceListUrl', 'priceListPublicId', file)
            }
            helpText="Current pricing for all unit types"
            disabled={disabled}
          />

          {/* Payment Plan */}
          <FileUploader
            label="Payment Plan"
            accept="pdf"
            folder={`projects/${projectSlug}/documents`}
            value={getDocumentValue('paymentPlanUrl', 'paymentPlanPublicId')}
            onChange={(file) =>
              updateDocument('paymentPlanUrl', 'paymentPlanPublicId', file)
            }
            helpText="Installment and payment schedule details"
            disabled={disabled}
          />

          {/* Master Plan */}
          <FileUploader
            label="Master Plan / Layout"
            accept="pdf"
            folder={`projects/${projectSlug}/documents`}
            value={getDocumentValue('masterPlanUrl', 'masterPlanPublicId')}
            onChange={(file) =>
              updateDocument('masterPlanUrl', 'masterPlanPublicId', file)
            }
            helpText="Overall project layout and master plan"
            disabled={disabled}
          />

          {/* NOC Document */}
          <FileUploader
            label="NOC / Approval Document"
            accept="pdf"
            folder={`projects/${projectSlug}/documents`}
            value={getDocumentValue('nocDocumentUrl', 'nocDocumentPublicId')}
            onChange={(file) =>
              updateDocument('nocDocumentUrl', 'nocDocumentPublicId', file)
            }
            helpText="Official NOC or approval certificate (optional)"
            disabled={disabled}
          />
        </div>
      </div>

      {/* Footer Stats */}
      <div className="px-6 py-3 bg-gray-50 border-t border-gray-200">
        <div className="flex items-center justify-between text-sm">
          <span className="text-gray-500">
            Documents uploaded:{' '}
            <span className="font-medium text-gray-700">
              {[
                documents.brochureUrl,
                documents.priceListUrl,
                documents.paymentPlanUrl,
                documents.masterPlanUrl,
                documents.nocDocumentUrl,
              ].filter(Boolean).length}{' '}
              / 5
            </span>
          </span>
          <span className="text-gray-400">PDF format recommended</span>
        </div>
      </div>
    </div>
  );
}

// components/admin/FileUploader.tsx

import React, { useState, useRef } from 'react';
import {
  Upload,
  X,
  FileText,
  Image as ImageIcon,
  Loader2,
  CheckCircle,
  AlertCircle,
  Eye,
  Download,
} from 'lucide-react';

interface FileUploaderProps {
  label: string;
  accept: 'image' | 'pdf' | 'both';
  folder: string;
  value?: {
    url: string;
    publicId: string;
  } | null;
  onChange: (file: { url: string; publicId: string } | null) => void;
  helpText?: string;
  required?: boolean;
  disabled?: boolean;
}

export default function FileUploader({
  label,
  accept,
  folder,
  value,
  onChange,
  helpText,
  required = false,
  disabled = false,
}: FileUploaderProps) {
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [imageError, setImageError] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Determine accept attribute
  const acceptAttr =
    accept === 'image'
      ? 'image/jpeg,image/png,image/webp,image/gif'
      : accept === 'pdf'
      ? 'application/pdf'
      : 'image/jpeg,image/png,image/webp,image/gif,application/pdf';

  // Get file type for API
  const fileType = accept === 'both' ? 'auto' : accept;

  // Handle file selection
  const handleFileSelect = async (file: File) => {
    if (!file) return;

    // Validate file size (10MB max)
    if (file.size > 10 * 1024 * 1024) {
      setError('File size must be less than 10MB');
      return;
    }

    // Validate file type
    const isImage = file.type.startsWith('image/');
    const isPdf = file.type === 'application/pdf';

    if (accept === 'image' && !isImage) {
      setError('Please select an image file (JPG, PNG, WebP)');
      return;
    }

    if (accept === 'pdf' && !isPdf) {
      setError('Please select a PDF file');
      return;
    }

    if (accept === 'both' && !isImage && !isPdf) {
      setError('Please select an image or PDF file');
      return;
    }

    setError(null);
    setImageError(false);
    setUploading(true);

    try {
      // Delete old file if exists
      if (value?.publicId) {
        await fetch('/api/upload/delete', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            publicId: value.publicId,
            resourceType: isPdf ? 'raw' : 'image',
          }),
        });
      }

      // Upload new file
      const formData = new FormData();
      formData.append('file', file);
      formData.append('folder', folder);
      formData.append('fileType', fileType);

      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (data.success) {
        onChange({
          url: data.data.url,
          publicId: data.data.publicId,
        });
      } else {
        setError(data.message || 'Upload failed');
      }
    } catch (err) {
      setError('Upload failed. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  // Handle delete
  const handleDelete = async () => {
    if (!value?.publicId) return;

    try {
      const isPdf = value.url.toLowerCase().endsWith('.pdf');
      
      await fetch('/api/upload/delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          publicId: value.publicId,
          resourceType: isPdf ? 'raw' : 'image',
        }),
      });

      onChange(null);
      setImageError(false);
    } catch (err) {
      console.error('Delete failed:', err);
    }
  };

  // Handle drag and drop
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    
    const file = e.dataTransfer.files[0];
    if (file) {
      handleFileSelect(file);
    }
  };

  // Check if value is PDF or image
  // NOTE: DocumentsSection jahan se ye component use ho raha hai wahan accept="pdf" set hai,
  // is liye hum primarily `accept` prop pe rely karte hain, aur fallback ke طور pe URL ending se check karte hain.
  const isPdf =
    accept === 'pdf' ||
    (!!value?.url && value.url.toLowerCase().endsWith('.pdf'));

  return (
    <div className="space-y-2">
      {/* Label */}
      <label className="block text-sm font-medium text-gray-700">
        {label}
        {required && <span className="text-red-500 ml-1">*</span>}
      </label>

      {/* Upload Area or Preview */}
      {!value ? (
        <div
          onClick={() => !disabled && inputRef.current?.click()}
          onDragOver={(e) => {
            e.preventDefault();
            setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={handleDrop}
          className={`
            relative border-2 border-dashed rounded-xl p-6 text-center cursor-pointer
            transition-all duration-200
            ${dragOver ? 'border-[#029bba] bg-[#029bba]/5' : 'border-gray-300 hover:border-[#029bba]'}
            ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
            ${error ? 'border-red-300 bg-red-50' : ''}
          `}
        >
          <input
            ref={inputRef}
            type="file"
            accept={acceptAttr}
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) handleFileSelect(file);
            }}
            className="hidden"
            disabled={disabled}
          />

          {uploading ? (
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="w-8 h-8 text-[#029bba] animate-spin" />
              <span className="text-sm text-gray-600">Uploading...</span>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-2">
              <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center">
                {accept === 'pdf' ? (
                  <FileText className="w-6 h-6 text-gray-400" />
                ) : accept === 'image' ? (
                  <ImageIcon className="w-6 h-6 text-gray-400" />
                ) : (
                  <Upload className="w-6 h-6 text-gray-400" />
                )}
              </div>
              <div>
                <span className="text-sm font-medium text-[#029bba]">
                  Click to upload
                </span>
                <span className="text-sm text-gray-500"> or drag and drop</span>
              </div>
              <span className="text-xs text-gray-400">
                {accept === 'pdf'
                  ? 'PDF (max 10MB)'
                  : accept === 'image'
                  ? 'JPG, PNG, WebP (max 10MB)'
                  : 'Image or PDF (max 10MB)'}
              </span>
            </div>
          )}
        </div>
      ) : (
        <div className="relative border border-gray-200 rounded-xl p-4 bg-gray-50">
          <div className="flex items-center gap-4">
            {/* Preview */}
            {isPdf ? (
              <div className="w-16 h-16 rounded-lg bg-red-100 flex items-center justify-center flex-shrink-0">
                <FileText className="w-8 h-8 text-red-500" />
              </div>
            ) : (
              <div className="w-16 h-16 rounded-lg overflow-hidden flex-shrink-0 bg-gray-200 flex items-center justify-center">
                {!imageError ? (
                  <img
                    src={value.url}
                    alt="Preview"
                    className="w-full h-full object-cover"
                    onError={() => setImageError(true)}
                  />
                ) : (
                  <ImageIcon className="w-8 h-8 text-gray-400" />
                )}
              </div>
            )}

            {/* Info */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <CheckCircle className="w-4 h-4 text-green-500 flex-shrink-0" />
                <span className="text-sm font-medium text-gray-700 truncate">
                  {isPdf ? 'PDF Document' : 'Image'} uploaded
                </span>
              </div>
              <p className="text-xs text-gray-500 truncate mt-1">
                {value.url.split('/').pop()}
              </p>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 flex-shrink-0">
              {/* View/Download */}
              <a
                href={value.url}
                target="_blank"
                rel="noopener noreferrer"
                className="p-2 rounded-lg bg-white border border-gray-200 hover:bg-gray-50 transition-colors"
                title={isPdf ? 'Download' : 'View'}
              >
                {isPdf ? (
                  <Download className="w-4 h-4 text-gray-600" />
                ) : (
                  <Eye className="w-4 h-4 text-gray-600" />
                )}
              </a>

              {/* Delete */}
              {!disabled && (
                <button
                  type="button"
                  onClick={handleDelete}
                  className="p-2 rounded-lg bg-white border border-red-200 hover:bg-red-50 transition-colors"
                  title="Delete"
                >
                  <X className="w-4 h-4 text-red-500" />
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Error Message */}
      {error && (
        <div className="flex items-center gap-2 text-red-600">
          <AlertCircle className="w-4 h-4" />
          <span className="text-sm">{error}</span>
        </div>
      )}

      {/* Help Text */}
      {helpText && !error && (
        <p className="text-xs text-gray-500">{helpText}</p>
      )}
    </div>
  );
}

// components/admin/GalleryUploader.tsx

import React, { useState, useRef, useCallback } from 'react';
import {
  Upload,
  X,
  Image as ImageIcon,
  Loader2,
  GripVertical,
  ChevronDown,
  CheckCircle,
  AlertCircle,
  FileText
} from 'lucide-react';

// ============================================
// TYPES
// ============================================

export type ImageCategory = 
  | 'exterior' 
  | 'interior' 
  | 'bedroom' 
  | 'bathroom' 
  | 'kitchen' 
  | 'living' 
  | 'view' 
  | 'amenity' 
  | 'floor_plan' 
  | 'construction' 
  | 'render' 
  | 'other';

export interface GalleryImage {
  url: string;
  publicId: string; // Changed from public_id to publicId to match your prop type
  caption?: string;
  category?: ImageCategory;
  order: number;
  mimeType?: string; // Track file type
}

interface GalleryUploaderProps {
  label?: string;
  value: GalleryImage[];
  onChange: (images: GalleryImage[]) => void;
  folder: string;
  maxImages?: number;
  required?: boolean;
  disabled?: boolean;
  helpText?: string;
  showCategories?: boolean;
  allowedCategories?: ImageCategory[];
}

// ============================================
// CATEGORY OPTIONS
// ============================================

const CATEGORY_OPTIONS: { value: ImageCategory; label: string; icon: string }[] = [
  { value: 'exterior', label: 'Exterior', icon: '🏠' },
  { value: 'interior', label: 'Interior', icon: '🛋️' },
  { value: 'bedroom', label: 'Bedroom', icon: '🛏️' },
  { value: 'bathroom', label: 'Bathroom', icon: '🚿' },
  { value: 'kitchen', label: 'Kitchen', icon: '🍳' },
  { value: 'living', label: 'Living Room', icon: '🪑' },
  { value: 'view', label: 'View', icon: '🌆' },
  { value: 'amenity', label: 'Amenity', icon: '🏊' },
  { value: 'floor_plan', label: 'Floor Plan', icon: '📐' },
  { value: 'construction', label: 'Construction', icon: '🏗️' },
  { value: 'render', label: '3D Render', icon: '🖼️' },
  { value: 'other', label: 'Other', icon: '📷' },
];

// ============================================
// MAIN COMPONENT
// ============================================

export default function GalleryUploader({
  label = 'Gallery Images',
  value = [],
  onChange,
  folder,
  maxImages = 20,
  required = false,
  disabled = false,
  helpText,
  showCategories = true,
  allowedCategories,
}: GalleryUploaderProps) {
  const [uploading, setUploading] = useState(false);
  const [uploadingCount, setUploadingCount] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Filter categories if specific ones are allowed
  const categoryOptions = allowedCategories
    ? CATEGORY_OPTIONS.filter((cat) => allowedCategories.includes(cat.value))
    : CATEGORY_OPTIONS;

  // ============================================
  // UPLOAD HANDLER (SECURE)
  // ============================================

  const uploadImage = async (file: File): Promise<GalleryImage | null> => {
    // 1. Client-Side Validation
    if (file.size > 10 * 1024 * 1024) {
      setError(`File ${file.name} is too large (Max 10MB)`);
      return null;
    }

    if (!file.type.startsWith('image/')) {
      setError(`File ${file.name} is not an image`);
      return null;
    }

    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('folder', folder);
      
      // ✅ Explicitly set image type for backend validation
      formData.append('fileType', 'image'); 

      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
        // No Content-Type header needed (browser sets multipart/form-data boundary)
      });

      if (!response.ok) {
        if (response.status === 429) {
          throw new Error('Rate limit exceeded. Please wait.');
        }
        throw new Error('Upload failed');
      }

      const data = await response.json();

      if (data.success) {
        return {
          url: data.data.url,
          publicId: data.data.publicId, // Normalized to camelCase
          category: 'other',
          order: value.length,
          mimeType: file.type,
        };
      }
      
      throw new Error(data.message || 'Upload failed');
    } catch (err: any) {
      console.error('Upload error:', err);
      setError(err.message || 'Failed to upload image');
      return null;
    }
  };

  const handleFileSelect = async (files: FileList | null) => {
    if (!files || files.length === 0) return;

    const remainingSlots = maxImages - value.length;
    if (remainingSlots <= 0) {
      setError(`Maximum ${maxImages} images allowed`);
      return;
    }

    const filesToUpload = Array.from(files).slice(0, remainingSlots);
    setUploading(true);
    setUploadingCount(filesToUpload.length);
    setError(null);

    const uploadedImages: GalleryImage[] = [];

    // Parallel uploads (max 3 at a time to prevent browser stall)
    // For simplicity here, we do sequential, but batching is better.
    for (const file of filesToUpload) {
      const result = await uploadImage(file);
      if (result) {
        // Adjust order locally
        result.order = value.length + uploadedImages.length;
        uploadedImages.push(result);
      }
      setUploadingCount((prev) => Math.max(0, prev - 1));
    }

    if (uploadedImages.length > 0) {
      onChange([...value, ...uploadedImages]);
    }

    setUploading(false);
    setUploadingCount(0);
  };

  // ============================================
  // DELETE HANDLER (SECURE)
  // ============================================

  const handleDelete = async (index: number) => {
    const imageToDelete = value[index];
    
    // Optimistic UI update
    const newImages = value
      .filter((_, i) => i !== index)
      .map((img, i) => ({ ...img, order: i }));
    
    onChange(newImages);

    try {
      // Secure delete call
      const res = await fetch('/api/upload/delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          publicId: imageToDelete.publicId,
          resourceType: 'image', // Explicit resource type
        }),
      });

      if (!res.ok) {
        console.error('Failed to delete from server, but removed from UI');
        // We don't revert UI here to avoid jankiness, but you could show a toast
      }
    } catch (err) {
      console.error('Delete error:', err);
    }
  };

  // ============================================
  // UPDATE HANDLERS
  // ============================================

  const handleCategoryChange = (index: number, category: ImageCategory) => {
    const newImages = [...value];
    newImages[index] = { ...newImages[index], category };
    onChange(newImages);
  };

  const handleCaptionChange = (index: number, caption: string) => {
    const newImages = [...value];
    newImages[index] = { ...newImages[index], caption };
    onChange(newImages);
  };

  // ============================================
  // DRAG & DROP REORDER
  // ============================================

  const handleDragStart = (index: number) => {
    setDraggedIndex(index);
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;

    const newImages = [...value];
    const draggedImage = newImages[draggedIndex];
    newImages.splice(draggedIndex, 1);
    newImages.splice(index, 0, draggedImage);

    // Update order
    newImages.forEach((img, i) => {
      img.order = i;
    });

    onChange(newImages);
    setDraggedIndex(index);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
  };

  // ============================================
  // DROP ZONE
  // ============================================

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    handleFileSelect(e.dataTransfer.files);
  };

  // ============================================
  // RENDER
  // ============================================

  return (
    <div className="space-y-4">
      {/* Label */}
      <div className="flex justify-between items-center">
        <label className="block text-sm font-bold text-gray-700">
          {label}
          {required && <span className="text-red-500 ml-1">*</span>}
        </label>
        <span className="text-xs font-medium text-gray-500">
          {value.length} / {maxImages} images
        </span>
      </div>

      {/* Upload Area */}
      {value.length < maxImages && (
        <div
          onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onDrop={handleDrop}
          onClick={() => !disabled && inputRef.current?.click()}
          className={`
            relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer
            transition-all duration-200 ease-in-out
            ${dragOver ? 'border-[#029bba] bg-[#029bba]/5 scale-[1.01]' : 'border-gray-300 hover:border-[#029bba] hover:bg-gray-50'}
            ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
            ${error ? 'border-red-300 bg-red-50' : ''}
          `}
        >
          <input
            ref={inputRef}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            multiple
            onChange={(e) => handleFileSelect(e.target.files)}
            className="hidden"
            disabled={disabled || uploading}
          />

          {uploading ? (
            <div className="flex flex-col items-center gap-3 py-2">
              <Loader2 className="w-10 h-10 text-[#029bba] animate-spin" />
              <div className="text-sm font-medium text-gray-600">
                Uploading {uploadingCount} image{uploadingCount !== 1 ? 's' : ''}...
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-3 py-2">
              <div className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${dragOver ? 'bg-[#029bba]/10 text-[#029bba]' : 'bg-gray-100 text-gray-400'}`}>
                <Upload className="w-7 h-7" />
              </div>
              <div>
                <span className="text-sm font-bold text-[#029bba]">Click to upload</span>
                <span className="text-sm text-gray-500"> or drag and drop</span>
              </div>
              <p className="text-xs text-gray-400">
                JPG, PNG, WebP (Max 10MB)
              </p>
            </div>
          )}
        </div>
      )}

      {/* Error Banner */}
      {error && (
        <div className="flex items-center gap-2 text-red-600 bg-red-50 p-3 rounded-lg border border-red-100 animate-in fade-in slide-in-from-top-1">
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          <span className="text-sm font-medium">{error}</span>
          <button onClick={() => setError(null)} className="ml-auto text-red-400 hover:text-red-700">
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Help Text */}
      {helpText && !error && (
        <p className="text-xs text-gray-500 flex items-center gap-1.5">
          <CheckCircle className="w-3 h-3 text-green-500" />
          {helpText}
        </p>
      )}

      {/* Image Grid */}
      {value.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 animate-in fade-in duration-500">
          {value.map((image, index) => (
            <div
              key={image.publicId}
              draggable
              onDragStart={() => handleDragStart(index)}
              onDragOver={(e) => handleDragOver(e, index)}
              onDragEnd={handleDragEnd}
              className={`
                relative group bg-white rounded-xl border overflow-hidden shadow-sm
                transition-all duration-200
                ${draggedIndex === index ? 'opacity-40 scale-95 ring-2 ring-[#029bba]' : 'opacity-100 hover:shadow-md'}
                ${index === 0 ? 'border-[#029bba] ring-1 ring-[#029bba]/20' : 'border-gray-200'}
              `}
            >
              {/* Image Preview */}
              <div className="aspect-square relative bg-gray-50">
                <img
                  src={image.url}
                  alt={image.caption || `Image ${index + 1}`}
                  className="w-full h-full object-cover"
                  loading="lazy"
                />

                {/* Drag Handle Overlay */}
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 transition-colors cursor-grab active:cursor-grabbing" />

                <div className="absolute top-2 left-2 p-1.5 bg-white/90 backdrop-blur rounded-lg shadow-sm opacity-0 group-hover:opacity-100 transition-opacity cursor-grab">
                  <GripVertical className="w-4 h-4 text-gray-600" />
                </div>

                <button
                  type="button"
                  onClick={() => handleDelete(index)}
                  className="absolute top-2 right-2 p-1.5 bg-red-500 text-white rounded-lg shadow-sm opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-600 hover:scale-105 transform duration-150"
                  title="Remove image"
                >
                  <X className="w-4 h-4" />
                </button>

                {/* Badges */}
                {index === 0 && (
                  <div className="absolute bottom-2 left-2 px-2 py-1 bg-[#029bba] text-white text-[10px] font-bold uppercase tracking-wider rounded shadow-sm">
                    Main Photo
                  </div>
                )}

                <div className="absolute bottom-2 right-2 w-6 h-6 bg-black/60 backdrop-blur text-white text-xs font-bold rounded-full flex items-center justify-center">
                  {index + 1}
                </div>
              </div>

              {/* Controls */}
              {showCategories && (
                <div className="p-3 space-y-2 bg-white border-t border-gray-100">
                  <select
                    value={image.category || 'other'}
                    onChange={(e) => handleCategoryChange(index, e.target.value as ImageCategory)}
                    className="w-full text-xs px-2 py-1.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#029bba]/20 focus:border-[#029bba] bg-gray-50 hover:bg-white transition-colors cursor-pointer"
                  >
                    {categoryOptions.map((cat) => (
                      <option key={cat.value} value={cat.value}>
                        {cat.icon} {cat.label}
                      </option>
                    ))}
                  </select>

                  <input
                    type="text"
                    value={image.caption || ''}
                    onChange={(e) => handleCaptionChange(index, e.target.value)}
                    placeholder="Caption (optional)"
                    className="w-full text-xs px-2 py-1.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#029bba]/20 focus:border-[#029bba] placeholder:text-gray-400"
                    maxLength={50}
                  />
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Helper Tip */}
      {value.length > 0 && (
        <div className="bg-blue-50 border border-blue-100 rounded-lg p-3 flex items-start gap-2">
          <div className="mt-0.5 min-w-[16px]">💡</div>
          <p className="text-xs text-blue-700 leading-snug">
            <strong>Pro Tip:</strong> Drag and drop images to reorder them. The first image will be your listing's main cover photo.
          </p>
        </div>
      )}
    </div>
  );
}

import React, { useRef, useState } from 'react';
import { X, Upload, Loader2 } from 'lucide-react';

interface TrustedPartnerFormProps {
  partner?: any | null;
  onClose: () => void;
}

export default function TrustedPartnerForm({ partner, onClose }: TrustedPartnerFormProps) {
  const [companyName, setCompanyName] = useState(partner?.companyName || '');
  const [logo, setLogo] = useState({ url: partner?.logo?.url || '', publicId: partner?.logo?.publicId || '' });
  const [website, setWebsite] = useState(partner?.website || '');
  const [displayOrder, setDisplayOrder] = useState(partner?.displayOrder || 0);
  const [isActive, setIsActive] = useState(partner?.isActive ?? true);
  const [loading, setLoading] = useState(false);
  const [uploadingLogo, setUploadingLogo] = useState(false);
  const [error, setError] = useState('');
  const logoInputRef = useRef<HTMLInputElement>(null);

  const handleLogoUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) {
      setError('Logo must be 2MB or smaller.');
      return;
    }

    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
      setError('Logo must be JPG, PNG, or WebP. SVG is not accepted for security reasons.');
      return;
    }

    setError('');
    setUploadingLogo(true);
    try {
      const body = new FormData();
      body.append('file', file);
      const response = await fetch('/api/upload?folder=trusted-partners', {
        method: 'POST',
        credentials: 'include',
        body,
      });
      const data = await response.json();
      if (!response.ok || !data?.success || !data?.data?.url || !data?.data?.publicId) {
        throw new Error(data?.error || 'Logo upload failed');
      }
      setLogo({ url: data.data.url, publicId: data.data.publicId });
    } catch (uploadError) {
      setError(uploadError instanceof Error ? uploadError.message : 'Logo upload failed');
    } finally {
      setUploadingLogo(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (!companyName.trim()) {
        setError('Company name is required');
        setLoading(false);
        return;
      }

      if (!logo.url || !logo.publicId) {
        setError('Logo is required');
        setLoading(false);
        return;
      }

      const url = partner ? `/api/trusted-partners/${partner._id}` : '/api/trusted-partners';
      const method = partner ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          companyName: companyName.trim(),
          logo,
          website: website.trim(),
          displayOrder: Number(displayOrder),
          isActive,
        }),
      });

      const data = await res.json();

      if (data.success) {
        onClose();
      } else {
        setError(data.message || 'Failed to save partner');
      }
    } catch (err) {
      setError('Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-gray-200">
          <h2 className="text-xl font-bold text-gray-900">
            {partner ? 'Edit Partner' : 'Add New Partner'}
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          {/* Error Message */}
          {error && (
            <div className="p-3 bg-red-50 border border-red-200 text-red-700 text-sm rounded-lg">
              {error}
            </div>
          )}

          {/* Company Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Company Name <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={companyName}
              onChange={(e) => setCompanyName(e.target.value)}
              placeholder="e.g., Bahria Town, DHA, etc."
              className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none transition-colors"
              required
            />
          </div>

          {/* Logo Upload */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Company Logo <span className="text-red-500">*</span>
            </label>
            <input
              ref={logoInputRef}
              type="file"
              accept="image/jpeg,image/png,image/webp"
              className="hidden"
              onChange={handleLogoUpload}
            />
            <button
              type="button"
              onClick={() => logoInputRef.current?.click()}
              disabled={uploadingLogo}
              className="w-full px-4 py-3 border-2 border-dashed border-gray-300 rounded-lg hover:border-[#029bba] hover:bg-[#029bba]/5 transition-colors flex items-center justify-center gap-2 disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {uploadingLogo ? (
                <Loader2 className="w-5 h-5 text-[#029bba] animate-spin" />
              ) : (
                <Upload className="w-5 h-5 text-gray-400" />
              )}
              <span className="text-sm text-gray-600">
                {uploadingLogo ? 'Uploading securely...' : logo.url ? 'Change Logo' : 'Upload Logo (JPG, PNG, WebP)'}
              </span>
            </button>

            {/* Logo Preview */}
            {logo.url && (
              <div className="mt-3 p-3 bg-gray-50 rounded-lg border border-gray-200 flex items-center gap-3">
                <img
                  src={logo.url}
                  alt="Logo preview"
                  className="w-20 h-10 object-contain bg-white rounded"
                />
                <button
                  type="button"
                  onClick={() => setLogo({ url: '', publicId: '' })}
                  className="text-xs text-red-600 hover:text-red-800"
                >
                  Remove
                </button>
              </div>
            )}
          </div>

          {/* Website */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Website URL
            </label>
            <input
              type="url"
              value={website}
              onChange={(e) => setWebsite(e.target.value)}
              placeholder="https://example.com"
              className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none transition-colors"
            />
          </div>

          {/* Display Order */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Display Order
            </label>
            <input
              type="number"
              value={displayOrder}
              onChange={(e) => setDisplayOrder(Number(e.target.value))}
              placeholder="0"
              min="0"
              className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none transition-colors"
            />
            <p className="text-xs text-gray-500 mt-1">Lower numbers appear first</p>
          </div>

          {/* Active Status */}
          <div className="flex items-center gap-3">
            <input
              type="checkbox"
              id="isActive"
              checked={isActive}
              onChange={(e) => setIsActive(e.target.checked)}
              className="w-4 h-4 text-[#029bba] border-gray-300 rounded focus:ring-[#029bba]"
            />
            <label htmlFor="isActive" className="text-sm text-gray-700">
              Show on homepage (Active)
            </label>
          </div>

          {/* Submit Button */}
          <div className="flex items-center gap-3 pt-4">
            <button
              type="submit"
              disabled={loading || uploadingLogo}
              className="flex-1 px-4 py-3 bg-[#029bba] hover:bg-[#027a94] text-white font-semibold rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Saving...
                </>
              ) : (
                'Save Partner'
              )}
            </button>
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-3 border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-gray-50 transition-colors"
            >
              Cancel
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// components/admin/UnitPlansSection.tsx

import React, { useState } from 'react';
import {
  Home,
  Plus,
  Trash2,
  ChevronDown,
  ChevronUp,
  GripVertical,
  Bed,
  Bath,
  Maximize,
  DollarSign,
  Video,
  Image as ImageIcon,
  X,
  Building2,
  Store,
  Briefcase,
  Crown,
  Coffee,
  Box,
} from 'lucide-react';
import FileUploader from './FileUploader';

// Type for interior image
interface InteriorImage {
  url: string;
  publicId: string;
  caption?: string;
}

// Type for a single unit plan
export interface UnitPlan {
  type: string;
  name: string;
  category?: 'residential' | 'commercial';
  totalUnits?: number;
  soldUnits?: number;
  availableUnits?: number;
  floorsAssigned?: string[];
  priceRange: {
    min: number;
    max: number;
  };
  areaRange?: {
    min: number;
    max: number;
    unit: string;
  };
  bedrooms?: number;
  bathrooms?: number;
  features?: string[];
  description?: string;
  layoutImageUrl?: string;
  layoutImagePublicId?: string;
  interiorImages?: InteriorImage[];
  floorPlanPdfUrl?: string;
  floorPlanPdfPublicId?: string;
  walkthroughVideoUrl?: string;
}

interface UnitPlansSectionProps {
  unitPlans: UnitPlan[];
  onChange: (unitPlans: UnitPlan[]) => void;
  projectSlug?: string;
  disabled?: boolean;
}

// Unit type options
const UNIT_TYPES = [
  { value: 'studio_apartment', label: 'Studio Apartment', icon: Home, category: 'residential' },
  { value: 'apartment_1bed', label: '1 Bed Apartment', icon: Home, category: 'residential' },
  { value: 'apartment_2bed', label: '2 Bed Apartment', icon: Home, category: 'residential' },
  { value: 'apartment_3bed', label: '3 Bed Apartment', icon: Home, category: 'residential' },
  { value: 'apartment_4bed', label: '4 Bed Apartment', icon: Home, category: 'residential' },
  { value: 'penthouse', label: 'Penthouse', icon: Crown, category: 'residential' },
  { value: 'duplex', label: 'Duplex', icon: Building2, category: 'residential' },
  { value: 'shop', label: 'Shop', icon: Store, category: 'commercial' },
  { value: 'office', label: 'Office', icon: Briefcase, category: 'commercial' },
  { value: 'food_court', label: 'Food Court', icon: Coffee, category: 'commercial' },
  { value: 'kiosk', label: 'Kiosk', icon: Box, category: 'commercial' },
  { value: 'showroom', label: 'Showroom', icon: Store, category: 'commercial' },
  { value: 'other', label: 'Other', icon: Box, category: 'commercial' },
];

// Common features for quick selection
const COMMON_FEATURES = [
  'Balcony',
  'Terrace',
  'Corner Unit',
  'Park Facing',
  'Road Facing',
  'Sea View',
  'City View',
  'Attached Bath',
  'Walk-in Closet',
  'Servant Quarter',
  'Laundry Area',
  'Storage Room',
  'Private Elevator',
  'Double Height Ceiling',
  'Smart Home',
  'Furnished',
  'Semi-Furnished',
];

// Helper function to format price
const formatPrice = (price: number): string => {
  if (price >= 10000000) {
    return `${(price / 10000000).toFixed(2)} Crore`;
  } else if (price >= 100000) {
    return `${(price / 100000).toFixed(2)} Lac`;
  }
  return price.toLocaleString();
};

// Helper function to convert area
const convertArea = (sqft: number, toUnit: string): string => {
  switch (toUnit) {
    case 'marla':
      return (sqft / 225).toFixed(2);
    case 'sqm':
      return (sqft * 0.0929).toFixed(2);
    case 'kanal':
      return (sqft / 4500).toFixed(3);
    default:
      return sqft.toString();
  }
};

export default function UnitPlansSection({
  unitPlans,
  onChange,
  projectSlug = 'general',
  disabled = false,
}: UnitPlansSectionProps) {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);
  const [newFeature, setNewFeature] = useState<{ [key: number]: string }>({});

  // Add new unit plan
  const addUnitPlan = () => {
    const newUnit: UnitPlan = {
      type: '',
      name: '',
      category: 'residential',
      priceRange: { min: 0, max: 0 },
      areaRange: { min: 0, max: 0, unit: 'Sq. Ft.' },
      features: [],
      interiorImages: [],
    };
    onChange([...unitPlans, newUnit]);
    setExpandedIndex(unitPlans.length);
  };

  // Remove unit plan
  const removeUnitPlan = (index: number) => {
    const updated = unitPlans.filter((_, i) => i !== index);
    onChange(updated);
    if (expandedIndex === index) {
      setExpandedIndex(null);
    }
  };

  // Update a specific unit plan
  const updateUnitPlan = (index: number, updates: Partial<UnitPlan>) => {
    const updated = unitPlans.map((unit, i) =>
      i === index ? { ...unit, ...updates } : unit
    );
    onChange(updated);
  };

  // Add feature to unit
  const addFeature = (index: number, feature: string) => {
    if (!feature.trim()) return;
    const unit = unitPlans[index];
    const features = unit.features || [];
    if (!features.includes(feature.trim())) {
      updateUnitPlan(index, { features: [...features, feature.trim()] });
    }
    setNewFeature({ ...newFeature, [index]: '' });
  };

  // Remove feature from unit
  const removeFeature = (index: number, feature: string) => {
    const unit = unitPlans[index];
    const features = (unit.features || []).filter((f) => f !== feature);
    updateUnitPlan(index, { features });
  };

  // Add interior image
  const addInteriorImage = (
    index: number,
    image: { url: string; publicId: string }
  ) => {
    const unit = unitPlans[index];
    const images = unit.interiorImages || [];
    updateUnitPlan(index, {
      interiorImages: [...images, { ...image, caption: '' }],
    });
  };

  // Remove interior image
  const removeInteriorImage = (unitIndex: number, imageIndex: number) => {
    const unit = unitPlans[unitIndex];
    const images = (unit.interiorImages || []).filter((_, i) => i !== imageIndex);
    updateUnitPlan(unitIndex, { interiorImages: images });
  };

  // Get icon for unit type
  const getUnitIcon = (type: string) => {
    const unitType = UNIT_TYPES.find((t) => t.value === type);
    const IconComponent = unitType?.icon || Box;
    return <IconComponent className="w-4 h-4" />;
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 bg-gradient-to-r from-purple-500/10 to-transparent border-b border-gray-200">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-purple-500 flex items-center justify-center">
              <Home className="w-5 h-5 text-white" />
            </div>
            <div>
              <h3 className="text-lg font-semibold text-gray-900">
                Unit Types & Plans
              </h3>
              <p className="text-sm text-gray-500">
                Add different unit types with pricing, area, and floor plans
              </p>
            </div>
          </div>

          {!disabled && (
            <button
              type="button"
              onClick={addUnitPlan}
              className="flex items-center gap-2 px-4 py-2 bg-purple-500 text-white rounded-xl hover:bg-purple-600 transition-colors text-sm font-medium"
            >
              <Plus className="w-4 h-4" />
              Add Unit Type
            </button>
          )}
        </div>
      </div>

      {/* Empty State */}
      {unitPlans.length === 0 && (
        <div className="mx-6 mt-4 p-4 bg-gray-50 border border-gray-200 rounded-xl flex items-start gap-3">
          <Home className="w-5 h-5 text-gray-400 flex-shrink-0 mt-0.5" />
          <div className="text-sm text-gray-600">
            <p className="font-medium text-gray-700">No unit types added yet</p>
            <p className="mt-1">
              Click "Add Unit Type" to add apartments, shops, offices, penthouses, etc.
              Each unit type can have its own pricing, area, and floor plans.
            </p>
          </div>
        </div>
      )}

      {/* Unit Plans List */}
      <div className="p-6 space-y-4">
        {unitPlans.map((unit, index) => (
          <div
            key={index}
            className="border border-gray-200 rounded-xl overflow-hidden bg-gray-50"
          >
            {/* Unit Header */}
            <div
              onClick={() =>
                setExpandedIndex(expandedIndex === index ? null : index)
              }
              className="px-4 py-3 bg-white flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors"
            >
              <div className="flex items-center gap-3">
                <GripVertical className="w-4 h-4 text-gray-400" />
                <div
                  className={`w-8 h-8 rounded-lg flex items-center justify-center ${
                    unit.category === 'commercial'
                      ? 'bg-amber-100 text-amber-600'
                      : 'bg-purple-100 text-purple-600'
                  }`}
                >
                  {getUnitIcon(unit.type)}
                </div>
                <div>
                  <p className="font-medium text-gray-900">
                    {unit.name || 'Unnamed Unit Type'}
                  </p>
                  <div className="flex items-center gap-3 text-xs text-gray-500">
  {unit.priceRange && unit.priceRange.min > 0 && unit.priceRange.max > 0 && (
    <span className="text-green-600 font-medium">
      PKR {formatPrice(unit.priceRange.min)} - {formatPrice(unit.priceRange.max)}
    </span>
  )}
  {unit.areaRange && unit.areaRange.min > 0 && unit.areaRange.max > 0 && (
    <span>
      {unit.areaRange.min} - {unit.areaRange.max} {unit.areaRange.unit}
    </span>
  )}
  {unit.bedrooms && <span>{unit.bedrooms} Bed</span>}
</div>
                </div>
              </div>

              <div className="flex items-center gap-2">
                {/* Delete */}
                {!disabled && (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      removeUnitPlan(index);
                    }}
                    className="p-1.5 rounded-lg hover:bg-red-100 text-red-500"
                    title="Delete unit"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}

                <ChevronDown
                  className={`w-5 h-5 text-gray-400 transition-transform ${
                    expandedIndex === index ? 'rotate-180' : ''
                  }`}
                />
              </div>
            </div>

            {/* Unit Details (Expandable) */}
            {expandedIndex === index && (
              <div className="px-4 py-4 border-t border-gray-200 space-y-6">
                {/* Basic Info Row */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {/* Unit Type */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Unit Type <span className="text-red-500">*</span>
                    </label>
                    <select
                      value={unit.type}
                      onChange={(e) => {
                        const selectedType = UNIT_TYPES.find(
                          (t) => t.value === e.target.value
                        );
                        updateUnitPlan(index, {
                          type: e.target.value,
                          category: selectedType?.category as 'residential' | 'commercial',
                        });
                      }}
                      className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                      disabled={disabled}
                    >
                      <option value="">Select type</option>
                      <optgroup label="Residential">
                        {UNIT_TYPES.filter((t) => t.category === 'residential').map(
                          (type) => (
                            <option key={type.value} value={type.value}>
                              {type.label}
                            </option>
                          )
                        )}
                      </optgroup>
                      <optgroup label="Commercial">
                        {UNIT_TYPES.filter((t) => t.category === 'commercial').map(
                          (type) => (
                            <option key={type.value} value={type.value}>
                              {type.label}
                            </option>
                          )
                        )}
                      </optgroup>
                    </select>
                  </div>

                  {/* Unit Name */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Display Name <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="text"
                      value={unit.name}
                      onChange={(e) =>
                        updateUnitPlan(index, { name: e.target.value })
                      }
                      placeholder="e.g., Studio Services Apartment"
                      className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                      disabled={disabled}
                    />
                  </div>

                  {/* Category Badge */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Category
                    </label>
                    <div
                      className={`px-3 py-2 rounded-xl text-sm font-medium text-center ${
                        unit.category === 'commercial'
                          ? 'bg-amber-100 text-amber-700'
                          : 'bg-purple-100 text-purple-700'
                      }`}
                    >
                      {unit.category === 'commercial' ? '🏪 Commercial' : '🏠 Residential'}
                    </div>
                  </div>
                </div>

                {/* Price Range */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    <DollarSign className="w-4 h-4 inline mr-1" />
                    Price Range (PKR) <span className="text-red-500">*</span>
                  </label>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs text-gray-500 mb-1">
                        Minimum Price
                      </label>
                      <input
                        type="number"
                        value={unit.priceRange?.min || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, {
                            priceRange: {
                              ...unit.priceRange,
                              min: Number(e.target.value),
                            },
                          })
                        }
                        placeholder="e.g., 28800000"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                      {unit.priceRange?.min > 0 && (
                        <p className="text-xs text-green-600 mt-1">
                          = {formatPrice(unit.priceRange.min)}
                        </p>
                      )}
                    </div>
                    <div>
                      <label className="block text-xs text-gray-500 mb-1">
                        Maximum Price
                      </label>
                      <input
                        type="number"
                        value={unit.priceRange?.max || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, {
                            priceRange: {
                              ...unit.priceRange,
                              max: Number(e.target.value),
                            },
                          })
                        }
                        placeholder="e.g., 38800000"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                      {unit.priceRange?.max > 0 && (
                        <p className="text-xs text-green-600 mt-1">
                          = {formatPrice(unit.priceRange.max)}
                        </p>
                      )}
                    </div>
                  </div>
                </div>

                {/* Area Range */}
<div>
  <label className="block text-sm font-medium text-gray-700 mb-2">
    <Maximize className="w-4 h-4 inline mr-1" />
    Area Range <span className="text-red-500">*</span>
  </label>
  <div className="grid grid-cols-3 gap-4">
    <div>
      <label className="block text-xs text-gray-500 mb-1">
        Minimum Area
      </label>
      <input
        type="number"
        value={unit.areaRange?.min ?? ''}
        onChange={(e) => {
          const currentAreaRange = unit.areaRange || { min: 0, max: 0, unit: 'Sq. Ft.' };
          updateUnitPlan(index, {
            areaRange: {
              ...currentAreaRange,
              min: Number(e.target.value),
            },
          });
        }}
        placeholder="e.g., 450"
        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
        disabled={disabled}
      />
    </div>
    <div>
      <label className="block text-xs text-gray-500 mb-1">
        Maximum Area
      </label>
      <input
        type="number"
        value={unit.areaRange?.max ?? ''}
        onChange={(e) => {
          const currentAreaRange = unit.areaRange || { min: 0, max: 0, unit: 'Sq. Ft.' };
          updateUnitPlan(index, {
            areaRange: {
              ...currentAreaRange,
              max: Number(e.target.value),
            },
          });
        }}
        placeholder="e.g., 548"
        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
        disabled={disabled}
      />
    </div>
    <div>
      <label className="block text-xs text-gray-500 mb-1">
        Unit
      </label>
      <select
        value={unit.areaRange?.unit ?? 'Sq. Ft.'}
        onChange={(e) => {
          const currentAreaRange = unit.areaRange || { min: 0, max: 0, unit: 'Sq. Ft.' };
          updateUnitPlan(index, {
            areaRange: {
              ...currentAreaRange,
              unit: e.target.value,
            },
          });
        }}
        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
        disabled={disabled}
      >
        <option value="Sq. Ft.">Sq. Ft.</option>
        <option value="Marla">Marla</option>
        <option value="Sq. M.">Sq. M.</option>
        <option value="Kanal">Kanal</option>
      </select>
    </div>
  </div>

                  {/* Area Conversions */}
{unit.areaRange && unit.areaRange.min > 0 && unit.areaRange.max > 0 && (
  <div className="mt-2 p-3 bg-gray-100 rounded-xl text-xs text-gray-600">
    <p className="font-medium mb-1">Area Conversions:</p>
    <div className="grid grid-cols-4 gap-2">
      <span>
        Sq.Ft: {unit.areaRange.min} - {unit.areaRange.max}
      </span>
      <span>
        Marla: {convertArea(unit.areaRange.min, 'marla')} -{' '}
        {convertArea(unit.areaRange.max, 'marla')}
      </span>
      <span>
        Sq.M: {convertArea(unit.areaRange.min, 'sqm')} -{' '}
        {convertArea(unit.areaRange.max, 'sqm')}
      </span>
      <span>
        Kanal: {convertArea(unit.areaRange.min, 'kanal')} -{' '}
        {convertArea(unit.areaRange.max, 'kanal')}
      </span>
    </div>
  </div>
)}
                </div>

                {/* Bedrooms & Bathrooms (For Residential) */}
                {unit.category === 'residential' && (
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        <Bed className="w-4 h-4 inline mr-1" />
                        Bedrooms
                      </label>
                      <input
                        type="number"
                        value={unit.bedrooms || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, { bedrooms: Number(e.target.value) })
                        }
                        min="0"
                        max="10"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        <Bath className="w-4 h-4 inline mr-1" />
                        Bathrooms
                      </label>
                      <input
                        type="number"
                        value={unit.bathrooms || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, { bathrooms: Number(e.target.value) })
                        }
                        min="0"
                        max="10"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Total Units
                      </label>
                      <input
                        type="number"
                        value={unit.totalUnits || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, { totalUnits: Number(e.target.value) })
                        }
                        min="0"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Available Units
                      </label>
                      <input
                        type="number"
                        value={unit.availableUnits || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, { availableUnits: Number(e.target.value) })
                        }
                        min="0"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                    </div>
                  </div>
                )}

                {/* Unit Counts (For Commercial) */}
                {unit.category === 'commercial' && (
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Total Units
                      </label>
                      <input
                        type="number"
                        value={unit.totalUnits || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, { totalUnits: Number(e.target.value) })
                        }
                        min="0"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Available Units
                      </label>
                      <input
                        type="number"
                        value={unit.availableUnits || ''}
                        onChange={(e) =>
                          updateUnitPlan(index, { availableUnits: Number(e.target.value) })
                        }
                        min="0"
                        className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                        disabled={disabled}
                      />
                    </div>
                  </div>
                )}

                {/* Features */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Features & Highlights
                  </label>

                  {/* Selected Features */}
                  <div className="flex flex-wrap gap-2 mb-3">
                    {(unit.features || []).map((feature) => (
                      <span
                        key={feature}
                        className="inline-flex items-center gap-1 px-3 py-1 bg-purple-100 text-purple-700 rounded-full text-sm"
                      >
                        {feature}
                        {!disabled && (
                          <button
                            type="button"
                            onClick={() => removeFeature(index, feature)}
                            className="hover:text-purple-900"
                          >
                            <X className="w-3 h-3" />
                          </button>
                        )}
                      </span>
                    ))}
                  </div>

                  {/* Quick Add Features */}
                  <div className="flex flex-wrap gap-1 mb-3">
                    {COMMON_FEATURES.filter(
                      (f) => !(unit.features || []).includes(f)
                    )
                      .slice(0, 8)
                      .map((feature) => (
                        <button
                          key={feature}
                          type="button"
                          onClick={() => addFeature(index, feature)}
                          className="px-2 py-1 text-xs border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors"
                          disabled={disabled}
                        >
                          + {feature}
                        </button>
                      ))}
                  </div>

                  {/* Custom Feature Input */}
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={newFeature[index] || ''}
                      onChange={(e) =>
                        setNewFeature({ ...newFeature, [index]: e.target.value })
                      }
                      placeholder="Add custom feature..."
                      className="flex-1 px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none text-sm"
                      disabled={disabled}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addFeature(index, newFeature[index] || '');
                        }
                      }}
                    />
                    <button
                      type="button"
                      onClick={() => addFeature(index, newFeature[index] || '')}
                      className="px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-xl text-sm font-medium transition-colors"
                      disabled={disabled}
                    >
                      Add
                    </button>
                  </div>
                </div>

                {/* Description */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Description
                  </label>
                  <textarea
                    value={unit.description || ''}
                    onChange={(e) =>
                      updateUnitPlan(index, { description: e.target.value })
                    }
                    placeholder="Describe this unit type..."
                    rows={2}
                    className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none resize-none"
                    disabled={disabled}
                  />
                </div>

                {/* Media Section */}
                <div className="pt-4 border-t border-gray-200">
                  <h4 className="text-sm font-semibold text-gray-700 mb-4 flex items-center gap-2">
                    <ImageIcon className="w-4 h-4" />
                    Media & Floor Plans
                  </h4>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Layout Image */}
                    <FileUploader
                      label="Layout / Floor Plan Image"
                      accept="image"
                      folder={`projects/${projectSlug}/unit-plans`}
                      value={
                        unit.layoutImageUrl && unit.layoutImagePublicId
                          ? {
                              url: unit.layoutImageUrl,
                              publicId: unit.layoutImagePublicId,
                            }
                          : null
                      }
                      onChange={(file) =>
                        updateUnitPlan(index, {
                          layoutImageUrl: file?.url || '',
                          layoutImagePublicId: file?.publicId || '',
                        })
                      }
                      helpText="Main floor plan layout image"
                      disabled={disabled}
                    />

                    {/* Floor Plan PDF */}
                    <FileUploader
                      label="Floor Plan PDF"
                      accept="pdf"
                      folder={`projects/${projectSlug}/unit-plans`}
                      value={
                        unit.floorPlanPdfUrl && unit.floorPlanPdfPublicId
                          ? {
                              url: unit.floorPlanPdfUrl,
                              publicId: unit.floorPlanPdfPublicId,
                            }
                          : null
                      }
                      onChange={(file) =>
                        updateUnitPlan(index, {
                          floorPlanPdfUrl: file?.url || '',
                          floorPlanPdfPublicId: file?.publicId || '',
                        })
                      }
                      helpText="Detailed PDF floor plan"
                      disabled={disabled}
                    />
                  </div>

                  {/* Walkthrough Video URL */}
                  <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      <Video className="w-4 h-4 inline mr-1" />
                      3D Walkthrough Video URL
                    </label>
                    <input
                      type="url"
                      value={unit.walkthroughVideoUrl || ''}
                      onChange={(e) =>
                        updateUnitPlan(index, {
                          walkthroughVideoUrl: e.target.value,
                        })
                      }
                      placeholder="https://youtube.com/watch?v=... or https://vimeo.com/..."
                      className="w-full px-3 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 outline-none"
                      disabled={disabled}
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      Paste YouTube or Vimeo video URL
                    </p>
                  </div>

                  {/* Interior Images */}
                  <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Interior Images
                    </label>

                    {/* Existing Interior Images */}
                    {(unit.interiorImages || []).length > 0 && (
                      <div className="grid grid-cols-4 gap-2 mb-3">
                        {(unit.interiorImages || []).map((img, imgIndex) => (
                          <div key={imgIndex} className="relative group">
                            <img
                              src={img.url}
                              alt={`Interior ${imgIndex + 1}`}
                              className="w-full h-20 object-cover rounded-lg"
                            />
                            {!disabled && (
                              <button
                                type="button"
                                onClick={() => removeInteriorImage(index, imgIndex)}
                                className="absolute top-1 right-1 p-1 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                              >
                                <X className="w-3 h-3" />
                              </button>
                            )}
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Add Interior Image */}
                    <FileUploader
                      label=""
                      accept="image"
                      folder={`projects/${projectSlug}/unit-interiors`}
                      value={null}
                      onChange={(file) => {
                        if (file) {
                          addInteriorImage(index, file);
                        }
                      }}
                      helpText="Add interior view images (multiple allowed)"
                      disabled={disabled}
                    />
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}

        {/* Add Unit Button */}
        {unitPlans.length > 0 && !disabled && (
          <button
            type="button"
            onClick={addUnitPlan}
            className="w-full py-3 border-2 border-dashed border-gray-300 rounded-xl text-gray-500 hover:border-purple-500 hover:text-purple-500 transition-colors flex items-center justify-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Add Another Unit Type
          </button>
        )}
      </div>

      {/* Footer Stats */}
      <div className="px-6 py-3 bg-gray-50 border-t border-gray-200">
        <div className="flex items-center justify-between text-sm">
          <span className="text-gray-500">
            Unit types:{' '}
            <span className="font-medium text-gray-700">{unitPlans.length}</span>
          </span>
          <span className="text-gray-400">
            {unitPlans.filter((u) => u.category === 'residential').length} Residential •{' '}
            {unitPlans.filter((u) => u.category === 'commercial').length} Commercial
          </span>
        </div>
      </div>
    </div>
  );
}

// components/admin/automation/SequenceBuilder.tsx
// ═══════════════════════════════════════════════════════════════
// Main builder for automation sequences
// Combines TriggerSelector + StepEditor list + filters + settings
// ═══════════════════════════════════════════════════════════════

import React, { useState, useCallback } from 'react';
import {
  Plus, Save, Play, Pause, Settings, AlertCircle, CheckCircle,
  ChevronDown, ChevronUp, Filter, Zap, Mail,
} from 'lucide-react';
import TriggerSelector, { AutomationTrigger } from './TriggerSelector';
import StepEditor, { StepData }               from './StepEditor';

// ─── Types ────────────────────────────────────────────────────

export interface SequenceFormData {
  name:             string;
  description:      string;
  trigger:          AutomationTrigger | '';
  status:           'draft' | 'active' | 'paused';
  steps:            StepData[];
  filters:          SequenceFiltersData;
  defaultFromName:  string;
  defaultFromEmail: string;
}

export interface SequenceFiltersData {
  subscriberSource: string[];
  leadCities:       string[];
  leadTypes:        string[];
  leadStatuses:     string[];
  leadPriorities:   string[];
  entityTypes:      string[];
}

const EMPTY_STEP = (stepNumber: number): StepData => ({
  stepNumber,
  delayDays:   stepNumber === 1 ? 0 : 3,
  subject:     '',
  previewText: '',
  content:     '',
  fromName:    '',
  fromEmail:   '',
});

const INITIAL_FORM: SequenceFormData = {
  name:             '',
  description:      '',
  trigger:          '',
  status:           'draft',
  steps:            [EMPTY_STEP(1)],
  filters:          {
    subscriberSource: [],
    leadCities:       [],
    leadTypes:        [],
    leadStatuses:     [],
    leadPriorities:   [],
    entityTypes:      [],
  },
  defaultFromName:  'Highrise.pk',
  defaultFromEmail: '',
};

// ─── Validation ───────────────────────────────────────────────

function validate(form: SequenceFormData): string[] {
  const errors: string[] = [];
  if (!form.name.trim())    errors.push('Sequence name is required');
  if (!form.trigger)        errors.push('Please select a trigger');
  if (form.steps.length === 0) errors.push('Add at least one step');
  form.steps.forEach((step, i) => {
    if (!step.subject.trim()) errors.push(`Step ${i + 1}: Subject is required`);
    if (!step.content.trim()) errors.push(`Step ${i + 1}: Content is required`);
  });
  return errors;
}

// ─── Filter chips helper ──────────────────────────────────────

function FilterChips({
  label, options, selected, onChange,
}: {
  label:    string;
  options:  { value: string; label: string }[];
  selected: string[];
  onChange: (selected: string[]) => void;
}) {
  function toggle(val: string) {
    if (selected.includes(val)) {
      onChange(selected.filter((v) => v !== val));
    } else {
      onChange([...selected, val]);
    }
  }
  return (
    <div>
      <p className="text-xs font-bold text-gray-600 mb-2">{label}</p>
      <div className="flex flex-wrap gap-2">
        {options.map((opt) => (
          <button
            key={opt.value}
            type="button"
            onClick={() => toggle(opt.value)}
            className={`
              px-3 py-1 rounded-full text-xs font-semibold border transition-colors
              ${selected.includes(opt.value)
                ? 'bg-[#004063] text-white border-[#004063]'
                : 'bg-white text-gray-600 border-gray-200 hover:border-gray-400'
              }
            `}
          >
            {opt.label}
          </button>
        ))}
      </div>
    </div>
  );
}

// ─── Main Component ───────────────────────────────────────────

interface SequenceBuilderProps {
  initialData?: Partial<SequenceFormData>;
  onSave:   (data: SequenceFormData) => Promise<void>;
  isSaving: boolean;
  mode:     'create' | 'edit';
}

export default function SequenceBuilder({
  initialData,
  onSave,
  isSaving,
  mode,
}: SequenceBuilderProps) {
  const [form, setForm] = useState<SequenceFormData>({
    ...INITIAL_FORM,
    ...initialData,
    steps: initialData?.steps?.length
      ? initialData.steps
      : [EMPTY_STEP(1)],
  });

  const [errors,         setErrors]         = useState<string[]>([]);
  const [showFilters,    setShowFilters]    = useState(false);
  const [showSettings,   setShowSettings]   = useState(false);
  const [saveSuccess,    setSaveSuccess]    = useState(false);

  // ── Form field helpers ─────────────────────────────────────

  function updateField<K extends keyof SequenceFormData>(
    key: K,
    value: SequenceFormData[K]
  ) {
    setForm((f) => ({ ...f, [key]: value }));
    setErrors([]);
    setSaveSuccess(false);
  }

  function updateFilter<K extends keyof SequenceFiltersData>(
    key: K,
    value: SequenceFiltersData[K]
  ) {
    setForm((f) => ({ ...f, filters: { ...f.filters, [key]: value } }));
  }

  // ── Step CRUD ──────────────────────────────────────────────

  const handleStepChange = useCallback(
    (index: number, updated: Partial<StepData>) => {
      setForm((f) => {
        const steps = [...f.steps];
        steps[index] = { ...steps[index], ...updated };
        return { ...f, steps };
      });
    },
    []
  );

  function addStep() {
    if (form.steps.length >= 20) return;
    setForm((f) => ({
      ...f,
      steps: [
        ...f.steps,
        EMPTY_STEP(f.steps.length + 1),
      ],
    }));
  }

  function deleteStep(index: number) {
    setForm((f) => {
      const steps = f.steps
        .filter((_, i) => i !== index)
        .map((s, i) => ({ ...s, stepNumber: i + 1 }));
      return { ...f, steps };
    });
  }

  function moveStep(index: number, direction: 'up' | 'down') {
    setForm((f) => {
      const steps = [...f.steps];
      const target = direction === 'up' ? index - 1 : index + 1;
      if (target < 0 || target >= steps.length) return f;
      [steps[index], steps[target]] = [steps[target], steps[index]];
      return {
        ...f,
        steps: steps.map((s, i) => ({ ...s, stepNumber: i + 1 })),
      };
    });
  }

  // ── Save ───────────────────────────────────────────────────

  async function handleSave(targetStatus?: 'draft' | 'active' | 'paused') {
    const finalForm = targetStatus
      ? { ...form, status: targetStatus }
      : form;

    const errs = validate(finalForm);
    if (errs.length > 0) {
      setErrors(errs);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    setErrors([]);
    try {
      await onSave(finalForm);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch {
      // onSave handles errors via banner in parent
    }
  }

  // ─── Render ───────────────────────────────────────────────

  const isLeadTrigger = form.trigger === 'lead_created' || form.trigger === 'lead_status_changed';
  const isSubTrigger  = form.trigger === 'subscriber_joined';

  return (
    <div className="space-y-6">

      {/* Error banner */}
      {errors.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-2xl p-4">
          <div className="flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
            <div>
              <p className="font-bold text-red-700 text-sm">Please fix these issues:</p>
              <ul className="mt-1 space-y-0.5">
                {errors.map((e, i) => (
                  <li key={i} className="text-sm text-red-600">• {e}</li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      )}

      {/* Success banner */}
      {saveSuccess && (
        <div className="bg-emerald-50 border border-emerald-200 rounded-2xl p-4 flex items-center gap-3">
          <CheckCircle className="w-5 h-5 text-emerald-500" />
          <p className="text-sm font-semibold text-emerald-700">
            {mode === 'create' ? 'Sequence created successfully!' : 'Changes saved successfully!'}
          </p>
        </div>
      )}

      {/* ── Section 1: Basic Info ─────────────────────────── */}
      <div className="bg-white rounded-2xl border border-gray-200 p-5 shadow-sm space-y-4">
        <div className="flex items-center gap-2 text-[#004063]">
          <Zap className="w-5 h-5" />
          <h2 className="font-black text-base">Sequence Details</h2>
        </div>

        <div>
          <label className="block text-xs font-bold text-gray-700 mb-1.5">
            Sequence Name <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={form.name}
            onChange={(e) => updateField('name', e.target.value)}
            placeholder="e.g. New Subscriber Welcome Series"
            maxLength={200}
            className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm
                       focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none"
          />
        </div>

        <div>
          <label className="block text-xs font-bold text-gray-700 mb-1.5">
            Description
            <span className="text-gray-400 font-normal ml-1">(optional)</span>
          </label>
          <textarea
            value={form.description}
            onChange={(e) => updateField('description', e.target.value)}
            placeholder="What is this automation for? (internal notes)"
            maxLength={1000}
            rows={2}
            className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm
                       focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none resize-none"
          />
        </div>
      </div>

      {/* ── Section 2: Trigger ───────────────────────────── */}
      <div className="bg-white rounded-2xl border border-gray-200 p-5 shadow-sm">
        <div className="flex items-center gap-2 text-[#004063] mb-4">
          <Play className="w-5 h-5" />
          <h2 className="font-black text-base">Trigger</h2>
          <span className="text-red-500 text-sm">*</span>
        </div>
        <TriggerSelector
          value={form.trigger}
          onChange={(t) => updateField('trigger', t)}
          disabled={mode === 'edit'}
        />
        {mode === 'edit' && (
          <p className="mt-2 text-xs text-amber-600 flex items-center gap-1.5">
            <AlertCircle className="w-3.5 h-3.5" />
            Trigger cannot be changed after creation (would affect existing enrollments)
          </p>
        )}
      </div>

      {/* ── Section 3: Filters ──────────────────────────── */}
      {form.trigger && (
        <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
          <button
            type="button"
            onClick={() => setShowFilters((s) => !s)}
            className="w-full flex items-center justify-between px-5 py-4
                       hover:bg-gray-50 transition-colors text-left"
          >
            <div className="flex items-center gap-2 text-[#004063]">
              <Filter className="w-5 h-5" />
              <h2 className="font-black text-base">Audience Filters</h2>
              <span className="text-xs font-normal text-gray-400">
                (optional — restrict who qualifies)
              </span>
            </div>
            {showFilters
              ? <ChevronUp className="w-4 h-4 text-gray-400" />
              : <ChevronDown className="w-4 h-4 text-gray-400" />
            }
          </button>

          {showFilters && (
            <div className="px-5 pb-5 space-y-5 border-t border-gray-100 pt-4">

              {isSubTrigger && (
                <FilterChips
                  label="Subscriber Source"
                  options={[
                    { value: 'website',  label: 'Website' },
                    { value: 'popup',    label: 'Popup' },
                    { value: 'footer',   label: 'Footer' },
                    { value: 'blog',     label: 'Blog' },
                    { value: 'referral', label: 'Referral' },
                  ]}
                  selected={form.filters.subscriberSource}
                  onChange={(v) => updateFilter('subscriberSource', v)}
                />
              )}

              {isLeadTrigger && (
                <>
                  <FilterChips
                    label="Lead City"
                    options={[
                      { value: 'Karachi',   label: 'Karachi' },
                      { value: 'Lahore',    label: 'Lahore' },
                      { value: 'Islamabad', label: 'Islamabad' },
                      { value: 'Rawalpindi', label: 'Rawalpindi' },
                      { value: 'Peshawar',  label: 'Peshawar' },
                      { value: 'Quetta',    label: 'Quetta' },
                    ]}
                    selected={form.filters.leadCities}
                    onChange={(v) => updateFilter('leadCities', v)}
                  />
                  <FilterChips
                    label="Inquiry Type"
                    options={[
                      { value: 'property_inquiry',  label: 'Property Inquiry' },
                      { value: 'project_interest',  label: 'Project Interest' },
                      { value: 'site_visit',        label: 'Site Visit' },
                      { value: 'rent_inquiry',      label: 'Rent Inquiry' },
                    ]}
                    selected={form.filters.leadTypes}
                    onChange={(v) => updateFilter('leadTypes', v)}
                  />
                  <FilterChips
                    label="Priority"
                    options={[
                      { value: 'urgent', label: '🔴 Urgent' },
                      { value: 'high',   label: '🟠 High' },
                      { value: 'medium', label: '🟡 Medium' },
                      { value: 'low',    label: '🟢 Low' },
                    ]}
                    selected={form.filters.leadPriorities}
                    onChange={(v) => updateFilter('leadPriorities', v)}
                  />
                  <FilterChips
                    label="Entity Type"
                    options={[
                      { value: 'project',  label: 'Project' },
                      { value: 'property', label: 'Property' },
                    ]}
                    selected={form.filters.entityTypes}
                    onChange={(v) => updateFilter('entityTypes', v)}
                  />
                </>
              )}

              <p className="text-xs text-gray-400">
                Leave all filters empty to enroll every qualifying recipient.
              </p>
            </div>
          )}
        </div>
      )}

      {/* ── Section 4: Steps ─────────────────────────────── */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2 text-[#004063]">
            <Mail className="w-5 h-5" />
            <h2 className="font-black text-base">Email Steps</h2>
            <span className="bg-[#004063] text-white text-xs rounded-full px-2 py-0.5 font-bold">
              {form.steps.length}
            </span>
          </div>
          <button
            type="button"
            onClick={addStep}
            disabled={form.steps.length >= 20}
            className="flex items-center gap-1.5 px-3 py-1.5 bg-[#029bba] text-white
                       rounded-xl text-xs font-bold hover:bg-[#0289a7] transition-colors
                       disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Plus className="w-3.5 h-3.5" />
            Add Step
          </button>
        </div>

        {form.steps.length === 0 && (
          <div className="text-center py-10 border-2 border-dashed border-gray-200 rounded-2xl">
            <Mail className="w-10 h-10 text-gray-300 mx-auto mb-3" />
            <p className="text-gray-500 font-semibold text-sm">No steps yet</p>
            <p className="text-gray-400 text-xs mt-1">Add your first email step above</p>
          </div>
        )}

        {form.steps.map((step, index) => (
          <StepEditor
            key={index}
            step={step}
            index={index}
            totalSteps={form.steps.length}
            onChange={handleStepChange}
            onDelete={deleteStep}
            onMoveUp={(i) => moveStep(i, 'up')}
            onMoveDown={(i) => moveStep(i, 'down')}
            defaultFromName={form.defaultFromName}
            defaultFromEmail={form.defaultFromEmail}
          />
        ))}

        {form.steps.length > 0 && form.steps.length < 20 && (
          <button
            type="button"
            onClick={addStep}
            className="w-full py-3 border-2 border-dashed border-gray-200 rounded-2xl
                       text-gray-400 text-sm font-semibold hover:border-[#029bba]
                       hover:text-[#029bba] transition-colors flex items-center justify-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Add Another Step
          </button>
        )}
      </div>

      {/* ── Section 5: Settings (collapsible) ────────────── */}
      <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
        <button
          type="button"
          onClick={() => setShowSettings((s) => !s)}
          className="w-full flex items-center justify-between px-5 py-4
                     hover:bg-gray-50 transition-colors text-left"
        >
          <div className="flex items-center gap-2 text-[#004063]">
            <Settings className="w-5 h-5" />
            <h2 className="font-black text-base">Default Sender</h2>
            <span className="text-xs font-normal text-gray-400">
              (used for steps without override)
            </span>
          </div>
          {showSettings
            ? <ChevronUp className="w-4 h-4 text-gray-400" />
            : <ChevronDown className="w-4 h-4 text-gray-400" />
          }
        </button>

        {showSettings && (
          <div className="px-5 pb-5 border-t border-gray-100 pt-4 grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-700 mb-1.5">
                From Name
              </label>
              <input
                type="text"
                value={form.defaultFromName}
                onChange={(e) => updateField('defaultFromName', e.target.value)}
                placeholder="Highrise.pk"
                maxLength={100}
                className="w-full px-3 py-2.5 border border-gray-200 rounded-xl text-sm
                           focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-700 mb-1.5">
                Reply-To Email
              </label>
              <input
                type="email"
                value={form.defaultFromEmail}
                onChange={(e) => updateField('defaultFromEmail', e.target.value)}
                placeholder="team@highrise.pk"
                maxLength={254}
                className="w-full px-3 py-2.5 border border-gray-200 rounded-xl text-sm
                           focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none"
              />
            </div>
          </div>
        )}
      </div>

      {/* ── Action Bar ───────────────────────────────────── */}
      <div className="sticky bottom-4 z-10">
        <div className="bg-white rounded-2xl border border-gray-200 shadow-xl p-4
                        flex items-center justify-between gap-3">

          <div className="text-xs text-gray-500">
            {form.steps.length} step{form.steps.length !== 1 ? 's' : ''} ·{' '}
            {form.trigger || 'no trigger selected'}
          </div>

          <div className="flex items-center gap-2">
            {/* Save as draft */}
            <button
              type="button"
              onClick={() => handleSave('draft')}
              disabled={isSaving}
              className="flex items-center gap-1.5 px-4 py-2 border border-gray-200
                         rounded-xl text-sm font-semibold text-gray-700
                         hover:bg-gray-50 transition-colors disabled:opacity-50"
            >
              <Save className="w-4 h-4" />
              Save Draft
            </button>

            {/* Activate */}
            <button
              type="button"
              onClick={() => handleSave('active')}
              disabled={isSaving}
              className="flex items-center gap-1.5 px-4 py-2 bg-[#029bba] text-white
                         rounded-xl text-sm font-bold hover:bg-[#0289a7] transition-colors
                         disabled:opacity-50"
            >
              {isSaving ? (
                <span className="flex items-center gap-1.5">
                  <svg className="animate-spin w-4 h-4" viewBox="0 0 24 24" fill="none">
                    <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" className="opacity-25" />
                    <path fill="currentColor" d="M4 12a8 8 0 018-8v8H4z" className="opacity-75" />
                  </svg>
                  Saving...
                </span>
              ) : (
                <>
                  <Play className="w-4 h-4" />
                  {mode === 'create' ? 'Create & Activate' : 'Save & Activate'}
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

