// components/admin/automation/StepEditor.tsx
// ═══════════════════════════════════════════════════════════════
// Editor for a single automation step
// Shows delay, subject, content (TipTap), from name/email
// ═══════════════════════════════════════════════════════════════

import React, { useRef, useState } from 'react';
import {
  Clock, Mail, User, ChevronDown, ChevronUp, Trash2, GripVertical, Eye,
} from 'lucide-react';
import dynamic from 'next/dynamic';

// Dynamically import RichTextEditor to avoid SSR issues
const RichTextEditor = dynamic(
  () => import('@/components/admin/campaigns/RichTextEditor'),
  { ssr: false, loading: () => <div className="h-48 bg-gray-50 rounded-xl animate-pulse" /> }
);

export interface StepData {
  stepNumber:  number;
  delayDays:   number;
  subject:     string;
  previewText: string;
  content:     string;
  fromName:    string;
  fromEmail:   string;
}

interface StepEditorProps {
  step:          StepData;
  index:         number;
  totalSteps:    number;
  onChange:      (index: number, updated: Partial<StepData>) => void;
  onDelete:      (index: number) => void;
  onMoveUp:      (index: number) => void;
  onMoveDown:    (index: number) => void;
  defaultFromName?:  string;
  defaultFromEmail?: string;
}

// Delay presets
const DELAY_PRESETS = [
  { label: 'Immediately',  days: 0 },
  { label: 'After 1 day',  days: 1 },
  { label: 'After 2 days', days: 2 },
  { label: 'After 3 days', days: 3 },
  { label: 'After 5 days', days: 5 },
  { label: 'After 7 days', days: 7 },
  { label: 'After 10 days', days: 10 },
  { label: 'After 14 days', days: 14 },
  { label: 'After 30 days', days: 30 },
  { label: 'Custom',       days: -1 },
];

export default function StepEditor({
  step,
  index,
  totalSteps,
  onChange,
  onDelete,
  onMoveUp,
  onMoveDown,
  defaultFromName  = 'Highrise.pk',
  defaultFromEmail = '',
}: StepEditorProps) {
  const [expanded,       setExpanded]       = useState(index === 0);
  const [showDelayInput, setShowDelayInput] = useState(false);
  const [showSenderOpts, setShowSenderOpts] = useState(false);
  const editorRef = useRef<any>(null);

  const delayPreset = DELAY_PRESETS.find((p) => p.days === step.delayDays);
  const delayLabel  = delayPreset && delayPreset.days !== -1
    ? delayPreset.label
    : `After ${step.delayDays} day${step.delayDays !== 1 ? 's' : ''}`;

  function handleDelayPreset(days: number) {
    if (days === -1) {
      setShowDelayInput(true);
    } else {
      onChange(index, { delayDays: days });
      setShowDelayInput(false);
    }
  }

  return (
    <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-sm">

      {/* ── Header ─────────────────────────────────────────── */}
      <div
        className="flex items-center gap-3 px-4 py-3 cursor-pointer hover:bg-gray-50 transition-colors"
        onClick={() => setExpanded((e) => !e)}
      >
        {/* Drag handle (visual only) */}
        <GripVertical className="w-4 h-4 text-gray-300 flex-shrink-0" />

        {/* Step badge */}
        <div className="flex-shrink-0 w-8 h-8 rounded-full bg-[#029bba] text-white text-sm font-bold flex items-center justify-center">
          {index + 1}
        </div>

        {/* Step summary */}
        <div className="flex-1 min-w-0">
          <p className="font-semibold text-gray-800 text-sm truncate">
            {step.subject || `Step ${index + 1} — (no subject)`}
          </p>
          <p className="text-xs text-gray-500 flex items-center gap-1 mt-0.5">
            <Clock className="w-3 h-3" />
            {index === 0 && step.delayDays === 0
              ? 'Sends immediately on enrollment'
              : delayLabel + ' after previous step'}
          </p>
        </div>

        {/* Reorder controls */}
        <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
          <button
            type="button"
            disabled={index === 0}
            onClick={() => onMoveUp(index)}
            className="p-1 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100
                       disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
            title="Move up"
          >
            <ChevronUp className="w-4 h-4" />
          </button>
          <button
            type="button"
            disabled={index === totalSteps - 1}
            onClick={() => onMoveDown(index)}
            className="p-1 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100
                       disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
            title="Move down"
          >
            <ChevronDown className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => onDelete(index)}
            className="p-1 rounded-lg text-red-400 hover:text-red-600 hover:bg-red-50 transition-colors ml-1"
            title="Delete step"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>

        {/* Expand toggle */}
        <div className="text-gray-400">
          {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
        </div>
      </div>

      {/* ── Body ───────────────────────────────────────────── */}
      {expanded && (
        <div className="px-4 pb-5 space-y-4 border-t border-gray-100 pt-4">

          {/* Delay selector */}
          <div>
            <label className="flex items-center gap-1.5 text-xs font-bold text-gray-700 mb-2">
              <Clock className="w-3.5 h-3.5" />
              Send Delay
              {index === 0 && (
                <span className="text-gray-400 font-normal">(delay after enrollment)</span>
              )}
              {index > 0 && (
                <span className="text-gray-400 font-normal">(delay after previous step)</span>
              )}
            </label>
            <div className="flex flex-wrap gap-2">
              {DELAY_PRESETS.map((preset) => (
                <button
                  key={preset.label}
                  type="button"
                  onClick={() => handleDelayPreset(preset.days)}
                  className={`
                    px-3 py-1.5 rounded-xl text-xs font-semibold border transition-colors
                    ${preset.days === step.delayDays || (preset.days === -1 && !DELAY_PRESETS.find((p) => p.days === step.delayDays && p.days !== -1))
                      ? 'bg-[#029bba] text-white border-[#029bba]'
                      : 'bg-white text-gray-600 border-gray-200 hover:border-[#029bba] hover:text-[#029bba]'
                    }
                  `}
                >
                  {preset.label}
                </button>
              ))}
            </div>

            {showDelayInput && (
              <div className="mt-2 flex items-center gap-2">
                <input
                  type="number"
                  min={0}
                  max={365}
                  value={step.delayDays}
                  onChange={(e) => onChange(index, { delayDays: Math.min(365, Math.max(0, parseInt(e.target.value) || 0)) })}
                  className="w-24 px-3 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none"
                />
                <span className="text-sm text-gray-500">days</span>
              </div>
            )}
          </div>

          {/* Subject */}
          <div>
            <label className="flex items-center gap-1.5 text-xs font-bold text-gray-700 mb-1.5">
              <Mail className="w-3.5 h-3.5" />
              Email Subject <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={step.subject}
              onChange={(e) => onChange(index, { subject: e.target.value })}
              placeholder="e.g. Welcome to Highrise.pk — Aapka Swagat Hai!"
              maxLength={255}
              className="w-full px-3 py-2.5 border border-gray-200 rounded-xl text-sm
                         focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none"
            />
            <div className="flex justify-between mt-1">
              <p className="text-xs text-gray-400">
                Merge tags like {'{{firstName}}'} are supported
              </p>
              <span className={`text-xs ${step.subject.length > 200 ? 'text-amber-500' : 'text-gray-400'}`}>
                {step.subject.length}/255
              </span>
            </div>
          </div>

          {/* Preview text */}
          <div>
            <label className="flex items-center gap-1.5 text-xs font-bold text-gray-700 mb-1.5">
              <Eye className="w-3.5 h-3.5" />
              Preview Text
              <span className="text-gray-400 font-normal">(optional — shown in inbox)</span>
            </label>
            <input
              type="text"
              value={step.previewText}
              onChange={(e) => onChange(index, { previewText: e.target.value })}
              placeholder="Brief preview shown below subject line in email clients..."
              maxLength={200}
              className="w-full px-3 py-2.5 border border-gray-200 rounded-xl text-sm
                         focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none"
            />
          </div>

          {/* Email Content */}
          <div>
            <label className="block text-xs font-bold text-gray-700 mb-1.5">
              Email Content <span className="text-red-500">*</span>
            </label>
            <div className="border border-gray-200 rounded-xl overflow-hidden">
              <RichTextEditor
                ref={editorRef}
                content={step.content}
                onChange={(html: string) => onChange(index, { content: html })}
                placeholder="Write your email content here... Use merge tags like {{firstName}}, {{city}}"
              />
            </div>
            <p className="text-xs text-gray-400 mt-1">
              An unsubscribe footer is automatically added to every email
            </p>
          </div>

          {/* Sender Override (collapsible) */}
          <div>
            <button
              type="button"
              onClick={() => setShowSenderOpts((s) => !s)}
              className="flex items-center gap-1.5 text-xs font-semibold text-gray-500
                         hover:text-gray-700 transition-colors"
            >
              <User className="w-3.5 h-3.5" />
              Override Sender for this Step
              {showSenderOpts ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            </button>

            {showSenderOpts && (
              <div className="mt-3 grid grid-cols-2 gap-3 p-3 bg-gray-50 rounded-xl border border-gray-100">
                <div>
                  <label className="block text-xs font-bold text-gray-600 mb-1">
                    From Name
                  </label>
                  <input
                    type="text"
                    value={step.fromName}
                    onChange={(e) => onChange(index, { fromName: e.target.value })}
                    placeholder={defaultFromName || 'Highrise.pk'}
                    maxLength={100}
                    className="w-full px-3 py-2 border border-gray-200 rounded-xl text-sm
                               focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none bg-white"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-600 mb-1">
                    Reply-To Email
                  </label>
                  <input
                    type="email"
                    value={step.fromEmail}
                    onChange={(e) => onChange(index, { fromEmail: e.target.value })}
                    placeholder={defaultFromEmail || 'team@highrise.pk'}
                    maxLength={254}
                    className="w-full px-3 py-2 border border-gray-200 rounded-xl text-sm
                               focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none bg-white"
                  />
                </div>
                <p className="col-span-2 text-xs text-gray-400">
                  Leave blank to use the sequence default sender
                </p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// pages/admin/automation/[id]/edit.tsx
// ═══════════════════════════════════════════════════════════════
// EDIT AUTOMATION SEQUENCE — HIGHRISE.PK
// Loads existing sequence → renders SequenceBuilder in edit mode
// ═══════════════════════════════════════════════════════════════

import React, { useEffect, useState, useCallback } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import {
  Loader2,
  X,
  ArrowLeft,
  AlertCircle,
  Users,
  CheckCircle,
  XCircle,
  Clock,
} from 'lucide-react';
import AdminLayout from '@/components/admin/AdminLayout';
import SequenceBuilder, {
  SequenceFormData,
} from '@/components/admin/automation/SequenceBuilder';

// ─── Types ────────────────────────────────────────────────────

interface Banner {
  type:    'success' | 'error' | 'info';
  message: string;
}

interface EnrollmentStats {
  active:    number;
  completed: number;
  cancelled: number;
  failed:    number;
  total:     number;
}

interface RecentEnrollment {
  email:         string;
  name:          string;
  status:        string;
  currentStep:   number;
  enrolledAt:    string;
  nextSendAt:    string | null;
  recipientType: string;
}

// ─── Helpers ──────────────────────────────────────────────────

function formatDate(iso: string | null): string {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString('en-PK', {
    day:    'numeric',
    month:  'short',
    year:   'numeric',
    hour:   '2-digit',
    minute: '2-digit',
  });
}

function enrollmentStatusStyle(status: string): string {
  switch (status) {
    case 'active':    return 'bg-emerald-100 text-emerald-700';
    case 'completed': return 'bg-blue-100 text-blue-700';
    case 'cancelled': return 'bg-gray-100 text-gray-600';
    case 'failed':    return 'bg-red-100 text-red-600';
    default:          return 'bg-gray-100 text-gray-600';
  }
}

// ─── Enrollment Stats Panel ───────────────────────────────────

const EnrollmentStatsPanel: React.FC<{
  stats:             EnrollmentStats;
  recentEnrollments: RecentEnrollment[];
}> = ({ stats, recentEnrollments }) => (
  <div className="bg-white rounded-2xl border border-gray-200 p-5 shadow-sm">
    <h3 className="text-sm font-black text-[#004063] mb-4 flex items-center gap-2">
      <Users className="w-4 h-4 text-[#029bba]" />
      Enrollment Activity
    </h3>

    {/* Stats grid */}
    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5">
      {[
        {
          label: 'Active',
          value: stats.active,
          Icon:  Clock,
          color: 'text-amber-600',
          bg:    'bg-amber-50',
        },
        {
          label: 'Completed',
          value: stats.completed,
          Icon:  CheckCircle,
          color: 'text-emerald-600',
          bg:    'bg-emerald-50',
        },
        {
          label: 'Cancelled',
          value: stats.cancelled,
          Icon:  XCircle,
          color: 'text-gray-500',
          bg:    'bg-gray-100',
        },
        {
          label: 'Failed',
          value: stats.failed,
          Icon:  AlertCircle,
          color: 'text-red-500',
          bg:    'bg-red-50',
        },
      ].map((s) => (
        <div
          key={s.label}
          className="flex items-center gap-3 p-3 rounded-xl border border-gray-100"
        >
          <div className={`w-8 h-8 rounded-lg ${s.bg} flex items-center
                          justify-center flex-shrink-0`}>
            <s.Icon className={`w-4 h-4 ${s.color}`} />
          </div>
          <div>
            <p className={`text-lg font-black ${s.color}`}>
              {s.value.toLocaleString()}
            </p>
            <p className="text-[10px] text-gray-400 font-semibold uppercase
                          tracking-wider">
              {s.label}
            </p>
          </div>
        </div>
      ))}
    </div>

    {/* Recent enrollments table */}
    {recentEnrollments.length === 0 ? (
      <div className="text-center py-6 text-gray-400">
        <Users className="w-8 h-8 mx-auto mb-2 opacity-40" />
        <p className="text-sm">No enrollments yet</p>
        <p className="text-xs mt-1">
          Recipients will appear here when the sequence is active
        </p>
      </div>
    ) : (
      <div>
        <p className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3">
          Recent Enrollments
        </p>
        <div className="space-y-2">
          {recentEnrollments.map((enrollment, i) => (
            <div
              key={i}
              className="flex items-center gap-3 p-3 rounded-xl
                         hover:bg-gray-50 transition-colors"
            >
              {/* Avatar */}
              <div className="w-8 h-8 rounded-full bg-gradient-to-br
                              from-[#029bba] to-[#004063] flex items-center
                              justify-center text-white text-xs font-black
                              flex-shrink-0">
                {(enrollment.name || enrollment.email).charAt(0).toUpperCase()}
              </div>

              {/* Details */}
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-gray-800 truncate">
                  {enrollment.name || enrollment.email}
                </p>
                <p className="text-xs text-gray-400 truncate">
                  {enrollment.name ? enrollment.email : ''}
                </p>
              </div>

              {/* Step + status */}
              <div className="flex items-center gap-2 flex-shrink-0">
                <span className="text-xs text-gray-400">
                  Step {enrollment.currentStep}
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-full
                                  font-bold ${enrollmentStatusStyle(enrollment.status)}`}>
                  {enrollment.status}
                </span>
              </div>

              {/* Next send */}
              <div className="text-right flex-shrink-0 hidden md:block">
                <p className="text-[10px] text-gray-400">
                  {enrollment.status === 'active' && enrollment.nextSendAt
                    ? `Next: ${formatDate(enrollment.nextSendAt)}`
                    : formatDate(enrollment.enrolledAt)
                  }
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    )}
  </div>
);

// ─── Main Page ────────────────────────────────────────────────

export default function EditAutomationPage() {
  const router  = useRouter();
  const { id }  = router.query;
  const { data: session, status: sessionStatus } = useSession();

  const [initialData,        setInitialData]        = useState<Partial<SequenceFormData> | null>(null);
  const [sequenceName,       setSequenceName]        = useState('');
  const [enrollmentStats,    setEnrollmentStats]     = useState<EnrollmentStats | null>(null);
  const [recentEnrollments,  setRecentEnrollments]   = useState<RecentEnrollment[]>([]);
  const [pageLoading,        setPageLoading]         = useState(true);
  const [pageError,          setPageError]           = useState('');
  const [isSaving,           setIsSaving]            = useState(false);
  const [banner,             setBanner]              = useState<Banner | null>(null);

  // ── Auth guard ────────────────────────────────────────────
  useEffect(() => {
    if (sessionStatus === 'loading') return;
    if (!session) {
      router.replace(
        `/login?redirect=${encodeURIComponent(router.asPath)}`
      );
      return;
    }
    if ((session.user as any)?.role !== 'admin') {
      router.replace('/');
    }
  }, [session, sessionStatus, router]);

  // ── Banner auto-dismiss ───────────────────────────────────
  useEffect(() => {
    if (!banner) return;
    const t = setTimeout(() => setBanner(null), 4500);
    return () => clearTimeout(t);
  }, [banner]);

  // ── Load sequence data ────────────────────────────────────
  const loadSequence = useCallback(async () => {
    if (!id || typeof id !== 'string') return;

    setPageLoading(true);
    setPageError('');

    try {
      const res  = await fetch(`/api/automation/sequences/${id}`, {
        credentials: 'include',
      });
      const data = await res.json();

      if (!res.ok || !data.success) {
        setPageError(data.message || 'Failed to load sequence');
        return;
      }

      const seq = data.sequence;
      setSequenceName(seq.name || 'Sequence');

      // Map API shape → SequenceFormData shape
      const formData: Partial<SequenceFormData> = {
        name:            seq.name         || '',
        description:     seq.description  || '',
        trigger:         seq.trigger      || '',
        status:          seq.status       || 'draft',
        steps:           (seq.steps || []).map((s: any) => ({
          stepNumber:  s.stepNumber  || 1,
          delayDays:   s.delayDays   || 0,
          subject:     s.subject     || '',
          previewText: s.previewText || '',
          content:     s.content     || '',
          fromName:    s.fromName    || '',
          fromEmail:   s.fromEmail   || '',
        })),
        filters: {
          subscriberSource: seq.triggerFilters?.subscriberSources || [],
          leadCities:       seq.triggerFilters?.leadCities        || [],
          leadTypes:        seq.triggerFilters?.leadTypes         || [],
          leadStatuses:     seq.triggerFilters?.leadStatuses      || [],
          leadPriorities:   [],
          entityTypes:      [],
        },
        defaultFromName:  seq.defaultFromName  || 'Highrise.pk',
        defaultFromEmail: seq.defaultFromEmail || '',
      };

      setInitialData(formData);
      setEnrollmentStats(data.enrollmentStats || null);
      setRecentEnrollments(data.recentEnrollments || []);

    } catch {
      setPageError('Network error — please try again');
    } finally {
      setPageLoading(false);
    }
  }, [id]);

  useEffect(() => {
    if (sessionStatus === 'authenticated' && id) {
      loadSequence();
    }
  }, [id, sessionStatus, loadSequence]);

  // ── Save handler ──────────────────────────────────────────
  const handleSave = async (data: SequenceFormData): Promise<void> => {
    if (!id || typeof id !== 'string') return;

    setIsSaving(true);
    try {
      const triggerFilters = {
        subscriberSources: data.filters.subscriberSource,
        leadCities:        data.filters.leadCities,
        leadTypes:         data.filters.leadTypes,
        leadStatuses:      data.filters.leadStatuses,
        leadSources:       [],
      };

      const res = await fetch(`/api/automation/sequences/${id}`, {
        method:      'PUT',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name:             data.name,
          description:      data.description,
          status:           data.status,
          steps:            data.steps,
          triggerFilters,
          defaultFromName:  data.defaultFromName,
          defaultFromEmail: data.defaultFromEmail,
        }),
      });

      const result = await res.json();

      if (result.success) {
        setBanner({
          type:    'success',
          message: 'Sequence saved successfully',
        });
        // Refresh enrollment stats
        loadSequence();
      } else {
        setBanner({
          type:    'error',
          message: result.message || 'Failed to save sequence',
        });
        throw new Error(result.message);
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Network error';
      setBanner({ type: 'error', message: msg });
      throw err;
    } finally {
      setIsSaving(false);
    }
  };

  // ── Loading state ─────────────────────────────────────────
  if (sessionStatus === 'loading' || !session) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-10 h-10 animate-spin text-[#029bba]" />
      </div>
    );
  }

  // ── Page error state ──────────────────────────────────────
  if (pageError) {
    return (
      <AdminLayout>
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
          <div className="text-center max-w-md">
            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center
                            justify-center mx-auto mb-4">
              <AlertCircle className="w-8 h-8 text-red-500" />
            </div>
            <h2 className="text-lg font-black text-[#004063] mb-2">
              Could not load sequence
            </h2>
            <p className="text-gray-500 text-sm mb-4">{pageError}</p>
            <div className="flex gap-3 justify-center">
              <button
                type="button"
                onClick={loadSequence}
                className="px-4 py-2 bg-[#029bba] text-white rounded-xl
                           text-sm font-bold hover:bg-[#027a94] transition-colors"
              >
                Try Again
              </button>
              <Link
                href="/admin/automation"
                className="px-4 py-2 border border-gray-300 text-gray-700
                           rounded-xl text-sm font-semibold hover:bg-gray-50
                           transition-colors"
              >
                Back to Automation
              </Link>
            </div>
          </div>
        </div>
      </AdminLayout>
    );
  }

  // ── Page loading state ────────────────────────────────────
  if (pageLoading || !initialData) {
    return (
      <AdminLayout>
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
          <div className="text-center">
            <Loader2 className="w-10 h-10 animate-spin text-[#029bba]
                                mx-auto mb-3" />
            <p className="text-gray-500 text-sm font-semibold">
              Loading sequence...
            </p>
          </div>
        </div>
      </AdminLayout>
    );
  }

  return (
    <>
      <Head>
        <title>{sequenceName} — Edit · Highrise.pk Admin</title>
        <meta name="robots" content="noindex,nofollow" />
      </Head>

      <AdminLayout>
        <div className="min-h-screen bg-gray-50 py-8">
          <div className="container mx-auto px-4 max-w-3xl">

            {/* ── Page header ─────────────────────────────── */}
            <div className="flex items-center gap-3 mb-6">
              <Link
                href="/admin/automation"
                className="p-2 hover:bg-white rounded-xl border border-transparent
                           hover:border-gray-200 transition-all text-gray-500"
              >
                <ArrowLeft className="w-5 h-5" />
              </Link>
              <div>
                <h1 className="text-2xl font-black text-[#004063]">
                  Edit Sequence
                </h1>
                <p className="text-sm text-gray-500 mt-0.5 truncate max-w-md">
                  {sequenceName}
                </p>
              </div>
            </div>

            {/* ── Enrollment stats panel ───────────────────── */}
            {enrollmentStats && (
              <div className="mb-6">
                <EnrollmentStatsPanel
                  stats={enrollmentStats}
                  recentEnrollments={recentEnrollments}
                />
              </div>
            )}

            {/* ── Sequence builder ─────────────────────────── */}
            <SequenceBuilder
              mode="edit"
              initialData={initialData}
              onSave={handleSave}
              isSaving={isSaving}
            />

          </div>
        </div>
      </AdminLayout>

      {/* ── Banner ───────────────────────────────────────────── */}
      {banner && (
        <div className="fixed top-5 left-1/2 -translate-x-1/2 z-50
                        max-w-md w-full mx-4">
          <div className={`p-4 rounded-2xl shadow-2xl flex items-start gap-3
            ${banner.type === 'success' ? 'bg-emerald-500 text-white'
            : banner.type === 'error'   ? 'bg-red-500 text-white'
            :                             'bg-[#029bba] text-white'}`}>
            <p className="flex-1 text-sm font-bold">{banner.message}</p>
            <button
              type="button"
              onClick={() => setBanner(null)}
              className="text-white/80 hover:text-white flex-shrink-0"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  X,
  Search,
  Image as ImageIcon,
  Check,
  RefreshCw,
  Upload,
  Info,
  CheckCircle2,
  Maximize2,
  FileImage,
  Type,
  AlignLeft,
} from 'lucide-react';
import { useDropzone } from 'react-dropzone';
import toast from 'react-hot-toast';

interface MediaItem {
  _id: string;
  url: string;
  originalName: string;
  format: string;
  size: number;
  width?: number;
  height?: number;
}

interface SelectedMediaPayload extends MediaItem {
  alt?: string;
  caption?: string;
}

interface MediaPickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (media: SelectedMediaPayload | SelectedMediaPayload[]) => void;
  title?: string;
  multiple?: boolean;
}

function formatFileSize(bytes: number) {
  if (!bytes || Number.isNaN(bytes)) return '0 B';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

export default function MediaPickerModal({
  isOpen,
  onClose,
  onSelect,
  title = 'Select Image',
  multiple = false,
}: MediaPickerModalProps) {
  const [media, setMedia] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedMedia, setSelectedMedia] = useState<MediaItem | null>(null);
  const [selectedMediaList, setSelectedMediaList] = useState<MediaItem[]>([]);
  const [uploading, setUploading] = useState(false);

  const [altText, setAltText] = useState('');
  const [caption, setCaption] = useState('');

  // fetch media
  const fetchMedia = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        type: 'image',
        limit: '60',
      });

      if (searchQuery.trim()) {
        params.append('search', searchQuery.trim());
      }

      const res = await fetch(`/api/admin/media?${params.toString()}`);
      const data = await res.json();

      if (data.success) {
        setMedia(Array.isArray(data.media) ? data.media : []);
      } else {
        toast.error(data.message || 'Failed to fetch media');
      }
    } catch (error) {
      console.error('Error fetching media:', error);
      toast.error('Failed to fetch media');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isOpen) {
      fetchMedia();
    }
  }, [isOpen, searchQuery]);

  useEffect(() => {
    if (!isOpen) {
      setSearchQuery('');
      setSelectedMedia(null);
      setSelectedMediaList([]);
      setAltText('');
      setCaption('');
    }
  }, [isOpen]);

  useEffect(() => {
    const onEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };

    if (isOpen) {
      window.addEventListener('keydown', onEsc);
    }

    return () => window.removeEventListener('keydown', onEsc);
  }, [isOpen, onClose]);

  // Upload handler
  const onDrop = async (acceptedFiles: File[]) => {
    if (acceptedFiles.length === 0) return;

    const file = acceptedFiles[0];
    setUploading(true);

    try {
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve, reject) => {
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64 = await base64Promise;

      const res = await fetch('/api/admin/media/upload', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          file: base64,
          filename: file.name,
          mimeType: file.type,
          folder: 'blog',
        }),
      });

      const data = await res.json();

      if (data.success && data.media) {
        toast.success('Image uploaded successfully');
        await fetchMedia();

        if (multiple) {
          setSelectedMediaList((prev) => {
            const exists = prev.find((m) => m._id === data.media._id);
            if (exists) return prev;
            return [data.media, ...prev];
          });
        } else {
          setSelectedMedia(data.media);
        }
      } else {
        toast.error(data.message || 'Failed to upload');
      }
    } catch (error) {
      console.error('Upload error:', error);
      toast.error('Failed to upload image');
    } finally {
      setUploading(false);
    }
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'image/*': ['.jpeg', '.jpg', '.png', '.webp', '.gif'],
    },
    maxSize: 10 * 1024 * 1024,
    multiple: false,
  });

  const selectedCount = multiple ? selectedMediaList.length : selectedMedia ? 1 : 0;

  const previewItem = multiple
    ? selectedMediaList[0] || null
    : selectedMedia;

  const toggleMediaSelection = (item: MediaItem) => {
    if (!multiple) {
      setSelectedMedia(item);
      return;
    }

    setSelectedMediaList((prev) => {
      const exists = prev.some((m) => m._id === item._id);
      if (exists) {
        return prev.filter((m) => m._id !== item._id);
      }
      return [...prev, item];
    });
  };

  const isSelected = (item: MediaItem) => {
    if (multiple) return selectedMediaList.some((m) => m._id === item._id);
    return selectedMedia?._id === item._id;
  };

  const handleSelect = () => {
    if (!multiple && selectedMedia) {
      onSelect({
        ...selectedMedia,
        alt: altText.trim(),
        caption: caption.trim(),
      });
      onClose();
      return;
    }

    if (multiple && selectedMediaList.length > 0) {
      onSelect(
        selectedMediaList.map((item) => ({
          ...item,
          alt: altText.trim(),
          caption: caption.trim(),
        }))
      );
      onClose();
    }
  };

  const clearSelection = () => {
    setSelectedMedia(null);
    setSelectedMediaList([]);
    setAltText('');
    setCaption('');
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        key="media-modal-overlay"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        onClick={onClose}
      >
        <motion.div
          key="media-modal-content"
          initial={{ scale: 0.96, opacity: 0, y: 12 }}
          animate={{ scale: 1, opacity: 1, y: 0 }}
          exit={{ scale: 0.96, opacity: 0, y: 12 }}
          transition={{ duration: 0.2 }}
          className="bg-white rounded-3xl w-full max-w-6xl max-h-[92vh] overflow-hidden flex flex-col shadow-2xl"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-5 border-b border-gray-200 bg-white">
            <div>
              <h3 className="text-xl font-semibold text-gray-900">{title}</h3>
              <p className="text-sm text-gray-500 mt-1">
                {multiple
                  ? 'Select one or more images for your gallery'
                  : 'Select a featured image or insert an image into your content'}
              </p>
            </div>

            <button
              onClick={onClose}
              className="p-2 hover:bg-gray-100 rounded-xl transition-colors"
            >
              <X className="w-5 h-5 text-gray-500" />
            </button>
          </div>

          {/* Controls */}
          <div className="px-6 py-4 border-b border-gray-200 bg-gray-50/70">
            <div className="flex flex-col lg:flex-row gap-4">
              {/* Search */}
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  type="text"
                  placeholder="Search by filename..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-2xl text-sm focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none bg-white"
                />
              </div>

              {/* Upload Zone Button */}
              <div
                {...getRootProps()}
                className={`rounded-2xl border-2 border-dashed transition-all cursor-pointer ${
                  isDragActive
                    ? 'border-[#029bba] bg-[#029bba]/5'
                    : 'border-gray-300 bg-white hover:border-[#029bba]/50'
                }`}
              >
                <input {...getInputProps()} />
                <div className="px-5 py-3 flex items-center gap-3 min-w-[220px]">
                  {uploading ? (
                    <RefreshCw className="w-5 h-5 animate-spin text-[#029bba]" />
                  ) : (
                    <Upload className="w-5 h-5 text-[#029bba]" />
                  )}
                  <div className="text-sm">
                    <div className="font-medium text-gray-900">
                      {uploading ? 'Uploading...' : isDragActive ? 'Drop image here' : 'Upload image'}
                    </div>
                    <div className="text-gray-500 text-xs">PNG, JPG, WEBP, GIF • up to 10MB</div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Body */}
          <div className="flex-1 overflow-hidden grid lg:grid-cols-12">
            {/* Media Grid */}
            <div className="lg:col-span-8 border-r border-gray-200 overflow-y-auto p-6">
              {loading ? (
                <div className="flex items-center justify-center py-16">
                  <RefreshCw className="w-8 h-8 text-[#029bba] animate-spin" />
                </div>
              ) : media.length === 0 ? (
                <div className="text-center py-16">
                  <div className="w-16 h-16 rounded-2xl bg-gray-100 flex items-center justify-center mx-auto mb-4">
                    <ImageIcon className="w-8 h-8 text-gray-300" />
                  </div>
                  <p className="text-gray-700 font-medium">No images found</p>
                  <p className="text-sm text-gray-400 mt-1">
                    Try searching differently or upload a new image.
                  </p>
                </div>
              ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                  {media.map((item) => {
                    const selected = isSelected(item);

                    return (
                      <button
                        type="button"
                        key={item._id}
                        onClick={() => toggleMediaSelection(item)}
                        className={`group relative rounded-2xl overflow-hidden border-2 transition-all text-left ${
                          selected
                            ? 'border-[#029bba] ring-2 ring-[#029bba]/20'
                            : 'border-transparent hover:border-gray-300'
                        }`}
                      >
                        <div className="aspect-square bg-gray-100 overflow-hidden">
                          <img
                            src={item.url}
                            alt={item.originalName}
                            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                          />
                        </div>

                        <div className="p-3 bg-white">
                          <p className="text-xs font-medium text-gray-800 line-clamp-1">
                            {item.originalName}
                          </p>
                          <div className="mt-1 text-[11px] text-gray-500 flex items-center justify-between">
                            <span>{item.format?.toUpperCase()}</span>
                            <span>{formatFileSize(item.size)}</span>
                          </div>
                        </div>

                        {selected && (
                          <div className="absolute inset-0 bg-[#029bba]/15 flex items-start justify-end p-3">
                            <div className="w-8 h-8 rounded-full bg-[#029bba] flex items-center justify-center shadow-md">
                              <Check className="w-5 h-5 text-white" />
                            </div>
                          </div>
                        )}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Preview Panel */}
            <div className="lg:col-span-4 overflow-y-auto p-6 bg-gray-50/50">
              <div className="flex items-center justify-between mb-4">
                <h4 className="font-semibold text-gray-900">Selection Details</h4>
                {selectedCount > 0 && (
                  <button
                    type="button"
                    onClick={clearSelection}
                    className="text-sm text-gray-500 hover:text-red-500 transition-colors"
                  >
                    Clear
                  </button>
                )}
              </div>

              {selectedCount === 0 ? (
                <div className="rounded-2xl border border-dashed border-gray-300 bg-white p-8 text-center">
                  <div className="w-14 h-14 rounded-2xl bg-gray-100 flex items-center justify-center mx-auto mb-4">
                    <Info className="w-6 h-6 text-gray-400" />
                  </div>
                  <p className="text-sm font-medium text-gray-700">No image selected</p>
                  <p className="text-xs text-gray-500 mt-2">
                    Choose an image from the library or upload a new one.
                  </p>
                </div>
              ) : (
                <div className="space-y-5">
                  <div className="rounded-2xl overflow-hidden bg-white border border-gray-200">
                    {previewItem ? (
                      <img
                        src={previewItem.url}
                        alt={previewItem.originalName}
                        className="w-full h-56 object-cover"
                      />
                    ) : null}
                  </div>

                  {previewItem && (
                    <div className="bg-white rounded-2xl border border-gray-200 p-4 space-y-3">
                      <div className="flex items-start gap-3">
                        <FileImage className="w-4 h-4 text-gray-400 mt-0.5" />
                        <div>
                          <p className="text-sm font-medium text-gray-900 break-all">
                            {previewItem.originalName}
                          </p>
                          <p className="text-xs text-gray-500 mt-1">
                            {previewItem.format?.toUpperCase()} • {formatFileSize(previewItem.size)}
                          </p>
                        </div>
                      </div>

                      <div className="flex items-start gap-3">
                        <Maximize2 className="w-4 h-4 text-gray-400 mt-0.5" />
                        <div className="text-sm text-gray-700">
                          {previewItem.width || '-'} × {previewItem.height || '-'} px
                        </div>
                      </div>

                      <div className="flex items-start gap-3">
                        <CheckCircle2 className="w-4 h-4 text-[#029bba] mt-0.5" />
                        <div className="text-sm text-gray-700">
                          {multiple
                            ? `${selectedCount} image(s) selected`
                            : 'Ready to insert'}
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Alt text */}
                  <div className="bg-white rounded-2xl border border-gray-200 p-4">
                    <label className="flex items-center gap-2 text-sm font-medium text-gray-800 mb-2">
                      <Type className="w-4 h-4 text-gray-400" />
                      Alt text
                    </label>
                    <input
                      type="text"
                      value={altText}
                      onChange={(e) => setAltText(e.target.value)}
                      placeholder="Describe the image for SEO and accessibility"
                      className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none"
                    />
                    <p className="text-xs text-gray-500 mt-2">
                      Helps search engines and screen readers understand the image.
                    </p>
                  </div>

                  {/* Caption */}
                  <div className="bg-white rounded-2xl border border-gray-200 p-4">
                    <label className="flex items-center gap-2 text-sm font-medium text-gray-800 mb-2">
                      <AlignLeft className="w-4 h-4 text-gray-400" />
                      Caption
                    </label>
                    <textarea
                      value={caption}
                      onChange={(e) => setCaption(e.target.value)}
                      rows={3}
                      placeholder="Optional image caption..."
                      className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none resize-none"
                    />
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Footer */}
          <div className="px-6 py-4 border-t border-gray-200 bg-white flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="text-sm text-gray-500">
              {selectedCount > 0 ? (
                <span>
                  Selected <strong>{selectedCount}</strong> item{selectedCount > 1 ? 's' : ''}
                </span>
              ) : (
                <span>No image selected</span>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={onClose}
                className="px-4 py-2.5 border border-gray-200 text-gray-700 rounded-xl font-medium hover:bg-gray-50 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleSelect}
                disabled={selectedCount === 0}
                className="px-5 py-2.5 bg-[#029bba] hover:bg-[#027a94] text-white rounded-xl font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {multiple ? 'Insert Selected Images' : 'Select Image'}
              </button>
            </div>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}

// components/admin/campaigns/ABTestPanel.tsx
// A/B Subject Line Testing Panel for MissionControl
// Lets admin configure variant B subject + split %

'use client';

import React, { useState } from 'react';
import {
  FlaskConical,
  ChevronDown,
  ChevronUp,
  Info,
  Trophy,
  Percent,
  Type,
  Eye,
  AlertCircle,
} from 'lucide-react';

// ─── Types ────────────────────────────────────────────────────

export interface ABTestConfig {
  enabled:           boolean;
  variantBSubject:   string;
  variantBPreview:   string;
  splitPercent:      number;
  winnerMetric:      'open_rate' | 'click_rate';
  testDurationHours: number;
}

interface ABTestPanelProps {
  subjectA:  string;        // The main subject from campaign form
  config:    ABTestConfig;
  onChange:  (config: ABTestConfig) => void;
}

export function getDefaultABConfig(): ABTestConfig {
  return {
    enabled:           false,
    variantBSubject:   '',
    variantBPreview:   '',
    splitPercent:      50,
    winnerMetric:      'open_rate',
    testDurationHours: 24,
  };
}

// ─── Component ────────────────────────────────────────────────

const ABTestPanel: React.FC<ABTestPanelProps> = ({
  subjectA,
  config,
  onChange,
}) => {
  const [expanded, setExpanded] = useState(false);

  const update = (partial: Partial<ABTestConfig>) => {
    onChange({ ...config, ...partial });
  };

  const toggle = () => {
    if (!config.enabled) {
      // Enable + expand
      update({ enabled: true });
      setExpanded(true);
    } else {
      // Disable + reset
      onChange(getDefaultABConfig());
      setExpanded(false);
    }
  };

  const isReady = config.enabled && config.variantBSubject.trim().length >= 5;
  const isSameAsA = config.variantBSubject.trim() === subjectA.trim();

  return (
    <div className={`
      rounded-2xl border transition-all
      ${config.enabled
        ? 'border-purple-300 bg-purple-50/50'
        : 'border-gray-200 bg-white'
      }
    `}>

      {/* ── Header / Toggle ──────────────────────────────── */}
      <div
        className="flex items-center justify-between p-4 cursor-pointer"
        onClick={() => config.enabled && setExpanded(!expanded)}
      >
        <div className="flex items-center gap-3">
          <div className={`
            w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0
            ${config.enabled ? 'bg-purple-600' : 'bg-gray-100'}
          `}>
            <FlaskConical className={`w-4 h-4 ${config.enabled ? 'text-white' : 'text-gray-500'}`} />
          </div>
          <div>
            <p className="text-sm font-black text-[#004063] flex items-center gap-2">
              A/B Subject Test
              {config.enabled && isReady && (
                <span className="text-[10px] bg-purple-600 text-white px-2 py-0.5 rounded-full font-bold">
                  ACTIVE
                </span>
              )}
            </p>
            <p className="text-xs text-gray-500 mt-0.5">
              {config.enabled
                ? `${config.splitPercent}% → A · ${100 - config.splitPercent}% → B`
                : 'Test two subject lines to find the winner'
              }
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Toggle switch */}
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); toggle(); }}
            className={`
              relative w-11 h-6 rounded-full transition-colors flex-shrink-0
              ${config.enabled ? 'bg-purple-600' : 'bg-gray-300'}
            `}
            title={config.enabled ? 'Disable A/B test' : 'Enable A/B test'}
          >
            <div className={`
              absolute top-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform
              ${config.enabled ? 'left-0.5 translate-x-5' : 'left-0.5'}
            `} />
          </button>

          {/* Expand/collapse chevron (only when enabled) */}
          {config.enabled && (
            <div className="text-gray-400">
              {expanded
                ? <ChevronUp className="w-4 h-4" />
                : <ChevronDown className="w-4 h-4" />
              }
            </div>
          )}
        </div>
      </div>

      {/* ── Body (expanded when enabled) ─────────────────── */}
      {config.enabled && expanded && (
        <div className="px-4 pb-4 space-y-4 border-t border-purple-200 pt-4">

          {/* Variant A (read-only display) */}
          <div>
            <label className="text-xs font-black text-gray-700 uppercase tracking-wider 
                               flex items-center gap-1.5 mb-2">
              <span className="w-5 h-5 bg-[#029bba] text-white rounded-md text-[10px] 
                               font-black flex items-center justify-center">
                A
              </span>
              Variant A — Current Subject
            </label>
            <div className="px-3 py-2.5 rounded-xl border border-gray-200 bg-gray-50 
                            text-sm text-gray-700 font-semibold">
              {subjectA || (
                <span className="text-gray-400 font-normal italic">
                  Enter subject line above first
                </span>
              )}
            </div>
          </div>

          {/* Variant B input */}
          <div>
            <label className="text-xs font-black text-gray-700 uppercase tracking-wider 
                               flex items-center gap-1.5 mb-2">
              <span className="w-5 h-5 bg-purple-600 text-white rounded-md text-[10px] 
                               font-black flex items-center justify-center">
                B
              </span>
              Variant B — Alternative Subject
              <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={config.variantBSubject}
              onChange={(e) => update({ variantBSubject: e.target.value.slice(0, 200) })}
              placeholder="Try a different angle, emoji, or question..."
              maxLength={200}
              className={`
                w-full px-3 py-2.5 rounded-xl border outline-none text-sm
                focus:ring-2 focus:ring-purple-400/30 focus:border-purple-400
                ${isSameAsA && config.variantBSubject
                  ? 'border-amber-300 bg-amber-50'
                  : 'border-gray-300'
                }
              `}
            />
            <div className="flex items-center justify-between mt-1">
              <span className="text-xs text-gray-400">
                {config.variantBSubject.length}/200
              </span>
              {isSameAsA && config.variantBSubject && (
                <span className="text-xs text-amber-600 flex items-center gap-1 font-semibold">
                  <AlertCircle className="w-3 h-3" />
                  Same as Variant A — they must differ
                </span>
              )}
            </div>
          </div>

          {/* Variant B preview text (optional) */}
          <div>
            <label className="text-xs font-black text-gray-700 uppercase tracking-wider 
                               flex items-center gap-1.5 mb-2">
              <Eye className="w-3 h-3 text-gray-400" />
              Variant B Preview Text
              <span className="text-gray-400 font-normal normal-case">(optional)</span>
            </label>
            <input
              type="text"
              value={config.variantBPreview}
              onChange={(e) => update({ variantBPreview: e.target.value.slice(0, 300) })}
              placeholder="Different inbox snippet for variant B..."
              maxLength={300}
              className="w-full px-3 py-2.5 rounded-xl border border-gray-300 outline-none 
                         text-sm focus:ring-2 focus:ring-purple-400/30 focus:border-purple-400"
            />
          </div>

          {/* Split % slider */}
          <div>
            <label className="text-xs font-black text-gray-700 uppercase tracking-wider 
                               flex items-center gap-1.5 mb-3">
              <Percent className="w-3 h-3 text-gray-400" />
              Recipient Split
            </label>
            <div className="flex items-center gap-3">
              <span className="text-sm font-black text-[#029bba] w-12 text-center bg-[#029bba]/10 
                               px-2 py-1 rounded-lg flex-shrink-0">
                A {config.splitPercent}%
              </span>
              <input
                type="range"
                min={10}
                max={90}
                step={5}
                value={config.splitPercent}
                onChange={(e) => update({ splitPercent: parseInt(e.target.value, 10) })}
                className="flex-1 accent-purple-600"
              />
              <span className="text-sm font-black text-purple-600 w-12 text-center bg-purple-100 
                               px-2 py-1 rounded-lg flex-shrink-0">
                B {100 - config.splitPercent}%
