export type SaveStatus = 'idle' | 'saving' | 'saved' | 'error';

interface CommandBarProps {
  title:            string;
  onTitleChange:    (title: string) => void;
  saveStatus:       SaveStatus;
  lastSavedAt:      Date | null;
  canSend:          boolean;
  isSending:        boolean;
  isSaving:         boolean;
