        <div className="flex items-start justify-between gap-2">
          <p className="text-sm font-bold text-gray-900 leading-tight
                        line-clamp-1 flex-1">
            {property.title}
          </p>
          {isInserted ? (
            <span className="flex items-center gap-1 text-xs font-bold
