// ========== FILE: components/admin/campaigns/RecipientSourceSelector.tsx ==========
// 📬 ENTERPRISE RECIPIENT SOURCE SELECTOR — HIGHRISE.PK
// Beautiful 3-option toggle: Subscribers / Leads / Both
// ═══════════════════════════════════════════════════════════════
// FEATURES:
//   ✅ 3 source options with icons and descriptions
//   ✅ Visual card-based selection (not dropdown)
//   ✅ Live count display per source
//   ✅ Merge tags toggle
//   ✅ Animated selection indicator
//   ✅ Mobile responsive
//   ✅ Pro tips per source
// ═══════════════════════════════════════════════════════════════

'use client';

import React, { useEffect, useState } from 'react';
import {
  Mail,
  Users,
  Combine,
  Check,
  Sparkles,
  Info,
  Loader2,
  Tag,
} from 'lucide-react';

// ═══════════════════════════════════════════════════════════════
// 🎨 TYPES
// ═══════════════════════════════════════════════════════════════

export type RecipientSource = 'subscribers' | 'leads' | 'both';

interface SourceOption {
  id:          RecipientSource;
  label:       string;
  description: string;
  icon:        React.ReactNode;
  gradient:    string;
  iconBg:      string;
  proTip:      string;
}

interface RecipientSourceSelectorProps {
  source:            RecipientSource;
  onSourceChange:    (source: RecipientSource) => void;
  mergeTagsEnabled:  boolean;
  onMergeTagsChange: (enabled: boolean) => void;
}

interface SourceCounts {
  subscribers: number;
  leads:       number;
  both:        number;
}

// ═══════════════════════════════════════════════════════════════
// 🎨 SOURCE OPTIONS
// ═══════════════════════════════════════════════════════════════

const SOURCE_OPTIONS: SourceOption[] = [
  {
    id:          'subscribers',
    label:       'Newsletter Only',
    description: 'Verified opt-in subscribers only',
    icon:        <Mail className="w-5 h-5" />,
    gradient:    'from-[#029bba] to-[#004063]',
    iconBg:      'bg-[#029bba]/10 text-[#029bba]',
    proTip:      'Highest deliverability — verified consent',
  },
  {
    id:          'leads',
    label:       'Leads Only',
    description: 'CRM contacts with advanced filters',
    icon:        <Users className="w-5 h-5" />,
    gradient:    'from-purple-500 to-indigo-600',
    iconBg:      'bg-purple-100 text-purple-600',
    proTip:      'Apply filters for laser-targeted outreach',
  },
  {
    id:          'both',
    label:       'Subscribers + Leads',
    description: 'Combined list — duplicates auto-removed',
    icon:        <Combine className="w-5 h-5" />,
    gradient:    'from-emerald-500 to-teal-600',
    iconBg:      'bg-emerald-100 text-emerald-600',
    proTip:      'Maximum reach — deduplication ensures no double sends',
  },
];

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN COMPONENT
// ═══════════════════════════════════════════════════════════════

const RecipientSourceSelector: React.FC<RecipientSourceSelectorProps> = ({
  source,
  onSourceChange,
  mergeTagsEnabled,
  onMergeTagsChange,
}) => {
  const [counts,  setCounts]  = useState<SourceCounts | null>(null);
  const [loading, setLoading] = useState(true);

  // ─────────────────────────────────────────────
  // Fetch counts for all sources
  // ─────────────────────────────────────────────
  useEffect(() => {
    let cancelled = false;

    const fetchCounts = async () => {
      setLoading(true);
      try {
        // Fetch subscriber count
        const subRes = await fetch(
          '/api/newsletter/subscribers?status=active',
          { credentials: 'include' }
        );
        const subData = await subRes.json();
        const subCount = subData.success ? (subData.stats?.active || 0) : 0;

        // Fetch lead count (no filters)
        const leadRes = await fetch(
          '/api/newsletter/campaigns/recipients-preview',
          {
            method:      'POST',
            credentials: 'include',
            headers:     { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              source:    'leads',
              leadFilters: {},
              countOnly: true,
            }),
          }
        );
        const leadData = await leadRes.json();
        const leadCount = leadData.success ? (leadData.counts?.leads || 0) : 0;

        if (!cancelled) {
          setCounts({
            subscribers: subCount,
            leads:       leadCount,
            both:        subCount + leadCount,
          });
        }
      } catch {
        // Silent fail — counts not critical
        if (!cancelled) setCounts({ subscribers: 0, leads: 0, both: 0 });
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchCounts();
    return () => { cancelled = true; };
  }, []);

  // ─────────────────────────────────────────────
  // Get count for a source
  // ─────────────────────────────────────────────
  const getCount = (sourceId: RecipientSource): number | null => {
    if (!counts || loading) return null;
    return counts[sourceId];
  };

  const activeOption = SOURCE_OPTIONS.find((o) => o.id === source)!;

  return (
    <div className="rounded-2xl border border-gray-200 bg-white overflow-hidden">

      {/* ═══════════════════════════════════════════
          HEADER
          ═══════════════════════════════════════════ */}
      <div className="px-4 py-3 bg-gradient-to-br from-white to-gray-50
                      border-b border-gray-200">
        <div className="flex items-center gap-2">
          <Mail className="w-4 h-4 text-[#029bba]" />
          <h3 className="text-sm font-black text-[#004063]">
            Who Receives This Campaign
          </h3>
        </div>
        <p className="text-xs text-gray-500 mt-0.5 ml-6">
          Choose your target audience
        </p>
      </div>

      {/* ═══════════════════════════════════════════
          SOURCE OPTIONS (3 Cards)
          ═══════════════════════════════════════════ */}
      <div className="p-4 space-y-3">
        {SOURCE_OPTIONS.map((option) => {
          const isSelected = source === option.id;
          const count      = getCount(option.id);

          return (
            <button
              key={option.id}
              type="button"
              onClick={() => onSourceChange(option.id)}
              className={`
                w-full flex items-center gap-3 p-3 rounded-2xl 
                border-2 transition-all text-left
                ${isSelected
                  ? 'border-[#029bba] bg-[#029bba]/5 shadow-md shadow-[#029bba]/10'
                  : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                }
              `}
            >
              {/* Selection Indicator */}
              <div className={`
                w-5 h-5 rounded-full border-2 flex items-center 
                justify-center flex-shrink-0 transition-all
                ${isSelected
                  ? 'border-[#029bba] bg-[#029bba]'
                  : 'border-gray-300 bg-white'
                }
              `}>
                {isSelected && (
                  <div className="w-2 h-2 rounded-full bg-white" />
                )}
              </div>

              {/* Icon */}
              <div className={`
                w-10 h-10 rounded-xl flex items-center justify-center 
                flex-shrink-0 ${option.iconBg}
              `}>
                {option.icon}
              </div>

              {/* Info */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-sm font-black text-gray-900 truncate">
                    {option.label}
                  </p>
                  {/* Count Badge */}
                  <div className={`
                    flex-shrink-0 px-2.5 py-1 rounded-lg text-xs font-black
                    ${isSelected
                      ? 'bg-[#029bba] text-white'
                      : 'bg-gray-100 text-gray-600'
                    }
                  `}>
                    {loading ? (
                      <Loader2 className="w-3 h-3 animate-spin" />
                    ) : count !== null ? (
                      count.toLocaleString()
                    ) : (
                      '...'
                    )}
                  </div>
                </div>
                <p className="text-xs text-gray-500 mt-0.5">
                  {option.description}
                </p>
              </div>
            </button>
          );
        })}
      </div>

      {/* ═══════════════════════════════════════════
          PRO TIP FOR SELECTED SOURCE
          ═══════════════════════════════════════════ */}
      <div className="mx-4 mb-4 p-3 bg-[#029bba]/5 border 
                      border-[#029bba]/15 rounded-xl">
        <div className="flex items-start gap-2">
          <Info className="w-3.5 h-3.5 text-[#029bba] flex-shrink-0 mt-0.5" />
          <p className="text-xs text-gray-700">
            <strong className="text-[#004063]">
              {activeOption.label}:
            </strong>{' '}
            {activeOption.proTip}
          </p>
        </div>
      </div>

      {/* ═══════════════════════════════════════════
          MERGE TAGS TOGGLE
          ═══════════════════════════════════════════ */}
      <div className="px-4 pb-4 border-t border-gray-100 pt-4">
        <label className="flex items-start gap-3 cursor-pointer">

          {/* Toggle Switch */}
          <div className="relative flex-shrink-0 mt-0.5">
            <input
              type="checkbox"
              checked={mergeTagsEnabled}
              onChange={(e) => onMergeTagsChange(e.target.checked)}
              className="sr-only peer"
            />
            <div className="w-10 h-5 bg-gray-200 rounded-full 
                            peer-checked:bg-[#029bba] transition-colors" />
            <div className="absolute top-0.5 left-0.5 w-4 h-4 bg-white 
                            rounded-full shadow transition-transform 
                            peer-checked:translate-x-5" />
          </div>

          {/* Label */}
          <div className="flex-1">
            <div className="flex items-center gap-1.5">
              <Tag className="w-3.5 h-3.5 text-[#029bba]" />
              <p className="text-sm font-bold text-gray-900">
                Personalization Tags
              </p>
              <span className="px-1.5 py-0.5 bg-[#029bba]/10 text-[#029bba] 
                               text-[10px] font-black rounded uppercase tracking-wider">
                Recommended
              </span>
            </div>
            <p className="text-xs text-gray-500 mt-0.5">
              {mergeTagsEnabled
                ? 'Active — {{name}}, {{city}}, {{budget}} will be replaced per recipient'
                : 'Disabled — all recipients get identical email content'}
            </p>
          </div>
        </label>

        {/* Example when enabled */}
        {mergeTagsEnabled && (
          <div className="mt-3 p-3 bg-gray-50 rounded-xl border border-gray-200">
            <div className="flex items-center gap-1.5 mb-2">
              <Sparkles className="w-3.5 h-3.5 text-[#029bba]" />
              <p className="text-xs font-black text-gray-600 uppercase tracking-wider">
                Personalization Preview
              </p>
            </div>
            <div className="space-y-1.5">
              <div className="flex items-center gap-2 text-xs">
                <code className="text-[#029bba] font-mono bg-[#029bba]/10 
                                 px-1.5 py-0.5 rounded">
                  {'{{name}}'}
                </code>
                <span className="text-gray-400">→</span>
                <span className="text-gray-700 font-semibold">
                  "Ahmed Ali Khan"
                </span>
              </div>
              <div className="flex items-center gap-2 text-xs">
                <code className="text-[#029bba] font-mono bg-[#029bba]/10 
                                 px-1.5 py-0.5 rounded">
                  {'{{city}}'}
                </code>
                <span className="text-gray-400">→</span>
                <span className="text-gray-700 font-semibold">
                  "Karachi"
                </span>
              </div>
              <div className="flex items-center gap-2 text-xs">
                <code className="text-[#029bba] font-mono bg-[#029bba]/10 
                                 px-1.5 py-0.5 rounded">
                  {'{{budget}}'}
                </code>
                <span className="text-gray-400">→</span>
                <span className="text-gray-700 font-semibold">
                  "PKR 2 Crore - 5 Crore"
                </span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default RecipientSourceSelector;
// ========== END OF FILE ==========

// components/admin/campaigns/SaveTemplateModal.tsx
// 🏗️ SAVE AS TEMPLATE MODAL — HIGHRISE.PK
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   Modal that lets admin save current campaign content
//   as a reusable template for future campaigns.
//
// FEATURES:
//   ✅ Name + description + category + tags input
//   ✅ Subject + previewText pre-filled from campaign
//   ✅ Category picker with visual icons
//   ✅ Tag input (comma separated, max 10)
//   ✅ Content size preview
//   ✅ Duplicate name warning
//   ✅ Loading state during save
//   ✅ Inline validation (no external libs)
//   ✅ Body scroll lock
//   ✅ Backdrop blur
//   ✅ Escape key closes
//   ✅ Mobile responsive
//   ✅ No react-hot-toast — inline Banner
//   ✅ Tailwind CSS only
//   ✅ Lucide React icons only
// ═══════════════════════════════════════════════════════════════

import React, {
  useState,
  useEffect,
  useCallback,
  useRef,
} from 'react';
import {
  X,
  BookTemplate,
  Sparkles,
  Newspaper,
  Bell,
  TrendingUp,
  Megaphone,
  FileText,
  Tag,
  CheckCircle,
  AlertCircle,
  RefreshCw,
  Info,
} from 'lucide-react';
import type { TemplateCategory } from '@/models/CampaignTemplate';

// ═══════════════════════════════════════════════════════════════
// 🔐 TYPES
// ═══════════════════════════════════════════════════════════════

interface SaveTemplateModalProps {
  isOpen:      boolean;
  onClose:     () => void;
  onSaved:     (templateId: string, templateName: string) => void;
  // Pre-filled from current campaign
  subject:     string;
  previewText: string;
  content:     string;
}

interface CategoryOption {
  value:       TemplateCategory;
  label:       string;
  description: string;
  icon:        React.ReactNode;
  gradient:    string;
}

// ═══════════════════════════════════════════════════════════════
// 🔐 CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_NAME_LENGTH        = 100;
const MAX_DESCRIPTION_LENGTH = 300;
const MAX_TAG_LENGTH         = 50;
const MAX_TAGS_COUNT         = 10;

const CATEGORY_OPTIONS: CategoryOption[] = [
  {
    value:       'welcome',
    label:       'Welcome',
    description: 'Onboarding new subscribers',
    icon:        <Sparkles  className="w-4 h-4" />,
    gradient:    'from-emerald-500 to-teal-500',
  },
  {
    value:       'newsletter',
    label:       'Newsletter',
    description: 'Weekly / monthly updates',
    icon:        <Newspaper className="w-4 h-4" />,
    gradient:    'from-blue-500 to-cyan-500',
  },
  {
    value:       'property_alert',
    label:       'Property Alert',
    description: 'New listing notifications',
    icon:        <Bell      className="w-4 h-4" />,
    gradient:    'from-amber-500 to-orange-500',
  },
  {
    value:       'market_insights',
    label:       'Market Insights',
    description: 'Analysis & price trends',
    icon:        <TrendingUp className="w-4 h-4" />,
    gradient:    'from-purple-500 to-pink-500',
  },
  {
    value:       'promotion',
    label:       'Promotion',
    description: 'Offers & special deals',
    icon:        <Megaphone className="w-4 h-4" />,
    gradient:    'from-rose-500 to-red-500',
  },
  {
    value:       'announcement',
    label:       'Announcement',
    description: 'News & platform updates',
    icon:        <Megaphone className="w-4 h-4" />,
    gradient:    'from-[#029bba] to-[#004063]',
  },
  {
    value:       'custom',
    label:       'Custom',
    description: 'General purpose template',
    icon:        <FileText  className="w-4 h-4" />,
    gradient:    'from-gray-500 to-slate-600',
  },
];

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

function formatBytes(bytes: number): string {
  if (bytes < 1024)        return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
}

function parseTags(input: string): string[] {
  return input
    .split(/[,،\n]/)  // comma, Arabic comma, newline
    .map((t) => t.trim().slice(0, MAX_TAG_LENGTH))
    .filter((t) => t.length > 0)
    .slice(0, MAX_TAGS_COUNT);
}

// ═══════════════════════════════════════════════════════════════
// 🎨 SUB-COMPONENTS
// ═══════════════════════════════════════════════════════════════

// ─── Inline Banner ────────────────────────────────────────────

interface InlineBannerProps {
  type:    'error' | 'success' | 'info';
  message: string;
}

function InlineBanner({ type, message }: InlineBannerProps) {
  const styles = {
    error:   'bg-red-50     border-red-200     text-red-800',
    success: 'bg-emerald-50 border-emerald-200 text-emerald-800',
    info:    'bg-blue-50    border-blue-200    text-blue-800',
  };
  const icons = {
    error:   <AlertCircle  className="w-4 h-4 shrink-0 mt-0.5" />,
    success: <CheckCircle  className="w-4 h-4 shrink-0 mt-0.5" />,
    info:    <Info         className="w-4 h-4 shrink-0 mt-0.5" />,
  };
  return (
    <div className={`flex items-start gap-2 px-4 py-3 rounded-xl border text-sm ${styles[type]}`}>
      {icons[type]}
      <span>{message}</span>
    </div>
  );
}

// ─── Category Picker ──────────────────────────────────────────

interface CategoryPickerProps {
  selected: TemplateCategory;
  onChange: (cat: TemplateCategory) => void;
}

function CategoryPicker({ selected, onChange }: CategoryPickerProps) {
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
      {CATEGORY_OPTIONS.map((cat) => {
        const isSelected = cat.value === selected;
        return (
          <button
            key={cat.value}
            type="button"
            onClick={() => onChange(cat.value)}
            className={`
              flex flex-col items-center gap-2 p-3 rounded-xl border-2
              transition-all text-center
              ${isSelected
                ? 'border-[#029bba] bg-[#029bba]/5 shadow-sm'
                : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
              }
            `}
          >
            {/* Category icon with gradient bg */}
            <div className={`
              w-8 h-8 rounded-lg bg-gradient-to-br ${cat.gradient}
              flex items-center justify-center text-white
              ${isSelected ? 'shadow-md' : ''}
            `}>
              {cat.icon}
            </div>
            <div>
              <p className={`text-xs font-bold leading-tight ${
                isSelected ? 'text-[#029bba]' : 'text-gray-700'
              }`}>
                {cat.label}
              </p>
              <p className="text-[10px] text-gray-400 leading-tight mt-0.5 hidden sm:block">
                {cat.description}
              </p>
            </div>
          </button>
        );
      })}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN COMPONENT
// ═══════════════════════════════════════════════════════════════

export default function SaveTemplateModal({
  isOpen,
  onClose,
  onSaved,
  subject,
  previewText,
  content,
}: SaveTemplateModalProps) {

  // ─── Form state ───────────────────────────────────────────
  const [name,        setName]        = useState('');
  const [description, setDescription] = useState('');
  const [category,    setCategory]    = useState<TemplateCategory>('custom');
  const [tagInput,    setTagInput]    = useState('');
  const [isSaving,    setIsSaving]    = useState(false);
  const [error,       setError]       = useState('');
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  const nameInputRef = useRef<HTMLInputElement>(null);

  // ─── Content size ──────────────────────────────────────────
  const contentSizeBytes = Buffer.byteLength(content, 'utf8');
  const contentSizeLabel = formatBytes(contentSizeBytes);
  const isContentTooLarge = contentSizeBytes > 500_000;

  // ─── Body scroll lock ─────────────────────────────────────
  useEffect(() => {
    if (!isOpen) return;
    document.body.style.overflow = 'hidden';

    // Auto-focus name input
    setTimeout(() => nameInputRef.current?.focus(), 100);

    return () => { document.body.style.overflow = ''; };
  }, [isOpen]);

  // ─── Escape key ───────────────────────────────────────────
  useEffect(() => {
    if (!isOpen) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !isSaving) onClose();
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [isOpen, isSaving, onClose]);

  // ─── Reset form on open ───────────────────────────────────
  useEffect(() => {
    if (isOpen) {
      setName('');
      setDescription('');
      setCategory('custom');
      setTagInput('');
      setError('');
      setFieldErrors({});
    }
  }, [isOpen]);

  // ─── Validate ─────────────────────────────────────────────
  const validate = useCallback((): boolean => {
    const errors: Record<string, string> = {};

    if (!name.trim()) {
      errors.name = 'Template name is required';
    } else if (name.trim().length < 3) {
      errors.name = 'Name must be at least 3 characters';
    } else if (name.trim().length > MAX_NAME_LENGTH) {
      errors.name = `Name cannot exceed ${MAX_NAME_LENGTH} characters`;
    }

    if (!description.trim()) {
      errors.description = 'Description is required';
    } else if (description.trim().length < 10) {
      errors.description = 'Description must be at least 10 characters';
    }

    if (!content.trim()) {
      errors.content = 'Cannot save a template with empty content';
    }

    if (isContentTooLarge) {
      errors.content = 'Content exceeds 500KB limit';
    }

    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  }, [name, description, content, isContentTooLarge]);

  // ─── Save handler ─────────────────────────────────────────
  const handleSave = useCallback(async () => {
    setError('');
    if (!validate()) return;

    setIsSaving(true);

    try {
      const tags = parseTags(tagInput);

      const res = await fetch('/api/admin/campaign-templates', {
        method:      'POST',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name:        name.trim(),
          description: description.trim(),
          category,
          subject,
          previewText,
          content,
          tags,
        }),
      });

      const data = await res.json();

      if (data.success) {
        onSaved(data.template._id, data.template.name);
        onClose();
      } else {
        // Handle duplicate name (409)
        if (res.status === 409) {
          setFieldErrors((prev) => ({
            ...prev,
            name: data.message || 'A template with this name already exists',
          }));
        } else {
          setError(data.message || 'Failed to save template. Please try again.');
        }
      }
    } catch {
      setError('Network error. Please check your connection and try again.');
    } finally {
      setIsSaving(false);
    }
  }, [
    validate, name, description, category,
    subject, previewText, content, tagInput,
    onSaved, onClose,
  ]);

  if (!isOpen) return null;

  // ═════════════════════════════════════════════════════════
  // 🎨 RENDER
  // ═════════════════════════════════════════════════════════

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">

        {/* ── Header ── */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#029bba] to-[#004063] flex items-center justify-center">
              <BookTemplate className="w-5 h-5 text-white" />
            </div>
            <div>
              <h2 className="text-lg font-black text-[#004063]">
                Save as Template
              </h2>
              <p className="text-xs text-gray-400 mt-0.5">
                Reuse this campaign content in future campaigns
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            disabled={isSaving}
            className="p-2 rounded-xl text-gray-400 hover:text-gray-600 hover:bg-gray-100 transition-colors disabled:opacity-50"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* ── Body (scrollable) ── */}
        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">

          {/* Global error */}
          {error && <InlineBanner type="error" message={error} />}

          {/* Content too large warning */}
          {isContentTooLarge && (
            <InlineBanner
              type="error"
              message={`Content is too large (${contentSizeLabel}). Maximum is 500KB. Please reduce the email content before saving as template.`}
            />
          )}

          {/* Content size info */}
          {!isContentTooLarge && (
            <div className="flex items-center gap-2 px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl">
              <Info className="w-4 h-4 text-gray-400 shrink-0" />
              <p className="text-xs text-gray-500">
                Template content size: <strong className="text-gray-700">{contentSizeLabel}</strong>
                {' '}· Subject and preview text from current campaign will be pre-filled.
              </p>
            </div>
          )}

          {/* ── Template Name ── */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1.5">
              Template Name <span className="text-red-500">*</span>
            </label>
            <input
              ref={nameInputRef}
              type="text"
              value={name}
              onChange={(e) => {
                setName(e.target.value.slice(0, MAX_NAME_LENGTH));
                if (fieldErrors.name) {
                  setFieldErrors((prev) => ({ ...prev, name: '' }));
                }
              }}
              placeholder="e.g., Weekly Property Alert — Karachi"
              disabled={isSaving}
              className={`
                w-full px-4 py-2.5 rounded-xl border text-sm
                focus:outline-none focus:ring-2 focus:ring-[#029bba]/30
                focus:border-[#029bba] transition-all disabled:opacity-50
                ${fieldErrors.name
                  ? 'border-red-300 bg-red-50'
                  : 'border-gray-200'
                }
              `}
            />
            <div className="flex items-center justify-between mt-1">
              {fieldErrors.name
                ? <p className="text-xs text-red-500">{fieldErrors.name}</p>
                : <p className="text-xs text-gray-400">Give it a descriptive name you'll recognize later</p>
              }
              <p className="text-xs text-gray-400 shrink-0 ml-2">
                {name.length}/{MAX_NAME_LENGTH}
              </p>
            </div>
          </div>

          {/* ── Description ── */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1.5">
              Description <span className="text-red-500">*</span>
            </label>
            <textarea
              value={description}
              onChange={(e) => {
                setDescription(e.target.value.slice(0, MAX_DESCRIPTION_LENGTH));
                if (fieldErrors.description) {
                  setFieldErrors((prev) => ({ ...prev, description: '' }));
                }
              }}
              placeholder="e.g., Weekly newsletter template with property listings and market insights for Karachi subscribers"
              rows={3}
              disabled={isSaving}
              className={`
                w-full px-4 py-2.5 rounded-xl border text-sm resize-none
                focus:outline-none focus:ring-2 focus:ring-[#029bba]/30
                focus:border-[#029bba] transition-all disabled:opacity-50
                ${fieldErrors.description
                  ? 'border-red-300 bg-red-50'
                  : 'border-gray-200'
                }
              `}
            />
            <div className="flex items-center justify-between mt-1">
              {fieldErrors.description
                ? <p className="text-xs text-red-500">{fieldErrors.description}</p>
                : <p className="text-xs text-gray-400">Describe what this template is for</p>
              }
              <p className="text-xs text-gray-400 shrink-0 ml-2">
                {description.length}/{MAX_DESCRIPTION_LENGTH}
              </p>
            </div>
          </div>

          {/* ── Category ── */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-2">
              Category
            </label>
            <CategoryPicker
              selected={category}
              onChange={setCategory}
            />
            <p className="text-xs text-gray-400 mt-2">
              Categories help you find templates faster in the gallery
            </p>
          </div>

          {/* ── Tags ── */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1.5">
              <div className="flex items-center gap-1.5">
                <Tag className="w-3.5 h-3.5 text-gray-500" />
                Tags
                <span className="font-normal text-gray-400">(optional)</span>
              </div>
            </label>
            <input
              type="text"
              value={tagInput}
              onChange={(e) => setTagInput(e.target.value)}
              placeholder="karachi, weekly, property-alert  (comma separated)"
              disabled={isSaving}
              className="w-full px-4 py-2.5 rounded-xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#029bba]/30 focus:border-[#029bba] transition-all disabled:opacity-50"
            />
            <div className="flex items-center justify-between mt-1">
              <p className="text-xs text-gray-400">
                Separate tags with commas — max {MAX_TAGS_COUNT} tags
              </p>
              {tagInput && (
                <p className="text-xs text-gray-400 shrink-0 ml-2">
                  {parseTags(tagInput).length}/{MAX_TAGS_COUNT} tags
                </p>
              )}
            </div>

            {/* Tag preview pills */}
            {tagInput && parseTags(tagInput).length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-2">
                {parseTags(tagInput).map((tag) => (
                  <span
                    key={tag}
                    className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold bg-[#029bba]/10 text-[#029bba]"
                  >
                    <Tag className="w-2.5 h-2.5" />
                    {tag}
                  </span>
                ))}
              </div>
            )}
          </div>

          {/* ── What gets saved info box ── */}
          <div className="bg-blue-50 border border-blue-200 rounded-xl p-4">
            <p className="text-xs font-bold text-blue-800 mb-2">
              📦 What gets saved in this template:
            </p>
            <ul className="text-xs text-blue-700 space-y-1">
              <li className="flex items-center gap-1.5">
                <CheckCircle className="w-3 h-3 text-blue-500 shrink-0" />
                Full email content (HTML from editor)
              </li>
              <li className="flex items-center gap-1.5">
                <CheckCircle className="w-3 h-3 text-blue-500 shrink-0" />
                Subject line: {subject
                  ? <em className="font-semibold">"{subject.slice(0, 40)}{subject.length > 40 ? '...' : ''}"</em>
                  : <span className="text-blue-400">none</span>
                }
              </li>
              <li className="flex items-center gap-1.5">
                <CheckCircle className="w-3 h-3 text-blue-500 shrink-0" />
                Preview text: {previewText
                  ? <em className="font-semibold">"{previewText.slice(0, 40)}{previewText.length > 40 ? '...' : ''}"</em>
                  : <span className="text-blue-400">none</span>
                }
              </li>
            </ul>
          </div>

          {/* Content error */}
          {fieldErrors.content && (
            <InlineBanner type="error" message={fieldErrors.content} />
          )}

        </div>

        {/* ── Footer ── */}
        <div className="px-6 py-4 border-t border-gray-100 shrink-0 flex items-center justify-between gap-3">
          <button
            onClick={onClose}
            disabled={isSaving}
            className="px-5 py-2.5 rounded-xl text-sm font-semibold text-gray-600 hover:bg-gray-100 transition-colors disabled:opacity-50"
          >
            Cancel
          </button>

          <button
            onClick={handleSave}
            disabled={isSaving || isContentTooLarge || !name.trim() || !description.trim()}
            className="flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-bold text-white bg-[#029bba] hover:bg-[#0289a5] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isSaving
              ? <><RefreshCw className="w-4 h-4 animate-spin" />Saving...</>
              : <><BookTemplate className="w-4 h-4" />Save Template</>
            }
          </button>
        </div>

      </div>
    </div>
  );
}

// ========== FILE: components/admin/campaigns/SendConfirmModal.tsx ==========
// 🚀 ENTERPRISE SEND CONFIRMATION MODAL — HIGHRISE.PK
// Beautiful send confirmation with test email flow
// ═══════════════════════════════════════════════════════════════
// FEATURES:
//   ✅ 2-step confirmation flow (Review → Confirm)
//   ✅ Test email sending inline
//   ✅ Test email validation
//   ✅ Multiple test emails (comma-separated)
//   ✅ Campaign summary display
//   ✅ Recipient count prominence
//   ✅ Send/Schedule mode toggle
//   ✅ Schedule date picker
//   ✅ Pre-send checklist (final review)
//   ✅ Warning banner (irreversible action)
//   ✅ Loading states with progress
//   ✅ Success/error inline banners
//   ✅ Body scroll lock
//   ✅ ESC key closes
//   ✅ Click outside closes
//   ✅ Beautiful animations
// ═══════════════════════════════════════════════════════════════

'use client';

import React, { useEffect, useState } from 'react';
import {
  X,
  Mail,
  Send,
  Calendar,
  AlertCircle,
  CheckCircle,
  Loader2,
  Users,
  Clock,
  Eye,
  Rocket,
  Shield,
  ArrowLeft,
  ArrowRight,
} from 'lucide-react';

// ═══════════════════════════════════════════════════════════════
// 🎨 TYPES
// ═══════════════════════════════════════════════════════════════

interface SendConfirmModalProps {
  isOpen:           boolean;
  onClose:          () => void;
  onSend:           (scheduleDate?: string) => Promise<void>;
  onTest:           (emails: string[]) => Promise<{ success: boolean; message: string }>;
  campaignTitle:    string;
  campaignSubject:  string;
  fromName:         string;
  fromEmail:        string;
  recipientCount:   number;
  isSending:        boolean;
}

type Step = 'review' | 'confirm';

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

const EMAIL_REGEX = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{1,63}$/;

function parseEmails(input: string): string[] {
  return input
    .split(/[,;\n]/)
    .map((e) => e.trim().toLowerCase())
    .filter((e) => e.length > 0);
}

function validateEmails(emails: string[]): { valid: string[]; invalid: string[] } {
  const valid: string[] = [];
  const invalid: string[] = [];

  emails.forEach((email) => {
    if (EMAIL_REGEX.test(email)) {
      valid.push(email);
    } else {
      invalid.push(email);
    }
  });

  return { valid, invalid };
}

function getMinScheduleDate(): string {
  const now = new Date();
  now.setMinutes(now.getMinutes() + 15); // Minimum 15 minutes in future
  now.setSeconds(0, 0);
  return now.toISOString().slice(0, 16);
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN COMPONENT
// ═══════════════════════════════════════════════════════════════

const SendConfirmModal: React.FC<SendConfirmModalProps> = ({
  isOpen,
  onClose,
  onSend,
  onTest,
  campaignTitle,
  campaignSubject,
  fromName,
  fromEmail,
  recipientCount,
  isSending,
}) => {

  // ═══════════════════════════════════════════════════════════
  // STATE
  // ═══════════════════════════════════════════════════════════
  const [step,           setStep]           = useState<Step>('review');
  const [testEmails,     setTestEmails]     = useState('');
  const [isTestSending,  setIsTestSending]  = useState(false);
  const [testResult,     setTestResult]     = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  const [sendMode,       setSendMode]       = useState<'now' | 'schedule'>('now');
  const [scheduleDate,   setScheduleDate]   = useState('');
  const [scheduleError,  setScheduleError]  = useState<string | null>(null);
  const [checklistState, setChecklistState] = useState({
    reviewed:   false,
    tested:     false,
    understood: false,
  });

  // ═══════════════════════════════════════════════════════════
  // EFFECTS
  // ═══════════════════════════════════════════════════════════

  // Reset state when modal opens/closes
  useEffect(() => {
    if (isOpen) {
      setStep('review');
      setTestResult(null);
      setScheduleError(null);
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  // Escape key handler
  useEffect(() => {
    if (!isOpen) return;
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !isSending) onClose();
    };
    document.addEventListener('keydown', handleEsc);
    return () => document.removeEventListener('keydown', handleEsc);
  }, [isOpen, isSending, onClose]);

  // ═══════════════════════════════════════════════════════════
  // HANDLERS
  // ═══════════════════════════════════════════════════════════

  const handleTestSend = async () => {
    setTestResult(null);
    const parsed = parseEmails(testEmails);

    if (parsed.length === 0) {
      setTestResult({
        type:    'error',
        message: 'Please enter at least one email address',
      });
      return;
    }

    if (parsed.length > 5) {
      setTestResult({
        type:    'error',
        message: 'Maximum 5 test emails allowed at once',
      });
      return;
    }

    const { valid, invalid } = validateEmails(parsed);

    if (invalid.length > 0) {
      setTestResult({
        type:    'error',
        message: `Invalid email${invalid.length > 1 ? 's' : ''}: ${invalid.slice(0, 3).join(', ')}`,
      });
      return;
    }

    setIsTestSending(true);
    try {
      const result = await onTest(valid);
      setTestResult({
        type:    result.success ? 'success' : 'error',
        message: result.message,
      });
      if (result.success) {
        setChecklistState((prev) => ({ ...prev, tested: true }));
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to send test';
      setTestResult({ type: 'error', message: msg });
    } finally {
      setIsTestSending(false);
    }
  };

  const handleProceedToConfirm = () => {
    if (sendMode === 'schedule') {
      if (!scheduleDate) {
        setScheduleError('Please select a date and time');
        return;
      }
      const scheduled = new Date(scheduleDate);
      if (scheduled.getTime() <= Date.now() + 10 * 60 * 1000) {
        setScheduleError('Schedule must be at least 15 minutes in the future');
        return;
      }
      setScheduleError(null);
    }
    setStep('confirm');
  };

  const handleFinalSend = async () => {
    try {
      await onSend(sendMode === 'schedule' ? scheduleDate : undefined);
      // Modal will close from parent
    } catch (err) {
      // Error handled by parent
    }
  };

  const allChecklistComplete =
    checklistState.reviewed &&
    checklistState.tested &&
    checklistState.understood;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/50 backdrop-blur-sm"
        onClick={() => !isSending && onClose()}
      />

      {/* Modal */}
      <div className="relative min-h-screen flex items-start 
                      justify-center p-4 py-8">
        <div className="relative bg-white rounded-3xl shadow-2xl 
                        w-full max-w-2xl">

          {/* ═══════════════════════════════════════════
              HEADER
              ═══════════════════════════════════════════ */}
          <div className="sticky top-0 bg-white border-b border-gray-200 
                          px-6 py-4 rounded-t-3xl flex items-center 
                          justify-between z-10">
            <div className="flex items-center gap-3">
              <div className={`w-10 h-10 rounded-xl flex items-center 
                               justify-center ${
                                 step === 'confirm'
                                   ? 'bg-gradient-to-br from-emerald-500 to-teal-600 text-white'
                                   : 'bg-gradient-to-br from-[#029bba] to-[#004063] text-white'
                               }`}>
                {step === 'confirm' ? (
                  <Rocket className="w-5 h-5" />
                ) : (
                  <Send className="w-5 h-5" />
                )}
              </div>
              <div>
                <h2 className="text-lg font-black text-[#004063]">
                  {step === 'confirm' ? 'Final Confirmation' : 'Ready to Send'}
                </h2>
                <p className="text-xs text-gray-500">
                  {step === 'confirm'
                    ? 'Last chance to review before sending'
                    : 'Review campaign details and send test email'}
                </p>
              </div>
            </div>
            <button
              type="button"
              onClick={() => !isSending && onClose()}
              disabled={isSending}
              className="p-2 hover:bg-gray-100 rounded-xl transition-colors 
                         disabled:opacity-40"
            >
              <X className="w-5 h-5 text-gray-500" />
            </button>
          </div>

          {/* ═══════════════════════════════════════════
              STEP INDICATOR
              ═══════════════════════════════════════════ */}
          <div className="px-6 py-3 border-b border-gray-100 bg-gray-50">
            <div className="flex items-center gap-2">
              <div className={`flex items-center gap-2 ${
                step === 'review' ? 'text-[#029bba]' : 'text-emerald-600'
              }`}>
                <div className={`w-6 h-6 rounded-full flex items-center 
                                 justify-center text-xs font-black 
                                 ${
                                   step === 'review'
                                     ? 'bg-[#029bba] text-white'
                                     : 'bg-emerald-500 text-white'
                                 }`}>
                  {step === 'confirm' ? <CheckCircle className="w-3.5 h-3.5" /> : '1'}
                </div>
                <span className="text-xs font-bold">Review & Test</span>
              </div>

              <div className={`flex-1 h-0.5 ${
                step === 'confirm' ? 'bg-emerald-500' : 'bg-gray-200'
              }`} />

              <div className={`flex items-center gap-2 ${
                step === 'confirm' ? 'text-[#029bba]' : 'text-gray-400'
              }`}>
                <div className={`w-6 h-6 rounded-full flex items-center 
                                 justify-center text-xs font-black 
                                 ${
                                   step === 'confirm'
                                     ? 'bg-[#029bba] text-white'
                                     : 'bg-gray-200 text-gray-500'
                                 }`}>
                  2
                </div>
                <span className="text-xs font-bold">Confirm & Send</span>
              </div>
            </div>
          </div>

          {/* ═══════════════════════════════════════════
              CONTENT: STEP 1 — REVIEW
              ═══════════════════════════════════════════ */}
          {step === 'review' && (
            <div className="p-6 space-y-5">

              {/* Campaign Summary Card */}
              <div className="p-4 bg-gradient-to-br from-gray-50 to-white 
                              rounded-2xl border border-gray-200">
                <p className="text-xs font-black text-gray-500 uppercase 
                              tracking-wider mb-3">
                  Campaign Summary
                </p>
                <div className="space-y-2.5">
                  <div className="flex items-start gap-2">
                    <span className="text-xs font-semibold text-gray-500 
                                     min-w-[80px]">Title:</span>
                    <span className="text-sm font-bold text-gray-900 flex-1">
                      {campaignTitle || 'Untitled'}
                    </span>
                  </div>
                  <div className="flex items-start gap-2">
                    <span className="text-xs font-semibold text-gray-500 
                                     min-w-[80px]">Subject:</span>
                    <span className="text-sm text-gray-900 flex-1">
                      {campaignSubject}
                    </span>
                  </div>
                  <div className="flex items-start gap-2">
                    <span className="text-xs font-semibold text-gray-500 
                                     min-w-[80px]">From:</span>
                    <span className="text-sm text-gray-900 flex-1">
                      {fromName} &lt;{fromEmail}&gt;
                    </span>
                  </div>
                  <div className="flex items-start gap-2 pt-2 border-t border-gray-200">
                    <span className="text-xs font-semibold text-gray-500 
                                     min-w-[80px]">Recipients:</span>
                    <span className="flex items-center gap-1.5">
                      <Users className="w-4 h-4 text-[#029bba]" />
                      <span className="text-lg font-black text-[#029bba]">
                        {recipientCount.toLocaleString()}
                      </span>
                      <span className="text-xs text-gray-500 font-semibold">
                        active subscribers
                      </span>
                    </span>
                  </div>
                </div>
              </div>

              {/* Test Email Section */}
              <div>
                <label className="flex text-sm font-black text-[#004063] 
                                  mb-2 items-center gap-2">
                  <Mail className="w-4 h-4 text-[#029bba]" />
                  Send Test Email First
                  <span className="text-xs font-normal text-gray-500">
                    (highly recommended)
                  </span>
                </label>

                <div className="flex gap-2">
                  <input
                    type="text"
                    value={testEmails}
                    onChange={(e) => setTestEmails(e.target.value)}
                    placeholder="your@email.com, colleague@email.com"
                    disabled={isTestSending}
                    className="flex-1 px-3 py-2 rounded-xl border border-gray-300 
                               focus:ring-2 focus:ring-[#029bba]/20 
                               focus:border-[#029bba] outline-none text-sm 
                               disabled:opacity-50"
                  />
                  <button
                    type="button"
                    onClick={handleTestSend}
                    disabled={isTestSending || !testEmails.trim()}
                    className="px-4 py-2 rounded-xl bg-[#029bba] hover:bg-[#027a94] 
                               text-white font-semibold text-sm transition-colors 
                               disabled:opacity-50 disabled:cursor-not-allowed 
                               flex items-center gap-1.5 flex-shrink-0"
                  >
                    {isTestSending ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Send className="w-4 h-4" />
                    )}
                    Send Test
                  </button>
                </div>
                <p className="text-xs text-gray-500 mt-1.5">
                  Separate multiple emails with commas (max 5)
                </p>

                {/* Test Result Banner */}
                {testResult && (
                  <div className={`mt-3 p-3 rounded-xl flex items-start gap-2 
                                    ${
                                      testResult.type === 'success'
                                        ? 'bg-emerald-50 border border-emerald-200'
                                        : 'bg-red-50 border border-red-200'
                                    }`}>
                    {testResult.type === 'success' ? (
                      <CheckCircle className="w-4 h-4 text-emerald-600 
                                              flex-shrink-0 mt-0.5" />
                    ) : (
                      <AlertCircle className="w-4 h-4 text-red-600 
                                              flex-shrink-0 mt-0.5" />
                    )}
                    <p className={`text-xs font-semibold ${
                      testResult.type === 'success'
                        ? 'text-emerald-800'
                        : 'text-red-800'
                    }`}>
                      {testResult.message}
                    </p>
                  </div>
                )}
              </div>

              {/* Send Mode Toggle */}
              <div>
                <label className="flex text-sm font-black text-[#004063] 
                                  mb-2 items-center gap-2">
                  <Clock className="w-4 h-4 text-[#029bba]" />
                  When to Send
                </label>

                <div className="grid grid-cols-2 gap-2">
                  <button
                    type="button"
                    onClick={() => setSendMode('now')}
                    className={`p-3 rounded-xl border-2 transition-all text-left 
                                ${
                                  sendMode === 'now'
                                    ? 'border-[#029bba] bg-[#029bba]/5'
                                    : 'border-gray-200 hover:border-gray-300'
                                }`}
                  >
                    <div className="flex items-center gap-2 mb-1">
                      <Rocket className={`w-4 h-4 ${
                        sendMode === 'now' ? 'text-[#029bba]' : 'text-gray-400'
                      }`} />
                      <span className="text-sm font-bold text-gray-900">
                        Send Now
                      </span>
                    </div>
                    <p className="text-xs text-gray-500">
                      Send immediately
                    </p>
                  </button>

                  <button
                    type="button"
                    onClick={() => setSendMode('schedule')}
                    className={`p-3 rounded-xl border-2 transition-all text-left 
                                ${
                                  sendMode === 'schedule'
                                    ? 'border-[#029bba] bg-[#029bba]/5'
                                    : 'border-gray-200 hover:border-gray-300'
                                }`}
                  >
                    <div className="flex items-center gap-2 mb-1">
                      <Calendar className={`w-4 h-4 ${
                        sendMode === 'schedule' ? 'text-[#029bba]' : 'text-gray-400'
                      }`} />
                      <span className="text-sm font-bold text-gray-900">
                        Schedule
                      </span>
                    </div>
                    <p className="text-xs text-gray-500">
                      Send at specific time
                    </p>
                  </button>
                </div>

                {/* Schedule Date Input */}
                {sendMode === 'schedule' && (
                  <div className="mt-3">
                    <input
                      type="datetime-local"
                      value={scheduleDate}
                      onChange={(e) => {
                        setScheduleDate(e.target.value);
                        setScheduleError(null);
                      }}
                      min={getMinScheduleDate()}
                      className="w-full px-3 py-2 rounded-xl border border-gray-300 
                                 focus:ring-2 focus:ring-[#029bba]/20 
                                 focus:border-[#029bba] outline-none text-sm"
                    />
                    {scheduleError && (
                      <p className="text-xs text-red-600 mt-1 flex items-center gap-1">
                        <AlertCircle className="w-3 h-3" />
                        {scheduleError}
                      </p>
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* ═══════════════════════════════════════════
              CONTENT: STEP 2 — CONFIRM
              ═══════════════════════════════════════════ */}
          {step === 'confirm' && (
            <div className="p-6 space-y-5">

              {/* Warning Banner */}
              <div className="p-4 bg-gradient-to-br from-amber-50 to-orange-50 
                              border border-amber-200 rounded-2xl">
                <div className="flex items-start gap-3">
                  <AlertCircle className="w-5 h-5 text-amber-600 
                                          flex-shrink-0 mt-0.5" />
                  <div>
                    <p className="text-sm font-black text-amber-900 mb-1">
                      This action cannot be undone
                    </p>
                    <p className="text-xs text-amber-800">
                      Once sent, this email will reach{' '}
                      <strong>{recipientCount.toLocaleString()}</strong> subscribers 
                      and cannot be recalled.
                    </p>
                  </div>
                </div>
              </div>

              {/* Final Summary */}
              <div className="p-4 bg-gray-50 rounded-2xl border border-gray-200">
                <p className="text-xs font-black text-gray-500 uppercase 
                              tracking-wider mb-3">
                  Sending To
                </p>
                <div className="text-center">
                  <div className="text-4xl font-black text-[#029bba] mb-1">
                    {recipientCount.toLocaleString()}
                  </div>
                  <p className="text-sm text-gray-600 font-semibold">
                    active subscribers
                  </p>
                </div>

                {sendMode === 'schedule' && scheduleDate && (
                  <div className="mt-4 pt-4 border-t border-gray-200 text-center">
                    <p className="text-xs text-gray-500 mb-1">Scheduled for:</p>
                    <p className="text-sm font-bold text-[#004063]">
                      {new Date(scheduleDate).toLocaleString('en-PK', {
                        weekday: 'long',
                        year: 'numeric',
                        month: 'long',
                        day: 'numeric',
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </p>
                  </div>
                )}
              </div>

              {/* Final Checklist */}
              <div>
                <p className="text-xs font-black text-gray-500 uppercase 
                              tracking-wider mb-3">
                  Please Confirm
                </p>
                <div className="space-y-2">
                  <label className="flex items-start gap-3 cursor-pointer 
                                    p-3 rounded-xl hover:bg-gray-50 
                                    transition-colors">
                    <input
                      type="checkbox"
                      checked={checklistState.reviewed}
                      onChange={(e) => setChecklistState((prev) => ({
                        ...prev,
                        reviewed: e.target.checked,
                      }))}
                      className="mt-0.5 w-4 h-4 rounded border-gray-300 
                                 text-[#029bba] focus:ring-[#029bba]/20"
                    />
                    <div className="flex-1">
                      <p className="text-sm font-semibold text-gray-900">
                        I have reviewed the email content
                      </p>
                      <p className="text-xs text-gray-500">
                        Subject, content, links, and images look correct
                      </p>
                    </div>
                  </label>

                  <label className="flex items-start gap-3 cursor-pointer 
                                    p-3 rounded-xl hover:bg-gray-50 
                                    transition-colors">
                    <input
                      type="checkbox"
                      checked={checklistState.tested}
                      onChange={(e) => setChecklistState((prev) => ({
                        ...prev,
                        tested: e.target.checked,
                      }))}
                      className="mt-0.5 w-4 h-4 rounded border-gray-300 
                                 text-[#029bba] focus:ring-[#029bba]/20"
                    />
                    <div className="flex-1">
                      <p className="text-sm font-semibold text-gray-900">
                        I sent a test email and verified it
                      </p>
                      <p className="text-xs text-gray-500">
                        The email arrived in my inbox and displays correctly
                      </p>
                    </div>
                  </label>

                  <label className="flex items-start gap-3 cursor-pointer 
                                    p-3 rounded-xl hover:bg-gray-50 
                                    transition-colors">
                    <input
                      type="checkbox"
                      checked={checklistState.understood}
                      onChange={(e) => setChecklistState((prev) => ({
                        ...prev,
                        understood: e.target.checked,
                      }))}
                      className="mt-0.5 w-4 h-4 rounded border-gray-300 
                                 text-[#029bba] focus:ring-[#029bba]/20"
                    />
                    <div className="flex-1">
                      <p className="text-sm font-semibold text-gray-900">
                        I understand this action is irreversible
                      </p>
                      <p className="text-xs text-gray-500">
                        Sent emails cannot be recalled
                      </p>
                    </div>
                  </label>
                </div>
              </div>
            </div>
          )}

          {/* ═══════════════════════════════════════════
              FOOTER — Action Buttons
              ═══════════════════════════════════════════ */}
          <div className="sticky bottom-0 bg-white border-t border-gray-200 
                          px-6 py-4 rounded-b-3xl flex items-center 
                          justify-between gap-3">

            {step === 'review' ? (
              <>
                <button
                  type="button"
                  onClick={onClose}
                  disabled={isSending}
                  className="px-5 py-2.5 rounded-xl border border-gray-300 
                             text-gray-700 font-semibold hover:bg-gray-50 
                             transition-colors disabled:opacity-50"
                >
                  Cancel
                </button>
                <button
                  type="button"
                  onClick={handleProceedToConfirm}
                  className="flex items-center gap-2 px-5 py-2.5 rounded-xl 
                             bg-gradient-to-r from-[#029bba] to-[#004063] 
                             text-white font-black hover:shadow-lg 
                             hover:shadow-[#029bba]/20 transition-all"
                >
                  Continue
                  <ArrowRight className="w-4 h-4" />
                </button>
              </>
            ) : (
              <>
                <button
                  type="button"
                  onClick={() => setStep('review')}
                  disabled={isSending}
                  className="flex items-center gap-2 px-5 py-2.5 rounded-xl 
                             border border-gray-300 text-gray-700 
                             font-semibold hover:bg-gray-50 transition-colors 
                             disabled:opacity-50"
                >
                  <ArrowLeft className="w-4 h-4" />
                  Back
                </button>
                <button
                  type="button"
                  onClick={handleFinalSend}
                  disabled={!allChecklistComplete || isSending}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-xl 
                              font-black transition-all
                              ${
                                allChecklistComplete && !isSending
                                  ? 'bg-gradient-to-r from-emerald-500 to-teal-600 text-white hover:shadow-lg hover:shadow-emerald-500/20'
                                  : 'bg-gray-200 text-gray-400 cursor-not-allowed'
                              }`}
                >
                  {isSending ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      Sending...
                    </>
                  ) : sendMode === 'schedule' ? (
                    <>
                      <Calendar className="w-4 h-4" />
                      Schedule Campaign
                    </>
                  ) : (
                    <>
                      <Rocket className="w-4 h-4" />
                      Send to {recipientCount.toLocaleString()} Recipients
                    </>
                  )}
                </button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SendConfirmModal;
