interface ImportError {
  row:    number;
  email:  string;
  reason: string;
}

interface SkippedRow {
  row:    number;
  email:  string;
  reason: string;
}

interface ImportResult {
  imported:        number;
  skipped:         number;
  failed:          number;
  errors:          ImportError[];
  skipped_details: SkippedRow[];
  total_processed: number;
}

interface PreviewRow {
  [key: string]: string;
