/**
 * components/compare/CompareSuggestions.tsx
 *
 * "Smart Suggestions" section on /compare page.
 * Shows similar projects the user might want to add to comparison.
 *
 * FEATURES:
 *   ✅ Fetches from /api/compare/suggestions
 *   ✅ Uses ProjectListingCard (grid variant) for consistency
 *   ✅ Shows matching context ("Because you're comparing X + Y...")
 *   ✅ Auto-refreshes when compare items change
 *   ✅ Empty state if no matches
 *   ✅ Skeleton loading
 *   ✅ Hides when compare is full (4 items)
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  Sparkles,
  MapPin,
  Building2,
  TrendingUp,
  Loader2,
  ArrowRight,
} from 'lucide-react';

import ProjectListingCard from '@/components/projects/ProjectListingCard';
import { MAX_COMPARE_ITEMS, type ProjectListing } from '@/types/projects';
import type { CompareEntity } from '@/components/compare/CompareTable';

// ─── TYPES ───────────────────────────────────────────────────────────────────

export interface CompareSuggestionsProps {
  entities: CompareEntity[];
}

interface SuggestionsResponse {
  success:  boolean;
  projects: ProjectListing[];
  context?: {
    cities:     string[];
    categories: string[];
    natures:    string[];
    priceRange: { min: number | null; max: number | null };
    totalMatches: number;
    tierBreakdown: {
      tier1: number;
      tier2: number;
      tier3: number;
      tier4: number;
    };
  };
  error?: string;
}

// ─── HELPERS ─────────────────────────────────────────────────────────────────

function extractSuggestionCriteria(entities: CompareEntity[]) {
  const cities:     Set<string> = new Set();
  const categories: Set<string> = new Set();
  const natures:    Set<string> = new Set();
  const projectIds: string[]    = [];
  let minPrice: number | null = null;
  let maxPrice: number | null = null;

  for (const entity of entities) {
    const d = entity.data;

    if (d._id) projectIds.push(String(d._id));

    if (typeof d.city === 'string' && d.city) cities.add(d.city);

    if (entity.entityType === 'project') {
      if (typeof d.projectCategory === 'string' && d.projectCategory) {
        categories.add(d.projectCategory);
      }
      if (typeof d.projectNature === 'string' && d.projectNature) {
        natures.add(d.projectNature);
      }
      if (typeof d.minPrice === 'number' && d.minPrice > 0) {
        minPrice = minPrice === null ? d.minPrice : Math.min(minPrice, d.minPrice);
      }
      if (typeof d.maxPrice === 'number' && d.maxPrice > 0) {
        maxPrice = maxPrice === null ? d.maxPrice : Math.max(maxPrice, d.maxPrice);
      }
    } else {
      // Property: use price directly
      if (typeof d.price === 'number' && d.price > 0) {
        if (minPrice === null || d.price < minPrice) minPrice = d.price;
        if (maxPrice === null || d.price > maxPrice) maxPrice = d.price;
      }
    }
  }

  return {
    projectIds,
    cities:     Array.from(cities),
    categories: Array.from(categories),
    natures:    Array.from(natures),
    minPrice,
    maxPrice,
  };
}

// ─── SKELETON LOADER ─────────────────────────────────────────────────────────

function SuggestionSkeleton(): React.ReactElement {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {[1, 2, 3].map(i => (
        <div key={i}
             className="bg-white rounded-2xl border border-gray-100
                        shadow-sm overflow-hidden animate-pulse">
          <div className="aspect-[16/10] bg-gray-100" />
          <div className="p-4 space-y-3">
            <div className="h-3 bg-gray-100 rounded w-1/3" />
            <div className="h-4 bg-gray-200 rounded w-3/4" />
            <div className="h-3 bg-gray-100 rounded w-1/2" />
            <div className="h-4 bg-gray-200 rounded w-2/3" />
          </div>
        </div>
      ))}
    </div>
  );
}

// ─── CONTEXT BADGES ──────────────────────────────────────────────────────────

function ContextBadges({
  cities,
  categories,
  natures,
}: {
  cities:     string[];
  categories: string[];
  natures:    string[];
}): React.ReactElement | null {

  const hasAny = cities.length > 0 || categories.length > 0 || natures.length > 0;
  if (!hasAny) return null;

  return (
    <div className="flex flex-wrap items-center gap-2 mt-3">
      <span className="text-xs font-black text-gray-500 uppercase tracking-wider">
        🎯 Based on:
      </span>

      {natures.map(n => (
        <span key={`n-${n}`}
              className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full
                         bg-purple-50 border border-purple-200 text-purple-700
                         text-xs font-bold capitalize">
          <Building2 className="w-3 h-3" />
          {n.replace(/_/g, ' ')}
        </span>
      ))}

      {cities.map(c => (
        <span key={`c-${c}`}
              className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full
                         bg-[#029bba]/10 border border-[#029bba]/20 text-[#029bba]
                         text-xs font-bold">
          <MapPin className="w-3 h-3" />
          {c}
        </span>
      ))}

      {categories.slice(0, 2).map(cat => (
        <span key={`cat-${cat}`}
              className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full
                         bg-emerald-50 border border-emerald-200 text-emerald-700
                         text-xs font-bold capitalize">
          {cat.replace(/_/g, ' ')}
        </span>
      ))}
    </div>
  );
}

// ─── MAIN COMPONENT ──────────────────────────────────────────────────────────

export default function CompareSuggestions({
  entities,
}: CompareSuggestionsProps): React.ReactElement | null {

  const [suggestions, setSuggestions] = useState<ProjectListing[]>([]);
  const [context,     setContext]     = useState<SuggestionsResponse['context']>();
  const [loading,     setLoading]     = useState(false);
  const [error,       setError]       = useState<string | null>(null);

  // ── Fetch suggestions ─────────────────────────────────────────────────────
  const fetchSuggestions = useCallback(async () => {
    if (entities.length === 0) {
      setSuggestions([]);
      setContext(undefined);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const criteria = extractSuggestionCriteria(entities);

      const res = await fetch('/api/compare/suggestions', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify({
          ...criteria,
          limit: 6,
        }),
      });

      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }

      const data = await res.json() as SuggestionsResponse;

      if (data.success && Array.isArray(data.projects)) {
        setSuggestions(data.projects);
        setContext(data.context);
      } else {
        setSuggestions([]);
        setError(data.error || 'Failed to load suggestions');
      }
    } catch (err) {
      console.error('[CompareSuggestions] Fetch failed:', err);
      setSuggestions([]);
      setError('Unable to load suggestions right now');
    } finally {
      setLoading(false);
    }
  }, [entities]);

  useEffect(() => {
    void fetchSuggestions();
  }, [fetchSuggestions]);

  // ─── DON'T RENDER conditions ─────────────────────────────────────────────
  // Hide when compare is full (user can't add more)
  if (entities.length >= MAX_COMPARE_ITEMS) return null;

  // Hide when compare is empty (nothing to base suggestions on)
  if (entities.length === 0) return null;

  return (
    <section className="mt-10" aria-labelledby="suggestions-heading">

      {/* ═══ Header ═══ */}
      <div className="bg-gradient-to-br from-[#029bba]/5 to-emerald-50
                      rounded-2xl border border-[#029bba]/20 p-5 md:p-6 mb-6">
        <div className="flex items-start justify-between flex-wrap gap-3">
          <div className="flex-1">
            <div className="inline-flex items-center gap-2 mb-2">
              <div className="w-9 h-9 rounded-xl bg-white shadow-sm
                              flex items-center justify-center">
                <Sparkles className="w-4 h-4 text-[#029bba]" />
              </div>
              <h2 id="suggestions-heading"
                  className="text-lg md:text-xl font-black text-gray-900">
                Smart Suggestions
              </h2>
              <span className="inline-flex items-center gap-1 px-2 py-0.5
                               rounded-full bg-emerald-500 text-white
                               text-[9px] font-black uppercase tracking-wider">
                <TrendingUp className="w-2.5 h-2.5" />
                AI Powered
              </span>
            </div>

            <p className="text-sm text-gray-600 leading-relaxed">
              Similar top-rated projects that match your comparison criteria.
              Add any to instantly include in your comparison.
            </p>

            {context && !loading && (
              <ContextBadges
                cities={context.cities}
                categories={context.categories}
                natures={context.natures}
              />
            )}
          </div>

          {suggestions.length > 0 && !loading && (
            <div className="hidden md:flex items-center gap-1 text-xs
                            font-bold text-gray-500">
              <span>{suggestions.length}</span>
              <span>match{suggestions.length > 1 ? 'es' : ''} found</span>
            </div>
          )}
        </div>
      </div>

      {/* ═══ Loading Skeleton ═══ */}
      {loading && <SuggestionSkeleton />}

      {/* ═══ Error State ═══ */}
      {!loading && error && (
        <div className="bg-amber-50 border border-amber-200 rounded-2xl
                        p-6 text-center">
          <p className="text-sm font-bold text-amber-700 mb-2">
            ⚠️ {error}
          </p>
          <button
            type="button"
            onClick={() => void fetchSuggestions()}
            className="text-xs font-black text-amber-800 hover:underline"
          >
            Try again
          </button>
        </div>
      )}

      {/* ═══ Empty State (no matches) ═══ */}
      {!loading && !error && suggestions.length === 0 && (
        <div className="bg-white border border-gray-100 rounded-2xl
                        p-8 text-center">
          <div className="w-14 h-14 rounded-full bg-gray-50
                          flex items-center justify-center mx-auto mb-3">
            <Sparkles className="w-6 h-6 text-gray-300" />
          </div>
          <p className="text-sm font-bold text-gray-700 mb-1">
            No perfect matches yet
          </p>
          <p className="text-xs text-gray-500 mb-4 max-w-sm mx-auto">
            We couldn&apos;t find projects that closely match your comparison criteria.
            Try browsing more projects.
          </p>
          <a
            href="/projects"
            className="inline-flex items-center gap-1.5 px-4 py-2
                       rounded-xl bg-[#029bba] text-white
                       text-xs font-black hover:bg-[#017a94]
                       transition-colors"
          >
            Browse All Projects
            <ArrowRight className="w-3.5 h-3.5" />
          </a>
        </div>
      )}

      {/* ═══ Suggestions Grid ═══ */}
      {!loading && !error && suggestions.length > 0 && (
        <>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {suggestions.map(project => (
              <ProjectListingCard
                key={project._id}
                project={project}
                variant="grid"
              />
            ))}
          </div>

          {/* Bottom CTA */}
          <div className="mt-6 text-center">
            <a
              href="/projects"
              className="inline-flex items-center gap-2 px-6 py-3
                         rounded-xl bg-white border-2 border-[#029bba]
                         text-[#029bba] text-sm font-black
                         hover:bg-[#029bba]/5 hover:shadow-md
                         transition-all"
            >
              <Building2 className="w-4 h-4" />
              Explore More Projects
              <ArrowRight className="w-4 h-4" />
            </a>
          </div>
        </>
      )}

      {/* ═══ Loading indicator (subtle, non-blocking) ═══ */}
      {loading && (
        <div className="mt-4 text-center">
          <div className="inline-flex items-center gap-2 text-xs
                          font-semibold text-gray-500">
            <Loader2 className="w-3.5 h-3.5 animate-spin text-[#029bba]" />
            Finding similar projects...
          </div>
        </div>
      )}
    </section>
  );
}

// components/developer/ProjectStatsCard.tsx
import React from 'react';
import Link from 'next/link';
import {
  Building2,
  Home,
  TrendingUp,
  Eye,
  MessageSquare,
  Users,
  CheckCircle2,
  Clock,
  AlertTriangle,
  XCircle,
  ArrowRight,
  ArrowUpRight,
  ArrowDownRight,
  BarChart3,
  Target,
  DollarSign,
  Layers,
  PlusCircle,
} from 'lucide-react';

// ════════════════════════════════════════════════════
// TYPES
// ════════════════════════════════════════════════════

export interface ProjectStats {
  totalProjects:       number;
  activeProjects:      number;
  draftProjects:       number;
  pendingProjects:     number;
  verifiedProjects:    number;
  rejectedProjects:    number;
  totalUnits:          number;
  availableUnits:      number;
  soldUnits:           number;
  reservedUnits:       number;
  totalViews:          number;
  totalInquiries:      number;
  totalLeads:          number;
  conversionRate:      number;
  totalRevenue:        number;
  avgPrice:            number;
  viewsTrend?:         number;  // percentage change
  inquiriesTrend?:     number;
  leadsTrend?:         number;
}

export interface ProjectStatsCardProps {
  stats:      ProjectStats;
  variant?:   'full' | 'compact' | 'sidebar';
  className?: string;
}

// ════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════

function formatNumber(num: number): string {
  if (!num && num !== 0) return '0';
  if (num >= 10_000_000) {
    const crore = num / 10_000_000;
    return `${crore % 1 === 0 ? crore.toFixed(0) : crore.toFixed(1)} Cr`;
  }
  if (num >= 100_000) {
    const lac = num / 100_000;
    return `${lac % 1 === 0 ? lac.toFixed(0) : lac.toFixed(1)} L`;
  }
  if (num >= 1000) {
    return `${(num / 1000).toFixed(1)}K`;
  }
  return num.toLocaleString();
}

function formatPKR(amount: number): string {
  if (!amount || amount <= 0) return 'PKR 0';
  if (amount >= 10_000_000) {
    const crore = amount / 10_000_000;
    return `PKR ${crore % 1 === 0 ? crore.toFixed(0) : crore.toFixed(2)} Cr`;
  }
  if (amount >= 100_000) {
    const lac = amount / 100_000;
    return `PKR ${lac % 1 === 0 ? lac.toFixed(0) : lac.toFixed(1)} Lac`;
  }
  return `PKR ${amount.toLocaleString()}`;
}

function TrendIndicator({ value }: { value?: number }): React.ReactElement | null {
  if (value === undefined || value === null) return null;

  if (value > 0) {
    return (
      <span className="inline-flex items-center gap-0.5 text-xs font-semibold text-emerald-600">
        <ArrowUpRight className="w-3 h-3" />
        {Math.abs(value).toFixed(1)}%
      </span>
    );
  }

  if (value < 0) {
    return (
      <span className="inline-flex items-center gap-0.5 text-xs font-semibold text-red-500">
        <ArrowDownRight className="w-3 h-3" />
        {Math.abs(value).toFixed(1)}%
      </span>
    );
  }

  return (
    <span className="text-xs font-semibold text-gray-400">0%</span>
  );
}

// ════════════════════════════════════════════════════
// STAT CARD ITEM (reusable)
// ════════════════════════════════════════════════════

interface StatItemProps {
  label:     string;
  value:     string | number;
  icon:      React.ReactElement;
  iconBg:    string;
  iconColor: string;
  trend?:    number;
  href?:     string;
  subtitle?: string;
}

function StatItem({
  label,
  value,
  icon,
  iconBg,
  iconColor,
  trend,
  href,
  subtitle,
}: StatItemProps): React.ReactElement {
  const content = (
    <div className="flex items-center gap-3 p-3 rounded-xl bg-white border border-gray-100
                    hover:border-gray-200 hover:shadow-sm transition-all duration-200 group">
      {/* Icon */}
      <div
        className={`
          w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0
          ${iconBg} ${iconColor}
        `}
      >
        {icon}
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <p className="text-xs text-gray-400 font-semibold uppercase tracking-wide truncate">
          {label}
        </p>
        <div className="flex items-baseline gap-2 mt-0.5">
          <p className="text-lg font-black text-gray-900">
            {typeof value === 'number' ? formatNumber(value) : value}
          </p>
          <TrendIndicator value={trend} />
        </div>
        {subtitle && (
          <p className="text-[10px] text-gray-400 mt-0.5 truncate">
            {subtitle}
          </p>
        )}
      </div>

      {/* Arrow for linked items */}
      {href && (
        <ArrowRight className="w-4 h-4 text-gray-300 group-hover:text-[#029bba]
                               transition-colors flex-shrink-0" />
      )}
    </div>
  );

  if (href) {
    return <Link href={href} className="block">{content}</Link>;
  }

  return content;
}

// ════════════════════════════════════════════════════
// UNIT STATUS BAR
// ════════════════════════════════════════════════════

function UnitStatusBar({
  available,
  reserved,
  sold,
  total,
}: {
  available: number;
  reserved:  number;
  sold:      number;
  total:     number;
}): React.ReactElement {
  if (total === 0) return <></>;

  const availPct  = Math.round((available / total) * 100);
  const resvPct   = Math.round((reserved / total) * 100);
  const soldPct   = Math.round((sold / total) * 100);

  return (
    <div className="mt-3">
      <div className="flex justify-between text-xs mb-1.5">
        <span className="text-gray-500 font-medium">Unit Inventory</span>
        <span className="text-gray-700 font-bold">{total} Total</span>
      </div>

      {/* Stacked bar */}
      <div className="h-3 rounded-full bg-gray-100 overflow-hidden flex">
        {soldPct > 0 && (
          <div
            className="h-full bg-red-400 transition-all duration-500"
            style={{ width: `${soldPct}%` }}
          />
        )}
        {resvPct > 0 && (
          <div
            className="h-full bg-amber-400 transition-all duration-500"
            style={{ width: `${resvPct}%` }}
          />
        )}
        {availPct > 0 && (
          <div
            className="h-full bg-emerald-400 transition-all duration-500"
            style={{ width: `${availPct}%` }}
          />
        )}
      </div>

      {/* Legend */}
      <div className="flex items-center gap-4 mt-2">
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 rounded-full bg-emerald-400" />
          <span className="text-[10px] text-gray-500 font-medium">
            Available ({available})
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 rounded-full bg-amber-400" />
          <span className="text-[10px] text-gray-500 font-medium">
            Reserved ({reserved})
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-2.5 h-2.5 rounded-full bg-red-400" />
          <span className="text-[10px] text-gray-500 font-medium">
            Sold ({sold})
          </span>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════
// PROJECT STATUS PILLS
// ════════════════════════════════════════════════════

function ProjectStatusPills({
  stats,
}: {
  stats: ProjectStats;
}): React.ReactElement {
  const statusItems = [
    {
      label: 'Verified',
      count: stats.verifiedProjects,
      icon:  <CheckCircle2 className="w-3 h-3" />,
      bg:    'bg-emerald-100',
      text:  'text-emerald-700',
    },
    {
      label: 'Active',
      count: stats.activeProjects,
      icon:  <Building2 className="w-3 h-3" />,
      bg:    'bg-blue-100',
      text:  'text-blue-700',
    },
    {
      label: 'Pending',
      count: stats.pendingProjects,
      icon:  <Clock className="w-3 h-3" />,
      bg:    'bg-amber-100',
      text:  'text-amber-700',
    },
    {
      label: 'Draft',
      count: stats.draftProjects,
      icon:  <Layers className="w-3 h-3" />,
      bg:    'bg-gray-100',
      text:  'text-gray-600',
    },
    {
      label: 'Rejected',
      count: stats.rejectedProjects,
      icon:  <XCircle className="w-3 h-3" />,
      bg:    'bg-red-100',
      text:  'text-red-600',
    },
  ].filter((item) => item.count > 0);

  return (
    <div className="flex flex-wrap gap-2 mt-3">
      {statusItems.map((item) => (
        <span
          key={item.label}
          className={`
            inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full
            ${item.bg} ${item.text} text-xs font-semibold
          `}
        >
          {item.icon}
          {item.count} {item.label}
        </span>
      ))}
    </div>
  );
}

// ════════════════════════════════════════════════════
// SIDEBAR VARIANT
// ════════════════════════════════════════════════════

function SidebarStats({
  stats,
  className,
}: {
  stats:      ProjectStats;
  className?: string;
}): React.ReactElement {
  const soldPercentage = stats.totalUnits > 0
    ? Math.round((stats.soldUnits / stats.totalUnits) * 100)
    : 0;

  return (
    <div className={`space-y-3 ${className ?? ''}`}>
      {/* Key metrics */}
      <div className="grid grid-cols-2 gap-2">
        <div className="p-3 rounded-xl bg-white border border-gray-100 text-center">
          <p className="text-2xl font-black text-[#004063]">
            {stats.totalProjects}
          </p>
          <p className="text-[10px] text-gray-400 font-semibold uppercase tracking-wide mt-0.5">
            Projects
          </p>
        </div>
        <div className="p-3 rounded-xl bg-white border border-gray-100 text-center">
          <p className="text-2xl font-black text-[#029bba]">
            {stats.totalUnits}
          </p>
          <p className="text-[10px] text-gray-400 font-semibold uppercase tracking-wide mt-0.5">
            Total Units
          </p>
        </div>
        <div className="p-3 rounded-xl bg-white border border-gray-100 text-center">
          <p className="text-2xl font-black text-emerald-600">
            {soldPercentage}%
          </p>
          <p className="text-[10px] text-gray-400 font-semibold uppercase tracking-wide mt-0.5">
            Sold
          </p>
        </div>
        <div className="p-3 rounded-xl bg-white border border-gray-100 text-center">
          <p className="text-2xl font-black text-amber-600">
            {formatNumber(stats.totalLeads)}
          </p>
          <p className="text-[10px] text-gray-400 font-semibold uppercase tracking-wide mt-0.5">
            Leads
          </p>
        </div>
      </div>

      {/* Quick stats list */}
      <div className="space-y-2">
        <div className="flex items-center justify-between py-1.5 border-b border-gray-50">
          <span className="text-xs text-gray-500 flex items-center gap-1.5">
            <Eye className="w-3 h-3" /> Views
          </span>
          <span className="text-xs font-bold text-gray-700">
            {formatNumber(stats.totalViews)}
          </span>
        </div>
        <div className="flex items-center justify-between py-1.5 border-b border-gray-50">
          <span className="text-xs text-gray-500 flex items-center gap-1.5">
            <MessageSquare className="w-3 h-3" /> Inquiries
          </span>
          <span className="text-xs font-bold text-gray-700">
            {formatNumber(stats.totalInquiries)}
          </span>
        </div>
        <div className="flex items-center justify-between py-1.5 border-b border-gray-50">
          <span className="text-xs text-gray-500 flex items-center gap-1.5">
            <Target className="w-3 h-3" /> Conversion
          </span>
          <span className="text-xs font-bold text-gray-700">
            {stats.conversionRate.toFixed(1)}%
          </span>
        </div>
        <div className="flex items-center justify-between py-1.5">
          <span className="text-xs text-gray-500 flex items-center gap-1.5">
            <DollarSign className="w-3 h-3" /> Revenue
          </span>
          <span className="text-xs font-bold text-gray-700">
            {formatPKR(stats.totalRevenue)}
          </span>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════
// COMPACT VARIANT
// ════════════════════════════════════════════════════

function CompactStats({
  stats,
  className,
}: {
  stats:      ProjectStats;
  className?: string;
}): React.ReactElement {
  return (
    <div className={`bg-white rounded-2xl border border-gray-100 shadow-sm p-4 ${className ?? ''}`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-3">
        <h3 className="font-bold text-sm text-[#004063] flex items-center gap-2">
          <BarChart3 className="w-4 h-4 text-[#029bba]" />
          Quick Stats
        </h3>
        <Link
          href="/developer/analytics"
          className="text-xs font-semibold text-[#029bba] hover:underline
                     flex items-center gap-1"
        >
          View All <ArrowRight className="w-3 h-3" />
        </Link>
      </div>

      {/* Stat grid */}
      <div className="grid grid-cols-4 gap-3">
        <div className="text-center">
          <p className="text-xl font-black text-[#004063]">{stats.totalProjects}</p>
          <p className="text-[10px] text-gray-400 font-semibold mt-0.5">Projects</p>
        </div>
        <div className="text-center">
          <p className="text-xl font-black text-[#029bba]">{stats.totalUnits}</p>
          <p className="text-[10px] text-gray-400 font-semibold mt-0.5">Units</p>
        </div>
        <div className="text-center">
          <p className="text-xl font-black text-emerald-600">{formatNumber(stats.totalViews)}</p>
          <p className="text-[10px] text-gray-400 font-semibold mt-0.5">Views</p>
        </div>
        <div className="text-center">
          <p className="text-xl font-black text-amber-600">{formatNumber(stats.totalLeads)}</p>
          <p className="text-[10px] text-gray-400 font-semibold mt-0.5">Leads</p>
        </div>
      </div>

      {/* Unit bar */}
      <UnitStatusBar
        available={stats.availableUnits}
        reserved={stats.reservedUnits}
        sold={stats.soldUnits}
        total={stats.totalUnits}
      />
    </div>
  );
}

// ════════════════════════════════════════════════════
// FULL VARIANT (DEFAULT)
// ════════════════════════════════════════════════════

export default function ProjectStatsCard({
  stats,
  variant   = 'full',
  className = '',
}: ProjectStatsCardProps): React.ReactElement {
  // ── Sidebar variant ──
  if (variant === 'sidebar') {
    return <SidebarStats stats={stats} className={className} />;
  }

  // ── Compact variant ──
  if (variant === 'compact') {
    return <CompactStats stats={stats} className={className} />;
  }

  // ── Empty state ──
  if (stats.totalProjects === 0) {
    return (
      <div className={`bg-white rounded-2xl border border-gray-100 shadow-sm p-8 text-center ${className}`}>
        <Building2 className="w-12 h-12 text-gray-300 mx-auto mb-3" />
        <h3 className="font-bold text-lg text-gray-700 mb-1">
          Koi Project Nahi Hai
        </h3>
        <p className="text-sm text-gray-400 mb-4 max-w-sm mx-auto">
          Apna pehla project add karein aur yahan par sab stats dikhenge — views, leads, sales sab kuch.
        </p>
        <Link
          href="/developer/projects/new"
          className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl
                     bg-gradient-to-r from-[#029bba] to-[#027a94]
                     text-white font-semibold text-sm
                     hover:from-[#02a8c9] hover:to-[#028aaa]
                     hover:shadow-lg transition-all duration-200"
        >
          <PlusCircle className="w-4 h-4" />
          Add First Project
        </Link>
      </div>
    );
  }

  // ── Full variant ──
  return (
    <div className={`bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden ${className}`}>
      {/* Header */}
      <div className="px-5 pt-5 pb-3 border-b border-gray-50">
        <div className="flex items-center justify-between">
          <h3 className="font-bold text-base text-[#004063] flex items-center gap-2">
            <BarChart3 className="w-5 h-5 text-[#029bba]" />
            Project Overview
          </h3>
          <Link
            href="/developer/analytics"
            className="text-xs font-semibold text-[#029bba] hover:underline
                       flex items-center gap-1"
          >
            Detailed Analytics <ArrowRight className="w-3 h-3" />
          </Link>
        </div>

        {/* Project status pills */}
        <ProjectStatusPills stats={stats} />
      </div>

      {/* Stats grid */}
      <div className="p-5">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
          <StatItem
            label="Total Projects"
            value={stats.totalProjects}
            icon={<Building2 className="w-5 h-5" />}
            iconBg="bg-blue-50"
            iconColor="text-blue-600"
            href="/developer/projects"
          />
          <StatItem
            label="Total Units"
            value={stats.totalUnits}
            icon={<Home className="w-5 h-5" />}
            iconBg="bg-purple-50"
            iconColor="text-purple-600"
          />
          <StatItem
            label="Total Views"
            value={stats.totalViews}
            icon={<Eye className="w-5 h-5" />}
            iconBg="bg-cyan-50"
            iconColor="text-cyan-600"
            trend={stats.viewsTrend}
            subtitle="Last 30 days"
          />
          <StatItem
            label="Inquiries"
            value={stats.totalInquiries}
            icon={<MessageSquare className="w-5 h-5" />}
            iconBg="bg-amber-50"
            iconColor="text-amber-600"
            trend={stats.inquiriesTrend}
            subtitle="Last 30 days"
          />
          <StatItem
            label="Active Leads"
            value={stats.totalLeads}
            icon={<Users className="w-5 h-5" />}
            iconBg="bg-emerald-50"
            iconColor="text-emerald-600"
            trend={stats.leadsTrend}
            href="/developer/leads"
          />
          <StatItem
            label="Conversion Rate"
            value={`${stats.conversionRate.toFixed(1)}%`}
            icon={<Target className="w-5 h-5" />}
            iconBg="bg-pink-50"
            iconColor="text-pink-600"
            subtitle={`${stats.soldUnits} sold of ${stats.totalUnits}`}
          />
        </div>

        {/* Unit status bar */}
        <UnitStatusBar
          available={stats.availableUnits}
          reserved={stats.reservedUnits}
          sold={stats.soldUnits}
          total={stats.totalUnits}
        />

        {/* Revenue */}
        {stats.totalRevenue > 0 && (
          <div className="mt-4 pt-4 border-t border-gray-100">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-green-50 flex items-center justify-center">
                  <DollarSign className="w-4 h-4 text-green-600" />
                </div>
                <div>
                  <p className="text-xs text-gray-400 font-semibold uppercase tracking-wide">
                    Total Revenue
                  </p>
                  <p className="text-lg font-black text-green-600">
                    {formatPKR(stats.totalRevenue)}
                  </p>
                </div>
              </div>

              {stats.avgPrice > 0 && (
                <div className="text-right">
                  <p className="text-xs text-gray-400 font-semibold uppercase tracking-wide">
                    Avg Unit Price
                  </p>
                  <p className="text-sm font-bold text-gray-700">
                    {formatPKR(stats.avgPrice)}
                  </p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

