// ═══════════════════════════════════════════════════════════════
// 🔐 SECURITY UTILITIES
// ═══════════════════════════════════════════════════════════════

function sanitizeDisplayName(raw?: string | null): string {
  if (!raw) return "";
  return String(raw)
    .replace(/[<>'"]/g, "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .trim()
    .slice(0, MAX_DISPLAY_NAME_LEN);
}

function extractFirstName(fullName?: string | null): string {
  if (!fullName) return "";
  const sanitized = sanitizeDisplayName(fullName);
  return sanitized.split(" ")[0] || sanitized;
}

function getDisplayName(user?: SessionUser | null): string {
  if (!user) return "";
  return (
    sanitizeDisplayName(user.displayName) ||
    extractFirstName(user.name) ||
    sanitizeDisplayName(user.email?.split("@")[0]) ||
    "User"
  );
}

function cx(...classes: Array<string | false | null | undefined>): string {
  return classes.filter(Boolean).join(" ");
}

// ═══════════════════════════════════════════════════════════════
// 🏗️ ROLE BADGE
// ═══════════════════════════════════════════════════════════════

function getRoleBadge(
  role?: string,
  hasDevProfile?: boolean,
  isDevApproved?: boolean,
  devStatus?: string,
  isVerifiedOwner?: boolean,
  ownerStatus?: string
): RoleBadge {
  if (role === "admin") {
    return {
      text: "Admin",
      bg: "#fef3c7",
      color: "#d97706",
      icon: <Shield className="w-3 h-3" />,
    };
  }

  // ── Verified Owner ──
  if (isVerifiedOwner) {
    return {
      text: "Verified Owner",
      bg: "#d1fae5",
      color: "#059669",
      icon: <ShieldCheck className="w-3 h-3" />,
    };
  }
  if (ownerStatus === "pending") {
    return {
      text: "Owner (Pending)",
      bg: "#fef3c7",
      color: "#d97706",
      icon: <Clock className="w-3 h-3" />,
    };
  }

  if (role === "developer" || hasDevProfile) {
    if (isDevApproved) {
      return {
        text: "Verified Developer",
        bg: "#d1fae5",
        color: "#059669",
        icon: <CheckCircle className="w-3 h-3" />,
      };
    }
    if (devStatus === "pending") {
      return {
        text: "Developer (Pending)",
        bg: "#fef3c7",
        color: "#d97706",
        icon: <Clock className="w-3 h-3" />,
      };
    }
    if (devStatus === "rejected") {
      return {
        text: "Developer (Rejected)",
        bg: "#fee2e2",
        color: "#dc2626",
        icon: <XCircle className="w-3 h-3" />,
      };
    }
    return {
      text: "Developer",
      bg: `${PRIMARY_COLOR}15`,
      color: PRIMARY_COLOR,
      icon: <Building2 className="w-3 h-3" />,
    };
  }

  if (role === "agent") {
    return {
      text: "Agent",
      bg: "#fff7ed",
      color: "#ea580c",
      icon: <Users className="w-3 h-3" />,
    };
  }

  return {
    text: "User",
    bg: "#f3f4f6",
    color: "#6b7280",
    icon: <User className="w-3 h-3" />,
  };
}

// ═══════════════════════════════════════════════════════════════
