                aria-expanded={isToolsDropdownOpen}
                aria-haspopup="true"
              >
                <Sparkles className="w-4 h-4" />
                Tools
                <ChevronDown className={cx("w-3.5 h-3.5 transition-transform", isToolsDropdownOpen && "rotate-180")} />
              </button>

              {isToolsDropdownOpen && (
