              className="mt-1 block w-full rounded-md border border-gray-300 px-3 py-2 shadow-sm focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary sm:text-sm"
            />
          </div>
        </div>

        {/* Actions */}
        <div className="flex justify-end space-x-3 pt-6 border-t border-gray-200">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors"
            disabled={loading}
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={loading}
            className="px-4 py-2 text-sm font-medium text-white bg-primary border border-transparent rounded-md hover:bg-primary-dark focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? (
              <span className="flex items-center">
                <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                Saving...
              </span>
            ) : (
              'Save Changes'
            )}
          </button>
        </div>
      </form>
    </Modal>
  );
}

// components/owner/OwnerLayout.tsx
// Owner Portal Layout — Enterprise V1.0
// Mirrors AgentLayout pattern with owner-specific:
//   - Verification status banner
//   - Listing limit display  
//   - Owner nav items
//   - Mobile drawer

import React, { useState, useEffect, useCallback } from "react";
import Head from "next/head";
import Link from "next/link";
import { useRouter } from "next/router";
import { useSession, signOut } from "next-auth/react";
import {
  Home,
  LayoutDashboard,
  List,
  Plus,
  MessageSquare,
  ShieldCheck,
  Menu,
  X,
  ChevronRight,
  LogOut,
  Bell,
  User,
  Clock,
  XCircle,
  AlertTriangle,
  CheckCircle,
  Loader2,
  Building2,
} from "lucide-react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface OwnerProfile {
  status:        "pending" | "under_review" | "approved" | "rejected" | "suspended";
  listingCount:  number;
  listingLimit:  number;
  fullName?:     string;
}

interface NavItem {
  href:    string;
  label:   string;
  icon:    React.ReactNode;
  badge?:  number;
  exact?:  boolean;
}

interface OwnerLayoutProps {
  children:     React.ReactNode;
  title?:       string;
  description?: string;
}

// ─── Constants ────────────────────────────────────────────────────────────────

const NAV_ITEMS: NavItem[] = [
  {
    href:  "/owner/dashboard",
    label: "Dashboard",
    icon:  <LayoutDashboard className="w-5 h-5" />,
    exact: true,
  },
  {
    href:  "/owner/listings",
    label: "My Listings",
    icon:  <List className="w-5 h-5" />,
  },
  {
    href:  "/owner/listings/new",
    label: "Add Listing",
    icon:  <Plus className="w-5 h-5" />,
  },
  {
    href:  "/owner/leads",
    label: "My Leads",
    icon:  <MessageSquare className="w-5 h-5" />,
  },
  {
    href:  "/owner/verify",
    label: "Verification",
    icon:  <ShieldCheck className="w-5 h-5" />,
  },
];

// ─── Status Banner Config ─────────────────────────────────────────────────────

const STATUS_BANNER = {
  pending: {
    bg:     "bg-amber-50 border-amber-200",
    text:   "text-amber-800",
    icon:   <Clock className="w-4 h-4 text-amber-600 flex-shrink-0" />,
    label:  "Verification Pending",
    detail: "Your verification is pending admin review. Listing requires approval.",
  },
  under_review: {
    bg:     "bg-blue-50 border-blue-200",
    text:   "text-blue-800",
    icon:   <Clock className="w-4 h-4 text-blue-600 flex-shrink-0" />,
    label:  "Under Review",
    detail: "Your documents are being reviewed. We'll notify you within 24–48 hours.",
  },
  approved: {
    bg:     "bg-emerald-50 border-emerald-200",
    text:   "text-emerald-800",
    icon:   <CheckCircle className="w-4 h-4 text-emerald-600 flex-shrink-0" />,
    label:  "Verified Owner",
