// ─────────────────────────────────────────────────────────────────────────────
// METRIC CARD
// ─────────────────────────────────────────────────────────────────────────────

function MetricCard({
  label,
  value,
  sub,
  color = 'text-gray-900',
  bg    = 'bg-gray-50',
}: {
  label: string;
  value: string | number;
