              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2
                            lg:grid-cols-3 gap-3">
              {visibleProjects.map((cp, idx) => (
                <CompletedProjectCard key={idx} project={cp} />
              ))}
            </div>
          </div>
        )}

        {/* ── View Full Profile CTA ── */}
        <div className="pt-4 border-t border-gray-100">
          <Link
            href={profileUrl}
            className="w-full flex items-center justify-center gap-2
                       py-3 px-4 rounded-xl border-2 border-[#029bba]/20
                       bg-[#029bba]/5 text-[#029bba] font-bold text-sm
                       hover:bg-[#029bba]/10 hover:border-[#029bba]/40
                       transition-all"
            aria-label={`View complete ${developerName} developer profile`}
          >
            <Building2 className="w-4 h-4" />
            View Complete Developer Profile
            <ArrowRight className="w-4 h-4" />
          </Link>
        </div>

      </div>
    </section>
  );
}

/**
 * components/project-detail/HomeLoanCalculator.tsx
 *
 * Highrise.pk — Home Loan / Financing Calculator
 * Extracted from index.tsx (Wave 4 Task 2)
 *
 * Features:
 *   → Property price display (auto from project)
 *   → Down payment slider (10-50%)
 *   → Loan amount slider (dynamic)
 *   → Tenure slider (5-30 years)
 *   → Interest rate slider (10-20%)
 *   → EMI calculation with breakdown
 *   → 7 Pakistani bank options with Islamic filter
 *   → Total Cost of Ownership section (Wave 4 NEW)
 *     - Stamp duty estimate (2%)
 *     - Registration fee estimate (~1%)
 *     - Annual maintenance estimate
 *     - Agent fee (PKR 0 on Highrise — USP)
 *
 * Rules:
 *   → Tailwind only (zero inline styles except % widths)
 *   → Lucide React icons only
 *   → No framer-motion
 *   → Mobile-first (375px min)
 *   → Guest-first (no login needed)
 */

'use client';

import React, { useState } from 'react';
import { CreditCard, Info } from 'lucide-react';
import { formatDetailPrice } from '@/types/projectDetail';

// ─────────────────────────────────────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────────────────────────────────────

export interface HomeLoanCalculatorProps {
  propertyPrice: number;
  projectName:   string;
  projectSlug?:  string;
}

// ─────────────────────────────────────────────────────────────────────────────
// CONSTANTS
// ─────────────────────────────────────────────────────────────────────────────

const PAKISTANI_BANKS = [
  { name: 'Meezan Bank',        rate: 12.5, type: 'Islamic',  badge: '🕌 Islamic'  },
  { name: 'HBL',                rate: 13.5, type: 'Standard', badge: '🏦 Standard' },
  { name: 'UBL',                rate: 14.0, type: 'Standard', badge: '🏦 Standard' },
  { name: 'MCB',                rate: 13.8, type: 'Standard', badge: '🏦 Standard' },
  { name: 'Standard Chartered', rate: 13.9, type: 'Standard', badge: '🏦 Standard' },
  { name: 'Islamic Bank',       rate: 13.0, type: 'Islamic',  badge: '🕌 Islamic'  },
  { name: 'Alfalah',            rate: 13.5, type: 'Both',     badge: '🏦 Both'     },
] as const;

// ─────────────────────────────────────────────────────────────────────────────
// EMI CALCULATOR
// ─────────────────────────────────────────────────────────────────────────────

function calcEMI(principal: number, annualRate: number, tenureYears: number): number {
  const monthlyRate = annualRate / 100 / 12;
  const months      = tenureYears * 12;
  if (monthlyRate === 0) return Math.round(principal / months);
  return Math.round(
    (principal * monthlyRate * Math.pow(1 + monthlyRate, months)) /
    (Math.pow(1 + monthlyRate, months) - 1),
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// TOTAL COST OF OWNERSHIP SECTION (Wave 4 NEW)
// ─────────────────────────────────────────────────────────────────────────────

function TotalCostOwnership({ propertyPrice }: { propertyPrice: number }) {
  const stampDuty          = Math.round(propertyPrice * 0.02);
  const registrationFee    = Math.round(propertyPrice * 0.01);
  const annualMaintenance  = Math.round(propertyPrice * 0.005);
  const agentFee           = 0;
  const firstYearTotal     = propertyPrice + stampDuty + registrationFee + annualMaintenance;

  const rows = [
    {
      label:   'Property Price',
      value:   formatDetailPrice(propertyPrice),
      color:   'text-gray-900',
      bg:      'bg-white',
      note:    null,
    },
    {
      label:   'Stamp Duty',
      value:   `PKR ${formatDetailPrice(stampDuty)}`,
      color:   'text-orange-700',
      bg:      'bg-orange-50',
      note:    '~2% of property value (estimate)',
    },
    {
      label:   'Registration Fee',
      value:   `PKR ${formatDetailPrice(registrationFee)}`,
      color:   'text-blue-700',
      bg:      'bg-blue-50',
      note:    '~1% of property value (estimate)',
    },
    {
      label:   'Annual Maintenance',
      value:   `PKR ${formatDetailPrice(annualMaintenance)}/yr`,
      color:   'text-purple-700',
      bg:      'bg-purple-50',
      note:    '~0.5% estimate — varies by project',
    },
    {
      label:   'Agent Commission',
      value:   'PKR 0',
      color:   'text-emerald-700',
      bg:      'bg-emerald-50',
      note:    '✅ Zero on Highrise.pk — always free',
    },
  ];

  return (
    <div className="mt-8 pt-6 border-t border-gray-100">
      {/* Section header */}
      <div className="flex items-center gap-2 mb-4">
        <Info className="w-4 h-4 text-[#029bba]" />
        <h3 className="font-bold text-gray-900 text-base">
          Total Cost of Ownership
        </h3>
        <span className="text-xs text-gray-400 font-medium">(First Year Estimate)</span>
      </div>

      {/* Cost rows */}
      <div className="space-y-2">
        {rows.map((row) => (
          <div
            key={row.label}
            className={`flex items-center justify-between px-4 py-3 rounded-xl border border-gray-100 ${row.bg}`}
          >
            <div>
              <p className="text-sm font-semibold text-gray-700">{row.label}</p>
              {row.note && (
                <p className="text-[10px] text-gray-400 mt-0.5">{row.note}</p>
              )}
            </div>
            <p className={`text-sm font-black ${row.color}`}>{row.value}</p>
          </div>
        ))}
      </div>

      {/* Total */}
      <div className="mt-3 flex items-center justify-between px-4 py-4 rounded-xl bg-gradient-to-r from-[#004063] to-[#029bba] text-white">
        <div>
          <p className="text-sm font-bold text-white/80">Estimated First Year Total</p>
          <p className="text-[10px] text-white/60 mt-0.5">
            Property + Stamp Duty + Registration + Maintenance
          </p>
        </div>
        <p className="text-xl font-black">PKR {formatDetailPrice(firstYearTotal)}</p>
      </div>

      {/* Disclaimer */}
      <p className="text-[11px] text-gray-400 mt-3 bg-gray-50 border border-gray-100 rounded-xl px-3 py-2 leading-relaxed">
        ⚠️ All figures are estimates only. Stamp duty and registration fees vary by province, property type, and transaction value. Consult a legal expert for exact amounts.
      </p>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN COMPONENT
// ─────────────────────────────────────────────────────────────────────────────

export default function HomeLoanCalculator({
  propertyPrice,
  projectName,
}: HomeLoanCalculatorProps) {
  const defaultPrice = propertyPrice > 0 ? propertyPrice : 10_000_000;

  const [downPercent,      setDownPercent]      = useState(20);
  const [loanAmount,       setLoanAmount]        = useState(Math.round(defaultPrice * 0.8));
  const [tenure,           setTenure]            = useState(20);
  const [rate,             setRate]              = useState(13.5);
  const [showIslamicOnly,  setShowIslamicOnly]   = useState(false);

  const months           = tenure * 12;
  const emi              = calcEMI(loanAmount, rate, tenure);
  const totalPayment     = emi * months;
  const totalInterest    = totalPayment - loanAmount;
  const principalPercent = Math.round((loanAmount / totalPayment) * 100);
  const interestPercent  = 100 - principalPercent;

  const handleDownPercent = (val: number) => {
    setDownPercent(val);
    setLoanAmount(Math.round(defaultPrice * (1 - val / 100)));
  };

  const displayBanks = showIslamicOnly
    ? PAKISTANI_BANKS.filter(b => b.type === 'Islamic')
    : PAKISTANI_BANKS;

  return (
    <div className="max-w-7xl mx-auto px-4 py-4">
      <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">

        {/* Header */}
        <div className="px-6 py-5 border-b border-gray-100">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-[#029bba]/10 flex items-center justify-center">
              <CreditCard className="w-4.5 h-4.5 text-[#029bba]" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-gray-900">
                Home Loan / Financing Calculator
              </h2>
              <p className="text-sm text-gray-500 mt-0.5">
                Estimate your monthly payments for {projectName}
              </p>
            </div>
          </div>
        </div>

        <div className="p-6">
          {/* ── Two column layout ── */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

            {/* LEFT — Inputs */}
            <div className="space-y-6">

              {/* Property price display */}
              <div className="p-4 bg-gray-50 rounded-xl border border-gray-200">
                <p className="text-xs text-gray-500 uppercase font-bold tracking-wider mb-1">
                  Property Price
                </p>
                <p className="text-2xl font-black text-gray-900">
                  PKR {formatDetailPrice(defaultPrice)}
                </p>
                <p className="text-xs text-gray-400 mt-1">Based on starting price</p>
              </div>

              {/* Down Payment slider */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-sm font-bold text-gray-700">
                    Down Payment
                  </label>
                  <span className="text-sm font-black text-[#029bba]">
                    {downPercent}% — PKR {formatDetailPrice(Math.round(defaultPrice * downPercent / 100))}
                  </span>
                </div>
                <input
                  type="range" min={10} max={50} step={5}
                  value={downPercent}
                  onChange={e => handleDownPercent(Number(e.target.value))}
                  aria-label="Down payment percentage"
                  className="w-full h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-[#029bba]"
                />
                <div className="flex justify-between text-[10px] text-gray-400 mt-1">
                  <span>10%</span><span>50%</span>
                </div>
              </div>

              {/* Loan Amount slider */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-sm font-bold text-gray-700">
                    Loan Amount
                  </label>
                  <span className="text-sm font-black text-[#029bba]">
                    PKR {formatDetailPrice(loanAmount)}
                  </span>
                </div>
                <input
                  type="range"
                  min={Math.round(defaultPrice * 0.5)}
                  max={Math.round(defaultPrice * 0.9)}
                  step={100_000}
                  value={loanAmount}
                  onChange={e => setLoanAmount(Number(e.target.value))}
                  aria-label="Loan amount"
                  className="w-full h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-[#029bba]"
                />
              </div>

              {/* Tenure slider */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-sm font-bold text-gray-700">
                    Loan Tenure
                  </label>
                  <span className="text-sm font-black text-[#029bba]">
                    {tenure} Years
                  </span>
                </div>
                <input
                  type="range" min={5} max={30} step={5}
                  value={tenure}
                  onChange={e => setTenure(Number(e.target.value))}
                  aria-label="Loan tenure in years"
                  className="w-full h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-[#029bba]"
                />
                <div className="flex justify-between text-[10px] text-gray-400 mt-1">
                  <span>5 Years</span><span>30 Years</span>
                </div>
              </div>

              {/* Rate slider */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-sm font-bold text-gray-700">
                    Interest / Profit Rate
                  </label>
                  <span className="text-sm font-black text-[#029bba]">
                    {rate}% per annum
                  </span>
                </div>
                <input
                  type="range" min={10} max={20} step={0.5}
                  value={rate}
                  onChange={e => setRate(Number(e.target.value))}
                  aria-label="Annual interest rate"
                  className="w-full h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-[#029bba]"
                />
                <div className="flex justify-between text-[10px] text-gray-400 mt-1">
                  <span>10%</span><span>20%</span>
                </div>
              </div>
            </div>

            {/* RIGHT — Results */}
            <div className="space-y-5">

              {/* EMI card */}
              <div className="bg-gradient-to-br from-[#029bba] to-[#017a94] rounded-2xl p-5 text-white">
                <p className="text-white/70 text-sm font-semibold mb-1">
                  Monthly Payment (EMI)
                </p>
                <p className="text-4xl font-black mb-1">
                  PKR {emi.toLocaleString()}
                </p>
                <p className="text-white/60 text-xs">
                  per month for {tenure} years
                </p>
                <div className="mt-4 pt-4 border-t border-white/20 grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-white/60 text-xs mb-1">Total Payable</p>
                    <p className="font-bold text-sm">PKR {formatDetailPrice(totalPayment)}</p>
                  </div>
                  <div>
                    <p className="text-white/60 text-xs mb-1">Total Interest</p>
                    <p className="font-bold text-sm">PKR {formatDetailPrice(totalInterest)}</p>
                  </div>
                </div>
              </div>

              {/* Breakdown bar */}
              <div className="p-4 bg-gray-50 rounded-xl border border-gray-200">
                <p className="text-xs text-gray-500 uppercase font-bold tracking-wider mb-3">
                  Payment Breakdown
                </p>
                <div className="h-4 rounded-full overflow-hidden flex mb-3">
                  <div
                    className="bg-[#029bba] h-full transition-all duration-500"
                    style={{ width: `${principalPercent}%` }}
                  />
                  <div
                    className="bg-orange-400 h-full transition-all duration-500"
                    style={{ width: `${interestPercent}%` }}
                  />
                </div>
                <div className="flex items-center gap-2 text-sm">
                  <div className="w-3 h-3 rounded-full bg-[#029bba]" />
                  <span className="text-gray-600">Principal ({principalPercent}%)</span>
                </div>
                <div className="flex items-center gap-2 text-sm mt-2">
                  <div className="w-3 h-3 rounded-full bg-orange-400" />
                  <span className="text-gray-600">Interest ({interestPercent}%)</span>
                </div>
              </div>

              {/* Estimate warning */}
              <p className="text-xs text-gray-400 bg-amber-50 border border-amber-100 rounded-xl p-3">
                ⚠️ Estimate only. Actual rates vary by bank and applicant profile.
              </p>
            </div>
          </div>

          {/* ── Pakistani Bank Options ── */}
          <div className="mt-8 pt-6 border-t border-gray-100">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-gray-900 text-base">
                Pakistani Bank Options
              </h3>
              <button
                onClick={() => setShowIslamicOnly(v => !v)}
                aria-pressed={showIslamicOnly}
                aria-label="Show Islamic banks only"
                className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all ${
                  showIslamicOnly
                    ? 'bg-green-500 text-white'
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                🕌 Islamic Only
              </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {displayBanks.map((bank) => {
                const bEmi       = calcEMI(loanAmount, bank.rate, tenure);
                const isSelected = rate === bank.rate;
                return (
                  <button
                    key={bank.name}
                    onClick={() => setRate(bank.rate)}
                    aria-pressed={isSelected}
                    aria-label={`Select ${bank.name} at ${bank.rate}% rate`}
                    className={`text-left p-4 rounded-xl border transition-all ${
                      isSelected
                        ? 'border-[#029bba] bg-[#029bba]/5 shadow-md'
                        : 'border-gray-200 bg-gray-50 hover:border-[#029bba]/30 hover:bg-white'
                    }`}
                  >
                    <div className="flex items-center justify-between mb-2">
                      <p className="font-bold text-gray-900 text-sm">{bank.name}</p>
                      <span className="text-[9px] font-bold text-gray-400">{bank.badge}</span>
                    </div>
                    <p className={`text-lg font-black ${isSelected ? 'text-[#029bba]' : 'text-gray-700'}`}>
                      {bank.rate}%
                    </p>
                    <p className="text-xs text-gray-500">
                      EMI: PKR {bEmi.toLocaleString()}/mo
                    </p>
                  </button>
                );
              })}
            </div>
          </div>

          {/* ── Total Cost of Ownership (Wave 4 NEW) ── */}
          <TotalCostOwnership propertyPrice={defaultPrice} />
        </div>
      </div>
    </div>
  );
}

/**
 * components/project-detail/ProjectDetailHero.tsx
 *
 * Highrise.pk — Enterprise Project Detail Hero (Wave 5A)
 *
 * ═══════════════════════════════════════════════════════════════
 * WAVE 5A REDESIGN — Enterprise Real Estate Portal Standard
 * ═══════════════════════════════════════════════════════════════
 *
 * INTEGRATIONS:
 *   → ProjectGallery       (variant="full") — 4 photos + 1 map tile
 *   → useFavorites         (Sprint 2)
 *   → useCompare           (Sprint 3)
 *   → ShareMenu            (Sprint 1)
 *   → useAuthGate          (Wave 5A) — session gating
 *   → AuthGateModal        (Wave 5A) — login before inquiry
 *   → downloadFile         (Wave 5A) — fl_attachment magic
 *   → calculateDurationMonths (Wave 5A)
 *
 * LAYOUT:
 *   1. Breadcrumb (semantic + microdata)
 *   2. Gallery (5-tile grid with static map as 5th)
 *   3. Bottom stats bar overlay (Photos | Tours | Video | Site Map)
 *   4. Title row (H1 + address + rating + trust score + actions)
 *   5. Company logo card (NO website — engagement lock)
 *   6. Stats bar (Price | Size | Start | Possession | Progress)
 *   7. CTA row (Brochure | Book Visit | Contact Now)
 *   8. Trust badges strip
 *
 * SECURITY:
 *   → No phone/email in DOM
 *   → Contact gating via AuthGateModal → UniversalInquiryModal
 *   → External links: rel="noopener noreferrer"
 *   → aria-pressed, aria-label on all buttons
 *
 * SEO:
 *   → Semantic <nav> breadcrumb + microdata
 *   → ONE <h1> only (project name)
 *   → Internal links: city filter, developer profile
 *   → progressbar aria attributes
 */

'use client';

import React, { useState, useCallback } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import {
  MapPin,
  ChevronRight,
  Home,
  Building2,
  CheckCircle2,
  Flame,
  BadgeCheck,
  Star,
  Heart,
  GitCompare,
  Share2,
  Phone,
  Calendar,
  Download,
  CalendarCheck,
  TrendingUp,
  MapPinned,
  Camera,
  Video,
  Play,
  Map as MapIcon,
  Clock,
  Sparkles,
} from 'lucide-react';

import ProjectGallery, {
  type GalleryImage,
} from '@/components/projects/ProjectGallery';

import { useFavorites }      from '@/hooks/useFavorites';
import { useCompare }        from '@/hooks/useCompare';
import { useAuthGate }       from '@/hooks/useAuthGate';
import ShareMenu             from '@/components/projects/ShareMenu';
import AuthGateModal         from '@/components/auth/AuthGateModal';
import UniversalInquiryModal from '@/components/UniversalInquiryModal';

import { downloadFile }      from '@/lib/cloudinaryClient';

import type { ProjectDetailData, InquiryType } from '@/types/projectDetail';
import type { ProjectListing }                 from '@/types/projects';

import {
  formatDetailPrice,
  formatDetailDate,
  formatDetailDateShort,
  convertToSqftAndMarla,
  getPrimaryImageUrl,
  getProjectAreaDisplay,
  getDeveloperDisplayName,
  calculateAndFormatDuration,
} from '@/types/projectDetail';

// ─────────────────────────────────────────────────────────────────────────────
// PROPS
// ─────────────────────────────────────────────────────────────────────────────

interface ProjectDetailHeroProps {
  project:         ProjectDetailData;
  overallMinPrice: number | undefined;
  overallMaxPrice: number | undefined;
  minAreaSqft:     number;
  maxAreaSqft:     number;
  canonicalUrl:    string;
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER — Map ProjectDetailData → ProjectListing for ShareMenu
// SECURITY: Only public fields. No contact data.
// ─────────────────────────────────────────────────────────────────────────────

function toListingShape(
  project:      ProjectDetailData,
  primaryImage: string,
  area:         string,
): ProjectListing {
  return {
    _id:             project._id,
    slug:            project.slug,
    projectName:     project.projectName,
    tagline:         project.tagline ?? null,
    city:            project.city,
    area,
    locality:        null,
    propertyType:    [],
    projectCategory: project.projectCategory,
    projectNature:   project.projectNature,
    projectStatus:   'under_construction',
    minPrice:        project.minPrice ?? null,
    maxPrice:        project.maxPrice ?? null,
    priceOnRequest:  !project.minPrice,
    minAreaMarla:    null,
    maxAreaMarla:    null,
    minBedrooms:     null,
    maxBedrooms:     null,
    possessionDate:  project.possessionStartDate ?? null,
    possessionQuarter: null,
    isVerified:      project.isVerified,
    nocStatus:       (project.nocStatus as 'approved' | 'pending' | 'not_applied') ?? 'not_applied',
    nocAuthority:    project.approvalAuthority ?? null,
    nocNumber:       null,
    legalDocumentUrl: project.legalDocs?.nocUrl ?? null,
    shield: {
      total:         project.highriseScore ?? 0,
      nocScore:      0,
      verifiedScore: 0,
      builderScore:  0,
      deliveryScore: 0,
      breakdown:     null,
    },
    developerId:      project.developer,
    developerName:    getDeveloperDisplayName(project.developerProfile),
    developerSlug:    project.developer,
    developerLogoUrl: project.developerProfile?.logoUrl ?? null,
    developerBadge:   null,
    isTrustedBuilder: project.isTrustedBuilder ?? false,
    marketedBy:       null,
    primaryImage,
    imageCount:       (project.images ?? []).length,
    isShortlisted:    false,
    inquiryCount:     null,
    amenities:        [],
    fairPriceUrl:     null,
    isFeatured:       project.isFeatured ?? false,
    highriseScore:    project.highriseScore ?? 0,
    createdAt:        project.createdAt ?? new Date().toISOString(),
  };
}

// Map removed from hero gallery (Wave 5A user feedback)
// → Uses 5-photo grid (Option A) instead
// → "Property Site Map" link in bottom stats bar → scrolls to Location section

// ─────────────────────────────────────────────────────────────────────────────
// GALLERY STATS BAR — Bottom overlay showing counts
// ─────────────────────────────────────────────────────────────────────────────

interface GalleryStatsBarProps {
  photoCount:      number;
  tourCount:       number;
  videoCount:      number;
  onScrollTo:      (sectionId: string) => void;
}

function GalleryStatsBar({
  photoCount,
  tourCount,
  videoCount,
  onScrollTo,
}: GalleryStatsBarProps) {
  const items = [
    {
      icon:  <Camera className="w-4 h-4" />,
      label: `${photoCount} Photos`,
      show:  photoCount > 0,
      onClick: () => {}, // Gallery already handles this
    },
    {
      icon:  <Video className="w-4 h-4" />,
      label: `${tourCount} Virtual Tours`,
      show:  tourCount > 0,
      onClick: () => onScrollTo('virtual-tour'),
    },
    {
      icon:  <Play className="w-4 h-4" />,
      label: `${videoCount} ${videoCount === 1 ? 'Video' : 'Videos'}`,
      show:  videoCount > 0,
      onClick: () => onScrollTo('video-tour'),
    },
    {
      icon:  <MapIcon className="w-4 h-4" />,
      label: 'Property Site Map',
      show:  true,
      onClick: () => onScrollTo('location'),
    },
  ].filter(item => item.show);

  if (items.length === 0) return null;

  return (
    <div className="flex justify-center -mt-6 relative z-10 px-4">
      <div className="bg-white rounded-2xl shadow-2xl border border-gray-100
                      px-2 py-1 flex items-center flex-wrap gap-1">
        {items.map((item, idx) => (
          <React.Fragment key={item.label}>
            {idx > 0 && (
              <div className="w-px h-6 bg-gray-200" aria-hidden="true" />
            )}
            <button
              onClick={item.onClick}
              className="flex items-center gap-1.5 px-3 py-2 rounded-xl
                         text-xs font-bold text-gray-700
                         hover:text-[#029bba] hover:bg-[#029bba]/5
                         transition-colors"
              aria-label={item.label}
            >
              <span className="text-[#029bba]">{item.icon}</span>
              {item.label}
            </button>
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}

// TrustBadgesStrip removed (Wave 5A polish)
// Trust signals now consolidated in title row: Verified + Delivered + Trust Score
// Approval authority (CDA/LDA) shown in Documents section + Property Passport
// Risk level shown in Highrise Trust Index section
// Zero Buyer Commission — always true on our platform, doesn't need display badge

// ─────────────────────────────────────────────────────────────────────────────
// STATS BAR — Price | Size | Start | Possession | Progress
// ─────────────────────────────────────────────────────────────────────────────

interface StatsBarProps {
  project:         ProjectDetailData;
  overallMinPrice: number | undefined;
  overallMaxPrice: number | undefined;
  minAreaSqft:     number;
  maxAreaSqft:     number;
  onInquiry:       (type: InquiryType) => void;
  onDownload:      (url: string, filename: string) => Promise<void>;
}

function StatsBar({
  project,
  overallMinPrice,
  overallMaxPrice,
  minAreaSqft,
  maxAreaSqft,
  onInquiry,
  onDownload,
}: StatsBarProps) {

  const duration = calculateAndFormatDuration(
    project.launchDate,
    project.possessionStartDate,
  );

  return (
    <div className="bg-gradient-to-r from-gray-50 to-white border-b border-gray-200">
      <div className="max-w-7xl mx-auto px-4 py-6">

        {/* ── Stats Grid ── */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4 mb-5">

          {/* 1. PRICE RANGE */}
          <div className="border-r border-gray-200 pr-4 last:border-r-0">
            <p className="text-[10px] text-gray-500 uppercase tracking-wider font-bold mb-1">
              Price Range
            </p>
            <p className="text-xl md:text-2xl font-black text-[#029bba] leading-tight">
              PKR {formatDetailPrice(overallMinPrice ?? null)}
            </p>
            {overallMaxPrice && overallMaxPrice > (overallMinPrice ?? 0) && (
              <p className="text-xs text-gray-500 mt-0.5">
                to {formatDetailPrice(overallMaxPrice)}
              </p>
            )}
          </div>

          {/* 2. SIZE RANGE */}
          {minAreaSqft > 0 && maxAreaSqft > 0 && (
            <div className="border-r border-gray-200 pr-4 last:border-r-0">
              <p className="text-[10px] text-gray-500 uppercase tracking-wider font-bold mb-1">
                Size Range
              </p>
              <p className="text-base md:text-lg font-black text-gray-900 leading-tight">
                {minAreaSqft.toLocaleString()} — {maxAreaSqft.toLocaleString()}
                <span className="text-xs text-gray-500 font-semibold ml-1">sqft</span>
              </p>
              <p className="text-xs text-gray-500 mt-0.5">
                ({convertToSqftAndMarla(minAreaSqft, 'sqft').marla} — {convertToSqftAndMarla(maxAreaSqft, 'sqft').marla} Marla)
              </p>
            </div>
          )}

          {/* 3. START DATE */}
          {project.launchDate && (
            <div className="border-r border-gray-200 pr-4 last:border-r-0">
              <p className="text-[10px] text-gray-500 uppercase tracking-wider font-bold mb-1">
                Start Date
              </p>
              <p className="text-base md:text-lg font-black text-gray-900 leading-tight flex items-center gap-1.5">
                <Calendar className="w-4 h-4 text-emerald-600 flex-shrink-0" />
                {formatDetailDateShort(project.launchDate)}
              </p>
              <p className="text-xs text-gray-500 mt-0.5">Project launched</p>
            </div>
          )}

          {/* 4. POSSESSION */}
          {project.possessionStartDate && (
            <div className="border-r border-gray-200 pr-4 last:border-r-0">
              <p className="text-[10px] text-gray-500 uppercase tracking-wider font-bold mb-1">
                Possession
              </p>
              <p className="text-base md:text-lg font-black text-gray-900 leading-tight flex items-center gap-1.5">
                <CalendarCheck className="w-4 h-4 text-[#029bba] flex-shrink-0" />
                {formatDetailDateShort(project.possessionStartDate)}
              </p>
              {duration && (
                <p className="text-xs text-[#029bba] font-bold mt-0.5 flex items-center gap-1">
                  <Clock className="w-3 h-3" />
                  {duration} total
                </p>
              )}
            </div>
          )}

          {/* 5. PROGRESS */}
          {project.developmentProgress !== undefined && (
            <div>
              <p className="text-[10px] text-gray-500 uppercase tracking-wider font-bold mb-1">
                Progress
              </p>
              <p className="text-base md:text-lg font-black text-[#029bba] leading-tight mb-1.5">
                {project.developmentProgress}%
              </p>
              <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
                <div
                  className="h-full bg-gradient-to-r from-[#029bba] to-[#017a94] rounded-full transition-all duration-700"
                  style={{ width: `${project.developmentProgress}%` }}
                  role="progressbar"
                  aria-valuenow={project.developmentProgress}
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-label={`Construction ${project.developmentProgress}% complete`}
                />
              </div>
            </div>
          )}
        </div>

        {/* ── CTA Buttons Row ── */}
        <div className="flex items-center gap-3 flex-wrap justify-end pt-4 border-t border-gray-100">

          {project.projectDocuments?.brochureUrl && (
            <button
              onClick={() => void onDownload(
                project.projectDocuments!.brochureUrl!,
                `${project.slug}-brochure`,
              )}
              aria-label="Download project brochure PDF"
              className="inline-flex items-center gap-2 px-4 py-2.5 bg-white
                         border border-gray-200 rounded-xl text-sm font-bold
                         text-gray-700 hover:bg-gray-50 hover:border-[#029bba]/30
                         transition-all"
            >
              <Download className="w-4 h-4" />
              Download Brochure
            </button>
          )}

          <button
            onClick={() => onInquiry('site_visit')}
            aria-label="Book a site visit"
            className="inline-flex items-center gap-2 px-4 py-2.5 bg-white
                       border border-gray-200 rounded-xl text-sm font-bold
                       text-gray-700 hover:bg-gray-50 hover:border-[#029bba]/30
                       transition-all"
          >
            <Calendar className="w-4 h-4" />
            Book Visit
          </button>

          <button
            onClick={() => onInquiry('project_interest')}
            aria-label="Contact developer about this project"
            className="inline-flex items-center gap-2 px-5 py-2.5
                       bg-gradient-to-r from-[#029bba] to-[#017a94]
                       hover:from-[#02a8c9] hover:to-[#018a9a]
                       text-white font-bold rounded-xl transition-all
                       shadow-lg shadow-[#029bba]/20"
          >
            <Phone className="w-4 h-4" />
            Contact Now
          </button>
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN COMPONENT
// ─────────────────────────────────────────────────────────────────────────────

export default function ProjectDetailHero({
  project,
  overallMinPrice,
  overallMaxPrice,
  minAreaSqft,
  maxAreaSqft,
  canonicalUrl,
}: ProjectDetailHeroProps) {

  // ── Derived values ──
  const area          = getProjectAreaDisplay(project);
  const developerName = getDeveloperDisplayName(project.developerProfile);
  const primaryImage  = getPrimaryImageUrl(project);

  // ── Gallery images (with map as 5th tile if coordinates exist) ──
  const galleryImages: GalleryImage[] = (project.images ?? []).map(img => ({
    url:       img.url,
    publicId:  img.publicId,
    caption:   img.caption,
    isPrimary: img.isPrimary,
    order:     img.order,
    category:  img.category ?? img.type,
  }));

  const coverImage = primaryImage ? { url: primaryImage } : null;

  // ── Counts for gallery stats bar ──
  const photoCount = galleryImages.length;
  const tourCount  = project.virtualTourUrl ? 1 : 0;
  const videoCount = (project.videos?.length ?? 0) + (project.droneVideoUrl ? 1 : 0);

  // ── Listing shape for ShareMenu ──
  const listingShape = toListingShape(project, primaryImage, area);

  // ── SPRINT 2: Favorites ──
  const {
    isFavorite,
    actionState: favActionState,
    toggle:      toggleFavorite,
  } = useFavorites({ defaultEntityType: 'project' });

  const isFavorited = isFavorite(project._id);
  const favPending  = favActionState === 'pending';

  // ── SPRINT 3: Compare ──
  const {
    isInCompare,
    actionState: compareActionState,
    toggle:      toggleCompare,
  } = useCompare({ defaultEntityType: 'project' });

  const isCompared     = isInCompare(project._id);
  const comparePending = compareActionState === 'pending';

  // ── WAVE 5A: Auth Gate ──
  const {
    authGateOpen,
    gateContext,
    closeAuthGate,
    requireAuth,
  } = useAuthGate();

  // ── Modals ──
  const [shareOpen,   setShareOpen]   = useState(false);
  const [inquiryOpen, setInquiryOpen] = useState(false);
  const [inquiryType, setInquiryType] = useState<InquiryType>('project_interest');

  // ── Handlers ──

  const handleInquiry = useCallback((type: InquiryType) => {
    const actionMap: Record<string, string> = {
      site_visit:       'book a site visit',
      call_back:        'request a callback',
      project_interest: 'contact the developer',
      general_inquiry:  'send an inquiry',
    };

    // Require login before opening inquiry
    requireAuth(
      () => {
        setInquiryType(type);
        setInquiryOpen(true);
      },
      {
        actionDescription: actionMap[type] || 'contact the developer',
        entityTitle:       project.projectName,
      },
    );
  }, [requireAuth, project.projectName]);

  const handleDownload = useCallback(async (url: string, filename: string) => {
    if (!url) return;
    // Uses fl_attachment magic — direct download, no Save-As dialog
    await downloadFile(url, filename);
  }, []);

  const scrollToSection = useCallback((sectionId: string) => {
    if (typeof document === 'undefined') return;
    const el = document.getElementById(sectionId);
    if (el) {
      window.scrollTo({
        top:      el.getBoundingClientRect().top + window.scrollY - 130,
        behavior: 'smooth',
      });
    }
  }, []);

  // ─────────────────────────────────────────────────────────
  // RENDER
  // ─────────────────────────────────────────────────────────

  return (
    <>
      {/* ══════════════════════════════════════
          1. BREADCRUMB — semantic + microdata
      ══════════════════════════════════════ */}
      <div className="bg-white border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 py-3">
          <nav aria-label="Breadcrumb">
            <ol
              className="flex items-center gap-2 text-sm flex-wrap list-none p-0 m-0"
              itemScope
              itemType="https://schema.org/BreadcrumbList"
            >
              <li itemProp="itemListElement" itemScope itemType="https://schema.org/ListItem">
                <Link href="/" itemProp="item"
                      className="flex items-center gap-1.5 text-gray-500 hover:text-[#029bba] transition-colors">
                  <Home className="w-4 h-4" />
                  <span itemProp="name">Home</span>
                </Link>
                <meta itemProp="position" content="1" />
              </li>

              <li aria-hidden="true"><ChevronRight className="w-4 h-4 text-gray-300" /></li>

              <li itemProp="itemListElement" itemScope itemType="https://schema.org/ListItem">
                <Link href="/projects" itemProp="item"
                      className="text-gray-500 hover:text-[#029bba] transition-colors">
                  <span itemProp="name">Projects</span>
                </Link>
                <meta itemProp="position" content="2" />
              </li>

              <li aria-hidden="true"><ChevronRight className="w-4 h-4 text-gray-300" /></li>

              <li itemProp="itemListElement" itemScope itemType="https://schema.org/ListItem">
                <Link href={`/projects?city=${encodeURIComponent(project.city)}`}
                      itemProp="item"
                      className="text-gray-500 hover:text-[#029bba] transition-colors flex items-center gap-1">
                  <MapPin className="w-3 h-3" />
                  <span itemProp="name">{project.city}</span>
                </Link>
                <meta itemProp="position" content="3" />
              </li>

              <li aria-hidden="true"><ChevronRight className="w-4 h-4 text-gray-300" /></li>

              <li itemProp="itemListElement" itemScope itemType="https://schema.org/ListItem"
                  className="min-w-0">
                <span itemProp="name" aria-current="page"
                      className="text-gray-900 font-bold truncate block max-w-[250px]">
                  {project.projectName}
                </span>
                <meta itemProp="position" content="4" />
                <meta itemProp="item" content={canonicalUrl} />
              </li>
            </ol>
          </nav>
        </div>
      </div>

      {/* ══════════════════════════════════════
          2. GALLERY — Delegated to ProjectGallery (Wave 5A Option A)
          → Map removed (user feedback)
          → ProjectGallery handles full 5-photo grid layout internally
          → Bottom stats bar shows Photos/Tours/Videos/Site Map counts
      ══════════════════════════════════════ */}
      <div className="bg-white">
        <div className="max-w-7xl mx-auto px-4 pt-4">
          <div className="relative">

            <ProjectGallery
              images={galleryImages}
              projectName={project.projectName}
              coverImage={coverImage}
              variant="full"
              maxVisible={12}
            />

            {/* ══ GALLERY STATS BAR — bottom overlay ══ */}
            <GalleryStatsBar
              photoCount={photoCount}
              tourCount={tourCount}
              videoCount={videoCount}
              onScrollTo={scrollToSection}
            />

          </div>
        </div>
      </div>

      {/* ══════════════════════════════════════
          3. TITLE ROW — H1 + Address + Rating + Trust Score + Actions
      ══════════════════════════════════════ */}
      <div className="bg-white pt-8">
        <div className="max-w-7xl mx-auto px-4 py-5">
          <div className="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-4">

            {/* ── LEFT: Title + Address + Rating/Trust ── */}
            <div className="flex-1 min-w-0">

              {/* Status badges */}
              <div className="flex items-center gap-2 flex-wrap mb-3">
                {project.isFeatured && (
                  <span className="inline-flex items-center gap-1 px-2.5 py-1
                                   bg-amber-50 text-amber-700 text-xs font-bold
                                   rounded-full border border-amber-200">
                    <Flame className="w-3 h-3" />
                    Featured
                  </span>
                )}
                {project.isTrustedBuilder && (
                  <span className="inline-flex items-center gap-1 px-2.5 py-1
                                   bg-[#029bba]/10 text-[#029bba] text-xs font-bold
                                   rounded-full border border-[#029bba]/20">
                    <BadgeCheck className="w-3 h-3" />
                    Trusted Developer
                  </span>
                )}
              </div>

              {/* H1 — SEO CRITICAL — Only one per page */}
              <h1 className="text-2xl md:text-3xl lg:text-4xl font-black text-gray-900 mb-2 leading-tight">
                {project.projectName}
              </h1>

              {project.tagline && (
                <p className="text-gray-500 italic mb-3 text-base">
                  &ldquo;{project.tagline}&rdquo;
                </p>
              )}

              {/* Address subheading */}
              <div className="flex items-center gap-2 text-gray-700 mb-4">
                <MapPinned className="w-4 h-4 text-[#029bba] flex-shrink-0" />
                <span className="text-sm font-semibold">
                  {area}, {project.city}
                  {project.specificLocation && (
                    <span className="text-gray-400 ml-1">• {project.specificLocation}</span>
                  )}
                </span>
              </div>

              {/* ══════════════════════════════════════
                  TRUST SIGNALS ROW (Wave 5A — Enterprise Pattern)
                  Order: Verified → Delivered Projects → Trust Score
                  Rationale: Facts only. No reviews (fake review protection).
              ══════════════════════════════════════ */}
              <div className="flex items-center gap-3 flex-wrap">

                {/* 1. Verified Badge */}
                {project.isVerified && (
                  <div className="flex items-center gap-1.5 bg-emerald-50 border border-emerald-200
                                  rounded-xl px-3 py-1.5">
                    <CheckCircle2 className="w-4 h-4 text-emerald-600" />
                    <span className="text-xs font-black text-emerald-800">
                      Verified by Highrise.pk
                    </span>
                  </div>
                )}

                {/* 2. Delivered Projects (Developer Track Record) */}
                {(() => {
                  const delivered = project.developerProfile?.completedProjectsCount
                    ?? project.completedProjects?.length
                    ?? 0;

                  // Show badge even when 0 (new developer — buyer transparency)
                  const displayLabel = delivered >= 100
                    ? '100+'
                    : delivered === 0
                    ? 'New Developer'
                    : String(delivered);

                  const badgeColor = delivered >= 10
                    ? 'bg-purple-50 border-purple-200 text-purple-800'
                    : delivered >= 5
                    ? 'bg-blue-50 border-blue-200 text-blue-800'
                    : delivered >= 1
                    ? 'bg-teal-50 border-teal-200 text-teal-800'
                    : 'bg-gray-50 border-gray-200 text-gray-700';

                  const iconColor = delivered >= 10
                    ? 'text-purple-600'
                    : delivered >= 5
                    ? 'text-blue-600'
                    : delivered >= 1
                    ? 'text-teal-600'
                    : 'text-gray-500';

                  return (
                    <div className={`flex items-center gap-1.5 rounded-xl px-3 py-1.5 border ${badgeColor}`}>
                      <BadgeCheck className={`w-4 h-4 ${iconColor}`} />
                      <span className="text-xs font-black">
                        {delivered === 0 ? displayLabel : `Delivered: ${displayLabel}`}
                        {delivered > 0 && (
                          <span className="text-[10px] font-semibold opacity-70 ml-0.5">
                            {delivered === 1 ? 'Project' : 'Projects'}
                          </span>
                        )}
                      </span>
                    </div>
                  );
                })()}

                {/* 3. Trust Score */}
                {typeof project.highriseScore === 'number' && project.highriseScore > 0 && (
                  <div className="flex items-center gap-1.5 bg-[#029bba]/10 border border-[#029bba]/20
                                  rounded-xl px-3 py-1.5">
                    <TrendingUp className="w-4 h-4 text-[#029bba]" />
                    <span className="text-xs font-black text-[#029bba]">
                      Trust Score: {project.highriseScore}/100
                    </span>
                  </div>
                )}

              </div>
            </div>

            {/* ── RIGHT: Developer Logo Card + Actions ── */}
            <div className="flex flex-col items-end gap-3 flex-shrink-0">

              {/* Developer Logo Card — NO website link (engagement lock) */}
              <Link
                href={`/developers/${project.developer ?? project.developerId ?? ''}`}
                className="flex items-center gap-3 px-4 py-3 bg-white border border-gray-200
                           rounded-2xl hover:border-[#029bba]/30 hover:shadow-md
                           transition-all group min-w-[220px]"
                aria-label={`View ${developerName} developer profile`}
              >
                {project.developerProfile?.logoUrl ? (
                  <div className="w-12 h-12 rounded-xl bg-white overflow-hidden
                                  border border-gray-100 relative flex-shrink-0">
                    <Image
                      src={project.developerProfile.logoUrl}
                      alt={`${developerName} logo`}
                      fill
                      className="object-contain p-1"
                      sizes="48px"
                    />
                  </div>
                ) : (
                  <div className="w-12 h-12 rounded-xl bg-gray-100 flex items-center
                                  justify-center flex-shrink-0">
                    <Building2 className="w-6 h-6 text-gray-400" />
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <p className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">
                    Developed by
                  </p>
                  <p className="text-sm font-black text-gray-900 truncate
                                group-hover:text-[#029bba] transition-colors">
                    {developerName}
                  </p>
                  <p className="text-[10px] text-[#029bba] font-bold flex items-center gap-0.5">
                    <Sparkles className="w-2.5 h-2.5" />
                    View Full Profile →
                  </p>
                </div>
              </Link>

              {/* Action Buttons */}
              <div className="flex items-center gap-2">

                {/* Save */}
                <button
                  onClick={() => void toggleFavorite(project._id, 'project')}
                  disabled={favPending}
                  aria-label={isFavorited ? 'Remove from shortlist' : 'Save to shortlist'}
                  aria-pressed={isFavorited}
                  className={`p-2.5 rounded-xl transition-all duration-200 ${
                    isFavorited
                      ? 'bg-[#029bba] text-white shadow-md shadow-[#029bba]/30'
                      : 'bg-gray-100 hover:bg-gray-200 text-gray-600'
                  } ${favPending ? 'opacity-60 cursor-wait' : ''}`}
                >
                  <Heart className={`w-4 h-4 ${isFavorited ? 'fill-current' : ''}`} />
                </button>

                {/* Compare */}
                <button
                  onClick={() => void toggleCompare(project._id, 'project')}
                  disabled={comparePending}
                  aria-label={isCompared ? 'Remove from comparison' : 'Add to comparison'}
                  aria-pressed={isCompared}
                  className={`p-2.5 rounded-xl transition-all duration-200 ${
                    isCompared
                      ? 'bg-[#004063] text-white shadow-md shadow-[#004063]/30'
                      : 'bg-gray-100 hover:bg-gray-200 text-gray-600'
                  } ${comparePending ? 'opacity-60 cursor-wait' : ''}`}
                >
                  <GitCompare className="w-4 h-4" />
                </button>

                {/* Share */}
                <button
                  onClick={() => setShareOpen(true)}
                  aria-label="Share this project"
                  className="p-2.5 rounded-xl bg-gray-100 hover:bg-gray-200
                             text-gray-600 transition-colors"
                >
                  <Share2 className="w-4 h-4" />
                </button>

              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ══════════════════════════════════════
          4. STATS BAR — Price | Size | Start | Possession | Progress
      ══════════════════════════════════════ */}
      <StatsBar
        project={project}
        overallMinPrice={overallMinPrice}
        overallMaxPrice={overallMaxPrice}
        minAreaSqft={minAreaSqft}
        maxAreaSqft={maxAreaSqft}
        onInquiry={handleInquiry}
        onDownload={handleDownload}
      />

      {/* TrustBadgesStrip removed (Wave 5A polish)
          Rationale: Verified + Trust Score already shown in title row.
          Zero Buyer Commission moved to sticky footer bar if needed.
          Reduces visual clutter, improves conversion focus. */}

      {/* ══════════════════════════════════════
          MODALS
      ══════════════════════════════════════ */}

      {/* Share Modal — Sprint 1 */}
      <ShareMenu
        project={listingShape}
        isOpen={shareOpen}
        onClose={() => setShareOpen(false)}
      />

      {/* Auth Gate Modal — Wave 5A */}
      <AuthGateModal
        isOpen={authGateOpen}
        onClose={closeAuthGate}
        actionDescription={gateContext.actionDescription}
        entityTitle={gateContext.entityTitle}
      />

      {/* Inquiry Modal — protected by AuthGate above */}
      <UniversalInquiryModal
        isOpen={inquiryOpen}
        onClose={() => setInquiryOpen(false)}
        entityType="project"
        entityId={project._id}
        entityTitle={project.projectName}
        entityPrice={overallMinPrice}
        entityLocation={`${area}, ${project.city}`}
        entityImage={primaryImage}
        developerId={project.developer}
        developerName={developerName}
        leadType={inquiryType}
        buttonText={
          inquiryType === 'site_visit'
            ? 'Schedule Visit'
            : inquiryType === 'call_back'
            ? 'Request Callback'
            : 'Send Inquiry'
        }
      />
    </>
  );
}

/**
 * components/project-detail/ProjectHighlights.tsx
 *
 * Highrise.pk — Project Highlights Section (Wave 5B)
 *
 * Purpose:
 *   Quick 5-second scan of project's key selling points.
 *   Auto-detects iconic features from amenities + project data.
 *
 * Features:
 *   → Grid of 8-12 highlights with icons
 *   → Smart auto-detection from project.amenitiesDetailed
 *   → Fallback to universal amenities if none provided
 *   → Responsive: 2 cols mobile → 3 cols tablet → 4 cols desktop
 *   → Icon mapping (25+ amenity types)
 *   → Featured highlight badges (Premium, Exclusive, etc.)
 *
 * Rules:
 *   → Tailwind only (zero inline styles)
 *   → Lucide React icons only
 *   → No framer-motion (CSS transitions only)
 *   → Mobile-first (375px min)
 *   → Guest-first (no login required)
 *
 * SEO:
 *   → Semantic <section> with heading hierarchy
 *   → aria-label on each highlight
 *
 * SECURITY:
 *   → No user HTML rendered (uses safe icon mapping)
 *   → No external links
 */

'use client';

import React from 'react';
import {
  Sparkles,
  Waves,          // Swimming Pool
  Dumbbell,       // Gym
  Shield,         // Security
  Car,            // Parking
  Zap,            // Backup Power
  Trees,          // Garden
  Star,           // Mosque
  Wifi,           // Internet
  Building,       // Elevator
  Film,           // Cinema
  Baby,           // Kids Play
  MapPin,         // Location
  Cctv,           // CCTV
  Utensils,       // Restaurant
  ShoppingBag,    // Shopping
  Coffee,         // Cafe
  Briefcase,      // Business
  Heart,          // Health
  BookOpen,       // Library
  Users,          // Community
  Lock,           // Security Gate
  Sun,            // Rooftop
  Home,           // Duplex
  Store,          // Retail
  Flame,          // Fire Safety
  DoorClosed,     // Concierge
  ArrowUpDown,    // High-Speed Elevator
  Phone,          // Intercom
  Snowflake,      // Central AC
  Award,          // Premium
  CheckCircle2,   // Generic
} from 'lucide-react';

import type { ProjectDetailData, AmenityItem } from '@/types/projectDetail';

// ─────────────────────────────────────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────────────────────────────────────

interface ProjectHighlightsProps {
  project: ProjectDetailData;
}

interface Highlight {
  id:       string;
  label:    string;
  icon:     React.ReactElement;
  featured?: boolean;
}

// ─────────────────────────────────────────────────────────────────────────────
// AMENITY → ICON MAPPING
// Maps common amenity keywords to Lucide icons
// ─────────────────────────────────────────────────────────────────────────────

const AMENITY_ICON_MAP: { keywords: string[]; icon: React.ReactElement; color: string }[] = [
  // Water
  { keywords: ['pool', 'swimming', 'jacuzzi'],       icon: <Waves className="w-5 h-5" />,       color: 'text-blue-600' },
  // Fitness
  { keywords: ['gym', 'fitness', 'workout'],          icon: <Dumbbell className="w-5 h-5" />,     color: 'text-red-600' },
  // Security
  { keywords: ['security', 'guard', 'patrol'],        icon: <Shield className="w-5 h-5" />,       color: 'text-emerald-600' },
  { keywords: ['cctv', 'surveillance', 'camera'],     icon: <Cctv className="w-5 h-5" />,         color: 'text-purple-600' },
  { keywords: ['gate', 'gated'],                       icon: <Lock className="w-5 h-5" />,         color: 'text-slate-600' },
  // Parking
  { keywords: ['parking', 'garage', 'basement park'], icon: <Car className="w-5 h-5" />,          color: 'text-gray-700' },
  // Power
  { keywords: ['backup', 'generator', 'power'],       icon: <Zap className="w-5 h-5" />,          color: 'text-amber-600' },
  // Nature
  { keywords: ['garden', 'landscape', 'green', 'park'], icon: <Trees className="w-5 h-5" />,      color: 'text-green-700' },
  { keywords: ['rooftop', 'terrace'],                  icon: <Sun className="w-5 h-5" />,          color: 'text-orange-600' },
  // Spiritual
  { keywords: ['mosque', 'prayer', 'jamat'],          icon: <Star className="w-5 h-5" />,         color: 'text-teal-600' },
  // Tech
  { keywords: ['wifi', 'internet', 'fiber'],          icon: <Wifi className="w-5 h-5" />,         color: 'text-cyan-600' },
  { keywords: ['intercom', 'phone'],                   icon: <Phone className="w-5 h-5" />,        color: 'text-indigo-600' },
  // Elevator
  { keywords: ['elevator', 'lift', 'escalator'],      icon: <ArrowUpDown className="w-5 h-5" />,  color: 'text-blue-700' },
  // Entertainment
  { keywords: ['cinema', 'theater', 'movie'],         icon: <Film className="w-5 h-5" />,         color: 'text-pink-600' },
  // Family
  { keywords: ['kids', 'children', 'play'],           icon: <Baby className="w-5 h-5" />,         color: 'text-rose-600' },
  { keywords: ['community', 'club', 'lounge'],        icon: <Users className="w-5 h-5" />,        color: 'text-violet-600' },
  // Business
  { keywords: ['business', 'office', 'meeting', 'conference'], icon: <Briefcase className="w-5 h-5" />, color: 'text-slate-700' },
  // Retail / Food
  { keywords: ['retail', 'shop', 'mall'],             icon: <Store className="w-5 h-5" />,        color: 'text-purple-600' },
  { keywords: ['restaurant', 'dining', 'food court'], icon: <Utensils className="w-5 h-5" />,     color: 'text-orange-700' },
  { keywords: ['shopping'],                            icon: <ShoppingBag className="w-5 h-5" />,  color: 'text-pink-700' },
  { keywords: ['cafe', 'coffee'],                     icon: <Coffee className="w-5 h-5" />,       color: 'text-amber-700' },
  // Health
  { keywords: ['health', 'clinic', 'medical', 'spa'], icon: <Heart className="w-5 h-5" />,        color: 'text-red-700' },
  // Reading
  { keywords: ['library', 'reading'],                 icon: <BookOpen className="w-5 h-5" />,     color: 'text-blue-800' },
  // Fire safety
  { keywords: ['fire', 'sprinkler'],                  icon: <Flame className="w-5 h-5" />,        color: 'text-red-600' },
  // Concierge
  { keywords: ['concierge', 'doorman', 'reception'],  icon: <DoorClosed className="w-5 h-5" />,   color: 'text-indigo-700' },
  // AC
  { keywords: ['ac', 'air conditioning', 'central cooling'], icon: <Snowflake className="w-5 h-5" />, color: 'text-sky-600' },
];

/**
 * Match amenity name to icon
 */
function getIconForAmenity(name: string): { icon: React.ReactElement; color: string } {
  const lower = name.toLowerCase();

  for (const mapping of AMENITY_ICON_MAP) {
    if (mapping.keywords.some(kw => lower.includes(kw))) {
      return { icon: mapping.icon, color: mapping.color };
    }
  }

  // Fallback icon
  return {
    icon:  <CheckCircle2 className="w-5 h-5" />,
    color: 'text-[#029bba]',
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// AUTO-DETECT HIGHLIGHTS FROM PROJECT DATA
// ─────────────────────────────────────────────────────────────────────────────

function buildHighlights(project: ProjectDetailData): Highlight[] {
  const highlights: Highlight[] = [];
  const seenLabels = new Set<string>();

  // ── Add unique amenities ──
  const amenities = project.amenitiesDetailed ?? [];
  for (const amenity of amenities) {
    if (highlights.length >= 12) break;
    if (!amenity.name || seenLabels.has(amenity.name.toLowerCase())) continue;

    seenLabels.add(amenity.name.toLowerCase());
    const { icon } = getIconForAmenity(amenity.name);

    highlights.push({
      id:    `amenity-${highlights.length}`,
      label: amenity.name,
      icon:  React.cloneElement(
        icon as React.ReactElement<{ className?: string }>,
        { className: 'w-5 h-5' },
      ),
    });
  }

  // ── Add universal Highrise highlights if we have space ──
  const universalHighlights = [
    {
      condition: project.isVerified,
      label:    'Highrise Verified',
      icon:     <Award className="w-5 h-5" />,
      featured: true,
    },
    {
      condition: project.isTrustedBuilder,
      label:    'Trusted Builder',
      icon:     <Shield className="w-5 h-5" />,
      featured: true,
    },
    {
      condition: (project.nocStatus ?? '').toLowerCase() === 'approved',
      label:    'NOC Approved',
      icon:     <CheckCircle2 className="w-5 h-5" />,
      featured: true,
    },
    {
      condition: true, // Always show
      label:    'Zero Buyer Commission',
      icon:     <Heart className="w-5 h-5" />,
      featured: true,
    },
  ];

  for (const uh of universalHighlights) {
    if (highlights.length >= 12) break;
    if (uh.condition && !seenLabels.has(uh.label.toLowerCase())) {
      seenLabels.add(uh.label.toLowerCase());
      highlights.push({
        id:       `universal-${highlights.length}`,
        label:    uh.label,
        icon:     uh.icon,
        featured: uh.featured,
      });
    }
  }

  return highlights;
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN COMPONENT
// ─────────────────────────────────────────────────────────────────────────────

export default function ProjectHighlights({ project }: ProjectHighlightsProps) {
  const highlights = buildHighlights(project);

  // Hide section if no highlights
  if (highlights.length === 0) return null;

  return (
    <section
