// ─── PAGINATION ───────────────────────────────────────────────────────────────

function Pagination({
  currentPage,
  totalPages,
  onPageChange,
}: {
  currentPage:  number;
  totalPages:   number;
  onPageChange: (page: number) => void;
}): React.ReactElement | null {
  if (totalPages <= 1) return null;

  // Show max 7 page numbers with smart truncation
  const getPageNumbers = (): (number | 'gap')[] => {
    const pages: (number | 'gap')[] = [];

    if (totalPages <= 7) {
      // Show all pages
      for (let i = 1; i <= totalPages; i++) pages.push(i);
      return pages;
    }

    // Always show first page
    pages.push(1);

    // Add gap before current if needed
    if (currentPage > 4) pages.push('gap');

    // Show current and neighbors
    const start = Math.max(2, currentPage - 1);
    const end   = Math.min(totalPages - 1, currentPage + 1);
    for (let i = start; i <= end; i++) pages.push(i);

    // Add gap after current if needed
    if (currentPage < totalPages - 3) pages.push('gap');

    // Always show last page
    if (totalPages > 1) pages.push(totalPages);

    return pages;
  };

  const pageNumbers = getPageNumbers();

  return (
    <nav
      className="flex items-center justify-center gap-1 mt-8"
      aria-label="Pagination"
    >
      {/* Previous button */}
      <button
        type="button"
        onClick={() => currentPage > 1 && onPageChange(currentPage - 1)}
        disabled={currentPage === 1}
        aria-label="Previous page"
        className="inline-flex items-center gap-1 px-3 py-2 rounded-xl
                   text-sm font-bold border-2 border-gray-200
                   text-gray-600 hover:border-[#029bba] hover:text-[#029bba]
                   transition-colors duration-200
                   disabled:opacity-40 disabled:cursor-not-allowed
                   disabled:hover:border-gray-200 disabled:hover:text-gray-600
                   focus:outline-none focus:ring-2 focus:ring-[#029bba]/30"
      >
        <ChevronLeft className="w-4 h-4" />
        <span className="hidden sm:inline">Previous</span>
      </button>

      {/* Page numbers */}
      {pageNumbers.map((page, i) => {
        if (page === 'gap') {
          return (
            <span
              key={`gap-${i}`}
              className="px-2 text-gray-400"
              aria-hidden="true"
            >
              …
            </span>
          );
        }

        const isActive = page === currentPage;

        return (
          <button
            key={page}
            type="button"
            onClick={() => onPageChange(page)}
            aria-current={isActive ? 'page' : undefined}
            aria-label={`Page ${page}`}
            className={`min-w-[40px] h-10 rounded-xl text-sm font-bold
                       transition-all duration-200
                       focus:outline-none focus:ring-2 focus:ring-[#029bba]/30 ${
              isActive
                ? 'bg-[#029bba] text-white shadow-md scale-105'
                : 'bg-white border-2 border-gray-200 text-gray-700 hover:border-[#029bba] hover:text-[#029bba]'
            }`}
          >
            {page}
          </button>
        );
      })}

      {/* Next button */}
      <button
        type="button"
        onClick={() => currentPage < totalPages && onPageChange(currentPage + 1)}
        disabled={currentPage === totalPages}
        aria-label="Next page"
        className="inline-flex items-center gap-1 px-3 py-2 rounded-xl
                   text-sm font-bold border-2 border-gray-200
                   text-gray-600 hover:border-[#029bba] hover:text-[#029bba]
                   transition-colors duration-200
                   disabled:opacity-40 disabled:cursor-not-allowed
                   disabled:hover:border-gray-200 disabled:hover:text-gray-600
                   focus:outline-none focus:ring-2 focus:ring-[#029bba]/30"
      >
        <span className="hidden sm:inline">Next</span>
        <ChevronRight className="w-4 h-4" />
      </button>
    </nav>
  );
}

// ─── MAIN COMPONENT ───────────────────────────────────────────────────────────

export function MainProjectGrid({
  filters,
  updateFilters,
  initialProjects,
  totalCount,
}: MainProjectGridProps): React.ReactElement {

  const router = useRouter();

  // ── State ──────────────────────────────────────────────────
  const [loadedProjects, setLoadedProjects] = useState<ProjectListing[]>(initialProjects);
  const [loadMoreCount, setLoadMoreCount]   = useState(0);
  const [loading, setLoading]                = useState(false);
  const [error, setError]                    = useState<string | null>(null);
  const [viewMode, setViewMode]              = useState<GridViewMode>('grid');

  // ── Derived state ──────────────────────────────────────────
  const currentPage    = filters.page || 1;
  const totalPages     = Math.ceil(totalCount / PROJECTS_PER_PAGE);
  const showingCount   = loadedProjects.length;
  const rangeStart     = totalCount > 0 ? (currentPage - 1) * PROJECTS_PER_PAGE + 1 : 0;
  const rangeEnd       = rangeStart + showingCount - 1;
  const remainingCount = totalCount - (rangeStart - 1 + showingCount);

  // Show pagination after 3 Load More clicks OR if starting on page 2+
  const showPagination = loadMoreCount >= MAX_LOAD_MORE_CLICKS
                          || currentPage > 1
                          || (totalPages > 1 && remainingCount === 0);

  // Show Load More if there are more results AND haven't hit max clicks
  const showLoadMore = !showPagination
                        && remainingCount > 0
                        && loadMoreCount < MAX_LOAD_MORE_CLICKS;

  // ── City-aware header ──────────────────────────────────────
  const cityLabel = filters.city ? ` in ${filters.city}` : ' Across Pakistan';

  // ── Sort change handler ────────────────────────────────────
  const handleSortChange = useCallback((sort: SortOption) => {
    updateFilters({ sort, page: 1 });
    setLoadMoreCount(0);
  }, [updateFilters]);

  // ── Page change handler (pagination) ───────────────────────
  const handlePageChange = useCallback((page: number) => {
    updateFilters({ page });
    setLoadMoreCount(0);
    // Scroll to top of grid
    setTimeout(() => {
      document.getElementById('main-project-grid')
        ?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 200);
  }, [updateFilters]);

  // ── Load More handler ──────────────────────────────────────
  const handleLoadMore = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const nextPage = currentPage + loadMoreCount + 1;

      const response = await fetch('/api/projects/list', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify({
          city:         filters.city,
          category:     filters.category,
          nature:       filters.nature,
          type:         filters.type,
          minBudget:    filters.minBudget,
          maxBudget:    filters.maxBudget,
          minArea:      filters.minArea,
          maxArea:      filters.maxArea,
          possession:   filters.possession,
          noc:          filters.noc,
          installments: filters.installments,
          locality:     filters.locality,
          builder:      filters.builder,
          sort:         filters.sort,
          page:         nextPage,
        }),
      });

      if (!response.ok) {
        throw new Error(`Request failed: ${response.status}`);
      }

      const data = (await response.json()) as ProjectListResponse;

      if (!data.success) {
        throw new Error(data.error ?? 'Failed to load more projects');
      }

      // Append new projects to loaded set
      setLoadedProjects(prev => [...prev, ...data.projects]);
      setLoadMoreCount(prev => prev + 1);

    } catch (err) {
      // eslint-disable-next-line no-console
      console.error('[MainProjectGrid] Load more failed:', err);
      setError('Unable to load more projects. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [
    filters.city, filters.category, filters.nature, filters.type,
    filters.minBudget, filters.maxBudget, filters.minArea, filters.maxArea,
    filters.possession, filters.noc, filters.installments,
    filters.locality, filters.builder, filters.sort,
    currentPage, loadMoreCount,
  ]);

  // ── Back to top handler ────────────────────────────────────
  const handleBackToTop = useCallback(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  // ── Reset loaded projects when filters change (SSR re-fetch) ─
  // The parent page does a full SSR re-run on filter change,
  // so initialProjects updates. But we need to sync local state.
  const initialIds = useMemo(
    () => initialProjects.map(p => p._id).join(','),
    [initialProjects],
  );

  React.useEffect(() => {
    setLoadedProjects(initialProjects);
    setLoadMoreCount(0);
    setError(null);
  }, [initialIds]); // eslint-disable-line react-hooks/exhaustive-deps

  // ─────────────────────────────────────────────────────────────

  return (
    <section
      id="main-project-grid"
      aria-labelledby="main-grid-heading"
      className="relative bg-gray-50 py-16 md:py-20 overflow-hidden"
    >
      {/* Subtle background decoration */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-0 right-1/4 w-96 h-96
                        bg-[#029bba]/[0.03] rounded-full blur-3xl" />
      </div>

      <div className="relative max-w-7xl mx-auto px-4">

        {/* ── SECTION HEADER (locked typography) ────────────── */}
        <div className="text-center max-w-2xl mx-auto mb-10">

          {/* Pill with divider lines */}
          <div className="inline-flex items-center gap-3 mb-4">
            <span className="h-px w-8 bg-gradient-to-r
                             from-transparent to-[#029bba]" />
            <span
              className="text-xs font-black text-[#029bba]
                         uppercase tracking-[0.2em]"
            >
              All Verified Projects
            </span>
            <span className="h-px w-8 bg-gradient-to-l
                             from-transparent to-[#029bba]" />
          </div>

          {/* H2 — locked: text-3xl md:text-4xl */}
          <h2
            id="main-grid-heading"
            className="text-3xl md:text-4xl font-black text-gray-900
                       mb-3 tracking-tight leading-tight"
          >
            Every Verified{' '}
            <span
              className="text-transparent bg-clip-text
                         bg-gradient-to-r from-[#029bba] to-[#017a94]"
            >
              Project{cityLabel}
            </span>
          </h2>

          <p className="text-base text-gray-500 leading-relaxed">
            {totalCount > 0 ? (
              <>
                <span className="font-bold text-gray-700">
                  {totalCount.toLocaleString()}
                </span>
                {' '}shield-verified project{totalCount !== 1 ? 's' : ''} —
                every listing manually checked by our team.
              </>
            ) : (
              'No projects match your current filters — try adjusting to see more.'
            )}
          </p>
        </div>

        {/* ── CONTROLS BAR (sort + view + count) ─────────────── */}
        {totalCount > 0 && (
          <div className="bg-white rounded-2xl border border-gray-100
                          shadow-sm p-4 mb-6
                          flex flex-col md:flex-row items-start md:items-center
                          justify-between gap-3">

            {/* Left: Showing count */}
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <span className="font-semibold">Showing</span>
              <span className="font-black text-gray-900">
                {rangeStart}-{Math.min(rangeStart + showingCount - 1, totalCount)}
              </span>
              <span className="font-semibold">of</span>
              <span className="font-black text-[#029bba]">
                {totalCount.toLocaleString()}
              </span>
              <span className="font-semibold">
                project{totalCount !== 1 ? 's' : ''}
              </span>
            </div>

            {/* Right: Sort + View Mode */}
            <div className="flex items-center gap-2 flex-wrap">
              <SortDropdown
                value={filters.sort}
                onChange={handleSortChange}
              />
              <ViewModeToggle
                mode={viewMode}
                onChange={setViewMode}
              />
            </div>
          </div>
        )}

        {/* ── EMPTY STATE ────────────────────────────────────── */}
        {totalCount === 0 && (
          <EmptyState filters={filters} updateFilters={updateFilters} />
        )}

        {/* ── GRID ──────────────────────────────────────────── */}
        {loadedProjects.length > 0 && (
          <>
            <div
              className={
                viewMode === 'grid'
                  ? 'grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-5'
                  : 'grid grid-cols-1 gap-4'
              }
              role="list"
              aria-label="Project listings"
            >
              {loadedProjects.map(project => (
                <div key={project._id} role="listitem">
                  <ProjectListingCard
                    project={project}
                    variant={viewMode === 'list' ? 'list' : 'grid'}
                  />
                </div>
              ))}

              {/* Skeleton loaders during Load More */}
              {loading && (
                <>
                  {Array.from({ length: 4 }).map((_, i) => (
                    <SkeletonCard key={`skeleton-${i}`} />
                  ))}
                </>
              )}
            </div>

            {/* Error message */}
            {error && (
              <div className="mt-6 p-4 bg-red-50 border border-red-200
                              rounded-2xl text-center">
                <p className="text-sm text-red-700 font-semibold mb-2">
                  {error}
                </p>
                <button
                  type="button"
                  onClick={handleLoadMore}
                  className="text-sm text-red-600 font-bold underline
                             hover:text-red-800 focus:outline-none"
                >
                  Try again
                </button>
              </div>
            )}

            {/* ── LOAD MORE BUTTON ────────────────────────────── */}
            {showLoadMore && !loading && (
              <div className="mt-8 text-center">
                <button
                  type="button"
                  onClick={handleLoadMore}
                  className="inline-flex items-center gap-2 px-8 py-3.5 rounded-xl
                             bg-[#029bba] text-white text-sm font-black
                             hover:bg-[#017a94] hover:shadow-lg hover:-translate-y-0.5
                             transition-all duration-200
                             focus:outline-none focus:ring-2 focus:ring-[#029bba]/50"
                >
                  <ArrowDown className="w-4 h-4" />
                  Load More Projects
                  <span className="opacity-80">
                    ({remainingCount.toLocaleString()} remaining)
                  </span>
                </button>

                <p className="text-xs text-gray-400 mt-3">
                  Showing {showingCount} of {totalCount} · {loadMoreCount + 1} of {MAX_LOAD_MORE_CLICKS} loads
                </p>
              </div>
            )}

            {/* Load More loading state */}
            {loading && (
              <div className="mt-8 text-center">
                <div className="inline-flex items-center gap-2 px-6 py-3
                                text-sm font-bold text-[#029bba]">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Loading more projects...
                </div>
              </div>
            )}

            {/* ── PAGINATION ──────────────────────────────────── */}
            {showPagination && (
              <>
                <Pagination
                  currentPage={currentPage}
                  totalPages={totalPages}
                  onPageChange={handlePageChange}
                />

                {/* Back to top button (after 2+ pages) */}
                {currentPage >= 2 && (
                  <div className="mt-6 text-center">
                    <button
                      type="button"
                      onClick={handleBackToTop}
                      className="inline-flex items-center gap-1.5 text-xs font-bold
                                 text-gray-500 hover:text-[#029bba]
                                 transition-colors duration-200
                                 focus:outline-none focus:ring-2
                                 focus:ring-[#029bba]/30 rounded px-2 py-1"
                    >
                      <ArrowUpToLine className="w-3.5 h-3.5" />
                      Back to top
                    </button>
                  </div>
                )}
              </>
            )}

            {/* End of results indicator (no more to load, no pagination) */}
            {!showLoadMore && !showPagination && totalCount > 0 && !loading && (
              <div className="mt-8 text-center">
                <div className="inline-flex items-center gap-2 px-4 py-2
                                text-xs font-bold text-gray-400
                                bg-white border border-gray-100 rounded-full">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                  You&apos;ve seen all {totalCount} project{totalCount !== 1 ? 's' : ''}
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </section>
  );
}

export default MainProjectGrid;

// components/projects/PaymentPlanCard.tsx
import React, { useState } from 'react';
import {
  DollarSign,
  Calendar,
  Clock,
  ChevronDown,
  ChevronUp,
  Star,
  BadgeCheck,
  Percent,
  Banknote,
  CreditCard,
  Building2,
  Info,
  ArrowRight,
  CheckCircle2,
  AlertTriangle,
  Tag,
  TrendingDown,
} from 'lucide-react';

// ════════════════════════════════════════════════════
// TYPES
// ════════════════════════════════════════════════════

export type PlanType =
  | 'standard'
  | 'easy_installment'
  | 'flexi'
  | 'down_payment'
  | 'full_payment'
  | 'custom';

export type ApplicableTo =
  | 'all_units'
  | 'residential'
  | 'commercial'
  | 'specific_types';

export interface InstallmentBreakdown {
  label:       string;
  amount:      number;
  percentage?: number;
  dueDate?:    string;
  dueAfter?:   string;
  frequency?:  string;
  count?:      number;
  notes?:      string;
}

export interface PaymentPlanData {
  _id?:                  string;
  name:                  string;
  description?:          string;
  planType:              PlanType;
  applicableTo?:         ApplicableTo;
  unitTypes?:            string[];
  totalPrice?:           number;
  currency?:             string;
  bookingAmount?:        number;
  bookingPercent?:       number;
  downPayment?:          number;
  downPaymentPercent?:   number;
  downPaymentDueIn?:     string;
  installments?:         InstallmentBreakdown[];
  possessionAmount?:     number;
  possessionPercent?:    number;
  planDuration?:         number;
  planDurationUnit?:     string;
  earlyPaymentDiscount?: number;
  fullPaymentDiscount?:  number;
  bulkBookingDiscount?:  number;
  validFrom?:            string;
  validUntil?:           string;
  isActive?:             boolean;
  isDefault?:            boolean;
  isFeatured?:           boolean;
  termsAndConditions?:   string;
  disclaimers?:          string;
}

export type PaymentPlanCardVariant = 'full' | 'compact' | 'comparison';

interface PaymentPlanCardProps {
  plan:        PaymentPlanData;
  variant?:    PaymentPlanCardVariant;
  onInquire?:  (planName: string) => void;
  className?:  string;
}

// ════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════

function formatPKR(amount: number): string {
  if (!amount || amount <= 0) return 'N/A';
  if (amount >= 10_000_000) {
    const crore = amount / 10_000_000;
    return `PKR ${crore % 1 === 0 ? crore.toFixed(0) : crore.toFixed(2)} Crore`;
  }
  if (amount >= 100_000) {
    const lac = amount / 100_000;
    return `${lac % 1 === 0 ? lac.toFixed(0) : lac.toFixed(1)} Lac`;
  }
  return `PKR ${amount.toLocaleString()}`;
}

function formatAmount(amount: number): string {
  if (!amount || amount <= 0) return '—';
  if (amount >= 10_000_000) {
    return `${(amount / 10_000_000).toFixed(2)} Cr`;
  }
  if (amount >= 100_000) {
    return `${(amount / 100_000).toFixed(1)} Lac`;
  }
  return amount.toLocaleString();
}

function getPlanTypeConfig(planType: PlanType): {
  label:    string;
  icon:     React.ReactElement;
  bg:       string;
  text:     string;
  border:   string;
} {
  const configs: Record<PlanType, {
    label:  string;
    icon:   React.ReactElement;
    bg:     string;
    text:   string;
    border: string;
  }> = {
    standard: {
      label:  'Standard Plan',
      icon:   <CreditCard className="w-4 h-4" />,
      bg:     'bg-blue-50',
      text:   'text-blue-700',
      border: 'border-blue-200',
    },
    easy_installment: {
      label:  'Easy Installment',
      icon:   <Calendar className="w-4 h-4" />,
      bg:     'bg-emerald-50',
      text:   'text-emerald-700',
      border: 'border-emerald-200',
    },
    flexi: {
      label:  'Flexi Plan',
      icon:   <TrendingDown className="w-4 h-4" />,
      bg:     'bg-purple-50',
      text:   'text-purple-700',
      border: 'border-purple-200',
    },
    down_payment: {
      label:  'Down Payment Plan',
      icon:   <Banknote className="w-4 h-4" />,
      bg:     'bg-amber-50',
      text:   'text-amber-700',
      border: 'border-amber-200',
    },
    full_payment: {
      label:  'Full Payment',
      icon:   <DollarSign className="w-4 h-4" />,
      bg:     'bg-green-50',
      text:   'text-green-700',
      border: 'border-green-200',
    },
    custom: {
      label:  'Custom Plan',
      icon:   <Building2 className="w-4 h-4" />,
      bg:     'bg-gray-50',
      text:   'text-gray-700',
      border: 'border-gray-200',
    },
  };

  return configs[planType] ?? configs.custom;
}

function getFrequencyLabel(frequency?: string): string {
  const labels: Record<string, string> = {
    one_time:      'One-Time',
    monthly:       'Monthly',
    quarterly:     'Quarterly',
    half_yearly:   'Half-Yearly',
    yearly:        'Yearly',
    on_possession: 'On Possession',
  };
  return frequency ? labels[frequency] ?? frequency : '';
}

function getApplicableLabel(applicableTo?: ApplicableTo): string {
  const labels: Record<ApplicableTo, string> = {
    all_units:       'All Units',
    residential:     'Residential Only',
    commercial:      'Commercial Only',
    specific_types:  'Specific Unit Types',
  };
  return applicableTo ? labels[applicableTo] ?? 'All Units' : 'All Units';
}

function hasDiscounts(plan: PaymentPlanData): boolean {
  return (
    (plan.earlyPaymentDiscount ?? 0) > 0 ||
    (plan.fullPaymentDiscount ?? 0) > 0 ||
    (plan.bulkBookingDiscount ?? 0) > 0
  );
}

// ════════════════════════════════════════════════════
// INSTALLMENT BREAKDOWN TABLE
// ════════════════════════════════════════════════════

function BreakdownTable({
  installments,
}: {
  installments: InstallmentBreakdown[];
}): React.ReactElement {
  return (
    <div className="mt-4 rounded-xl border border-gray-100 overflow-hidden">
      <table className="w-full text-sm">
        <thead>
          <tr className="bg-gray-50">
            <th className="text-left px-3 py-2 text-xs font-bold text-gray-500 uppercase tracking-wide">
              Payment
            </th>
            <th className="text-right px-3 py-2 text-xs font-bold text-gray-500 uppercase tracking-wide">
              Amount
            </th>
            <th className="text-right px-3 py-2 text-xs font-bold text-gray-500 uppercase tracking-wide hidden sm:table-cell">
              Frequency
            </th>
            <th className="text-right px-3 py-2 text-xs font-bold text-gray-500 uppercase tracking-wide hidden sm:table-cell">
              Duration
            </th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-50">
          {installments.map((inst, idx) => (
            <tr key={idx} className="hover:bg-gray-50/50 transition-colors">
              <td className="px-3 py-2.5">
                <p className="font-semibold text-gray-700">{inst.label}</p>
                {inst.notes && (
                  <p className="text-[10px] text-gray-400 mt-0.5">{inst.notes}</p>
                )}
                {inst.dueDate && (
                  <p className="text-[10px] text-gray-400 mt-0.5">
                    Due: {inst.dueDate}
                  </p>
                )}
                {inst.dueAfter && (
                  <p className="text-[10px] text-gray-400 mt-0.5">
                    Due after: {inst.dueAfter}
                  </p>
                )}
              </td>
              <td className="px-3 py-2.5 text-right">
                <p className="font-bold text-gray-900">{formatAmount(inst.amount)}</p>
                {inst.percentage !== undefined && inst.percentage > 0 && (
                  <p className="text-[10px] text-gray-400">{inst.percentage}%</p>
                )}
              </td>
              <td className="px-3 py-2.5 text-right hidden sm:table-cell">
                <span className="text-gray-500 text-xs">
                  {getFrequencyLabel(inst.frequency)}
                </span>
              </td>
              <td className="px-3 py-2.5 text-right hidden sm:table-cell">
                {inst.count && inst.count > 0 ? (
                  <span className="text-gray-500 text-xs">
                    {inst.count}x
                  </span>
                ) : (
                  <span className="text-gray-300 text-xs">—</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// ════════════════════════════════════════════════════
// DISCOUNT SECTION
// ════════════════════════════════════════════════════

function DiscountSection({
  plan,
}: {
  plan: PaymentPlanData;
}): React.ReactElement | null {
  if (!hasDiscounts(plan)) return null;

  return (
    <div className="mt-4 p-3 rounded-xl bg-green-50 border border-green-100">
      <p className="text-xs font-bold text-green-700 uppercase tracking-wide mb-2 flex items-center gap-1.5">
        <Percent className="w-3.5 h-3.5" />
        Available Discounts
      </p>
      <div className="space-y-1.5">
        {(plan.earlyPaymentDiscount ?? 0) > 0 && (
          <div className="flex items-center justify-between">
            <span className="text-xs text-green-600">Early Payment Discount</span>
            <span className="text-xs font-bold text-green-700">
              {plan.earlyPaymentDiscount}% OFF
            </span>
          </div>
        )}
        {(plan.fullPaymentDiscount ?? 0) > 0 && (
          <div className="flex items-center justify-between">
            <span className="text-xs text-green-600">Full Payment Discount</span>
            <span className="text-xs font-bold text-green-700">
              {plan.fullPaymentDiscount}% OFF
            </span>
          </div>
        )}
        {(plan.bulkBookingDiscount ?? 0) > 0 && (
          <div className="flex items-center justify-between">
            <span className="text-xs text-green-600">Bulk Booking Discount</span>
            <span className="text-xs font-bold text-green-700">
              {plan.bulkBookingDiscount}% OFF
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════
// COMPACT VARIANT
// ════════════════════════════════════════════════════

function CompactPlanCard({
  plan,
  onInquire,
  className,
}: {
  plan:       PaymentPlanData;
  onInquire?: (planName: string) => void;
  className?: string;
}): React.ReactElement {
  const typeConfig = getPlanTypeConfig(plan.planType);

  return (
    <div className={`bg-white rounded-2xl border border-gray-100 shadow-sm p-4
                     hover:shadow-md hover:border-[#029bba]/20 transition-all duration-200
                     ${plan.isDefault ? 'ring-2 ring-[#029bba]/20' : ''}
                     ${className ?? ''}`}>
      {/* Header */}
      <div className="flex items-start justify-between mb-3">
        <div className="flex items-center gap-2">
          <div className={`p-1.5 rounded-lg ${typeConfig.bg} ${typeConfig.text}`}>
            {typeConfig.icon}
          </div>
          <div>
            <h4 className="font-bold text-sm text-gray-900">{plan.name}</h4>
            <span className="text-[10px] text-gray-400">{typeConfig.label}</span>
          </div>
        </div>

        {plan.isDefault && (
          <span className="px-2 py-0.5 rounded-full bg-[#029bba] text-white
                           text-[10px] font-bold flex items-center gap-0.5">
            <Star className="w-3 h-3" /> Default
          </span>
        )}
      </div>

      {/* Key amounts */}
      <div className="grid grid-cols-2 gap-2 mb-3">
        {(plan.bookingAmount ?? 0) > 0 && (
          <div className="p-2 rounded-lg bg-gray-50">
            <p className="text-[10px] text-gray-400 font-semibold uppercase">Booking</p>
            <p className="text-sm font-bold text-gray-900">
              {formatAmount(plan.bookingAmount!)}
            </p>
          </div>
        )}
        {(plan.downPayment ?? 0) > 0 && (
          <div className="p-2 rounded-lg bg-gray-50">
            <p className="text-[10px] text-gray-400 font-semibold uppercase">Down Payment</p>
            <p className="text-sm font-bold text-gray-900">
              {formatAmount(plan.downPayment!)}
            </p>
          </div>
        )}
      </div>

      {/* Duration */}
      {plan.planDuration && (
        <div className="flex items-center gap-1.5 text-xs text-gray-500 mb-3">
          <Clock className="w-3 h-3" />
          {plan.planDuration} {plan.planDurationUnit ?? 'months'}
        </div>
      )}

      {/* CTA */}
      {onInquire && (
        <button
          onClick={() => onInquire(plan.name)}
          className="w-full flex items-center justify-center gap-2 py-2 rounded-xl
                     bg-gradient-to-r from-[#029bba] to-[#027a94]
                     text-white text-sm font-semibold
                     hover:from-[#02a8c9] hover:to-[#028aaa]
                     hover:shadow-lg transition-all duration-200"
        >
          Inquire About This Plan
          <ArrowRight className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  );
}

