          </label>
          <div className="relative">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500">
              Rs.
            </span>
            <Input
              name="whtFiler"
              type="text"
              placeholder="e.g., 3,00,000"
