  { icon: '🍳', label: 'Kitchen' },
  { icon: '🛏️', label: 'Each bedroom' },
  { icon: '🚿', label: 'Each bathroom' },
  { icon: '🌳', label: 'Lawn / Garden / Terrace' },
  { icon: '🅿️', label: 'Parking area' },
