interface InstallmentFieldsProps {
  form:                PropertyFormState;
  errors:              TabErrors;
  setInstallmentField: UsePropertyFormReturn['setInstallmentField'];
}

// ─── Frequency keys ───────────────────────────────────────────────────────────

type FreqKey = 'monthly' | 'quarterly' | 'halfYearly' | 'yearly';

const FREQ_CONFIG: Record<FreqKey, {
  label: string;
  description: string;
  divisor: number;
  unit: string;
  flagKey: 'hasMonthly' | 'hasQuarterly' | 'hasHalfYearly' | 'hasYearly';
  amountKey: 'monthlyAmount' | 'quarterlyAmount' | 'halfYearlyAmount' | 'yearlyAmount';
  countKey: 'monthlyCount' | 'quarterlyCount' | 'halfYearlyCount' | 'yearlyCount';
}> = {
  monthly: {
    label: 'Monthly',
    description: 'Every month',
    divisor: 1,
    unit: 'month',
    flagKey: 'hasMonthly',
    amountKey: 'monthlyAmount',
    countKey: 'monthlyCount',
  },
  quarterly: {
    label: 'Quarterly',
    description: 'Every 3 months',
    divisor: 3,
    unit: 'quarter',
    flagKey: 'hasQuarterly',
    amountKey: 'quarterlyAmount',
    countKey: 'quarterlyCount',
  },
  halfYearly: {
    label: 'Half-Yearly',
    description: 'Every 6 months',
    divisor: 6,
    unit: 'half-year',
    flagKey: 'hasHalfYearly',
    amountKey: 'halfYearlyAmount',
    countKey: 'halfYearlyCount',
  },
  yearly: {
    label: 'Yearly',
    description: 'Once per year (bonus payment)',
    divisor: 12,
    unit: 'year',
    flagKey: 'hasYearly',
    amountKey: 'yearlyAmount',
    countKey: 'yearlyCount',
  },
};

// ─── Quick Preset Plans (Pakistani market) ───────────────────────────────────

interface PresetPlan {
  label:        string;
  description:  string;
  booking:      number;
  downPayment:  number;
  possession:   number;
  duration:     number;
  frequencies:  Partial<Record<FreqKey, number>>;
}

const PRESET_PLANS: PresetPlan[] = [
  {
    label:        'DHA Standard',
    description:  '10% + 10% + 36 monthly + 10% possession',
    booking:      10,
    downPayment:  10,
    possession:   10,
    duration:     36,
    frequencies:  { monthly: 100 },
  },
  {
    label:        'Bahria Easy 3-Year',
    description:  '15% booking + 15% DP + monthly & yearly mix',
    booking:      15,
    downPayment:  15,
    possession:   10,
    duration:     36,
    frequencies:  { monthly: 70, yearly: 30 },
  },
  {
    label:        '5-Year Long Plan',
    description:  '10% + 10% + 60 monthly + 10% possession',
    booking:      10,
    downPayment:  10,
    possession:   10,
    duration:     60,
    frequencies:  { monthly: 100 },
  },
  {
    label:        'Quick 2-Year',
    description:  '20% + 20% + 24 monthly + 10% possession',
    booking:      20,
    downPayment:  20,
    possession:   10,
    duration:     24,
    frequencies:  { monthly: 100 },
  },
];

interface InstallmentFieldsProps {
  form:                PropertyFormState;
  errors:              TabErrors;
  setInstallmentField: UsePropertyFormReturn['setInstallmentField'];
}

function InstallmentFields({
  form, errors, setInstallmentField,
}: InstallmentFieldsProps): React.ReactElement {

  const plan  = form.installmentPlan;
  const total = safeNum(plan.totalPrice);

  // ─── Live computed amounts from percentages ────────────────────
  const bookingAmt = total > 0 ? Math.round((total * safeNum(plan.bookingPercent)) / 100) : 0;
  const dpAmt      = total > 0 ? Math.round((total * safeNum(plan.downPaymentPercent)) / 100) : 0;
  const possAmt    = total > 0 ? Math.round((total * safeNum(plan.possessionPercent)) / 100) : 0;
  const remaining  = Math.max(0, total - bookingAmt - dpAmt - possAmt);

  const usedPercent = safeNum(plan.bookingPercent) +
                      safeNum(plan.downPaymentPercent) +
                      safeNum(plan.possessionPercent);
  const remainingPercent = Math.max(0, 100 - usedPercent);
  const isMilestoneOverflow = usedPercent > 100;

  // Sync derived amounts to form state
  useEffect(() => {
    if (plan.bookingAmount !== bookingAmt)
      setInstallmentField('bookingAmount', bookingAmt);
    if (plan.downPaymentAmount !== dpAmt)
      setInstallmentField('downPaymentAmount', dpAmt);
    if (plan.possessionAmount !== possAmt)
      setInstallmentField('possessionAmount', possAmt);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [total, plan.bookingPercent, plan.downPaymentPercent, plan.possessionPercent]);

  // ─── Frequency counts (auto from duration) ─────────────────────
  const dur = safeNum(plan.durationMonths);
  const counts: Record<FreqKey, number> = {
    monthly:    dur,
    quarterly:  Math.floor(dur / 3),
    halfYearly: Math.floor(dur / 6),
    yearly:     Math.floor(dur / 12),
  };

  const enabled: Record<FreqKey, boolean> = {
    monthly:    plan.hasMonthly,
    quarterly:  plan.hasQuarterly,
    halfYearly: plan.hasHalfYearly,
    yearly:     plan.hasYearly,
  };

  // ─── Allocation % per frequency (local state) ─────────────────
  const [alloc, setAlloc] = useState<Record<FreqKey, number>>(() => {
    if (remaining <= 0) return { monthly: 0, quarterly: 0, halfYearly: 0, yearly: 0 };
    const calc = (amt: number, cnt: number) =>
      Math.round(((amt * cnt) / remaining) * 100);
    return {
      monthly:    calc(safeNum(plan.monthlyAmount),    safeNum(plan.monthlyCount)),
      quarterly:  calc(safeNum(plan.quarterlyAmount),  safeNum(plan.quarterlyCount)),
      halfYearly: calc(safeNum(plan.halfYearlyAmount), safeNum(plan.halfYearlyCount)),
      yearly:     calc(safeNum(plan.yearlyAmount),     safeNum(plan.yearlyCount)),
    };
  });

  // Sum of enabled allocations
  const enabledKeys = (Object.keys(enabled) as FreqKey[]).filter((k) => enabled[k]);
  const totalAllocPercent = enabledKeys.reduce((sum, k) => sum + alloc[k], 0);
  const allocIsBalanced = enabledKeys.length === 0 || Math.abs(totalAllocPercent - 100) < 0.5;

  // ─── Recompute installment amounts when alloc/remaining/duration changes ──
  useEffect(() => {
    (Object.keys(FREQ_CONFIG) as FreqKey[]).forEach((k) => {
      const cfg = FREQ_CONFIG[k];
      if (enabled[k]) {
        const portionTotal = (remaining * alloc[k]) / 100;
        const count = counts[k];
        const amount = count > 0 ? Math.round(portionTotal / count) : 0;
        setInstallmentField(cfg.amountKey, amount);
        setInstallmentField(cfg.countKey, count);
      } else {
        setInstallmentField(cfg.amountKey, 0);
        setInstallmentField(cfg.countKey, 0);
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [alloc.monthly, alloc.quarterly, alloc.halfYearly, alloc.yearly,
      remaining, dur,
      enabled.monthly, enabled.quarterly, enabled.halfYearly, enabled.yearly]);

  // ─── Handlers ──────────────────────────────────────────────────

  // Auto-redistribute allocations when toggling a frequency
  const handleFreqToggle = (freq: FreqKey, val: boolean) => {
    setInstallmentField(FREQ_CONFIG[freq].flagKey, val);
    const futureEnabled = { ...enabled, [freq]: val };
    const futureKeys = (Object.keys(futureEnabled) as FreqKey[]).filter((k) => futureEnabled[k]);

    if (futureKeys.length === 0) {
      setAlloc({ monthly: 0, quarterly: 0, halfYearly: 0, yearly: 0 });
      return;
    }

    const equalShare = Math.floor(100 / futureKeys.length);
    const newAlloc: Record<FreqKey, number> = {
      monthly: 0, quarterly: 0, halfYearly: 0, yearly: 0,
    };
    futureKeys.forEach((k, i) => {
      newAlloc[k] = i === futureKeys.length - 1
        ? 100 - equalShare * (futureKeys.length - 1)
        : equalShare;
    });
    setAlloc(newAlloc);
  };

  const handleAllocChange = (freq: FreqKey, newPercent: number) => {
    const clamped = Math.max(0, Math.min(100, newPercent));
    setAlloc((prev) => ({ ...prev, [freq]: clamped }));
  };

  // Apply preset plan
  const applyPreset = (preset: PresetPlan) => {
    setInstallmentField('bookingPercent', preset.booking);
    setInstallmentField('downPaymentPercent', preset.downPayment);
    setInstallmentField('possessionPercent', preset.possession);
    setInstallmentField('durationMonths', preset.duration);

    // Toggle frequencies
    (Object.keys(FREQ_CONFIG) as FreqKey[]).forEach((k) => {
      const shouldEnable = preset.frequencies[k] !== undefined;
      setInstallmentField(FREQ_CONFIG[k].flagKey, shouldEnable);
    });

    // Set allocations
    const newAlloc: Record<FreqKey, number> = {
      monthly: 0, quarterly: 0, halfYearly: 0, yearly: 0,
    };
    (Object.keys(preset.frequencies) as FreqKey[]).forEach((k) => {
      newAlloc[k] = preset.frequencies[k] ?? 0;
    });
    setAlloc(newAlloc);
  };

  // Balance calculation
  const installmentsTotal = enabledKeys.reduce((sum, k) => {
    const cfg = FREQ_CONFIG[k];
    return sum + safeNum(plan[cfg.amountKey]) * safeNum(plan[cfg.countKey]);
  }, 0);

  const grandTotal = bookingAmt + dpAmt + installmentsTotal + possAmt;
  const balanceDiff = total - grandTotal;
  const isBalanced = total > 0 && Math.abs(balanceDiff) < 100;

  return (
    <>
      {/* ─── Total Price ──────────────────────────────────────────── */}
      <FormSection
        id="pricing-installment-total"
        title="Total Property Price"
        icon={<DollarSign className="w-5 h-5" />}
        defaultOpen={true}
        required
        badge="Installment"
        badgeColor="purple"
        completionStatus={total > 0 ? 'complete' : 'incomplete'}
      >
        <div className="space-y-4">
          <PriceInput
            id="inst-total"
            label="Total Price"
            value={plan.totalPrice}
            onChange={(val) => setInstallmentField('totalPrice', val === '' ? 0 : val)}
            error={errors['installmentPlan.totalPrice']}
            required
            placeholder="e.g. 10000000"
            hint="Enter the total property price — all other amounts auto-calculate from percentages below"
          />

          {/* Quick Preset Plans */}
          {total > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-2">
                <Sparkles className="w-4 h-4 text-[#7c3aed]" />
                <p className="text-sm font-medium text-gray-700">
                  Quick Preset Plans
                </p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {PRESET_PLANS.map((preset) => (
                  <button
                    key={preset.label}
                    type="button"
                    onClick={() => applyPreset(preset)}
                    className="text-left p-3 rounded-xl border-2 border-gray-200
                      hover:border-[#7c3aed] hover:bg-[#7c3aed] hover:bg-opacity-5
                      transition-all duration-150 group"
                  >
                    <p className="text-sm font-semibold text-[#004063]
                      group-hover:text-[#7c3aed]">
                      {preset.label}
                    </p>
                    <p className="text-xs text-gray-500 mt-0.5">
                      {preset.description}
                    </p>
                  </button>
                ))}
              </div>
              <p className="text-xs text-gray-400 mt-2">
                💡 Click a preset to auto-fill, then adjust as needed
              </p>
            </div>
          )}
        </div>
      </FormSection>

      {/* ─── Payment Breakdown (%) ────────────────────────────────── */}
      <FormSection
        id="pricing-installment-breakdown"
        title="Payment Breakdown"
        icon={<Calculator className="w-5 h-5" />}
        defaultOpen={true}
        required
        badge={`${usedPercent.toFixed(1)}% allocated`}
        badgeColor="purple"
        completionStatus={
          safeNum(plan.bookingPercent) > 0 ? 'complete' : 'incomplete'
        }
      >
        <div className="space-y-4">
          {/* Three percentage inputs in a grid */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {/* Booking */}
            <div className="bg-[#029bba] bg-opacity-5 border border-[#029bba]
              border-opacity-30 rounded-xl p-3">
              <label htmlFor="inst-booking-pct"
                className="block text-xs font-semibold text-[#029bba] mb-1.5">
                BOOKING %
              </label>
              <div className="relative">
                <input
                  id="inst-booking-pct"
                  type="number" min="0" max="100" step="0.5"
                  placeholder="e.g. 10"
                  value={plan.bookingPercent || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') { setInstallmentField('bookingPercent', 0); return; }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0 && n <= 100)
                      setInstallmentField('bookingPercent', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 pr-7
                    text-lg font-bold text-[#029bba]
                    focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
                />
                <span className="absolute right-2.5 top-1/2 -translate-y-1/2
                  text-sm font-bold text-[#029bba]">%</span>
              </div>
              {bookingAmt > 0 && (
                <p className="text-xs font-medium text-[#004063] mt-2">
                  Rs. {formatPKRNumeric(bookingAmt)}
                </p>
              )}
              {bookingAmt > 0 && (
                <p className="text-xs text-gray-500">
                  {formatPKR(bookingAmt)}
                </p>
              )}
            </div>

            {/* Down Payment */}
            <div className="bg-[#004063] bg-opacity-5 border border-[#004063]
              border-opacity-30 rounded-xl p-3">
              <label htmlFor="inst-dp-pct"
                className="block text-xs font-semibold text-[#004063] mb-1.5">
                DOWN PAYMENT %
              </label>
              <div className="relative">
                <input
                  id="inst-dp-pct"
                  type="number" min="0" max="100" step="0.5"
                  placeholder="e.g. 20"
                  value={plan.downPaymentPercent || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') { setInstallmentField('downPaymentPercent', 0); return; }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0 && n <= 100)
                      setInstallmentField('downPaymentPercent', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 pr-7
                    text-lg font-bold text-[#004063]
                    focus:ring-2 focus:ring-[#004063] focus:border-transparent"
                />
                <span className="absolute right-2.5 top-1/2 -translate-y-1/2
                  text-sm font-bold text-[#004063]">%</span>
              </div>
              {dpAmt > 0 && (
                <p className="text-xs font-medium text-[#004063] mt-2">
                  Rs. {formatPKRNumeric(dpAmt)}
                </p>
              )}
              {dpAmt > 0 && (
                <p className="text-xs text-gray-500">
                  {formatPKR(dpAmt)}
                </p>
              )}
            </div>

            {/* Possession */}
            <div className="bg-[#0d9488] bg-opacity-5 border border-[#0d9488]
              border-opacity-30 rounded-xl p-3">
              <label htmlFor="inst-poss-pct"
                className="block text-xs font-semibold text-[#0d9488] mb-1.5">
                ON POSSESSION %
              </label>
              <div className="relative">
                <input
                  id="inst-poss-pct"
                  type="number" min="0" max="100" step="0.5"
                  placeholder="e.g. 10"
                  value={plan.possessionPercent || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') { setInstallmentField('possessionPercent', 0); return; }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0 && n <= 100)
                      setInstallmentField('possessionPercent', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 pr-7
                    text-lg font-bold text-[#0d9488]
                    focus:ring-2 focus:ring-[#0d9488] focus:border-transparent"
                />
                <span className="absolute right-2.5 top-1/2 -translate-y-1/2
                  text-sm font-bold text-[#0d9488]">%</span>
              </div>
              {possAmt > 0 && (
                <p className="text-xs font-medium text-[#004063] mt-2">
                  Rs. {formatPKRNumeric(possAmt)}
                </p>
              )}
              {possAmt > 0 && (
                <p className="text-xs text-gray-500">
                  {formatPKR(possAmt)}
                </p>
              )}
            </div>
          </div>

          {/* Remaining for installments banner */}
          {total > 0 && (
            <div className={`rounded-xl p-4 border-2 ${
              isMilestoneOverflow
                ? 'bg-[#fef2f2] border-[#ef4444]'
                : 'bg-gradient-to-r from-[#7c3aed] to-[#4f46e5] border-transparent text-white'
            }`}>
              {isMilestoneOverflow ? (
                <>
                  <p className="text-sm font-bold text-[#ef4444]">
                    ⚠ Milestones exceed 100%
                  </p>
                  <p className="text-xs text-red-700 mt-1">
                    Booking + DP + Possession = {usedPercent.toFixed(1)}% — please reduce
                  </p>
                </>
              ) : (
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs opacity-80 uppercase tracking-wider">
                      Remaining for Installments
                    </p>
                    <p className="text-2xl font-bold mt-1">
                      Rs. {formatPKRNumeric(remaining)}
                    </p>
                    <p className="text-xs opacity-70 mt-0.5">
                      {formatPKR(remaining)}
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs opacity-80 uppercase tracking-wider">
                      % of Total
                    </p>
                    <p className="text-2xl font-bold mt-1">
                      {remainingPercent.toFixed(1)}%
                    </p>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </FormSection>

      {/* ─── Duration ───────────────────────────────────────────── */}
      <FormSection
        id="pricing-installment-duration"
        title="Plan Duration"
        icon={<span className="text-lg">📅</span>}
        defaultOpen={true}
        required
        badge="Months"
        badgeColor="purple"
        completionStatus={dur > 0 ? 'complete' : 'incomplete'}
      >
        <div className="space-y-4">
          {/* Quick presets */}
          <div>
            <p className="text-sm font-medium text-gray-700 mb-2">
              Quick Select
            </p>
            <div className="flex flex-wrap gap-2">
              {[12, 24, 36, 48, 60, 84, 120].map((months) => {
                const isActive = dur === months;
                return (
                  <button
                    key={months}
                    type="button"
                    onClick={() => setInstallmentField('durationMonths', months)}
                    className={`px-4 py-2 rounded-full text-sm font-medium
                      transition-all duration-150
                      ${isActive
                        ? 'bg-[#7c3aed] text-white shadow-md'
                        : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                      }`}
                  >
                    {months / 12 >= 1 ? `${months / 12}y` : `${months}m`}
                    <span className="text-xs ml-1 opacity-70">
                      ({months}m)
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Custom input */}
          <div>
            <label htmlFor="inst-duration"
              className="block text-sm font-medium text-gray-700 mb-1.5">
              Custom Duration (months) <span className="text-red-500">*</span>
            </label>
            <input
              id="inst-duration" type="number" min="1" max="360"
              placeholder="e.g. 36"
              value={plan.durationMonths || ''}
              onChange={(e) => {
                const raw = e.target.value;
                if (raw === '') { setInstallmentField('durationMonths', 0); return; }
                const n = parseInt(raw, 10);
                if (!isNaN(n) && n >= 0 && n <= 360)
                  setInstallmentField('durationMonths', n);
              }}
              className={`w-full border rounded-lg px-4 py-2.5
                focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent
                ${errors['installmentPlan.durationMonths']
                  ? 'border-red-500' : 'border-gray-300'}`}
            />
            <FieldError error={errors['installmentPlan.durationMonths']} />
            {dur > 0 && (
              <p className="text-xs text-gray-500 mt-1">
                = {Math.floor(dur / 12)} year{Math.floor(dur / 12) !== 1 ? 's' : ''}
                {dur % 12 > 0 ? ` ${dur % 12} month${dur % 12 !== 1 ? 's' : ''}` : ''}
              </p>
            )}
          </div>

          {/* Date range */}
          <div className="grid grid-cols-2 gap-4 border-t border-gray-100 pt-4">
            <div>
              <label htmlFor="inst-start"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Start Date
              </label>
              <input
                id="inst-start" type="date"
                value={plan.startDate}
                onChange={(e) => setInstallmentField('startDate', e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
              />
            </div>
            <div>
              <label htmlFor="inst-end"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                End Date
              </label>
              <input
                id="inst-end" type="date"
                value={plan.endDate}
                onChange={(e) => setInstallmentField('endDate', e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
              />
            </div>
          </div>
        </div>
      </FormSection>

      {/* ─── Installment Frequency (Auto-Calculator) ────────────── */}
      <FormSection
        id="pricing-installment-frequency"
        title="Installment Frequency"
        icon={<RefreshCw className="w-5 h-5" />}
        defaultOpen={true}
        required
        badge={enabledKeys.length === 0 ? 'Select at least one' :
               `${enabledKeys.length} frequency${enabledKeys.length > 1 ? 'ies' : ''}`}
        badgeColor="purple"
        completionStatus={
          enabledKeys.length > 0 && allocIsBalanced ? 'complete' : 'incomplete'
        }
      >
        <div className="space-y-4">
          {total === 0 || dur === 0 ? (
            <div className="bg-[#fef3c7] border-l-4 border-[#f59e0b]
              px-4 py-3 rounded-r-lg">
              <p className="text-sm text-amber-800 font-medium">
                ⚠ Enter Total Price and Duration first
              </p>
              <p className="text-xs text-amber-700 mt-1">
                Installment amounts will auto-calculate once those are set
              </p>
            </div>
          ) : remaining <= 0 ? (
            <div className="bg-[#fef3c7] border-l-4 border-[#f59e0b]
              px-4 py-3 rounded-r-lg">
              <p className="text-sm text-amber-800 font-medium">
                ⚠ No amount remaining for installments
              </p>
              <p className="text-xs text-amber-700 mt-1">
                Booking + DP + Possession = 100%. Reduce one to add installments.
              </p>
            </div>
          ) : (
            <>
              <p className="text-sm text-gray-600">
                Toggle one or more payment frequencies. Amounts auto-calculate
                from your allocation.
              </p>

              {/* Frequency cards */}
              {(Object.keys(FREQ_CONFIG) as FreqKey[]).map((freq) => {
                const cfg          = FREQ_CONFIG[freq];
                const isEnabled    = enabled[freq];
                const count        = counts[freq];
                const allocPercent = alloc[freq];
                const portionTotal = (remaining * allocPercent) / 100;
                const amountPerInst = count > 0 ? Math.round(portionTotal / count) : 0;

                return (
                  <div
                    key={freq}
                    className={`border-2 rounded-xl p-4 transition-all duration-150
                      ${isEnabled
                        ? 'border-[#7c3aed] bg-[#7c3aed] bg-opacity-5'
                        : 'border-gray-200 bg-white'}`}
                  >
                    <Toggle
                      label={cfg.label}
                      checked={isEnabled}
                      onChange={(val) => handleFreqToggle(freq, val)}
                      description={cfg.description}
                    />

                    {isEnabled && (
                      <div className="mt-4 pt-4 border-t border-gray-100 space-y-3">
                        {count === 0 ? (
                          <div className="bg-[#fef3c7] border-l-4 border-[#f59e0b]
                            px-3 py-2 rounded-r-lg">
                            <p className="text-xs text-amber-800">
                              ⚠ Duration too short — need at least {cfg.divisor} months
                            </p>
                          </div>
                        ) : (
                          <>
                            {/* Allocation slider/input */}
                            <div>
                              <div className="flex items-center justify-between mb-1.5">
                                <label className="text-sm font-medium text-gray-700">
                                  Allocation: {allocPercent.toFixed(0)}% of installments
                                </label>
                                <span className="text-xs text-[#7c3aed] font-semibold">
                                  Rs. {formatPKRNumeric(portionTotal)}
                                </span>
                              </div>
                              <input
                                type="range"
                                min="0" max="100" step="5"
                                value={allocPercent}
                                onChange={(e) =>
                                  handleAllocChange(freq, parseFloat(e.target.value))
                                }
                                className="w-full h-2 bg-gray-200 rounded-full appearance-none
                                  cursor-pointer accent-[#7c3aed]"
                              />
                              <div className="flex justify-between text-xs text-gray-400 mt-1">
                                <span>0%</span>
                                <span>25%</span>
                                <span>50%</span>
                                <span>75%</span>
                                <span>100%</span>
                              </div>
                            </div>

                            {/* Manual % input */}
                            <div className="grid grid-cols-3 gap-3 items-end">
                              <div>
                                <label className="block text-xs font-medium text-gray-500 mb-1">
                                  Allocation %
                                </label>
                                <div className="relative">
                                  <input
                                    type="number" min="0" max="100" step="1"
                                    value={Math.round(allocPercent)}
                                    onChange={(e) => {
                                      const n = parseFloat(e.target.value);
                                      if (!isNaN(n)) handleAllocChange(freq, n);
                                    }}
                                    className="w-full border border-gray-300 rounded-lg
                                      px-3 py-2 pr-7 text-sm font-semibold
                                      focus:ring-2 focus:ring-[#7c3aed]
                                      focus:border-transparent"
                                  />
                                  <span className="absolute right-2.5 top-1/2
                                    -translate-y-1/2 text-xs text-gray-400">%</span>
                                </div>
                              </div>
                              <div>
                                <label className="block text-xs font-medium text-gray-500 mb-1">
                                  Count
                                </label>
                                <div className="w-full bg-gray-50 rounded-lg px-3 py-2
                                  border border-gray-200 text-sm font-semibold text-center">
                                  {count} {cfg.unit}{count !== 1 ? 's' : ''}
                                </div>
                              </div>
                              <div>
                                <label className="block text-xs font-medium text-gray-500 mb-1">
                                  Per Installment
                                </label>
                                <div className="w-full bg-[#7c3aed] bg-opacity-10
                                  rounded-lg px-3 py-2 border border-[#7c3aed]
                                  border-opacity-30 text-sm font-bold text-[#7c3aed]
                                  text-center">
                                  Rs. {formatPKRNumeric(amountPerInst)}
                                </div>
                              </div>
                            </div>

                            <div className="text-xs text-gray-500 text-center pt-1">
                              <strong>{count}</strong> × Rs. {formatPKRNumeric(amountPerInst)} ={' '}
                              <strong className="text-[#7c3aed]">
                                Rs. {formatPKRNumeric(amountPerInst * count)}
                              </strong>
                            </div>
                          </>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}

              {/* Allocation balance check */}
              {enabledKeys.length > 1 && (
                <div className={`p-3 rounded-lg border-2 ${
                  allocIsBalanced
                    ? 'bg-[#f0fdf4] border-[#10b981]'
                    : 'bg-[#fef3c7] border-[#f59e0b]'
                }`}>
                  <div className="flex items-center justify-between">
                    <span className={`text-sm font-semibold ${
                      allocIsBalanced ? 'text-[#10b981]' : 'text-[#f59e0b]'
                    }`}>
                      {allocIsBalanced
                        ? '✓ Allocations balanced'
                        : `⚠ Allocations sum to ${totalAllocPercent.toFixed(0)}% (should be 100%)`}
                    </span>
                    <span className="text-xs text-gray-600">
                      Total: {totalAllocPercent.toFixed(0)}%
                    </span>
                  </div>
                </div>
              )}

              {/* Frequency mix tip */}
              {enabledKeys.length === 1 && enabledKeys[0] === 'monthly' && (
                <div className="bg-[#eff6ff] border-l-4 border-[#029bba]
                  px-4 py-3 rounded-r-lg">
                  <p className="text-xs text-[#004063]">
                    💡 <strong>Pro tip:</strong> Many Pakistani developers offer
                    <strong> Monthly + Yearly bonus</strong> payments. Enable Yearly
                    frequency to split (e.g. 70% monthly + 30% yearly bonus).
                  </p>
                </div>
              )}
            </>
          )}
        </div>
      </FormSection>

      {/* ─── Plan Branding (collapsible — optional) ────────────── */}
      <FormSection
        id="pricing-installment-branding"
        title="Plan Details (Optional)"
        icon={<span className="text-lg">🏷️</span>}
        defaultOpen={false}
        description="Developer name, plan name — leave empty if reselling"
        completionStatus="optional"
      >
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="inst-plan-name"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Plan Name
              </label>
              <input
                id="inst-plan-name" type="text"
                placeholder="e.g. 3 Year Easy Plan"
                value={plan.planName}
                onChange={(e) => setInstallmentField('planName', e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
              />
            </div>
            <div>
              <label htmlFor="inst-dev-name"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Developer Name
              </label>
              <input
                id="inst-dev-name" type="text"
                placeholder="e.g. Bahria Town / Leave empty if reselling"
                value={plan.developerName}
                onChange={(e) => setInstallmentField('developerName', e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2
            border-t border-gray-100 pt-3">
            <Toggle
              label="Price Negotiable"
              checked={plan.isNegotiable}
              onChange={(val) => setInstallmentField('isNegotiable', val)}
            />
            <Toggle
              label="Bank Financing Available"
              checked={plan.bankFinancingAvailable}
              onChange={(val) => setInstallmentField('bankFinancingAvailable', val)}
            />
          </div>
        </div>
      </FormSection>

      {/* ─── Penalties & Policies ────────────────────────────── */}
      <FormSection
        id="pricing-installment-policies"
        title="Penalties & Policies"
        icon={<Lock className="w-5 h-5" />}
        defaultOpen={false}
        badge="Optional"
        badgeColor="purple"
        completionStatus="optional"
      >
        <div className="space-y-4">
          <PriceInput
            id="inst-confirmation"
            label="Refundable Confirmation Deposit"
            value={plan.confirmationDeposit}
            onChange={(val) => setInstallmentField('confirmationDeposit', val === '' ? 0 : val)}
            hint="Refundable deposit at booking — returned at possession"
            placeholder="e.g. 100000"
          />

          <div className="grid grid-cols-3 gap-4">
            <div>
              <label htmlFor="inst-late-penalty"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Late Payment Penalty
              </label>
              <div className="relative">
                <input
                  id="inst-late-penalty"
                  type="number" min="0" max="50" step="0.1"
                  placeholder="e.g. 2"
                  value={plan.latePaymentPenalty || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') { setInstallmentField('latePaymentPenalty', 0); return; }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0 && n <= 50)
                      setInstallmentField('latePaymentPenalty', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5 pr-8
                    focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2
                  text-sm text-gray-400 font-medium">%</span>
              </div>
              <p className="text-xs text-gray-400 mt-1">% per month late</p>
            </div>

            <div>
              <label htmlFor="inst-discount"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Full Payment Discount
              </label>
              <div className="relative">
                <input
                  id="inst-discount"
                  type="number" min="0" max="50" step="0.1"
                  placeholder="e.g. 5"
                  value={plan.discountOnFullPayment || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') { setInstallmentField('discountOnFullPayment', 0); return; }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0 && n <= 50)
                      setInstallmentField('discountOnFullPayment', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5 pr-8
                    focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2
                  text-sm text-gray-400 font-medium">%</span>
              </div>
              <p className="text-xs text-gray-400 mt-1">If paid upfront</p>
            </div>

            <div>
              <label htmlFor="inst-transfer-pct"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Transfer Charges
              </label>
              <div className="relative">
                <input
                  id="inst-transfer-pct"
                  type="number" min="0" max="20" step="0.1"
                  placeholder="e.g. 2"
                  value={plan.transferChargePercent || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') { setInstallmentField('transferChargePercent', 0); return; }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0 && n <= 20)
                      setInstallmentField('transferChargePercent', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5 pr-8
                    focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2
                  text-sm text-gray-400 font-medium">%</span>
              </div>
              <p className="text-xs text-gray-400 mt-1">On file transfer</p>
            </div>
          </div>

          <div>
            <label htmlFor="inst-cancel"
              className="block text-sm font-medium text-gray-700 mb-1.5">
              Cancellation Policy
            </label>
            <textarea
              id="inst-cancel"
              placeholder="e.g. Booking amount non-refundable. Down payment refundable minus 10% deduction. Cancellation request must be in writing..."
              value={plan.cancellationPolicy}
              onChange={(e) => setInstallmentField('cancellationPolicy', e.target.value)}
              rows={3}
              className="w-full border border-gray-300 rounded-lg px-4 py-2.5 resize-y
                focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
            />
            <p className="text-xs text-gray-400 mt-1">
              Clearly state refund / cancellation rules for the buyer
            </p>
          </div>
        </div>
      </FormSection>

      {/* ─── Final Balance Summary ────────────────────────────── */}
      {total > 0 && (
        <div className={`rounded-xl p-4 border-2 ${
          isBalanced
            ? 'bg-[#f0fdf4] border-[#10b981]'
            : 'bg-[#fef3c7] border-[#f59e0b]'
        }`}>
          <div className="flex items-start gap-3">
            <span className={`text-2xl ${isBalanced ? 'text-[#10b981]' : 'text-[#f59e0b]'}`}>
              {isBalanced ? '✓' : '⚠'}
            </span>
            <div className="flex-1">
              <p className={`text-sm font-bold ${
                isBalanced ? 'text-[#10b981]' : 'text-[#f59e0b]'
              }`}>
                {isBalanced
                  ? 'Payment plan is balanced'
                  : `Off by Rs. ${formatPKRNumeric(Math.abs(balanceDiff))} ${balanceDiff > 0 ? '(short)' : '(over)'}`}
              </p>

              <div className="mt-3 grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
                <div>
                  <span className="text-gray-500">Booking</span>
                  <p className="font-semibold text-[#029bba]">
                    Rs. {formatPKRNumeric(bookingAmt)}
                  </p>
                </div>
                <div>
                  <span className="text-gray-500">Down Payment</span>
                  <p className="font-semibold text-[#004063]">
                    Rs. {formatPKRNumeric(dpAmt)}
                  </p>
                </div>
                <div>
                  <span className="text-gray-500">Installments</span>
                  <p className="font-semibold text-[#7c3aed]">
                    Rs. {formatPKRNumeric(installmentsTotal)}
                  </p>
                </div>
                <div>
                  <span className="text-gray-500">Possession</span>
                  <p className="font-semibold text-[#0d9488]">
                    Rs. {formatPKRNumeric(possAmt)}
                  </p>
                </div>
              </div>

              {/* Visual breakdown bar */}
              <div className="mt-3 h-3 rounded-full overflow-hidden flex bg-gray-200">
                {bookingAmt > 0 && (
                  <div className="bg-[#029bba] h-full"
                    style={{ width: `${(bookingAmt / total) * 100}%` }}
                    title={`Booking: ${pct(bookingAmt, total)}%`}
                  />
                )}
                {dpAmt > 0 && (
                  <div className="bg-[#004063] h-full"
                    style={{ width: `${(dpAmt / total) * 100}%` }}
                    title={`Down Payment: ${pct(dpAmt, total)}%`}
                  />
                )}
                {installmentsTotal > 0 && (
                  <div className="bg-[#7c3aed] h-full"
                    style={{ width: `${(installmentsTotal / total) * 100}%` }}
                    title={`Installments: ${pct(installmentsTotal, total)}%`}
                  />
                )}
                {possAmt > 0 && (
                  <div className="bg-[#0d9488] h-full"
                    style={{ width: `${(possAmt / total) * 100}%` }}
                    title={`Possession: ${pct(possAmt, total)}%`}
                  />
                )}
              </div>

              <div className="mt-3 pt-3 border-t border-gray-300 border-opacity-50">
                <div className="flex justify-between text-sm">
                  <span className="font-medium text-gray-600">
                    Total Plan Value
                  </span>
                  <span className="font-bold text-[#004063]">
                    Rs. {formatPKRNumeric(grandTotal)}
                  </span>
                </div>
                <div className="flex justify-between text-xs mt-1">
                  <span className="text-gray-500">Expected</span>
                  <span className="text-gray-500">
                    Rs. {formatPKRNumeric(total)}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

// ═══════════════════════════════════════════════════════════════
// RENT SECTION (Enterprise Grade)
// ═══════════════════════════════════════════════════════════════

interface RentFieldsProps {
  form:           PropertyFormState;
  errors:         TabErrors;
  setRentalField: UsePropertyFormReturn['setRentalField'];
  fieldConfig:    FieldConfig;
}

function RentFields({
  form, errors, setRentalField, fieldConfig: cfg,
}: RentFieldsProps): React.ReactElement {
  const rental = form.rentalDetails;

  // Auto-calc security deposit + advance amounts
  const monthlyRent       = safeNum(rental.monthlyRent);
  const autoSecurity      = monthlyRent * safeNum(rental.securityDepositMonths);
  const autoAdvance       = monthlyRent * safeNum(rental.advanceMonths);
  const totalMoveInCost   =
    (rental.securityDepositAmount > 0 ? rental.securityDepositAmount : autoSecurity) +
    (autoAdvance) +
    monthlyRent;

  return (
    <>
      {/* ── Core Rent ── */}
      <FormSection
        id="pricing-rent-core"
        title="Monthly Rent"
        icon={<Home className="w-5 h-5" />}
        defaultOpen={true}
        required
        badge="Rent"
        badgeColor="green"
        completionStatus={monthlyRent > 0 ? 'complete' : 'incomplete'}
      >
        <div className="space-y-4">
          {/* Monthly Rent */}
          <PriceInput
            id="rent-monthly"
            label="Monthly Rent"
            value={rental.monthlyRent}
            onChange={(val) => setRentalField('monthlyRent', val === '' ? 0 : val)}
            error={errors['rentalDetails.monthlyRent']}
            required
            placeholder="e.g. 50000"
          />

          {/* Weekly rent (room/short-term) */}
          {cfg.showWeeklyRent && (
            <PriceInput
              id="rent-weekly"
              label="Weekly Rent"
              value={rental.weeklyRent}
              onChange={(val) => setRentalField('weeklyRent', val === '' ? 0 : val)}
              hint="Optional — for short-term / weekly stays"
              placeholder="e.g. 15000"
            />
          )}

          <Toggle
            label="Rent is Negotiable"
            checked={rental.isNegotiable}
            onChange={(val) => setRentalField('isNegotiable', val)}
            description="Allow tenants to negotiate the rent"
          />
        </div>
      </FormSection>

      {/* ── Security Deposit & Advance ── */}
      <FormSection
        id="pricing-rent-deposit"
        title="Security Deposit & Advance"
        icon={<Lock className="w-5 h-5" />}
        defaultOpen={true}
        required
        badge="Upfront Cost"
        badgeColor="green"
        completionStatus={
          safeNum(rental.securityDepositMonths) > 0 ||
          safeNum(rental.securityDepositAmount) > 0
            ? 'complete' : 'optional'
        }
      >
        <div className="space-y-4">
          {/* Security Deposit */}
          <div className="bg-[#0d9488] bg-opacity-5 border border-[#0d9488]
            border-opacity-20 rounded-xl p-4">
            <p className="text-sm font-semibold text-[#0d9488] mb-3">
              🔒 Security Deposit (Refundable)
            </p>
            <div className="grid grid-cols-2 gap-3">
              {/* Months */}
              <div>
                <label htmlFor="rent-security-months"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Number of Months
                </label>
                <input
                  id="rent-security-months"
                  type="number" min="0" max="24" step="1"
                  placeholder="e.g. 2"
                  value={rental.securityDepositMonths || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    const n = raw === '' ? 0 : parseInt(raw, 10);
                    if (!isNaN(n) && n >= 0 && n <= 24) {
                      setRentalField('securityDepositMonths', n);
                      // Auto-update amount
                      if (monthlyRent > 0) {
                        setRentalField('securityDepositAmount', n * monthlyRent);
                      }
                    }
                  }}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#0d9488] focus:border-transparent"
                />
                <p className="text-xs text-gray-400 mt-1">
                  Pakistani standard: 1-2 months rent
                </p>
              </div>

              {/* Or amount */}
              <div>
                <label htmlFor="rent-security-amount"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Total Amount
                </label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2
                    text-gray-400 text-sm font-medium pointer-events-none">
                    Rs.
                  </span>
                  <input
                    id="rent-security-amount"
                    type="number" min="0"
                    placeholder={autoSecurity > 0 ? formatPKRNumeric(autoSecurity) : 'e.g. 100000'}
                    value={rental.securityDepositAmount || ''}
                    onChange={(e) => {
                      const raw = e.target.value;
                      const n = raw === '' ? 0 : parseFloat(raw);
                      if (!isNaN(n) && n >= 0)
                        setRentalField('securityDepositAmount', n);
                    }}
                    className="w-full border border-gray-300 rounded-lg pl-10 pr-4 py-2.5
                      focus:ring-2 focus:ring-[#0d9488] focus:border-transparent"
                  />
                </div>
                {autoSecurity > 0 && rental.securityDepositAmount === 0 && (
                  <p className="text-xs text-[#0d9488] mt-1">
                    Auto: Rs. {formatPKRNumeric(autoSecurity)}
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Advance Rent */}
          <div className="bg-[#7c3aed] bg-opacity-5 border border-[#7c3aed]
            border-opacity-20 rounded-xl p-4">
            <p className="text-sm font-semibold text-[#7c3aed] mb-3">
              💰 Advance Rent (Upfront)
            </p>
            <div>
              <label htmlFor="rent-advance"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Number of Months Paid in Advance
              </label>
              <input
                id="rent-advance"
                type="number" min="0" max="24"
                placeholder="e.g. 1"
                value={rental.advanceMonths || ''}
                onChange={(e) => {
                  const raw = e.target.value;
                  const n = raw === '' ? 0 : parseInt(raw, 10);
                  if (!isNaN(n) && n >= 0 && n <= 24) {
                    setRentalField('advanceMonths', n);
                    setRentalField('advanceAmount', n * monthlyRent);
                  }
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#7c3aed] focus:border-transparent"
              />
              {autoAdvance > 0 && (
                <p className="text-xs text-[#7c3aed] mt-1 font-medium">
                  Advance amount: Rs. {formatPKRNumeric(autoAdvance)}
                </p>
              )}
              <p className="text-xs text-gray-400 mt-1">
                Common: 1 month advance paid at move-in
              </p>
            </div>
          </div>

          {/* Move-in Cost Summary */}
          {monthlyRent > 0 && (
            <div className="bg-gradient-to-r from-[#0d9488] to-[#065f46]
              rounded-xl p-4 text-white">
              <h4 className="text-sm font-bold mb-3 opacity-90">
                💵 Total Move-in Cost Estimate
              </h4>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="opacity-80">Security Deposit</span>
                  <span className="font-medium">
                    Rs. {formatPKRNumeric(
                      rental.securityDepositAmount > 0
                        ? rental.securityDepositAmount : autoSecurity
                    )}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="opacity-80">
                    Advance ({rental.advanceMonths || 0} months)
                  </span>
                  <span className="font-medium">
                    Rs. {formatPKRNumeric(autoAdvance)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="opacity-80">First Month Rent</span>
                  <span className="font-medium">
                    Rs. {formatPKRNumeric(monthlyRent)}
                  </span>
                </div>
                <div className="border-t border-white border-opacity-30 pt-2 mt-2">
                  <div className="flex justify-between text-base">
                    <span className="font-bold">Total Upfront</span>
                    <span className="font-bold">
                      Rs. {formatPKRNumeric(totalMoveInCost)}
                    </span>
                  </div>
                  <p className="text-xs opacity-70 mt-1">
                    {formatPKR(totalMoveInCost)}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      </FormSection>

      {/* ── Lease Terms ── */}
      <FormSection
        id="pricing-rent-lease"
        title="Lease Terms"
        icon={<span className="text-lg">📜</span>}
        defaultOpen={false}
        completionStatus={
          safeNum(rental.minimumLeasePeriod) > 0 ? 'complete' : 'optional'
        }
      >
        <div className="space-y-4">
          {/* Lease Period */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="rent-min-lease"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Minimum Lease (months)
              </label>
              <input
                id="rent-min-lease" type="number" min="1" max="120"
                placeholder="e.g. 12"
                value={rental.minimumLeasePeriod || ''}
                onChange={(e) => {
                  const raw = e.target.value;
                  const n = raw === '' ? 0 : parseInt(raw, 10);
                  if (!isNaN(n) && n >= 0) setRentalField('minimumLeasePeriod', n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
              />
              <p className="text-xs text-gray-400 mt-1">
                Common: 11-12 months in Pakistan
              </p>
            </div>
            <div>
              <label htmlFor="rent-max-lease"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Maximum Lease (months)
              </label>
              <input
                id="rent-max-lease" type="number" min="1" max="120"
                placeholder="e.g. 36"
                value={rental.maximumLeasePeriod || ''}
                onChange={(e) => {
                  const raw = e.target.value;
                  const n = raw === '' ? 0 : parseInt(raw, 10);
                  if (!isNaN(n) && n >= 0) setRentalField('maximumLeasePeriod', n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
              />
            </div>
          </div>

          <Toggle
            label="Lease Period is Flexible"
            checked={rental.leaseFlexible}
            onChange={(val) => setRentalField('leaseFlexible', val)}
            description="Open to negotiating shorter or longer terms"
          />

          {/* Available From */}
          <div>
            <label htmlFor="rent-available"
              className="block text-sm font-medium text-gray-700 mb-1.5">
              Available From
            </label>
            <input
              id="rent-available" type="date"
              value={rental.availableFrom}
              onChange={(e) => setRentalField('availableFrom', e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-1
            border-t border-gray-100 pt-3">
            <Toggle
              label="Immediate Availability"
              checked={rental.immediateAvailable}
              onChange={(val) => setRentalField('immediateAvailable', val)}
              description="Ready to move in immediately"
            />
            <Toggle
              label="Short-Term Allowed"
              checked={rental.shortTermAllowed}
              onChange={(val) => setRentalField('shortTermAllowed', val)}
              description="Less than 6 month stays accepted"
            />
          </div>

          {/* Agreement Type */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Agreement Type
            </label>
            <div className="grid grid-cols-3 gap-2">
              {AGREEMENT_TYPE_OPTIONS.map((opt) => {
                const isActive = rental.agreementType === opt.value;
                return (
                  <button
                    key={opt.value ?? 'standard'}
                    type="button"
                    onClick={() => setRentalField('agreementType', opt.value)}
                    className={`px-3 py-2.5 rounded-lg border-2 text-sm font-medium
                      transition-all duration-150 text-center
                      ${isActive
                        ? 'border-[#0d9488] bg-[#0d9488] bg-opacity-5 text-[#0d9488]'
                        : 'border-gray-200 text-gray-600 hover:border-gray-300'
                      }`}
                  >
                    {opt.label}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </FormSection>

      {/* ── Furnishing & Inclusions ── */}
      {cfg.showFurnishingStatus && (
        <FormSection
          id="pricing-rent-furnishing"
          title="Furnishing & Inclusions"
          icon={<span className="text-lg">🛋️</span>}
          defaultOpen={false}
          completionStatus="optional"
        >
          <div className="space-y-4">
            {/* Furnishing Status */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Furnishing Status
              </label>
              <div className="grid grid-cols-3 gap-2">
                {FURNISHING_OPTIONS.map((opt) => {
                  const isActive = rental.furnishingStatus === opt.value;
                  return (
                    <button
                      key={opt.value}
                      type="button"
                      onClick={() => setRentalField('furnishingStatus', opt.value)}
                      className={`px-3 py-2.5 rounded-lg border-2 text-sm font-medium
                        transition-all duration-150 text-center
                        ${isActive
                          ? 'border-[#0d9488] bg-[#0d9488] bg-opacity-5 text-[#0d9488]'
                          : 'border-gray-200 text-gray-600 hover:border-gray-300'
                        }`}
                    >
                      {opt.label}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Maintenance */}
            <div className="border-t border-gray-100 pt-3">
              <Toggle
                label="Maintenance Included"
                checked={rental.maintenanceIncluded}
                onChange={(val) => setRentalField('maintenanceIncluded', val)}
                description="Monthly maintenance charges included in rent"
              />
              {!rental.maintenanceIncluded && (
                <div className="mt-3">
                  <PriceInput
                    id="rent-maintenance"
                    label="Separate Maintenance Charges (per month)"
                    value={rental.maintenanceAmount}
                    onChange={(val) =>
                      setRentalField('maintenanceAmount', val === '' ? 0 : val)
                    }
                    placeholder="e.g. 5000"
                    hint="Building / society maintenance fee"
                    showWords={false}
                  />
                </div>
              )}
            </div>

            {/* Utilities Inclusions */}
            <div className="border-t border-gray-100 pt-3">
              <Toggle
                label="All Utilities Included"
                checked={rental.utilitiesIncluded}
                onChange={(val) => {
                  setRentalField('utilitiesIncluded', val);
                  if (val) {
                    setRentalField('electricityIncluded', true);
                    setRentalField('gasIncluded',         true);
                    setRentalField('waterIncluded',       true);
                    setRentalField('internetIncluded',    true);
                  }
                }}
                description="Electricity, gas, water, internet all included"
              />
              {!rental.utilitiesIncluded && (
                <div className="grid grid-cols-2 gap-1 mt-3">
                  <Toggle
                    label="⚡ Electricity Included"
                    checked={rental.electricityIncluded}
                    onChange={(val) => setRentalField('electricityIncluded', val)}
                  />
                  <Toggle
                    label="🔥 Gas Included"
                    checked={rental.gasIncluded}
                    onChange={(val) => setRentalField('gasIncluded', val)}
                  />
                  <Toggle
                    label="💧 Water Included"
                    checked={rental.waterIncluded}
                    onChange={(val) => setRentalField('waterIncluded', val)}
                  />
                  <Toggle
                    label="🌐 Internet Included"
                    checked={rental.internetIncluded}
                    onChange={(val) => setRentalField('internetIncluded', val)}
                  />
                </div>
              )}
            </div>

            <div className="border-t border-gray-100 pt-3">
              <Toggle
                label="Parking Included"
                checked={rental.parkingIncluded}
                onChange={(val) => setRentalField('parkingIncluded', val)}
                description="Parking space included in monthly rent"
              />
            </div>

            {/* Rent Increment */}
            <div className="border-t border-gray-100 pt-3">
              <Toggle
                label="Annual Rent Increment"
                checked={rental.rentIncrementYearly}
                onChange={(val) => setRentalField('rentIncrementYearly', val)}
                description="Rent will increase each year (Pakistani market norm)"
              />
              {rental.rentIncrementYearly && (
                <div className="mt-3">
                  <label htmlFor="rent-increment"
                    className="block text-sm font-medium text-gray-700 mb-1.5">
                    Annual Increment (%)
                  </label>
                  <div className="relative">
                    <input
                      id="rent-increment"
                      type="number" min="0" max="50" step="0.5"
                      placeholder="e.g. 10"
                      value={rental.rentIncrementPercent || ''}
                      onChange={(e) => {
                        const raw = e.target.value;
                        const n = raw === '' ? 0 : parseFloat(raw);
                        if (!isNaN(n) && n >= 0 && n <= 50)
                          setRentalField('rentIncrementPercent', n);
                      }}
                      className="w-full border border-gray-300 rounded-lg px-4 py-2.5 pr-8
                        focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
                    />
                    <span className="absolute right-3 top-1/2 -translate-y-1/2
                      text-sm text-gray-400 font-medium pointer-events-none">%</span>
                  </div>
                  <p className="text-xs text-gray-400 mt-1">
                    Pakistani standard: 8-10% annual increment
                  </p>
                </div>
              )}
            </div>
          </div>
        </FormSection>
      )}

      {/* ── Tenant Preferences ── */}
      {cfg.showPreferredTenant && (
        <FormSection
          id="pricing-rent-tenant"
          title="Tenant Preferences"
          icon={<Users className="w-5 h-5" />}
          defaultOpen={false}
          completionStatus={
            rental.preferredTenantType && rental.preferredTenantType !== 'any'
              ? 'complete' : 'optional'
          }
        >
          <div className="space-y-4">
            {/* Tenant Type */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Preferred Tenant Type
              </label>
              <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
                {TENANT_TYPE_OPTIONS.map((opt) => {
                  const isActive = rental.preferredTenantType === opt.value;
                  return (
                    <button
                      key={opt.value ?? 'any'}
                      type="button"
                      onClick={() =>
                        setRentalField('preferredTenantType', opt.value)
                      }
                      className={`flex flex-col items-center gap-1 p-3 rounded-xl border-2
                        transition-all duration-150 text-center
                        ${isActive
                          ? 'border-[#0d9488] bg-[#0d9488] bg-opacity-5 text-[#0d9488]'
                          : 'border-gray-200 text-gray-500 hover:border-gray-300'
                        }`}
                    >
                      <span className="text-xl">{opt.icon}</span>
                      <span className="text-xs font-medium">{opt.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Max Occupants */}
            <div>
              <label htmlFor="rent-max-occupants"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Maximum Occupants
              </label>
              <input
                id="rent-max-occupants"
                type="number" min="0" max="50"
                placeholder="e.g. 4"
                value={rental.maxOccupants || ''}
                onChange={(e) => {
                  const raw = e.target.value;
                  const n = raw === '' ? 0 : parseInt(raw, 10);
                  if (!isNaN(n) && n >= 0) setRentalField('maxOccupants', n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
              />
              <p className="text-xs text-gray-400 mt-1">
                Maximum number of people allowed (0 = unrestricted)
              </p>
            </div>

            {/* Permissions */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-1
              border-t border-gray-100 pt-3">
              <Toggle
                label="Pets Allowed"
                checked={rental.petsAllowed}
                onChange={(val) => setRentalField('petsAllowed', val)}
                description="Dogs, cats, birds etc."
              />
              <Toggle
                label="Smoking Allowed"
                checked={rental.smokingAllowed}
                onChange={(val) => setRentalField('smokingAllowed', val)}
              />
              <Toggle
                label="Commercial Use Allowed"
                checked={rental.commercialUseAllowed}
                onChange={(val) => setRentalField('commercialUseAllowed', val)}
                description="Running a business from the property"
              />
            </div>
          </div>
        </FormSection>
      )}
    </>
  );
}

// ═══════════════════════════════════════════════════════════════
// PRE-LAUNCH SECTION
// ═══════════════════════════════════════════════════════════════

interface PreLaunchFieldsProps {
  form:     PropertyFormState;
  errors:   TabErrors;
  setField: UsePropertyFormReturn['setField'];
}

function PreLaunchFields({
  form, errors, setField,
}: PreLaunchFieldsProps): React.ReactElement {
  return (
    <FormSection
      id="pricing-pre-launch"
      title="Pre-Launch Pricing"
      icon={<Rocket className="w-5 h-5" />}
      defaultOpen={true}
      required
      badge="Pre-Launch"
      badgeColor="blue"
      completionStatus={safeNum(form.price) > 0 ? 'complete' : 'incomplete'}
    >
      <div className="space-y-4">
        <div className="bg-[#eff6ff] border-l-4 border-[#4f46e5] px-4 py-3 rounded-r-lg">
          <p className="text-sm text-[#004063]">
            <strong>Pre-Launch / Token Booking:</strong> Set the expected launch
            price and token amount required to secure this property before
            official launch.
          </p>
        </div>

        <PriceInput
          id="price-pre-launch"
          label="Expected Price"
          value={form.price}
          onChange={(val) => setField('price', val)}
          error={errors.price}
          required
          placeholder="e.g. 8000000"
          hint="Price may change at launch — this is the expected/indicative price"
        />

        <PriceInput
          id="price-token"
          label="Token / Booking Amount"
          value={form.tokenAmount}
          onChange={(val) => setField('tokenAmount', val)}
          placeholder="e.g. 500000"
          hint="Amount required to secure booking before launch"
        />

        {/* Balance */}
        {safeNum(form.price) > 0 && safeNum(form.tokenAmount) > 0 && (
          <div className="bg-[#4f46e5] bg-opacity-5 border border-[#4f46e5]
            rounded-lg p-3">
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Balance on Launch</span>
              <span className="font-semibold text-[#4f46e5]">
                Rs. {formatPKRNumeric(safeNum(form.price) - safeNum(form.tokenAmount))}
              </span>
            </div>
            <p className="text-xs text-gray-400 mt-1">
              {formatPKR(safeNum(form.price) - safeNum(form.tokenAmount))}
            </p>
          </div>
        )}

        {/* Expected Completion */}
        <div>
          <label htmlFor="price-completion"
            className="block text-sm font-medium text-gray-700 mb-1.5">
            Expected Launch / Completion Date
          </label>
          <input
            id="price-completion" type="date"
            value={form.expectedCompletionDate}
            onChange={(e) => setField('expectedCompletionDate', e.target.value)}
            min={new Date().toISOString().split('T')[0]}
            className="w-full border border-gray-300 rounded-lg px-4 py-2.5
              focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
          />
        </div>

        <Toggle
          label="Price is Negotiable"
          checked={form.isNegotiable}
          onChange={(val) => setField('isNegotiable', val)}
        />
      </div>
    </FormSection>
  );
}

// ═══════════════════════════════════════════════════════════════
// MAIN COMPONENT
// ═══════════════════════════════════════════════════════════════

export default function TabPricing({
  form,
  errors,
  setField,
  setInstallmentField,
  setRentalField,
  setListingType,
  fieldConfig: cfg,
}: TabPricingProps): React.ReactElement {

  // Safety guard
  if (!cfg) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center text-gray-400 text-sm">
          Loading form...
        </div>
      </div>
    );
  }

  // Get allowed listing types for this property type
  const allowedTypes = cfg.allowedListingTypes;
  const isLocked     = allowedTypes.length === 1;

  return (
    <div className="space-y-5">

      {/* ══════════════════════════════════════════════════════
          LISTING TYPE SELECTOR
         ══════════════════════════════════════════════════════ */}
      <div className="bg-white rounded-xl border border-gray-200 p-4 shadow-sm">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold text-[#004063]">
            Listing Type
          </h3>
          {isLocked && (
            <span className="inline-flex items-center gap-1 px-2.5 py-1
              rounded-full bg-amber-50 text-[#f59e0b] text-xs font-medium">
              <Lock className="w-3 h-3" />
              Locked for this type
            </span>
          )}
        </div>

        {/* Show all 4 types, but disable non-allowed ones */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {(Object.entries(LISTING_TYPE_LABELS) as [ListingType, string][])
            .map(([type, label]) => {
              const isActive   = form.listingType === type;
              const isAllowed  = allowedTypes.includes(type);
              const colors     = LISTING_TYPE_COLORS[type];

              return (
                <button
                  key={type}
                  type="button"
                  disabled={!isAllowed}
                  onClick={() => isAllowed && setListingType(type)}
                  title={!isAllowed
                    ? `Not available for ${form.propertyType || 'this property type'}`
                    : ''}
                  className={`flex flex-col items-center gap-2 p-4 rounded-xl border-2
                    transition-all duration-150
                    ${!isAllowed
                      ? 'border-gray-100 bg-gray-50 opacity-40 cursor-not-allowed'
                      : isActive
                        ? `${colors.border} ${colors.bg} shadow-md`
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                >
                  <span className={
                    !isAllowed
                      ? 'text-gray-300'
                      : isActive ? colors.text : 'text-gray-400'
                  }>
                    {LISTING_TYPE_ICONS[type]}
                  </span>
                  <span className={`text-xs font-medium text-center leading-tight
                    ${!isAllowed
                      ? 'text-gray-400'
                      : isActive ? colors.text : 'text-gray-600'
                    }`}>
                    {label}
                  </span>
                  {!isAllowed && (
                    <Lock className="w-3 h-3 text-gray-300" />
                  )}
                </button>
              );
            })}
        </div>

        {/* Reset notice / restriction notice */}
        {!isLocked && (
          <p className="text-xs text-gray-400 mt-3 text-center">
            ⚠ Changing listing type resets pricing fields
          </p>
        )}
        {isLocked && form.propertyType === 'room' && (
          <p className="text-xs text-[#f59e0b] mt-3 text-center font-medium">
            🛏️ Rooms are typically only for rent in Pakistani market
          </p>
        )}
      </div>

      {/* ══════════════════════════════════════════════════════
          DYNAMIC PRICING FIELDS
         ══════════════════════════════════════════════════════ */}
      {form.listingType === 'full_payment' && (
        <FullPaymentFields
          form={form}
          errors={errors}
          setField={setField}
        />
      )}

      {form.listingType === 'installment' && (
        <InstallmentFields
          form={form}
          errors={errors}
          setInstallmentField={setInstallmentField}
        />
      )}

      {form.listingType === 'rent' && (
        <RentFields
          form={form}
          errors={errors}
          setRentalField={setRentalField}
          fieldConfig={cfg}
        />
      )}

      {form.listingType === 'pre_launch' && (
        <PreLaunchFields
          form={form}
          errors={errors}
          setField={setField}
        />
      )}

    </div>
  );
}

// components/property/forms/tabs/TabSize.tsx

import {
  Ruler, Calendar, Maximize2, PenTool,
  HardHat, CheckCircle2, AlertCircle, Zap, Rocket,
} from 'lucide-react';
import FormSection from '../shared/FormSection';
import {
  PropertyFormState,
  PropertyType,
  AreaUnit,
  AREA_UNITS,
  AREA_UNIT_DESCRIPTIONS,
  convertToSqFt,
  TabErrors,
  UsePropertyFormReturn,
  FieldConfig,
  ResidentialDetails,
  CommercialDetails,
  ConstructionDetails,
  ProjectStatus,
  ConstructionStage,
  ScheduleStatus,
  STAGE_PROGRESS_MAP,
  STAGE_DETAILS,
} from '../shared/usePropertyForm';

// ─── Types ────────────────────────────────────────────────────────────────────

interface TabSizeProps {
  form:                 PropertyFormState;
  errors:               TabErrors;
  setField:             UsePropertyFormReturn['setField'];
  setResidentialField:  UsePropertyFormReturn['setResidentialField'];
  setCommercialField:   UsePropertyFormReturn['setCommercialField'];
  setConstructionField: UsePropertyFormReturn['setConstructionField'];
  fieldConfig:          FieldConfig;
}

// ─── Reusable Components ──────────────────────────────────────────────────────

function FieldError({ error }: { error?: string }): React.ReactElement | null {
  if (!error) return null;
  return (
    <p className="mt-1 text-xs text-red-600 flex items-center gap-1">
      <span>⚠</span>
      <span>{error}</span>
    </p>
  );
}

interface NumberInputProps {
  id:           string;
  label:        string;
  value:        number | '';
  onChange:     (val: number | '') => void;
  placeholder?: string;
  hint?:        string;
  error?:       string;
  min?:         number;
  max?:         number;
  step?:        number;
  suffix?:      string;
  required?:    boolean;
}

function NumberInput({
  id, label, value, onChange, placeholder, hint,
  error, min = 0, max, step = 0.01, suffix, required = false,
}: NumberInputProps): React.ReactElement {
  return (
    <div>
      <label htmlFor={id}
        className="block text-sm font-medium text-gray-700 mb-1.5">
        {label}
        {required && <span className="text-red-500 ml-1">*</span>}
      </label>
      <div className="relative">
        <input
          id={id} type="number" min={min} max={max} step={step}
          placeholder={placeholder}
          value={value === '' ? '' : value}
          onChange={(e) => {
            const raw = e.target.value;
            if (raw === '') { onChange(''); return; }
            const n = parseFloat(raw);
            if (!isNaN(n) && n >= min) onChange(n);
          }}
          className={`w-full border rounded-lg px-4 py-2.5
            ${suffix ? 'pr-14' : 'pr-4'}
            focus:ring-2 focus:ring-[#029bba] focus:border-transparent
            ${error ? 'border-red-500' : 'border-gray-300'}`}
        />
        {suffix && (
          <span className="absolute right-3 top-1/2 -translate-y-1/2
            text-sm text-gray-400 font-medium pointer-events-none">
            {suffix}
          </span>
        )}
      </div>
      {hint && !error && (
        <p className="text-xs text-gray-400 mt-1">{hint}</p>
      )}
      <FieldError error={error} />
    </div>
  );
}

// ─── Area Input with Unit Selector ────────────────────────────────────────────

interface AreaInputProps {
  id:           string;
  label:        string;
  sizeValue:    number | '';
  unitValue:    AreaUnit;
  onSizeChange: (val: number | '') => void;
  onUnitChange: (val: AreaUnit) => void;
  error?:       string;
  required?:    boolean;
  hint?:        string;
  availableUnits?: AreaUnit[];
}

function AreaInput({
  id, label, sizeValue, unitValue,
  onSizeChange, onUnitChange,
  error, required = false, hint,
  availableUnits = AREA_UNITS,
}: AreaInputProps): React.ReactElement {
  const sqFt = sizeValue !== '' && sizeValue > 0
    ? convertToSqFt(sizeValue, unitValue) : 0;

  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1.5">
        {label}
        {required && <span className="text-red-500 ml-1">*</span>}
      </label>
      <div className="grid grid-cols-5 gap-3">
        {/* Size input — 3 cols */}
        <div className="col-span-3">
          <input
            id={id} type="number" step="0.01" min="0"
            placeholder="e.g. 5"
            value={sizeValue === '' ? '' : sizeValue}
            onChange={(e) => {
              const raw = e.target.value;
              if (raw === '') { onSizeChange(''); return; }
              const n = parseFloat(raw);
              if (!isNaN(n) && n >= 0) onSizeChange(n);
            }}
            className={`w-full border rounded-lg px-4 py-2.5
              focus:ring-2 focus:ring-[#029bba] focus:border-transparent
              ${error ? 'border-red-500' : 'border-gray-300'}`}
          />
        </div>
        {/* Unit selector — 2 cols */}
        <div className="col-span-2">
          <select
            value={unitValue}
            onChange={(e) => onUnitChange(e.target.value as AreaUnit)}
            className="w-full border border-gray-300 rounded-lg px-3 py-2.5
              focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
          >
            {availableUnits.map((unit) => (
              <option key={unit} value={unit}>{unit}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Conversion helper */}
      {sqFt > 0 && unitValue !== 'Square Feet' && (
        <div className="mt-2 bg-[#eff6ff] border-l-4 border-[#029bba]
          px-3 py-2 rounded-r-lg flex items-center gap-2">
          <Maximize2 className="w-3.5 h-3.5 text-[#029bba] flex-shrink-0" />
          <span className="text-xs text-[#004063]">
            {sizeValue} {unitValue} ={' '}
            <strong>{sqFt.toLocaleString('en-PK')} sq ft</strong>
            {unitValue === 'Marla' && (
              <span className="text-gray-400 ml-2">
                ({((sqFt) / 5445).toFixed(3)} Kanal)
              </span>
            )}
            {unitValue === 'Kanal' && (
              <span className="text-gray-400 ml-2">
                ({(sizeValue as number * 20).toFixed(0)} Marla)
              </span>
            )}
          </span>
        </div>
      )}

      {hint && !error && (
        <p className="text-xs text-gray-400 mt-1">{hint}</p>
      )}
      {AREA_UNIT_DESCRIPTIONS[unitValue] && (
        <p className="text-xs text-gray-400 mt-1">
          ℹ️ {AREA_UNIT_DESCRIPTIONS[unitValue]}
        </p>
      )}
      <FieldError error={error} />
    </div>
  );
}

// ─── Quick Size Pills ─────────────────────────────────────────────────────────

interface QuickSizePillsProps {
  sizes:        { label: string; size: number; unit: AreaUnit }[];
  currentSize:  number | '';
  currentUnit:  AreaUnit;
  onSelect:     (size: number, unit: AreaUnit) => void;
  propertyType: PropertyType | '';
}

function QuickSizePills({
  sizes, currentSize, currentUnit, onSelect, propertyType,
}: QuickSizePillsProps): React.ReactElement | null {
  if (!sizes.length) return null;
  return (
    <div>
      <p className="text-sm font-medium text-gray-700 mb-2">
        Common Sizes
        {propertyType && (
          <span className="text-xs text-gray-400 font-normal ml-2">
            for {propertyType}
          </span>
        )}
      </p>
      <div className="flex flex-wrap gap-2">
        {sizes.map((qs) => {
          const isActive = currentSize === qs.size && currentUnit === qs.unit;
          return (
            <button
              key={qs.label}
              type="button"
              onClick={() => onSelect(qs.size, qs.unit)}
              className={`px-3 py-1.5 rounded-full text-sm font-medium
                transition-all duration-150
                ${isActive
                  ? 'bg-[#029bba] text-white shadow-md'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
            >
              {qs.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ─── Current Year ─────────────────────────────────────────────────────────────

const CURRENT_YEAR = new Date().getFullYear();

// ─── Area unit sets per category ─────────────────────────────────────────────

const PLOT_AREA_UNITS: AreaUnit[]       = ['Marla','Kanal','Square Feet','Square Yards','Acres'];
const SQFT_AREA_UNITS: AreaUnit[]       = ['Square Feet','Square Yards','Square Meters','Marla'];
const LARGE_AREA_UNITS: AreaUnit[]      = ['Kanal','Acres','Marla','Square Feet'];
const ALL_AREA_UNITS: AreaUnit[]        = AREA_UNITS;

function getAreaUnits(pt: PropertyType | ''): AreaUnit[] {
  switch (pt) {
    case 'plot':                    return PLOT_AREA_UNITS;
    case 'house': case 'villa':     return PLOT_AREA_UNITS;
    case 'apartment': case 'room':
    case 'penthouse': case 'shop':
    case 'office': case 'commercial': return SQFT_AREA_UNITS;
    case 'warehouse': case 'building': return ALL_AREA_UNITS;
    case 'farmhouse': case 'other':  return LARGE_AREA_UNITS;
    default:                        return ALL_AREA_UNITS;
  }
}

// ═══════════════════════════════════════════════════════════════
// CONSTRUCTION JOURNEY COMPONENT
// ═══════════════════════════════════════════════════════════════

interface ConstructionJourneyProps {
  construction:                 ConstructionDetails;
  setConstructionField:         UsePropertyFormReturn['setConstructionField'];
  setField:                     UsePropertyFormReturn['setField'];
  currentTopLevelYearBuilt:     number | '';
  currentTopLevelRenovationYear:number | '';
}

const PROJECT_STATUS_OPTIONS: {
  value: ProjectStatus;
  label: string;
  icon: React.ReactElement;
  desc: string;
  color: string;
}[] = [
  {
    value: 'planned',
    label: 'Planned',
    icon: <Rocket className="w-5 h-5" />,
    desc: 'Pre-launch / not yet started',
    color: '#4f46e5',
  },
  {
    value: 'building',
    label: 'Building',
    icon: <HardHat className="w-5 h-5" />,
    desc: 'Active construction in progress',
    color: '#f59e0b',
  },
  {
    value: 'finishing',
    label: 'Finishing',
    icon: <Zap className="w-5 h-5" />,
    desc: 'Near completion — finishing work',
    color: '#7c3aed',
  },
  {
    value: 'ready',
    label: 'Ready',
    icon: <CheckCircle2 className="w-5 h-5" />,
    desc: 'Completed & ready for possession',
    color: '#10b981',
  },
];

const SCHEDULE_STATUS_OPTIONS: {
  value: ScheduleStatus;
  label: string;
  icon: string;
  color: string;
  bg: string;
}[] = [
  { value: 'on_time', label: 'On Schedule', icon: '✅', color: '#029bba', bg: '#eff6ff' },
  { value: 'delayed', label: 'Delayed',     icon: '⚠️', color: '#ef4444', bg: '#fef2f2' },
  { value: 'ahead',   label: 'Ahead of Schedule', icon: '⚡', color: '#10b981', bg: '#f0fdf4' },
];

const STAGE_ORDER: Exclude<ConstructionStage, ''>[] = [
  'foundation', 'structure', 'brickwork',
  'plastering', 'electrical', 'finishing', 'final_touches',
];

function ConstructionJourney({
  construction,
  setConstructionField,
  setField,
  currentTopLevelYearBuilt,
  currentTopLevelRenovationYear,
}: ConstructionJourneyProps): React.ReactElement {

  const isBuildingOrFinishing =
    construction.projectStatus === 'building' ||
    construction.projectStatus === 'finishing';

  // ─── Project Status Selection ───────────────────────────────
  const handleStatusChange = (status: ProjectStatus) => {
    setConstructionField('projectStatus', status);
    // Auto-clear irrelevant fields when switching status
    if (status === 'ready') {
      setConstructionField('currentStage', '');
      setConstructionField('progressPercent', '');
      setConstructionField('constructionStart', '');
      setConstructionField('expectedCompletion', '');
      setConstructionField('scheduleStatus', '');
      setConstructionField('originalCompletion', '');
      setConstructionField('delayReason', '');
    }
    if (status === 'planned') {
      setConstructionField('currentStage', '');
      setConstructionField('progressPercent', '');
      setConstructionField('scheduleStatus', '');
      setConstructionField('yearBuilt', '');
    }
  };

  // ─── Stage Selection (auto-fills progress %) ───────────────
  const handleStageSelect = (stage: ConstructionStage) => {
    setConstructionField('currentStage', stage);
    if (stage && STAGE_PROGRESS_MAP[stage as Exclude<ConstructionStage, ''>]) {
      setConstructionField(
        'progressPercent',
        STAGE_PROGRESS_MAP[stage as Exclude<ConstructionStage, ''>]
      );
    }
  };

  // ─── Auto-calc delay months when dates change ──────────────
  const calcDelayMonths = (original: string, revised: string): number => {
    if (!original || !revised) return 0;
    const o = new Date(original);
    const r = new Date(revised);
    if (isNaN(o.getTime()) || isNaN(r.getTime())) return 0;
    const months =
      (r.getFullYear() - o.getFullYear()) * 12 +
      (r.getMonth() - o.getMonth());
    return Math.max(0, months);
  };

  // Sync year built to top-level form field (backward compat)
  const handleYearBuiltChange = (val: number | '') => {
    setConstructionField('yearBuilt', val);
    setField('constructionYear', val);
  };

  const handleYearRenovatedChange = (val: number | '') => {
    setConstructionField('yearRenovated', val);
    setField('renovationYear', val);
  };

  return (
    <div className="space-y-6">

      {/* ─── STEP 1: Project Status ──────────────────────────── */}
      <div>
        <div className="flex items-baseline justify-between mb-3">
          <h4 className="text-sm font-bold text-[#004063]
            uppercase tracking-wider">
            Step 1: What&apos;s the project status?
          </h4>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {PROJECT_STATUS_OPTIONS.map((opt) => {
            const isActive = construction.projectStatus === opt.value;
            return (
              <button
                key={opt.value}
                type="button"
                onClick={() => handleStatusChange(opt.value as ProjectStatus)}
                className={`text-left p-4 rounded-xl border-2
                  transition-all duration-150
                  ${isActive
                    ? 'shadow-md'
                    : 'border-gray-200 hover:border-gray-300'
                  }`}
                style={isActive ? {
                  borderColor: opt.color,
                  backgroundColor: `${opt.color}0d`,
                } : undefined}
              >
                <div className="flex items-center gap-2 mb-2">
                  <span style={{ color: isActive ? opt.color : '#9ca3af' }}>
                    {opt.icon}
                  </span>
                  <p className={`font-semibold text-sm
                    ${isActive ? '' : 'text-gray-700'}`}
                    style={isActive ? { color: opt.color } : undefined}>
                    {opt.label}
                  </p>
                </div>
                <p className="text-xs text-gray-400">{opt.desc}</p>
              </button>
            );
          })}
        </div>
      </div>

      {/* ═══════════════════════════════════════════════════════
          BUILDING / FINISHING — Full Construction Tracking
         ═══════════════════════════════════════════════════════ */}
      {isBuildingOrFinishing && (
        <>
          {/* ─── STEP 2: Construction Stage ──────────────────── */}
          <div className="border-t border-gray-200 pt-5">
            <div className="flex items-baseline justify-between mb-3">
              <h4 className="text-sm font-bold text-[#004063]
                uppercase tracking-wider">
                Step 2: Current Construction Stage
              </h4>
              {construction.progressPercent !== '' && (
                <span className="text-xs font-semibold text-[#f59e0b]">
                  {construction.progressPercent}% Complete
                </span>
              )}
            </div>

            {/* Visual stage tracker */}
            <div className="space-y-2">
              {STAGE_ORDER.map((stage, idx) => {
                const details   = STAGE_DETAILS[stage];
                const isActive  = construction.currentStage === stage;
                const isPassed  = construction.currentStage &&
                  STAGE_ORDER.indexOf(construction.currentStage as Exclude<ConstructionStage, ''>) > idx;
                const isCurrent = isActive;

                return (
                  <button
                    key={stage}
                    type="button"
                    onClick={() => handleStageSelect(stage)}
                    className={`w-full text-left p-3 rounded-xl border-2
                      transition-all duration-150 group
                      ${isCurrent
                        ? 'border-[#f59e0b] bg-[#fef3c7] shadow-md'
                      : isPassed
                        ? 'border-[#10b981] bg-[#f0fdf4]'
                        : 'border-gray-200 hover:border-gray-300 bg-white'
                      }`}
                  >
                    <div className="flex items-center gap-3">
                      {/* Stage number circle */}
                      <div className={`w-8 h-8 rounded-full flex items-center
                        justify-center text-sm font-bold flex-shrink-0
                        transition-all duration-150
                        ${isCurrent
                          ? 'bg-[#f59e0b] text-white'
                        : isPassed
                          ? 'bg-[#10b981] text-white'
                          : 'bg-gray-100 text-gray-400'
                        }`}>
                        {isPassed ? '✓' : idx + 1}
                      </div>

                      {/* Stage info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-base">{details.icon}</span>
                          <span className={`text-sm font-semibold
                            ${isCurrent
                              ? 'text-[#92400e]'
                            : isPassed
                              ? 'text-[#065f46]'
                              : 'text-gray-700'
                            }`}>
                            {details.label}
                          </span>
                          {isCurrent && (
                            <span className="ml-auto text-xs px-2 py-0.5
                              rounded-full bg-[#f59e0b] text-white font-medium">
                              CURRENT
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-gray-500 mt-0.5">
                          {details.description} · {details.typicalDuration}
                        </p>
                      </div>

                      {/* Stage progress indicator */}
                      <div className="text-xs font-bold flex-shrink-0
                        text-gray-400">
                        {STAGE_PROGRESS_MAP[stage]}%
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>

            {/* Progress % override slider */}
            {construction.currentStage && (
              <div className="mt-4 pt-4 border-t border-gray-100">
                <div className="flex items-center justify-between mb-2">
                  <label htmlFor="progress-pct"
                    className="text-sm font-medium text-gray-700">
                    Override Progress %
                  </label>
                  <span className="text-sm font-bold text-[#f59e0b]">
                    {construction.progressPercent || 0}%
                  </span>
                </div>
                <input
                  id="progress-pct"
                  type="range" min="0" max="100" step="5"
                  value={construction.progressPercent || 0}
                  onChange={(e) =>
                    setConstructionField('progressPercent',
                      parseInt(e.target.value, 10))
                  }
                  className="w-full h-2 bg-gray-200 rounded-full appearance-none
                    cursor-pointer accent-[#f59e0b]"
                />
                <div className="flex justify-between text-xs text-gray-400 mt-1">
                  <span>0%</span>
                  <span>25%</span>
                  <span>50%</span>
                  <span>75%</span>
                  <span>100%</span>
                </div>
                <p className="text-xs text-gray-400 mt-2">
                  💡 Auto-filled from stage. Adjust if your project differs.
                </p>
              </div>
            )}
          </div>

          {/* ─── STEP 3: Timeline ────────────────────────────── */}
          <div className="border-t border-gray-200 pt-5">
            <h4 className="text-sm font-bold text-[#004063]
              uppercase tracking-wider mb-3">
              Step 3: Construction Timeline
            </h4>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="con-start"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Construction Start
                </label>
                <input
                  id="con-start" type="date"
                  value={construction.constructionStart}
                  onChange={(e) =>
                    setConstructionField('constructionStart', e.target.value)
                  }
                  max={new Date().toISOString().split('T')[0]}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#f59e0b] focus:border-transparent"
                />
              </div>
              <div>
                <label htmlFor="con-expected"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Expected Completion
                </label>
                <input
                  id="con-expected" type="date"
                  value={construction.expectedCompletion}
                  onChange={(e) =>
                    setConstructionField('expectedCompletion', e.target.value)
                  }
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#f59e0b] focus:border-transparent"
                />
              </div>
              <div>
                <label htmlFor="con-handover"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Handover Date
                </label>
                <input
                  id="con-handover" type="date"
                  value={construction.handoverDate}
                  onChange={(e) =>
                    setConstructionField('handoverDate', e.target.value)
                  }
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#f59e0b] focus:border-transparent"
                />
                <p className="text-xs text-gray-400 mt-1">
                  When keys delivered to buyer
                </p>
              </div>
              <div>
                <label htmlFor="con-movein"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Move-In Ready
                </label>
                <input
                  id="con-movein" type="date"
                  value={construction.moveInDate}
                  onChange={(e) =>
                    setConstructionField('moveInDate', e.target.value)
                  }
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#f59e0b] focus:border-transparent"
                />
                <p className="text-xs text-gray-400 mt-1">
                  When buyer can move in
                </p>
              </div>
            </div>

            {/* Duration calculator */}
            {construction.constructionStart && construction.expectedCompletion && (
              <div className="mt-3 bg-[#fef3c7] border-l-4 border-[#f59e0b]
                px-3 py-2 rounded-r-lg">
                <p className="text-xs text-amber-800">
                  <strong>Total Duration:</strong>{' '}
                  {(() => {
                    const s = new Date(construction.constructionStart);
                    const e = new Date(construction.expectedCompletion);
                    if (isNaN(s.getTime()) || isNaN(e.getTime())) return 'invalid dates';
                    const months =
                      (e.getFullYear() - s.getFullYear()) * 12 +
                      (e.getMonth() - s.getMonth());
                    if (months < 0) return 'completion before start';
                    const years = Math.floor(months / 12);
                    const rem = months % 12;
                    return `${months} months${years > 0 ? ` (${years}y${rem > 0 ? ` ${rem}m` : ''})` : ''}`;
                  })()}
                </p>
              </div>
            )}
          </div>

          {/* ─── STEP 4: Schedule Status ─────────────────────── */}
          <div className="border-t border-gray-200 pt-5">
            <h4 className="text-sm font-bold text-[#004063]
              uppercase tracking-wider mb-3">
              Step 4: Schedule Status
            </h4>

            <div className="grid grid-cols-3 gap-3">
              {SCHEDULE_STATUS_OPTIONS.map((opt) => {
                const isActive = construction.scheduleStatus === opt.value;
                return (
                  <button
                    key={opt.value}
                    type="button"
                    onClick={() =>
                      setConstructionField('scheduleStatus', opt.value as ScheduleStatus)
                    }
                    className={`flex flex-col items-center gap-2 p-4 rounded-xl
                      border-2 transition-all duration-150
                      ${isActive ? 'shadow-md' : 'border-gray-200 hover:border-gray-300'}`}
                    style={isActive ? {
                      borderColor: opt.color,
                      backgroundColor: opt.bg,
                    } : undefined}
                  >
                    <span className="text-2xl">{opt.icon}</span>
                    <span className={`text-sm font-semibold
                      ${isActive ? '' : 'text-gray-600'}`}
                      style={isActive ? { color: opt.color } : undefined}>
                      {opt.label}
                    </span>
                  </button>
                );
              })}
            </div>

            {/* Delay details (if delayed) */}
            {construction.scheduleStatus === 'delayed' && (
              <div className="mt-4 bg-[#fef2f2] border-2 border-[#ef4444]
                rounded-xl p-4 space-y-3">
                <div className="flex items-start gap-2">
                  <AlertCircle className="w-5 h-5 text-[#ef4444]
                    flex-shrink-0 mt-0.5" />
                  <div>
                    <p className="text-sm font-bold text-[#ef4444]">
                      Delay Disclosure
                    </p>
                    <p className="text-xs text-red-700 mt-1">
                      Transparent disclosure earns the <strong>&quot;Honest Seller&quot;</strong>{' '}
                      trust badge — buyers value honesty over hidden delays.
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label htmlFor="con-orig"
                      className="block text-xs font-medium text-gray-700 mb-1.5">
                      Original Completion Date
                    </label>
                    <input
                      id="con-orig" type="date"
                      value={construction.originalCompletion}
                      onChange={(e) => {
                        const val = e.target.value;
                        setConstructionField('originalCompletion', val);
                        if (val && construction.expectedCompletion) {
                          setConstructionField('delayMonths',
                            calcDelayMonths(val, construction.expectedCompletion));
                        }
                      }}
                      className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm
                        focus:ring-2 focus:ring-[#ef4444] focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1.5">
                      Delay Duration
                    </label>
                    <div className="w-full bg-white border border-[#ef4444]
                      rounded-lg px-3 py-2 text-sm font-bold text-[#ef4444]">
                      {construction.delayMonths || 0} months
                    </div>
                  </div>
                </div>

                <div>
                  <label htmlFor="con-delay-reason"
                    className="block text-xs font-medium text-gray-700 mb-1.5">
                    Reason for Delay
                  </label>
                  <textarea
                    id="con-delay-reason"
                    placeholder="e.g. Material price hike, worker shortage during economic situation, regulatory approvals..."
                    value={construction.delayReason}
                    onChange={(e) =>
                      setConstructionField('delayReason', e.target.value)
                    }
                    rows={2}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm
                      resize-y focus:ring-2 focus:ring-[#ef4444] focus:border-transparent"
                  />
                </div>
              </div>
            )}

            {/* On time / Ahead celebration banner */}
            {(construction.scheduleStatus === 'on_time' ||
              construction.scheduleStatus === 'ahead') && (
              <div className={`mt-4 px-4 py-3 rounded-xl border-l-4
                ${construction.scheduleStatus === 'ahead'
                  ? 'bg-[#f0fdf4] border-[#10b981]'
                  : 'bg-[#eff6ff] border-[#029bba]'
                }`}>
                <p className={`text-sm font-semibold
                  ${construction.scheduleStatus === 'ahead'
                    ? 'text-[#065f46]' : 'text-[#004063]'
                  }`}>
                  {construction.scheduleStatus === 'ahead'
                    ? '⚡ Excellent! Ahead-of-schedule projects earn premium trust badges.'
                    : '✅ Great! On-schedule projects build strong buyer confidence.'}
                </p>
              </div>
            )}
          </div>
        </>
      )}

      {/* ═══════════════════════════════════════════════════════
          READY — Year Built & Renovation
         ═══════════════════════════════════════════════════════ */}
      {construction.projectStatus === 'ready' && (
        <div className="border-t border-gray-200 pt-5">
          <h4 className="text-sm font-bold text-[#004063]
            uppercase tracking-wider mb-3">
            Step 2: Completion Details
          </h4>

          <div className="bg-[#f0fdf4] border-l-4 border-[#10b981]
            px-4 py-3 rounded-r-lg mb-4">
            <p className="text-sm text-[#065f46]">
              ✅ <strong>Ready property:</strong> Just tell buyers when it was built.
              Renovation year is optional but adds value.
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="ready-year-built"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Year Built <span className="text-red-500">*</span>
              </label>
              <input
                id="ready-year-built" type="number"
                min="1900" max={CURRENT_YEAR}
                placeholder={`e.g. ${CURRENT_YEAR - 2}`}
                value={construction.yearBuilt === '' ?
                  (currentTopLevelYearBuilt === '' ? '' : currentTopLevelYearBuilt)
                  : construction.yearBuilt}
                onChange={(e) => {
                  const raw = e.target.value;
                  if (raw === '') { handleYearBuiltChange(''); return; }
                  const n = parseInt(raw, 10);
                  if (!isNaN(n) && n >= 1900 && n <= CURRENT_YEAR)
                    handleYearBuiltChange(n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#10b981] focus:border-transparent"
              />
              {construction.yearBuilt !== '' && (
                <p className="text-xs text-gray-400 mt-1">
                  Property age:{' '}
                  <span className="font-medium text-[#004063]">
                    {CURRENT_YEAR - (construction.yearBuilt as number)} year
                    {CURRENT_YEAR - (construction.yearBuilt as number) !== 1 ? 's' : ''}
                  </span>
                </p>
              )}
            </div>

            <div>
              <label htmlFor="ready-year-renovated"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Last Renovated
              </label>
              <input
                id="ready-year-renovated" type="number"
                min="1900" max={CURRENT_YEAR}
                placeholder="Optional"
                value={construction.yearRenovated === '' ?
                  (currentTopLevelRenovationYear === '' ? '' : currentTopLevelRenovationYear)
                  : construction.yearRenovated}
                onChange={(e) => {
                  const raw = e.target.value;
                  if (raw === '') { handleYearRenovatedChange(''); return; }
                  const n = parseInt(raw, 10);
                  if (!isNaN(n) && n >= 1900 && n <= CURRENT_YEAR)
                    handleYearRenovatedChange(n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#10b981] focus:border-transparent"
              />
              {construction.yearRenovated !== '' &&
               construction.yearBuilt !== '' &&
               (construction.yearRenovated as number) <
                 (construction.yearBuilt as number) && (
                <p className="text-xs text-[#ef4444] mt-1">
                  ⚠ Renovation cannot be before construction
                </p>
              )}
            </div>
          </div>

          {/* Quick year buttons */}
          <div className="mt-4">
            <p className="text-xs text-gray-400 mb-2">Quick select year built:</p>
            <div className="flex flex-wrap gap-2">
              {[
                CURRENT_YEAR,
                CURRENT_YEAR - 1,
                CURRENT_YEAR - 2,
                CURRENT_YEAR - 3,
                CURRENT_YEAR - 5,
                CURRENT_YEAR - 10,
                CURRENT_YEAR - 15,
                CURRENT_YEAR - 20,
              ].map((year) => {
                const isActive = construction.yearBuilt === year;
                return (
                  <button
                    key={year}
                    type="button"
                    onClick={() => handleYearBuiltChange(year)}
                    className={`px-3 py-1 rounded-full text-xs font-medium
                      transition-all duration-150
                      ${isActive
                        ? 'bg-[#10b981] text-white'
                        : 'bg-gray-100 text-gray-500 hover:bg-gray-200'
                      }`}
                  >
                    {year}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════
          PLANNED — Pre-Launch Timeline
         ═══════════════════════════════════════════════════════ */}
      {construction.projectStatus === 'planned' && (
        <div className="border-t border-gray-200 pt-5">
          <h4 className="text-sm font-bold text-[#004063]
            uppercase tracking-wider mb-3">
            Step 2: Pre-Launch Timeline
          </h4>

          <div className="bg-[#eff6ff] border-l-4 border-[#4f46e5]
            px-4 py-3 rounded-r-lg mb-4">
            <p className="text-sm text-[#004063]">
              🚀 <strong>Pre-launch / Planning:</strong> Tell buyers when the
              project will launch and open for booking.
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="plan-launch"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Expected Launch Date
              </label>
              <input
                id="plan-launch" type="date"
                value={construction.expectedLaunch}
                onChange={(e) =>
                  setConstructionField('expectedLaunch', e.target.value)
                }
                min={new Date().toISOString().split('T')[0]}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#4f46e5] focus:border-transparent"
              />
            </div>
            <div>
              <label htmlFor="plan-booking"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Booking Opens
              </label>
              <input
                id="plan-booking" type="date"
                value={construction.bookingOpens}
                onChange={(e) =>
                  setConstructionField('bookingOpens', e.target.value)
                }
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#4f46e5] focus:border-transparent"
              />
            </div>
            <div className="col-span-2">
              <label htmlFor="plan-completion"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Expected Completion
              </label>
              <input
                id="plan-completion" type="date"
                value={construction.expectedCompletion}
                onChange={(e) =>
                  setConstructionField('expectedCompletion', e.target.value)
                }
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#4f46e5] focus:border-transparent"
              />
            </div>
            <div className="col-span-2">
              <label htmlFor="plan-discount"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Pre-Launch Discount (%)
              </label>
              <div className="relative">
                <input
                  id="plan-discount" type="number" min="0" max="50" step="0.5"
                  placeholder="e.g. 15"
                  value={construction.preLaunchDiscount || ''}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') {
                      setConstructionField('preLaunchDiscount', '');
                      return;
                    }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0 && n <= 50)
                      setConstructionField('preLaunchDiscount', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5 pr-8
                    focus:ring-2 focus:ring-[#4f46e5] focus:border-transparent"
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2
                  text-sm font-medium text-gray-400">%</span>
              </div>
              <p className="text-xs text-gray-400 mt-1">
                Discount % offered to early-bird buyers vs launch price
              </p>
            </div>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════
          NO STATUS YET — Prompt
         ═══════════════════════════════════════════════════════ */}
      {!construction.projectStatus && (
        <div className="bg-[#eff6ff] border-l-4 border-[#029bba]
          px-4 py-3 rounded-r-lg">
          <p className="text-sm font-semibold text-[#004063]">
            👆 Select project status above to continue
          </p>
          <p className="text-xs text-gray-500 mt-1">
            Fields will appear based on whether the project is planned,
            being built, finishing, or ready for possession
          </p>
        </div>
      )}
    </div>
  );
}

// ─── Main Component ───────────────────────────────────────────────────────────

export default function TabSize({
  form,
  errors,
  setField,
  setResidentialField,
  setCommercialField,
  setConstructionField,
  fieldConfig: cfg,
}: TabSizeProps): React.ReactElement {
  const pt = form.propertyType as PropertyType | '';
  const con = form.construction;

  // Computed conversions
  const areaSqFt = form.areaSize !== '' && form.areaSize > 0
    ? convertToSqFt(form.areaSize, form.areaUnit) : 0;

  const coveredSqFt = form.coveredArea !== '' && form.coveredArea > 0
    ? convertToSqFt(form.coveredArea, form.coveredAreaUnit) : 0;

  const coveragePercent = areaSqFt > 0 && coveredSqFt > 0
    ? Math.round((coveredSqFt / areaSqFt) * 100) : 0;

  const areaUnits = getAreaUnits(pt);

  // ── Smart area label based on type
  const areaLabel = cfg.plotAreaLabel || 'Total Area';

  return (
    <div className="space-y-5">

      {/* ══════════════════════════════════════════════════════
          SECTION 1 — Primary Area (type-aware label)
         ══════════════════════════════════════════════════════ */}
      <FormSection
        id="size-area"
        title={areaLabel}
        icon={<Ruler className="w-5 h-5" />}
        defaultOpen={true}
        required
        description={
          pt === 'apartment' || pt === 'penthouse' || pt === 'room'
            ? 'Your unit\'s total covered/built-up area'
          : pt === 'shop' || pt === 'office' || pt === 'commercial'
            ? 'Total covered floor area'
          : pt === 'plot'
            ? 'Plot area as per society records'
          : pt === 'house' || pt === 'villa' || pt === 'farmhouse'
            ? 'Total land area (plot size)'
          : pt === 'warehouse' || pt === 'building'
            ? 'Total land area'
          : pt === 'other'
            ? 'Agricultural land area'
          : undefined
        }
        completionStatus={
          form.areaSize !== '' && (form.areaSize as number) > 0
            ? 'complete' : 'incomplete'
        }
      >
        <div className="space-y-4">
          {/* Quick size pills */}
          <QuickSizePills
            sizes={cfg.quickSizes}
            currentSize={form.areaSize}
            currentUnit={form.areaUnit}
            onSelect={(size, unit) => {
              setField('areaSize', size);
              setField('areaUnit', unit);
            }}
            propertyType={pt}
          />

          {/* Area input */}
          <AreaInput
            id="prop-area-size"
            label={areaLabel}
            sizeValue={form.areaSize}
            unitValue={form.areaUnit}
            onSizeChange={(val) => setField('areaSize', val)}
            onUnitChange={(val) => setField('areaUnit', val)}
            error={errors.areaSize}
            required
            availableUnits={areaUnits}
            hint={
              pt === 'apartment'
                ? '✓ This is your apartment\'s TOTAL covered area (walls + rooms + balcony). No separate plot area needed for apartments.'
              : pt === 'penthouse'
                ? '✓ Total covered area of your penthouse. Terrace area can be added separately below.'
              : pt === 'room'
                ? '✓ Total room area in square feet'
              : pt === 'shop'
                ? '✓ Total shop floor area. Mezzanine (if any) can be added separately below.'
              : pt === 'office'
                ? '✓ Total office covered area. Add carpet area below for transparency.'
              : pt === 'plot'
                ? '✓ Plot area as per allotment letter (1 Marla = 272.25 sq ft | 1 Kanal = 20 Marla)'
              : pt === 'house' || pt === 'villa'
                ? '✓ Land/plot area in Marla or Kanal. Covered area (sum of all floors) goes in the next section.'
              : pt === 'farmhouse'
                ? '✓ Total land area in Kanal or Acres. Covered area (constructed portion) goes below.'
              : pt === 'warehouse'
                ? '✓ Total land area including open yard. Covered shed area goes in next section.'
              : pt === 'building'
                ? '✓ Total plot area of the building. Floor plate area goes in next section.'
              : pt === 'other'
                ? '✓ Total agricultural land area in Acres or Kanal'
              : undefined
            }
          />

          {/* Type-specific area info banners */}
          {pt === 'apartment' && (
            <div className="bg-[#eff6ff] border-l-4 border-[#029bba]
              px-4 py-3 rounded-r-lg">
              <p className="text-xs text-[#004063]">
                <strong>Tip:</strong> For apartments, enter the total covered area
                (sq ft). Also fill in Carpet Area below for accurate
                comparison — carpet area is typically 70–80% of total area.
              </p>
            </div>
          )}

          {pt === 'plot' && (
            <div className="bg-[#f0fdf4] border-l-4 border-[#10b981]
              px-4 py-3 rounded-r-lg">
              <p className="text-xs text-[#065f46]">
                <strong>Pakistani standard:</strong> 1 Marla = 272.25 sq ft |
                1 Kanal = 20 Marla | 1 Acre = 8 Kanal.
                Enter the size as shown on your allotment letter or NOC.
              </p>
            </div>
          )}

          {pt === 'warehouse' && (
            <div className="bg-[#fef3c7] border-l-4 border-[#f59e0b]
              px-4 py-3 rounded-r-lg">
              <p className="text-xs text-amber-800">
                <strong>Note:</strong> Enter total land area here.
                Add covered built-up area and open yard area in the
                sections below.
              </p>
            </div>
          )}
        </div>
      </FormSection>

      {/* ══════════════════════════════════════════════════════
          SECTION 2 — Covered / Built-up Area
          (Only shown for types where Plot Area ≠ Covered Area:
           house, villa, farmhouse, warehouse, building)
         ══════════════════════════════════════════════════════ */}
      {cfg.showCoveredArea && (
        <FormSection
          id="size-covered"
          title="Covered / Built-up Area"
          icon={<span className="text-lg">🏗️</span>}
          defaultOpen={true}
          description={
            pt === 'house' || pt === 'villa'
              ? 'Sum of all floors (Ground + 1st + 2nd, etc.)'
            : pt === 'warehouse'
              ? 'Covered shed / factory floor area only'
            : pt === 'building'
              ? 'Total built-up area across all floors'
            : pt === 'farmhouse'
              ? 'Constructed portion of farmhouse'
            : 'Total constructed area'
          }
          completionStatus={
            form.coveredArea !== '' && (form.coveredArea as number) > 0
              ? 'complete' : 'optional'
          }
        >
          <div className="space-y-4">
            {/* Info banner explaining what to enter */}
            <div className="bg-[#eff6ff] border-l-4 border-[#029bba]
              px-4 py-3 rounded-r-lg">
              <p className="text-xs text-[#004063]">
                <strong>How to calculate:</strong>{' '}
                {pt === 'house' || pt === 'villa' ? (
                  <>Add up the covered area of EACH floor.
                  Example: 5 Marla house with Ground (1,000 sqft) + 1st Floor (900 sqft)
                  = <strong>1,900 sqft covered area</strong>.</>
                ) : pt === 'warehouse' ? (
                  <>Enter ONLY the covered/shed area (not the open yard).
                  Open yard area goes in a separate section below.</>
                ) : pt === 'building' ? (
                  <>Total constructed area across all floors including basements.</>
                ) : pt === 'farmhouse' ? (
                  <>Just the constructed living area (not the open farmland).</>
                ) : (
                  <>Total built-up / constructed area in square feet.</>
                )}
              </p>
            </div>

            <AreaInput
              id="prop-covered-area"
              label="Covered Area"
              sizeValue={form.coveredArea}
              unitValue={form.coveredAreaUnit}
              onSizeChange={(val) => setField('coveredArea', val)}
              onUnitChange={(val) => setField('coveredAreaUnit', val)}
              availableUnits={SQFT_AREA_UNITS}
              hint={
                pt === 'house' || pt === 'villa'
                  ? 'Sum of all floors\' covered area'
                : pt === 'warehouse'
                  ? 'Covered shed / factory floor area only'
                : 'Net usable built-up area'
              }
            />

            {/* Coverage ratio */}
            {coveragePercent > 0 && cfg.showPlotArea && (
              <div className="space-y-2">
                <div className="flex justify-between text-xs text-gray-500">
                  <span>Coverage Ratio (built-up vs total area)</span>
                  <span className={`font-semibold ${
                    coveragePercent > 80 ? 'text-[#f59e0b]'
                    : coveragePercent > 60 ? 'text-[#10b981]'
                    : 'text-[#029bba]'
                  }`}>
                    {coveragePercent}%
                  </span>
                </div>
                <div className="h-2.5 bg-gray-100 rounded-full overflow-hidden">
                  <div
                    className={`h-full rounded-full transition-all duration-500 ${
                      coveragePercent > 80 ? 'bg-[#f59e0b]'
                      : coveragePercent > 60 ? 'bg-[#10b981]'
                      : 'bg-[#029bba]'
                    }`}
                    style={{ width: `${Math.min(coveragePercent, 100)}%` }}
                    role="progressbar"
                    aria-valuenow={coveragePercent}
                    aria-valuemin={0}
                    aria-valuemax={100}
                  />
                </div>
                <p className="text-xs text-gray-400">
                  Covered area is {coveragePercent}% of total area
                  {coveragePercent > 80 && (
                    <span className="text-[#f59e0b] ml-1">
                      — high coverage ratio
                    </span>
                  )}
                </p>
              </div>
            )}
          </div>
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 3 — Carpet Area (Apartment / Office / Penthouse)
         ══════════════════════════════════════════════════════ */}
      {cfg.showCarpetArea && (
        <FormSection
          id="size-carpet"
          title="Carpet Area (Net Usable)"
          icon={<span className="text-lg">📏</span>}
          defaultOpen={pt === 'apartment' || pt === 'office' || pt === 'penthouse'}
          description="Actual walkable floor space (optional but builds trust)"
          completionStatus={
            form.residential.carpetArea !== '' &&
            (form.residential.carpetArea as number) > 0
              ? 'complete' : 'optional'
          }
        >
          <div className="space-y-3">
            <div className="bg-[#f0fdf4] border-l-4 border-[#10b981]
              px-4 py-3 rounded-r-lg mb-3">
              <p className="text-xs text-[#065f46]">
                <strong>What is Carpet Area?</strong>{' '}
                The actual floor space you can walk on — excludes walls, balcony,
                lobby, and shared common areas. Typically{' '}
                <strong>70-80% of covered area</strong>.
                <br /><br />
                <strong>Example:</strong> If your apartment is{' '}
                {pt === 'apartment' ? '1,200 sq ft covered' : '1,500 sq ft covered'},
                carpet area is usually around{' '}
                {pt === 'apartment' ? '950 sq ft' : '1,200 sq ft'}.
                <br /><br />
                <strong>Why fill this?</strong> Listings with carpet area get
                a &quot;Transparent Seller&quot; trust badge — 2× more inquiries!
              </p>
            </div>

            <div className="grid grid-cols-5 gap-3">
              <div className="col-span-3">
                <label htmlFor="carpet-area"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Carpet Area
                </label>
                <input
                  id="carpet-area"
                  type="number" step="0.01" min="0"
                  placeholder="e.g. 900"
                  value={form.residential.carpetArea === ''
                    ? '' : form.residential.carpetArea}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') {
                      setResidentialField('carpetArea', '');
                      return;
                    }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0)
                      setResidentialField('carpetArea', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
                />
              </div>
              <div className="col-span-2 flex items-end">
                <div className="w-full bg-gray-50 rounded-lg px-3 py-2.5
                  border border-gray-200 text-sm text-gray-500">
                  sq ft
                </div>
              </div>
            </div>

            {/* Auto ratio */}
            {form.residential.carpetArea !== '' &&
             form.coveredArea !== '' &&
             (form.residential.carpetArea as number) > 0 &&
             (form.coveredArea as number) > 0 && (
              <p className="text-xs text-[#029bba] font-medium">
                Carpet ratio:{' '}
                {Math.round(
                  ((form.residential.carpetArea as number) /
                    convertToSqFt(form.coveredArea as number, form.coveredAreaUnit)
                  ) * 100
                )}% of covered area
              </p>
            )}
          </div>
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 4 — Terrace / Rooftop Area (Penthouse)
         ══════════════════════════════════════════════════════ */}
      {cfg.showTerraceArea && (
        <FormSection
          id="size-terrace"
          title="Private Terrace / Rooftop Area"
          icon={<span className="text-lg">🌆</span>}
          defaultOpen={true}
          description="Exclusive outdoor space for penthouse"
          completionStatus={
            form.residential.terraceArea !== '' &&
            (form.residential.terraceArea as number) > 0
              ? 'complete' : 'optional'
          }
        >
          <div className="space-y-3">
            <div className="grid grid-cols-5 gap-3">
              <div className="col-span-3">
                <label htmlFor="terrace-area"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  Terrace / Rooftop Area (sq ft)
                </label>
                <input
                  id="terrace-area"
                  type="number" step="0.01" min="0"
                  placeholder="e.g. 500"
                  value={form.residential.terraceArea === ''
                    ? '' : form.residential.terraceArea}
                  onChange={(e) => {
                    const raw = e.target.value;
                    if (raw === '') {
                      setResidentialField('terraceArea', '');
                      return;
                    }
                    const n = parseFloat(raw);
                    if (!isNaN(n) && n >= 0)
                      setResidentialField('terraceArea', n);
                  }}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
                />
              </div>
              <div className="col-span-2 flex items-end">
                <div className="w-full bg-gray-50 rounded-lg px-3 py-2.5
                  border border-gray-200 text-sm text-gray-500">
                  sq ft
                </div>
              </div>
            </div>
            <p className="text-xs text-gray-400">
              Private rooftop / terrace exclusive to this penthouse
            </p>
          </div>
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 5 — Mezzanine Area (Shop / Commercial)
         ══════════════════════════════════════════════════════ */}
      {cfg.showMezzanineArea && form.commercial.hasMezzanine && (
        <FormSection
          id="size-mezzanine"
          title="Mezzanine Floor Area"
          icon={<span className="text-lg">↕️</span>}
          defaultOpen={true}
          description="Upper half-floor inside the shop"
          completionStatus={
            form.commercial.mezzanineArea !== '' &&
            (form.commercial.mezzanineArea as number) > 0
              ? 'complete' : 'optional'
          }
        >
          <div className="grid grid-cols-5 gap-3">
            <div className="col-span-3">
              <label htmlFor="mezzanine-area"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Mezzanine Area (sq ft)
              </label>
              <input
                id="mezzanine-area"
                type="number" step="0.01" min="0"
                placeholder="e.g. 150"
                value={form.commercial.mezzanineArea === ''
                  ? '' : form.commercial.mezzanineArea}
                onChange={(e) => {
                  const raw = e.target.value;
                  if (raw === '') {
                    setCommercialField('mezzanineArea', '');
                    return;
                  }
                  const n = parseFloat(raw);
                  if (!isNaN(n) && n >= 0)
                    setCommercialField('mezzanineArea', n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
              />
            </div>
            <div className="col-span-2 flex items-end">
              <div className="w-full bg-gray-50 rounded-lg px-3 py-2.5
                border border-gray-200 text-sm text-gray-500">
                sq ft
              </div>
            </div>
          </div>
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 6 — Open Yard Area (Warehouse)
         ══════════════════════════════════════════════════════ */}
      {cfg.showOpenYardArea && (
        <FormSection
          id="size-yard"
          title="Open Yard / Parking Area"
          icon={<span className="text-lg">🏭</span>}
          defaultOpen={false}
          description="Uncovered outdoor area within compound"
          completionStatus={
            form.commercial.openYardArea !== '' &&
            (form.commercial.openYardArea as number) > 0
              ? 'complete' : 'optional'
          }
        >
          <div className="grid grid-cols-5 gap-3">
            <div className="col-span-3">
              <label htmlFor="yard-area"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Open Yard Area (sq ft)
              </label>
              <input
                id="yard-area"
                type="number" step="0.01" min="0"
                placeholder="e.g. 2000"
                value={form.commercial.openYardArea === ''
                  ? '' : form.commercial.openYardArea}
                onChange={(e) => {
                  const raw = e.target.value;
                  if (raw === '') {
                    setCommercialField('openYardArea', '');
                    return;
                  }
                  const n = parseFloat(raw);
                  if (!isNaN(n) && n >= 0)
                    setCommercialField('openYardArea', n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
              />
            </div>
            <div className="col-span-2 flex items-end">
              <div className="w-full bg-gray-50 rounded-lg px-3 py-2.5
                border border-gray-200 text-sm text-gray-500">
                sq ft
              </div>
            </div>
          </div>
          <p className="text-xs text-gray-400 mt-2">
            Useful for truck parking, loading/unloading space
          </p>
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 7 — Floor Plate Area (Building)
         ══════════════════════════════════════════════════════ */}
      {cfg.showFloorPlateArea && (
        <FormSection
          id="size-floor-plate"
          title="Floor Plate Area"
          icon={<span className="text-lg">🏢</span>}
          defaultOpen={false}
          description="Area per single floor"
          completionStatus={
            form.commercial.floorPlateArea !== '' &&
            (form.commercial.floorPlateArea as number) > 0
              ? 'complete' : 'optional'
          }
        >
          <div className="grid grid-cols-5 gap-3">
            <div className="col-span-3">
              <label htmlFor="floor-plate"
                className="block text-sm font-medium text-gray-700 mb-1.5">
                Area per Floor (sq ft)
              </label>
              <input
                id="floor-plate"
                type="number" step="0.01" min="0"
                placeholder="e.g. 3000"
                value={form.commercial.floorPlateArea === ''
                  ? '' : form.commercial.floorPlateArea}
                onChange={(e) => {
                  const raw = e.target.value;
                  if (raw === '') {
                    setCommercialField('floorPlateArea', '');
                    return;
                  }
                  const n = parseFloat(raw);
                  if (!isNaN(n) && n >= 0)
                    setCommercialField('floorPlateArea', n);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                  focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
              />
            </div>
            <div className="col-span-2 flex items-end">
              <div className="w-full bg-gray-50 rounded-lg px-3 py-2.5
                border border-gray-200 text-sm text-gray-500">
                sq ft
              </div>
            </div>
          </div>
          {/* Total building area estimate */}
          {form.commercial.floorPlateArea !== '' &&
           form.totalFloors !== '' &&
           (form.commercial.floorPlateArea as number) > 0 &&
           (form.totalFloors as number) > 0 && (
            <div className="mt-3 bg-gray-50 rounded-lg p-3 border border-gray-200">
              <div className="flex justify-between text-sm">
                <span className="text-gray-600">
                  Estimated Total Building Area
                </span>
                <span className="font-semibold text-[#004063]">
                  {(
                    (form.commercial.floorPlateArea as number) *
                    (form.totalFloors as number)
                  ).toLocaleString('en-PK')}{' '}
                  sq ft
                </span>
              </div>
              <p className="text-xs text-gray-400 mt-1">
                {form.commercial.floorPlateArea} sq ft ×{' '}
                {form.totalFloors} floors
              </p>
            </div>
          )}
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 8 — Plot Dimensions (W × L)
         ══════════════════════════════════════════════════════ */}
      {cfg.showPlotDimensions && (
        <FormSection
          id="size-dimensions"
          title="Plot / Unit Dimensions"
          icon={<PenTool className="w-5 h-5" />}
          defaultOpen={pt === 'plot'}
          description="Width × Length in feet"
          completionStatus={
            form.plotWidth !== '' && form.plotLength !== ''
              ? 'complete' : 'optional'
          }
        >
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <NumberInput
                id="prop-width"
                label="Width (ft)"
                value={form.plotWidth}
                onChange={(val) => setField('plotWidth', val)}
                placeholder="e.g. 25"
                step={0.5}
                suffix="ft"
              />
              <NumberInput
                id="prop-length"
                label="Length / Depth (ft)"
                value={form.plotLength}
                onChange={(val) => setField('plotLength', val)}
                placeholder="e.g. 50"
                step={0.5}
                suffix="ft"
              />
            </div>

            {/* Computed area */}
            {form.plotWidth !== '' && form.plotLength !== '' &&
             (form.plotWidth as number) > 0 && (form.plotLength as number) > 0 && (
              <div className="bg-gray-50 rounded-lg p-3 border border-gray-200">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-600">
                    Computed Area:
                  </span>
                  <span className="text-sm font-semibold text-[#004063]">
                    {form.plotWidth} × {form.plotLength} ={' '}
                    {(
                      (form.plotWidth as number) *
                      (form.plotLength as number)
                    ).toLocaleString('en-PK')}{' '}
                    sq ft
                  </span>
                </div>
                <div className="flex items-center justify-between mt-1">
                  <span className="text-xs text-gray-400">
                    In Marla:
                  </span>
                  <span className="text-xs font-medium text-[#029bba]">
                    {(
                      ((form.plotWidth as number) *
                        (form.plotLength as number)) / 272.25
                    ).toFixed(2)}{' '}
                    Marla
                  </span>
                </div>
                <div className="flex items-center justify-between mt-0.5">
                  <span className="text-xs text-gray-400">In Kanal:</span>
                  <span className="text-xs font-medium text-[#004063]">
                    {(
                      ((form.plotWidth as number) *
                        (form.plotLength as number)) / 5445
                    ).toFixed(3)}{' '}
                    Kanal
                  </span>
                </div>
              </div>
            )}

            {/* Common plot dimension presets */}
            {pt === 'plot' && (
              <div>
                <p className="text-xs text-gray-400 mb-2">
                  Common plot dimensions:
                </p>
                <div className="flex flex-wrap gap-2">
                  {[
                    { label: '25×45 (3M)', w: 25,  l: 45  },
                    { label: '25×50 (3M)', w: 25,  l: 50  },
                    { label: '30×60 (5M)', w: 30,  l: 60  },
                    { label: '35×70 (7M)', w: 35,  l: 70  },
                    { label: '40×80 (10M)',w: 40,  l: 80  },
                    { label: '50×90 (1K)', w: 50,  l: 90  },
                  ].map((preset) => {
                    const isActive =
                      form.plotWidth === preset.w &&
                      form.plotLength === preset.l;
                    return (
                      <button
                        key={preset.label}
                        type="button"
                        onClick={() => {
                          setField('plotWidth', preset.w);
                          setField('plotLength', preset.l);
                        }}
                        className={`px-3 py-1.5 rounded-full text-xs font-medium
                          transition-all duration-150
                          ${isActive
                            ? 'bg-[#029bba] text-white shadow-sm'
                            : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                          }`}
                      >
                        {preset.label}
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 9 — Balconies (Apartment / Penthouse)
         ══════════════════════════════════════════════════════ */}
      {(pt === 'apartment' || pt === 'penthouse') && (
        <FormSection
          id="size-balcony"
          title="Balconies & View"
          icon={<span className="text-lg">🌅</span>}
          defaultOpen={false}
          completionStatus="optional"
        >
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              {/* Number of balconies */}
              <NumberInput
                id="prop-balconies"
                label="Number of Balconies"
                value={form.residential.balconies}
                onChange={(val) =>
                  setResidentialField('balconies', val)
                }
                placeholder="e.g. 2"
                min={0} max={10} step={1}
              />

              {/* View type */}
              <div>
                <label htmlFor="prop-view"
                  className="block text-sm font-medium text-gray-700 mb-1.5">
                  View Type
                </label>
                <select
                  id="prop-view"
                  value={form.residential.view}
                  onChange={(e) =>
                    setResidentialField('view', e.target.value)
                  }
                  className="w-full border border-gray-300 rounded-lg px-4 py-2.5
                    focus:ring-2 focus:ring-[#029bba] focus:border-transparent"
                >
                  <option value="">Select view...</option>
                  <option value="sea_view">Sea / Lake View</option>
                  <option value="garden_view">Garden / Park View</option>
                  <option value="city_view">City / Skyline View</option>
                  <option value="mountain_view">Mountain View</option>
                  <option value="golf_view">Golf Course View</option>
                  <option value="pool_view">Pool View</option>
                  <option value="street_view">Street View</option>
                  <option value="no_view">No Specific View</option>
                </select>
              </div>
            </div>
          </div>
        </FormSection>
      )}

      {/* ══════════════════════════════════════════════════════
          SECTION 10 — Construction Journey (Enterprise)
          Unified lifecycle tracking — replaces simple year input
         ══════════════════════════════════════════════════════ */}
      {cfg.showConstructionYear && (
        <FormSection
          id="size-construction-journey"
          title="Construction Journey"
          icon={<HardHat className="w-5 h-5" />}
          defaultOpen={true}
          description={
            con.projectStatus === 'ready'
              ? `Completed in ${con.yearBuilt || 'N/A'}`
            : con.projectStatus === 'building'
              ? `${con.progressPercent || '?'}% complete — ${
                  con.currentStage
                    ? STAGE_DETAILS[con.currentStage]?.label
                    : 'stage not set'
                }`
            : con.projectStatus === 'finishing'
              ? 'Near completion — finishing stage'
            : con.projectStatus === 'planned'
              ? 'Pre-launch / planning phase'
            : 'Tell buyers what stage your property is at'
          }
