// hooks/usePropertyForm.ts

import { useState, useCallback, ChangeEvent } from 'react';
import {
  PropertyFormData,
  PropertyFormErrors,
  initialPropertyFormData,
} from '@/types/property';
import {
  validatePropertyForm,
  validateTitle,
  validatePrice,
  validateArea,
  validateDeveloper,
  validateCity,
  validateBedrooms,
  validateBathrooms,
  validateDescription,
  validateVideo,
  validateImages,
  hasErrors,
} from '@/lib/validators/propertyValidators';

interface UsePropertyFormReturn {
  formData: PropertyFormData;
  errors: PropertyFormErrors;
  touched: Record<string, boolean>;
  isSubmitting: boolean;
  handleChange: (
    e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => void;
  handleCheckboxChange: (e: ChangeEvent<HTMLInputElement>) => void;
  handleImageChange: (files: File[]) => void;
  removeImage: (index: number) => void;
  handleBlur: (field: string) => void;
  validateField: (field: string) => void;
  validateAll: () => boolean;
  resetForm: () => void;
  setIsSubmitting: (value: boolean) => void;
}

export const usePropertyForm = (): UsePropertyFormReturn => {
  const [formData, setFormData] = useState<PropertyFormData>(initialPropertyFormData);
  const [errors, setErrors] = useState<PropertyFormErrors>({});
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Handle text/select inputs
  const handleChange = useCallback(
    (e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
      const { name, value } = e.target;
      
      setFormData((prev) => ({
        ...prev,
        [name]: value,
      }));

      // Clear error when user starts typing
      if (errors[name as keyof PropertyFormErrors]) {
        setErrors((prev) => {
          const newErrors = { ...prev };
          delete newErrors[name as keyof PropertyFormErrors];
          return newErrors;
        });
      }
    },
    [errors]
  );

  // Handle checkbox inputs
  const handleCheckboxChange = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      const { name, checked } = e.target;
      setFormData((prev) => ({
        ...prev,
        [name]: checked,
      }));
    },
    []
  );

  // Handle image files
  const handleImageChange = useCallback(
    (files: File[]) => {
      setFormData((prev) => {
        const newImages = [...prev.images, ...files].slice(0, 10); // Max 10
        return {
          ...prev,
          images: newImages,
        };
      });

      // Clear image error
      if (errors.images) {
        setErrors((prev) => {
          const newErrors = { ...prev };
          delete newErrors.images;
          return newErrors;
        });
      }
    },
    [errors]
  );

  // Remove image by index
  const removeImage = useCallback((index: number) => {
    setFormData((prev) => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index),
    }));
  }, []);

  // Handle field blur (for real-time validation)
  const handleBlur = useCallback((field: string) => {
    setTouched((prev) => ({
      ...prev,
      [field]: true,
    }));
    validateField(field);
  }, []);

    // Validate single field
  const validateField = useCallback(
    (field: string) => {
      let error: string | undefined;

      switch (field) {
        case 'title':
          error = validateTitle(formData.title);
          break;
        case 'price':
          error = validatePrice(formData.price);
          break;
        case 'area':
          error = validateArea(formData.area);
          break;
        case 'developer':
          error = validateDeveloper(formData.developer);
          break;
        case 'city':
          error = validateCity(formData.city);
          break;
        case 'bedrooms':
          // Legacy validator propertyType expect karta hai
          error = validateBedrooms(formData.bedrooms, formData.propertyType);
          break;
        case 'bathrooms':
          error = validateBathrooms(formData.bathrooms, formData.propertyType);
          break;
        case 'description':
          error = validateDescription(formData.description);
          break;
        case 'video':
          // Legacy form field ka naam "video" hai (types/property.ts me)
          error = validateVideo(formData.video);
          break;
        case 'images':
          error = validateImages(formData.images);
          break;
      }

      setErrors((prev) => {
        if (error) {
          return { ...prev, [field]: error };
        } else {
          const newErrors = { ...prev };
          delete newErrors[field as keyof PropertyFormErrors];
          return newErrors;
        }
      });
    },
    [formData]
  );

  // Validate entire form
  const validateAll = useCallback((): boolean => {
    const newErrors = validatePropertyForm(formData);
    setErrors(newErrors);

    // Mark all fields as touched
    const allTouched: Record<string, boolean> = {};
    Object.keys(formData).forEach((key) => {
      allTouched[key] = true;
    });
    setTouched(allTouched);

    return !hasErrors(newErrors);
  }, [formData]);

  // Reset form
  const resetForm = useCallback(() => {
    setFormData(initialPropertyFormData);
    setErrors({});
    setTouched({});
    setIsSubmitting(false);
  }, []);

  return {
    formData,
    errors,
    touched,
    isSubmitting,
    handleChange,
    handleCheckboxChange,
    handleImageChange,
    removeImage,
    handleBlur,
    validateField,
    validateAll,
    resetForm,
    setIsSubmitting,
  };
};

/**
 * hooks/useShare.ts
 *
 * Enterprise share hook for Highrise.pk project cards.
 *
 * Features:
 *   → Web Share API (native mobile sheet)
 *   → Per-channel UTM URL generation
 *   → QR code generation (qrcode package)
 *   → Share event logging (POST /api/projects/share)
 *   → Copy-to-clipboard with feedback
 *   → Print-friendly trigger
 *   → Zero external state dependencies
 *
 * Rules:
 *   → No framer-motion
 *   → No toast libraries
 *   → Lucide icons only (in consuming component)
 *   → Works 100% without login (guest-first)
 */

import { useState, useCallback, useRef } from 'react';
import type QRCode from 'qrcode';
import type { ShareChannel, ShareEvent } from '@/types/projects';

// ─── TYPES ───────────────────────────────────────────────────────────────────

export interface ShareTarget {
  projectId:   string;
  projectSlug: string;
  projectName: string;
  city:        string;
  area:        string;
  minPrice:    number | null;
  maxPrice:    number | null;
  priceOnRequest: boolean;
  shieldScore: number;
  primaryImage: string | null;
  developerName: string;
  nocStatus:   'approved' | 'pending' | 'not_applied';
}

export interface UseShareReturn {
  // State
  copyState:   'idle' | 'copied' | 'error';
  qrDataUrl:   string | null;
  qrLoading:   boolean;
  shareLoading: boolean;

  // Actions
  shareViaChannel:   (channel: ShareChannel, target: ShareTarget) => Promise<void>;
  generateQrCode:    (target: ShareTarget) => Promise<void>;
  triggerNativeShare:(target: ShareTarget) => Promise<boolean>;
  canNativeShare:    boolean;
}

// ─── CONSTANTS ────────────────────────────────────────────────────────────────

const BASE_URL = 'https://highrise.pk';

// ─── URL BUILDER ─────────────────────────────────────────────────────────────

function buildShareUrl(
  slug: string,
  channel: ShareChannel,
): string {
  const base = `${BASE_URL}/projects/${slug}`;
  const params = new URLSearchParams({
    utm_source:   'highrise_share',
    utm_medium:   channel,
    utm_campaign: slug,
    utm_content:  'project_card',
  });
  return `${base}?${params.toString()}`;
}

// ─── MESSAGE BUILDER ─────────────────────────────────────────────────────────

function buildWhatsAppMessage(target: ShareTarget, url: string): string {
  const priceStr = target.priceOnRequest
    ? 'Price on Request'
    : target.minPrice && target.maxPrice
      ? `PKR ${formatPKRShort(target.minPrice)} – ${formatPKRShort(target.maxPrice)}`
      : target.minPrice
        ? `PKR ${formatPKRShort(target.minPrice)}+`
        : 'Contact for Price';

  const nocStr = target.nocStatus === 'approved' ? '✅ NOC Approved' : '';
  const shieldStr = `🛡️ Shield Score: ${target.shieldScore}/100`;
  const location = [target.area, target.city].filter(Boolean).join(', ');

  return [
    `🏢 *${target.projectName}*`,
    `📍 ${location}`,
    `💰 ${priceStr}`,
    shieldStr,
    nocStr,
    ``,
    `🔗 View on Highrise.pk:`,
    url,
    ``,
    `_Pakistan's most trusted property portal_`,
  ]
    .filter(line => line !== null && line !== undefined)
    .join('\n');
}

function buildEmailBody(target: ShareTarget, url: string): string {
  const priceStr = target.priceOnRequest
    ? 'Price on Request'
    : target.minPrice && target.maxPrice
      ? `PKR ${formatPKRShort(target.minPrice)} – ${formatPKRShort(target.maxPrice)}`
      : target.minPrice
        ? `PKR ${formatPKRShort(target.minPrice)}+`
        : 'Contact for Price';

  const location = [target.area, target.city].filter(Boolean).join(', ');

  return [
    `I found this property on Highrise.pk and wanted to share it with you:`,
    ``,
    `Project: ${target.projectName}`,
    `Developer: ${target.developerName}`,
    `Location: ${location}`,
    `Price: ${priceStr}`,
    `Shield Score: ${target.shieldScore}/100`,
    target.nocStatus === 'approved' ? `NOC Status: Approved ✓` : '',
    ``,
    `View full details: ${url}`,
    ``,
    `— Shared via Highrise.pk`,
    `Pakistan's most trusted property portal`,
  ]
    .filter(line => line !== null)
    .join('\n');
}

// ─── PKR FORMATTER (standalone — no import to keep hook self-contained) ───────

function formatPKRShort(amount: number): string {
  if (amount >= 1_000_000_000) {
    const v = amount / 1_000_000_000;
    return `${v % 1 === 0 ? v : v.toFixed(1)} Arab`;
  }
  if (amount >= 10_000_000) {
    const v = amount / 10_000_000;
    return `${v % 1 === 0 ? v : v.toFixed(1)} Cr`;
  }
  if (amount >= 100_000) {
    const v = amount / 100_000;
    return `${v % 1 === 0 ? v : v.toFixed(1)} Lakh`;
  }
  return amount.toLocaleString('en-PK');
}

// ─── LOG SHARE EVENT ─────────────────────────────────────────────────────────

async function logShareEvent(event: ShareEvent): Promise<void> {
  try {
    await fetch('/api/projects/share', {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify(event),
    });
  } catch {
    // Non-critical — never block user action on analytics failure
  }
}

// ─── MAIN HOOK ───────────────────────────────────────────────────────────────

export function useShare(): UseShareReturn {
  const [copyState,    setCopyState]    = useState<'idle' | 'copied' | 'error'>('idle');
  const [qrDataUrl,    setQrDataUrl]    = useState<string | null>(null);
  const [qrLoading,    setQrLoading]    = useState(false);
  const [shareLoading, setShareLoading] = useState(false);

  // Debounce copy reset
  const copyResetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const canNativeShare =
    typeof navigator !== 'undefined' && Boolean(navigator.share);

  // ── Native Share API ────────────────────────────────────────────────────────
  const triggerNativeShare = useCallback(
    async (target: ShareTarget): Promise<boolean> => {
      if (!canNativeShare) return false;

      const url = buildShareUrl(target.projectSlug, 'native');
      const location = [target.area, target.city].filter(Boolean).join(', ');

      try {
        await navigator.share({
          title: target.projectName,
          text:  `${target.projectName} — ${location} | Highrise.pk`,
          url,
        });

        void logShareEvent({
          projectId:   target.projectId,
          projectSlug: target.projectSlug,
          channel:     'native',
          timestamp:   new Date().toISOString(),
          utmSource:   'highrise_share',
          utmMedium:   'native',
          utmCampaign: target.projectSlug,
        });

        return true;
      } catch (err) {
        // User cancelled — not an error
        if (err instanceof Error && err.name === 'AbortError') return false;
        return false;
      }
    },
    [canNativeShare],
  );

  // ── Per-Channel Share ───────────────────────────────────────────────────────
  const shareViaChannel = useCallback(
    async (channel: ShareChannel, target: ShareTarget): Promise<void> => {
      setShareLoading(true);

      const url      = buildShareUrl(target.projectSlug, channel);
      const location = [target.area, target.city].filter(Boolean).join(', ');

      try {
        switch (channel) {

          // ── WhatsApp ────────────────────────────────────────────────────────
          case 'whatsapp': {
            const msg = buildWhatsAppMessage(target, url);
            const waUrl = `https://wa.me/?text=${encodeURIComponent(msg)}`;
            window.open(waUrl, '_blank', 'noopener,noreferrer');
            break;
          }

          // ── Facebook ────────────────────────────────────────────────────────
          case 'facebook': {
            const fbUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`;
            window.open(fbUrl, '_blank', 'noopener,noreferrer,width=600,height=400');
            break;
          }

          // ── Twitter / X ─────────────────────────────────────────────────────
          case 'twitter': {
            const priceStr = target.priceOnRequest
              ? ''
              : target.minPrice
                ? ` | PKR ${formatPKRShort(target.minPrice)}+`
                : '';
            const tweet = `🏢 ${target.projectName} — ${location}${priceStr} | 🛡️ Shield ${target.shieldScore}/100\n\nView on @HighrisePK:`;
            const twUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(tweet)}&url=${encodeURIComponent(url)}`;
            window.open(twUrl, '_blank', 'noopener,noreferrer,width=600,height=400');
            break;
          }

          // ── LinkedIn ────────────────────────────────────────────────────────
          case 'linkedin': {
            const liUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`;
            window.open(liUrl, '_blank', 'noopener,noreferrer,width=600,height=400');
            break;
          }

          // ── Email ────────────────────────────────────────────────────────────
          // Handled by ShareMenu's email panel — NOT mailto:
          // This case is a no-op; the UI shows provider buttons directly.
          case 'email': {
            // Email sharing is handled by ShareMenu's email provider panel.
            // This case intentionally does nothing — the channel click
            // toggles the email panel visibility in ShareMenu.tsx.
            break;
          }

          // ── Copy Link ────────────────────────────────────────────────────────
          case 'copy_link': {
            if (copyResetTimer.current) {
              clearTimeout(copyResetTimer.current);
            }
            try {
              await navigator.clipboard.writeText(url);
              setCopyState('copied');
            } catch {
              // Fallback for older browsers / non-HTTPS
              const textarea = document.createElement('textarea');
              textarea.value = url;
              textarea.style.position = 'fixed';
              textarea.style.opacity  = '0';
              document.body.appendChild(textarea);
              textarea.focus();
              textarea.select();
              try {
                document.execCommand('copy');
                setCopyState('copied');
              } catch {
                setCopyState('error');
              }
              document.body.removeChild(textarea);
            }
            copyResetTimer.current = setTimeout(
              () => setCopyState('idle'),
              2500,
            );
            break;
          }

          // ── QR Code ─────────────────────────────────────────────────────────
          // QR generation is handled separately via generateQrCode()
          // This case just logs the event
          case 'qr_code': {
            break;
          }

          // ── Native ───────────────────────────────────────────────────────────
          case 'native': {
            await triggerNativeShare(target);
            break;
          }
        }

        // Log event for all channels except copy_link
        // (copy_link sets its own state, no need to double-fire)
        if (channel !== 'copy_link' && channel !== 'qr_code') {
          void logShareEvent({
            projectId:   target.projectId,
            projectSlug: target.projectSlug,
            channel,
            timestamp:   new Date().toISOString(),
            utmSource:   'highrise_share',
            utmMedium:   channel,
            utmCampaign: target.projectSlug,
          });
        }

      } finally {
        setShareLoading(false);
      }
    },
    [triggerNativeShare],
  );

  // ── QR Code Generation ──────────────────────────────────────────────────────
  const generateQrCode = useCallback(
    async (target: ShareTarget): Promise<void> => {
      setQrLoading(true);
      try {
        const url = buildShareUrl(target.projectSlug, 'qr_code');

        // Dynamic import — code-splits qrcode from main bundle
        const QRCodeLib = await import('qrcode') as typeof QRCode;

        const dataUrl = await QRCodeLib.toDataURL(url, {
          width:           256,
          margin:          2,
          color: {
            dark:  '#004063', // Highrise Navy
            light: '#ffffff',
          },
          errorCorrectionLevel: 'M',
        });

        setQrDataUrl(dataUrl);

        void logShareEvent({
          projectId:   target.projectId,
          projectSlug: target.projectSlug,
          channel:     'qr_code',
          timestamp:   new Date().toISOString(),
          utmSource:   'highrise_share',
          utmMedium:   'qr_code',
          utmCampaign: target.projectSlug,
        });

      } catch (err) {
        console.error('[useShare] QR generation failed:', err);
      } finally {
        setQrLoading(false);
      }
    },
    [],
  );

  return {
    copyState,
    qrDataUrl,
    qrLoading,
    shareLoading,
    shareViaChannel,
    generateQrCode,
    triggerNativeShare,
    canNativeShare,
  };
}

// ─── EMAIL PROVIDER HELPERS ───────────────────────────────────────────────────
// Direct compose URLs for major email providers.
// These open the provider's compose window pre-filled with project details.
// No mailto: interception by Chrome.

export interface EmailShareData {
  subject: string;
  body:    string;
}

export function buildEmailShareData(target: ShareTarget): EmailShareData {
  const url = buildShareUrl(target.projectSlug, 'email');

  const priceStr = target.priceOnRequest
    ? 'Price on Request'
    : target.minPrice && target.maxPrice
      ? `PKR ${formatPKRShort(target.minPrice)} – ${formatPKRShort(target.maxPrice)}`
      : target.minPrice
        ? `PKR ${formatPKRShort(target.minPrice)}+`
        : 'Contact for Price';

  const location = [target.area, target.city].filter(Boolean).join(', ');

  const subject = `Check out ${target.projectName} on Highrise.pk`;

  const body = [
    `I found this property on Highrise.pk and wanted to share it with you:`,
    ``,
    `Project: ${target.projectName}`,
    `Developer: ${target.developerName}`,
    `Location: ${location}`,
    `Price: ${priceStr}`,
    `Shield Score: ${target.shieldScore}/100`,
    target.nocStatus === 'approved' ? `NOC Status: Approved ✓` : '',
    ``,
    `View full details: ${url}`,
    ``,
    `— Shared via Highrise.pk`,
    `Pakistan's most trusted property portal`,
  ]
    .filter(line => line !== null)
    .join('\n');

  return { subject, body };
}

export type EmailProvider = 'gmail' | 'outlook' | 'yahoo';

export function getEmailProviderUrl(
  provider: EmailProvider,
  data: EmailShareData,
): string {
  const subject = encodeURIComponent(data.subject);
  const body    = encodeURIComponent(data.body);

  switch (provider) {
    case 'gmail':
      return `https://mail.google.com/mail/?view=cm&fs=1&su=${subject}&body=${body}`;
    case 'outlook':
      return `https://outlook.live.com/mail/0/deeplink/compose?subject=${subject}&body=${body}`;
    case 'yahoo':
      return `https://compose.mail.yahoo.com/?subject=${subject}&body=${body}`;
  }
}

// lib/apiClient.ts
// Clean API Client - Uses session for auth (no query params)

type HttpMethod = 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE';

interface ApiOptions {
  method?: HttpMethod;
  body?: any;
  headers?: Record<string, string>;
}

// API Response type - any extra fields allowed
interface ApiResponse {
  success: boolean;
  data?: any;
  message?: string;
  error?: string;
  stats?: any;
  pagination?: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
  [key: string]: any; // Allow any additional properties
}

// Main API function - ye har jagah use hoga
export async function apiClient(
  endpoint: string,
  options: ApiOptions = {}
): Promise<ApiResponse> {
  const { method = 'GET', body, headers = {} } = options;

  // Build URL - NO userRole/userEmail params (backend uses session)
  let url: string;
  
  if (typeof window !== 'undefined') {
    url = endpoint.startsWith('http')
      ? endpoint
      : `${window.location.origin}${endpoint}`;
  } else {
    // Server-side fallback
    url = endpoint;
  }

  try {
    const response = await fetch(url, {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...headers,
      },
      credentials: 'include', // Important: session cookies bhejne ke liye
      ...(body && { body: JSON.stringify(body) }),
    });

    const data = await response.json();

    if (!response.ok) {
      return {
        success: false,
        message: data.message || 'Request failed',
        error: data.error,
      };
    }

    return data;
  } catch (error) {
    console.error('API Error:', error);
    return {
      success: false,
      message: 'Network error. Please try again.',
    };
  }
}

// Shortcut functions - easy to use
export const api = {
  get: (endpoint: string) => 
    apiClient(endpoint, { method: 'GET' }),

  post: (endpoint: string, body: any) => 
    apiClient(endpoint, { method: 'POST', body }),

  patch: (endpoint: string, body: any) => 
    apiClient(endpoint, { method: 'PATCH', body }),

  put: (endpoint: string, body: any) => 
    apiClient(endpoint, { method: 'PUT', body }),

  delete: (endpoint: string) => 
    apiClient(endpoint, { method: 'DELETE' }),
};

// lib/autoProtection.ts
import Property from "@/models/Property";
import Report from "@/models/Report";
import { computePropertyRisk } from "@/lib/riskEngine";

/**
 * Auto protection rules (existing):
 * - 3+ unique IPs (24h) => auto reviewing
 * - 5+ unique IPs (24h) => auto soft delete + flagged
 *
 * Phase 3.5 add-on:
 * - If RiskScore >= 8 => mark as flagged (trust-first) even if thresholds not hit
 *   (does NOT hard delete; preserves soft delete architecture)
 */

export async function applyAutoProtectionForProperty(propertyId: string) {
  const since = new Date(Date.now() - 24 * 60 * 60 * 1000);

  // Count unique ipHash for this property in last 24h
  const rows = await Report.aggregate([
    { $match: { propertyId: (Report as any).db.base.Types.ObjectId(propertyId), createdAt: { $gte: since } } },
  ]).catch(async () => {
    // fallback if aggregation ObjectId path fails in some envs
    // we'll do a safer route below
    return null;
  });

  // Safe count unique ipHash (works in all cases)
  const agg = await Report.aggregate([
    { $match: { propertyId: new (require("mongoose").Types.ObjectId)(propertyId), createdAt: { $gte: since } } },
    { $group: { _id: "$ipHash" } },
    { $count: "count" },
  ]);

  const uniqueIpCount24h = agg?.[0]?.count ?? 0;

  const property = await Property.findById(propertyId);
  if (!property) return { uniqueIpCount24h, action: "none" as const };

  // IMPORTANT: never do anything if already soft-deleted (respect prior protections)
  if ((property as any).isDeleted || (property as any).deletedAt) {
    return { uniqueIpCount24h, action: "none" as const };
  }

  // Identify developer id best-effort
  const developerId =
    (property as any).createdBy?.toString?.() ||
    (property as any).userId?.toString?.() ||
    (property as any).ownerId?.toString?.() ||
    (property as any).developerId?.toString?.() ||
    null;

  // Phase 3.5: compute risk
  const risk = await computePropertyRisk(propertyId, developerId);

  // Existing threshold logic
  if (uniqueIpCount24h >= 5) {
    // Auto: soft delete + flag
    (property as any).isFlagged = true;
    (property as any).flagReason = "AUTO: 5+ unique IP reports in 24h";
    (property as any).flaggedAt = new Date();

    // Soft delete fields (existing architecture)
    (property as any).isDeleted = true;
    (property as any).deletedAt = new Date();
    (property as any).deletedReason = "AUTO_FRAUD_THRESHOLD";

    await property.save();
    return { uniqueIpCount24h, risk, action: "auto_soft_delete_flag" as const };
  }

  if (uniqueIpCount24h >= 3) {
    // Auto: mark under review (flag)
    (property as any).isFlagged = true;
    (property as any).flagReason = "AUTO: 3+ unique IP reports in 24h";
    (property as any).flaggedAt = new Date();

    await property.save();
    return { uniqueIpCount24h, risk, action: "auto_flag_review" as const };
  }

  // Phase 3.5: high-risk flag even if IP threshold not met
  if (risk.score >= 8) {
    (property as any).isFlagged = true;
    (property as any).flagReason = "AUTO: RiskScore ≥ 8 (Critical)";
    (property as any).flaggedAt = new Date();
    await property.save();
    return { uniqueIpCount24h, risk, action: "auto_flag_risk_critical" as const };
  }

  return { uniqueIpCount24h, risk, action: "none" as const };
}

// lib/automation/enrollRecipient.ts
// ═══════════════════════════════════════════════════════════════
// AUTOMATION ENROLLMENT HELPER — HIGHRISE.PK
// SERVER ONLY — never import in client components
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   Called from trigger points (verify.ts, leads/index.ts) to
//   enroll a recipient into all matching active automation
//   sequences for a given trigger type.
//
// DESIGN:
//   - Non-blocking: caller fires and forgets (no await needed)
//   - Never throws: all errors caught and logged to console
//   - Idempotent: skipIfAlreadyActive prevents duplicate enrollments
//   - Lightweight: only fetches active sequences for trigger type
//   - Daily cap: respects maxEnrollmentsPerDay per sequence
//
// USAGE:
//   // In verify.ts (subscriber_joined):
//   enrollRecipient('subscriber_joined', {
//     recipientId:   subscriber._id.toString(),
//     recipientType: 'subscriber',
//     email:         subscriber.email,
//     name:          subscriber.name || '',
//   }).catch(() => {});  // fire and forget
//
//   // In leads/index.ts (lead_created):
//   enrollRecipient('lead_created', {
//     recipientId:   lead._id.toString(),
//     recipientType: 'lead',
//     email:         lead.email,
//     name:          lead.name,
//     city:          lead.projectSnapshot?.city || lead.propertySnapshot?.city,
//     leadStatus:    lead.status,
//     leadSource:    lead.source,
//     leadType:      lead.leadType,
//   }).catch(() => {});  // fire and forget
// ═══════════════════════════════════════════════════════════════

import dbConnect              from '@/lib/db';
import AutomationSequence,
  { AutomationTrigger }       from '@/models/AutomationSequence';
import AutomationEnrollment   from '@/models/AutomationEnrollment';
import mongoose               from 'mongoose';

// ─── Recipient payload shape ──────────────────────────────────

export interface EnrollRecipientPayload {
  recipientId:    string;
  recipientType:  'subscriber' | 'lead';
  email:          string;
  name:           string;

  // Lead-specific (used for trigger filter matching)
  city?:          string;
  leadStatus?:    string;
  leadSource?:    string;
  leadType?:      string;

  // For lead_status_changed trigger
  previousStatus?: string;
  newStatus?:      string;
}

// ─── Main function ────────────────────────────────────────────

/**
 * Enroll a recipient into all matching active automation
 * sequences for the given trigger.
 *
 * Designed to be called fire-and-forget:
 *   enrollRecipient('lead_created', payload).catch(() => {});
 *
 * Never throws — all errors are silently caught.
 */
export async function enrollRecipient(
  trigger:  AutomationTrigger,
  payload:  EnrollRecipientPayload
): Promise<void> {
  try {
    await dbConnect();

    // ── Step 1: Find all active sequences for this trigger ────
    const sequences: any[] = await AutomationSequence.find({
      status:  'active',
      trigger,
    })
      .select(
        '_id name skipIfAlreadyActive maxEnrollmentsPerDay ' +
        'recipientType triggerFilters steps'
      )
      .lean();

    if (!sequences || sequences.length === 0) return;

    const now = new Date();

    for (const sequence of sequences) {
      try {
        // ── Step 2: Recipient type filter ─────────────────────
        // 'subscribers' sequences only enroll subscribers
        // 'leads' sequences only enroll leads
        // 'both' enroll either
        const seqRecipientType = sequence.recipientType || 'subscribers';

        if (
          seqRecipientType !== 'both' &&
          seqRecipientType !== payload.recipientType + 's'
        ) {
          continue;
        }

        // ── Step 3: Trigger filter matching ───────────────────
        const filters = sequence.triggerFilters || {};

        // City filter (leads only)
        if (
          filters.leadCities?.length > 0 &&
          payload.city &&
          !filters.leadCities.includes(payload.city)
        ) {
          continue;
        }

        // Status filter (leads only)
        if (
          filters.leadStatuses?.length > 0 &&
          payload.leadStatus &&
          !filters.leadStatuses.includes(payload.leadStatus)
        ) {
          continue;
        }

        // Source filter (leads only)
        if (
          filters.leadSources?.length > 0 &&
          payload.leadSource &&
          !filters.leadSources.includes(payload.leadSource)
        ) {
          continue;
        }

        // Lead type filter
        if (
          filters.leadTypes?.length > 0 &&
          payload.leadType &&
          !filters.leadTypes.includes(payload.leadType)
        ) {
          continue;
        }

        // Status change filter (lead_status_changed trigger)
        if (trigger === 'lead_status_changed') {
          if (
            filters.fromStatus &&
            payload.previousStatus !== filters.fromStatus
          ) {
            continue;
          }
          if (
            filters.toStatus &&
            payload.newStatus !== filters.toStatus
          ) {
            continue;
          }
        }

        // Subscriber source filter
        if (
          trigger === 'subscriber_joined' &&
          filters.subscriberSources?.length > 0 &&
          payload.leadSource &&
          !filters.subscriberSources.includes(payload.leadSource)
        ) {
          continue;
        }

        // ── Step 4: Skip if already active (if configured) ────
        if (sequence.skipIfAlreadyActive) {
          const existing = await AutomationEnrollment.findOne({
            sequenceId:    sequence._id,
            recipientId:   payload.recipientId,
            status:        'active',
          })
            .select('_id')
            .lean();

          if (existing) continue;
        }

        // ── Step 5: Daily enrollment cap check ────────────────
        if (sequence.maxEnrollmentsPerDay > 0) {
          const startOfDay = new Date(now);
          startOfDay.setHours(0, 0, 0, 0);

          const todayCount = await AutomationEnrollment.countDocuments({
            sequenceId: sequence._id,
            enrolledAt: { $gte: startOfDay },
          });

          if (todayCount >= sequence.maxEnrollmentsPerDay) {
            console.warn(
              `[Automation] Daily cap reached for sequence "${sequence.name}" ` +
              `(${todayCount}/${sequence.maxEnrollmentsPerDay})`
            );
            continue;
          }
        }

        // ── Step 6: Skip sequences with no steps ──────────────
        if (!sequence.steps || sequence.steps.length === 0) continue;

        // ── Step 7: Calculate nextSendAt for step 1 ───────────
        const step1 = sequence.steps[0];
        const delayMs = (step1.delayDays || 0) * 24 * 60 * 60 * 1000;
        const nextSendAt = new Date(now.getTime() + delayMs);

        // ── Step 8: Create enrollment ─────────────────────────
        await AutomationEnrollment.create({
          sequenceId:    new mongoose.Types.ObjectId(sequence._id),
          recipientId:   payload.recipientId,
          recipientType: payload.recipientType,
          email:         payload.email.toLowerCase().trim(),
          name:          payload.name || '',
          currentStep:   1,
          status:        'active',
          nextSendAt,
          enrolledAt:    now,
          stepsCompleted: [],
          failedSteps:   [],
        });

        // ── Step 9: Increment sequence stats ──────────────────
        await AutomationSequence.updateOne(
          { _id: sequence._id },
          {
            $inc: {
              'stats.totalEnrolled': 1,
              'stats.activeCount':   1,
            },
          }
        );

      } catch (seqErr) {
        // Per-sequence error — log and continue to next sequence
        console.error(
          `[Automation] Failed to enroll in sequence "${sequence?.name}":`,
          seqErr instanceof Error ? seqErr.message : seqErr
        );
      }
    }
  } catch (err) {
    // Top-level error — log and return silently
    console.error(
      '[Automation] enrollRecipient failed:',
      err instanceof Error ? err.message : err
    );
  }
}

/**
 * lib/cache/projectAggregations.ts
 *
 * Cached MongoDB aggregations for the Projects listing page.
 * Uses Upstash Redis when available — falls back to direct DB
 * queries if Redis is unreachable (fail-open, never block SSR).
 *
 * getCityCounts()             → TTL: 5 min
 * getProjectCategoryCounts()  → TTL: 2 min (project category)
 * getProjectNatureCounts()    → TTL: 2 min (residential/commercial/mixed)
 *
 * Resilience: Every redis.get() / redis.setex() call is wrapped
 * in try/catch. Redis outages log a warning and proceed with the
 * direct DB path. Never throws to the SSR layer.
 */

import { Redis } from '@upstash/redis';

import dbConnect from '@/lib/dbConnect';
import Project   from '@/models/Projects';

import {
  PROJECT_CATEGORY_LABELS,
  PROJECT_NATURE_LABELS,
  normalizeProjectCategory,
  normalizeProjectNature,
  type CityCount,
  type ProjectCategoryCount,
  type ProjectNatureCount,
  type HotspotArea,
} from '@/types/projects';

// ─── SAFE REDIS SINGLETON ─────────────────────────────────
// Redis.fromEnv() can throw if env vars are missing at module
// load time. Wrap init so aggregation module never fails to load.
let redis: Redis | null = null;
try {
  redis = Redis.fromEnv();
} catch {
  redis = null;
}

/** Safe Redis GET — returns null on any failure (unreachable, timeout, etc). */
async function safeCacheGet<T>(key: string): Promise<T | null> {
  if (!redis) return null;
  try {
    return await redis.get<T>(key);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(
      `[cache] Redis GET failed for "${key}" — falling back to DB:`,
      err instanceof Error ? err.message : 'unknown'
    );
    return null;
  }
}

/** Safe Redis SETEX — silent no-op on failure (aggregation still returns). */
async function safeCacheSet<T>(
  key: string, ttlSecs: number, value: T
): Promise<void> {
  if (!redis) return;
  try {
    await redis.setex(key, ttlSecs, value);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(
      `[cache] Redis SETEX failed for "${key}" — result not cached:`,
      err instanceof Error ? err.message : 'unknown'
    );
  }
}

const VERIFIED_BASE = {
  isDeleted:               { $ne: true },
  status:                  'verified',
  verificationStatus:      'verified',
  developerApprovalStatus: 'approved',
} as const;

// ─── CITY COUNTS ──────────────────────────────────────────────────────────────

/**
 * Returns aggregated city-level project counts with verified stats.
 *
 * Used by:
 *   - HeroSection city filter dropdown
 *   - Section 8 (BrowseByCity) with images + verified badges
 *
 * Fields returned per city:
 *   - city           city name (from DB)
 *   - count          total verified projects
 *   - verifiedCount  projects with isVerified === true
 *   - verifiedPct    percentage 0–100
 *   - image          null (populated client-side from CITY_CONFIG)
 *   - province       null (populated client-side from CITY_CONFIG)
 *
 * Cached 5 min. Fail-open on Redis outage.
 * Cache key: v3 (bumped from v2 due to new fields).
 */
export async function getCityCounts(): Promise<CityCount[]> {
  const CACHE_KEY = 'projects:city_counts:v3';
  const TTL_SECS  = 300;

  const cached = await safeCacheGet<CityCount[]>(CACHE_KEY);
  if (cached && Array.isArray(cached) && cached.length > 0) return cached;

  await dbConnect();

  const raw = await Project.aggregate([
    { $match: VERIFIED_BASE },
    {
      $group: {
        _id: '$city',
        count: { $sum: 1 },
        verifiedCount: {
          $sum: {
            $cond: [{ $eq: ['$isVerified', true] }, 1, 0],
          },
        },
      },
    },
    { $sort:  { count: -1 } },
    { $limit: 20 },  // Up to 20 cities — component picks top 8 + fills fixed list
  ]).option({ maxTimeMS: 3000 }) as Array<{
    _id:           string;
    count:         number;
    verifiedCount: number;
  }>;

  const result: CityCount[] = raw.map(c => {
    const count         = c.count ?? 0;
    const verifiedCount = c.verifiedCount ?? 0;
    const verifiedPct   = count > 0
      ? Math.round((verifiedCount / count) * 100)
      : 0;

    return {
      city:  c._id ?? '',
      count,
      image: null,        // populated client-side via CITY_CONFIG map
      verifiedCount,
      verifiedPct,
      province: null,     // populated client-side via CITY_CONFIG map
    };
  });

  await safeCacheSet(CACHE_KEY, TTL_SECS, result);
  return result;
}

// ─── PROJECT CATEGORY COUNTS ──────────────────────────────────────────────────

/**
 * Groups by projectCategory field (High-Rise, Housing Society, etc.)
 * Normalizes DB values to canonical ProjectCategory enum.
 * Filters out unknown/legacy values.
 */
export async function getProjectCategoryCounts(
  baseMatch: Record<string, unknown>
): Promise<ProjectCategoryCount[]> {
  const cityValue = baseMatch.city as
    | { $regex?: { source?: string } }
    | string
    | undefined;

  const cityKey =
    typeof cityValue === 'string'
      ? cityValue.toLowerCase()
      : (cityValue?.$regex?.source ?? 'all');

  const CACHE_KEY = `projects:proj_cat:v2:${cityKey}`;
  const TTL_SECS  = 120;

  const cached = await safeCacheGet<ProjectCategoryCount[]>(CACHE_KEY);
  if (cached && Array.isArray(cached) && cached.length > 0) return cached;

  await dbConnect();

  const raw = await Project.aggregate([
    { $match: baseMatch },
    { $group: { _id: '$projectCategory', count: { $sum: 1 } } },
    { $sort:  { count: -1 } },
  ]).option({ maxTimeMS: 3000 }) as Array<{ _id: string; count: number }>;

  // Normalize + aggregate variations (e.g. "highrise" + "high_rise" → same key)
  const normalized = new Map<string, number>();
  raw.forEach(r => {
    const cat = normalizeProjectCategory(r._id ?? '');
    if (cat) {
      normalized.set(cat, (normalized.get(cat) ?? 0) + r.count);
    }
  });

  const result: ProjectCategoryCount[] = Array.from(normalized.entries())
    .map(([category, count]) => ({
      category: category as ProjectCategoryCount['category'],
      label:    PROJECT_CATEGORY_LABELS[category as ProjectCategoryCount['category']],
      count,
    }))
    .sort((a, b) => b.count - a.count);

  await safeCacheSet(CACHE_KEY, TTL_SECS, result);
  return result;
}

