// ─── HOTSPOT AREAS ────────────────────────────────────────────────────────────

/**
 * Top locality-level hotspot areas within Pakistan or a specific city.
 *
 * Groups verified projects by { city, area } combination.
 * Returns top 8 areas sorted by project count DESC.
 *
 * When `city` is provided → hotspots ONLY in that city
 * When `city` is undefined → hotspots ACROSS all cities
 *
 * Each hotspot includes:
 *   - area           locality/neighbourhood name (e.g. "DHA Phase 5")
 *   - city           parent city (e.g. "Lahore")
 *   - projectCount   total verified projects in this area
 *   - verifiedCount  projects with isVerified === true
 *   - verifiedPct    percentage of verified (0–100)
 *
 * Cached per-city key. TTL 5 min. Fail-open on Redis outage.
 */
export async function getHotspotAreas(
  city?: string,
): Promise<HotspotArea[]> {
  const cityKey   = city ? city.toLowerCase().trim() : 'all';
  const CACHE_KEY = `projects:hotspots:v1:${cityKey}`;
  const TTL_SECS  = 300;

  // ── Cache first ──────────────────────────────────────────
  const cached = await safeCacheGet<HotspotArea[]>(CACHE_KEY);
  if (cached && Array.isArray(cached) && cached.length > 0) return cached;

  await dbConnect();

  // ── Build match stage ────────────────────────────────────
  const matchStage: Record<string, unknown> = { ...VERIFIED_BASE };
  if (city) {
    // Case-insensitive exact city match
    matchStage.city = { $regex: new RegExp(`^${city.trim()}$`, 'i') };
  }

  // ── Aggregation pipeline ─────────────────────────────────
  // Groups by { city, area } — both must be non-empty to count
  const raw = await Project.aggregate([
    { $match: matchStage },
    {
      $match: {
        area: { $exists: true, $nin: [null, ''] },
        city: { $exists: true, $nin: [null, ''] },
      },
    },
    {
      $group: {
        _id: { city: '$city', area: '$area' },
        projectCount:  { $sum: 1 },
        verifiedCount: {
          $sum: {
            $cond: [{ $eq: ['$isVerified', true] }, 1, 0],
          },
        },
      },
    },
    { $sort:  { projectCount: -1 } },
    { $limit: 8 },
  ]).option({ maxTimeMS: 3000 }) as Array<{
    _id: { city: string; area: string };
    projectCount:  number;
    verifiedCount: number;
  }>;

  // ── Map to HotspotArea shape ─────────────────────────────
  const result: HotspotArea[] = raw.map(r => {
    const projectCount  = r.projectCount ?? 0;
    const verifiedCount = r.verifiedCount ?? 0;
    const verifiedPct   = projectCount > 0
      ? Math.round((verifiedCount / projectCount) * 100)
      : 0;

    return {
      area:  r._id?.area ?? '',
      city:  r._id?.city ?? '',
      projectCount,
      verifiedCount,
      verifiedPct,
    };
  });

  // ── Cache & return ───────────────────────────────────────
  await safeCacheSet(CACHE_KEY, TTL_SECS, result);
  return result;
}

// lib/cloudinary.ts
// 🔒 ENTERPRISE CLOUDINARY SYSTEM — Highrise.pk
// Signed server-side uploads only. No direct browser uploads.
// Fixes: console.error removed, catch unknown, as any removed,
//        userId removed from Cloudinary tags (PII),
//        folder mapping added for /api/upload route

import { v2 as cloudinary } from 'cloudinary';
import type { UploadApiOptions, UploadApiResponse } from 'cloudinary';
import crypto from 'crypto';

// ═══════════════════════════════════════════════════════════════
// 🔐 CONFIGURATION
// ═══════════════════════════════════════════════════════════════

const CLOUD_NAME  = process.env.CLOUDINARY_CLOUD_NAME  ?? '';
const API_KEY     = process.env.CLOUDINARY_API_KEY     ?? '';
const API_SECRET  = process.env.CLOUDINARY_API_SECRET  ?? '';

cloudinary.config({
  cloud_name: CLOUD_NAME,
  api_key:    API_KEY,
  api_secret: API_SECRET,
  secure:     true,
});

export default cloudinary;

// ═══════════════════════════════════════════════════════════════
// 🔐 SECURITY CONSTANTS
// ═══════════════════════════════════════════════════════════════

export const FILE_SIZE_LIMITS = {
  image:    5   * 1024 * 1024,
  document: 10  * 1024 * 1024,
  video:    100 * 1024 * 1024,
  avatar:   2   * 1024 * 1024,
  kyc:      5   * 1024 * 1024,
} as const;

export const IMAGE_DIMENSION_LIMITS = {
  maxWidth:  4096,
  maxHeight: 4096,
  minWidth:  100,
  minHeight: 100,
} as const;

// ✅ No SVG — XSS risk (SVG can contain JavaScript)
export const ALLOWED_MIME_TYPES = {
  image:    ['image/jpeg', 'image/png', 'image/webp', 'image/gif'] as const,
  document: ['application/pdf'] as const,
  video:    ['video/mp4', 'video/webm'] as const,
  avatar:   ['image/jpeg', 'image/png', 'image/webp'] as const,
  kyc:      ['image/jpeg', 'image/png', 'application/pdf'] as const,
} as const;

export const ALLOWED_EXTENSIONS = {
  image:    ['.jpg', '.jpeg', '.png', '.webp', '.gif'] as const,
  document: ['.pdf'] as const,
  video:    ['.mp4', '.webm'] as const,
  avatar:   ['.jpg', '.jpeg', '.png', '.webp'] as const,
  kyc:      ['.jpg', '.jpeg', '.png', '.pdf'] as const,
} as const;

// ✅ Internal Cloudinary folder paths
