type GeminiResponse = {
  candidates?: Array<{
    content?: { parts?: Array<{ text?: string }> };
  }>;
};

export async function generateAIResponse(
  userMessage: string,
  chatHistory: { role: string; content: string }[],
  agentName: string,
  _agentGender: 'male' | 'female',
): Promise<{ response: string; tokensUsed: number }> {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) throw new Error('GEMINI_API_KEY is not configured');

  const model = process.env.GEMINI_MODEL || 'gemini-3.5-flash';
  if (!/^[a-zA-Z0-9._-]+$/.test(model)) throw new Error('Invalid GEMINI_MODEL');

  const systemInstruction = SYSTEM_PROMPT.replace(/{AGENT_NAME}/g, agentName);
  const contents = [
    ...chatHistory.slice(-8).map((msg) => ({
      role: msg.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: String(msg.content).slice(0, 2000) }],
    })),
    { role: 'user', parts: [{ text: userMessage.slice(0, 2000) }] },
  ];

  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': apiKey,
      },
      body: JSON.stringify({
        system_instruction: { parts: [{ text: systemInstruction }] },
        contents,
        generationConfig: { maxOutputTokens: 1024 },
      }),
      signal: AbortSignal.timeout(12_000),
    },
  );

  if (!response.ok) throw new Error(`Gemini request failed (${response.status})`);

  const data = (await response.json()) as GeminiResponse;
  const text = data.candidates?.[0]?.content?.parts
    ?.map((part) => part.text || '')
    .join('')
    .trim();

  if (!text) throw new Error('Gemini returned an empty response');

  return {
    response: text,
    tokensUsed: Math.ceil((userMessage.length + text.length) / 4),
  };
}

export function detectLanguage(message: string): 'urdu' | 'english' | 'roman-urdu' {
  if (/[\u0600-\u06FF]/.test(message)) return 'urdu';
  if (/^[a-zA-Z\s.,!?\'"-]+$/.test(message)) return 'english';
  return 'roman-urdu';
}

// lib/geocode.ts

export interface Coordinates {
  lat: number;
  lng: number;
}

export interface GeocodeResult {
  coordinates: Coordinates | null;
  formattedAddress: string | null;
  error?: string;
}

/**
 * Convert address to coordinates using Google Geocoding API
 */
export async function geocodeAddress(address: string): Promise<GeocodeResult> {
  const apiKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY;

  if (!apiKey) {
    console.error('Google Maps API key not found');
    return {
      coordinates: null,
      formattedAddress: null,
      error: 'API key not configured',
    };
  }

  try {
    const encodedAddress = encodeURIComponent(address);
    const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodedAddress}&key=${apiKey}&region=pk`;

    const response = await fetch(url);
    const data = await response.json();

    if (data.status === 'OK' && data.results.length > 0) {
      const result = data.results[0];
      return {
        coordinates: {
          lat: result.geometry.location.lat,
          lng: result.geometry.location.lng,
        },
        formattedAddress: result.formatted_address,
      };
    } else if (data.status === 'ZERO_RESULTS') {
      return {
        coordinates: null,
        formattedAddress: null,
        error: 'Address not found',
      };
    } else {
      console.error('Geocoding error:', data.status, data.error_message);
      return {
        coordinates: null,
        formattedAddress: null,
        error: data.error_message || data.status,
      };
    }
  } catch (error: any) {
    console.error('Geocoding request failed:', error);
    return {
      coordinates: null,
      formattedAddress: null,
      error: error.message,
    };
  }
}

/**
 * Build full address string from property fields
 */
export function buildAddressString(
  streetNumber?: string,
  block?: string,
  phase?: string,
  society?: string,
  city?: string
): string {
  const parts = [];

  if (streetNumber) parts.push(streetNumber);
  if (block) parts.push(block);
  if (phase) parts.push(phase);
  if (society) parts.push(society);
  if (city) parts.push(city);

  // Always add Pakistan for better accuracy
  parts.push('Pakistan');

  return parts.join(', ');
}

