// lib/riskCache.ts

type CacheEntry<T> = {
  value: T;
  expiresAt: number;
};

const riskCache = new Map<string, CacheEntry<any>>();
const heatCache = new Map<string, CacheEntry<any>>();

function now() {
  return Date.now();
}

function isExpired(entry?: CacheEntry<any>) {
  if (!entry) return true;
  return now() > entry.expiresAt;
}

function safeGet<T>(map: Map<string, CacheEntry<T>>, key: string): T | null {
  const entry = map.get(key);
  if (!entry || isExpired(entry)) {
    if (entry) map.delete(key);
    return null;
  }
  return entry.value as T;
}

function safeSet<T>(map: Map<string, CacheEntry<T>>, key: string, value: T, ttlMs: number) {
  map.set(key, { value, expiresAt: now() + ttlMs });
}

// ✅ Risk cache helpers
export function getCachedRisk<T>(key: string): T | null {
  return safeGet<T>(riskCache, key);
}

export function setCachedRisk<T>(key: string, value: T, ttlMs = 10 * 60 * 1000) {
  safeSet<T>(riskCache, key, value, ttlMs);
}

// ✅ Developer heat cache helpers
export function getCachedHeat<T>(key: string): T | null {
  return safeGet<T>(heatCache, key);
}

export function setCachedHeat<T>(key: string, value: T, ttlMs = 15 * 60 * 1000) {
  safeSet<T>(heatCache, key, value, ttlMs);
}

// Optional: manual clear (useful after admin actions)
export function clearRiskCache() {
  riskCache.clear();
}

export function clearHeatCache() {
  heatCache.clear();
}

// lib/riskEngine.ts
import mongoose from "mongoose";
import Property from "@/models/Property";
import Report from "@/models/Report";

/**
 * Risk score is computed (not stored) to keep schema safe + avoid migrations.
 * Score components (rough weights):
 * - Unique IPs (24h) -> strong signal
 * - Total reports -> moderate
 * - Severity weighting -> strong
 * - Developer history -> moderate
 * - Time decay -> reduces old report impact
 */

export type RiskLevel = "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";

export type RiskBreakdown = {
  uniqueIpCount24h: number;
  totalReports: number;
  severityWeighted: number;
  developerHistoryFactor: number;
  timeDecayWeighted: number;
};

export type RiskResult = {
  score: number;
  level: RiskLevel;
  breakdown: RiskBreakdown;
};

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

function toObjectId(id: string) {
  if (!mongoose.Types.ObjectId.isValid(id)) return null;
  return new mongoose.Types.ObjectId(id);
}

// Severity weights — adjust as your Report Reason enum grows
export function severityWeight(reason: string) {
  const r = String(reason || "").toLowerCase();
  if (r.includes("scam") || r.includes("fraud") || r.includes("fake")) return 3.0;
  if (r.includes("agent") || r.includes("decept") || r.includes("imperson")) return 2.2;
  if (r.includes("spam") || r.includes("duplicate")) return 1.2;
  if (r.includes("other")) return 1.0;
  return 1.0;
}

// Exponential decay by age (half-life ~ 7 days)
export function timeDecayFactor(createdAt: Date, halfLifeDays = 7) {
  const ageMs = Date.now() - new Date(createdAt).getTime();
  const ageDays = ageMs / (1000 * 60 * 60 * 24);
  const lambda = Math.log(2) / halfLifeDays;
  const factor = Math.exp(-lambda * ageDays);
  return clamp(factor, 0.05, 1);
}

export function riskLevelFromScore(score: number): RiskLevel {
  if (score >= 8) return "CRITICAL";
  if (score >= 5) return "HIGH";
  if (score >= 3) return "MEDIUM";
  return "LOW";
}

export async function getUniqueIpCount24h(propertyId: string) {
  const pid = toObjectId(propertyId);
  if (!pid) return 0;

  const since = new Date(Date.now() - 24 * 60 * 60 * 1000);

  const rows = await Report.aggregate([
    { $match: { propertyId: pid, createdAt: { $gte: since } } },
    { $group: { _id: "$ipHash" } },
    { $count: "count" },
  ]);

  return rows?.[0]?.count ?? 0;
}

export async function getReportStats(propertyId: string) {
  const pid = toObjectId(propertyId);
  if (!pid) {
    return {
      totalReports: 0,
      severityWeighted: 0,
      timeDecayWeighted: 0,
    };
  }

  // Pull only needed fields for scoring
  const reports = await Report.find({ propertyId: pid })
    .select("reason createdAt")
    .lean();

  const totalReports = reports.length;

  let severityWeighted = 0;
  let timeDecayWeighted = 0;

  for (const rep of reports) {
    const sev = severityWeight((rep as any).reason);
    severityWeighted += sev;
    timeDecayWeighted += sev * timeDecayFactor((rep as any).createdAt);
  }

  return { totalReports, severityWeighted, timeDecayWeighted };
}

/**
 * Developer history factor:
 * - counts flagged/hidden properties in last 30 days (strong)
 * - counts auto-hidden/soft-deleted in last 7 days (future)
 *
 * NOTE: Property schema may store developer as `createdBy` or `userId` or `ownerId`.
 * We try best-effort keys without breaking if your schema differs.
 */
export async function getDeveloperHistoryFactor(developerId: string | null | undefined) {
  const did = developerId ? toObjectId(developerId) : null;
  if (!did) return 0;

  const since30 = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

  const match: any = {
    createdAt: { $gte: since30 },
    $or: [{ createdBy: did }, { userId: did }, { ownerId: did }, { developerId: did }],
  };

  // Flagged/hidden are moderation indicators (soft-delete already exists separately)
  const flaggedHiddenCount = await Property.countDocuments({
    ...match,
    $or: [
      ...(match.$or || []),
    ],
    $and: [
      {
        $or: [
          { isFlagged: true },
          { status: "hidden" }, // if you have status
          { isHidden: true },   // if you have isHidden
        ],
      },
    ],
  });

  // Normalize into small factor (0..3)
  // 0 -> 0, 1 -> 0.7, 2 -> 1.2, 3 -> 1.6, 4+ -> 2.2
  if (flaggedHiddenCount <= 0) return 0;
  if (flaggedHiddenCount === 1) return 0.7;
  if (flaggedHiddenCount === 2) return 1.2;
  if (flaggedHiddenCount === 3) return 1.6;
  return 2.2;
}

export async function computePropertyRisk(propertyId: string, developerId?: string | null): Promise<RiskResult> {
  const [uniqueIpCount24h, reportStats, developerHistoryFactor] = await Promise.all([
    getUniqueIpCount24h(propertyId),
    getReportStats(propertyId),
    getDeveloperHistoryFactor(developerId),
  ]);

  // Core scoring
  // IPs (24h) -> 0..6
  const ipScore = clamp(uniqueIpCount24h * 1.1, 0, 6);

  // Total reports -> 0..3
  const reportScore = clamp(reportStats.totalReports * 0.35, 0, 3);

  // Severity/time decay -> 0..6 (but decays old reports)
  const severityScore = clamp(reportStats.timeDecayWeighted * 0.9, 0, 6);

  // Developer history -> 0..2.5
  const devScore = clamp(developerHistoryFactor, 0, 2.5);

  // Combined
  const raw = ipScore + reportScore + severityScore + devScore;

  // Keep score compact
  const score = Math.round(raw * 10) / 10;
  const level = riskLevelFromScore(score);

  return {
    score,
    level,
    breakdown: {
      uniqueIpCount24h,
      totalReports: reportStats.totalReports,
      severityWeighted: Math.round(reportStats.severityWeighted * 10) / 10,
      developerHistoryFactor: Math.round(developerHistoryFactor * 10) / 10,
      timeDecayWeighted: Math.round(reportStats.timeDecayWeighted * 10) / 10,
    },
  };
}

// lib/seo/property-jsonld.ts

interface PropertyData {
  _id: string;
  title: string;
  description?: string;
  price: number;
  currency?: string;
  listingType?: 'full_payment' | 'rent' | 'installment';
  propertyType?: string;
  bedrooms?: number;
  bathrooms?: number;
  area?: number;
  areaUnit?: string;
  city?: string;
  location?: string;
  society?: string;
  images?: string[];
  createdAt?: string;
  isVerified?: boolean;
  agent?: {
    name: string;
    phone?: string;
    email?: string;
  };
}

export function generatePropertyJsonLd(property: PropertyData): string {
  const baseUrl = process.env.NEXT_PUBLIC_SITE_URL || 'https://highrise.pk';
  const propertyUrl = `${baseUrl}/property/${property._id}`;
  
  const imageUrls = property.images?.filter(Boolean).slice(0, 8) || [];
  
  const listingType = property.listingType === 'rent' ? 'https://schema.org/Rent' : 'https://schema.org/Sale';
  
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: property.title,
    description: property.description || `Property for ${property.listingType === 'rent' ? 'rent' : 'sale'} in ${property.city}`,
    image: imageUrls,
    url: propertyUrl,
    brand: {
      '@type': 'Brand',
      name: 'Highrise.pk',
    },
    offers: {
      '@type': 'Offer',
      price: property.price,
      priceCurrency: property.currency || 'PKR',
      availability: 'https://schema.org/InStock',
      url: propertyUrl,
      validFrom: property.createdAt || new Date().toISOString(),
    },
    ...(property.bedrooms && {
      numberOfRooms: property.bedrooms,
    }),
    ...(property.bathrooms && {
      numberOfBathroomsTotal: property.bathrooms,
    }),
    ...(property.area && {
      floorSize: {
        '@type': 'QuantitativeValue',
        value: property.area,
        unitCode: property.areaUnit === 'Sq.Ft.' ? 'FTK' : 'MTK',
        unitText: property.areaUnit || 'Square Feet',
      },
    }),
    ...(property.city && {
      address: {
        '@type': 'PostalAddress',
        addressLocality: property.city,
        addressRegion: property.location || property.city,
        addressCountry: 'PK',
      },
    }),
    ...(property.agent && {
      seller: {
        '@type': 'Person',
        name: property.agent.name,
        telephone: property.agent.phone,
        email: property.agent.email,
      },
    }),
    additionalProperty: [
      {
        '@type': 'PropertyValue',
        name: 'Property Type',
        value: property.propertyType || 'Residential',
      },
      {
        '@type': 'PropertyValue',
        name: 'Listing Type',
        value: property.listingType === 'rent' ? 'Rent' : 'Sale',
      },
      ...(property.isVerified
        ? [
            {
              '@type': 'PropertyValue',
              name: 'Verified',
              value: 'Yes',
            },
          ]
        : []),
    ],
  };

  return JSON.stringify(jsonLd);
}

export function generateRealEstateAgentJsonLd(agentData: {
  name: string;
  phone?: string;
  email?: string;
  address?: string;
  logo?: string;
}): string {
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'RealEstateAgent',
    name: agentData.name,
    ...(agentData.phone && { telephone: agentData.phone }),
    ...(agentData.email && { email: agentData.email }),
    ...(agentData.address && { address: agentData.address }),
    ...(agentData.logo && { logo: agentData.logo }),
    areaServed: {
      '@type': 'Country',
      name: 'Pakistan',
    },
  };

  return JSON.stringify(jsonLd);
}

