      label:    'NOC Approved',
      emoji:    '🏛️',
      color:    'text-blue-700',
      verified: true,
    });
  }

  if (project.isTrustedBuilder) {
    badges.push({
      id:       'trusted_builder',
      label:    'Trusted Builder',
      emoji:    '🏆',
      color:    'text-[#029bba]',
