  wonDate?: Date;
  lostReason?: string;
  lostDate?: Date;

  // ===================================
  // 🆕 BUDGET INFO
  // ===================================
  budget?: IBudgetInfo;

  // ===================================
  // 🆕 COMMUNICATION LOG
  // ===================================
  communications?: ICommunication[];

  // ===================================
  // TIMELINE & AUDIT TRAIL
  // ===================================
  timeline: ITimelineEntry[];

  // ===================================
  // ADMIN MANAGEMENT
  // ===================================
  notes?: string;
  tags?: string[];
  isArchived: boolean;
  archivedAt?: Date;
  archivedBy?: string;

  // ===================================
  // 🆕 PHASE 2 — EMAIL MARKETING PREFERENCES
