  usedMortgageCalculator?: boolean;
  comparedProperties?: number;
  savedToFavorites?: boolean;

  // ===================================
  // TIMESTAMPS
  // ===================================
  createdAt: Date;
  updatedAt: Date;
}

// ============================================
// SUB-SCHEMAS
// ============================================

const DeveloperSnapshotSchema = new Schema(
  {
    _id: { type: Schema.Types.ObjectId, required: true },
