export type CodeType = "email_verification" | "phone_verification" | "password_reset";

export interface ISignupCode extends Document {
  email: string;
  code: string; // ✅ Hashed, not plaintext
  expiresAt: Date;
  codeType: CodeType;

  // Form Data (encrypted password)
  formData: {
    email?: string;
    fullName?: string;
    cnicName?: string;
    cnic?: string;
    phone?: string;
    country?: string;
    profession?: string;
    accountType?: string;
    org?: any;
    city?: string;
    companyName?: string;
    licenseNumber?: string;
    ntnNumber?: string;
    officeAddress?: string;
    homeAddress?: string;
    /** @deprecated Sprint 3 Batch B — use passwordHash instead */
    passwordEnc?: string;
    /** bcrypt hash stored at send time (Sprint 3 Batch B — GAP-S09 fix) */
    passwordHash?: string;
    [key: string]: any;
  };

  // Verification Status
  isVerified: boolean;
  verifiedAt?: Date;

  // Attempt Tracking
  attempts?: number;
  maxAttempts?: number;
  lastAttemptAt?: Date;

  // Resend Tracking (⚠️ Field name must match API usage)
  resendCount?: number; // ✅ Changed from resentCount to match API
  maxResends?: number;
  lastResentAt?: Date;

  // Security Metadata (⚠️ Field name must match API usage)
  meta?: {
    ip?: string; // ✅ Hashed
    ipHash?: string;
    userAgent?: string;
    location?: string;
    deviceType?: string;
    createdAt?: Date;
    requestId?: string;
    reason?: string;
    attempts?: number; // ✅ Backup counter
    resendCount?: number; // ✅ Backup counter
    lastAttemptAt?: Date;
    lastResentAt?: Date;
    codeAlgo?: string;
    pwAlgo?: string;
    [key: string]: any;
  };

  // Timestamps
  createdAt: Date;
  updatedAt: Date;

  // Instance Methods
  isExpired(): boolean;
  canAttempt(): boolean;
  canResend(): boolean;
  getRemainingAttempts(): number;
  getRemainingResends(): number;
  getExpirySeconds(): number;
  verifyCode(code: string): boolean;
}

// ═══════════════════════════════════════════════════════════════
// 🔐 SECURITY HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════

/**
 * ✅ Hash IP address for privacy
 */
function hashIp(ip: string): string {
  return hashSecurityIdentifier(ip);
}

/**
 * ✅ Constant-time string comparison (prevents timing attacks)
 */
function constantTimeCompare(a: string, b: string): boolean {
  return timingSafeEqualDigest(a, b);
}

// ═══════════════════════════════════════════════════════════════
// 🔐 MONGOOSE SCHEMA
// ═══════════════════════════════════════════════════════════════

const SignupCodeSchema = new Schema<ISignupCode>(
  {
    email: {
      type: String,
      required: [true, "Email is required"],
      lowercase: true,
      trim: true,
      index: true,
      validate: {
        validator: function (v: string) {
          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
        },
        message: "Please provide a valid email address",
      },
    },

    code: {
      type: String,
      required: [true, "Verification code is required"],
    },

    expiresAt: {
      type: Date,
      required: [true, "Expiry date is required"],
      index: true,
    },

    codeType: {
      type: String,
      enum: {
        values: ["email_verification", "phone_verification", "password_reset"],
        message: "{VALUE} is not a valid code type",
      },
      default: "email_verification",
      index: true,
    },

    formData: {
      type: Schema.Types.Mixed,
      required: [true, "Form data is required"],
      validate: {
        validator: function (v: unknown) {
          // Reject any formData containing raw `password` field.
          // Correct field is passwordHash (bcrypt) — never raw plaintext.
          if (
            v !== null &&
            typeof v === "object" &&
            "password" in v
          ) {
            return false;
          }
          return true;
        },
        message:
          "Raw password field is not allowed in formData. Use passwordHash (bcrypt).",
      },
    },

    isVerified: {
      type: Boolean,
      default: false,
      index: true,
    },

    verifiedAt: {
      type: Date,
    },

    attempts: {
      type: Number,
      default: 0,
      min: [0, "Attempts cannot be negative"],
    },

    maxAttempts: {
      type: Number,
      default: 5,
      min: [1, "Max attempts must be at least 1"],
    },

    lastAttemptAt: {
      type: Date,
    },

    resendCount: {
      type: Number,
      default: 0,
      min: [0, "Resend count cannot be negative"],
    },

    maxResends: {
      type: Number,
      default: 5,
      min: [1, "Max resends must be at least 1"],
    },

    lastResentAt: {
      type: Date,
    },

    meta: {
      type: Schema.Types.Mixed,
      default: {},
    },
  },
  {
    timestamps: true,
    strict: true,
  }
);

// ═══════════════════════════════════════════════════════════════
// 🔐 INDEXES
// ═══════════════════════════════════════════════════════════════

// Lookup indexes
SignupCodeSchema.index({ email: 1, codeType: 1 });
SignupCodeSchema.index({ email: 1, isVerified: 1 });

// ✅ TTL Index - Auto-delete expired codes
SignupCodeSchema.index({ expiresAt: 1 }, { expireAfterSeconds: 0 });

// Cleanup indexes
SignupCodeSchema.index({ createdAt: 1 });
SignupCodeSchema.index({ isVerified: 1, verifiedAt: 1 });

// Performance indexes
SignupCodeSchema.index({ email: 1, createdAt: -1 });

// ═══════════════════════════════════════════════════════════════
// 🔐 PRE-SAVE MIDDLEWARE
// ═══════════════════════════════════════════════════════════════

SignupCodeSchema.pre("save", function (next) {
  // ✅ Hash IP address in metadata if present
  if (this.meta && this.meta.ip) {
    if (!this.meta.ipHash) {
      this.meta.ipHash = hashIp(this.meta.ip);
    }
    delete this.meta.ip;
  }

  // ✅ Sanitize user agent (limit length)
  if (this.meta && this.meta.userAgent) {
    this.meta.userAgent = String(this.meta.userAgent).slice(0, 500);
  }

  // ✅ Ensure attempts/resendCount are initialized
  if (typeof this.attempts !== "number") this.attempts = 0;
  if (typeof this.resendCount !== "number") this.resendCount = 0;

  next();
});

