              </div>
              <button onClick={() => setShowRejectModal(false)} className="p-1.5 rounded-lg hover:bg-gray-100">
                <X className="w-4 h-4 text-gray-400" />
              </button>
            </div>
            <div className="mb-5">
              <label className="block text-sm font-semibold text-gray-700 mb-1.5">
                Reason <span className="text-gray-400 font-normal">(optional)</span>
              </label>
              <textarea
                value={rejectReason}
                onChange={(e) => setRejectReason(e.target.value)}
                rows={3}
                placeholder="Explain why this agent is being rejected..."
                className="w-full rounded-xl border border-gray-300 focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 text-sm p-3 outline-none resize-none"
              />
            </div>
            <div className="flex gap-3">
              <button
                onClick={() => setShowRejectModal(false)}
                disabled={actionLoading}
                className="flex-1 px-4 py-2.5 rounded-xl border border-gray-300 text-gray-700 font-semibold hover:bg-gray-50 disabled:opacity-50 transition-colors text-sm"
              >
                Cancel
              </button>
              <button
                onClick={() => void handleReject()}
                disabled={actionLoading}
                className="flex-1 px-4 py-2.5 rounded-xl bg-red-600 hover:bg-red-700 text-white font-semibold disabled:opacity-50 transition-colors text-sm flex items-center justify-center gap-2"
              >
                {actionLoading
                  ? <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  : null
                }
                {actionLoading ? 'Rejecting...' : 'Reject Agent'}
              </button>
            </div>
          </div>
        </div>
      )}

      <AdminLayout>
        <div className="space-y-6 max-w-5xl mx-auto">

          {/* Banner */}
          {banner && (
            <div className={`rounded-xl p-4 border-l-4 flex items-center justify-between gap-4 ${
              banner.type === 'success'
                ? 'bg-[#f0fdf4] border-[#10b981] text-[#10b981]'
                : 'bg-[#fef2f2] border-[#ef4444] text-red-700'
            }`}>
              <p className="text-sm font-medium">{banner.message}</p>
              <button onClick={() => setBanner(null)} className="shrink-0 p-1 rounded hover:bg-black/5">
                <X className="w-4 h-4" />
              </button>
            </div>
          )}

          {/* Breadcrumb */}
          <div className="flex items-center gap-2 text-sm text-gray-500">
            <Link href="/admin" className="hover:text-gray-700 transition-colors">Admin</Link>
            <span>/</span>
            <Link href="/admin/agents" className="hover:text-gray-700 transition-colors">Agents</Link>
            <span>/</span>
            <span className="text-gray-900 font-medium truncate max-w-xs">{agent.displayName}</span>
          </div>

          {/* Header card */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
            <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-6">
              <div className="flex items-start gap-4">
                {avatarUrl ? (
                  <div className="relative w-20 h-20 rounded-full overflow-hidden border border-gray-100 shrink-0">
                    <Image src={avatarUrl} alt={agent.displayName} fill sizes="80px" className="object-cover" priority />
                  </div>
                ) : (
                  <div className="w-20 h-20 rounded-full bg-[#029bba] flex items-center justify-center text-3xl font-bold text-white shrink-0">
                    {agent.displayName?.charAt(0)?.toUpperCase() ?? 'A'}
                  </div>
                )}
                <div>
                  <h1 className="text-2xl font-bold text-[#004063]">{agent.displayName}</h1>
                  {agent.tagline && (
                    <p className="text-gray-500 text-sm mt-0.5">{agent.tagline}</p>
                  )}
                  <div className="flex flex-wrap items-center gap-2 mt-2">
                    <StatusBadge status={agent.status} />
                    {agent.isPremium && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-bold bg-amber-50 text-amber-600 border border-amber-200">
                        <Star className="w-3 h-3" />
                        {agent.premiumTier ?? 'Premium'}
                      </span>
                    )}
                    {agent.slug && agent.status === 'approved' && (
                      <Link
                        href={`/agent/${agent.slug}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-1 text-xs text-[#029bba] hover:underline"
                      >
                        <ExternalLink className="w-3 h-3" />
                        View Public Profile
                      </Link>
                    )}
                    {agent.slug && agent.status !== 'approved' && (
                      <span
                        className="inline-flex items-center gap-1 text-xs text-gray-400 italic"
                        title="Public profile becomes available after approval"
                      >
                        <ExternalLink className="w-3 h-3" />
                        Public profile pending approval
                      </span>
                    )}
                  </div>
                </div>
              </div>

              {/* Action buttons */}
              <div className="flex flex-wrap gap-3 shrink-0">
                {/* Approve — available for pending, rejected, suspended */}
                {(agent.status === 'pending' ||
                  agent.status === 'rejected' ||
                  agent.status === 'suspended' ||
                  agent.status === 'draft') && (
                  <button
                    onClick={() => setShowApproveModal(true)}
                    disabled={actionLoading}
                    className="px-5 py-2.5 rounded-xl bg-[#10b981] hover:bg-green-600 text-white font-semibold text-sm disabled:opacity-50 transition-colors"
                  >
                    Approve
                  </button>
                )}

                {/* Reject — only for pending, draft */}
                {(agent.status === 'pending' || agent.status === 'draft') && (
                  <button
                    onClick={() => setShowRejectModal(true)}
                    disabled={actionLoading}
                    className="px-5 py-2.5 rounded-xl bg-red-600 hover:bg-red-700 text-white font-semibold text-sm disabled:opacity-50 transition-colors"
                  >
                    Reject
                  </button>
                )}

                {/* V6.8.0: Suspend — only for approved */}
                {agent.status === 'approved' && (
                  <button
                    onClick={() => setShowSuspendModal(true)}
                    disabled={actionLoading}
                    className="px-5 py-2.5 rounded-xl bg-orange-500 hover:bg-orange-600 text-white font-semibold text-sm disabled:opacity-50 transition-colors"
                  >
                    Suspend
                  </button>
                )}

                {/* V6.8.0: Reinstate — only for suspended */}
                {agent.status === 'suspended' && (
                  <button
                    onClick={() => setShowReinstateModal(true)}
                    disabled={actionLoading}
                    className="px-5 py-2.5 rounded-xl bg-[#029bba] hover:bg-[#027a94] text-white font-semibold text-sm disabled:opacity-50 transition-colors"
                  >
                    Reinstate
                  </button>
                )}

                <Link
                  href="/admin/agents"
                  className="px-5 py-2.5 rounded-xl border border-gray-300 text-gray-700 font-semibold text-sm hover:bg-gray-50 transition-colors inline-flex items-center gap-2"
                >
                  <ArrowLeft className="w-4 h-4" />
                  Back
                </Link>
              </div>
            </div>
          </div>

          {/* V6.8.7: Interactive Verification Toggles */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2">
                <Shield className="w-5 h-5 text-[#029bba]" />
                <h2 className="text-base font-bold text-[#004063]">Individual Verifications</h2>
              </div>
              <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">
                Trust Score Auto-Updates
              </span>
            </div>

            {agent.status !== 'approved' ? (
              <div className="p-4 bg-amber-50 border border-amber-200 rounded-xl flex items-start gap-3">
                <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                <div>
                  <p className="text-sm font-bold text-amber-900">Agent Must Be Approved First</p>
                  <p className="text-xs text-amber-700 mt-0.5">
                    Approve the agent above to enable individual document verifications.
                  </p>
                </div>
              </div>
            ) : (
              <>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                  <VerificationToggle
                    verified={agent.cnicVerified}
                    label="CNIC"
                    item="cnic"
                    loading={verifyingItem === 'cnic'}
                    onToggle={(item, verified) => void handleVerifyItem(item, verified)}
                  />
                  <VerificationToggle
                    verified={agent.licenseVerified}
                    label="License"
                    item="license"
                    loading={verifyingItem === 'license'}
                    onToggle={(item, verified) => void handleVerifyItem(item, verified)}
                  />
                  <VerificationToggle
                    verified={agent.ntnVerified}
                    label="NTN"
                    item="ntn"
                    loading={verifyingItem === 'ntn'}
                    onToggle={(item, verified) => void handleVerifyItem(item, verified)}
                  />
                  <VerificationToggle
                    verified={agent.secpVerified}
                    label="SECP"
                    item="secp"
                    loading={verifyingItem === 'secp'}
                    onToggle={(item, verified) => void handleVerifyItem(item, verified)}
                  />
                </div>

                <div className="mt-4 pt-4 border-t border-gray-100">
                  <p className="text-xs text-gray-500 flex items-start gap-2">
                    <Info className="w-3.5 h-3.5 text-gray-400 shrink-0 mt-0.5" />
                    <span>
                      <strong>Guide:</strong> Verify each document manually after reviewing.
                      Compare the identifier (above in Business Compliance) against the uploaded image.
                      Trust Score auto-recalculates after each toggle.
                    </span>
                  </p>
                </div>

                {/* Office Verification Card */}
                <div className="mt-4 pt-4 border-t border-gray-100">
                  <h3 className="text-sm font-bold text-[#004063] mb-3 flex items-center gap-2">
                    <MapPin className="w-4 h-4 text-[#029bba]" />
                    Office Physical Verification
                  </h3>

                  {agent.officeVerification?.address ? (
                    <div className={`p-4 rounded-xl border-2 transition-all ${
                      agent.officeVerification.verifiedAt
                        ? 'bg-emerald-50 border-emerald-200'
                        : 'bg-gray-50 border-gray-200'
                    }`}>
                      {/* V6.9.0: Map preview for admin verification */}
                      {/* CRITICAL: Pass coordinates so map shows EXACT GPS pin */}
                      {/* Without lat/lng, component geocodes text address (approximation) */}
                      <div className="mb-4">
                        <OfficeMapPreview
                          address={agent.officeVerification.address}
                          city={agent.officeVerification.city}
                          lat={agent.officeVerification.coordinates?.latitude}
                          lng={agent.officeVerification.coordinates?.longitude}
                          height={220}
                          zoom={16}
                        />
                      </div>

                      <div className="flex items-start justify-between gap-4">
                        <div className="flex-1 min-w-0">
                          <p className="text-xs text-gray-500 font-semibold uppercase tracking-wider mb-1">
                            Office Address
                          </p>
                          <p className="text-sm text-gray-900">{agent.officeVerification.address}</p>
                          <p className="text-xs text-gray-500 mt-1">{agent.officeVerification.city}</p>

                          {agent.officeVerification.verifiedAt && (
                            <div className="mt-3 flex items-center gap-2 text-xs text-emerald-700">
                              <CheckCircle className="w-3.5 h-3.5" />
                              <span className="font-semibold">
                                Physically verified on {new Date(agent.officeVerification.verifiedAt).toLocaleDateString('en-PK', {
                                  day: 'numeric', month: 'long', year: 'numeric'
                                })}
                              </span>
                            </div>
                          )}
                        </div>

                        <button
                          onClick={() => {
                            if (agent.officeVerification?.verifiedAt) {
                              void handleVerifyItem('office', false);
                            } else {
                              setShowOfficeVerifyModal(true);
                            }
                          }}
                          disabled={verifyingItem === 'office'}
                          className={`px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap transition-colors disabled:opacity-50 ${
                            agent.officeVerification.verifiedAt
                              ? 'bg-white text-red-600 border border-red-200 hover:bg-red-50'
                              : 'bg-emerald-500 text-white hover:bg-emerald-600'
                          }`}
                        >
                          {verifyingItem === 'office' ? (
                            <span className="inline-flex items-center gap-1.5">
                              <span className="w-3 h-3 border-2 border-current border-t-transparent rounded-full animate-spin" />
                              Updating...
                            </span>
                          ) : agent.officeVerification.verifiedAt ? (
                            'Remove Verification'
                          ) : (
                            '✓ Mark Verified'
                          )}
                        </button>
                      </div>
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic p-3 bg-gray-50 rounded-xl">
                      Agent has not provided an office address yet.
                    </p>
                  )}
                </div>
              </>
            )}
          </div>

          {/* Trust Score — V6.8.6: Auto-calculated + Manual Recalc */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2">
                <Activity className="w-5 h-5 text-[#029bba]" />
                <h2 className="text-base font-bold text-[#004063]">Trust Score</h2>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-3xl font-black text-[#029bba]">
                  {agent.trustScore.overall}
                  <span className="text-sm text-gray-400 font-normal">/100</span>
                </span>
                <button
                  onClick={() => void handleRecalculateTrust()}
                  disabled={recalculating}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg
                             bg-[#029bba]/10 text-[#029bba] text-xs font-bold
                             hover:bg-[#029bba]/20 disabled:opacity-50
                             disabled:cursor-not-allowed transition-colors"
                  title="Recalculate trust score based on current data"
                >
                  <RefreshCw className={`w-3.5 h-3.5 ${recalculating ? 'animate-spin' : ''}`} />
                  {recalculating ? 'Calculating...' : 'Recalculate'}
                </button>
              </div>
            </div>

            {/* Progress bar */}
            <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden mb-2">
              <div
                className="h-full bg-gradient-to-r from-[#029bba] to-[#0284a3] rounded-full transition-all duration-500"
                style={{ width: `${agent.trustScore.overall}%` }}
              />
            </div>

            {/* Last calculated */}
            {agent.trustScore.lastCalculated && (
              <p className="text-[10px] text-gray-400 mb-4">
                Last calculated: {new Date(agent.trustScore.lastCalculated).toLocaleString('en-PK', {
                  day: 'numeric',
                  month: 'short',
                  year: 'numeric',
                  hour: 'numeric',
                  minute: '2-digit',
                })}
              </p>
            )}

            {/* Breakdown with progress bars */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {[
                { key: 'profileComplete',    label: 'Profile Complete',    max: 20, icon: '👤' },
                { key: 'documentsVerified',  label: 'Documents Verified',  max: 25, icon: '📄' },
                { key: 'officeVerified',     label: 'Office Verified',     max: 15, icon: '🏢' },
                { key: 'customerRatings',    label: 'Customer Ratings',    max: 20, icon: '⭐' },
                { key: 'dealHistory',        label: 'Deal History',        max: 15, icon: '🤝' },
                { key: 'responseTime',       label: 'Response Time',       max: 5,  icon: '⚡' },
              ].map(({ key, label, max, icon }) => {
                const val = agent.trustScore.breakdown[key] ?? 0;
                const pct = max > 0 ? (val / max) * 100 : 0;
                const color =
                  pct >= 80 ? 'bg-emerald-500' :
                  pct >= 50 ? 'bg-blue-500' :
                  pct >= 25 ? 'bg-amber-500' :
                              'bg-gray-300';
                return (
                  <div key={key} className="bg-gray-50 rounded-xl p-3">
                    <div className="flex items-center justify-between mb-1.5">
                      <div className="flex items-center gap-1.5">
                        <span className="text-sm">{icon}</span>
                        <p className="text-[11px] text-gray-600 font-medium">{label}</p>
                      </div>
                      <span className="text-xs font-bold text-gray-900">
                        {val}<span className="text-gray-400">/{max}</span>
                      </span>
                    </div>
                    <div className="w-full h-1.5 bg-white rounded-full overflow-hidden">
                      <div
                        className={`h-full ${color} rounded-full transition-all duration-500`}
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Info footer */}
            <div className="mt-4 pt-4 border-t border-gray-100 flex items-start gap-2">
              <TrendingUp className="w-4 h-4 text-[#029bba] shrink-0 mt-0.5" />
              <p className="text-[11px] text-gray-500 leading-relaxed">
                Trust Score is auto-calculated based on profile completeness, verified documents,
                office verification, customer ratings, deal history, and response time.
                Click <strong>Recalculate</strong> after admin actions to refresh.
              </p>
            </div>
          </div>

          {/* V6.9.4: Enterprise Reviews Management — Search, Filter, Sort, Paginate, Edit */}
          <ReviewsSection
            agent={agent}
            agentId={agent._id}
            onAddReview={() => setShowAddReviewModal(true)}
            onEditReview={handleOpenEditReview}
            onDeleteReview={handleDeleteReview}
            onToggleVisibility={handleToggleReviewVisibility}
            deletingReviewId={deletingReviewId}
            togglingReviewId={togglingReviewId}
          />

          {/* Badges */}
          {agent.badges.length > 0 && (
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
              <div className="flex items-center gap-2 mb-4">
                <Award className="w-5 h-5 text-[#029bba]" />
                <h2 className="text-base font-bold text-[#004063]">Earned Badges</h2>
              </div>
              <div className="flex flex-wrap gap-2">
                {agent.badges.map((badge) => (
                  <span
                    key={badge}
                    className="px-3 py-1.5 rounded-full text-xs font-bold bg-[#029bba]/10 text-[#029bba] capitalize"
                  >
                    {badge.replace(/_/g, ' ')}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* V6.8.4: Business Compliance & Identity Section — FULL VALUES for admin verification */}
          <div className="bg-white rounded-2xl border-2 border-red-100 shadow-sm p-6">
            <div className="flex items-start justify-between gap-3 mb-5">
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <Shield className="w-5 h-5 text-red-600" />
                  <h2 className="text-base font-bold text-[#004063]">Business Compliance &amp; Identity</h2>
                </div>
                <p className="text-xs text-gray-500 ml-7">
                  <strong className="text-red-700">Full values shown for verification.</strong> Compare against uploaded documents below.
                  Every view is logged. Data is encrypted (AES-256-GCM) at rest.
                </p>
              </div>
              <span
                className="text-[10px] font-bold uppercase tracking-wider bg-red-50 text-red-700 px-2 py-1 rounded-full border border-red-200 shrink-0"
                title="Admin can see full values — every access is audit-logged"
              >
                🔓 Decrypted
              </span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8">
              {/* Left column — Identity */}
              <dl>
                <ComplianceRow
                  label="CNIC Number"
                  value={formatCnicDisplay(agent.cnicNumber)}
                  isSensitive
                />
                <ComplianceRow
                  label="License Number"
                  value={agent.licenseNumber}
                  isSensitive
                />
                <ComplianceRow
                  label="NTN Number"
                  value={agent.ntnNumber}
                  isSensitive
                />
              </dl>

              {/* Right column — Business & Contact */}
              <dl>
                <ComplianceRow
                  label="Company Reg No"
                  value={agent.companyRegNo}
                  isVisible
                />
                <ComplianceRow
                  label="Phone"
                  value={formatPhoneDisplay(agent.phoneNumber)}
                  isSensitive
                />
                <ComplianceRow
                  label="WhatsApp"
                  value={formatPhoneDisplay(agent.whatsappNumber)}
                  isSensitive
                />
              </dl>
            </div>

            {/* Verification status footer */}
            <div className="mt-5 pt-5 border-t border-gray-100 flex flex-wrap items-center gap-2 text-xs">
              <span className="text-gray-500">Verification Status:</span>
              <span className={`px-2 py-1 rounded-full font-semibold ${agent.cnicVerified ? 'bg-emerald-50 text-emerald-700' : 'bg-gray-100 text-gray-500'}`}>
                CNIC {agent.cnicVerified ? '✓' : '✗'}
              </span>
              <span className={`px-2 py-1 rounded-full font-semibold ${agent.licenseVerified ? 'bg-emerald-50 text-emerald-700' : 'bg-gray-100 text-gray-500'}`}>
                License {agent.licenseVerified ? '✓' : '✗'}
              </span>
              <span className={`px-2 py-1 rounded-full font-semibold ${agent.ntnVerified ? 'bg-emerald-50 text-emerald-700' : 'bg-gray-100 text-gray-500'}`}>
                NTN {agent.ntnVerified ? '✓' : '✗'}
              </span>
            </div>
          </div>

          {/* Info sections grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

            <Section title="Agent Information">
              <dl>
                <InfoRow label="Display Name"       value={agent.displayName}  />
                <InfoRow label="Agent Type"         value={agent.agentType}    />
                <InfoRow label="Agency Name"        value={agent.agencyName}   />
                <InfoRow label="Agency Size"        value={agent.agencySize}   />
                <InfoRow label="Representative"     value={agent.representativeName} />
                <InfoRow label="Representative Role" value={agent.representativeRole} />
                <InfoRow label="License Issuer"     value={agent.licenseIssuer} />
                <InfoRow label="Specializations"    value={agent.specializations.join(', ')} />
                <InfoRow label="Languages"          value={agent.languages.join(', ')} />
                <InfoRow label="Experience"         value={`${agent.experience.years} years`} />
                <InfoRow label="Total Deals"        value={agent.experience.totalDeals} />
              </dl>
            </Section>

            <Section title="Contact & Location">
              <dl>
                <InfoRow label="Personal Email"   value={agent.email}                             />
                <InfoRow label="Business Email"   value={agent.contactEmail}                      />
                <InfoRow label="Primary City"     value={agent.city}                              />
                <InfoRow label="Operating Cities" value={agent.operatingCities.join(', ')}        />
                <InfoRow label="Service Areas"    value={agent.serviceAreas?.localities?.join(', ')} />
                <InfoRow label="Is Available"     value={agent.isAvailable}                       />
                <InfoRow label="Is Featured"      value={agent.isFeatured}                        />
                <InfoRow label="Member Since"     value={new Date(agent.memberSince).toLocaleDateString('en-PK', { day: 'numeric', month: 'long', year: 'numeric' })} />
              </dl>
              {agent.officeVerification && (
                <div className="mt-4 pt-4 border-t border-gray-100">
                  <p className="text-sm font-semibold text-gray-700 mb-2 flex items-center gap-1.5">
                    <MapPin className="w-4 h-4 text-[#029bba]" />
                    Office
                  </p>
                  <p className="text-sm text-gray-600">{agent.officeVerification.address}</p>
                  <p className="text-xs text-gray-400 mt-1">{agent.officeVerification.city}</p>
                  {agent.officeVerification.verifiedAt && (
                    <span className="inline-flex items-center gap-1 mt-2 text-xs font-semibold text-[#10b981] bg-[#f0fdf4] px-2 py-1 rounded-full">
                      <CheckCircle className="w-3 h-3" />
                      Office Verified
                    </span>
                  )}
                </div>
              )}
            </Section>

            <Section title="Performance Stats">
              <dl>
                <InfoRow label="Active Listings"     value={agent.stats.activeListings}    />
                <InfoRow label="Total Listings"      value={agent.stats.totalListings}     />
                <InfoRow label="Sold Properties"     value={agent.stats.soldProperties}    />
                <InfoRow label="Rented Properties"   value={agent.stats.rentedProperties}  />
                <InfoRow label="Total Leads"         value={agent.stats.totalLeads}        />
                <InfoRow label="Converted Leads"     value={agent.stats.convertedLeads}    />
                <InfoRow label="Response Rate"       value={agent.stats.responseRate !== undefined ? `${agent.stats.responseRate}%` : undefined} />
                <InfoRow label="Avg Response Time"   value={agent.stats.averageResponseTime !== undefined ? `${agent.stats.averageResponseTime} min` : undefined} />
              </dl>
            </Section>

            <Section title="Ratings">
              <dl>
                <InfoRow label="Average Rating" value={`${agent.ratings.averageRating} / 5`} />
                <InfoRow label="Total Reviews"  value={agent.ratings.totalReviews}           />
              </dl>
            </Section>

            <Section title="User Account">
              <dl>
                <InfoRow label="Name"           value={agent.user?.name}   />
                <InfoRow label="Email"          value={agent.user?.email}  />
                <InfoRow label="Role"           value={agent.user?.role}   />
                <InfoRow label="Status"         value={agent.user?.status} />
                <InfoRow label="Account Created" value={agent.user?.createdAt
                  ? new Date(agent.user.createdAt).toLocaleDateString('en-PK', { day: 'numeric', month: 'long', year: 'numeric' })
                  : undefined
                } />
              </dl>
            </Section>

            <Section title="Social Links">
              <dl>
                <InfoRow label="Facebook"  value={agent.socialLinks?.facebook}  />
                <InfoRow label="Instagram" value={agent.socialLinks?.instagram} />
                <InfoRow label="LinkedIn"  value={agent.socialLinks?.linkedin}  />
                <InfoRow label="YouTube"   value={agent.socialLinks?.youtube}   />
                <InfoRow label="Twitter"   value={agent.socialLinks?.twitter}   />
                <InfoRow label="TikTok"    value={agent.socialLinks?.tiktok}    />
                <InfoRow label="Website"   value={agent.socialLinks?.website}   />
              </dl>
            </Section>

            <Section title="Submission Info">
              <dl>
                <InfoRow label="Submitted On"  value={new Date(agent.createdAt).toLocaleDateString('en-PK', { day: 'numeric', month: 'long', year: 'numeric' })} />
                <InfoRow label="Last Updated"  value={new Date(agent.updatedAt).toLocaleDateString('en-PK', { day: 'numeric', month: 'long', year: 'numeric' })} />
                {agent.verifiedAt && (
                  <InfoRow label="Verified On" value={new Date(agent.verifiedAt).toLocaleDateString('en-PK', { day: 'numeric', month: 'long', year: 'numeric' })} />
                )}
                {agent.rejectionReason && (
                  <InfoRow label="Rejection Reason" value={agent.rejectionReason} />
                )}
                {agent.suspensionReason && (
                  <InfoRow label="Suspension Reason" value={agent.suspensionReason} />
                )}
              </dl>
            </Section>

            <Section title="About">
              <dl>
                <InfoRow label="Profile Slug" value={agent.slug} />
              </dl>
              {agent.about ? (
                <div className="mt-4 pt-4 border-t border-gray-100">
                  <p className="text-sm font-semibold text-gray-500 mb-2">About</p>
                  <p className="text-sm text-gray-700 whitespace-pre-wrap">{agent.about}</p>
                </div>
              ) : (
                <p className="text-sm text-gray-400 italic mt-2">No bio provided.</p>
              )}
            </Section>

          </div>

          {/* V6.8.3: Documents Section — cleaned up (removed empty NTN/SECP boxes) */}
          <Section title="Uploaded Documents">
            <div className="mb-4 p-3 bg-blue-50 border border-blue-100 rounded-xl">
              <p className="text-xs text-blue-800">
                <strong>ℹ️ Review Guide:</strong> Verify each document matches the identity claims above.
                Check CNIC images are clear, match the agent&apos;s name, and are not expired.
              </p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {/* Identity documents (MANDATORY for verification) */}
              <DocumentCard
                title="CNIC Front"
                url={agent.documents?.cnicFront?.url}
              />
              <DocumentCard
                title="CNIC Back"
                url={agent.documents?.cnicBack?.url}
              />
              <DocumentCard
                title="License / Verification Doc"
                url={agent.documents?.license?.url ?? agent.licenseDocumentUrl}
              />

              {/* Profile & branding (OPTIONAL — for public profile) */}
              <DocumentCard
                title="Profile Photo"
                url={agent.documents?.profilePhoto?.url}
              />
              <DocumentCard
                title="Cover Photo"
                url={agent.documents?.coverPhoto?.url}
              />
              <DocumentCard
                title="Agency Logo"
                url={agent.agencyLogo?.url}
              />
            </div>

            <div className="mt-4 pt-4 border-t border-gray-100">
              <p className="text-xs text-gray-500">
                Documents marked as &quot;Not uploaded&quot; are optional and can be added by the agent later from their dashboard.
              </p>
            </div>
          </Section>

          {/* Contact quick links */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
            <h2 className="text-base font-bold text-[#004063] mb-4">Quick Contact</h2>
            <div className="flex flex-wrap gap-3">
              {agent.email && (
                <a
                  href={`mailto:${agent.email}`}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-[#029bba]/10 text-[#029bba] text-sm font-semibold hover:bg-[#029bba]/20 transition-colors"
                >
                  <Mail className="w-4 h-4" />
                  Email Agent
                </a>
              )}
              {agent.slug && (
                <Link
                  href={`/agent/${agent.slug}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-gray-100 text-gray-700 text-sm font-semibold hover:bg-gray-200 transition-colors"
                >
                  <ExternalLink className="w-4 h-4" />
                  Public Profile
                </Link>
              )}
            </div>
          </div>

        </div>
      </AdminLayout>
    </>
  );
}

// pages/admin/aleem/conversations.tsx
// Highrise.pk — Aleem Conversations List + Viewer (admin)
// V6.4.1 — Browse all conversations + view full message threads

import React, { useState, useEffect, useCallback } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import AdminLayout from '@/components/admin/AdminLayout';
import {
  MessagesSquare,
  Search,
  Filter,
  Loader2,
  Eye,
  X,
  ChevronLeft,
  ChevronRight,
  AlertCircle,
  Bot,
  User,
  CheckCircle,
  XCircle,
  ExternalLink,
  Calendar,
  Globe,
  Target,
  Phone,
  Mail,
  Flame,
  RefreshCw,
} from 'lucide-react';

interface ConversationItem {
  _id:             string;
  sessionId:       string;
  createdAt:       string;
  lastActivityAt:  string;
  messageCount:    number;
  detectedIntent:  string;
  leadStatus:      string;
  leadCaptured:    boolean;
  leadId?:         string;
  context: { type: string; title?: string; city?: string };
  isActive:        boolean;
}

interface FullConversation {
  _id:            string;
  sessionId:      string;
  context:        Record<string, unknown>;
  messages:       Array<{ role: string; content: string; timestamp: string }>;
  messageCount:   number;
  detectedIntent: string;
  budgetMentioned?: number;
  cityMentioned?:   string;
  leadStatus:     string;
  leadCaptured:   boolean;
  leadId?:        string | null;
  linkedLead?: {
    _id: string; name: string; phone: string; email: string;
    temperature: string; priority: string; status: string;
  } | null;
  ipAddress?:     string;
  createdAt:      string;
  lastActivityAt: string;
}

interface Pagination {
  page: number; limit: number; total: number; pages: number;
}

const INTENT_COLORS: Record<string, string> = {
  buy:            '#029bba',
  rent:           '#10b981',
  invest:         '#f59e0b',
  verify_society: '#7c3aed',
  price_check:    '#06b6d4',
  general:        '#6b7280',
  unknown:        '#9ca3af',
};

const INTENT_LABELS: Record<string, string> = {
  buy: 'BUY', rent: 'RENT', invest: 'INVEST',
  verify_society: 'VERIFY', price_check: 'PRICE',
  general: 'GENERAL', unknown: '—',
};

export default function AleemConversationsPage(): React.ReactElement {
  const router = useRouter();
  const { status } = useSession();

  const [conversations, setConversations] = useState<ConversationItem[]>([]);
  const [pagination, setPagination] = useState<Pagination>({
    page: 1, limit: 20, total: 0, pages: 0,
  });
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');

  // Filters
  const [intent, setIntent]               = useState('');
  const [contextType, setContextType]     = useState('');
  const [leadCaptured, setLeadCaptured]   = useState('');
  const [search, setSearch]               = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');

  // Modal
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [fullConv, setFullConv]     = useState<FullConversation | null>(null);
  const [modalLoading, setModalLoading] = useState(false);

  // Auth guard
  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/login?callbackUrl=/admin/aleem/conversations');
    }
  }, [status, router]);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 500);
    return () => clearTimeout(timer);
  }, [search]);

  // Fetch conversations
  const fetchConversations = useCallback(async (showRefresh = false) => {
    if (showRefresh) setRefreshing(true);
    else setLoading(true);
    setError('');

    try {
      const params = new URLSearchParams({
        page:  String(pagination.page),
        limit: String(pagination.limit),
      });
      if (intent)       params.append('intent', intent);
      if (contextType)  params.append('contextType', contextType);
      if (leadCaptured) params.append('leadCaptured', leadCaptured);
      if (debouncedSearch) params.append('search', debouncedSearch);

      const res = await fetch(`/api/admin/aleem/conversations?${params}`);
      const data = await res.json() as {
        success: boolean;
        data?: { conversations: ConversationItem[]; pagination: Pagination };
        error?: string;
      };

      if (!res.ok || !data.success || !data.data) {
        setError(data.error ?? 'Failed to load');
        return;
      }
      setConversations(data.data.conversations);
      setPagination(data.data.pagination);
    } catch {
      setError('Network error.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [pagination.page, pagination.limit, intent, contextType, leadCaptured, debouncedSearch]);

  useEffect(() => {
    fetchConversations();
  }, [fetchConversations]);

  // View single conversation
  const viewConversation = async (id: string) => {
    setSelectedId(id);
    setModalLoading(true);
    setFullConv(null);
    try {
      const res = await fetch(`/api/admin/aleem/conversations/${id}`);
      const data = await res.json() as { success: boolean; data?: FullConversation; error?: string };
      if (data.success && data.data) setFullConv(data.data);
    } catch {
      // silent
    } finally {
      setModalLoading(false);
    }
  };

  const closeModal = () => {
    setSelectedId(null);
    setFullConv(null);
  };

  const formatDate = (iso: string) => {
    const d = new Date(iso);
    const diffMs   = Date.now() - d.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    if (diffMins < 1)   return 'Just now';
    if (diffMins < 60)  return `${diffMins}m ago`;
    if (diffMins < 1440) return `${Math.floor(diffMins/60)}h ago`;
    return d.toLocaleDateString('en-PK', { day: 'numeric', month: 'short' });
  };

  if (status === 'loading') {
    return <AdminLayout><div className="flex items-center justify-center min-h-[60vh]"><Loader2 className="w-8 h-8 animate-spin text-[#029bba]" /></div></AdminLayout>;
  }

  return (
    <AdminLayout>
      <Head><title>Aleem Conversations | Highrise Admin</title></Head>

      <div className="p-6 space-y-6">

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              <MessagesSquare className="w-7 h-7 text-[#029bba]" />
              Aleem Conversations
            </h1>
            <p className="text-gray-500 mt-1">All chat sessions with full message history</p>
          </div>
          <button
            onClick={() => fetchConversations(true)}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2.5 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 rounded-xl font-medium transition-colors"
          >
            <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>

        {/* Filters */}
        <div className="bg-white border border-gray-200 rounded-2xl p-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Search session ID or title..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pl-10 pr-3 py-2.5 border border-gray-200 rounded-xl text-sm focus:outline-none focus:border-[#029bba]"
              />
            </div>

            {/* Intent filter */}
            <select
              value={intent}
              onChange={(e) => { setIntent(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
              className="px-3 py-2.5 border border-gray-200 rounded-xl text-sm bg-white focus:outline-none focus:border-[#029bba]"
            >
              <option value="">All Intents</option>
              <option value="buy">🏠 Buy</option>
              <option value="rent">🔑 Rent</option>
              <option value="invest">📈 Invest</option>
              <option value="verify_society">🔍 Verify Society</option>
              <option value="price_check">💰 Price Check</option>
              <option value="general">💬 General</option>
            </select>

            {/* Context filter */}
            <select
              value={contextType}
              onChange={(e) => { setContextType(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
              className="px-3 py-2.5 border border-gray-200 rounded-xl text-sm bg-white focus:outline-none focus:border-[#029bba]"
            >
              <option value="">All Contexts</option>
              <option value="property">🏠 Property Page</option>
              <option value="project">🏗️ Project Page</option>
              <option value="society">🏘️ Society Page</option>
              <option value="general">🌐 General/Homepage</option>
            </select>

            {/* Lead captured filter */}
            <select
              value={leadCaptured}
              onChange={(e) => { setLeadCaptured(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
              className="px-3 py-2.5 border border-gray-200 rounded-xl text-sm bg-white focus:outline-none focus:border-[#029bba]"
            >
              <option value="">All Conversations</option>
              <option value="true">✅ Lead Captured</option>
              <option value="false">❌ No Lead</option>
            </select>
          </div>
        </div>

        {/* Error */}
        {error && (
          <div className="bg-[#fef2f2] border-l-4 border-[#ef4444] text-red-700 px-4 py-3 rounded-xl flex items-center gap-2">
            <AlertCircle className="w-5 h-5" />
            {error}
          </div>
        )}

        {/* Table */}
        <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-8 h-8 animate-spin text-[#029bba]" />
            </div>
          ) : conversations.length === 0 ? (
            <div className="text-center py-12">
              <MessagesSquare className="w-12 h-12 text-gray-300 mx-auto mb-3" />
              <p className="text-gray-500">No conversations found</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="text-left px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Session</th>
                    <th className="text-left px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Context</th>
                    <th className="text-left px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Intent</th>
                    <th className="text-left px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Messages</th>
                    <th className="text-left px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Lead</th>
                    <th className="text-left px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Active</th>
                    <th className="text-left px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Last Activity</th>
                    <th className="text-right px-4 py-3 text-xs font-semibold text-gray-600 uppercase">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {conversations.map((c) => (
                    <tr key={c._id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-4 py-3">
                        <p className="font-mono text-xs text-gray-700">{c.sessionId.slice(0, 8)}...</p>
                        <p className="text-xs text-gray-400 mt-0.5">{formatDate(c.createdAt)}</p>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          <span className="text-xs px-2 py-0.5 rounded-full bg-gray-100 text-gray-700 capitalize">
                            {c.context.type}
                          </span>
                        </div>
                        {c.context.title && (
                          <p className="text-xs text-gray-600 mt-1 truncate max-w-[180px]">{c.context.title}</p>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className="text-xs px-2 py-1 rounded-full font-bold"
                          style={{
                            backgroundColor: `${INTENT_COLORS[c.detectedIntent]}15`,
                            color: INTENT_COLORS[c.detectedIntent],
                          }}
                        >
                          {INTENT_LABELS[c.detectedIntent]}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-700">{c.messageCount}</td>
                      <td className="px-4 py-3">
                        {c.leadCaptured ? (
                          <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full bg-[#f0fdf4] text-[#10b981] text-xs font-bold">
                            <CheckCircle className="w-3 h-3" /> Captured
                          </span>
                        ) : (
                          <span className="text-xs text-gray-400">—</span>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        {c.isActive ? (
                          <span className="inline-flex items-center gap-1 text-xs text-[#10b981]">
                            <div className="w-2 h-2 rounded-full bg-[#10b981] animate-pulse" />
                            Active
                          </span>
                        ) : (
                          <span className="text-xs text-gray-400">Closed</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-xs text-gray-500">
                        {formatDate(c.lastActivityAt)}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          onClick={() => viewConversation(c._id)}
                          className="p-2 hover:bg-[#029bba]/10 text-[#029bba] rounded-lg transition-colors"
                          title="View Full Conversation"
                        >
                          <Eye className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Pagination */}
          {pagination.pages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200">
              <p className="text-sm text-gray-600">
                Page {pagination.page} of {pagination.pages} • {pagination.total} total
              </p>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setPagination(p => ({ ...p, page: p.page - 1 }))}
                  disabled={pagination.page === 1}
                  className="p-2 hover:bg-gray-100 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <ChevronLeft className="w-5 h-5" />
                </button>
                <button
                  onClick={() => setPagination(p => ({ ...p, page: p.page + 1 }))}
                  disabled={pagination.page === pagination.pages}
                  className="p-2 hover:bg-gray-100 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <ChevronRight className="w-5 h-5" />
                </button>
              </div>
            </div>
          )}
        </div>

      </div>

      {/* Full Conversation Modal */}
      {selectedId && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-3xl max-h-[90vh] flex flex-col shadow-2xl">
            {/* Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 bg-gradient-to-r from-[#029bba] to-[#004063] text-white rounded-t-2xl">
              <div>
                <h2 className="text-lg font-bold flex items-center gap-2">
                  <Bot className="w-5 h-5" />
                  Full Conversation
                </h2>
                {fullConv && (
                  <p className="text-xs text-white/80 mt-1 font-mono">{fullConv.sessionId}</p>
                )}
              </div>
              <button onClick={closeModal} className="p-2 hover:bg-white/10 rounded-lg transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Body */}
            <div className="flex-1 overflow-y-auto">
              {modalLoading ? (
                <div className="flex items-center justify-center py-12">
                  <Loader2 className="w-8 h-8 animate-spin text-[#029bba]" />
                </div>
              ) : fullConv ? (
                <div className="p-6 space-y-4">
                  {/* Meta info */}
                  <div className="grid grid-cols-2 gap-3 bg-gray-50 rounded-xl p-4">
                    <div>
                      <p className="text-xs text-gray-500">Intent</p>
                      <p className="font-semibold text-gray-900 capitalize">{fullConv.detectedIntent.replace('_', ' ')}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Messages</p>
                      <p className="font-semibold text-gray-900">{fullConv.messageCount}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Started</p>
                      <p className="font-semibold text-gray-900 text-sm">{new Date(fullConv.createdAt).toLocaleString('en-PK')}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Lead Status</p>
                      <p className="font-semibold text-gray-900 capitalize">{fullConv.leadStatus}</p>
                    </div>
                  </div>

                  {/* Linked Lead */}
                  {fullConv.linkedLead && (
                    <div className="bg-[#f0fdf4] border border-[#10b981]/30 rounded-xl p-4">
                      <div className="flex items-center justify-between">
                        <div>
                          <p className="text-xs text-[#10b981] font-bold uppercase mb-1">✓ Lead Captured</p>
                          <p className="font-bold text-gray-900">{fullConv.linkedLead.name}</p>
                          <div className="flex items-center gap-3 mt-1 text-sm text-gray-700">
                            <span className="flex items-center gap-1"><Phone className="w-3 h-3" /> {fullConv.linkedLead.phone}</span>
                            {fullConv.linkedLead.email && <span className="flex items-center gap-1"><Mail className="w-3 h-3" /> {fullConv.linkedLead.email}</span>}
                          </div>
                        </div>
                        <div className="flex flex-col items-end gap-1">
                          {fullConv.linkedLead.temperature === 'burning' && (
                            <span className="px-2 py-1 rounded-full bg-[#ef4444] text-white text-xs font-bold">🔥 BURNING</span>
                          )}
                          {fullConv.linkedLead.temperature === 'hot' && (
                            <span className="px-2 py-1 rounded-full bg-[#f97316] text-white text-xs font-bold">🔥 HOT</span>
                          )}
                          <Link href={`/admin/leads`}>
                            <button className="text-xs text-[#029bba] hover:underline flex items-center gap-1">
                              View Lead <ExternalLink className="w-3 h-3" />
                            </button>
                          </Link>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Messages */}
                  <div className="space-y-3">
                    {fullConv.messages.map((msg, idx) => (
                      <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[75%] rounded-2xl px-4 py-3 ${
                          msg.role === 'user'
                            ? 'bg-[#029bba] text-white'
                            : 'bg-gray-100 text-gray-800'
                        }`}>
                          <div className="flex items-center gap-2 mb-1 opacity-80">
                            {msg.role === 'user'
                              ? <User className="w-3 h-3" />
                              : <Bot className="w-3 h-3" />}
                            <span className="text-xs font-medium">
                              {msg.role === 'user' ? 'User' : 'Aleem'}
                            </span>
                          </div>
                          <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                          <p className={`text-xs mt-1 ${msg.role === 'user' ? 'text-white/70' : 'text-gray-500'}`}>
                            {new Date(msg.timestamp).toLocaleTimeString('en-PK', { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="text-center py-12">
                  <p className="text-gray-500">Failed to load conversation</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </AdminLayout>
  );
}

// pages/admin/aleem/index.tsx
// Highrise.pk — Aleem AI Dashboard (admin)
// V6.4.1 — Live stats, hot leads alert, quota monitoring

import React, { useState, useEffect } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import AdminLayout from '@/components/admin/AdminLayout';
import {
  Bot,
  MessageCircle,
  Users,
  TrendingUp,
  Activity,
  AlertCircle,
  CheckCircle,
  Flame,
  Clock,
  ArrowRight,
  RefreshCw,
  Loader2,
  Globe,
  Target,
  Zap,
} from 'lucide-react';

interface DashboardStats {
  conversationsToday:    number;
  leadsToday:            number;
  conversionRateToday:   number;
  activeNow:             number;
  conversationsThisWeek: number;
  leadsThisWeek:         number;
  conversionRateWeek:    number;
  totalConversations:    number;
  totalLeads:            number;
  totalHotLeads:         number;
  totalBurningLeads:     number;
  intentBreakdown: {
    buy: number; rent: number; invest: number;
    verify_society: number; price_check: number;
    general: number; unknown: number;
  };
  contextBreakdown: {
    property: number; project: number; society: number; general: number;
  };
  hourlyActivity: Array<{
    hour: string; conversations: number; leads: number;
  }>;
  quota: {
    used: number; limit: number; percentage: number;
    mode: 'normal' | 'priority' | 'lead_only';
    remaining: number; resetAt: number;
  };
}

export default function AleemDashboardPage(): React.ReactElement {
  const router = useRouter();
  const { status } = useSession();

  const [stats, setStats]     = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState('');
  const [refreshing, setRefreshing] = useState(false);

  // Auth guard
  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/login?callbackUrl=/admin/aleem');
    }
  }, [status, router]);

  // Fetch stats
  const fetchStats = async (showRefresh = false) => {
    if (showRefresh) setRefreshing(true);
    else setLoading(true);
    setError('');

    try {
      const res = await fetch('/api/admin/aleem/dashboard-stats');
      const data = await res.json() as { success: boolean; data?: DashboardStats; error?: string };

      if (!res.ok || !data.success || !data.data) {
        setError(data.error ?? 'Failed to load stats');
        return;
      }
      setStats(data.data);
    } catch {
      setError('Network error. Please try again.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchStats();
    // Auto-refresh every 30 seconds
    const interval = setInterval(() => fetchStats(true), 30000);
    return () => clearInterval(interval);
  }, []);

  if (status === 'loading' || loading) {
    return (
      <AdminLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="w-8 h-8 animate-spin text-[#029bba]" />
        </div>
      </AdminLayout>
    );
  }

  if (error || !stats) {
    return (
      <AdminLayout>
        <Head><title>Aleem Dashboard | Highrise Admin</title></Head>
        <div className="p-6">
          <div className="bg-[#fef2f2] border border-[#ef4444]/30 rounded-2xl p-6 text-center">
            <AlertCircle className="w-12 h-12 text-[#ef4444] mx-auto mb-3" />
            <h2 className="text-lg font-bold text-red-700 mb-2">Unable to Load Dashboard</h2>
            <p className="text-red-600 mb-4">{error || 'No data available'}</p>
            <button
              onClick={() => fetchStats()}
              className="px-5 py-2.5 bg-[#029bba] text-white rounded-xl font-medium hover:bg-[#027a94] transition-colors"
            >
              Retry
            </button>
          </div>
        </div>
      </AdminLayout>
    );
  }

  const totalHotAndBurning = stats.totalHotLeads + stats.totalBurningLeads;
  const quotaColor = stats.quota.mode === 'lead_only' ? 'red'
                   : stats.quota.mode === 'priority'  ? 'amber'
                   : 'green';

  // Build intent rows for display
  const intentRows = [
    { label: '🏠 Buy',           value: stats.intentBreakdown.buy,            color: '#029bba' },
    { label: '🔑 Rent',          value: stats.intentBreakdown.rent,           color: '#10b981' },
    { label: '📈 Invest',        value: stats.intentBreakdown.invest,         color: '#f59e0b' },
    { label: '🔍 Verify Society',value: stats.intentBreakdown.verify_society, color: '#7c3aed' },
    { label: '💰 Price Check',   value: stats.intentBreakdown.price_check,    color: '#06b6d4' },
    { label: '💬 General',       value: stats.intentBreakdown.general,        color: '#6b7280' },
  ].filter(row => row.value > 0);

  return (
    <AdminLayout>
      <Head><title>Aleem Dashboard | Highrise Admin</title></Head>

      <div className="p-6 space-y-6">

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#029bba] to-[#004063] flex items-center justify-center">
                <Bot className="w-5 h-5 text-white" />
              </div>
              Aleem AI Dashboard
            </h1>
            <p className="text-gray-500 mt-1">Real-time performance + lead conversion metrics</p>
          </div>
          <button
            onClick={() => fetchStats(true)}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2.5 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 rounded-xl font-medium transition-colors"
          >
            <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>

        {/* HOT LEADS ALERT */}
        {totalHotAndBurning > 0 && (
          <div className="bg-gradient-to-r from-[#ef4444] to-[#dc2626] text-white rounded-2xl p-6 shadow-lg">
            <div className="flex items-center justify-between flex-wrap gap-4">
              <div className="flex items-center gap-4">
                <div className="w-14 h-14 rounded-full bg-white/20 flex items-center justify-center animate-pulse">
                  <Flame className="w-7 h-7 text-white" />
                </div>
                <div>
                  <h2 className="text-xl font-bold">🔥 {totalHotAndBurning} Priority Lead{totalHotAndBurning > 1 ? 's' : ''} Need Attention!</h2>
                  <p className="text-white/90 text-sm mt-1">
                    {stats.totalBurningLeads} burning + {stats.totalHotLeads} hot leads pending — call within 1 hour for best conversion
                  </p>
                </div>
              </div>
              <Link href="/admin/aleem/leads?temperature=burning,hot">
                <button className="px-5 py-2.5 bg-white text-[#dc2626] rounded-xl font-bold hover:bg-gray-100 transition-colors flex items-center gap-2">
                  View Hot Leads
                  <ArrowRight className="w-4 h-4" />
                </button>
              </Link>
            </div>
          </div>
        )}

        {/* QUOTA STATUS */}
        <div className={`bg-white border-2 rounded-2xl p-5 ${
          quotaColor === 'red'   ? 'border-[#ef4444]' :
          quotaColor === 'amber' ? 'border-[#f59e0b]' :
                                   'border-[#10b981]'
        }`}>
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Zap className={`w-5 h-5 ${
                quotaColor === 'red'   ? 'text-[#ef4444]' :
                quotaColor === 'amber' ? 'text-[#f59e0b]' :
                                         'text-[#10b981]'
              }`} />
              <h3 className="font-bold text-gray-900">Quota Status</h3>
            </div>
            <span className={`px-3 py-1 rounded-full text-xs font-bold ${
              quotaColor === 'red'   ? 'bg-[#fef2f2] text-[#ef4444]' :
              quotaColor === 'amber' ? 'bg-[#fef3c7] text-[#f59e0b]' :
                                       'bg-[#f0fdf4] text-[#10b981]'
            }`}>
              {stats.quota.mode === 'lead_only' ? '🔴 LEAD CAPTURE ONLY' :
               stats.quota.mode === 'priority'  ? '🟠 PRIORITY MODE' :
                                                  '🟢 NORMAL MODE'}
            </span>
          </div>
          <div className="space-y-2">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-600">
                {stats.quota.used.toLocaleString()} / {stats.quota.limit.toLocaleString()} requests
              </span>
              <span className="font-bold text-gray-900">{stats.quota.percentage}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-3">
              <div
                className={`h-3 rounded-full transition-all ${
                  quotaColor === 'red'   ? 'bg-[#ef4444]' :
                  quotaColor === 'amber' ? 'bg-[#f59e0b]' :
                                           'bg-[#10b981]'
                }`}
                style={{ width: `${stats.quota.percentage}%` }}
              />
            </div>
            <p className="text-xs text-gray-500">
              Resets at midnight UTC (5 AM PKT) • {stats.quota.remaining.toLocaleString()} requests remaining
            </p>
          </div>
        </div>

        {/* MAIN STATS GRID */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <StatCard
            icon={<MessageCircle className="w-5 h-5" />}
            label="Conversations Today"
            value={stats.conversationsToday}
            color="#029bba"
          />
          <StatCard
            icon={<Users className="w-5 h-5" />}
            label="Leads Today"
            value={stats.leadsToday}
            color="#10b981"
          />
          <StatCard
            icon={<TrendingUp className="w-5 h-5" />}
            label="Conversion Rate"
            value={`${stats.conversionRateToday}%`}
            color="#f59e0b"
          />
          <StatCard
            icon={<Activity className="w-5 h-5" />}
            label="Active Now"
            value={stats.activeNow}
            color="#7c3aed"
            pulse={stats.activeNow > 0}
          />
        </div>

        {/* WEEK & ALL-TIME GRID */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {/* This Week */}
          <div className="bg-white border border-gray-200 rounded-2xl p-5">
            <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2">
              <Clock className="w-5 h-5 text-[#029bba]" />
              This Week
            </h3>
            <div className="grid grid-cols-3 gap-3">
              <div>
                <p className="text-3xl font-bold text-gray-900">{stats.conversationsThisWeek}</p>
                <p className="text-xs text-gray-500 mt-1">Conversations</p>
              </div>
              <div>
                <p className="text-3xl font-bold text-[#10b981]">{stats.leadsThisWeek}</p>
                <p className="text-xs text-gray-500 mt-1">Leads</p>
              </div>
              <div>
                <p className="text-3xl font-bold text-[#f59e0b]">{stats.conversionRateWeek}%</p>
                <p className="text-xs text-gray-500 mt-1">Conv. Rate</p>
              </div>
            </div>
          </div>

          {/* All-Time */}
          <div className="bg-white border border-gray-200 rounded-2xl p-5">
            <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2">
              <Target className="w-5 h-5 text-[#029bba]" />
              All-Time Performance
            </h3>
            <div className="grid grid-cols-3 gap-3">
              <div>
                <p className="text-3xl font-bold text-gray-900">{stats.totalConversations.toLocaleString()}</p>
                <p className="text-xs text-gray-500 mt-1">Total Chats</p>
              </div>
              <div>
                <p className="text-3xl font-bold text-[#10b981]">{stats.totalLeads.toLocaleString()}</p>
                <p className="text-xs text-gray-500 mt-1">Total Leads</p>
              </div>
              <div>
                <p className="text-3xl font-bold text-[#ef4444]">{totalHotAndBurning}</p>
                <p className="text-xs text-gray-500 mt-1">Hot Leads</p>
              </div>
            </div>
          </div>
        </div>

        {/* INTENT BREAKDOWN */}
        {intentRows.length > 0 && (
          <div className="bg-white border border-gray-200 rounded-2xl p-5">
            <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2">
              <Target className="w-5 h-5 text-[#029bba]" />
              Today's Intent Breakdown
            </h3>
            <div className="space-y-3">
              {intentRows.map((row) => {
                const max = Math.max(...intentRows.map(r => r.value), 1);
                const pct = Math.round((row.value / max) * 100);
                return (
                  <div key={row.label} className="flex items-center gap-3">
                    <div className="w-40 text-sm text-gray-700">{row.label}</div>
                    <div className="flex-1 bg-gray-100 rounded-full h-7 overflow-hidden">
                      <div
                        className="h-full flex items-center justify-end px-3 text-white text-xs font-bold transition-all duration-500"
                        style={{ width: `${pct}%`, backgroundColor: row.color }}
                      >
                        {row.value > 0 && row.value}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* QUICK LINKS */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <Link href="/admin/aleem/conversations">
            <div className="bg-white border border-gray-200 rounded-2xl p-5 hover:shadow-md hover:border-[#029bba] transition-all cursor-pointer">
              <div className="flex items-center justify-between mb-3">
                <div className="w-12 h-12 rounded-xl bg-[#029bba]/10 flex items-center justify-center">
                  <MessageCircle className="w-6 h-6 text-[#029bba]" />
                </div>
                <ArrowRight className="w-5 h-5 text-gray-400" />
              </div>
              <h4 className="font-bold text-gray-900">View All Conversations</h4>
              <p className="text-sm text-gray-500 mt-1">Browse complete chat history with filters</p>
            </div>
          </Link>

          <Link href="/admin/aleem/leads">
            <div className="bg-white border border-gray-200 rounded-2xl p-5 hover:shadow-md hover:border-[#10b981] transition-all cursor-pointer">
              <div className="flex items-center justify-between mb-3">
                <div className="w-12 h-12 rounded-xl bg-[#10b981]/10 flex items-center justify-center">
                  <Users className="w-6 h-6 text-[#10b981]" />
                </div>
                <ArrowRight className="w-5 h-5 text-gray-400" />
              </div>
              <h4 className="font-bold text-gray-900">Aleem-Only Leads</h4>
              <p className="text-sm text-gray-500 mt-1">View leads captured by Aleem with priorities</p>
            </div>
          </Link>
        </div>

      </div>
    </AdminLayout>
  );
}

// ─── StatCard ─────────────────────────────────────────────────────────────────

function StatCard({
  icon, label, value, color, pulse,
}: {
  icon: React.ReactElement;
  label: string;
  value: number | string;
  color: string;
  pulse?: boolean;
}): React.ReactElement {
  return (
    <div className="bg-white border border-gray-200 rounded-2xl p-5 hover:shadow-md transition-shadow">
      <div className="flex items-center justify-between mb-3">
        <div
          className={`w-10 h-10 rounded-xl flex items-center justify-center ${pulse ? 'animate-pulse' : ''}`}
          style={{ backgroundColor: `${color}15`, color }}
        >
          {icon}
        </div>
      </div>
      <p className="text-3xl font-bold text-gray-900">{value}</p>
      <p className="text-xs text-gray-500 mt-1">{label}</p>
    </div>
  );
}

// pages/admin/aleem/leads.tsx
// Highrise.pk — Aleem-Only Leads (admin)
// V6.4.1 — Filtered view of source='direct' leads with temperature colors

import React, { useState, useEffect, useCallback } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import AdminLayout from '@/components/admin/AdminLayout';
import {
  Users,
  Phone,
  Mail,
  Search,
  Loader2,
  ChevronLeft,
  ChevronRight,
  AlertCircle,
  Bot,
  Flame,
  ExternalLink,
  Eye,
  MessageCircle,
  RefreshCw,
  Filter,
  Calendar,
} from 'lucide-react';

interface AleemLead {
  _id:        string;
  name:       string;
  phone:      string;
  email:      string;
  message?:   string;
  leadType:   string;
  status:     string;
  priority:   string;
  temperature: string;
  source:     string;
  leadScore:  number;
  conversationId?: string;
  sessionId?: string;
  budget?: { tier?: string };
  createdAt:  string;
}

interface Pagination {
  page: number; limit: number; total: number; pages: number;
}

const TEMPERATURE_CONFIG: Record<string, { label: string; bg: string; text: string; icon: string }> = {
  burning: { label: 'BURNING', bg: 'bg-[#ef4444]',  text: 'text-white',         icon: '🔥' },
  hot:     { label: 'HOT',     bg: 'bg-[#f97316]',  text: 'text-white',         icon: '🔥' },
  warm:    { label: 'WARM',    bg: 'bg-[#f59e0b]',  text: 'text-white',         icon: '🌡️' },
  cold:    { label: 'COLD',    bg: 'bg-[#6b7280]',  text: 'text-white',         icon: '❄️' },
};

const STATUS_COLORS: Record<string, string> = {
  new:        '#3b82f6',
  contacted:  '#7c3aed',
  qualified:  '#f97316',
  won:        '#10b981',
  lost:       '#ef4444',
};

export default function AleemLeadsPage(): React.ReactElement {
  const router = useRouter();
  const { status: sessionStatus } = useSession();

  const [leads, setLeads] = useState<AleemLead[]>([]);
  const [pagination, setPagination] = useState<Pagination>({
    page: 1, limit: 20, total: 0, pages: 0,
  });
  const [loading, setLoading]       = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError]           = useState('');

  // Filters
  const [temperature, setTemperature] = useState('');
  const [status, setStatus]           = useState('');
  const [search, setSearch]           = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');

  // Read query param on mount (e.g., ?temperature=burning,hot)
  useEffect(() => {
    if (router.query.temperature && typeof router.query.temperature === 'string') {
      setTemperature(router.query.temperature);
    }
  }, [router.query]);

  // Auth guard
  useEffect(() => {
    if (sessionStatus === 'unauthenticated') {
      router.push('/auth/login?callbackUrl=/admin/aleem/leads');
    }
  }, [sessionStatus, router]);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 500);
    return () => clearTimeout(timer);
  }, [search]);

  // Fetch leads (using existing /api/leads endpoint, filtered to source=direct)
  const fetchLeads = useCallback(async (showRefresh = false) => {
    if (showRefresh) setRefreshing(true);
    else setLoading(true);
    setError('');

    try {
      const params = new URLSearchParams({
        page:  String(pagination.page),
        limit: String(pagination.limit),
        source: 'direct',  // Aleem source filter
      });
      if (status)     params.append('status', status);
      if (debouncedSearch) params.append('search', debouncedSearch);

      // Try /api/leads first (existing endpoint)
      const res = await fetch(`/api/leads?${params}`, {
        credentials: 'include', // ✅ Required: sends session cookie to getServerSession()
      });
      const data = await res.json() as {
        success: boolean;
        data?: AleemLead[];
        pagination?: Pagination;
        error?: string;
      };

      if (!res.ok || !data.success) {
        setError(data.error ?? 'Failed to load leads');
        return;
      }

      let filteredLeads = data.data ?? [];

      // Apply temperature filter (client-side since API may not support it)
      if (temperature) {
        const temps = temperature.split(',');
        filteredLeads = filteredLeads.filter(l => temps.includes(l.temperature));
      }

      setLeads(filteredLeads);
      if (data.pagination) setPagination(data.pagination);

    } catch {
      setError('Network error.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [pagination.page, pagination.limit, status, debouncedSearch, temperature]);

  useEffect(() => {
    fetchLeads();
  }, [fetchLeads]);

  const formatDate = (iso: string) => {
    const d = new Date(iso);
    const diffMs = Date.now() - d.getTime();
    const mins = Math.floor(diffMs / 60000);
    if (mins < 60) return `${mins}m ago`;
    if (mins < 1440) return `${Math.floor(mins/60)}h ago`;
    return d.toLocaleDateString('en-PK', { day: 'numeric', month: 'short' });
  };

  if (sessionStatus === 'loading') {
    return <AdminLayout><div className="flex items-center justify-center min-h-[60vh]"><Loader2 className="w-8 h-8 animate-spin text-[#029bba]" /></div></AdminLayout>;
  }

  const hotCount     = leads.filter(l => l.temperature === 'hot').length;
  const burningCount = leads.filter(l => l.temperature === 'burning').length;

  return (
    <AdminLayout>
      <Head><title>Aleem Leads | Highrise Admin</title></Head>

      <div className="p-6 space-y-6">

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#029bba] to-[#004063] flex items-center justify-center">
                <Bot className="w-5 h-5 text-white" />
              </div>
              Aleem Leads
            </h1>
            <p className="text-gray-500 mt-1">All leads captured by Aleem AI assistant</p>
          </div>
          <button
            onClick={() => fetchLeads(true)}
            disabled={refreshing}
            className="flex items-center gap-2 px-4 py-2.5 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 rounded-xl font-medium transition-colors"
          >
            <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>

        {/* Priority Alert */}
        {burningCount + hotCount > 0 && (
          <div className="bg-gradient-to-r from-[#ef4444] to-[#dc2626] text-white rounded-2xl p-5">
            <div className="flex items-center gap-3">
              <Flame className="w-8 h-8 animate-pulse" />
              <div>
                <h3 className="font-bold text-lg">{burningCount + hotCount} Priority Leads on This Page</h3>
                <p className="text-sm text-white/90">{burningCount} burning + {hotCount} hot — contact within 1 hour</p>
              </div>
            </div>
          </div>
        )}

        {/* Filters */}
        <div className="bg-white border border-gray-200 rounded-2xl p-4">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Search name, phone, email..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pl-10 pr-3 py-2.5 border border-gray-200 rounded-xl text-sm focus:outline-none focus:border-[#029bba]"
              />
            </div>

            {/* Temperature filter */}
            <select
              value={temperature}
              onChange={(e) => { setTemperature(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
              className="px-3 py-2.5 border border-gray-200 rounded-xl text-sm bg-white"
            >
              <option value="">All Temperatures</option>
              <option value="burning">🔥 Burning Only</option>
              <option value="hot">🔥 Hot Only</option>
              <option value="burning,hot">🔥 Burning + Hot</option>
              <option value="warm">🌡️ Warm Only</option>
              <option value="cold">❄️ Cold Only</option>
            </select>

            {/* Status filter */}
            <select
              value={status}
              onChange={(e) => { setStatus(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
              className="px-3 py-2.5 border border-gray-200 rounded-xl text-sm bg-white"
            >
              <option value="">All Statuses</option>
              <option value="new">🆕 New</option>
              <option value="contacted">📞 Contacted</option>
              <option value="qualified">✅ Qualified</option>
              <option value="won">🏆 Won</option>
              <option value="lost">❌ Lost</option>
            </select>
          </div>
        </div>

        {/* Error */}
        {error && (
          <div className="bg-[#fef2f2] border-l-4 border-[#ef4444] text-red-700 px-4 py-3 rounded-xl flex items-center gap-2">
            <AlertCircle className="w-5 h-5" />
            {error}
          </div>
        )}

        {/* Leads list */}
        <div className="bg-white border border-gray-200 rounded-2xl overflow-hidden">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-8 h-8 animate-spin text-[#029bba]" />
            </div>
          ) : leads.length === 0 ? (
            <div className="text-center py-12">
              <Users className="w-12 h-12 text-gray-300 mx-auto mb-3" />
              <p className="text-gray-500">No Aleem leads yet</p>
              <p className="text-xs text-gray-400 mt-1">Leads captured via chat will appear here</p>
            </div>
          ) : (
            <div className="divide-y divide-gray-100">
              {leads.map((lead) => {
                const temp = TEMPERATURE_CONFIG[lead.temperature] ?? TEMPERATURE_CONFIG.warm;
                return (
                  <div key={lead._id} className="p-4 hover:bg-gray-50 transition-colors">
                    <div className="flex items-start justify-between gap-4">
                      {/* Left: Info */}
                      <div className="flex items-start gap-3 flex-1 min-w-0">
                        {/* Avatar */}
                        <div className="w-12 h-12 rounded-full bg-gradient-to-br from-[#029bba] to-[#027a94] flex items-center justify-center text-white font-bold text-lg shrink-0">
                          {lead.name.charAt(0).toUpperCase()}
                        </div>

                        <div className="flex-1 min-w-0">
                          {/* Name + temperature */}
                          <div className="flex items-center gap-2 flex-wrap mb-1">
                            <p className="font-bold text-gray-900">{lead.name}</p>
                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${temp.bg} ${temp.text}`}>
                              {temp.icon} {temp.label}
                            </span>
                            <span
                              className="px-2 py-0.5 rounded-full text-[10px] font-bold text-white capitalize"
                              style={{ backgroundColor: STATUS_COLORS[lead.status] ?? '#6b7280' }}
                            >
                              {lead.status}
                            </span>
                          </div>

                          {/* Contact */}
                          <div className="flex items-center gap-3 text-sm text-gray-600 flex-wrap">
                            <a href={`tel:${lead.phone}`} className="flex items-center gap-1 hover:text-[#029bba]">
                              <Phone className="w-3.5 h-3.5" />
                              {lead.phone}
                            </a>
                            {lead.email && !lead.email.includes('@noemail.highrise.pk') && (
                              <a href={`mailto:${lead.email}`} className="flex items-center gap-1 hover:text-[#029bba]">
                                <Mail className="w-3.5 h-3.5" />
                                {lead.email}
                              </a>
                            )}
                          </div>

                          {/* Meta */}
                          <div className="flex items-center gap-3 mt-2 text-xs text-gray-500 flex-wrap">
                            <span className="flex items-center gap-1">
                              <Calendar className="w-3 h-3" />
                              {formatDate(lead.createdAt)}
                            </span>
                            <span>Score: <strong className="text-gray-700">{lead.leadScore}</strong></span>
                            {lead.budget?.tier && (
                              <span>Budget: <strong className="text-gray-700">{lead.budget.tier}</strong></span>
                            )}
                          </div>

                          {/* Message preview */}
                          {lead.message && (
                            <p className="text-sm text-gray-600 mt-2 line-clamp-2 italic">"{lead.message}"</p>
                          )}
                        </div>
                      </div>

                      {/* Right: Actions */}
                      <div className="flex flex-col gap-2 shrink-0">
                        {lead.conversationId && (
                          <Link href={`/admin/aleem/conversations?search=${lead.sessionId ?? ''}`}>
                            <button className="p-2 hover:bg-[#029bba]/10 text-[#029bba] rounded-lg transition-colors" title="View Chat">
                              <MessageCircle className="w-4 h-4" />
                            </button>
                          </Link>
                        )}
                        <a href={`tel:${lead.phone}`}>
                          <button className="p-2 hover:bg-[#10b981]/10 text-[#10b981] rounded-lg transition-colors" title="Call">
                            <Phone className="w-4 h-4" />
                          </button>
                        </a>
                        <a href={`https://wa.me/${lead.phone.replace(/\D/g, '')}`} target="_blank" rel="noopener noreferrer">
                          <button className="p-2 hover:bg-[#25D366]/10 text-[#25D366] rounded-lg transition-colors" title="WhatsApp">
                            <MessageCircle className="w-4 h-4" />
                          </button>
                        </a>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {/* Pagination */}
          {pagination.pages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200">
              <p className="text-sm text-gray-600">
                Page {pagination.page} of {pagination.pages} • {pagination.total} total
              </p>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setPagination(p => ({ ...p, page: p.page - 1 }))}
                  disabled={pagination.page === 1}
                  className="p-2 hover:bg-gray-100 rounded-lg disabled:opacity-50"
                >
                  <ChevronLeft className="w-5 h-5" />
                </button>
                <button
                  onClick={() => setPagination(p => ({ ...p, page: p.page + 1 }))}
                  disabled={pagination.page === pagination.pages}
                  className="p-2 hover:bg-gray-100 rounded-lg disabled:opacity-50"
                >
                  <ChevronRight className="w-5 h-5" />
                </button>
              </div>
            </div>
          )}
        </div>

      </div>
    </AdminLayout>
  );
}

// pages/admin/analytics/index.tsx

import { useState, useEffect } from 'react';
import AdminLayout from "@/components/admin/AdminLayout";
import AdminGuard from "@/components/AdminGuard";
import { Card } from "@/components/ui/card";
import { 
  Building2, 
  Users, 
  FileText, 
  Mail, 
  MessageSquare,
  TrendingUp,
  TrendingDown,
  Loader2,
  AlertCircle,
  Eye,
  MousePointerClick,
  RefreshCw,
  Building,
  UserCheck
} from "lucide-react";
import {
  LineChart,
  Line,
  AreaChart,
  Area,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer
} from 'recharts';

// Types
interface AnalyticsData {
  overview: {
    properties: {
      total: number;
      change: string;
      approved: number;
      pending: number;
      rejected: number;
      draft: number;
    };
    users: {
      total: number;
      change: string;
      active: number;
      pending: number;
      suspended: number;
      banned: number;
    };
    blogs: {
      total: number;
      change: string;
      published: number;
      draft: number;
      scheduled: number;
    };
    emails: {
      total: number;
      change: string;
      sent: number;
      failed: number;
      pending: number;
    };
    developers: {
      total: number;
      verified: number;
      pending: number;
    };
    inquiries: {
      total: number;
      new: number;
      contacted: number;
    };
    comments: {
      total: number;
      approved: number;
      pending: number;
    };
  };
  charts: {
    userGrowth: Array<{ date: string; users: number }>;
    propertyTrends: Array<{ date: string; properties: number }>;
    emailTrends: Array<{ date: string; emails: number }>;
    propertyStatus: Array<{ name: string; value: number; color: string }>;
    emailStatus: Array<{ name: string; value: number; color: string }>;
    userStatus: Array<{ name: string; value: number; color: string }>;
  };
  topProperties: Array<{
    _id: string;
    title: string;
    views: number;
    inquiries: number;
    status: string;
    city: string;
    propertyType: string;
  }>;
  topBlogs: Array<{
    _id: string;
    title: string;
    views: number;
    comments: number;
    slug: string;
  }>;
}

// Stat Card Component
function StatCard({ 
  title, 
  value, 
  change, 
  icon: Icon, 
  color,
  subtitle
}: { 
  title: string;
  value: number | string;
  change?: string;
  icon: any;
  color: string;
  subtitle?: string;
}) {
  const isPositive = change?.startsWith('+');
  const isNegative = change?.startsWith('-');
  
  const colorClasses: Record<string, string> = {
    blue: 'bg-blue-50 text-blue-600',
    green: 'bg-green-50 text-green-600',
    purple: 'bg-purple-50 text-purple-600',
    orange: 'bg-orange-50 text-orange-600',
    teal: 'bg-[#029bba]/10 text-[#029bba]',
    red: 'bg-red-50 text-red-600',
    yellow: 'bg-yellow-50 text-yellow-600',
  };

  return (
    <Card className="p-6 hover:shadow-lg transition-all duration-200 border border-gray-100">
      <div className="flex items-start justify-between mb-4">
        <div className={`p-3 rounded-xl ${colorClasses[color] || colorClasses.blue}`}>
          <Icon className="w-6 h-6" />
        </div>
        {change && (
          <div className={`flex items-center gap-1 text-sm font-medium px-2 py-1 rounded-full ${
            isPositive ? 'bg-green-50 text-green-600' : 
            isNegative ? 'bg-red-50 text-red-600' : 
            'bg-gray-50 text-gray-600'
          }`}>
            {isPositive ? <TrendingUp className="w-3 h-3" /> : 
             isNegative ? <TrendingDown className="w-3 h-3" /> : null}
            {change}
          </div>
        )}
      </div>
      <h3 className="text-3xl font-bold text-gray-900 mb-1">
        {typeof value === 'number' ? value.toLocaleString() : value}
      </h3>
      <p className="text-gray-500 text-sm">{title}</p>
      {subtitle && <p className="text-xs text-gray-400 mt-1">{subtitle}</p>}
    </Card>
  );
}

// Custom Tooltip for Charts
function CustomTooltip({ active, payload, label }: any) {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white p-3 rounded-lg shadow-lg border border-gray-100">
        <p className="text-sm font-medium text-gray-900">{label}</p>
        {payload.map((entry: any, index: number) => (
          <p key={index} className="text-sm" style={{ color: entry.color }}>
            {entry.name}: {entry.value}
          </p>
        ))}
      </div>
    );
  }
  return null;
}

// Status Badge Component
function StatusBadge({ status }: { status: string }) {
  const statusStyles: Record<string, string> = {
    approved: 'bg-green-100 text-green-800',
    active: 'bg-green-100 text-green-800',
    pending: 'bg-yellow-100 text-yellow-800',
    rejected: 'bg-red-100 text-red-800',
    draft: 'bg-gray-100 text-gray-800',
  };

  return (
    <span className={`px-2 py-1 text-xs font-medium rounded-full capitalize ${
      statusStyles[status] || 'bg-gray-100 text-gray-800'
    }`}>
      {status}
    </span>
  );
}

export default function AnalyticsPage() {
  const [data, setData] = useState<AnalyticsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [dateRange, setDateRange] = useState('30days');
  const [refreshing, setRefreshing] = useState(false);

  // Fetch analytics data
  const fetchAnalytics = async (showRefresh = false) => {
    try {
      if (showRefresh) setRefreshing(true);
      else setLoading(true);
      
      const response = await fetch(`/api/admin/analytics?range=${dateRange}`);
      const result = await response.json();
      
      if (result.success) {
        setData(result.data);
        setError(null);
      } else {
        setError(result.message || 'Failed to fetch analytics');
      }
    } catch (err) {
      setError('Failed to connect to server');
      console.error('Analytics fetch error:', err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchAnalytics();
  }, [dateRange]);

  // Loading State
  if (loading) {
    return (
      <AdminGuard>
        <AdminLayout>
          <div className="p-6 flex items-center justify-center min-h-[60vh]">
            <div className="text-center">
              <Loader2 className="w-12 h-12 animate-spin text-[#029bba] mx-auto mb-4" />
              <p className="text-gray-500">Loading analytics data...</p>
            </div>
          </div>
        </AdminLayout>
      </AdminGuard>
    );
  }

  // Error State
  if (error) {
    return (
      <AdminGuard>
        <AdminLayout>
          <div className="p-6 flex items-center justify-center min-h-[60vh]">
            <Card className="p-8 text-center max-w-md">
              <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-gray-900 mb-2">Failed to Load Analytics</h3>
              <p className="text-gray-500 mb-4">{error}</p>
              <button
                onClick={() => fetchAnalytics()}
                className="px-4 py-2 bg-[#029bba] text-white rounded-xl hover:bg-[#027a94] transition-colors"
              >
                Try Again
              </button>
            </Card>
          </div>
        </AdminLayout>
      </AdminGuard>
    );
  }

  if (!data) return null;

  return (
    <AdminGuard>
      <AdminLayout>
        <div className="p-6 space-y-6">
          {/* Header */}
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Analytics Dashboard</h1>
              <p className="text-gray-500 mt-1">Track your platform performance and insights</p>
            </div>
            <div className="flex items-center gap-3">
              <button
                onClick={() => fetchAnalytics(true)}
                disabled={refreshing}
                className="p-2 text-gray-500 hover:text-[#029bba] hover:bg-gray-100 rounded-lg transition-colors"
                title="Refresh data"
              >
                <RefreshCw className={`w-5 h-5 ${refreshing ? 'animate-spin' : ''}`} />
              </button>
              <select
                value={dateRange}
                onChange={(e) => setDateRange(e.target.value)}
                className="px-4 py-2 border border-gray-200 rounded-xl text-sm focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none"
              >
                <option value="7days">Last 7 days</option>
                <option value="30days">Last 30 days</option>
                <option value="90days">Last 90 days</option>
                <option value="1year">Last year</option>
              </select>
            </div>
          </div>

          {/* Overview Stats */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4">
            <StatCard
              title="Total Properties"
              value={data.overview.properties.total}
              change={data.overview.properties.change}
              icon={Building2}
              color="teal"
              subtitle={`${data.overview.properties.pending} pending approval`}
            />
            <StatCard
              title="Total Users"
              value={data.overview.users.total}
              change={data.overview.users.change}
              icon={Users}
              color="blue"
              subtitle={`${data.overview.users.active} active`}
            />
            <StatCard
              title="Blog Posts"
              value={data.overview.blogs.total}
              change={data.overview.blogs.change}
              icon={FileText}
              color="purple"
              subtitle={`${data.overview.blogs.published} published`}
            />
            <StatCard
              title="Emails Sent"
              value={data.overview.emails.sent}
              change={data.overview.emails.change}
              icon={Mail}
              color="green"
              subtitle={`${data.overview.emails.failed} failed`}
            />
            <StatCard
              title="Developers"
              value={data.overview.developers.total}
              icon={Building}
              color="orange"
              subtitle={`${data.overview.developers.verified} verified`}
            />
          </div>

          {/* Secondary Stats */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <Card className="p-4 flex items-center gap-4">
              <div className="p-3 rounded-xl bg-yellow-50">
                <MousePointerClick className="w-5 h-5 text-yellow-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900">{data.overview.inquiries.total}</p>
                <p className="text-sm text-gray-500">Total Inquiries</p>
              </div>
            </Card>
            <Card className="p-4 flex items-center gap-4">
              <div className="p-3 rounded-xl bg-green-50">
                <UserCheck className="w-5 h-5 text-green-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900">{data.overview.inquiries.new}</p>
                <p className="text-sm text-gray-500">New Inquiries</p>
              </div>
            </Card>
            <Card className="p-4 flex items-center gap-4">
              <div className="p-3 rounded-xl bg-blue-50">
                <MessageSquare className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900">{data.overview.comments.total}</p>
                <p className="text-sm text-gray-500">Total Comments</p>
              </div>
            </Card>
            <Card className="p-4 flex items-center gap-4">
              <div className="p-3 rounded-xl bg-orange-50">
                <AlertCircle className="w-5 h-5 text-orange-600" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900">{data.overview.comments.pending}</p>
                <p className="text-sm text-gray-500">Pending Comments</p>
              </div>
            </Card>
          </div>

          {/* Charts Row 1 */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* User Growth Chart */}
            <Card className="p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">User Growth</h2>
              <div className="h-72">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={data.charts.userGrowth}>
                    <defs>
                      <linearGradient id="colorUsers" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#029bba" stopOpacity={0.3}/>
                        <stop offset="95%" stopColor="#029bba" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis 
                      dataKey="date" 
                      tick={{ fontSize: 12 }} 
                      tickLine={false}
                      axisLine={{ stroke: '#e5e7eb' }}
                    />
                    <YAxis 
                      tick={{ fontSize: 12 }} 
                      tickLine={false}
                      axisLine={{ stroke: '#e5e7eb' }}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    <Area 
                      type="monotone" 
                      dataKey="users" 
                      stroke="#029bba" 
                      strokeWidth={2}
                      fillOpacity={1} 
                      fill="url(#colorUsers)" 
                      name="New Users"
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </Card>

            {/* Property Trends Chart */}
            <Card className="p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Property Submissions</h2>
              <div className="h-72">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={data.charts.propertyTrends}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis 
                      dataKey="date" 
                      tick={{ fontSize: 12 }} 
                      tickLine={false}
                      axisLine={{ stroke: '#e5e7eb' }}
                    />
                    <YAxis 
                      tick={{ fontSize: 12 }} 
                      tickLine={false}
                      axisLine={{ stroke: '#e5e7eb' }}
                    />
                    <Tooltip content={<CustomTooltip />} />
                    <Bar 
                      dataKey="properties" 
                      fill="#029bba" 
                      radius={[4, 4, 0, 0]}
                      name="Properties"
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </Card>
          </div>

          {/* Charts Row 2 - Pie Charts */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {/* Property Status Chart */}
            <Card className="p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">Properties by Status</h2>
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={data.charts.propertyStatus}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={90}
                      paddingAngle={2}
                      dataKey="value"
                    >
                      {data.charts.propertyStatus.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
