          </div>
        </div>
      </AdminLayout>
    </AdminGuard>
  );
}

// pages/admin/applications/index.tsx
// 🔒 ADMIN APPLICATIONS LIST UI - HIGHRISE.PK
// V5.9.0 — Combined inbox for agent + developer applications
// fetch() only | lucide-react | native Tailwind | no framer-motion
// ═══════════════════════════════════════════════════════════════

import { useState, useEffect, useCallback } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import {
  Search,
  Loader2,
  Users,
  Building2,
  CheckCircle,
  XCircle,
  AlertCircle,
  Clock,
  ChevronLeft,
  ChevronRight,
  ArrowUpDown,
  RefreshCw,
  Eye,
  Filter,
  MapPin,
} from 'lucide-react';
import { useRouter } from 'next/router';
import AdminLayout from '@/components/admin/AdminLayout';

// ─── Types ─────────────────────────────────────────────────────

type AppType = 'agent' | 'developer' | 'society' | 'all';
type AppStatus =
  | 'pending'
  | 'approved'
  | 'rejected'
  | 'info_required'
  | 'suspended'
  | 'all';

interface ApplicationListItem {
  _id: string;
  type: 'agent' | 'developer' | 'society';
  displayName: string;
  agencyOrCompany: string;
  city: string;
  email: string;
  status: AppStatus;
  submittedAt: string | null;
  createdAt: string;
  agentType?: string;
  developerType?: string;
  authority?: string;
  nocNumber?: string;
}

interface Counts {
  all: number;
  pending: number;
  approved: number;
  rejected: number;
  info_required: number;
  agents: number;
  developers: number;
  societies: number;
}

interface ApiResponse {
  success: boolean;
  applications?: ApplicationListItem[];
  counts?: Counts;
  pagination?: {
    page: number;
    totalPages: number;
    total: number;
    limit: number;
  };
  message?: string;
}

// ─── Helpers ───────────────────────────────────────────────────

function cx(...classes: Array<string | false | null | undefined>): string {
  return classes.filter(Boolean).join(' ');
}

function timeAgo(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const minutes = Math.floor(diff / 60000);
  if (minutes < 1) return 'just now';
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `${days}d ago`;
  const months = Math.floor(days / 30);
  return `${months}mo ago`;
}

function statusBadge(status: AppStatus): { label: string; classes: string; Icon: typeof CheckCircle } {
  switch (status) {
    case 'approved':
      return {
        label: 'Approved',
        classes: 'bg-green-50 text-green-700 border-green-200',
        Icon: CheckCircle,
      };
    case 'rejected':
      return {
        label: 'Rejected',
        classes: 'bg-red-50 text-red-700 border-red-200',
        Icon: XCircle,
      };
    case 'info_required':
      return {
        label: 'Info Required',
        classes: 'bg-amber-50 text-amber-700 border-amber-200',
        Icon: AlertCircle,
      };
    case 'suspended':
      return {
        label: 'Suspended',
        classes: 'bg-gray-100 text-gray-700 border-gray-300',
        Icon: XCircle,
      };
    default:
      return {
        label: 'Pending',
        classes: 'bg-blue-50 text-blue-700 border-blue-200',
        Icon: Clock,
      };
  }
}

// ─── Component ─────────────────────────────────────────────────

export default function AdminApplicationsPage() {
  const router = useRouter();
  const [applications, setApplications] = useState<ApplicationListItem[]>([]);
  const [counts, setCounts] = useState<Counts | null>(null);
  const [pagination, setPagination] = useState({
    page: 1,
    totalPages: 1,
    total: 0,
    limit: 20,
  });

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Filters
  const [typeFilter, setTypeFilter] = useState<AppType>('all');
  const [statusFilter, setStatusFilter] = useState<AppStatus>('pending');
  const [searchInput, setSearchInput] = useState('');
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState<'newest' | 'oldest'>('newest');
  const [page, setPage] = useState(1);

  // ── Hydrate filters from URL query (for deep links from navbar) ──
  useEffect(() => {
    if (!router.isReady) return;
    const qType = router.query.type;
    const qStatus = router.query.status;

    if (
      typeof qType === 'string' &&
      ['all', 'agent', 'developer', 'society'].includes(qType)
    ) {
      setTypeFilter(qType as AppType);
    }
    if (
      typeof qStatus === 'string' &&
      [
        'all',
        'pending',
        'approved',
        'rejected',
        'info_required',
        'suspended',
      ].includes(qStatus)
    ) {
      setStatusFilter(qStatus as AppStatus);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [router.isReady, router.query.type, router.query.status]);

  // ── Fetch data ──
  const fetchData = useCallback(
    async (isRefresh = false) => {
      if (isRefresh) {
        setRefreshing(true);
      } else {
        setLoading(true);
      }
      setError(null);

      try {
        const params = new URLSearchParams({
          page: String(page),
          limit: '20',
          type: typeFilter,
          status: statusFilter,
          sort,
        });

        if (search) params.set('search', search);

        const res = await fetch(`/api/admin/applications?${params.toString()}`);
        const data = (await res.json()) as ApiResponse;

        if (!res.ok || !data.success) {
          throw new Error(data.message ?? 'Failed to load applications');
        }

        setApplications(data.applications ?? []);
        setCounts(data.counts ?? null);
        if (data.pagination) setPagination(data.pagination);
      } catch (err: unknown) {
        setError(
          err instanceof Error ? err.message : 'Failed to load applications'
        );
      } finally {
        setLoading(false);
        setRefreshing(false);
      }
    },
    [page, typeFilter, statusFilter, search, sort]
  );

  // Initial + filter changes
  useEffect(() => {
    void fetchData();
  }, [fetchData]);

  // Reset page when filters change
  useEffect(() => {
    setPage(1);
  }, [typeFilter, statusFilter, search, sort]);

  // ── Search submit ──
  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSearch(searchInput.trim());
  };

  const handleClearSearch = () => {
    setSearchInput('');
    setSearch('');
  };

  // ── Render ──
  return (
    <AdminLayout>
      <Head>
        <title>Applications | Admin | Highrise.pk</title>
      </Head>

      <div className="space-y-6">
        {/* Page Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">
              Applications Inbox
            </h1>
            <p className="text-gray-600 text-sm mt-1">
              Review agent, developer &amp; society onboarding applications
            </p>
          </div>

          <button
            type="button"
            onClick={() => fetchData(true)}
            disabled={refreshing || loading}
            className="inline-flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-xl text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50 transition-colors"
          >
            <RefreshCw
              className={cx('w-4 h-4', refreshing && 'animate-spin')}
            />
            Refresh
          </button>
        </div>

        {/* Stats Cards */}
        {counts && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <button
              type="button"
              onClick={() => setStatusFilter('pending')}
              className={cx(
                'p-4 rounded-xl border text-left transition-all',
                statusFilter === 'pending'
                  ? 'bg-blue-50 border-blue-300 ring-2 ring-blue-200'
                  : 'bg-white border-gray-200 hover:border-gray-300'
              )}
            >
              <div className="flex items-center gap-2 mb-1">
                <Clock className="w-4 h-4 text-blue-600" />
                <span className="text-xs font-semibold text-gray-600 uppercase tracking-wide">
                  Pending
                </span>
              </div>
              <p className="text-2xl font-bold text-gray-900">{counts.pending}</p>
            </button>

            <button
              type="button"
              onClick={() => setStatusFilter('info_required')}
              className={cx(
                'p-4 rounded-xl border text-left transition-all',
                statusFilter === 'info_required'
                  ? 'bg-amber-50 border-amber-300 ring-2 ring-amber-200'
                  : 'bg-white border-gray-200 hover:border-gray-300'
              )}
            >
              <div className="flex items-center gap-2 mb-1">
                <AlertCircle className="w-4 h-4 text-amber-600" />
                <span className="text-xs font-semibold text-gray-600 uppercase tracking-wide">
                  Info Req
                </span>
              </div>
              <p className="text-2xl font-bold text-gray-900">
                {counts.info_required}
              </p>
            </button>

            <button
              type="button"
              onClick={() => setStatusFilter('approved')}
              className={cx(
                'p-4 rounded-xl border text-left transition-all',
                statusFilter === 'approved'
                  ? 'bg-green-50 border-green-300 ring-2 ring-green-200'
                  : 'bg-white border-gray-200 hover:border-gray-300'
              )}
            >
              <div className="flex items-center gap-2 mb-1">
                <CheckCircle className="w-4 h-4 text-green-600" />
                <span className="text-xs font-semibold text-gray-600 uppercase tracking-wide">
                  Approved
                </span>
              </div>
              <p className="text-2xl font-bold text-gray-900">{counts.approved}</p>
            </button>

            <button
              type="button"
              onClick={() => setStatusFilter('rejected')}
              className={cx(
                'p-4 rounded-xl border text-left transition-all',
                statusFilter === 'rejected'
                  ? 'bg-red-50 border-red-300 ring-2 ring-red-200'
                  : 'bg-white border-gray-200 hover:border-gray-300'
              )}
            >
              <div className="flex items-center gap-2 mb-1">
                <XCircle className="w-4 h-4 text-red-600" />
                <span className="text-xs font-semibold text-gray-600 uppercase tracking-wide">
                  Rejected
                </span>
              </div>
              <p className="text-2xl font-bold text-gray-900">{counts.rejected}</p>
            </button>
          </div>
        )}

        {/* Type Filter Tabs */}
        <div className="bg-white border border-gray-200 rounded-xl p-2 inline-flex gap-1 flex-wrap">
          {(
            [
              { value: 'all', label: 'All', icon: Filter, count: counts?.all },
              { value: 'agent', label: 'Agents', icon: Users, count: counts?.agents },
              {
                value: 'developer',
                label: 'Developers',
                icon: Building2,
                count: counts?.developers,
              },
              {
                value: 'society',
                label: 'Societies',
                icon: MapPin,
                count: counts?.societies,
              },
            ] as const
          ).map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.value}
                type="button"
                onClick={() => setTypeFilter(tab.value)}
                className={cx(
                  'flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all',
                  typeFilter === tab.value
                    ? 'bg-[#029bba] text-white'
                    : 'text-gray-600 hover:bg-gray-100'
                )}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
                {tab.count !== undefined && tab.count !== null && (
                  <span
                    className={cx(
                      'text-xs px-1.5 py-0.5 rounded-full',
                      typeFilter === tab.value
                        ? 'bg-white/20 text-white'
                        : 'bg-gray-200 text-gray-700'
                    )}
                  >
                    {tab.count}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        {/* Search + Sort Row */}
        <div className="flex flex-col sm:flex-row gap-3">
          <form
            onSubmit={handleSearchSubmit}
            className="flex-1 flex gap-2"
          >
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="Search by name, company, email, city..."
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-[#029bba]/20 focus:border-[#029bba] outline-none transition-all"
              />
              {search && (
                <button
                  type="button"
                  onClick={handleClearSearch}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                >
                  <XCircle className="w-4 h-4" />
                </button>
              )}
            </div>
            <button
              type="submit"
              className="px-4 py-2.5 bg-[#029bba] hover:bg-[#027a94] text-white rounded-xl text-sm font-medium transition-colors"
            >
              Search
            </button>
          </form>

          <button
            type="button"
            onClick={() => setSort(sort === 'newest' ? 'oldest' : 'newest')}
            className="inline-flex items-center justify-center gap-2 px-4 py-2.5 bg-white border border-gray-200 rounded-xl text-sm font-medium text-gray-700 hover:bg-gray-50 transition-colors"
          >
            <ArrowUpDown className="w-4 h-4" />
            {sort === 'newest' ? 'Newest first' : 'Oldest first'}
          </button>
        </div>

        {/* Error banner */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-400 p-4 rounded-r-xl">
            <p className="text-sm text-red-800">{error}</p>
          </div>
        )}

        {/* Applications Table */}
        <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
          {loading ? (
            <div className="p-12 text-center">
              <Loader2 className="w-8 h-8 text-[#029bba] animate-spin mx-auto mb-3" />
              <p className="text-sm text-gray-500">Loading applications...</p>
            </div>
          ) : applications.length === 0 ? (
            <div className="p-12 text-center">
              <Filter className="w-12 h-12 text-gray-300 mx-auto mb-3" />
              <p className="text-sm text-gray-600 font-medium">
                No applications found
              </p>
              <p className="text-xs text-gray-400 mt-1">
                Try adjusting your filters or search query
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 text-xs uppercase text-gray-500 font-semibold border-b border-gray-200">
                  <tr>
                    <th className="px-6 py-4">Type</th>
                    <th className="px-6 py-4">Company / Agent</th>
                    <th className="px-6 py-4">City</th>
                    <th className="px-6 py-4">Email</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4">Submitted</th>
                    <th className="px-6 py-4 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {applications.map((app) => {
                    const badge = statusBadge(app.status);
                    const BadgeIcon = badge.Icon;
                    // Type badge colors — society is purple per design system
                    const typeBadgeClasses =
                      app.type === 'society'
                        ? 'bg-purple-50 text-purple-700 border-purple-200'
                        : app.type === 'developer'
                        ? 'bg-cyan-50 text-cyan-700 border-cyan-200'
                        : 'bg-blue-50 text-blue-700 border-blue-200';

                    const TypeIcon =
                      app.type === 'society'
                        ? MapPin
                        : app.type === 'developer'
                        ? Building2
                        : Users;

                    const typeLabel =
                      app.type === 'society'
                        ? 'Society'
                        : app.type === 'developer'
                        ? 'Developer'
                        : 'Agent';

                    return (
                      <tr
                        key={`${app.type}-${app._id}`}
                        className="hover:bg-gray-50 transition-colors"
                      >
                        <td className="px-6 py-4">
                          <div
                            className={cx(
                              'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-medium border',
                              typeBadgeClasses
                            )}
                          >
                            <TypeIcon className="w-3.5 h-3.5" />
                            {typeLabel}
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="font-medium text-gray-900">
                            {app.agencyOrCompany}
                          </div>
                          {app.type === 'agent' && app.agentType && (
                            <div className="text-xs text-gray-500 mt-0.5 capitalize">
                              {app.agentType}
                            </div>
                          )}
                          {app.type === 'developer' && app.developerType && (
                            <div className="text-xs text-gray-500 mt-0.5 capitalize">
                              {app.developerType}
                            </div>
                          )}
                          {app.type === 'society' && (app.authority || app.nocNumber) && (
                            <div className="text-xs text-gray-500 mt-0.5">
                              {app.authority && (
                                <span className="font-medium">{app.authority}</span>
                              )}
                              {app.authority && app.nocNumber && (
                                <span className="mx-1">·</span>
                              )}
                              {app.nocNumber && (
                                <span className="font-mono">NOC: {app.nocNumber}</span>
                              )}
                            </div>
                          )}
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600">
                          {app.city}
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600 truncate max-w-xs">
                          {app.email}
                        </td>
                        <td className="px-6 py-4">
                          <span
                            className={cx(
                              'inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium border',
                              badge.classes
                            )}
                          >
                            <BadgeIcon className="w-3 h-3" />
                            {badge.label}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-500">
                          {timeAgo(app.submittedAt ?? app.createdAt)}
                        </td>
                        <td className="px-6 py-4 text-right">
                          <Link
                            href={`/admin/applications/${app._id}?type=${app.type}`}
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-[#029bba] hover:bg-[#027a94] text-white text-xs font-medium rounded-lg transition-colors"
                          >
                            <Eye className="w-3.5 h-3.5" />
                            Review
                          </Link>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Pagination */}
        {pagination.totalPages > 1 && (
          <div className="flex items-center justify-between bg-white border border-gray-200 rounded-xl px-4 py-3">
            <p className="text-sm text-gray-600">
              Page <strong>{pagination.page}</strong> of{' '}
              <strong>{pagination.totalPages}</strong> ({pagination.total} total)
            </p>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={pagination.page <= 1}
                className="inline-flex items-center gap-1 px-3 py-1.5 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft className="w-4 h-4" />
                Previous
              </button>
              <button
                type="button"
                onClick={() =>
                  setPage((p) => Math.min(pagination.totalPages, p + 1))
                }
                disabled={pagination.page >= pagination.totalPages}
                className="inline-flex items-center gap-1 px-3 py-1.5 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                Next
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>
    </AdminLayout>
  );
}

// pages/admin/automation/index.tsx
// ═══════════════════════════════════════════════════════════════
// AUTOMATION DASHBOARD — HIGHRISE.PK
// List all sequences with stats, status controls, quick actions
// ═══════════════════════════════════════════════════════════════

import React, { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import AdminLayout from '@/components/admin/AdminLayout';
import {
  Plus,
  Zap,
  Play,
  Pause,
  Archive,
  Edit,
  Users,
  Mail,
  CheckCircle,
  Clock,
  XCircle,
  AlertCircle,
  Loader2,
  RefreshCw,
  X,
  BarChart2,
  ChevronRight,
  Inbox,
} from 'lucide-react';

// ─── Types ────────────────────────────────────────────────────

type SequenceStatus = 'draft' | 'active' | 'paused' | 'archived';

interface SequenceStats {
  totalEnrolled:  number;
  activeCount:    number;
  completedCount: number;
  cancelledCount: number;
  failedCount:    number;
  emailsSent:     number;
}

interface Sequence {
  _id:           string;
  name:          string;
  description:   string;
  status:        SequenceStatus;
  trigger:       string;
  recipientType: string;
  steps:         { stepNumber: number; subject: string; delayDays: number }[];
  stats:         SequenceStats;
  createdAt:     string;
  updatedAt:     string;
}

interface DashboardStats {
  total:                 number;
  draft:                 number;
  active:                number;
  paused:                number;
  archived:              number;
  totalActiveEnrollments: number;
}

interface Banner {
  type:    'success' | 'error' | 'info';
  message: string;
}

// ─── Helpers ──────────────────────────────────────────────────

function triggerLabel(trigger: string): string {
  const labels: Record<string, string> = {
    subscriber_joined:    'New Subscriber',
    lead_created:         'New Lead',
    lead_status_changed:  'Lead Status Changed',
    manual:               'Manual Only',
  };
  return labels[trigger] || trigger;
}

function triggerColor(trigger: string): string {
  const colors: Record<string, string> = {
    subscriber_joined:   'bg-blue-100 text-blue-700',
    lead_created:        'bg-amber-100 text-amber-700',
    lead_status_changed: 'bg-purple-100 text-purple-700',
    manual:              'bg-gray-100 text-gray-600',
  };
  return colors[trigger] || 'bg-gray-100 text-gray-600';
}

function statusConfig(status: SequenceStatus): {
  label: string;
  bg:    string;
  text:  string;
  Icon:  React.ComponentType<{ className?: string }>;
} {
  switch (status) {
    case 'active':
      return { label: 'Active',   bg: 'bg-emerald-100', text: 'text-emerald-700', Icon: Play      };
    case 'paused':
      return { label: 'Paused',   bg: 'bg-amber-100',   text: 'text-amber-700',   Icon: Pause     };
    case 'draft':
      return { label: 'Draft',    bg: 'bg-gray-100',    text: 'text-gray-600',    Icon: Clock     };
    case 'archived':
      return { label: 'Archived', bg: 'bg-red-100',     text: 'text-red-600',     Icon: Archive   };
    default:
      return { label: status,     bg: 'bg-gray-100',    text: 'text-gray-600',    Icon: Clock     };
  }
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-PK', {
    day:   'numeric',
    month: 'short',
    year:  'numeric',
  });
}

// ─── Confirm Modal ────────────────────────────────────────────

const ConfirmModal: React.FC<{
  isOpen:      boolean;
  title:       string;
  message:     string;
  confirmText: string;
  variant:     'danger' | 'warning' | 'info';
  isLoading:   boolean;
  onConfirm:   () => void;
  onClose:     () => void;
}> = ({ isOpen, title, message, confirmText, variant, isLoading, onConfirm, onClose }) => {
  useEffect(() => {
    if (isOpen) document.body.style.overflow = 'hidden';
    else        document.body.style.overflow = '';
    return () => { document.body.style.overflow = ''; };
  }, [isOpen]);

  if (!isOpen) return null;

  const variantBg = {
    danger:  'bg-red-500 hover:bg-red-600',
    warning: 'bg-amber-500 hover:bg-amber-600',
    info:    'bg-[#029bba] hover:bg-[#027a94]',
  }[variant];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-2xl max-w-md w-full p-6">
        <h3 className="text-lg font-black text-[#004063] mb-2">{title}</h3>
        <p className="text-sm text-gray-600 mb-6 whitespace-pre-line">{message}</p>
        <div className="flex gap-3">
          <button
            type="button"
            onClick={onClose}
            disabled={isLoading}
            className="flex-1 px-4 py-2.5 rounded-xl border border-gray-300
                       text-gray-700 font-semibold hover:bg-gray-50
                       transition-colors disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={onConfirm}
            disabled={isLoading}
            className={`flex-1 px-4 py-2.5 rounded-xl text-white font-bold
                        transition-colors disabled:opacity-50 flex items-center
                        justify-center gap-2 ${variantBg}`}
          >
            {isLoading
              ? <Loader2 className="w-4 h-4 animate-spin" />
              : confirmText
            }
          </button>
        </div>
      </div>
    </div>
  );
};

// ─── Sequence Card ────────────────────────────────────────────

const SequenceCard: React.FC<{
  sequence:         Sequence;
  actionLoading:    string | null;
  onStatusChange:   (id: string, newStatus: string) => void;
  onArchive:        (seq: Sequence) => void;
}> = ({ sequence, actionLoading, onStatusChange, onArchive }) => {
  const cfg       = statusConfig(sequence.status);
  const StatusIcon = cfg.Icon;
  const isLoading  = actionLoading === sequence._id;

  return (
    <div className="bg-white rounded-2xl border border-gray-200 p-5
                    hover:shadow-md transition-shadow">

      {/* ── Header ──────────────────────────────────────────── */}
      <div className="flex items-start justify-between gap-3 mb-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap mb-1">
            <h3 className="text-base font-black text-[#004063] truncate">
              {sequence.name}
            </h3>
            {/* Status badge */}
            <span className={`inline-flex items-center gap-1 px-2 py-0.5 
                              rounded-full text-xs font-bold
                              ${cfg.bg} ${cfg.text}`}>
              <StatusIcon className="w-3 h-3" />
              {cfg.label}
            </span>
            {/* Trigger badge */}
            <span className={`px-2 py-0.5 rounded-full text-xs font-semibold
                              ${triggerColor(sequence.trigger)}`}>
              {triggerLabel(sequence.trigger)}
            </span>
          </div>
          {sequence.description && (
            <p className="text-sm text-gray-500 line-clamp-1">
              {sequence.description}
            </p>
          )}
        </div>

        {/* Actions */}
        <div className="flex items-center gap-1 flex-shrink-0">
          {/* Edit */}
          {sequence.status !== 'archived' && (
            <Link
              href={`/admin/automation/${sequence._id}/edit`}
              className="p-2 text-gray-400 hover:text-[#029bba]
                         hover:bg-[#029bba]/10 rounded-lg transition-all"
              title="Edit sequence"
            >
              <Edit className="w-4 h-4" />
            </Link>
          )}

          {/* Pause / Resume */}
          {sequence.status === 'active' && (
            <button
              type="button"
              onClick={() => onStatusChange(sequence._id, 'paused')}
              disabled={isLoading}
              className="p-2 text-gray-400 hover:text-amber-600
                         hover:bg-amber-50 rounded-lg transition-all
                         disabled:opacity-50"
              title="Pause sequence"
            >
              {isLoading
                ? <Loader2 className="w-4 h-4 animate-spin" />
                : <Pause className="w-4 h-4" />
              }
            </button>
          )}

          {sequence.status === 'paused' && (
            <button
              type="button"
              onClick={() => onStatusChange(sequence._id, 'active')}
              disabled={isLoading}
              className="p-2 text-gray-400 hover:text-emerald-600
                         hover:bg-emerald-50 rounded-lg transition-all
                         disabled:opacity-50"
              title="Resume sequence"
            >
              {isLoading
                ? <Loader2 className="w-4 h-4 animate-spin" />
                : <Play className="w-4 h-4" />
              }
            </button>
          )}

          {sequence.status === 'draft' && (
            <button
              type="button"
              onClick={() => onStatusChange(sequence._id, 'active')}
              disabled={isLoading || sequence.steps.length === 0}
              className="p-2 text-gray-400 hover:text-emerald-600
                         hover:bg-emerald-50 rounded-lg transition-all
                         disabled:opacity-50 disabled:cursor-not-allowed"
              title={
                sequence.steps.length === 0
                  ? 'Add steps before activating'
                  : 'Activate sequence'
              }
            >
              {isLoading
                ? <Loader2 className="w-4 h-4 animate-spin" />
                : <Play className="w-4 h-4" />
              }
            </button>
          )}

          {/* Archive */}
          {sequence.status !== 'archived' && (
            <button
              type="button"
              onClick={() => onArchive(sequence)}
              disabled={isLoading}
              className="p-2 text-gray-400 hover:text-red-500
                         hover:bg-red-50 rounded-lg transition-all
                         disabled:opacity-50"
              title="Archive sequence"
            >
              <Archive className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* ── Steps summary ────────────────────────────────────── */}
      <div className="flex items-center gap-2 mb-4 overflow-x-auto pb-1">
        {sequence.steps.length === 0 ? (
          <p className="text-xs text-gray-400 italic">No steps yet — edit to add steps</p>
        ) : (
          sequence.steps.slice(0, 5).map((step, idx) => (
            <React.Fragment key={step.stepNumber}>
              <div className="flex-shrink-0 bg-gray-50 border border-gray-200
                              rounded-xl px-3 py-1.5 text-center min-w-max">
                <p className="text-[10px] text-gray-400 font-semibold uppercase tracking-wider">
                  Step {step.stepNumber}
                </p>
                <p className="text-xs font-bold text-gray-700 max-w-[100px] truncate">
                  {step.subject || 'No subject'}
                </p>
                <p className="text-[10px] text-gray-400">
                  {step.delayDays === 0 ? 'Immediate' : `Day ${step.delayDays}`}
                </p>
              </div>
              {idx < sequence.steps.slice(0, 5).length - 1 && (
                <ChevronRight className="w-3 h-3 text-gray-300 flex-shrink-0" />
              )}
            </React.Fragment>
          ))
        )}
        {sequence.steps.length > 5 && (
          <span className="text-xs text-gray-400 flex-shrink-0">
            +{sequence.steps.length - 5} more
          </span>
        )}
      </div>

      {/* ── Stats row ────────────────────────────────────────── */}
      <div className="grid grid-cols-3 gap-3 pt-3 border-t border-gray-100">
        {[
          {
            label:  'Enrolled',
            value:  sequence.stats.totalEnrolled,
            Icon:   Users,
            color:  'text-[#029bba]',
          },
          {
            label:  'Active',
            value:  sequence.stats.activeCount,
            Icon:   Zap,
            color:  'text-amber-500',
          },
          {
            label:  'Completed',
            value:  sequence.stats.completedCount,
            Icon:   CheckCircle,
            color:  'text-emerald-500',
          },
        ].map((stat) => (
          <div key={stat.label} className="text-center">
            <div className="flex items-center justify-center gap-1 mb-0.5">
              <stat.Icon className={`w-3.5 h-3.5 ${stat.color}`} />
              <span className={`text-base font-black ${stat.color}`}>
                {stat.value.toLocaleString()}
              </span>
            </div>
            <p className="text-[10px] text-gray-400 font-semibold uppercase tracking-wider">
              {stat.label}
            </p>
          </div>
        ))}
      </div>

      {/* ── Footer ───────────────────────────────────────────── */}
      <div className="flex items-center justify-between mt-3 pt-3 border-t border-gray-100">
        <div className="flex items-center gap-3 text-xs text-gray-400">
          <span className="flex items-center gap-1">
            <Mail className="w-3 h-3" />
            {sequence.stats.emailsSent.toLocaleString()} sent
          </span>
          <span>·</span>
          <span>{sequence.steps.length} step{sequence.steps.length !== 1 ? 's' : ''}</span>
          <span>·</span>
          <span>{formatDate(sequence.createdAt)}</span>
        </div>
        <Link
          href={`/admin/automation/${sequence._id}/edit`}
          className="text-xs font-semibold text-[#029bba] hover:underline
                     flex items-center gap-1"
        >
          View Details
          <ChevronRight className="w-3 h-3" />
        </Link>
      </div>
    </div>
  );
};

// ─── Main Page ────────────────────────────────────────────────

export default function AutomationIndexPage() {
  const router  = useRouter();
  const { data: session, status: sessionStatus } = useSession();

  const [sequences,     setSequences]     = useState<Sequence[]>([]);
  const [stats,         setStats]         = useState<DashboardStats>({
    total: 0, draft: 0, active: 0, paused: 0,
    archived: 0, totalActiveEnrollments: 0,
  });
  const [loading,       setLoading]       = useState(true);
  const [filter,        setFilter]        = useState<string>('all');
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [banner,        setBanner]        = useState<Banner | null>(null);
  const [isProcessing,  setIsProcessing]  = useState(false);

  // Archive confirm modal
  const [archiveModal, setArchiveModal] = useState<{
    open: boolean;
    sequence: Sequence | null;
  }>({ open: false, sequence: null });

  // ── Auth guard ────────────────────────────────────────────
  useEffect(() => {
    if (sessionStatus === 'loading') return;
    if (!session) {
      router.replace(`/login?redirect=${encodeURIComponent('/admin/automation')}`);
      return;
    }
    if ((session.user as any)?.role !== 'admin') {
      router.replace('/');
    }
  }, [session, sessionStatus, router]);

  // ── Banner auto-dismiss ───────────────────────────────────
  useEffect(() => {
    if (!banner) return;
    const t = setTimeout(() => setBanner(null), 4500);
    return () => clearTimeout(t);
  }, [banner]);

  // ── Fetch sequences ───────────────────────────────────────
  const fetchSequences = useCallback(async () => {
    setLoading(true);
    try {
      const url = filter === 'all'
        ? '/api/automation/sequences'
        : `/api/automation/sequences?status=${filter}`;

      const res  = await fetch(url, { credentials: 'include' });
      const data = await res.json();

      if (data.success) {
        setSequences(data.sequences || []);
        setStats(data.stats || {
          total: 0, draft: 0, active: 0,
          paused: 0, archived: 0, totalActiveEnrollments: 0,
        });
      } else {
        setBanner({ type: 'error', message: data.message || 'Failed to load sequences' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Network error — please try again' });
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    if (sessionStatus === 'authenticated') fetchSequences();
  }, [filter, sessionStatus, fetchSequences]);

  // ── Status change ─────────────────────────────────────────
  const handleStatusChange = async (id: string, newStatus: string) => {
    setActionLoading(id);
    try {
      const res  = await fetch(`/api/automation/sequences/${id}`, {
        method:      'PUT',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
        body:        JSON.stringify({ status: newStatus }),
      });
      const data = await res.json();

      if (data.success) {
        setBanner({
          type:    'success',
          message: `Sequence ${newStatus === 'active' ? 'activated' : newStatus} successfully`,
        });
        fetchSequences();
      } else {
        setBanner({ type: 'error', message: data.message || 'Failed to update status' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Network error — please try again' });
    } finally {
      setActionLoading(null);
    }
  };

  // ── Archive ───────────────────────────────────────────────
  const handleArchiveConfirm = async () => {
    if (!archiveModal.sequence) return;
    setActionLoading(archiveModal.sequence._id);

    try {
      const res  = await fetch(
        `/api/automation/sequences/${archiveModal.sequence._id}`,
        { method: 'DELETE', credentials: 'include' }
      );
      const data = await res.json();

      if (data.success) {
        setBanner({ type: 'success', message: data.message || 'Sequence archived' });
        setArchiveModal({ open: false, sequence: null });
        fetchSequences();
      } else {
        setBanner({ type: 'error', message: data.message || 'Failed to archive' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Network error — please try again' });
    } finally {
      setActionLoading(null);
    }
  };

  // ── Manual process trigger ────────────────────────────────
  const handleManualProcess = async () => {
    setIsProcessing(true);
    try {
      const res  = await fetch('/api/automation/process', {
        method:      'POST',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
      });
      const data = await res.json();

      if (data.success) {
        setBanner({
          type:    'success',
          message: `Processor ran: ${data.stats.sent} sent, ${data.stats.completed} completed`,
        });
        fetchSequences();
      } else {
        setBanner({ type: 'error', message: data.message || 'Processor failed' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Network error — please try again' });
    } finally {
      setIsProcessing(false);
    }
  };

  // ── Loading state ─────────────────────────────────────────
  if (sessionStatus === 'loading' || !session) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader2 className="w-10 h-10 animate-spin text-[#029bba]" />
      </div>
    );
  }

  const filterTabs = [
    { id: 'all',      label: 'All',      count: stats.total    },
    { id: 'active',   label: 'Active',   count: stats.active   },
    { id: 'draft',    label: 'Drafts',   count: stats.draft    },
    { id: 'paused',   label: 'Paused',   count: stats.paused   },
    { id: 'archived', label: 'Archived', count: stats.archived  },
  ];

  return (
    <>
      <Head>
        <title>Automation · Highrise.pk Admin</title>
        <meta name="robots" content="noindex,nofollow" />
      </Head>

      <AdminLayout>
        <div className="min-h-screen bg-gray-50 py-8">
          <div className="container mx-auto px-4 max-w-6xl">

            {/* ── Header ──────────────────────────────────────── */}
            <div className="flex flex-col md:flex-row md:items-center
                            md:justify-between gap-4 mb-6">
              <div>
                <h1 className="text-2xl font-black text-[#004063]
                               flex items-center gap-2">
                  <Zap className="w-6 h-6 text-[#029bba]" />
                  Automation Sequences
                </h1>
                <p className="text-sm text-gray-500 mt-1">
                  Set up drip campaigns that send automatically on triggers
                </p>
              </div>

              <div className="flex items-center gap-2">
                {/* Manual process trigger */}
                <button
                  type="button"
                  onClick={handleManualProcess}
                  disabled={isProcessing}
                  className="flex items-center gap-2 px-4 py-2.5 rounded-xl
                             border border-gray-200 bg-white text-gray-600
                             font-semibold text-sm hover:bg-gray-50
                             transition-colors disabled:opacity-50"
