                             rounded-xl bg-gradient-to-r from-[#029bba]
                             to-[#004063] text-white font-black text-sm
                             hover:shadow-lg hover:shadow-[#029bba]/20
                             transition-all"
                >
                  <Plus className="w-4 h-4" />
                  New Sequence
