                                    flex items-center justify-center flex-shrink-0`}>
                      <s.Icon className={`w-5 h-5 ${s.color}`} />
                    </div>
                    <div>
                      <p className={`text-2xl font-black ${s.color}`}>
                        {s.value.toLocaleString()}
                      </p>
                      <p className="text-xs text-gray-500 font-semibold">
                        {s.label}
                      </p>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* ── Filter tabs ──────────────────────────────────── */}
