  const getScheduleStatus = (
    banner: HeroBannerItem
  ): { label: string; color: string } => {
    const now = new Date();
    const start = banner.startDate ? new Date(banner.startDate) : null;
    const end = banner.endDate ? new Date(banner.endDate) : null;
