// pages/admin/reports.tsx
import React, { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/router';
import AdminLayout from '@/components/admin/AdminLayout';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Flag, Search, RefreshCw, CheckCircle, XCircle, Eye, Clock } from 'lucide-react';

type ReportStatus = 'open' | 'reviewing' | 'resolved' | 'rejected';

type ReportRow = {
  _id: string;
  entityType: 'property';
  entityId: string;
  reason: string;
  details: string;
  reporterEmail?: string;
  reporterPhone?: string;
  status: ReportStatus;
  createdAt: string;
  updatedAt: string;
};

const PRIMARY = '#029bba';

const reasonLabel = (r: string) => {
  const map: Record<string, string> = {
    scam_suspicious: 'Scam / Suspicious',
    fake_images: 'Fake Images',
    incorrect_price: 'Incorrect Price',
    wrong_location: 'Wrong Location',
    duplicate_listing: 'Duplicate Listing',
    agent_not_owner: 'Agent Not Owner',
    spam: 'Spam',
    other: 'Other',
  };
  return map[r] || r;
};

const formatDateTime = (d: string) => {
  const dt = new Date(d);
  return dt.toLocaleString('en-PK', { year: 'numeric', month: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit' });
};

export default function AdminReportsPage() {
  const router = useRouter();

  const [status, setStatus] = useState<ReportStatus | 'all'>('open');
  const [q, setQ] = useState('');
  const [page, setPage] = useState(1);

  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState<ReportRow[]>([]);
  const [total, setTotal] = useState(0);
  const [totalPages, setTotalPages] = useState(1);
  const limit = 10;

  // Read initial status from query (deep link support)
  useEffect(() => {
    if (!router.isReady) return;
    const qs = router.query.status;
    if (typeof qs === 'string' && ['open', 'reviewing', 'resolved', 'rejected', 'all'].includes(qs)) {
      setStatus(qs as any);
    }
  }, [router.isReady, router.query.status]);

  const fetchReports = async (nextPage?: number) => {
    const p = nextPage || page;
    setLoading(true);

    try {
      const params = new URLSearchParams();
      params.set('page', String(p));
      params.set('limit', String(limit));
      if (status !== 'all') params.set('status', status);
      if (q.trim()) params.set('q', q.trim());

      const res = await fetch(`/api/admin/reports?${params.toString()}`, { credentials: 'include' });
      const data = await res.json();

      if (!data?.success) {
        setItems([]);
        setTotal(0);
        setTotalPages(1);
        return;
      }

      setItems(data.reports || []);
      setTotal(data.total || 0);
      setTotalPages(data.totalPages || 1);

      // Sync badges in AdminLayout (Trust-first UI)
      window.dispatchEvent(new Event('refreshAdminStats'));
    } catch (e) {
      console.error('Failed to load reports', e);
      setItems([]);
      setTotal(0);
      setTotalPages(1);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchReports(1);
    setPage(1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status]);

  const statusPill = (s: ReportStatus) => {
    const base = 'px-2 py-1 rounded-full text-xs font-semibold border';
    if (s === 'open') return <span className={`${base} bg-red-50 text-red-700 border-red-100`}>Open</span>;
    if (s === 'reviewing') return <span className={`${base} bg-amber-50 text-amber-700 border-amber-100`}>Reviewing</span>;
    if (s === 'resolved') return <span className={`${base} bg-green-50 text-green-700 border-green-100`}>Resolved</span>;
    return <span className={`${base} bg-gray-50 text-gray-700 border-gray-200`}>Rejected</span>;
  };

  const changeStatus = async (id: string, next: ReportStatus) => {
    try {
      const res = await fetch(`/api/admin/reports/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ status: next }),
      });

      const data = await res.json();
      if (!data?.success) return;

      // Refresh list
      await fetchReports(page);

      // Refresh sidebar badges
      window.dispatchEvent(new Event('refreshAdminStats'));
    } catch (e) {
      console.error('Failed to update status', e);
    }
  };

  const canPrev = page > 1;
  const canNext = page < totalPages;

  return (
    <AdminLayout>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              <Flag className="w-6 h-6" style={{ color: PRIMARY }} />
              Reports Inbox
            </h1>
            <p className="text-gray-600 text-sm">
              Trust-first moderation: review reported listings and take action.
            </p>
          </div>

          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              onClick={() => fetchReports(page)}
              className="flex items-center gap-2"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
              Refresh
            </Button>
          </div>
        </div>

        {/* Filters */}
        <Card className="p-4">
          <div className="flex flex-col lg:flex-row gap-3 lg:items-center lg:justify-between">
            <div className="flex flex-wrap gap-2">
              {(['open', 'reviewing', 'resolved', 'rejected', 'all'] as const).map((s) => (
                <button
                  key={s}
                  onClick={() => setStatus(s as any)}
                  className={`px-4 py-2 rounded-xl text-sm font-medium border transition-all ${
                    status === s
                      ? 'bg-[#029bba] text-white border-[#029bba] shadow-lg shadow-[#029bba]/25'
                      : 'bg-white text-gray-700 border-gray-200 hover:bg-gray-50'
                  }`}
                >
                  {s === 'all' ? 'All' : s.charAt(0).toUpperCase() + s.slice(1)}
                </button>
              ))}
            </div>

            <div className="flex gap-2">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  value={q}
                  onChange={(e) => setQ(e.target.value)}
                  placeholder="Search: reportId, propertyId, reason, email…"
                  className="w-full lg:w-[360px] pl-10 pr-4 py-2 rounded-xl border border-gray-200 bg-gray-50 text-sm focus:bg-white focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none transition-all"
                />
              </div>
              <Button onClick={() => fetchReports(1)} className="flex items-center gap-2">
                <Search className="w-4 h-4" />
                Search
              </Button>
            </div>
          </div>
        </Card>

        {/* Table */}
        <Card className="overflow-hidden">
          <div className="p-4 border-b border-gray-100 flex items-center justify-between">
            <p className="text-sm text-gray-700">
              Total: <span className="font-semibold">{total}</span>
            </p>
            <p className="text-xs text-gray-500">
              Page {page} / {totalPages}
            </p>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead className="bg-gray-50 text-xs uppercase text-gray-500 font-semibold">
                <tr>
                  <th className="px-5 py-4">Date</th>
                  <th className="px-5 py-4">Reason</th>
                  <th className="px-5 py-4">Status</th>
                  <th className="px-5 py-4">Property</th>
                  <th className="px-5 py-4">Reporter</th>
                  <th className="px-5 py-4">Details</th>
                  <th className="px-5 py-4">Actions</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-100">
                {loading ? (
                  Array.from({ length: 6 }).map((_, i) => (
                    <tr key={i}>
                      <td className="px-5 py-4" colSpan={7}>
                        <div className="h-4 bg-gray-100 rounded animate-pulse" />
                      </td>
                    </tr>
                  ))
                ) : items.length === 0 ? (
                  <tr>
                    <td className="px-5 py-10 text-center text-sm text-gray-500" colSpan={7}>
                      No reports found.
                    </td>
                  </tr>
                ) : (
                  items.map((r) => (
                    <tr key={r._id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-5 py-4 text-sm text-gray-700 whitespace-nowrap">
                        {formatDateTime(r.createdAt)}
                      </td>

                      <td className="px-5 py-4 text-sm font-medium text-gray-900">
                        {reasonLabel(r.reason)}
                      </td>

                      <td className="px-5 py-4">
                        {statusPill(r.status)}
                      </td>

                      <td className="px-5 py-4">
                        <Link
                          href={`/property/${r.entityId}`}
                          target="_blank"
                          className="text-sm font-semibold text-[#029bba] hover:underline"
                        >
                          Open Listing
                        </Link>
                        <div className="text-[11px] text-gray-400 font-mono mt-1">
                          {r.entityId.slice(-8).toUpperCase()}
                        </div>
                      </td>

                      <td className="px-5 py-4 text-sm text-gray-700">
                        <div className="text-xs text-gray-700">
                          {r.reporterEmail || '—'}
                        </div>
                        <div className="text-[11px] text-gray-400">
                          {r.reporterPhone || ''}
                        </div>
                      </td>

                      <td className="px-5 py-4 text-sm text-gray-700">
                        <div className="line-clamp-2 max-w-[360px]">
                          {r.details}
                        </div>
                      </td>

                      <td className="px-5 py-4">
                        <div className="flex flex-wrap gap-2">
                          <button
                            onClick={() => changeStatus(r._id, 'reviewing')}
                            className="px-3 py-2 rounded-xl text-xs font-semibold border border-amber-200 bg-amber-50 text-amber-700 hover:bg-amber-100 transition-colors flex items-center gap-1"
                            title="Mark Reviewing"
                          >
                            <Clock className="w-4 h-4" />
                            Review
                          </button>

                          <button
                            onClick={() => changeStatus(r._id, 'resolved')}
                            className="px-3 py-2 rounded-xl text-xs font-semibold border border-green-200 bg-green-50 text-green-700 hover:bg-green-100 transition-colors flex items-center gap-1"
                            title="Mark Resolved"
                          >
                            <CheckCircle className="w-4 h-4" />
                            Resolve
                          </button>

                          <button
                            onClick={() => changeStatus(r._id, 'rejected')}
                            className="px-3 py-2 rounded-xl text-xs font-semibold border border-gray-200 bg-gray-50 text-gray-700 hover:bg-gray-100 transition-colors flex items-center gap-1"
                            title="Reject"
                          >
                            <XCircle className="w-4 h-4" />
                            Reject
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          <div className="p-4 border-t border-gray-100 flex items-center justify-between">
            <Button
              variant="outline"
              disabled={!canPrev || loading}
              onClick={() => {
                const next = Math.max(1, page - 1);
                setPage(next);
                fetchReports(next);
              }}
            >
              Prev
            </Button>

            <div className="text-xs text-gray-500">
              Showing <span className="font-semibold">{items.length}</span> of{' '}
              <span className="font-semibold">{total}</span>
            </div>

            <Button
              variant="outline"
              disabled={!canNext || loading}
              onClick={() => {
                const next = Math.min(totalPages, page + 1);
                setPage(next);
                fetchReports(next);
              }}
            >
              Next
            </Button>
          </div>
        </Card>
      </div>
    </AdminLayout>
  );
}

// pages/admin/reviews/create.tsx

import React, { useState } from 'react';
import Head from 'next/head';
import { useRouter } from 'next/router';
import AdminLayout from '@/components/admin/AdminLayout';
import AdminGuard from '@/components/AdminGuard';
import { api } from '@/lib/apiClient';
import {
  ArrowLeft,
  Star,
  Search,
  Loader2,
  CheckCircle,
  Building2,
  User,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import toast from 'react-hot-toast';

export default function CreateReviewPage() {
  const router = useRouter();
  const [step, setStep] = useState(1); // 1: Select Entity, 2: Write Review
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  
  // Search State
  const [searchTerm, setSearchTerm] = useState('');
  // Supported types in UI
  const [entityType, setEntityType] = useState<string>('agent');
  const [searchResults, setSearchResults] = useState<any[]>([]);
  
  // Selected Entity
  const [selectedEntity, setSelectedEntity] = useState<any>(null);

  // Review Form State
  const [rating, setRating] = useState(5);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [pros, setPros] = useState<string[]>(['']);
  const [cons, setCons] = useState<string[]>(['']);

  // Search Logic
  const handleSearch = async () => {
    if (!searchTerm) return;
    setLoading(true);
    try {
      // Search agents or developers
      const endpoint = entityType === 'agent' ? '/api/agents' : '/api/developers';
      // Note: Assuming these APIs support ?search= param. 
      // If not, we might need adjustments. 
      // Using generic search for now.
      const res = await api.get(`${endpoint}?search=${searchTerm}&limit=10`);
      
      if (res.success) {
        setSearchResults(res.data || []);
      } else {
        setSearchResults([]);
      }
    } catch (error) {
      toast.error('Search failed');
    } finally {
      setLoading(false);
    }
  };

  // Submit Logic
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEntity || !content) {
      toast.error('Please fill all required fields');
      return;
    }

    setSubmitting(true);
    try {
      const payload = {
        entityType,
        entityId: selectedEntity._id,
        rating,
        title,
        content,
        pros: pros.filter(p => p.trim()),
        cons: cons.filter(c => c.trim()),
        entitySnapshot: {
          name: selectedEntity.name || selectedEntity.companyName || selectedEntity.displayName,
          slug: selectedEntity.slug,
          city: selectedEntity.city,
          imageUrl: selectedEntity.profilePicture || selectedEntity.logo,
        }
      };

      const res = await api.post('/api/reviews', payload);

      if (res.success) {
        toast.success('Review published successfully!');
        router.push('/admin/reviews');
      } else {
        toast.error(res.message || 'Failed to publish review');
      }
    } catch (error) {
      console.error(error);
      toast.error('Something went wrong');
    } finally {
      setSubmitting(false);
    }
  };

  const addPro = () => setPros([...pros, '']);
  const addCon = () => setCons([...cons, '']);

  const updatePro = (index: number, val: string) => {
    const newPros = [...pros];
    newPros[index] = val;
    setPros(newPros);
  };

  const updateCon = (index: number, val: string) => {
    const newCons = [...cons];
    newCons[index] = val;
    setCons(newCons);
  };

  return (
    <AdminGuard>
      <AdminLayout>
        <Head>
          <title>Write Review | Highrise Admin</title>
        </Head>

        <div className="max-w-4xl mx-auto space-y-6">
          {/* Header */}
          <div className="flex items-center gap-4">
            <button 
              onClick={() => step === 2 ? setStep(1) : router.back()}
              className="p-2 hover:bg-gray-100 rounded-full"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <h1 className="text-2xl font-bold text-gray-900">
              {step === 1 ? 'Select Entity to Review' : 'Write Curated Review'}
            </h1>
          </div>

          {/* STEP 1: SELECT ENTITY */}
          {step === 1 && (
            <Card className="p-6 space-y-6">
              <div className="flex flex-wrap gap-2 p-1 bg-gray-100 rounded-lg w-fit">
                {['agent', 'developer', 'contractor', 'architect', 'vendor'].map((type) => (
                  <button
                    key={type}
                    onClick={() => { setEntityType(type); setSearchResults([]); }}
                    className={`px-4 py-2 text-sm font-medium rounded-md transition-all capitalize ${
                      entityType === type ? 'bg-white shadow text-[#029bba]' : 'text-gray-500'
                    }`}
                  >
                    {type}s
                  </button>
                ))}
              </div>

              <div className="relative">
                <div className="flex gap-2">
                  <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                      type="text"
                      placeholder={`Search ${entityType} name...`}
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                      className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-[#029bba]"
                    />
                  </div>
                  <Button onClick={handleSearch} disabled={loading} className="h-[46px] px-6">
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Search'}
                  </Button>
                </div>
              </div>

              <div className="space-y-2">
                {searchResults.length > 0 && (
                  <p className="text-sm text-gray-500 font-medium">Select one to proceed:</p>
                )}
                {searchResults.map((item) => (
                  <div 
                    key={item._id}
                    onClick={() => {
                      setSelectedEntity(item);
                      setStep(2);
                    }}
                    className="flex items-center gap-4 p-4 border rounded-xl hover:bg-gray-50 cursor-pointer transition-colors group"
                  >
                    <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center">
                      {item.profilePicture || item.logo ? (
                        <img src={item.profilePicture || item.logo} className="w-full h-full object-cover rounded-full" />
                      ) : (
                        entityType === 'agent' ? <User className="w-6 h-6 text-gray-500" /> : <Building2 className="w-6 h-6 text-gray-500" />
                      )}
                    </div>
                    <div className="flex-1">
                      <h3 className="font-semibold text-gray-900 group-hover:text-[#029bba]">
                        {item.name || item.companyName || item.displayName}
                      </h3>
                      <p className="text-sm text-gray-500">{item.city} • {item.email}</p>
                    </div>
                    <div className="w-8 h-8 rounded-full border border-gray-300 group-hover:bg-[#029bba] group-hover:border-[#029bba] flex items-center justify-center">
                      <CheckCircle className="w-5 h-5 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
                    </div>
                  </div>
                ))}
                
                {!loading && searchResults.length === 0 && searchTerm && (
                  <p className="text-center text-gray-500 py-8">No results found.</p>
                )}
              </div>
            </Card>
          )}

          {/* STEP 2: WRITE REVIEW */}
          {step === 2 && selectedEntity && (
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Selected Entity Summary */}
              <div className="flex items-center gap-4 p-4 bg-blue-50 border border-blue-100 rounded-xl">
                 <div className="w-12 h-12 bg-white rounded-full overflow-hidden border-2 border-white shadow-sm">
                    <img 
                      src={selectedEntity.profilePicture || selectedEntity.logo || '/placeholder.png'} 
                      className="w-full h-full object-cover" 
                      onError={(e) => (e.currentTarget.src = 'https://via.placeholder.com/50')}
                    />
                 </div>
                 <div>
                    <p className="text-sm text-blue-600 font-medium uppercase tracking-wider">Reviewing</p>
                    <h3 className="font-bold text-gray-900 text-lg">
                      {selectedEntity.name || selectedEntity.companyName || selectedEntity.displayName}
                    </h3>
                 </div>
                 <Button 
                   type="button" 
                   variant="ghost" 
                   size="sm" 
                   onClick={() => setStep(1)}
                   className="ml-auto text-blue-600 hover:text-blue-700 hover:bg-blue-100"
                 >
                   Change
                 </Button>
              </div>

              <Card className="p-6 space-y-6">
                {/* Rating */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Overall Rating</label>
                  <div className="flex gap-2">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <button
                        key={star}
                        type="button"
                        onClick={() => setRating(star)}
                        className="focus:outline-none transition-transform hover:scale-110"
                      >
                        <Star 
                          className={`w-8 h-8 ${star <= rating ? 'fill-amber-400 text-amber-400' : 'text-gray-300'}`} 
                        />
                      </button>
                    ))}
                    <span className="ml-2 text-lg font-bold text-gray-700">{rating}.0</span>
                  </div>
                </div>

                {/* Title */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Review Headline</label>
                  <input
                    type="text"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    placeholder="e.g. Professional and reliable service"
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-[#029bba]"
                  />
                </div>

                {/* Content */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Review Content</label>
                  <textarea
                    rows={6}
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    placeholder="Write your detailed review here..."
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-[#029bba]"
                  />
                </div>

                {/* Pros */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Pros (What you liked)</label>
                  <div className="space-y-2">
                    {pros.map((pro, idx) => (
                      <input
                        key={idx}
                        type="text"
                        value={pro}
                        onChange={(e) => updatePro(idx, e.target.value)}
                        placeholder="+ Add a pro point"
                        className="w-full px-3 py-2 border rounded-lg text-sm bg-green-50 border-green-200 focus:ring-green-500"
                      />
                    ))}
                    <button type="button" onClick={addPro} className="text-sm text-[#029bba] font-medium hover:underline">
                      + Add another pro
                    </button>
                  </div>
                </div>

                {/* Cons */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Cons (Areas for improvement)</label>
                  <div className="space-y-2">
                    {cons.map((con, idx) => (
                      <input
                        key={idx}
                        type="text"
                        value={con}
                        onChange={(e) => updateCon(idx, e.target.value)}
                        placeholder="- Add a con point"
                        className="w-full px-3 py-2 border rounded-lg text-sm bg-red-50 border-red-200 focus:ring-red-500"
                      />
                    ))}
                    <button type="button" onClick={addCon} className="text-sm text-red-500 font-medium hover:underline">
                      + Add another con
                    </button>
                  </div>
                </div>
              </Card>

              <div className="flex justify-end gap-3">
                <Button 
                  type="button" 
                  variant="outline" 
                  onClick={() => router.push('/admin/reviews')}
                >
                  Cancel
                </Button>
                <Button 
                  type="submit" 
                  disabled={submitting}
                  className="bg-[#029bba] hover:bg-[#027a94] text-white min-w-[140px]"
                >
                  {submitting ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : 'Publish Review'}
                </Button>
              </div>
            </form>
          )}
        </div>
      </AdminLayout>
    </AdminGuard>
  );
}

