              onChange={(v) => updateField('seoDescription', v)}
              placeholder="A brief description of your website"
              rows={3}
              hint="Recommended: 150-160 characters"
            />

            <TextareaField
              label="Default Keywords"
              value={settings.seoKeywords}
              onChange={(v) => updateField('seoKeywords', v)}
              placeholder="keyword1, keyword2, keyword3"
              rows={2}
              hint="Comma-separated keywords (less important for modern SEO)"
            />

            <div className="pt-4 border-t border-gray-100">
              <h3 className="text-lg font-semibold text-gray-900 mb-4">Analytics & Tracking</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <InputField
                  label="Google Analytics ID"
                  value={settings.googleAnalyticsId}
                  onChange={(v) => updateField('googleAnalyticsId', v)}
                  placeholder="G-XXXXXXXXXX"
                  hint="Your GA4 Measurement ID"
                />
                <InputField
                  label="Google Tag Manager ID"
                  value={settings.googleTagManagerId}
                  onChange={(v) => updateField('googleTagManagerId', v)}
                  placeholder="GTM-XXXXXXX"
                  hint="Your GTM Container ID"
                />
              </div>
            </div>

            {/* SEO Preview */}
            <div className="pt-4 border-t border-gray-100">
              <h3 className="text-lg font-semibold text-gray-900 mb-4">Google Search Preview</h3>
              <div className="bg-white border border-gray-200 rounded-xl p-4">
                <p className="text-blue-600 text-lg hover:underline cursor-pointer truncate">
                  {settings.seoTitle || 'Your Site Title'}
                </p>
                <p className="text-green-700 text-sm truncate">
                  {settings.siteUrl}
                </p>
                <p className="text-gray-600 text-sm line-clamp-2">
                  {settings.seoDescription || 'Your meta description will appear here...'}
                </p>
              </div>
            </div>
          </div>
        );

      case 'email':
        return (
          <div className="space-y-6">
            <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-start gap-3">
              <AlertTriangle className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-blue-800 font-medium">Email Configuration</p>
                <p className="text-blue-700 text-sm mt-1">
                  SMTP settings are configured in your <code className="bg-blue-100 px-1 rounded">.env.local</code> file for security.
                  The values below are for display/reference only.
                </p>
              </div>
            </div>

            <h3 className="text-lg font-semibold text-gray-900 mb-4">Email Display Settings</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <InputField
                label="Email Host"
                value={settings.emailHost}
                onChange={(v) => updateField('emailHost', v)}
                placeholder="mail.example.com"
                disabled
              />
              <InputField
                label="Email Port"
                value={settings.emailPort}
                onChange={(v) => updateField('emailPort', v)}
                placeholder="465"
                disabled
              />
              <InputField
                label="From Email"
                value={settings.emailFrom}
                onChange={(v) => updateField('emailFrom', v)}
                placeholder="info@example.com"
              />
              <InputField
                label="From Name"
                value={settings.emailFromName}
                onChange={(v) => updateField('emailFromName', v)}
                placeholder="Your Site Name"
              />
            </div>

            <div className="pt-4">
              <a
                href="/admin/email-templates"
                className="inline-flex items-center gap-2 text-[#029bba] hover:underline font-medium"
              >
                <FileText className="w-4 h-4" />
                Manage Email Templates
                <ExternalLink className="w-4 h-4" />
              </a>
            </div>
          </div>
        );

      case 'features':
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Feature Toggles</h3>
            <p className="text-gray-500 text-sm mb-4">
              Enable or disable various features of your platform.
            </p>

            <div className="space-y-3">
              <ToggleSwitch
                enabled={settings.maintenanceMode}
                onChange={(v) => updateField('maintenanceMode', v)}
                label="Maintenance Mode"
                description="When enabled, visitors see a maintenance page"
              />
              <ToggleSwitch
                enabled={settings.allowRegistration}
                onChange={(v) => updateField('allowRegistration', v)}
                label="Allow User Registration"
                description="Allow new users to create accounts"
              />
              <ToggleSwitch
                enabled={settings.requireEmailVerification}
                onChange={(v) => updateField('requireEmailVerification', v)}
                label="Require Email Verification"
                description="Users must verify email before accessing features"
              />
              <ToggleSwitch
                enabled={settings.enableNotifications}
                onChange={(v) => updateField('enableNotifications', v)}
                label="Enable Email Notifications"
                description="Send email notifications for various events"
              />
              <ToggleSwitch
                enabled={settings.enableNewsletter}
                onChange={(v) => updateField('enableNewsletter', v)}
                label="Enable Newsletter"
                description="Show newsletter subscription forms"
              />
              <ToggleSwitch
                enabled={settings.enableComments}
                onChange={(v) => updateField('enableComments', v)}
                label="Enable Comments"
                description="Allow users to comment on blog posts"
              />
            </div>

            {settings.maintenanceMode && (
              <div className="bg-orange-50 border border-orange-200 rounded-xl p-4 flex items-start gap-3">
                <AlertTriangle className="w-5 h-5 text-orange-600 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="text-orange-800 font-medium">Maintenance Mode is ON</p>
                  <p className="text-orange-700 text-sm mt-1">
                    Your website is currently showing a maintenance page to visitors. 
                    Admin users can still access the site.
                  </p>
                </div>
              </div>
            )}
          </div>
        );

          case 'watermark':
        return (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-lg font-semibold text-gray-900">Watermark Settings</h3>
                <p className="text-gray-500 text-sm mt-1">
                  Add watermark to property images automatically
                </p>
              </div>
              <ToggleSwitch
                enabled={settings.watermark?.enabled ?? true}
                onChange={(v) => updateField('watermark', { ...settings.watermark, enabled: v })}
                label=""
              />
            </div>

            {settings.watermark?.enabled && (
              <>
                {/* Watermark Type */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Watermark Type</label>
                  <div className="flex gap-4">
                    <button
                      type="button"
                      onClick={() => updateField('watermark', { ...settings.watermark, type: 'text' })}
                      className={`flex-1 p-4 rounded-xl border-2 transition-all ${
                        settings.watermark?.type === 'text'
                          ? 'border-[#029bba] bg-[#029bba]/5'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <FileText className={`w-6 h-6 mx-auto mb-2 ${
                        settings.watermark?.type === 'text' ? 'text-[#029bba]' : 'text-gray-400'
                      }`} />
                      <p className={`text-sm font-medium ${
                        settings.watermark?.type === 'text' ? 'text-[#029bba]' : 'text-gray-600'
                      }`}>Text Watermark</p>
                      <p className="text-xs text-gray-500 mt-1">Use your site name</p>
                    </button>
                    <button
                      type="button"
                      onClick={() => updateField('watermark', { ...settings.watermark, type: 'logo' })}
                      className={`flex-1 p-4 rounded-xl border-2 transition-all ${
                        settings.watermark?.type === 'logo'
                          ? 'border-[#029bba] bg-[#029bba]/5'
                          : 'border-gray-200 hover:border-gray-300'
                      }`}
                    >
                      <Image className={`w-6 h-6 mx-auto mb-2 ${
                        settings.watermark?.type === 'logo' ? 'text-[#029bba]' : 'text-gray-400'
                      }`} />
                      <p className={`text-sm font-medium ${
                        settings.watermark?.type === 'logo' ? 'text-[#029bba]' : 'text-gray-600'
                      }`}>Logo Watermark</p>
                      <p className="text-xs text-gray-500 mt-1">Use your logo image</p>
                    </button>
                  </div>
                </div>

                {/* Text or Logo Input */}
                {settings.watermark?.type === 'text' ? (
                  <InputField
                    label="Watermark Text"
                    value={settings.watermark?.text || 'Highrise.pk'}
                    onChange={(v) => updateField('watermark', { ...settings.watermark, text: v })}
                    placeholder="Highrise.pk"
                    hint="This text will appear on all property images"
                  />
                ) : (
                  <ImageUploadField
                    label="Watermark Logo"
                    value={settings.watermark?.logoUrl || ''}
                    onChange={(v) => updateField('watermark', { ...settings.watermark, logoUrl: v })}
                    hint="Recommended: PNG with transparent background, max 500x200px"
                    folder="general"
                  />
                )}

                {/* Position */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Position</label>
                  <div className="grid grid-cols-3 gap-2">
                    {[
                      { value: 'top-left', label: 'Top Left' },
                      { value: 'top-right', label: 'Top Right' },
                      { value: 'center', label: 'Center' },
                      { value: 'bottom-left', label: 'Bottom Left' },
                      { value: 'bottom-center', label: 'Bottom Center' },
                      { value: 'bottom-right', label: 'Bottom Right' },
                    ].map((pos) => (
                      <button
                        key={pos.value}
                        type="button"
                        onClick={() => updateField('watermark', { ...settings.watermark, position: pos.value as any })}
                        className={`p-3 rounded-xl border text-sm font-medium transition-all ${
                          settings.watermark?.position === pos.value
                            ? 'border-[#029bba] bg-[#029bba] text-white'
                            : 'border-gray-200 text-gray-600 hover:border-gray-300'
                        }`}
                      >
                        {pos.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Size */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Size</label>
                  <div className="flex gap-2">
                    {[
                      { value: 'small', label: 'Small' },
                      { value: 'medium', label: 'Medium' },
                      { value: 'large', label: 'Large' },
                    ].map((size) => (
                      <button
                        key={size.value}
                        type="button"
                        onClick={() => updateField('watermark', { ...settings.watermark, size: size.value as any })}
                        className={`flex-1 p-3 rounded-xl border text-sm font-medium transition-all ${
                          settings.watermark?.size === size.value
                            ? 'border-[#029bba] bg-[#029bba] text-white'
                            : 'border-gray-200 text-gray-600 hover:border-gray-300'
                        }`}
                      >
                        {size.label}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Opacity Slider */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Opacity: {settings.watermark?.opacity || 70}%
                  </label>
                  <input
                    type="range"
                    min="10"
                    max="100"
                    step="5"
                    value={settings.watermark?.opacity || 70}
                    onChange={(e) => updateField('watermark', { ...settings.watermark, opacity: parseInt(e.target.value) })}
                    className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-[#029bba]"
                  />
                  <div className="flex justify-between text-xs text-gray-500 mt-1">
                    <span>10% (Subtle)</span>
                    <span>100% (Solid)</span>
                  </div>
                </div>

                {/* Padding */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Padding from Edge: {settings.watermark?.padding || 20}px
                  </label>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    step="5"
                    value={settings.watermark?.padding || 20}
                    onChange={(e) => updateField('watermark', { ...settings.watermark, padding: parseInt(e.target.value) })}
                    className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-[#029bba]"
                  />
                  <div className="flex justify-between text-xs text-gray-500 mt-1">
                    <span>0px (Edge)</span>
                    <span>100px (Inset)</span>
                  </div>
                </div>

                {/* Preview */}
                <div className="pt-4 border-t border-gray-100">
                  <label className="block text-sm font-medium text-gray-700 mb-3">Preview</label>
                  <div className="relative bg-gray-100 rounded-xl overflow-hidden" style={{ aspectRatio: '16/9' }}>
                    {/* Sample Image Background */}
                    <div className="absolute inset-0 bg-gradient-to-br from-gray-300 to-gray-400 flex items-center justify-center">
                      <Building2 className="w-20 h-20 text-gray-500/50" />
                    </div>
                    
                    {/* Watermark Preview */}
                    <div
                      className={`absolute ${
                        settings.watermark?.position === 'top-left' ? 'top-0 left-0' :
                        settings.watermark?.position === 'top-right' ? 'top-0 right-0' :
                        settings.watermark?.position === 'bottom-left' ? 'bottom-0 left-0' :
                        settings.watermark?.position === 'bottom-right' ? 'bottom-0 right-0' :
                        settings.watermark?.position === 'center' ? 'top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2' :
                        settings.watermark?.position === 'bottom-center' ? 'bottom-0 left-1/2 -translate-x-1/2' :
                        'bottom-0 right-0'
                      }`}
                      style={{ 
                        padding: `${settings.watermark?.padding || 20}px`,
                        opacity: (settings.watermark?.opacity || 70) / 100 
                      }}
                    >
                      {settings.watermark?.type === 'logo' && settings.watermark?.logoUrl ? (
                        <img 
                          src={settings.watermark.logoUrl} 
                          alt="Watermark"
                          className={`${
                            settings.watermark?.size === 'small' ? 'h-6' :
                            settings.watermark?.size === 'large' ? 'h-14' :
                            'h-10'
                          } w-auto`}
                        />
                      ) : (
                        <span 
                          className={`font-bold text-white drop-shadow-lg ${
                            settings.watermark?.size === 'small' ? 'text-sm' :
                            settings.watermark?.size === 'large' ? 'text-2xl' :
                            'text-lg'
                          }`}
                          style={{ textShadow: '2px 2px 4px rgba(0,0,0,0.5)' }}
                        >
                          {settings.watermark?.text || 'Highrise.pk'}
                        </span>
                      )}
                    </div>
                  </div>
                  <p className="text-xs text-gray-500 mt-2 text-center">
                    This is how watermark will appear on property images
                  </p>
                </div>
              </>
            )}

            {!settings.watermark?.enabled && (
              <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-4 flex items-start gap-3">
                <AlertTriangle className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="text-yellow-800 font-medium">Watermark Disabled</p>
                  <p className="text-yellow-700 text-sm mt-1">
                    Property images will be uploaded without watermark. Enable watermark to protect your images.
                  </p>
                </div>
              </div>
            )}
          </div>
        );

      case 'hours':
        return (
          <div className="space-y-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Business Hours</h3>
            <p className="text-gray-500 text-sm mb-4">
              Set your operating hours. These may be displayed on your website.
            </p>

            <div className="space-y-3">
              {(Object.keys(settings.businessHours) as Array<keyof typeof settings.businessHours>).map((day) => (
                <div
                  key={day}
                  className="flex items-center justify-between p-4 bg-gray-50 rounded-xl"
                >
                  <div className="flex items-center gap-4">
                    <span className="font-medium text-gray-900 capitalize w-24">{day}</span>
                    
                    {!settings.businessHours[day].closed ? (
                      <div className="flex items-center gap-2">
                        <input
                          type="time"
                          value={settings.businessHours[day].open}
                          onChange={(e) => updateBusinessHours(day, 'open', e.target.value)}
                          className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none"
                        />
                        <span className="text-gray-500">to</span>
                        <input
                          type="time"
                          value={settings.businessHours[day].close}
                          onChange={(e) => updateBusinessHours(day, 'close', e.target.value)}
                          className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none"
                        />
                      </div>
                    ) : (
                      <span className="text-gray-500 italic">Closed</span>
                    )}
                  </div>

                  <button
                    type="button"
                    onClick={() => updateBusinessHours(day, 'closed', !settings.businessHours[day].closed)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                      settings.businessHours[day].closed
                        ? 'bg-red-100 text-red-700 hover:bg-red-200'
                        : 'bg-green-100 text-green-700 hover:bg-green-200'
                    }`}
                  >
                    {settings.businessHours[day].closed ? 'Closed' : 'Open'}
                  </button>
                </div>
              ))}
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Settings</h1>
          <p className="text-gray-500 mt-1">Manage your platform configuration</p>
        </div>
        <div className="flex items-center gap-3">
          {hasChanges && (
            <span className="text-sm text-orange-600 flex items-center gap-1">
              <AlertTriangle className="w-4 h-4" />
              Unsaved changes
            </span>
          )}
          <button
            onClick={handleSave}
            disabled={saving || !hasChanges}
            className="px-4 py-2.5 bg-[#029bba] text-white rounded-xl hover:bg-[#027a94] transition-colors font-medium flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {saving ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Save className="w-4 h-4" />
            )}
            Save Changes
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex flex-col lg:flex-row gap-6">
        {/* Sidebar Tabs */}
        <div className="lg:w-64 flex-shrink-0">
          <Card className="p-2">
            <nav className="space-y-1">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
                    activeTab === tab.id
                      ? 'bg-[#029bba] text-white'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  <tab.icon className="w-5 h-5" />
                  <span className="font-medium">{tab.label}</span>
                </button>
              ))}
            </nav>

            {/* Danger Zone */}
            <div className="mt-4 pt-4 border-t border-gray-100">
              <button
                onClick={() => setResetModal(true)}
                className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left text-red-600 hover:bg-red-50 transition-colors"
              >
                <RefreshCw className="w-5 h-5" />
                <span className="font-medium">Reset to Defaults</span>
              </button>
            </div>
          </Card>

          {/* Last Updated */}
          {settings.updatedAt && (
            <p className="text-xs text-gray-400 mt-3 px-2">
              Last updated: {new Date(settings.updatedAt).toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
              })}
            </p>
          )}
        </div>

        {/* Content Area */}
        <div className="flex-1">
          <Card className="p-6">
            {renderTabContent()}
          </Card>
        </div>
      </div>

      {/* Reset Confirmation Modal */}
      <ConfirmationModal
        isOpen={resetModal}
        onClose={() => setResetModal(false)}
        onConfirm={handleReset}
        title="Reset All Settings?"
        message="This will reset all settings to their default values. This action cannot be undone."
        confirmText="Reset Settings"
        cancelText="Cancel"
        variant="danger"
        isLoading={resetLoading}
      />
    </div>
  );
}

// Main Export
export default function AdminSettingsPage() {
  return (
    <AdminGuard>
      <AdminLayout>
        <SettingsContent />
      </AdminLayout>
    </AdminGuard>
  );
}

// pages/admin/societies/index.tsx
import React, { useState, useEffect, useCallback, useRef } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import {
  Shield, ShieldCheck, ShieldAlert, ShieldX, Plus, Search,
  Filter, X, Eye, Edit, Trash2, BadgeCheck, AlertTriangle,
  CheckCircle, XCircle, Loader2, ChevronLeft, ChevronRight,
  Building2, MapPin, Star, Activity, Clock, Award,
  Calendar, ArrowUpDown, MoreVertical, Download, RefreshCw,
  Settings,
} from 'lucide-react';
import AdminLayout from '@/components/admin/AdminLayout';

// ─── Types ────────────────────────────────────────────────────────────────────

interface SocietyAdminListItem {
  _id: string;
  name: string;
  slug: string;
  city: string;
  areaName: string;
  category: string;
  nocStatus: string;
  approvalAuthority: string;
  overallRiskLevel: string;
  legalScore: number;
  growthScore: number;
  overallScore: number;
  featuredImage?: string;
  isVerifiedByHighrise: boolean;
  isPublished: boolean;
  isFeatured: boolean;
  viewCount: number;
  searchCount: number;
  activeAlertCount: number;
  developerName?: string;
  lastVerifiedAt?: string;
  createdAt: string;
  updatedAt: string;
}

interface DashboardStats {
  total: number;
  published: number;
  verified: number;
  pending: number;
  flagged: number;
}

interface PaginationData {
  page: number;
  limit: number;
  total: number;
  pages: number;
  hasNext: boolean;
  hasPrev: boolean;
}

type BannerType = 'success' | 'error' | 'info';

interface Banner {
  type: BannerType;
  message: string;
}

// ─── Constants ────────────────────────────────────────────────────────────────

const NOC_STATUS_CONFIG: Record<string, { label: string; color: string }> = {
  approved: { label: 'Approved', color: 'bg-[#10b981] text-white' },
  pending: { label: 'Pending', color: 'bg-[#f59e0b] text-white' },
  under_review: { label: 'Reviewing', color: 'bg-[#f59e0b] text-white' },
  illegal: { label: 'Illegal', color: 'bg-[#ef4444] text-white' },
  disputed: { label: 'Disputed', color: 'bg-[#ef4444] text-white' },
  cancelled: { label: 'Cancelled', color: 'bg-[#ef4444] text-white' },
  expired: { label: 'Expired', color: 'bg-[#f59e0b] text-white' },
};

const RISK_CONFIG: Record<string, { label: string; bg: string; text: string }> = {
  safe: { label: 'Safe', bg: 'bg-[#f0fdf4]', text: 'text-[#10b981]' },
  caution: { label: 'Caution', bg: 'bg-[#fef3c7]', text: 'text-[#92400e]' },
  high_risk: { label: 'High Risk', bg: 'bg-[#fef2f2]', text: 'text-[#ef4444]' },
  avoid: { label: 'Avoid', bg: 'bg-[#ef4444]', text: 'text-white' },
};

// ─── Main Component ───────────────────────────────────────────────────────────

export default function AdminSocietiesPage(): React.ReactElement {
  const router = useRouter();
  const { data: session, status } = useSession();

  // Data
  const [societies, setSocieties] = useState<SocietyAdminListItem[]>([]);
  const [stats, setStats] = useState<DashboardStats>({
    total: 0,
    published: 0,
    verified: 0,
    pending: 0,
    flagged: 0,
  });
  const [pagination, setPagination] = useState<PaginationData>({
    page: 1,
    limit: 20,
    total: 0,
    pages: 0,
    hasNext: false,
    hasPrev: false,
  });

  // Filters
  const [search, setSearch] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [city, setCity] = useState('');
  const [nocStatus, setNocStatus] = useState('');
  const [riskLevel, setRiskLevel] = useState('');
  const [isPublished, setIsPublished] = useState('');
  const [isVerified, setIsVerified] = useState('');
  const [sortBy, setSortBy] = useState('createdAt');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [page, setPage] = useState(1);

  // UI
  const [loading, setLoading] = useState(true);
  const [banner, setBanner] = useState<Banner | null>(null);
  const [actionLoadingId, setActionLoadingId] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [deleteModal, setDeleteModal] = useState<{ id: string; name: string } | null>(null);
  const [deleteMode, setDeleteMode] = useState<'soft' | 'hard'>('soft');
  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ─── Auth Guard ──────────────────────────────────────────────────────────

  useEffect(() => {
    if (status === 'loading') return;
    if (!session?.user) {
      router.replace('/login?redirect=/admin/societies');
      return;
    }
    const userRole = (session.user as { role?: string }).role;
    if (userRole !== 'admin') {
      router.replace('/');
    }
  }, [session, status, router]);

  // ─── Fetch Data ──────────────────────────────────────────────────────────

  const fetchSocieties = useCallback(async () => {
    setLoading(true);

    try {
      const params = new URLSearchParams();
      if (search) params.set('search', search);
      if (city) params.set('city', city);
      if (nocStatus) params.set('nocStatus', nocStatus);
      if (riskLevel) params.set('riskLevel', riskLevel);
      if (isPublished) params.set('isPublished', isPublished);
      if (isVerified) params.set('isVerified', isVerified);
      params.set('sortBy', sortBy);
      params.set('sortOrder', sortOrder);
      params.set('page', String(page));
      params.set('limit', '20');

      const res = await fetch(`/api/admin/societies?${params.toString()}`, {
        cache: 'no-store',
      });
      const data = await res.json();

      if (!res.ok || !data.success) {
        setBanner({ type: 'error', message: data?.error || 'Failed to load societies' });
        setSocieties([]);
        return;
      }

      setSocieties(data.data.societies || []);
      setPagination(data.data.pagination);
      setStats(data.data.stats);
    } catch {
      setBanner({ type: 'error', message: 'Network error. Please try again.' });
      setSocieties([]);
    } finally {
      setLoading(false);
    }
  }, [search, city, nocStatus, riskLevel, isPublished, isVerified, sortBy, sortOrder, page]);

  useEffect(() => {
    const userRole = (session?.user as { role?: string })?.role;
    if (session?.user && userRole === 'admin') {
      fetchSocieties();
    }
  }, [session, fetchSocieties]);

  // Debounced search
  useEffect(() => {
    if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
    searchTimeoutRef.current = setTimeout(() => {
      if (searchInput !== search) {
        setSearch(searchInput);
        setPage(1);
      }
    }, 400);
    return () => {
      if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
    };
  }, [searchInput, search]);

  // Auto-clear banner
  useEffect(() => {
    if (!banner) return;
    const timer = setTimeout(() => setBanner(null), 5000);
    return () => clearTimeout(timer);
  }, [banner]);

  // ─── Actions ─────────────────────────────────────────────────────────────

  const handleQuickToggle = async (
    society: SocietyAdminListItem,
    field: 'isPublished' | 'isVerifiedByHighrise' | 'isFeatured'
  ) => {
    setActionLoadingId(society._id);
    try {
      const currentValue =
        field === 'isPublished' ? society.isPublished :
        field === 'isVerifiedByHighrise' ? society.isVerifiedByHighrise :
        society.isFeatured;

      const res = await fetch(`/api/admin/societies/${society._id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ [field]: !currentValue }),
      });

      const data = await res.json();

      if (!res.ok || !data.success) {
        setBanner({ type: 'error', message: data?.error || 'Failed to update society' });
        return;
      }

      const fieldLabels: Record<string, string> = {
        isPublished: currentValue ? 'unpublished' : 'published',
        isVerifiedByHighrise: currentValue ? 'unverified' : 'verified',
        isFeatured: currentValue ? 'unfeatured' : 'featured',
      };

      setBanner({
        type: 'success',
        message: `${society.name} has been ${fieldLabels[field]}.`,
      });

      // Refresh list
      fetchSocieties();
    } catch {
      setBanner({ type: 'error', message: 'Connection error. Please try again.' });
    } finally {
      setActionLoadingId(null);
    }
  };

  const handleDelete = async () => {
    if (!deleteModal) return;
    setActionLoadingId(deleteModal.id);

    try {
      const url = deleteMode === 'hard'
        ? `/api/admin/societies/${deleteModal.id}?hard=true`
        : `/api/admin/societies/${deleteModal.id}`;

      const res = await fetch(url, { method: 'DELETE' });
      const data = await res.json();

      if (!res.ok || !data.success) {
        setBanner({ type: 'error', message: data?.error || 'Delete failed' });
        return;
      }

      setBanner({
        type: 'success',
        message: deleteMode === 'hard'
          ? `${deleteModal.name} permanently deleted.`
          : `${deleteModal.name} unpublished successfully.`,
      });

      setDeleteModal(null);
      setDeleteMode('soft');
      fetchSocieties();
    } catch {
      setBanner({ type: 'error', message: 'Connection error during delete.' });
    } finally {
      setActionLoadingId(null);
    }
  };

  const handleClearFilters = () => {
    setSearchInput('');
    setSearch('');
    setCity('');
    setNocStatus('');
    setRiskLevel('');
    setIsPublished('');
    setIsVerified('');
    setSortBy('createdAt');
    setSortOrder('desc');
    setPage(1);
  };

  const activeFilterCount =
    (city ? 1 : 0) +
    (nocStatus ? 1 : 0) +
    (riskLevel ? 1 : 0) +
    (isPublished ? 1 : 0) +
    (isVerified ? 1 : 0);

  // ─── Auth Loading State ──────────────────────────────────────────────────

  if (status === 'loading' || !session?.user) {
    return (
      <>
        <Head>
          <title>Loading… | Admin</title>
        </Head>
        <div className="min-h-screen bg-gray-50 flex items-center justify-center">
          <Loader2 className="w-10 h-10 text-[#029bba] animate-spin" />
        </div>
      </>
    );
  }

  const userRole = (session.user as { role?: string }).role;
  if (userRole !== 'admin') {
    return (
      <>
        <Head>
          <title>Access Denied</title>
        </Head>
        <div className="min-h-screen bg-gray-50 flex items-center justify-center px-4">
          <div className="bg-white rounded-2xl shadow-md p-8 max-w-md text-center">
            <ShieldX className="w-16 h-16 text-[#ef4444] mx-auto mb-4" />
            <h1 className="text-xl font-bold text-gray-900 mb-2">Access Denied</h1>
            <p className="text-gray-600">Admin privileges required.</p>
          </div>
        </div>
      </>
    );
  }

  return (
    <>
      <Head>
        <title>Society Management | Highrise Admin</title>
      </Head>

      <AdminLayout>
        <div className="p-6 max-w-[1600px] mx-auto">

          {/* ── HEADER ── */}
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6">
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-gray-900 flex items-center gap-3">
                <Shield className="w-7 h-7 text-[#029bba]" />
                Society Management
              </h1>
              <p className="text-gray-600 text-sm mt-1">
                Manage NOC verifications, risk alerts, and society intelligence data
              </p>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => fetchSocieties()}
                disabled={loading}
                className="px-3 py-2.5 rounded-xl bg-white border border-gray-300 text-gray-700 text-sm font-semibold hover:bg-gray-50 transition-colors flex items-center gap-2 disabled:opacity-50"
                title="Refresh"
              >
                <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
              </button>
              <Link href="/admin/societies/new">
                <button className="px-4 py-2.5 rounded-xl bg-[#029bba] text-white text-sm font-semibold hover:bg-[#027a94] transition-colors inline-flex items-center gap-2 shadow-md">
                  <Plus className="w-4 h-4" />
                  Add Society
                </button>
              </Link>
            </div>
          </div>

          {/* ── BANNER ── */}
          {banner && (
            <div
              className={`mb-6 rounded-xl border-l-4 p-4 flex items-start gap-3 ${
                banner.type === 'success'
                  ? 'bg-[#f0fdf4] border-[#10b981] text-[#10b981]'
                  : banner.type === 'error'
                  ? 'bg-[#fef2f2] border-[#ef4444] text-red-700'
                  : 'bg-[#eff6ff] border-[#029bba] text-[#004063]'
              }`}
            >
              {banner.type === 'success' && <CheckCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />}
              {banner.type === 'error' && <XCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />}
              {banner.type === 'info' && <Activity className="w-5 h-5 flex-shrink-0 mt-0.5" />}
              <span className="flex-1 text-sm font-medium">{banner.message}</span>
              <button
                onClick={() => setBanner(null)}
                className="opacity-60 hover:opacity-100 transition-opacity"
                aria-label="Dismiss"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          )}

          {/* ── STATS DASHBOARD ── */}
          <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-6">
            <StatCard
              icon={<Building2 className="w-5 h-5" />}
              label="Total Societies"
              value={stats.total}
              color="#029bba"
              onClick={handleClearFilters}
            />
            <StatCard
              icon={<CheckCircle className="w-5 h-5" />}
              label="Published"
              value={stats.published}
              color="#10b981"
              onClick={() => { setIsPublished('true'); setPage(1); }}
            />
            <StatCard
              icon={<BadgeCheck className="w-5 h-5" />}
              label="Verified"
              value={stats.verified}
              color="#7c3aed"
              onClick={() => { setIsVerified('true'); setPage(1); }}
            />
            <StatCard
              icon={<Clock className="w-5 h-5" />}
              label="Pending NOC"
              value={stats.pending}
              color="#f59e0b"
              onClick={() => { setNocStatus('pending'); setPage(1); }}
            />
            <StatCard
              icon={<AlertTriangle className="w-5 h-5" />}
              label="Flagged"
              value={stats.flagged}
              color="#ef4444"
              onClick={() => { setRiskLevel('high_risk'); setPage(1); }}
            />
          </div>

          {/* ── SEARCH + FILTERS BAR ── */}
          <div className="bg-white rounded-2xl shadow-sm p-4 mb-6">
            <div className="flex flex-col md:flex-row md:items-center gap-3">
              {/* Search */}
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                <input
                  type="text"
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  placeholder="Search by name, city, area, or slug..."
                  className="w-full h-10 pl-10 pr-3 rounded-xl border border-gray-300 text-sm focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/10 outline-none"
                />
                {searchInput && (
                  <button
                    onClick={() => setSearchInput('')}
                    className="absolute right-3 top-1/2 -translate-y-1/2"
                    aria-label="Clear search"
                  >
                    <X className="w-4 h-4 text-gray-400 hover:text-gray-600" />
                  </button>
                )}
              </div>

              {/* Toggle filters on mobile */}
              <button
                onClick={() => setShowFilters(!showFilters)}
                className="md:hidden h-10 px-4 rounded-xl bg-gray-100 text-gray-700 text-sm font-semibold hover:bg-gray-200 transition-colors flex items-center gap-2"
              >
                <Filter className="w-4 h-4" />
                Filters
                {activeFilterCount > 0 && (
                  <span className="ml-1 inline-flex items-center justify-center w-5 h-5 rounded-full bg-[#029bba] text-white text-[10px] font-bold">
                    {activeFilterCount}
                  </span>
                )}
              </button>
            </div>

            {/* Filters */}
            <div className={`${showFilters ? 'grid' : 'hidden'} md:grid grid-cols-2 md:grid-cols-6 gap-3 mt-3 pt-3 border-t border-gray-100`}>
              <select
                value={city}
                onChange={(e) => { setCity(e.target.value); setPage(1); }}
                className="h-10 px-3 rounded-xl border border-gray-300 text-sm focus:border-[#029bba] outline-none cursor-pointer bg-white"
              >
                <option value="">All Cities</option>
                <option value="Lahore">Lahore</option>
                <option value="Islamabad">Islamabad</option>
                <option value="Karachi">Karachi</option>
                <option value="Rawalpindi">Rawalpindi</option>
                <option value="Faisalabad">Faisalabad</option>
                <option value="Multan">Multan</option>
                <option value="Peshawar">Peshawar</option>
                <option value="Quetta">Quetta</option>
                <option value="Gujranwala">Gujranwala</option>
                <option value="Sialkot">Sialkot</option>
              </select>

              <select
                value={nocStatus}
                onChange={(e) => { setNocStatus(e.target.value); setPage(1); }}
                className="h-10 px-3 rounded-xl border border-gray-300 text-sm focus:border-[#029bba] outline-none cursor-pointer bg-white"
              >
                <option value="">All NOC</option>
                <option value="approved">Approved</option>
                <option value="pending">Pending</option>
                <option value="under_review">Under Review</option>
                <option value="illegal">Illegal</option>
                <option value="disputed">Disputed</option>
                <option value="cancelled">Cancelled</option>
                <option value="expired">Expired</option>
              </select>

              <select
                value={riskLevel}
                onChange={(e) => { setRiskLevel(e.target.value); setPage(1); }}
                className="h-10 px-3 rounded-xl border border-gray-300 text-sm focus:border-[#029bba] outline-none cursor-pointer bg-white"
              >
                <option value="">All Risk</option>
                <option value="safe">🟢 Safe</option>
                <option value="caution">🟡 Caution</option>
                <option value="high_risk">🔴 High Risk</option>
                <option value="avoid">⛔ Avoid</option>
              </select>

              <select
                value={isPublished}
                onChange={(e) => { setIsPublished(e.target.value); setPage(1); }}
                className="h-10 px-3 rounded-xl border border-gray-300 text-sm focus:border-[#029bba] outline-none cursor-pointer bg-white"
              >
                <option value="">Any Status</option>
                <option value="true">Published</option>
                <option value="false">Unpublished</option>
              </select>

              <select
                value={isVerified}
                onChange={(e) => { setIsVerified(e.target.value); setPage(1); }}
                className="h-10 px-3 rounded-xl border border-gray-300 text-sm focus:border-[#029bba] outline-none cursor-pointer bg-white"
              >
                <option value="">Any</option>
                <option value="true">✓ Verified</option>
                <option value="false">Not Verified</option>
              </select>

              <select
                value={`${sortBy}:${sortOrder}`}
                onChange={(e) => {
                  const [field, order] = e.target.value.split(':');
                  setSortBy(field);
                  setSortOrder(order as 'asc' | 'desc');
                  setPage(1);
                }}
                className="h-10 px-3 rounded-xl border border-gray-300 text-sm focus:border-[#029bba] outline-none cursor-pointer bg-white"
              >
                <option value="createdAt:desc">Newest First</option>
                <option value="createdAt:asc">Oldest First</option>
                <option value="updatedAt:desc">Recently Updated</option>
                <option value="name:asc">Name (A-Z)</option>
                <option value="name:desc">Name (Z-A)</option>
                <option value="overallScore:desc">Highest Score</option>
                <option value="legalScore:desc">Best Legal Score</option>
                <option value="viewCount:desc">Most Viewed</option>
              </select>

              {activeFilterCount > 0 && (
                <button
                  onClick={handleClearFilters}
                  className="col-span-2 md:col-span-6 h-10 px-3 rounded-xl bg-red-50 text-[#ef4444] text-sm font-semibold hover:bg-red-100 transition-colors flex items-center justify-center gap-2"
                >
                  <X className="w-4 h-4" />
                  Clear All Filters ({activeFilterCount})
                </button>
              )}
            </div>
          </div>

          {/* ── TABLE ── */}
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden">
            <div className="px-4 py-3 border-b border-gray-100 flex items-center justify-between">
              <div className="text-sm text-gray-600">
                {loading ? (
                  'Loading...'
                ) : (
                  <>
                    Showing <strong className="text-gray-900">{societies.length}</strong> of{' '}
                    <strong className="text-gray-900">{pagination.total.toLocaleString()}</strong> societies
                  </>
                )}
              </div>
            </div>

            {loading ? (
              <div className="flex flex-col items-center justify-center py-20">
                <Loader2 className="w-10 h-10 text-[#029bba] animate-spin mb-3" />
                <p className="text-gray-600 text-sm">Loading societies...</p>
              </div>
            ) : societies.length === 0 ? (
              <div className="text-center py-16 px-4">
                <Building2 className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-lg font-bold text-gray-900 mb-2">No societies found</h3>
                <p className="text-gray-600 mb-6">
                  {activeFilterCount > 0 || search
                    ? 'Try adjusting filters or clearing them.'
                    : 'Get started by adding your first society.'}
                </p>
                <div className="flex items-center justify-center gap-2">
                  {activeFilterCount > 0 && (
                    <button
                      onClick={handleClearFilters}
                      className="px-4 py-2 rounded-xl bg-gray-100 text-gray-700 text-sm font-semibold hover:bg-gray-200 transition-colors"
                    >
                      Clear Filters
                    </button>
                  )}
                  <Link href="/admin/societies/new">
                    <button className="px-4 py-2 rounded-xl bg-[#029bba] text-white text-sm font-semibold hover:bg-[#027a94] transition-colors inline-flex items-center gap-2">
                      <Plus className="w-4 h-4" />
                      Add Society
                    </button>
                  </Link>
                </div>
              </div>
            ) : (
              <>
                {/* Desktop Table */}
                <div className="hidden lg:block overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="text-left py-3 px-4 font-semibold text-gray-700 text-xs uppercase tracking-wider">Society</th>
                        <th className="text-left py-3 px-3 font-semibold text-gray-700 text-xs uppercase tracking-wider">NOC</th>
                        <th className="text-left py-3 px-3 font-semibold text-gray-700 text-xs uppercase tracking-wider">Risk</th>
                        <th className="text-center py-3 px-3 font-semibold text-gray-700 text-xs uppercase tracking-wider">Score</th>
                        <th className="text-center py-3 px-3 font-semibold text-gray-700 text-xs uppercase tracking-wider">Alerts</th>
                        <th className="text-center py-3 px-3 font-semibold text-gray-700 text-xs uppercase tracking-wider">Status</th>
                        <th className="text-right py-3 px-4 font-semibold text-gray-700 text-xs uppercase tracking-wider">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {societies.map((s) => (
                        <SocietyRow
                          key={s._id}
                          society={s}
                          isLoading={actionLoadingId === s._id}
                          onToggle={(field) => handleQuickToggle(s, field)}
                          onDelete={() => setDeleteModal({ id: s._id, name: s.name })}
                        />
                      ))}
                    </tbody>
                  </table>
                </div>

                {/* Mobile Cards */}
                <div className="lg:hidden divide-y divide-gray-100">
                  {societies.map((s) => (
                    <SocietyCardMobile
                      key={s._id}
                      society={s}
                      isLoading={actionLoadingId === s._id}
                      onToggle={(field) => handleQuickToggle(s, field)}
                      onDelete={() => setDeleteModal({ id: s._id, name: s.name })}
                    />
                  ))}
                </div>

                {/* Pagination */}
                {pagination.pages > 1 && (
                  <div className="px-4 py-3 border-t border-gray-100 flex items-center justify-between">
                    <p className="text-sm text-gray-600">
                      Page <strong>{pagination.page}</strong> of{' '}
                      <strong>{pagination.pages}</strong>
                    </p>
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => setPage((p) => Math.max(1, p - 1))}
                        disabled={!pagination.hasPrev}
                        className="p-2 rounded-lg border border-gray-300 text-gray-700 disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50 transition-colors"
                        aria-label="Previous page"
                      >
                        <ChevronLeft className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => setPage((p) => p + 1)}
                        disabled={!pagination.hasNext}
                        className="p-2 rounded-lg border border-gray-300 text-gray-700 disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50 transition-colors"
                        aria-label="Next page"
                      >
                        <ChevronRight className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {/* ── DELETE MODAL ── */}
        {deleteModal && (
          <DeleteModal
            societyName={deleteModal.name}
            mode={deleteMode}
            onModeChange={setDeleteMode}
            isLoading={actionLoadingId === deleteModal.id}
            onConfirm={handleDelete}
            onCancel={() => {
              setDeleteModal(null);
              setDeleteMode('soft');
            }}
          />
        )}
      </AdminLayout>
    </>
  );
}

// ─── Stat Card ───────────────────────────────────────────────────────────────

interface StatCardProps {
  icon: React.ReactElement;
  label: string;
  value: number;
  color: string;
  onClick?: () => void;
}

function StatCard({ icon, label, value, color, onClick }: StatCardProps): React.ReactElement {
  return (
    <button
      onClick={onClick}
      className="bg-white rounded-2xl p-4 shadow-sm hover:shadow-md transition-all text-left group"
    >
      <div className="flex items-center justify-between mb-2">
        <div
          className="w-9 h-9 rounded-xl flex items-center justify-center text-white"
          style={{ backgroundColor: color }}
        >
          {icon}
        </div>
      </div>
      <div className="text-2xl font-extrabold text-gray-900 group-hover:text-[#029bba] transition-colors">
        {value.toLocaleString()}
      </div>
      <div className="text-xs text-gray-500 font-medium mt-0.5">{label}</div>
    </button>
  );
}

// ─── Society Row (Desktop) ───────────────────────────────────────────────────

interface SocietyRowProps {
  society: SocietyAdminListItem;
  isLoading: boolean;
  onToggle: (field: 'isPublished' | 'isVerifiedByHighrise' | 'isFeatured') => void;
  onDelete: () => void;
}

function SocietyRow({ society, isLoading, onToggle, onDelete }: SocietyRowProps): React.ReactElement {
