// ════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════

function formatPKR(amount?: number): string {
  if (!amount || amount <= 0) return '—';
  if (amount >= 10_000_000) {
    const crore = amount / 10_000_000;
    return `PKR ${crore % 1 === 0 ? crore.toFixed(0) : crore.toFixed(2)} Crore`;
  }
  if (amount >= 100_000) {
    const lac = amount / 100_000;
    return `${lac % 1 === 0 ? lac.toFixed(0) : lac.toFixed(1)} Lac`;
  }
  return `PKR ${amount.toLocaleString()}`;
}

function formatDate(dateStr?: string): string {
  if (!dateStr) return '—';
  return new Date(dateStr).toLocaleDateString('en-PK', {
    day: 'numeric', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}

function getStatusConfig(status: string): {
  label: string; bg: string; text: string; icon: React.ReactElement;
} {
  const configs: Record<string, { label: string; bg: string; text: string; icon: React.ReactElement }> = {
    available: { label: 'Available', bg: 'bg-emerald-100', text: 'text-emerald-700', icon: <CheckCircle2 className="w-4 h-4" /> },
    reserved:  { label: 'Reserved',  bg: 'bg-amber-100',   text: 'text-amber-700',   icon: <Clock className="w-4 h-4" /> },
    sold:      { label: 'Sold',      bg: 'bg-red-100',     text: 'text-red-700',     icon: <XCircle className="w-4 h-4" /> },
    on_hold:   { label: 'On Hold',   bg: 'bg-gray-100',    text: 'text-gray-600',    icon: <AlertCircle className="w-4 h-4" /> },
    cancelled: { label: 'Cancelled', bg: 'bg-gray-50',     text: 'text-gray-400',    icon: <XCircle className="w-4 h-4" /> },
  };
  return configs[status] ?? { label: status, bg: 'bg-gray-100', text: 'text-gray-600', icon: <AlertCircle className="w-4 h-4" /> };
}

function getFinishingLabel(level?: string): string {
  const labels: Record<string, string> = {
    grey_structure: 'Grey Structure',
    standard:       'Standard',
    premium:        'Premium',
    luxury:         'Luxury',
  };
  return level ? labels[level] ?? level : '';
}

function getFinishingColor(level?: string): string {
  const colors: Record<string, string> = {
    grey_structure: 'bg-gray-100 text-gray-600',
    standard:       'bg-blue-50 text-blue-600',
    premium:        'bg-purple-50 text-purple-600',
    luxury:         'bg-amber-50 text-amber-700',
  };
  return level ? colors[level] ?? 'bg-gray-100 text-gray-600' : '';
}

// ════════════════════════════════════════════════════
// BANNER
// ════════════════════════════════════════════════════

function Banner({
  type, message, onDismiss,
}: {
  type: 'success' | 'error';
  message: string;
  onDismiss: () => void;
}): React.ReactElement {
  useEffect(() => {
    const t = setTimeout(onDismiss, 5000);
    return () => clearTimeout(t);
  }, [onDismiss]);

  return (
    <div className={`fixed top-5 left-1/2 -translate-x-1/2 z-50
                     px-5 py-3 rounded-xl shadow-xl flex items-center gap-3
                     ${type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'}`}>
      {type === 'success'
        ? <CheckCircle2 className="w-5 h-5 flex-shrink-0" />
        : <AlertCircle className="w-5 h-5 flex-shrink-0" />
      }
      <p className="text-sm font-semibold">{message}</p>
      <button onClick={onDismiss} className="p-1 hover:bg-white/20 rounded-full">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

// ════════════════════════════════════════════════════
// IMAGE GALLERY
// ════════════════════════════════════════════════════

function ImageGallery({ images }: { images: AdminUnitDetail['images'] }): React.ReactElement {
  const [current, setCurrent] = useState(0);
  const allImages = images ?? [];

  if (allImages.length === 0) {
    return (
      <div className="aspect-video bg-gray-100 rounded-xl flex items-center justify-center">
        <div className="text-center">
          <Home className="w-10 h-10 text-gray-300 mx-auto mb-2" />
          <p className="text-xs text-gray-400">No images</p>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="relative aspect-video rounded-xl overflow-hidden bg-gray-100">
        <Image
          src={allImages[current].url}
          alt={allImages[current].caption ?? `Image ${current + 1}`}
          fill
          className="object-cover"
          sizes="(max-width: 768px) 100vw, 50vw"
          priority
        />
        {allImages.length > 1 && (
          <>
            <button
              onClick={() => setCurrent((p) => (p > 0 ? p - 1 : allImages.length - 1))}
              className="absolute left-2 top-1/2 -translate-y-1/2 p-2 rounded-full
                         bg-black/40 hover:bg-black/60 text-white transition-colors"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button
              onClick={() => setCurrent((p) => (p < allImages.length - 1 ? p + 1 : 0))}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-full
                         bg-black/40 hover:bg-black/60 text-white transition-colors"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
            <div className="absolute bottom-2 right-2 px-2.5 py-1 rounded-full
                            bg-black/50 text-white text-[10px] font-bold">
              {current + 1} / {allImages.length}
            </div>
          </>
        )}
        {allImages[current].isPrimary && (
          <div className="absolute top-2 left-2">
            <span className="px-2 py-0.5 rounded-full bg-[#029bba] text-white
                             text-[10px] font-bold flex items-center gap-0.5">
              <Star className="w-3 h-3" /> Primary
            </span>
          </div>
        )}
      </div>
      {allImages.length > 1 && (
        <div className="flex gap-1.5 mt-2 overflow-x-auto pb-1">
          {allImages.map((img, idx) => (
            <button
              key={idx}
              onClick={() => setCurrent(idx)}
              className={`relative w-12 h-12 rounded-lg overflow-hidden flex-shrink-0
                          border-2 transition-all
                          ${idx === current ? 'border-[#029bba]' : 'border-transparent opacity-60'}`}
            >
              <Image src={img.url} alt="" fill className="object-cover" sizes="48px" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// ════════════════════════════════════════════════════
// DETAIL ROW
// ════════════════════════════════════════════════════

function DetailRow({ icon, label, value, highlight }: {
  icon:      React.ReactElement;
  label:     string;
  value:     string | number | React.ReactElement | null | undefined;
  highlight?: boolean;
}): React.ReactElement | null {
  if (value === undefined || value === null || value === '') return null;
  return (
    <div className="flex items-center justify-between py-2 border-b border-gray-50 last:border-0">
      <div className="flex items-center gap-2">
        <span className="text-gray-400 flex-shrink-0">{icon}</span>
        <span className="text-xs text-gray-500 font-medium">{label}</span>
      </div>
      <span className={`text-sm font-semibold text-right ${highlight ? 'text-[#029bba]' : 'text-gray-800'}`}>
        {value}
      </span>
    </div>
  );
}

// ════════════════════════════════════════════════════
// SECTION HEADER
// ════════════════════════════════════════════════════

function SectionHeader({ icon, title }: { icon: React.ReactElement; title: string }): React.ReactElement {
  return (
    <div className="flex items-center gap-2 mb-3 mt-6">
      <span className="text-[#029bba]">{icon}</span>
      <h4 className="font-bold text-sm text-[#004063] uppercase tracking-wide">{title}</h4>
    </div>
  );
}

// ════════════════════════════════════════════════════
// ADMIN ACTION PANEL
// ════════════════════════════════════════════════════

function AdminActionPanel({
  unit,
  onUpdate,
  onTrash,
  onRestore,
  saving,
}: {
  unit:      AdminUnitDetail;
  onUpdate:  (data: Record<string, unknown>) => Promise<void>;
  onTrash:   (reason: string) => Promise<void>;
  onRestore: () => Promise<void>;
  saving:    boolean;
}): React.ReactElement {
  const [adminNotes, setAdminNotes]   = useState(unit.adminNotes ?? '');
  const [priceOverride, setPriceOverride] = useState<string>(unit.price ? String(unit.price) : '');
  const [trashReason, setTrashReason] = useState('');
  const [showTrash, setShowTrash]     = useState(false);
  const [showRestore, setShowRestore] = useState(false);

  return (
    <div className="space-y-4">

      {/* ── Toggle flags ── */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
        <h3 className="font-bold text-sm text-[#004063] mb-4 flex items-center gap-2">
          <Shield className="w-4 h-4 text-[#029bba]" />
          Unit Controls
        </h3>

        <div className="space-y-3">
          {/* Published */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Eye className="w-4 h-4 text-gray-400" />
              <div>
                <p className="text-sm font-semibold text-gray-700">Published</p>
                <p className="text-[10px] text-gray-400">Visible on public pages</p>
              </div>
            </div>
            <button
              onClick={() => onUpdate({ isPublished: !unit.isPublished })}
              disabled={saving}
              className={`relative w-12 h-6 rounded-full transition-colors
                          ${unit.isPublished ? 'bg-emerald-500' : 'bg-gray-200'}`}
            >
              <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow
                               transition-transform
                               ${unit.isPublished ? 'translate-x-6' : 'translate-x-0.5'}`} />
            </button>
          </div>

          {/* Verified */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <BadgeCheck className="w-4 h-4 text-gray-400" />
              <div>
                <p className="text-sm font-semibold text-gray-700">Verified</p>
                <p className="text-[10px] text-gray-400">Admin-verified unit</p>
              </div>
            </div>
            <button
              onClick={() => onUpdate({ isVerified: !unit.isVerified, ...((!unit.isVerified && !unit.isPublished) ? { isPublished: true } : {}) })}
              disabled={saving}
              className={`relative w-12 h-6 rounded-full transition-colors
                          ${unit.isVerified ? 'bg-[#029bba]' : 'bg-gray-200'}`}
            >
              <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow
                               transition-transform
                               ${unit.isVerified ? 'translate-x-6' : 'translate-x-0.5'}`} />
            </button>
          </div>

          {/* Featured */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Star className="w-4 h-4 text-gray-400" />
              <div>
                <p className="text-sm font-semibold text-gray-700">Featured</p>
                <p className="text-[10px] text-gray-400">Highlighted in listings</p>
              </div>
            </div>
            <button
              onClick={() => onUpdate({ isFeatured: !unit.isFeatured })}
              disabled={saving}
              className={`relative w-12 h-6 rounded-full transition-colors
                          ${unit.isFeatured ? 'bg-amber-500' : 'bg-gray-200'}`}
            >
              <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow
                               transition-transform
                               ${unit.isFeatured ? 'translate-x-6' : 'translate-x-0.5'}`} />
            </button>
          </div>

          {/* Hot Deal */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <TrendingDown className="w-4 h-4 text-gray-400" />
              <div>
                <p className="text-sm font-semibold text-gray-700">Hot Deal</p>
                <p className="text-[10px] text-gray-400">Show hot deal badge</p>
              </div>
            </div>
            <button
              onClick={() => onUpdate({ isHotDeal: !unit.isHotDeal })}
              disabled={saving}
              className={`relative w-12 h-6 rounded-full transition-colors
                          ${unit.isHotDeal ? 'bg-red-500' : 'bg-gray-200'}`}
            >
              <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow
                               transition-transform
                               ${unit.isHotDeal ? 'translate-x-6' : 'translate-x-0.5'}`} />
            </button>
          </div>
        </div>
      </div>

      {/* ── Status override ── */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
        <h3 className="font-bold text-sm text-[#004063] mb-3 flex items-center gap-2">
          <Activity className="w-4 h-4 text-[#029bba]" />
          Status Override
        </h3>
        <div className="grid grid-cols-2 gap-2">
          {['available', 'reserved', 'sold', 'on_hold', 'cancelled'].map((s) => {
            const cfg = getStatusConfig(s);
            return (
              <button
                key={s}
                onClick={() => unit.status !== s && onUpdate({ status: s })}
                disabled={saving || unit.status === s}
                className={`px-3 py-2 rounded-xl text-xs font-bold transition-all
                            ${unit.status === s
                              ? `${cfg.bg} ${cfg.text} ring-2 ring-offset-1 ring-current`
                              : 'bg-gray-50 text-gray-500 hover:bg-gray-100'
                            }`}
              >
                {cfg.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* ── Price override ── */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
        <h3 className="font-bold text-sm text-[#004063] mb-3 flex items-center gap-2">
          <DollarSign className="w-4 h-4 text-[#029bba]" />
          Price Override
        </h3>
        <div className="flex items-center gap-2">
          <input
            type="number"
            value={priceOverride}
            onChange={(e) => setPriceOverride(e.target.value)}
            placeholder="Enter new price"
            className="flex-1 px-3 py-2.5 rounded-xl border border-gray-200
                       text-sm focus:border-[#029bba] focus:ring-1 focus:ring-[#029bba]
                       outline-none transition-colors"
          />
          <button
            onClick={() => {
              const p = Number(priceOverride);
              if (p > 0) onUpdate({ price: p });
            }}
            disabled={saving || !priceOverride || Number(priceOverride) <= 0}
            className="px-4 py-2.5 rounded-xl bg-[#029bba] text-white text-sm
                       font-semibold hover:bg-[#027a94] disabled:opacity-50 transition-colors"
          >
            {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
          </button>
        </div>
        {priceOverride && Number(priceOverride) > 0 && (
          <p className="text-[10px] text-[#029bba] mt-1 font-semibold">
            {formatPKR(Number(priceOverride))}
          </p>
        )}
      </div>

      {/* ── Admin notes ── */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
        <h3 className="font-bold text-sm text-[#004063] mb-3 flex items-center gap-2">
          <FileText className="w-4 h-4 text-[#029bba]" />
          Admin Notes
        </h3>
        <textarea
          value={adminNotes}
          onChange={(e) => setAdminNotes(e.target.value)}
          maxLength={2000}
          rows={3}
          placeholder="Internal notes — not visible to developers or public..."
          className="w-full px-3 py-2.5 rounded-xl border border-gray-200
                     text-sm resize-none focus:border-[#029bba] focus:ring-1
                     focus:ring-[#029bba] outline-none transition-colors"
        />
        <div className="flex items-center justify-between mt-2">
          <p className="text-[10px] text-gray-400">{adminNotes.length}/2000</p>
          <button
            onClick={() => onUpdate({ adminNotes })}
            disabled={saving}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg
                       bg-gray-100 hover:bg-gray-200 text-gray-700
                       text-xs font-semibold transition-colors"
          >
            {saving ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />}
            Save Notes
          </button>
        </div>
      </div>

      {/* ── Danger zone ── */}
      <div className="bg-red-50 rounded-2xl border border-red-100 p-4">
        <h3 className="font-bold text-sm text-red-700 mb-3 flex items-center gap-2">
          <AlertTriangle className="w-4 h-4" />
          Danger Zone
        </h3>

        {!unit.isDeleted ? (
          <>
            {!showTrash ? (
              <button
                onClick={() => setShowTrash(true)}
                className="w-full flex items-center justify-center gap-2 px-4 py-2.5
                           rounded-xl border-2 border-red-300 text-red-600
                           text-sm font-semibold hover:bg-red-100 transition-colors"
              >
                <Trash2 className="w-4 h-4" />
                Delete Unit
              </button>
            ) : (
              <div className="space-y-2">
                <p className="text-xs text-red-600 font-medium">
                  Provide a reason for deletion:
                </p>
                <textarea
                  value={trashReason}
                  onChange={(e) => setTrashReason(e.target.value)}
                  maxLength={500}
                  rows={2}
                  placeholder="Reason for deletion (min 5 characters)..."
                  className="w-full px-3 py-2 rounded-xl border border-red-200
                             text-xs resize-none focus:border-red-400 outline-none"
                />
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => { setShowTrash(false); setTrashReason(''); }}
                    className="flex-1 px-3 py-2 rounded-xl border border-gray-200
                               text-xs font-semibold text-gray-700 hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={() => {
                      if (trashReason.trim().length >= 5) {
                        onTrash(trashReason.trim());
                        setShowTrash(false);
                      }
                    }}
                    disabled={saving || trashReason.trim().length < 5}
                    className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2
                               rounded-xl bg-red-500 text-white text-xs font-semibold
                               hover:bg-red-600 disabled:opacity-50"
                  >
                    {saving ? <Loader2 className="w-3 h-3 animate-spin" /> : <Trash2 className="w-3 h-3" />}
                    Confirm Delete
                  </button>
                </div>
              </div>
            )}
          </>
        ) : (
          <>
            <div className="p-3 rounded-xl bg-red-100 border border-red-200 mb-3">
              <p className="text-xs font-bold text-red-700 flex items-center gap-1.5">
                <Trash2 className="w-3.5 h-3.5" />
                This unit is deleted
              </p>
              {unit.deletedAt && (
                <p className="text-[10px] text-red-500 mt-0.5">
                  Deleted on {formatDate(unit.deletedAt)}
                </p>
              )}
            </div>

            {!showRestore ? (
              <button
                onClick={() => setShowRestore(true)}
                className="w-full flex items-center justify-center gap-2 px-4 py-2.5
                           rounded-xl border-2 border-blue-300 text-blue-600
                           text-sm font-semibold hover:bg-blue-50 transition-colors"
              >
                <RotateCcw className="w-4 h-4" />
                Restore Unit
              </button>
            ) : (
              <div className="space-y-2">
                <p className="text-xs text-blue-600 font-medium">
                  Unit will be restored as unpublished. Confirm?
                </p>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => setShowRestore(false)}
                    className="flex-1 px-3 py-2 rounded-xl border border-gray-200
                               text-xs font-semibold text-gray-700 hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={() => { onRestore(); setShowRestore(false); }}
                    disabled={saving}
                    className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2
                               rounded-xl bg-blue-500 text-white text-xs font-semibold
                               hover:bg-blue-600 disabled:opacity-50"
                  >
                    {saving ? <Loader2 className="w-3 h-3 animate-spin" /> : <RotateCcw className="w-3 h-3" />}
                    Restore
                  </button>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════
// MAIN PAGE
// ════════════════════════════════════════════════════

export default function AdminUnitDetailPage(): React.ReactElement {
  const router      = useRouter();
  const { id }      = router.query;

  const [unit, setUnit]       = useState<AdminUnitDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving]   = useState(false);
  const [banner, setBanner]   = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  // ── Fetch unit ──
  const fetchUnit = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setLoading(true);
    try {
      const res  = await fetch(`/api/admin/units/${id}`, { credentials: 'include' });
      const data = await res.json();
      if (data.success && data.data?.unit) {
        setUnit(data.data.unit as AdminUnitDetail);
      } else {
        setBanner({ type: 'error', message: data.message ?? 'Unit not found' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Failed to load unit. Please try again.' });
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => {
    fetchUnit();
  }, [fetchUnit]);

  // ── Update unit ──
  const handleUpdate = useCallback(async (data: Record<string, unknown>) => {
    if (!id) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/admin/units/${id}`, {
        method:      'PATCH',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
        body:        JSON.stringify(data),
      });
      const result = await res.json();
      if (result.success) {
        setBanner({ type: 'success', message: 'Unit updated successfully' });
        // Update local state immediately
        setUnit((prev) => prev ? { ...prev, ...data } as AdminUnitDetail : prev);
      } else {
        setBanner({ type: 'error', message: result.message ?? 'Update failed' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Update failed. Please try again.' });
    } finally {
      setSaving(false);
    }
  }, [id]);

  // ── Trash unit ──
  const handleTrash = useCallback(async (reason: string) => {
    if (!id) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/admin/units/${id}`, {
        method:      'DELETE',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
        body:        JSON.stringify({ reason }),
      });
      const result = await res.json();
      if (result.success) {
        setBanner({ type: 'success', message: 'Unit deleted successfully' });
        setUnit((prev) => prev ? { ...prev, isDeleted: true, deletedAt: new Date().toISOString() } : prev);
      } else {
        setBanner({ type: 'error', message: result.message ?? 'Delete failed' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Delete failed. Please try again.' });
    } finally {
      setSaving(false);
    }
  }, [id]);

  // ── Restore unit ──
  const handleRestore = useCallback(async () => {
    if (!id) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/admin/units/${id}`, {
        method:      'PUT',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
        body:        JSON.stringify({ reason: 'Restored by admin' }),
      });
      const result = await res.json();
      if (result.success) {
        setBanner({ type: 'success', message: 'Unit restored successfully' });
        setUnit((prev) => prev
          ? { ...prev, isDeleted: false, deletedAt: undefined, isPublished: false }
          : prev
        );
      } else {
        setBanner({ type: 'error', message: result.message ?? 'Restore failed' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Restore failed. Please try again.' });
    } finally {
      setSaving(false);
    }
  }, [id]);

  // ── Loading ──
  if (loading) {
    return (
      <AdminLayout>
        <div className="flex items-center justify-center py-24">
          <Loader2 className="w-10 h-10 text-[#029bba] animate-spin" />
        </div>
      </AdminLayout>
    );
  }

  // ── Not found ──
  if (!unit) {
    return (
      <AdminLayout>
        <div className="text-center py-24">
          <AlertCircle className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-gray-700 mb-2">Unit Not Found</h2>
          <p className="text-gray-400 mb-6">This unit does not exist or has been permanently deleted.</p>
          <Link
            href="/admin/units"
            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl
                       bg-[#029bba] text-white text-sm font-semibold
                       hover:bg-[#027a94] transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to Units
          </Link>
        </div>
      </AdminLayout>
    );
  }

  const statusConfig = getStatusConfig(unit.status);

  return (
    <AdminLayout>
      <Head>
        <title>Unit #{unit.unitNumber} | Highrise.pk Admin</title>
        <meta name="robots" content="noindex, nofollow" />
      </Head>

      {/* Banner */}
      {banner && (
        <Banner
          type={banner.type}
          message={banner.message}
          onDismiss={() => setBanner(null)}
        />
      )}

      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center gap-3 mb-3">
          <Link
            href="/admin/units"
            className="inline-flex items-center gap-1.5 text-sm text-gray-500
                       hover:text-[#029bba] transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            All Units
          </Link>
          {unit.projectId && (
            <>
              <span className="text-gray-300">/</span>
              <Link
                href={`/admin/projects/${unit.projectId._id}`}
                className="text-sm text-gray-500 hover:text-[#029bba] transition-colors truncate max-w-[200px]"
              >
                {unit.projectId.projectName}
              </Link>
            </>
          )}
        </div>

        <div className="flex items-start justify-between flex-wrap gap-4">
          <div>
            {/* Status + deleted badge */}
            <div className="flex items-center gap-2 mb-2">
              <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full
                                text-xs font-bold ${statusConfig.bg} ${statusConfig.text}`}>
                {statusConfig.icon}
                {statusConfig.label}
              </span>
              {unit.isDeleted && (
                <span className="px-3 py-1 rounded-full bg-red-100 text-red-700
                                 text-xs font-bold flex items-center gap-1">
                  <Trash2 className="w-3 h-3" /> Deleted
                </span>
              )}
              {unit.isVerified && (
                <span className="px-2 py-0.5 rounded-full bg-[#029bba]/10 text-[#029bba]
                                 text-[10px] font-bold flex items-center gap-0.5">
                  <BadgeCheck className="w-3 h-3" /> Verified
                </span>
              )}
              {unit.isFeatured && (
                <span className="px-2 py-0.5 rounded-full bg-amber-100 text-amber-700
                                 text-[10px] font-bold flex items-center gap-0.5">
                  <Star className="w-3 h-3" /> Featured
                </span>
              )}
            </div>

            <h1 className="text-2xl font-black text-[#004063]">
              Unit #{unit.unitNumber}
            </h1>
            {unit.title && unit.title !== `Unit ${unit.unitNumber}` && (
              <p className="text-sm text-gray-500 mt-0.5">{unit.title}</p>
            )}

            {/* Breadcrumb info */}
            <div className="flex flex-wrap items-center gap-4 mt-2 text-xs text-gray-400">
              {unit.projectId && (
                <span className="flex items-center gap-1">
                  <Building2 className="w-3.5 h-3.5" />
                  {unit.projectId.projectName}
                </span>
              )}
              {unit.projectId?.city && (
                <span className="flex items-center gap-1">
                  <MapPin className="w-3.5 h-3.5" />
                  {unit.projectId.city}
                </span>
              )}
              {unit.developerId && (
                <span className="flex items-center gap-1">
                  <Building2 className="w-3.5 h-3.5" />
                  {unit.developerId.companyName}
                </span>
              )}
            </div>
          </div>

          {/* Quick actions */}
          <div className="flex items-center gap-2">
            <button
              onClick={fetchUnit}
              className="p-2.5 rounded-xl border border-gray-200 text-gray-500
                         hover:text-[#029bba] hover:border-[#029bba]/30 transition-colors"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
            {unit.projectId?.slug && unit.slug && (
              <a
                href={`/projects/${unit.projectId.slug}/units/${unit.slug}`}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl
                           border border-gray-200 text-gray-600 text-sm font-semibold
                           hover:bg-gray-50 transition-colors"
              >
                <Eye className="w-4 h-4" />
                View Live
              </a>
            )}
          </div>
        </div>
      </div>

      {/* Main grid — 2 columns */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* ── Left column (details) ── */}
        <div className="lg:col-span-2 space-y-6">

          {/* Gallery */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
            <ImageGallery images={unit.images} />

            {/* Floor plan + layout */}
            {(unit.floorPlanImage || unit.layoutImage) && (
              <div className="flex gap-3 mt-3">
                {unit.floorPlanImage && (
                  <div className="flex-1">
                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Floor Plan</p>
                    <div className="relative aspect-video rounded-xl overflow-hidden bg-gray-100">
                      <Image
                        src={unit.floorPlanImage.url}
                        alt="Floor Plan"
                        fill
                        className="object-contain"
                        sizes="50vw"
                      />
                    </div>
                  </div>
                )}
                {unit.layoutImage && (
                  <div className="flex-1">
                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Layout</p>
                    <div className="relative aspect-video rounded-xl overflow-hidden bg-gray-100">
                      <Image
                        src={unit.layoutImage.url}
                        alt="Layout"
                        fill
                        className="object-contain"
                        sizes="50vw"
                      />
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Price section */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
            <div className="flex items-baseline gap-3 flex-wrap mb-3">
              <span className="text-3xl font-black text-[#029bba]">
                {formatPKR(unit.price)}
              </span>
              {unit.previousPrice && unit.previousPrice > unit.price && (
                <span className="text-xl text-gray-400 line-through">
                  {formatPKR(unit.previousPrice)}
                </span>
              )}
            </div>

            <div className="flex flex-wrap gap-3">
              {unit.pricePerUnit && (
                <span className="text-xs text-gray-500">
                  {formatPKR(unit.pricePerUnit)} / {unit.areaUnit ?? 'sqft'}
                </span>
              )}
              {unit.priceNegotiable && (
                <span className="px-2 py-0.5 rounded-full bg-green-50 text-green-600
                                 text-[10px] font-bold flex items-center gap-0.5">
                  <CheckCircle2 className="w-3 h-3" /> Negotiable
                </span>
              )}
              {unit.isPriceDropped && (
                <span className="px-2 py-0.5 rounded-full bg-green-100 text-green-700
                                 text-[10px] font-bold flex items-center gap-0.5">
                  <TrendingDown className="w-3 h-3" /> Price Dropped
                </span>
              )}
              {unit.listingType && (
                <span className="px-2 py-0.5 rounded-full bg-gray-100 text-gray-600
                                 text-[10px] font-bold flex items-center gap-0.5">
                  <Tag className="w-3 h-3" />
                  {unit.listingType === 'installment' ? 'Installment' :
                   unit.listingType === 'full_payment' ? 'Full Payment' :
                   unit.listingType === 'both' ? 'Cash + Installment' :
                   unit.listingType === 'pre_launch' ? 'Pre-Launch' :
                   unit.listingType}
                </span>
              )}
            </div>
          </div>

          {/* Core details */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">

            <SectionHeader icon={<Maximize2 className="w-4 h-4" />} title="Size & Location" />
            <div className="rounded-xl border border-gray-100 px-4">
              <DetailRow icon={<Maximize2 className="w-3.5 h-3.5" />} label="Total Area"
                         value={`${unit.area.toLocaleString()} ${unit.areaUnit ?? 'Sq.Ft'}`} highlight />
              {unit.coveredArea && (
                <DetailRow icon={<Maximize2 className="w-3.5 h-3.5" />} label="Covered Area"
                           value={`${unit.coveredArea.toLocaleString()} ${unit.areaUnit ?? 'Sq.Ft'}`} />
              )}
              {unit.carpetArea && (
                <DetailRow icon={<Maximize2 className="w-3.5 h-3.5" />} label="Carpet Area"
                           value={`${unit.carpetArea.toLocaleString()} ${unit.areaUnit ?? 'Sq.Ft'}`} />
              )}
              {unit.floorName && (
                <DetailRow icon={<Layers className="w-3.5 h-3.5" />} label="Floor"
                           value={unit.floorName} />
              )}
              {unit.floorNumber !== undefined && !unit.floorName && (
                <DetailRow icon={<Layers className="w-3.5 h-3.5" />} label="Floor Number"
                           value={`Floor ${unit.floorNumber}`} />
              )}
              {unit.tower && (
                <DetailRow icon={<Building2 className="w-3.5 h-3.5" />} label="Tower"
                           value={unit.tower} />
              )}
              {unit.wing && (
                <DetailRow icon={<Building2 className="w-3.5 h-3.5" />} label="Wing"
                           value={unit.wing} />
              )}
              {unit.isCorner && (
                <DetailRow icon={<CornerDownRight className="w-3.5 h-3.5" />} label="Corner Unit"
                           value="Yes" />
              )}
              {unit.facing && (
                <DetailRow icon={<Compass className="w-3.5 h-3.5" />} label="Facing"
                           value={unit.facing.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase())} />
              )}
              {unit.view && (
                <DetailRow icon={<Mountain className="w-3.5 h-3.5" />} label="View"
                           value={unit.view.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase())} />
              )}
              {unit.finishingLevel && (
                <DetailRow icon={<Sparkles className="w-3.5 h-3.5" />} label="Finishing"
                           value={
                             <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold
                                               ${getFinishingColor(unit.finishingLevel)}`}>
                               {getFinishingLabel(unit.finishingLevel)}
                             </span>
                           } />
              )}
            </div>

            {/* Room config */}
            {(unit.bedrooms || unit.bathrooms || unit.livingRooms || unit.kitchens) && (
              <>
                <SectionHeader
                  icon={unit.category === 'commercial'
                    ? <Store className="w-4 h-4" />
                    : <Home className="w-4 h-4" />
                  }
                  title="Room Configuration"
                />
                <div className="rounded-xl border border-gray-100 px-4">
                  {unit.bedrooms !== undefined && unit.bedrooms > 0 && (
                    <DetailRow icon={<Bed className="w-3.5 h-3.5" />} label="Bedrooms" value={unit.bedrooms} />
                  )}
                  {unit.bathrooms !== undefined && unit.bathrooms > 0 && (
                    <DetailRow icon={<Bath className="w-3.5 h-3.5" />} label="Bathrooms" value={unit.bathrooms} />
                  )}
                  {unit.livingRooms !== undefined && unit.livingRooms > 0 && (
                    <DetailRow icon={<Home className="w-3.5 h-3.5" />} label="Living Rooms" value={unit.livingRooms} />
                  )}
                  {unit.kitchens !== undefined && unit.kitchens > 0 && (
                    <DetailRow icon={<Home className="w-3.5 h-3.5" />} label="Kitchens" value={unit.kitchens} />
                  )}
                  {unit.servantQuarter && (
                    <DetailRow icon={<Home className="w-3.5 h-3.5" />} label="Servant Quarter" value="Yes" />
                  )}
                  {unit.storeRoom && (
                    <DetailRow icon={<Home className="w-3.5 h-3.5" />} label="Store Room" value="Yes" />
                  )}
                  {unit.cabins !== undefined && unit.cabins > 0 && (
                    <DetailRow icon={<Store className="w-3.5 h-3.5" />} label="Cabins" value={unit.cabins} />
                  )}
                  {unit.seatingCapacity !== undefined && unit.seatingCapacity > 0 && (
                    <DetailRow icon={<Store className="w-3.5 h-3.5" />} label="Seating Capacity" value={unit.seatingCapacity} />
                  )}
                </div>
              </>
            )}

            {/* Parking */}
            {unit.parkingIncluded && (
              <>
                <SectionHeader icon={<Car className="w-4 h-4" />} title="Parking" />
                <div className="rounded-xl border border-gray-100 px-4">
                  <DetailRow icon={<Car className="w-3.5 h-3.5" />} label="Parking Spaces"
                             value={unit.parkingSpaces ? `${unit.parkingSpaces} Space(s)` : 'Included'} />
                  {unit.parkingType && (
                    <DetailRow icon={<Car className="w-3.5 h-3.5" />} label="Parking Type"
                               value={unit.parkingType.replace(/\b\w/g, (l) => l.toUpperCase())} />
                  )}
                </div>
              </>
            )}

            {/* Features */}
            {unit.features && unit.features.length > 0 && (
              <>
                <SectionHeader icon={<CheckCircle2 className="w-4 h-4" />} title="Features" />
                <div className="flex flex-wrap gap-1.5">
                  {unit.features.map((f, idx) => (
                    <span key={idx} className="px-2.5 py-1 rounded-full bg-gray-50 border border-gray-100
                                               text-xs text-gray-600 font-medium">
                      {f}
                    </span>
                  ))}
                </div>
              </>
            )}

            {/* Description */}
            {unit.description && (
              <>
                <SectionHeader icon={<FileText className="w-4 h-4" />} title="Description" />
                <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-line">
                  {unit.description}
                </p>
              </>
            )}
          </div>

          {/* Booking / Sold info */}
          {(unit.bookingInfo || unit.soldInfo) && (
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
              {unit.bookingInfo && unit.status === 'reserved' && (
                <>
                  <SectionHeader icon={<Clock className="w-4 h-4" />} title="Booking Information" />
                  <div className="rounded-xl border border-amber-100 bg-amber-50 px-4">
                    <DetailRow icon={<Clock className="w-3.5 h-3.5" />} label="Reserved By"
                               value={unit.bookingInfo.reservedByName ?? '—'} />
                    <DetailRow icon={<Clock className="w-3.5 h-3.5" />} label="Phone"
                               value={unit.bookingInfo.reservedByPhone ?? '—'} />
                    <DetailRow icon={<Clock className="w-3.5 h-3.5" />} label="Reserved On"
                               value={formatDate(unit.bookingInfo.reservedOn)} />
                    <DetailRow icon={<Clock className="w-3.5 h-3.5" />} label="Reserved Until"
                               value={formatDate(unit.bookingInfo.reservedUntil)} />
                    {unit.bookingInfo.reservationAmount && (
                      <DetailRow icon={<DollarSign className="w-3.5 h-3.5" />} label="Booking Amount"
                                 value={formatPKR(unit.bookingInfo.reservationAmount)} highlight />
                    )}
                    {unit.bookingInfo.reservationExpired && (
                      <div className="py-2">
                        <span className="px-2 py-0.5 rounded-full bg-red-100 text-red-600
                                         text-[10px] font-bold">
                          Reservation Expired
                        </span>
                      </div>
                    )}
                  </div>
                </>
              )}

              {unit.soldInfo && unit.status === 'sold' && (
                <>
                  <SectionHeader icon={<CheckCircle2 className="w-4 h-4" />} title="Sale Information" />
                  <div className="rounded-xl border border-red-100 bg-red-50 px-4">
                    <DetailRow icon={<CheckCircle2 className="w-3.5 h-3.5" />} label="Sold To"
                               value={unit.soldInfo.soldToName ?? '—'} />
                    <DetailRow icon={<CheckCircle2 className="w-3.5 h-3.5" />} label="Sold On"
                               value={formatDate(unit.soldInfo.soldOn)} />
                    <DetailRow icon={<DollarSign className="w-3.5 h-3.5" />} label="Sold Price"
                               value={formatPKR(unit.soldInfo.soldPrice)} highlight />
                    {unit.soldInfo.paymentMethod && (
                      <DetailRow icon={<Tag className="w-3.5 h-3.5" />} label="Payment Method"
                                 value={unit.soldInfo.paymentMethod.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase())} />
                    )}
                    {unit.soldInfo.saleNotes && (
                      <div className="py-2">
                        <p className="text-xs text-gray-500 font-medium mb-0.5">Sale Notes</p>
                        <p className="text-sm text-gray-700">{unit.soldInfo.saleNotes}</p>
                      </div>
                    )}
                  </div>
                </>
              )}
            </div>
          )}

          {/* Analytics */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
            <SectionHeader icon={<Activity className="w-4 h-4" />} title="Analytics & Audit" />
            <div className="grid grid-cols-3 gap-3 mb-4">
              <div className="p-3 rounded-xl bg-cyan-50 border border-cyan-100 text-center">
                <Eye className="w-5 h-5 text-cyan-600 mx-auto mb-1" />
                <p className="text-xl font-black text-cyan-700">{unit.views}</p>
                <p className="text-[10px] text-cyan-500 font-semibold">Views</p>
              </div>
              <div className="p-3 rounded-xl bg-amber-50 border border-amber-100 text-center">
                <MessageSquare className="w-5 h-5 text-amber-600 mx-auto mb-1" />
                <p className="text-xl font-black text-amber-700">{unit.inquiryCount}</p>
                <p className="text-[10px] text-amber-500 font-semibold">Inquiries</p>
              </div>
              <div className="p-3 rounded-xl bg-pink-50 border border-pink-100 text-center">
                <Star className="w-5 h-5 text-pink-600 mx-auto mb-1" />
                <p className="text-xl font-black text-pink-700">{unit.favoriteCount ?? 0}</p>
                <p className="text-[10px] text-pink-500 font-semibold">Favorites</p>
              </div>
            </div>

            <div className="rounded-xl border border-gray-100 px-4">
              <DetailRow icon={<Calendar className="w-3.5 h-3.5" />} label="Created"
                         value={formatDate(unit.createdAt)} />
              <DetailRow icon={<Calendar className="w-3.5 h-3.5" />} label="Last Updated"
                         value={formatDate(unit.updatedAt)} />
              {unit.lastStatusChangedAt && (
                <DetailRow icon={<Activity className="w-3.5 h-3.5" />} label="Status Changed"
                           value={formatDate(unit.lastStatusChangedAt)} />
              )}
              {unit.lastPriceChangedAt && (
                <DetailRow icon={<DollarSign className="w-3.5 h-3.5" />} label="Price Changed"
                           value={formatDate(unit.lastPriceChangedAt)} />
              )}
            </div>

            {/* Admin notes display */}
            {unit.adminNotes && (
              <div className="mt-4 p-3 rounded-xl bg-yellow-50 border border-yellow-100">
                <p className="text-[10px] font-bold text-yellow-700 uppercase mb-1 flex items-center gap-1">
                  <FileText className="w-3 h-3" /> Admin Notes
                </p>
                <p className="text-xs text-yellow-800 whitespace-pre-line">{unit.adminNotes}</p>
              </div>
            )}
          </div>
        </div>

        {/* ── Right column (admin controls) ── */}
        <div className="space-y-4">

          {/* Unit summary card */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
            <div className="flex items-center gap-3 mb-3">
              <div className="w-10 h-10 rounded-xl bg-[#029bba]/10 flex items-center justify-center">
                {unit.category === 'commercial'
                  ? <Store className="w-5 h-5 text-[#029bba]" />
                  : <Home className="w-5 h-5 text-[#029bba]" />
                }
              </div>
              <div>
                <p className="font-bold text-sm text-gray-900">
                  {unit.unitTypeName ?? unit.unitType.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase())}
                </p>
                <p className="text-[10px] text-gray-400 capitalize">{unit.category}</p>
              </div>
            </div>

            {/* Published status */}
            <div className={`flex items-center gap-2 px-3 py-2 rounded-xl
                             ${unit.isPublished
                               ? 'bg-emerald-50 border border-emerald-100'
                               : 'bg-gray-50 border border-gray-200'
                             }`}>
              {unit.isPublished
                ? <Eye className="w-4 h-4 text-emerald-600" />
                : <EyeOff className="w-4 h-4 text-gray-400" />
              }
              <span className={`text-xs font-bold
                                ${unit.isPublished ? 'text-emerald-700' : 'text-gray-500'}`}>
                {unit.isPublished ? 'Published — visible to public' : 'Unpublished — hidden from public'}
              </span>
            </div>
          </div>

          {/* Admin action panel */}
          <AdminActionPanel
            unit={unit}
            onUpdate={handleUpdate}
            onTrash={handleTrash}
            onRestore={handleRestore}
            saving={saving}
          />

          {/* Quick links */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
            <h3 className="font-bold text-sm text-[#004063] mb-3">Quick Links</h3>
            <div className="space-y-2">
              {unit.projectId && (
                <Link
                  href={`/admin/projects/${unit.projectId._id}`}
                  className="flex items-center gap-2 p-2.5 rounded-xl hover:bg-gray-50
                             text-sm text-gray-700 hover:text-[#029bba] transition-colors"
                >
                  <Building2 className="w-4 h-4 text-gray-400" />
                  View Project
                </Link>
              )}
              {unit.developerId?.slug && (
                <Link
                  href={`/admin/developers/${unit.developerId._id ?? ''}`}
                  className="flex items-center gap-2 p-2.5 rounded-xl hover:bg-gray-50
                             text-sm text-gray-700 hover:text-[#029bba] transition-colors"
                >
                  <Building2 className="w-4 h-4 text-gray-400" />
                  View Developer
                </Link>
              )}
              <Link
                href="/admin/units"
                className="flex items-center gap-2 p-2.5 rounded-xl hover:bg-gray-50
                           text-sm text-gray-700 hover:text-[#029bba] transition-colors"
              >
                <ArrowLeft className="w-4 h-4 text-gray-400" />
                Back to All Units
              </Link>
            </div>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}

// pages/admin/units/index.tsx
import React, { useState, useEffect, useCallback, useRef } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import Image from 'next/image';
import { useSession } from 'next-auth/react';
import {
  Home,
  Store,
  Search,
  Filter,
  ChevronDown,
  ChevronUp,
  Eye,
  MessageSquare,
  CheckCircle2,
  XCircle,
  Clock,
  Loader2,
  AlertCircle,
  X,
  Star,
  Shield,
  Trash2,
  RotateCcw,
  ArrowUpDown,
  Building2,
  MapPin,
  Layers,
  TrendingDown,
  Package,
  RefreshCw,
  Download,
  MoreVertical,
  BadgeCheck,
  EyeOff,
} from 'lucide-react';
import AdminLayout from '@/components/admin/AdminLayout';

// ════════════════════════════════════════════════════
// TYPES
// ════════════════════════════════════════════════════

interface AdminUnit {
  _id:           string;
  unitNumber:    string;
  title?:        string;
  unitType:      string;
  unitTypeName?: string;
  category:      string;
  status:        string;
  isPublished:   boolean;
  isVerified:    boolean;
  isFeatured:    boolean;
  isHotDeal:     boolean;
  isPriceDropped: boolean;
  price:         number;
  area:          number;
  areaUnit?:     string;
  bedrooms?:     number;
  bathrooms?:    number;
  floorNumber?:  number;
  floorName?:    string;
  tower?:        string;
  isCorner?:     boolean;
  views?:        number;
  inquiryCount?: number;
  isDeleted?:    boolean;
  deletedAt?:    string;
  createdAt:     string;
  updatedAt:     string;
  images?:       Array<{ url: string; isPrimary?: boolean }>;
  projectId?: {
    _id:         string;
    projectName: string;
    slug:        string;
    city?:       string;
  };
  developerId?: {
    companyName: string;
    email:       string;
  };
}

interface AdminStats {
  totalUnits:     number;
  availableUnits: number;
  reservedUnits:  number;
  soldUnits:      number;
  onHoldUnits:    number;
  publishedUnits: number;
  verifiedUnits:  number;
  featuredUnits:  number;
  deletedUnits:   number;
  totalViews:     number;
  totalInquiries: number;
  avgPrice:       number;
  minPrice:       number;
  maxPrice:       number;
}

interface Pagination {
  page:       number;
  limit:      number;
  totalCount: number;
  totalPages: number;
  hasMore:    boolean;
}

type BulkAction = 'publish' | 'unpublish' | 'verify' | 'unverify' | 'feature' | 'unfeature' | 'trash' | 'restore';

// ════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════

function formatPKR(amount: number): string {
  if (!amount || amount <= 0) return '—';
  if (amount >= 10_000_000) return `${(amount / 10_000_000).toFixed(1)} Cr`;
  if (amount >= 100_000) return `${(amount / 100_000).toFixed(1)} Lac`;
  return amount.toLocaleString();
}

function formatNumber(num: number): string {
  if (!num) return '0';
  if (num >= 1000) return `${(num / 1000).toFixed(1)}K`;
  return String(num);
}

function getPrimaryImage(unit: AdminUnit): string | null {
  if (unit.images && unit.images.length > 0) {
    const primary = unit.images.find((img) => img.isPrimary);
    return primary?.url ?? unit.images[0].url;
  }
  return null;
}

function getStatusConfig(status: string): { label: string; bg: string; text: string } {
  const configs: Record<string, { label: string; bg: string; text: string }> = {
    available:  { label: 'Available',  bg: 'bg-emerald-100', text: 'text-emerald-700' },
    reserved:   { label: 'Reserved',   bg: 'bg-amber-100',   text: 'text-amber-700' },
    sold:       { label: 'Sold',       bg: 'bg-red-100',     text: 'text-red-700' },
    on_hold:    { label: 'On Hold',    bg: 'bg-gray-100',    text: 'text-gray-600' },
    cancelled:  { label: 'Cancelled',  bg: 'bg-gray-50',     text: 'text-gray-400' },
  };
  return configs[status] ?? { label: status, bg: 'bg-gray-100', text: 'text-gray-600' };
}

// ════════════════════════════════════════════════════
// BANNER
// ════════════════════════════════════════════════════

function Banner({
  type,
  message,
  onDismiss,
}: {
  type: 'success' | 'error';
  message: string;
  onDismiss: () => void;
}): React.ReactElement {
  useEffect(() => {
    const t = setTimeout(onDismiss, 5000);
    return () => clearTimeout(t);
  }, [onDismiss]);

  return (
    <div className={`fixed top-5 left-1/2 -translate-x-1/2 z-50
                     px-5 py-3 rounded-xl shadow-xl flex items-center gap-3
                     ${type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'}`}>
      {type === 'success'
        ? <CheckCircle2 className="w-5 h-5 flex-shrink-0" />
        : <AlertCircle className="w-5 h-5 flex-shrink-0" />
      }
      <p className="text-sm font-semibold">{message}</p>
      <button onClick={onDismiss} className="p-1 hover:bg-white/20 rounded-full">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

// ════════════════════════════════════════════════════
// STAT CARD
// ════════════════════════════════════════════════════

function StatCard({
  label,
  value,
  icon,
  iconBg,
  iconColor,
}: {
  label:     string;
  value:     string | number;
  icon:      React.ReactElement;
  iconBg:    string;
  iconColor: string;
}): React.ReactElement {
  return (
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
      <div className="flex items-center gap-3">
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${iconBg} ${iconColor}`}>
          {icon}
        </div>
        <div>
          <p className="text-[10px] font-semibold text-gray-400 uppercase tracking-wide">{label}</p>
          <p className="text-xl font-black text-gray-900">
            {typeof value === 'number' ? formatNumber(value) : value}
          </p>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════
// MAIN PAGE
// ════════════════════════════════════════════════════

export default function AdminUnitsPage(): React.ReactElement {
  const { data: session } = useSession();

  // Data
  const [units, setUnits]       = useState<AdminUnit[]>([]);
  const [stats, setStats]       = useState<AdminStats | null>(null);
  const [pagination, setPagination] = useState<Pagination>({
    page: 1, limit: 50, totalCount: 0, totalPages: 0, hasMore: false,
  });

  // Filters
  const [search, setSearch]           = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [publishedFilter, setPublishedFilter] = useState('');
  const [verifiedFilter, setVerifiedFilter]   = useState('');
  const [deletedFilter, setDeletedFilter]     = useState('');
  const [sortBy, setSortBy]         = useState('createdAt');
  const [sortOrder, setSortOrder]   = useState('desc');

  // UI state
  const [loading, setLoading]       = useState(true);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [bulkLoading, setBulkLoading] = useState(false);
  const [banner, setBanner]         = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ── Fetch units ──
  const fetchUnits = useCallback(async (page = 1) => {
    setLoading(true);

    const params = new URLSearchParams();
    params.set('page', String(page));
    params.set('limit', '50');
    params.set('sortBy', sortBy);
    params.set('sortOrder', sortOrder);

    if (search)           params.set('q', search);
    if (statusFilter)     params.set('status', statusFilter);
    if (categoryFilter)   params.set('category', categoryFilter);
    if (publishedFilter)  params.set('published', publishedFilter);
    if (verifiedFilter)   params.set('verified', verifiedFilter);
    if (deletedFilter === 'deleted')     params.set('deleted', 'true');
    if (deletedFilter === 'all')         params.set('all', 'true');

    try {
      const res  = await fetch(`/api/admin/units?${params.toString()}`, {
        credentials: 'include',
      });
      const data = await res.json();

      if (data.success && data.data) {
        setUnits(data.data.units ?? []);
        setPagination(data.data.pagination ?? pagination);
        setStats(data.data.stats ?? null);
      } else {
        setBanner({ type: 'error', message: data.message ?? 'Failed to load units' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Failed to load units. Please try again.' });
    } finally {
      setLoading(false);
    }
  }, [search, statusFilter, categoryFilter, publishedFilter, verifiedFilter, deletedFilter, sortBy, sortOrder]);

  useEffect(() => {
    fetchUnits();
  }, [fetchUnits]);

  // ── Search debounce ──
  const handleSearch = useCallback((value: string) => {
    setSearch(value);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      fetchUnits(1);
    }, 400);
  }, [fetchUnits]);

  // ── Selection ──
  const toggleSelect = useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const selectAll = useCallback(() => {
    if (selectedIds.size === units.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(units.map((u) => u._id)));
    }
  }, [units, selectedIds]);

  // ── Bulk action ──
  const handleBulkAction = useCallback(async (action: BulkAction) => {
    if (selectedIds.size === 0) return;

    const confirmMessages: Record<BulkAction, string> = {
      publish:   `Publish ${selectedIds.size} unit(s)?`,
      unpublish: `Unpublish ${selectedIds.size} unit(s)?`,
      verify:    `Verify ${selectedIds.size} unit(s)?`,
      unverify:  `Remove verification from ${selectedIds.size} unit(s)?`,
      feature:   `Feature ${selectedIds.size} unit(s)?`,
      unfeature: `Unfeature ${selectedIds.size} unit(s)?`,
      trash:     `Delete ${selectedIds.size} unit(s)? They can be restored later.`,
      restore:   `Restore ${selectedIds.size} unit(s)?`,
    };

    if (!window.confirm(confirmMessages[action])) return;

    setBulkLoading(true);
    try {
      const res = await fetch('/api/admin/units', {
        method:      'POST',
        credentials: 'include',
        headers:     { 'Content-Type': 'application/json' },
        body:        JSON.stringify({
          action,
          unitIds: Array.from(selectedIds),
        }),
      });
      const data = await res.json();

      if (data.success) {
        setBanner({
          type:    'success',
          message: data.message ?? `Bulk ${action} completed — ${data.data?.affectedCount ?? 0} units affected`,
        });
        setSelectedIds(new Set());
        fetchUnits(pagination.page);
      } else {
        setBanner({ type: 'error', message: data.message ?? 'Bulk action failed' });
      }
    } catch {
      setBanner({ type: 'error', message: 'Bulk action failed. Please try again.' });
    } finally {
      setBulkLoading(false);
    }
  }, [selectedIds, pagination.page, fetchUnits]);

  // ── Sort toggle ──
  const handleSort = useCallback((field: string) => {
    if (sortBy === field) {
      setSortOrder((prev) => (prev === 'desc' ? 'asc' : 'desc'));
    } else {
      setSortBy(field);
      setSortOrder('desc');
    }
  }, [sortBy]);

  // ── Reset filters ──
  const resetFilters = useCallback(() => {
    setSearch('');
    setStatusFilter('');
    setCategoryFilter('');
    setPublishedFilter('');
    setVerifiedFilter('');
    setDeletedFilter('');
    setSortBy('createdAt');
    setSortOrder('desc');
  }, []);

  const hasActiveFilters = search || statusFilter || categoryFilter ||
    publishedFilter || verifiedFilter || deletedFilter;

  return (
    <AdminLayout>
      <Head>
        <title>Units Management | Highrise.pk Admin</title>
        <meta name="robots" content="noindex, nofollow" />
      </Head>

      {/* Banner */}
      {banner && (
        <Banner
          type={banner.type}
          message={banner.message}
          onDismiss={() => setBanner(null)}
        />
      )}

      {/* Header */}
      <div className="mb-6">
        <h1 className="text-2xl font-black text-[#004063] flex items-center gap-2">
          <Package className="w-6 h-6 text-[#029bba]" />
          Units Management
        </h1>
        <p className="text-sm text-gray-500 mt-1">
          Manage all units across all projects on the platform
        </p>
      </div>

      {/* Stats */}
      {stats && (
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 mb-6">
          <StatCard
            label="Total Units"
            value={stats.totalUnits}
            icon={<Package className="w-5 h-5" />}
            iconBg="bg-blue-50"
            iconColor="text-blue-600"
          />
          <StatCard
            label="Available"
            value={stats.availableUnits}
            icon={<CheckCircle2 className="w-5 h-5" />}
            iconBg="bg-emerald-50"
            iconColor="text-emerald-600"
          />
          <StatCard
            label="Sold"
            value={stats.soldUnits}
            icon={<XCircle className="w-5 h-5" />}
            iconBg="bg-red-50"
            iconColor="text-red-500"
          />
          <StatCard
            label="Verified"
            value={stats.verifiedUnits}
            icon={<Shield className="w-5 h-5" />}
            iconBg="bg-teal-50"
            iconColor="text-teal-600"
          />
          <StatCard
            label="Total Views"
            value={stats.totalViews}
            icon={<Eye className="w-5 h-5" />}
            iconBg="bg-purple-50"
            iconColor="text-purple-600"
          />
        </div>
      )}

      {/* Search + Filter bar */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
          {/* Search */}
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              value={search}
              onChange={(e) => handleSearch(e.target.value)}
              placeholder="Search by unit number, type, tower..."
              className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200
                         text-sm focus:border-[#029bba] focus:ring-1 focus:ring-[#029bba]
                         outline-none transition-colors"
            />
          </div>

          {/* Filter toggle */}
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`inline-flex items-center gap-2 px-4 py-2.5 rounded-xl border
                        text-sm font-semibold transition-colors
                        ${hasActiveFilters
                          ? 'border-[#029bba] bg-[#029bba]/5 text-[#029bba]'
                          : 'border-gray-200 text-gray-600 hover:bg-gray-50'
                        }`}
          >
            <Filter className="w-4 h-4" />
            Filters
            {hasActiveFilters && (
              <span className="w-5 h-5 rounded-full bg-[#029bba] text-white text-[10px]
                               font-bold flex items-center justify-center">
                !
              </span>
            )}
            {showFilters ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>

          {/* Refresh */}
          <button
            onClick={() => fetchUnits(pagination.page)}
            className="p-2.5 rounded-xl border border-gray-200 text-gray-500
                       hover:text-[#029bba] hover:border-[#029bba]/30 transition-colors"
          >
            <RefreshCw className="w-4 h-4" />
          </button>
        </div>

        {/* Expanded filters */}
        {showFilters && (
          <div className="mt-4 pt-4 border-t border-gray-100">
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
              {/* Status */}
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">
                  Status
                </label>
                <select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl border border-gray-200 text-sm
                             appearance-none bg-white focus:border-[#029bba] outline-none"
                >
                  <option value="">All Statuses</option>
                  <option value="available">Available</option>
                  <option value="reserved">Reserved</option>
                  <option value="sold">Sold</option>
                  <option value="on_hold">On Hold</option>
                  <option value="cancelled">Cancelled</option>
                </select>
              </div>

              {/* Category */}
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">
                  Category
                </label>
                <select
                  value={categoryFilter}
                  onChange={(e) => setCategoryFilter(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl border border-gray-200 text-sm
                             appearance-none bg-white focus:border-[#029bba] outline-none"
                >
                  <option value="">All Categories</option>
                  <option value="residential">Residential</option>
                  <option value="commercial">Commercial</option>
                </select>
              </div>

              {/* Published */}
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">
                  Published
                </label>
                <select
                  value={publishedFilter}
                  onChange={(e) => setPublishedFilter(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl border border-gray-200 text-sm
                             appearance-none bg-white focus:border-[#029bba] outline-none"
                >
                  <option value="">All</option>
                  <option value="true">Published</option>
                  <option value="false">Unpublished</option>
                </select>
              </div>

              {/* Verified */}
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">
                  Verified
                </label>
                <select
                  value={verifiedFilter}
                  onChange={(e) => setVerifiedFilter(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl border border-gray-200 text-sm
                             appearance-none bg-white focus:border-[#029bba] outline-none"
                >
                  <option value="">All</option>
                  <option value="true">Verified</option>
                  <option value="false">Not Verified</option>
                </select>
              </div>

              {/* Deleted */}
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">
                  Show
                </label>
                <select
                  value={deletedFilter}
                  onChange={(e) => setDeletedFilter(e.target.value)}
                  className="w-full px-3 py-2 rounded-xl border border-gray-200 text-sm
                             appearance-none bg-white focus:border-[#029bba] outline-none"
                >
                  <option value="">Active Only</option>
                  <option value="deleted">Deleted Only</option>
                  <option value="all">All (incl. deleted)</option>
                </select>
              </div>
            </div>

            {/* Reset */}
            {hasActiveFilters && (
              <button
                onClick={resetFilters}
                className="mt-3 text-xs font-semibold text-[#029bba] hover:underline
                           flex items-center gap-1"
              >
                <RotateCcw className="w-3 h-3" />
                Reset all filters
              </button>
            )}
          </div>
        )}
      </div>

      {/* Bulk actions bar */}
      {selectedIds.size > 0 && (
        <div className="bg-[#004063] rounded-2xl p-4 mb-6 flex flex-wrap items-center
                        justify-between gap-3">
          <p className="text-sm font-semibold text-white">
            {selectedIds.size} unit{selectedIds.size > 1 ? 's' : ''} selected
          </p>
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => handleBulkAction('publish')}
              disabled={bulkLoading}
              className="px-3 py-1.5 rounded-lg bg-emerald-500 text-white text-xs
                         font-semibold hover:bg-emerald-600 disabled:opacity-50"
            >
              Publish
            </button>
            <button
              onClick={() => handleBulkAction('unpublish')}
              disabled={bulkLoading}
              className="px-3 py-1.5 rounded-lg bg-gray-500 text-white text-xs
                         font-semibold hover:bg-gray-600 disabled:opacity-50"
            >
              Unpublish
            </button>
            <button
              onClick={() => handleBulkAction('verify')}
              disabled={bulkLoading}
              className="px-3 py-1.5 rounded-lg bg-[#029bba] text-white text-xs
                         font-semibold hover:bg-[#027a94] disabled:opacity-50"
            >
              Verify
            </button>
            <button
              onClick={() => handleBulkAction('feature')}
              disabled={bulkLoading}
              className="px-3 py-1.5 rounded-lg bg-amber-500 text-white text-xs
                         font-semibold hover:bg-amber-600 disabled:opacity-50"
            >
              Feature
            </button>
            <button
              onClick={() => handleBulkAction('trash')}
              disabled={bulkLoading}
              className="px-3 py-1.5 rounded-lg bg-red-500 text-white text-xs
                         font-semibold hover:bg-red-600 disabled:opacity-50"
            >
              Delete
            </button>
            <button
              onClick={() => handleBulkAction('restore')}
              disabled={bulkLoading}
              className="px-3 py-1.5 rounded-lg bg-blue-500 text-white text-xs
                         font-semibold hover:bg-blue-600 disabled:opacity-50"
            >
              Restore
            </button>
            <button
              onClick={() => setSelectedIds(new Set())}
              className="px-3 py-1.5 rounded-lg bg-white/20 text-white text-xs
                         font-semibold hover:bg-white/30"
            >
              Clear
            </button>
          </div>
        </div>
      )}

      {/* Loading */}
      {loading && (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="w-8 h-8 text-[#029bba] animate-spin" />
        </div>
      )}

      {/* Empty state */}
      {!loading && units.length === 0 && (
        <div className="text-center py-16 bg-white rounded-2xl border border-gray-100 shadow-sm">
          <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-bold text-gray-700 mb-1">No Units Found</h3>
          <p className="text-sm text-gray-400 mb-4">
            {hasActiveFilters
              ? 'No units match the current filters. Try adjusting your search.'
              : 'No units have been created yet.'
            }
          </p>
          {hasActiveFilters && (
            <button
              onClick={resetFilters}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-xl
                         bg-[#029bba] text-white text-sm font-semibold
                         hover:bg-[#027a94] transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              Reset Filters
            </button>
          )}
        </div>
      )}

      {/* Units table */}
      {!loading && units.length > 0 && (
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100">
                  {/* Checkbox */}
                  <th className="px-4 py-3 w-10">
                    <input
                      type="checkbox"
                      checked={selectedIds.size === units.length && units.length > 0}
                      onChange={selectAll}
                      className="w-4 h-4 rounded border-gray-300 text-[#029bba]
                                 focus:ring-[#029bba]"
                    />
                  </th>

                  {/* Unit */}
                  <th className="px-4 py-3 text-left">
                    <button
                      onClick={() => handleSort('unitNumber')}
                      className="flex items-center gap-1 text-xs font-bold text-gray-500
                                 uppercase tracking-wide hover:text-[#029bba]"
                    >
                      Unit <ArrowUpDown className="w-3 h-3" />
                    </button>
                  </th>

                  {/* Project */}
                  <th className="px-4 py-3 text-left text-xs font-bold text-gray-500
                                 uppercase tracking-wide">
                    Project
                  </th>

                  {/* Status */}
                  <th className="px-4 py-3 text-left">
                    <button
                      onClick={() => handleSort('status')}
                      className="flex items-center gap-1 text-xs font-bold text-gray-500
                                 uppercase tracking-wide hover:text-[#029bba]"
                    >
                      Status <ArrowUpDown className="w-3 h-3" />
                    </button>
                  </th>

                  {/* Price */}
                  <th className="px-4 py-3 text-right">
                    <button
                      onClick={() => handleSort('price')}
                      className="flex items-center gap-1 text-xs font-bold text-gray-500
                                 uppercase tracking-wide hover:text-[#029bba] ml-auto"
                    >
                      Price <ArrowUpDown className="w-3 h-3" />
                    </button>
                  </th>

                  {/* Area */}
                  <th className="px-4 py-3 text-right text-xs font-bold text-gray-500
                                 uppercase tracking-wide hidden lg:table-cell">
                    Area
                  </th>

                  {/* Flags */}
                  <th className="px-4 py-3 text-center text-xs font-bold text-gray-500
                                 uppercase tracking-wide hidden md:table-cell">
                    Flags
                  </th>

                  {/* Views */}
                  <th className="px-4 py-3 text-right">
                    <button
                      onClick={() => handleSort('views')}
                      className="flex items-center gap-1 text-xs font-bold text-gray-500
                                 uppercase tracking-wide hover:text-[#029bba] ml-auto"
                    >
                      Views <ArrowUpDown className="w-3 h-3" />
                    </button>
                  </th>

                  {/* Actions */}
                  <th className="px-4 py-3 text-right text-xs font-bold text-gray-500
                                 uppercase tracking-wide">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {units.map((unit) => {
                  const statusConfig = getStatusConfig(unit.status);
                  const image        = getPrimaryImage(unit);
                  const isSelected   = selectedIds.has(unit._id);

                  return (
                    <tr
                      key={unit._id}
                      className={`hover:bg-gray-50/50 transition-colors
                                  ${unit.isDeleted ? 'bg-red-50/30' : ''}
                                  ${isSelected ? 'bg-[#029bba]/5' : ''}`}
                    >
                      {/* Checkbox */}
                      <td className="px-4 py-3">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => toggleSelect(unit._id)}
                          className="w-4 h-4 rounded border-gray-300 text-[#029bba]
                                     focus:ring-[#029bba]"
                        />
                      </td>

                      {/* Unit info */}
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          {/* Thumbnail */}
                          <div className="relative w-10 h-10 rounded-lg overflow-hidden
                                          bg-gray-100 flex-shrink-0">
                            {image ? (
                              <Image
                                src={image}
                                alt={unit.unitNumber}
                                fill
                                className="object-cover"
                                sizes="40px"
                              />
                            ) : (
                              <div className="w-full h-full flex items-center justify-center">
                                {unit.category === 'commercial'
                                  ? <Store className="w-4 h-4 text-gray-300" />
                                  : <Home className="w-4 h-4 text-gray-300" />
                                }
                              </div>
                            )}
                          </div>

                          {/* Details */}
                          <div className="min-w-0">
                            <p className="font-bold text-gray-900 text-sm truncate">
                              #{unit.unitNumber}
                            </p>
                            <p className="text-[10px] text-gray-400 truncate">
                              {unit.unitTypeName ?? unit.unitType.replace(/_/g, ' ')}
                              {unit.floorName ? ` · ${unit.floorName}` : ''}
                              {unit.tower ? ` · ${unit.tower}` : ''}
                            </p>
                          </div>
                        </div>
                      </td>

                      {/* Project */}
                      <td className="px-4 py-3">
                        {unit.projectId ? (
                          <div className="min-w-0">
                            <Link
                              href={`/admin/projects/${unit.projectId._id}`}
                              className="text-xs font-semibold text-gray-700 hover:text-[#029bba]
                                         truncate block max-w-[160px]"
                            >
                              {unit.projectId.projectName}
                            </Link>
                            {unit.projectId.city && (
                              <p className="text-[10px] text-gray-400 flex items-center gap-0.5">
                                <MapPin className="w-3 h-3" />
                                {unit.projectId.city}
                              </p>
                            )}
                          </div>
                        ) : (
                          <span className="text-xs text-gray-300">—</span>
                        )}
                      </td>

                      {/* Status */}
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold
                                          ${statusConfig.bg} ${statusConfig.text}`}>
                          {statusConfig.label}
                        </span>
                        {unit.isDeleted && (
                          <span className="block mt-1 px-2 py-0.5 rounded-full bg-red-100
                                           text-red-600 text-[9px] font-bold w-fit">
                            Deleted
                          </span>
                        )}
                      </td>

                      {/* Price */}
                      <td className="px-4 py-3 text-right">
                        <p className="font-bold text-[#029bba] text-sm">
                          {formatPKR(unit.price)}
                        </p>
                        {unit.isPriceDropped && (
                          <span className="text-[9px] text-green-600 font-bold flex items-center
                                           gap-0.5 justify-end">
                            <TrendingDown className="w-3 h-3" /> Dropped
                          </span>
                        )}
                      </td>

                      {/* Area */}
                      <td className="px-4 py-3 text-right text-xs text-gray-600 hidden lg:table-cell">
                        {unit.area} {unit.areaUnit ?? 'sqft'}
                        {unit.bedrooms !== undefined && unit.bedrooms > 0 && (
                          <p className="text-[10px] text-gray-400">
                            {unit.bedrooms}B / {unit.bathrooms ?? 0}B
                          </p>
                        )}
                      </td>

                      {/* Flags */}
                      <td className="px-4 py-3 hidden md:table-cell">
                        <div className="flex items-center justify-center gap-1">
                          <span title={unit.isPublished ? 'Published' : 'Unpublished'}>
                            {unit.isPublished ? (
                              <Eye className="w-3.5 h-3.5 text-emerald-500" />
                            ) : (
                              <EyeOff className="w-3.5 h-3.5 text-gray-300" />
                            )}
                          </span>
                          {unit.isVerified && (
                            <span title="Verified">
                              <BadgeCheck className="w-3.5 h-3.5 text-[#029bba]" />
                            </span>
                          )}
                          {unit.isFeatured && (
                            <span title="Featured">
                              <Star className="w-3.5 h-3.5 text-amber-500" />
                            </span>
                          )}
                          {unit.isCorner && (
                            <span title="Corner">
                              <Layers className="w-3.5 h-3.5 text-purple-500" />
                            </span>
                          )}
                        </div>
                      </td>

                      {/* Views */}
                      <td className="px-4 py-3 text-right">
                        <div className="flex items-center gap-2 justify-end text-xs text-gray-500">
                          <span className="flex items-center gap-0.5">
                            <Eye className="w-3 h-3" />
                            {formatNumber(unit.views ?? 0)}
                          </span>
                          <span className="flex items-center gap-0.5">
                            <MessageSquare className="w-3 h-3" />
                            {unit.inquiryCount ?? 0}
                          </span>
                        </div>
                      </td>

                      {/* Actions */}
                      <td className="px-4 py-3 text-right">
                        <Link
                          href={`/admin/units/${unit._id}`}
                          className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg
                                     bg-gray-100 text-gray-600 text-xs font-semibold
                                     hover:bg-[#029bba] hover:text-white transition-colors"
                        >
                          <Eye className="w-3 h-3" />
                          View
                        </Link>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          <div className="px-4 py-3 border-t border-gray-100 flex items-center justify-between">
            <p className="text-xs text-gray-400">
              Showing {((pagination.page - 1) * pagination.limit) + 1}–
              {Math.min(pagination.page * pagination.limit, pagination.totalCount)} of{' '}
              {pagination.totalCount} units
            </p>
            <div className="flex items-center gap-2">
              <button
                onClick={() => fetchUnits(pagination.page - 1)}
                disabled={pagination.page <= 1}
                className="px-3 py-1.5 rounded-lg border border-gray-200 text-xs
                           font-semibold text-gray-600 hover:bg-gray-50
                           disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Previous
              </button>
              <span className="text-xs font-semibold text-gray-600">
                Page {pagination.page} of {pagination.totalPages}
              </span>
              <button
                onClick={() => fetchUnits(pagination.page + 1)}
                disabled={!pagination.hasMore}
                className="px-3 py-1.5 rounded-lg border border-gray-200 text-xs
                           font-semibold text-gray-600 hover:bg-gray-50
                           disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Next
              </button>
            </div>
          </div>
        </div>
      )}
    </AdminLayout>
  );
}

// pages/admin/users/index.tsx
// Admin Users Management List — V4.1 Compliant
// Single AdminLayout wrap | useSession() guard | noindex
// Inline banners + modals | No toast | No framer-motion | No <img>
// Mailto: email button | Pagination | Tab sync with URL

import React, { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';
import Head from 'next/head';
import Link from 'next/link';
import Image from 'next/image';
import AdminLayout from '@/components/admin/AdminLayout';
import {
  Users,
  Search,
  CheckCircle,
  Clock,
  Trash2,
  RotateCcw,
  Eye,
  Shield,
  ShieldOff,
  ShieldAlert,
  ChevronDown,
  X,
  Loader2,
  RefreshCw,
  Mail,
  Phone,
  MapPin,
  Calendar,
  AlertCircle,
  AlertTriangle,
} from 'lucide-react';

// ─── Types ────────────────────────────────────────────────────────────────────

interface MaskedUser {
  _id:               string;
  name:              string;
  displayName:       string;
  emailMasked:       string;
  phoneMasked:       string;
  role:              string;
  status:            string;
  accountType:       string;
  city:              string;
  country:           string;
  isVerified:        boolean;
  isDeleted:         boolean;
  cnicStatus:        string;
  profilePictureUrl: string;
  createdAt:         string;
  lastLoginAt:       string | null;
  deletedAt:         string | null;
  statusReason:      string;
}

interface Counts {
  all:       number;
  active:    number;
  pending:   number;
  suspended: number;
  banned:    number;
  trash:     number;
}

interface Banner {
  type:    'success' | 'error';
  message: string;
}

type StatusAction = 'active' | 'pending' | 'suspended' | 'banned';
type ValidRole = 'user' | 'agent' | 'developer';

// ─── Constants ────────────────────────────────────────────────────────────────

const TABS = [
  { key: 'all',       label: 'All Users',  icon: Users       },
  { key: 'active',    label: 'Active',     icon: CheckCircle },
  { key: 'pending',   label: 'Pending',    icon: Clock       },
  { key: 'suspended', label: 'Suspended',  icon: ShieldOff   },
  { key: 'banned',    label: 'Banned',     icon: ShieldAlert },
  { key: 'trash',     label: 'Trash',      icon: Trash2      },
] as const;

// V4.1 Option A — only 4 valid assignable roles
const VALID_ROLES: { value: ValidRole; label: string; cls: string }[] = [
  { value: 'user',      label: 'User',      cls: 'bg-gray-100 text-gray-700' },
  { value: 'agent',     label: 'Agent',     cls: 'bg-blue-100 text-blue-700' },
  { value: 'developer', label: 'Developer', cls: 'bg-green-100 text-green-700' },
];

// Legacy roles shown read-only in filters (cannot be assigned to)
const ALL_ROLE_LABELS: Record<string, string> = {
  user:      'User',
  agent:     'Agent',
  developer: 'Developer',
  admin:     'Admin',
  reader:    'Reader (legacy)',
  writer:    'Writer (legacy)',
  editor:    'Editor (legacy)',
};

const STATUS_BADGE: Record<string, { cls: string; label: string }> = {
  active:    { cls: 'bg-[#f0fdf4] text-[#10b981] border-[#10b981]', label: 'Active'    },
  pending:   { cls: 'bg-[#fef3c7] text-[#92400e] border-[#f59e0b]', label: 'Pending'   },
  suspended: { cls: 'bg-[#fef3c7] text-[#9a3412] border-[#f59e0b]', label: 'Suspended' },
  banned:    { cls: 'bg-[#fef2f2] text-red-700 border-[#ef4444]',   label: 'Banned'    },
};

const ROLE_BADGE_CLS: Record<string, string> = {
  user:      'bg-gray-100 text-gray-700',
  agent:     'bg-blue-100 text-blue-700',
  developer: 'bg-green-100 text-green-700',
  admin:     'bg-purple-100 text-purple-700',
  reader:    'bg-slate-100 text-slate-600',
  writer:    'bg-slate-100 text-slate-600',
  editor:    'bg-slate-100 text-slate-600',
};

const PAGE_SIZE = 12;

// ─── Helpers ──────────────────────────────────────────────────────────────────

function formatDate(iso: string | null): string {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString('en-PK', {
    year:  'numeric',
    month: 'short',
    day:   'numeric',
  });
}

function refreshSidebarStats(): void {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new Event('refreshAdminStats'));
  }
}

// ─── Inline Confirm Modal ─────────────────────────────────────────────────────

interface InlineConfirmModalProps {
  open:          boolean;
  title:         string;
  message:       string;
  confirmLabel:  string;
  confirmColor:  'primary' | 'danger' | 'warning';
  loading:       boolean;
  showReason:    boolean;
  onConfirm:     (reason: string) => void;
  onCancel:      () => void;
}

function InlineConfirmModal({
  open, title, message, confirmLabel, confirmColor, loading,
  showReason, onConfirm, onCancel,
}: InlineConfirmModalProps): React.ReactElement | null {
  const [reason, setReason] = useState('');

  useEffect(() => {
    if (!open) setReason('');
  }, [open]);

  if (!open) return null;

  const btnCls: Record<typeof confirmColor, string> = {
    primary: 'bg-[#029bba] hover:bg-[#027a94]',
    danger:  'bg-[#ef4444] hover:bg-red-700',
    warning: 'bg-[#f59e0b] hover:bg-amber-600',
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-black/50"
        onClick={loading ? undefined : onCancel}
        aria-hidden="true"
      />
      <div
        className="relative w-full max-w-md bg-white rounded-2xl shadow-xl p-6"
        role="dialog"
        aria-modal="true"
      >
        <h3 className="text-lg font-bold text-[#004063] mb-2">{title}</h3>
        <p className="text-sm text-gray-600 mb-4 whitespace-pre-line">{message}</p>

        {showReason && (
          <div className="mb-4">
            <label className="block text-xs font-medium text-gray-700 mb-1">
              Reason {confirmColor === 'danger' && <span className="text-red-500">*</span>}
            </label>
            <textarea
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              rows={3}
              maxLength={500}
              placeholder="Enter reason for this action..."
              className="w-full px-3 py-2 text-sm border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none resize-none"
            />
            <p className="text-xs text-gray-400 mt-1 text-right">{reason.length}/500</p>
          </div>
        )}

        <div className="flex gap-2 justify-end">
          <button
            type="button"
            onClick={onCancel}
            disabled={loading}
            className="px-4 py-2 text-sm border border-gray-300 rounded-xl text-gray-700 hover:bg-gray-50 transition-colors disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={() => onConfirm(reason.trim())}
            disabled={loading || (showReason && confirmColor === 'danger' && reason.trim().length < 5)}
            className={`px-4 py-2 text-sm text-white rounded-xl transition-colors disabled:opacity-50 flex items-center gap-2 ${btnCls[confirmColor]}`}
          >
            {loading && <Loader2 className="w-4 h-4 animate-spin" />}
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── User Avatar ──────────────────────────────────────────────────────────────

function UserAvatar({
  url, name, size = 48,
}: { url: string; name: string; size?: number }): React.ReactElement {
  if (url) {
    return (
      <div className={`relative rounded-full overflow-hidden bg-gray-100`} style={{ width: size, height: size }}>
        <Image
          src={url}
          alt={name}
          fill
          className="object-cover"
          sizes={`${size}px`}
        />
      </div>
    );
  }
  return (
    <div
      className="rounded-full bg-gradient-to-br from-[#029bba] to-[#004063] flex items-center justify-center text-white font-bold"
      style={{ width: size, height: size, fontSize: size / 2.5 }}
    >
      {name?.charAt(0).toUpperCase() || 'U'}
    </div>
  );
}

// ─── User Card ────────────────────────────────────────────────────────────────

interface UserCardProps {
  user:        MaskedUser;
  isTrashTab:  boolean;
  busy:        boolean;
  onAction:    (action: string, user: MaskedUser, extra?: string) => void;
}

function UserCard({ user, isTrashTab, busy, onAction }: UserCardProps): React.ReactElement {
  const [showRoleMenu, setShowRoleMenu] = useState(false);

  const status = STATUS_BADGE[user.status] ?? STATUS_BADGE.active;
  const roleCls = ROLE_BADGE_CLS[user.role] ?? ROLE_BADGE_CLS.user;
  const roleLabel = ALL_ROLE_LABELS[user.role] ?? user.role;
  const isAdmin = user.role === 'admin';
  const canChangeRole = !isTrashTab && !isAdmin;

  return (
    <div className="bg-white rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow p-5">

      {/* Header */}
      <div className="flex items-start justify-between mb-4">
        <div className="flex items-center gap-3 min-w-0">
          <div className="relative shrink-0">
            <UserAvatar url={user.profilePictureUrl} name={user.name} size={48} />
            {user.isVerified && (
              <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center border-2 border-white">
                <CheckCircle className="w-3 h-3 text-white" />
              </div>
            )}
          </div>
          <div className="min-w-0">
            <h3 className="font-semibold text-gray-900 truncate">{user.name}</h3>
            <p className="text-xs text-gray-500 truncate">{user.emailMasked}</p>
          </div>
        </div>
        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase border ${status.cls} shrink-0`}>
          {status.label}
        </span>
      </div>

      {/* Info */}
      <div className="grid grid-cols-2 gap-2 mb-4 text-xs text-gray-600">
        <div className="flex items-center gap-1.5">
          <Phone className="w-3 h-3 text-gray-400" />
          <span className="truncate">{user.phoneMasked || '—'}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <MapPin className="w-3 h-3 text-gray-400" />
          <span className="truncate">{user.city || '—'}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <Calendar className="w-3 h-3 text-gray-400" />
          <span>{formatDate(user.createdAt)}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <Shield className="w-3 h-3 text-gray-400" />
          <span className="truncate capitalize">{user.accountType}</span>
        </div>
      </div>

      {/* Role + KYC badges */}
      <div className="flex items-center gap-2 mb-4 flex-wrap">
        {canChangeRole ? (
          <div className="relative">
            <button
              type="button"
              onClick={() => setShowRoleMenu(!showRoleMenu)}
              disabled={busy}
              className={`px-2.5 py-1 rounded-lg text-xs font-medium flex items-center gap-1 transition-opacity hover:opacity-80 disabled:opacity-50 ${roleCls}`}
            >
              <Shield className="w-3 h-3" />
              {roleLabel}
              <ChevronDown className="w-3 h-3" />
            </button>
            {showRoleMenu && (
              <>
                <div className="fixed inset-0 z-10" onClick={() => setShowRoleMenu(false)} />
                <div className="absolute left-0 top-full mt-1 w-40 bg-white rounded-xl shadow-lg border border-gray-200 py-1 z-20">
                  {VALID_ROLES.map((r) => (
                    <button
                      key={r.value}
                      type="button"
                      onClick={() => {
                        onAction('change-role', user, r.value);
                        setShowRoleMenu(false);
                      }}
                      className={`w-full px-3 py-2 text-left text-xs flex items-center gap-2 hover:bg-gray-50 ${user.role === r.value ? 'font-bold text-[#029bba]' : ''}`}
                    >
                      <span className={`px-2 py-0.5 rounded ${r.cls}`}>{r.label}</span>
                      {user.role === r.value && <CheckCircle className="w-3 h-3 ml-auto text-[#10b981]" />}
                    </button>
                  ))}
                </div>
              </>
            )}
          </div>
        ) : (
          <span className={`px-2.5 py-1 rounded-lg text-xs font-medium flex items-center gap-1 ${roleCls}`}>
            <Shield className="w-3 h-3" />
            {roleLabel}
          </span>
        )}
        {user.cnicStatus !== 'none' && (
          <span className={`px-2 py-0.5 rounded text-[10px] font-medium ${
            user.cnicStatus === 'verified' ? 'bg-[#f0fdf4] text-[#10b981]' :
            user.cnicStatus === 'rejected' ? 'bg-[#fef2f2] text-red-700' :
            'bg-[#fef3c7] text-amber-700'
          }`}>
            KYC: {user.cnicStatus}
          </span>
        )}
      </div>

      {/* Deleted info */}
      {user.isDeleted && user.deletedAt && (
        <div className="mb-3 p-2 bg-[#fef2f2] border-l-4 border-[#ef4444] rounded text-xs text-red-700 flex items-center gap-1">
          <Trash2 className="w-3 h-3" />
          Deleted on {formatDate(user.deletedAt)}
        </div>
      )}

      {/* Status reason */}
      {user.statusReason && (user.status === 'suspended' || user.status === 'banned') && (
        <div className="mb-3 p-2 bg-[#fef3c7] border-l-4 border-[#f59e0b] rounded text-xs text-amber-800">
          <strong>Reason:</strong> {user.statusReason}
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center justify-between pt-3 border-t border-gray-100 gap-2">
        <div className="flex gap-1 flex-wrap">
          {!isTrashTab && !isAdmin && (
            <>
              {user.status !== 'active' && (
                <button
                  type="button"
                  onClick={() => onAction('activate', user)}
                  disabled={busy}
                  className="px-2.5 py-1 bg-[#10b981] text-white text-xs rounded-lg hover:bg-emerald-600 transition-colors disabled:opacity-50 flex items-center gap-1"
                >
                  <CheckCircle className="w-3 h-3" /> Activate
                </button>
              )}
              {user.status === 'active' && (
                <button
                  type="button"
                  onClick={() => onAction('suspend', user)}
                  disabled={busy}
                  className="px-2.5 py-1 bg-[#f59e0b] text-white text-xs rounded-lg hover:bg-amber-600 transition-colors disabled:opacity-50 flex items-center gap-1"
                >
                  <ShieldOff className="w-3 h-3" /> Suspend
                </button>
              )}
              {user.status !== 'banned' && user.status !== 'active' && (
                <button
                  type="button"
                  onClick={() => onAction('ban', user)}
                  disabled={busy}
                  className="px-2.5 py-1 bg-[#ef4444] text-white text-xs rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50 flex items-center gap-1"
                >
                  <ShieldAlert className="w-3 h-3" /> Ban
                </button>
              )}
            </>
          )}
          {isTrashTab && (
            <>
              <button
                type="button"
                onClick={() => onAction('restore', user)}
                disabled={busy}
                className="px-2.5 py-1 bg-[#029bba] text-white text-xs rounded-lg hover:bg-[#027a94] transition-colors disabled:opacity-50 flex items-center gap-1"
              >
                <RotateCcw className="w-3 h-3" /> Restore
              </button>
              <button
                type="button"
                onClick={() => onAction('permanent-delete', user)}
                disabled={busy}
                className="px-2.5 py-1 bg-[#ef4444] text-white text-xs rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50 flex items-center gap-1"
              >
                <Trash2 className="w-3 h-3" /> Delete
              </button>
            </>
          )}
        </div>

        {/* Right side actions */}
        <div className="flex gap-1 shrink-0">
          <Link
            href={`/admin/users/${user._id}`}
            className="p-1.5 text-gray-400 hover:text-[#029bba] hover:bg-gray-50 rounded transition-colors"
            title="View Details"
          >
            <Eye className="w-4 h-4" />
          </Link>
          {!isTrashTab && (
            <>
              <a
                href={`mailto:${user.emailMasked.replace('***', '')}`}
                className="p-1.5 text-gray-400 hover:text-[#029bba] hover:bg-gray-50 rounded transition-colors"
                title="Email user (opens your email client)"
              >
                <Mail className="w-4 h-4" />
              </a>
              {!isAdmin && (
                <button
                  type="button"
                  onClick={() => onAction('trash', user)}
                  disabled={busy}
                  className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors disabled:opacity-50"
                  title="Move to Trash"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────

function UsersContent(): React.ReactElement {
  const router = useRouter();

  // Data state
  const [users, setUsers] = useState<MaskedUser[]>([]);
  const [counts, setCounts] = useState<Counts>({
    all: 0, active: 0, pending: 0, suspended: 0, banned: 0, trash: 0,
  });
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);

  // Filter state
  const [activeTab, setActiveTab] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedRole, setSelectedRole] = useState<string>('');

  // UI state
  const [banner, setBanner] = useState<Banner | null>(null);
  const [confirmModal, setConfirmModal] = useState<{
    open: boolean; title: string; message: string;
    confirmLabel: string; confirmColor: 'primary' | 'danger' | 'warning';
    showReason: boolean; onConfirm: (reason: string) => Promise<void>;
  }>({
    open: false, title: '', message: '',
    confirmLabel: 'Confirm', confirmColor: 'primary',
    showReason: false, onConfirm: async () => {},
  });

  const showBanner = useCallback((type: 'success' | 'error', message: string) => {
    setBanner({ type, message });
    setTimeout(() => setBanner(null), 4000);
  }, []);

  // Fetch users
  const fetchUsers = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page:  String(page),
        limit: String(PAGE_SIZE),
        ...(activeTab === 'trash' ? { deleted: 'true' } : {}),
        ...(activeTab !== 'all' && activeTab !== 'trash' ? { status: activeTab } : {}),
        ...(searchQuery ? { search: searchQuery } : {}),
        ...(selectedRole ? { role: selectedRole } : {}),
      });

      const res = await fetch(`/api/admin/users?${params}`, {
        credentials: 'include',
      });

      const data = await res.json() as {
        success:    boolean;
        message?:   string;
        users?:     MaskedUser[];
        counts?:    Counts;
        pagination?: { page: number; pages: number };
      };

      if (data.success && data.users) {
        setUsers(data.users);
        if (data.counts) setCounts(data.counts);
        if (data.pagination) setTotalPages(data.pagination.pages);
      } else {
        showBanner('error', data.message ?? 'Failed to load users');
      }
    } catch {
      showBanner('error', 'Network error — could not load users');
    } finally {
      setLoading(false);
    }
  }, [page, activeTab, searchQuery, selectedRole, showBanner]);

  useEffect(() => {
    void fetchUsers();
  }, [fetchUsers]);

  // Sync tab with URL
  useEffect(() => {
    const status = router.query.status;
    if (typeof status === 'string') {
      const valid = TABS.map((t) => t.key);
      if (valid.includes(status as typeof valid[number])) {
        setActiveTab(status);
      }
    }
  }, [router.query.status]);

  const handleTabChange = (tabKey: string) => {
    setActiveTab(tabKey);
    setPage(1);
    void router.push(`/admin/users?status=${tabKey}`, undefined, { shallow: true });
  };

  // Perform mutation
  const performMutation = useCallback(async (
    url: string,
    method: 'PATCH' | 'PUT' | 'DELETE',
    body?: Record<string, unknown>,
    successMessage = 'Action completed'
  ): Promise<boolean> => {
    setBusy(true);
    try {
      const res = await fetch(url, {
        method,
        credentials: 'include',
        headers: body ? { 'Content-Type': 'application/json' } : undefined,
        body: body ? JSON.stringify(body) : undefined,
      });

      const data = await res.json() as { success: boolean; message?: string };

      if (data.success) {
        showBanner('success', data.message ?? successMessage);
        await fetchUsers();
        refreshSidebarStats();
        return true;
      } else {
        showBanner('error', data.message ?? 'Action failed');
        return false;
      }
    } catch {
      showBanner('error', 'Network error');
      return false;
    } finally {
      setBusy(false);
    }
  }, [fetchUsers, showBanner]);

  // Action dispatcher
  const handleAction = useCallback(async (action: string, user: MaskedUser, extra?: string) => {
    switch (action) {
      case 'activate':
        await performMutation(
          `/api/admin/users/${user._id}`,
          'PATCH',
          { status: 'active' },
          'User activated'
        );
        break;

      case 'suspend':
        setConfirmModal({
          open: true,
          title: 'Suspend User',
          message: `Suspend "${user.name}"? They won't be able to log in.`,
          confirmLabel: 'Suspend',
          confirmColor: 'warning',
          showReason: true,
          onConfirm: async (reason) => {
            const body: Record<string, unknown> = { status: 'suspended' };
            if (reason) body.statusReason = reason;
            await performMutation(`/api/admin/users/${user._id}`, 'PATCH', body, 'User suspended');
            setConfirmModal((p) => ({ ...p, open: false }));
          },
        });
        break;

      case 'ban':
        setConfirmModal({
          open: true,
          title: 'Ban User',
          message: `Ban "${user.name}"? Reason is required (min 5 chars).`,
          confirmLabel: 'Ban User',
          confirmColor: 'danger',
          showReason: true,
          onConfirm: async (reason) => {
            if (reason.length < 5) {
              showBanner('error', 'Reason must be at least 5 characters');
              return;
            }
            await performMutation(
              `/api/admin/users/${user._id}`,
              'PATCH',
              { status: 'banned', statusReason: reason },
              'User banned'
            );
            setConfirmModal((p) => ({ ...p, open: false }));
          },
        });
        break;

      case 'change-role':
        if (extra) {
          await performMutation(
            `/api/admin/users/${user._id}`,
            'PATCH',
            { role: extra },
            `Role changed to ${extra}`
          );
        }
        break;

      case 'trash':
        setConfirmModal({
          open: true,
          title: 'Move to Trash',
          message: `Move "${user.name}" to trash? You can restore later.`,
          confirmLabel: 'Move to Trash',
          confirmColor: 'danger',
          showReason: false,
          onConfirm: async () => {
            await performMutation(
              `/api/admin/users/${user._id}/trash`,
              'PUT',
              undefined,
              'User moved to trash'
            );
            setConfirmModal((p) => ({ ...p, open: false }));
          },
        });
        break;

      case 'restore':
        await performMutation(
          `/api/admin/users/${user._id}/trash`,
          'PUT',
          undefined,
          'User restored'
        );
        break;

      case 'permanent-delete':
        showBanner('error', 'Use the user detail page for permanent delete (requires confirmation code).');
        break;
    }
  }, [performMutation, showBanner]);

  return (
    <div className="p-4 md:p-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-[#004063]">Users Management</h1>
          <p className="text-sm text-gray-500">Manage all user accounts and permissions</p>
        </div>
        <button
          type="button"
          onClick={() => void fetchUsers()}
          disabled={loading}
          className="px-4 py-2 border border-gray-300 rounded-xl text-sm font-medium text-gray-700 hover:bg-gray-50 transition-colors flex items-center gap-2 disabled:opacity-50"
        >
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </button>
      </div>

      {/* Banner */}
      {banner && (
        <div className={`mb-4 rounded-xl p-4 border-l-4 flex items-center justify-between gap-4 ${
          banner.type === 'success'
            ? 'bg-[#f0fdf4] border-[#10b981] text-[#10b981]'
            : 'bg-[#fef2f2] border-[#ef4444] text-red-700'
        }`}>
          <div className="flex items-center gap-2">
            {banner.type === 'success' ? <CheckCircle className="w-4 h-4 shrink-0" /> : <AlertCircle className="w-4 h-4 shrink-0" />}
            <p className="text-sm font-medium">{banner.message}</p>
          </div>
          <button type="button" onClick={() => setBanner(null)} className="shrink-0 p-1 hover:bg-black/5 rounded">
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Tabs */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-6">
        {TABS.map((tab) => {
          const Icon = tab.icon;
          const count = counts[tab.key as keyof Counts] ?? 0;
          const isActive = activeTab === tab.key;
          return (
            <button
              key={tab.key}
              type="button"
              onClick={() => handleTabChange(tab.key)}
              className={`p-4 rounded-xl border text-left transition-all ${
                isActive
                  ? 'bg-[#029bba] text-white border-[#029bba] shadow-md'
                  : 'bg-white text-gray-700 border-gray-200 hover:border-[#029bba]/30'
              }`}
            >
              <div className="flex items-center justify-between mb-2">
                <Icon className={`w-5 h-5 ${isActive ? 'text-white' : 'text-gray-400'}`} />
                <span className={`text-2xl font-bold ${isActive ? 'text-white' : 'text-gray-900'}`}>
                  {count}
                </span>
              </div>
              <p className={`text-xs ${isActive ? 'text-white/90' : 'text-gray-500'}`}>
                {tab.label}
              </p>
            </button>
          );
        })}
      </div>

      {/* Filters */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-4 mb-6">
        <div className="flex flex-col md:flex-row gap-3">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search by name, email, phone, city..."
              value={searchQuery}
              onChange={(e) => { setSearchQuery(e.target.value); setPage(1); }}
              className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-[#029bba] focus:border-[#029bba] outline-none"
            />
          </div>
          <select
            value={selectedRole}
            onChange={(e) => { setSelectedRole(e.target.value); setPage(1); }}
            className="px-4 py-2.5 border border-gray-200 rounded-xl text-sm bg-white focus:ring-2 focus:ring-[#029bba] outline-none md:w-48"
          >
            <option value="">All Roles</option>
            {Object.entries(ALL_ROLE_LABELS).map(([k, v]) => (
              <option key={k} value={k}>{v}</option>
            ))}
          </select>
          {(searchQuery || selectedRole) && (
            <button
              type="button"
              onClick={() => { setSearchQuery(''); setSelectedRole(''); setPage(1); }}
              className="px-4 py-2.5 border border-gray-200 rounded-xl text-sm text-gray-600 hover:bg-gray-50 flex items-center gap-2"
            >
              <X className="w-4 h-4" />
              Clear
            </button>
          )}
        </div>
      </div>

      {/* User Grid */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 className="w-8 h-8 animate-spin text-[#029bba]" />
        </div>
      ) : users.length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
          <Users className="w-12 h-12 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">No users found</h3>
          <p className="text-sm text-gray-500">
            {activeTab === 'trash' ? 'No users in trash.' :
             (searchQuery || selectedRole) ? 'Try adjusting your filters.' :
             'No users to display.'}
          </p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {users.map((u) => (
              <UserCard
                key={u._id}
                user={u}
                isTrashTab={activeTab === 'trash'}
                busy={busy}
                onAction={handleAction}
              />
            ))}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-center gap-2 mt-8">
              <button
                type="button"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
                className="px-4 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 disabled:opacity-50"
              >
                Previous
              </button>
              <span className="text-sm text-gray-700 font-medium px-3">
                Page {page} of {totalPages}
              </span>
              <button
                type="button"
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page === totalPages}
                className="px-4 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 disabled:opacity-50"
              >
                Next
              </button>
            </div>
          )}
        </>
      )}

      {/* Confirm Modal */}
      <InlineConfirmModal
        open={confirmModal.open}
        title={confirmModal.title}
        message={confirmModal.message}
        confirmLabel={confirmModal.confirmLabel}
        confirmColor={confirmModal.confirmColor}
        showReason={confirmModal.showReason}
        loading={busy}
        onConfirm={confirmModal.onConfirm}
        onCancel={() => setConfirmModal((p) => ({ ...p, open: false }))}
      />
    </div>
  );
}

// ─── Page Export with Auth Guard ──────────────────────────────────────────────

export default function AdminUsersPage(): React.ReactElement {
  const { data: session, status } = useSession();
  const router = useRouter();

  useEffect(() => {
    if (status === 'loading') return;
    if (!session || session.user?.role !== 'admin') {
      void router.replace('/auth/login');
    }
  }, [session, status, router]);

  return (
    <>
      <Head>
        <title>Users Management | Highrise Admin</title>
        <meta name="robots" content="noindex, nofollow" />
      </Head>
      <AdminLayout>
        {status === 'loading' || !session || session.user?.role !== 'admin' ? (
          <div className="flex items-center justify-center min-h-[60vh]">
            <Loader2 className="w-8 h-8 animate-spin text-[#029bba]" />
          </div>
        ) : (
          <UsersContent />
        )}
      </AdminLayout>
    </>
  );
}

