// Helper function to get date range
function getDateRange(range: string): { startDate: Date; endDate: Date } {
  const endDate = new Date();
  endDate.setHours(23, 59, 59, 999);

  const startDate = new Date();
  startDate.setHours(0, 0, 0, 0);

  switch (range) {
    case '7days':
      startDate.setDate(startDate.getDate() - 7);
      break;
    case '30days':
      startDate.setDate(startDate.getDate() - 30);
      break;
    case '90days':
      startDate.setDate(startDate.getDate() - 90);
      break;
    case '1year':
      startDate.setFullYear(startDate.getFullYear() - 1);
      break;
    default:
      startDate.setDate(startDate.getDate() - 30);
  }

  return { startDate, endDate };
}

// Helper function to generate date labels
function generateDateLabels(startDate: Date, endDate: Date): string[] {
  const labels: string[] = [];
  const current = new Date(startDate);

  while (current <= endDate) {
    labels.push(current.toISOString().split('T')[0]);
    current.setDate(current.getDate() + 1);
  }

  return labels;
}

// Helper to calculate percentage change
function calculateChange(current: number, previous: number): string {
  if (previous === 0) return current > 0 ? '+100%' : '0%';
  const change = ((current - previous) / previous) * 100;
  const sign = change >= 0 ? '+' : '';
  return `${sign}${change.toFixed(1)}%`;
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  if (req.method !== 'GET') {
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  try {
    await dbConnect();

    const { range = '30days' } = req.query;
    const { startDate, endDate } = getDateRange(range as string);

    // Calculate previous period for comparison
    const periodLength = endDate.getTime() - startDate.getTime();
    const previousStartDate = new Date(startDate.getTime() - periodLength);
    const previousEndDate = new Date(startDate.getTime() - 1);

    // ============ OVERVIEW STATS ============

    // Current period counts
    const [
      totalProperties,
      propertiesApproved,
      propertiesPending,
      propertiesRejected,
      propertiesDraft,
      newPropertiesCurrentPeriod,
      newPropertiesPreviousPeriod,

      totalUsers,
      usersActive,
      usersPending,
      usersSuspended,
      usersBanned,
      newUsersCurrentPeriod,
      newUsersPreviousPeriod,

      totalBlogs,
      blogsPublished,
      blogsDraft,
      blogsScheduled,
      newBlogsCurrentPeriod,
      newBlogsPreviousPeriod,

      totalEmails,
      emailsSent,
      emailsFailed,
      emailsPending,
      newEmailsCurrentPeriod,
      newEmailsPreviousPeriod,

      totalDevelopers,
      developersVerified,
      developersPending,

      totalInquiries,
      inquiriesNew,
      inquiriesContacted,

      totalComments,
      commentsApproved,
      commentsPending,
    ] = await Promise.all([
      // Properties
      Property.countDocuments({ isDeleted: { $ne: true } }),
      Property.countDocuments({ status: 'approved', isDeleted: { $ne: true } }),
      Property.countDocuments({ status: 'pending', isDeleted: { $ne: true } }),
      Property.countDocuments({ status: 'rejected', isDeleted: { $ne: true } }),
      Property.countDocuments({ status: 'draft', isDeleted: { $ne: true } }),
      Property.countDocuments({ createdAt: { $gte: startDate, $lte: endDate }, isDeleted: { $ne: true } }),
      Property.countDocuments({ createdAt: { $gte: previousStartDate, $lte: previousEndDate }, isDeleted: { $ne: true } }),

      // Users
      User.countDocuments({ isDeleted: { $ne: true } }),
      User.countDocuments({ status: 'active', isDeleted: { $ne: true } }),
      User.countDocuments({ status: 'pending', isDeleted: { $ne: true } }),
      User.countDocuments({ status: 'suspended', isDeleted: { $ne: true } }),
      User.countDocuments({ status: 'banned', isDeleted: { $ne: true } }),
      User.countDocuments({ createdAt: { $gte: startDate, $lte: endDate }, isDeleted: { $ne: true } }),
      User.countDocuments({ createdAt: { $gte: previousStartDate, $lte: previousEndDate }, isDeleted: { $ne: true } }),

      // Blogs
      Blog.countDocuments({ isDeleted: { $ne: true } }),
      Blog.countDocuments({ status: 'published', isDeleted: { $ne: true } }),
      Blog.countDocuments({ status: 'draft', isDeleted: { $ne: true } }),
      Blog.countDocuments({ status: 'scheduled', isDeleted: { $ne: true } }),
      Blog.countDocuments({ createdAt: { $gte: startDate, $lte: endDate }, isDeleted: { $ne: true } }),
      Blog.countDocuments({ createdAt: { $gte: previousStartDate, $lte: previousEndDate }, isDeleted: { $ne: true } }),

      // Emails
      Email.countDocuments({}),
      Email.countDocuments({ status: 'sent' }),
      Email.countDocuments({ status: 'failed' }),
      Email.countDocuments({ status: 'pending' }),
      Email.countDocuments({ createdAt: { $gte: startDate, $lte: endDate } }),
      Email.countDocuments({ createdAt: { $gte: previousStartDate, $lte: previousEndDate } }),

      // Developers
      DeveloperProfile.countDocuments({ isDeleted: { $ne: true } }),
      DeveloperProfile.countDocuments({ status: 'approved', isDeleted: { $ne: true } }),
      DeveloperProfile.countDocuments({ status: 'pending', isDeleted: { $ne: true } }),

      // Inquiries (property leads only)
      Lead.countDocuments({ entityType: 'property', isArchived: false }),
      Lead.countDocuments({ entityType: 'property', isArchived: false, status: 'new' }),
      Lead.countDocuments({ entityType: 'property', isArchived: false, status: 'contacted' }),

      // Comments
      Comment.countDocuments({ isDeleted: { $ne: true } }),
      Comment.countDocuments({ status: 'approved', isDeleted: { $ne: true } }),
      Comment.countDocuments({ status: 'pending', isDeleted: { $ne: true } }),
    ]);

    // ============ TIME SERIES DATA ============

    const dateLabels = generateDateLabels(startDate, endDate);

    // Get daily user registrations
    const userGrowthData = await User.aggregate([
      {
        $match: {
          createdAt: { $gte: startDate, $lte: endDate },
          isDeleted: { $ne: true }
        }
      },
      {
        $group: {
          _id: { $dateToString: { format: '%Y-%m-%d', date: '$createdAt' } },
          count: { $sum: 1 }
        }
      },
      { $sort: { _id: 1 } }
    ]);

    // Get daily property submissions
    const propertyTrendsData = await Property.aggregate([
      {
        $match: {
          createdAt: { $gte: startDate, $lte: endDate },
          isDeleted: { $ne: true }
        }
      },
      {
        $group: {
          _id: { $dateToString: { format: '%Y-%m-%d', date: '$createdAt' } },
          count: { $sum: 1 }
        }
      },
      { $sort: { _id: 1 } }
    ]);

    // Get daily emails sent
    const emailTrendsData = await Email.aggregate([
      {
        $match: {
          createdAt: { $gte: startDate, $lte: endDate },
          status: 'sent'
        }
      },
      {
        $group: {
          _id: { $dateToString: { format: '%Y-%m-%d', date: '$createdAt' } },
          count: { $sum: 1 }
        }
      },
      { $sort: { _id: 1 } }
    ]);

    // Convert to chart-friendly format
    const userGrowthMap = new Map(userGrowthData.map(item => [item._id, item.count]));
    const propertyTrendsMap = new Map(propertyTrendsData.map(item => [item._id, item.count]));
    const emailTrendsMap = new Map(emailTrendsData.map(item => [item._id, item.count]));

    const userGrowthChart = dateLabels.map(date => ({
      date: new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      users: userGrowthMap.get(date) || 0
    }));

    const propertyTrendsChart = dateLabels.map(date => ({
      date: new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      properties: propertyTrendsMap.get(date) || 0
    }));

    const emailTrendsChart = dateLabels.map(date => ({
      date: new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      emails: emailTrendsMap.get(date) || 0
    }));

    // ============ TOP PROPERTIES ============

    const topProperties = await Property.find({ isDeleted: { $ne: true } })
      .sort({ views: -1, createdAt: -1 })
      .limit(5)
      .select('title views status createdAt city propertyType')
      .lean();

    // Get inquiry counts for top properties
    const topPropertiesWithInquiries = await Promise.all(
      topProperties.map(async (property: any) => {
        const inquiryCount = await Lead.countDocuments({
          entityType: 'property',
          property: property._id,
          isArchived: false,
        });
        return {
          _id: property._id,
          title: property.title || 'Untitled Property',
          views: property.views || 0,
          inquiries: inquiryCount,
          status: property.status || 'pending',
          city: property.city || 'N/A',
          propertyType: property.propertyType || 'N/A'
        };
      })
    );

    // ============ TOP BLOGS ============

    const topBlogs = await Blog.find({ 
      isDeleted: { $ne: true },
      status: 'published'
    })
      .sort({ views: -1 })
      .limit(5)
      .select('title views slug createdAt')
      .lean();

    const topBlogsWithComments = await Promise.all(
      topBlogs.map(async (blog: any) => {
        const commentCount = await Comment.countDocuments({ 
          blogId: blog._id,
          status: 'approved',
          isDeleted: { $ne: true }
        });
        return {
          _id: blog._id,
          title: blog.title || 'Untitled Blog',
          views: blog.views || 0,
          comments: commentCount,
          slug: blog.slug
        };
      })
    );

    // ============ RESPONSE ============

    const response = {
      success: true,
      data: {
        overview: {
          properties: {
            total: totalProperties,
            change: calculateChange(newPropertiesCurrentPeriod, newPropertiesPreviousPeriod),
            approved: propertiesApproved,
            pending: propertiesPending,
            rejected: propertiesRejected,
            draft: propertiesDraft
          },
          users: {
            total: totalUsers,
            change: calculateChange(newUsersCurrentPeriod, newUsersPreviousPeriod),
            active: usersActive,
            pending: usersPending,
            suspended: usersSuspended,
            banned: usersBanned
          },
          blogs: {
            total: totalBlogs,
            change: calculateChange(newBlogsCurrentPeriod, newBlogsPreviousPeriod),
            published: blogsPublished,
            draft: blogsDraft,
            scheduled: blogsScheduled
          },
          emails: {
            total: totalEmails,
            change: calculateChange(newEmailsCurrentPeriod, newEmailsPreviousPeriod),
            sent: emailsSent,
            failed: emailsFailed,
            pending: emailsPending
          },
          developers: {
            total: totalDevelopers,
            verified: developersVerified,
            pending: developersPending
          },
          inquiries: {
            total: totalInquiries,
            new: inquiriesNew,
            contacted: inquiriesContacted
          },
          comments: {
            total: totalComments,
            approved: commentsApproved,
            pending: commentsPending
          }
        },
        charts: {
          userGrowth: userGrowthChart,
          propertyTrends: propertyTrendsChart,
          emailTrends: emailTrendsChart,
          propertyStatus: [
            { name: 'Approved', value: propertiesApproved, color: '#22c55e' },
            { name: 'Pending', value: propertiesPending, color: '#eab308' },
            { name: 'Rejected', value: propertiesRejected, color: '#ef4444' },
            { name: 'Draft', value: propertiesDraft, color: '#6b7280' }
          ],
          emailStatus: [
            { name: 'Sent', value: emailsSent, color: '#22c55e' },
            { name: 'Failed', value: emailsFailed, color: '#ef4444' },
            { name: 'Pending', value: emailsPending, color: '#eab308' }
          ],
          userStatus: [
            { name: 'Active', value: usersActive, color: '#22c55e' },
            { name: 'Pending', value: usersPending, color: '#eab308' },
            { name: 'Suspended', value: usersSuspended, color: '#f97316' },
            { name: 'Banned', value: usersBanned, color: '#ef4444' }
          ]
        },
        topProperties: topPropertiesWithInquiries,
        topBlogs: topBlogsWithComments,
        dateRange: {
          start: startDate.toISOString(),
          end: endDate.toISOString(),
          range: range
        }
      }
    };

    return res.status(200).json(response);

  } catch (error: any) {
    console.error('Analytics API Error:', error);
    return res.status(500).json({
      success: false,
      message: 'Failed to fetch analytics data',
      error: error?.message || 'Unknown error'
    });
  }
}

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import { requireAdmin } from "@/lib/requireAdmin";
import ApiKey from '@/models/ApiKey';
import crypto from 'crypto';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const admin = await requireAdmin(req, res);
  if (!admin) return;

  await dbConnect();


  if (req.method === 'GET') {
    try {
      const keys = await ApiKey.find()
        .select('-hashedKey')
        .sort({ createdAt: -1 })
        .lean();

      return res.status(200).json({
        success: true,
        apiKeys: keys,
      });
    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Error fetching API keys',
        error: error.message,
      });
    }
  }

  if (req.method === 'POST') {
    try {
      const { name, permissions, expiresAt } = req.body;

      if (!name) {
  return res.status(400).json({
    success: false,
    message: "Name is required",
  });
}


      // Generate API key
      const key = 'hrpk_' + crypto.randomBytes(32).toString('hex');
      const hashedKey = crypto.createHash('sha256').update(key).digest('hex');

      const apiKey = await ApiKey.create({
        name,
        key: key.substring(0, 12) + '...' + key.substring(key.length - 4), // Store partial for display
        hashedKey,
        permissions: permissions || ['blog:create', 'blog:read'],
       createdBy: admin.id,
        expiresAt: expiresAt ? new Date(expiresAt) : null,
      });

      // Return the full key ONLY on creation (won't be stored/shown again)
      return res.status(201).json({
        success: true,
        message: 'API key created successfully. Save this key now - it will not be shown again!',
        apiKey: {
          ...apiKey.toObject(),
          fullKey: key, // Only returned on creation!
        },
      });
    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Error creating API key',
        error: error.message,
      });
    }
  }

  if (req.method === 'DELETE') {
    try {
      const { keyId } = req.body;

      await ApiKey.findByIdAndDelete(keyId);

      return res.status(200).json({
        success: true,
        message: 'API key deleted',
      });
    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Error deleting API key',
        error: error.message,
      });
    }
  }

  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

// pages/api/admin/applications/[id].ts
// 🔒 ADMIN APPLICATION ACTIONS API - HIGHRISE.PK
// V6.0.0 — Society Tier Added
// GET detail | PATCH approve/reject/request_info
// Handles agent + developer + society applications
// ═══════════════════════════════════════════════════════════════

import crypto from 'crypto';
import type { NextApiRequest, NextApiResponse } from 'next';
import { Types, isValidObjectId } from 'mongoose';
import { z } from 'zod';

import dbConnect from '@/lib/dbConnect';
import { requireAdmin } from '@/lib/requireAuth';
import { rateLimitAdmin } from '@/lib/rateLimit';
import { logSecurityEvent } from '@/lib/security/logSecurityEvent';
import { sendEmail } from '@/lib/email';
import {
  agentOnboardingApprovedTemplate,
  agentOnboardingRejectedTemplate,
  agentOnboardingInfoRequiredTemplate,
  developerOnboardingApprovedTemplate,
  developerOnboardingRejectedTemplate,
  developerOnboardingInfoRequiredTemplate,
  societyOnboardingApprovedTemplate,
  societyOnboardingRejectedTemplate,
  societyOnboardingInfoRequiredTemplate,
} from '@/lib/email-templates';

import User from '@/models/User';
import AgentProfile from '@/models/AgentProfile';
import DeveloperProfile from '@/models/DeveloperProfile';
import SocietyProfile from '@/models/SocietyProfile';

// ─── Types ─────────────────────────────────────────────────────

type AppType = 'agent' | 'developer' | 'society';
type AdminAction = 'approve' | 'reject' | 'request_info';

interface ApiResponse {
  success: boolean;
  message?: string;
  data?: unknown;
  requestId: string;
}

interface QueryShape {
  id?: string | string[];
  type?: string | string[];
}

// ─── Validation schemas ────────────────────────────────────────

const ActionSchema = z.object({
  action: z.enum(['approve', 'reject', 'request_info']),
  reason: z.string().trim().max(1000).optional(),
});

const TypeSchema = z.enum(['agent', 'developer', 'society']);

// ─── Security headers ──────────────────────────────────────────

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id', requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
}

// ─── Helpers ───────────────────────────────────────────────────

function getClientIp(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  return req.socket?.remoteAddress ?? 'unknown';
}

function parseQuery(req: NextApiRequest): {
  id: string | null;
  type: AppType | null;
} {
  const q = req.query as QueryShape;
  const rawId = Array.isArray(q.id) ? q.id[0] : q.id;
  const rawType = Array.isArray(q.type) ? q.type[0] : q.type;

  const id = typeof rawId === 'string' && isValidObjectId(rawId) ? rawId : null;
  const typeResult = TypeSchema.safeParse(rawType);
  const type = typeResult.success ? typeResult.data : null;

  return { id, type };
}

// ─── Handler ───────────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
): Promise<void> {
  const requestId = crypto.randomUUID();
  setSecurityHeaders(res, requestId);

  // ── Rate limit ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    res.setHeader('Retry-After', String(rl.retryAfter ?? 60));
    res.status(429).json({
      success: false,
      message: `Too many requests. Retry in ${rl.retryAfter ?? 60} seconds.`,
      requestId,
    });
    return;
  }

  // ── Auth ───────────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  // ── Parse + validate query ─────────────────────────────────
  const { id, type } = parseQuery(req);

  if (!id) {
    res.status(400).json({
      success: false,
      message: 'Invalid application ID',
      requestId,
    });
    return;
  }

  if (!type) {
    res.status(400).json({
      success: false,
      message: 'Application type required (?type=agent|developer|society)',
      requestId,
    });
    return;
  }

  // ── Route by method ────────────────────────────────────────
  try {
    await dbConnect();

    if (req.method === 'GET') {
      return await handleGet(req, res, auth.id, id, type, requestId);
    }

    if (req.method === 'PATCH') {
      return await handlePatch(req, res, auth.id, id, type, requestId);
    }

    res.setHeader('Allow', 'GET, PATCH');
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
  } catch (error: unknown) {
    const message =
      error instanceof Error ? error.message : 'Unknown error';

    await logSecurityEvent({
      type: 'system_error',
      severity: 'high',
      userId: auth.id,
      req,
      metadata: {
        endpoint: '/api/admin/applications/[id]',
        method: req.method,
        appId: id,
        appType: type,
        errorMessage: message,
      },
    }).catch(() => {
      /* never throw */
    });

    res.status(500).json({
      success: false,
      message: 'Internal server error',
      requestId,
    });
  }
}

// ═══════════════════════════════════════════════════════════════
// GET — Application Detail
// ═══════════════════════════════════════════════════════════════

async function handleGet(
  _req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
  adminId: string,
  id: string,
  type: AppType,
  requestId: string
): Promise<void> {
  // ── AGENT ──────────────────────────────────────────────────
  if (type === 'agent') {
    const profile = await AgentProfile.findById(id)
      .select(
        '+cnicEncrypted +licenseEncrypted +ntnEncrypted +secpEncrypted +phoneEncrypted +whatsappEncrypted'
      )
      .populate(
        'user',
        'email name displayName onboardingStatus onboardingRole kycVerified role'
      );

    if (!profile || profile.isDeleted) {
      res.status(404).json({
        success: false,
        message: 'Application not found',
        requestId,
      });
      return;
    }

    const decrypted = {
      cnic: profile.getCNIC?.() ?? null,
      cnicMasked: profile.getMaskedCNIC?.() ?? '—',
      license: profile.getLicense?.() ?? null,
      ntn: profile.getNTN?.() ?? null,
      secp: profile.getSECP?.() ?? null,
      phone: profile.getPhone?.() ?? null,
      phoneMasked: profile.getMaskedPhone?.() ?? '—',
    };

    const profileObj = profile.toJSON();

    res.status(200).json({
      success: true,
      data: { type: 'agent', profile: profileObj, decrypted },
      requestId,
    });
    return;
  }

  // ── DEVELOPER ──────────────────────────────────────────────
  if (type === 'developer') {
    const profile = await DeveloperProfile.findById(id)
      .select(
        '+ntnEncrypted +secpEncrypted +authorizedPersonCnicEncrypted +phoneEncrypted +whatsappEncrypted +authorizedPersonPhoneEncrypted +adminNotes'
      )
      .populate(
        'user',
        'email name displayName onboardingStatus onboardingRole kycVerified role'
      );

    if (!profile || profile.isDeleted) {
      res.status(404).json({
        success: false,
        message: 'Application not found',
        requestId,
      });
      return;
    }

    const decrypted = {
      ntn: profile.getNTN?.() ?? null,
      secp: profile.getSECP?.() ?? null,
      authorizedPersonCnic: profile.getAuthorizedPersonCNIC?.() ?? null,
      authorizedPersonCnicMasked:
        profile.getMaskedAuthorizedPersonCNIC?.() ?? '—',
      phone: profile.getPhone?.() ?? null,
      phoneMasked: profile.getMaskedPhone?.() ?? '—',
      authorizedPersonPhone: profile.getAuthorizedPersonPhone?.() ?? null,
    };

    const profileObj = profile.toJSON();

    res.status(200).json({
      success: true,
      data: { type: 'developer', profile: profileObj, decrypted },
      requestId,
    });
    return;
  }

  // ── SOCIETY ────────────────────────────────────────────────
  const profile = await SocietyProfile.findById(id)
    .select(
      '+authorizedPersonCnicEncrypted +authorizedPersonCnicHash +authorizedPersonPhoneEncrypted +bankIban'
    )
    .populate(
      'userId',
      'email name displayName onboardingStatus onboardingRole kycVerified role'
    );

  if (!profile) {
    res.status(404).json({
      success: false,
      message: 'Application not found',
      requestId,
    });
    return;
  }

  let decryptedCnic: string | null = null;
  let maskedCnic = '—';

  if (profile.authorizedPersonCnicEncrypted) {
    try {
      const { kycDecrypt, maskCnic } = await import('@/lib/kycCrypto');
      decryptedCnic = kycDecrypt(profile.authorizedPersonCnicEncrypted, {
        adminId,
        reason: 'admin_review_society_application',
      });
      maskedCnic = maskCnic(decryptedCnic);
    } catch {
      decryptedCnic = null;
      maskedCnic = '—';
    }
  }

  const profileObj = profile.toJSON();

  res.status(200).json({
    success: true,
    data: {
      type: 'society',
      profile: profileObj,
      decrypted: {
        authorizedPersonCnic: decryptedCnic,
        authorizedPersonCnicMasked: maskedCnic,
      },
    },
    requestId,
  });
}

// ═══════════════════════════════════════════════════════════════
// HELPERS
// ═══════════════════════════════════════════════════════════════

/**
 * Profile shape that has the addAuditEntry method.
 * Used to narrow union types when calling audit helper.
 */
interface ProfileWithAudit {
  addAuditEntry: (
    action: string,
    performedBy: Types.ObjectId,
    payload: Record<string, unknown>,
    ip: string
  ) => Promise<unknown>;
}

/**
 * Type guard — returns true if profile has addAuditEntry method.
 * Society profiles don't have this method (they use auditTrail.push directly).
 */
function hasAddAuditEntry(profile: unknown): profile is ProfileWithAudit {
  return (
    profile !== null &&
    typeof profile === 'object' &&
    'addAuditEntry' in profile &&
    typeof (profile as { addAuditEntry?: unknown }).addAuditEntry === 'function'
  );
}

// ═══════════════════════════════════════════════════════════════
// PATCH — Admin Action (approve / reject / request_info)
// ═══════════════════════════════════════════════════════════════

async function handlePatch(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
  adminId: string,
  id: string,
  type: AppType,
  requestId: string
): Promise<void> {
  // Validate body
  const parsed = ActionSchema.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({
      success: false,
      message: 'Invalid request body. Provide { action, reason? }',
      requestId,
    });
    return;
  }

  const { action, reason } = parsed.data;

  // Reason required for reject + request_info
  if ((action === 'reject' || action === 'request_info') && !reason) {
    res.status(400).json({
      success: false,
      message: `A reason is required when ${
        action === 'reject' ? 'rejecting' : 'requesting more information'
      }.`,
      requestId,
    });
    return;
  }

  const ip = getClientIp(req);
  const adminObjectId = new Types.ObjectId(adminId);

  // ── Fetch profile (NOT lean — need .save()) ───────────────
  let profile:
    | InstanceType<typeof AgentProfile>
    | InstanceType<typeof DeveloperProfile>
    | InstanceType<typeof SocietyProfile>
    | null = null;

  if (type === 'agent') {
    profile = await AgentProfile.findById(id);
    if (!profile || (profile as { isDeleted?: boolean }).isDeleted) {
      res.status(404).json({
        success: false,
        message: 'Application not found',
        requestId,
      });
      return;
    }
  } else if (type === 'developer') {
    profile = await DeveloperProfile.findById(id);
    if (!profile || (profile as { isDeleted?: boolean }).isDeleted) {
      res.status(404).json({
        success: false,
        message: 'Application not found',
        requestId,
      });
      return;
    }
  } else {
    profile = await SocietyProfile.findById(id);
    if (!profile) {
      res.status(404).json({
        success: false,
        message: 'Application not found',
        requestId,
      });
      return;
    }
  }

  // ── Validate state transitions ─────────────────────────────
  const currentStatus = profile.status;
  if (currentStatus === 'approved' && action === 'approve') {
    res.status(409).json({
      success: false,
      message: 'Application is already approved.',
      requestId,
    });
    return;
  }
  if (currentStatus === 'suspended') {
    res.status(409).json({
      success: false,
      message:
        'Suspended applications cannot be modified through this endpoint.',
      requestId,
    });
    return;
  }

  // ── Resolve userId (society uses userId, agent/dev use user) ──
  const profileUserId =
    type === 'society'
      ? (profile as InstanceType<typeof SocietyProfile>).userId
      : (profile as InstanceType<typeof AgentProfile>).user;

  // ── Fetch user (NOT lean — need .save()) ───────────────────
  const userDoc = await User.findById(profileUserId);
  if (!userDoc || userDoc.isDeleted) {
    res.status(404).json({
      success: false,
      message: 'Associated user not found',
      requestId,
    });
    return;
  }

  const now = new Date();

  // ═══════════════════════════════════════════════════════════
  // ACTION: APPROVE
  // ═══════════════════════════════════════════════════════════
  if (action === 'approve') {
    profile.status = 'approved';
    profile.rejectionReason = undefined;
    profile.infoRequiredReason = undefined;

    if (type === 'agent') {
      const ap = profile as InstanceType<typeof AgentProfile>;
      ap.verifiedAt = now;
      ap.verifiedBy = adminObjectId;
      if (ap.cnicHash && !ap.cnicVerified) ap.cnicVerified = true;
      if (ap.licenseHash && !ap.licenseVerified) ap.licenseVerified = true;
      if (ap.ntnHash && !ap.ntnVerified) ap.ntnVerified = true;
    } else if (type === 'developer') {
      const dp = profile as InstanceType<typeof DeveloperProfile>;
      dp.verifiedAt = now;
      dp.verifiedBy = adminObjectId;
      dp.kycStatus = 'verified';
      dp.isVerified = true;
      dp.lastVerifiedAt = now;
    } else {
      const sp = profile as InstanceType<typeof SocietyProfile>;
      sp.cnicVerified = true;
      sp.nocVerified = true;
      sp.kycStatus = 'verified';
      sp.trustScore = 70;
      sp.verifiedAt = now;
      sp.reviewedBy = adminObjectId;
      sp.reviewedAt = now;
      sp.auditTrail.push({
        action: 'approved',
        performedBy: adminObjectId,
        performedAt: now,
        note: `Approved by admin ${adminId}`,
      });
    }

    // Audit entry for agent/developer (method-based)
    if (type !== 'society' && hasAddAuditEntry(profile)) {
      await profile.addAuditEntry(
        `admin_approved_${type}_application`,
        adminObjectId,
        { previousStatus: currentStatus, newStatus: 'approved' },
        ip
      );
    }

    // Update user
    userDoc.role = type;
    userDoc.onboardingStatus = 'approved';
    userDoc.onboardingReviewedAt = now;
    userDoc.onboardingReviewedBy = adminObjectId;
    userDoc.onboardingRejectionReason = undefined;
    userDoc.kycVerified = true;
    userDoc.tokenVersion = (userDoc.tokenVersion ?? 0) + 1;

    await Promise.all([profile.save(), userDoc.save()]);

    await logSecurityEvent({
      type:
        type === 'agent'
          ? 'agent_profile_created'
          : type === 'developer'
          ? 'developer_profile_created'
          : 'admin_action',
      severity: 'low',
      userId: String(userDoc._id),
      req,
      metadata: {
        action: 'approved',
        appId: id,
        appType: type,
        adminId,
        roleAssigned: type,
      },
    });

    sendApprovalEmail(type, userDoc, profile).catch(() => {
      /* silent */
    });

    const label =
      type === 'agent'
        ? 'Agent'
        : type === 'developer'
        ? 'Developer'
        : 'Society';

    res.status(200).json({
      success: true,
      message: `${label} application approved successfully.`,
      data: { id, newStatus: 'approved', userRole: type },
      requestId,
    });
    return;
  }

  // ═══════════════════════════════════════════════════════════
  // ACTION: REJECT
  // ═══════════════════════════════════════════════════════════
  if (action === 'reject') {
    profile.status = 'rejected';
    profile.rejectionReason = reason;
    profile.infoRequiredReason = undefined;

    if (type === 'developer') {
      const dp = profile as InstanceType<typeof DeveloperProfile>;
      dp.kycStatus = 'rejected';
    }

    if (type === 'society') {
      const sp = profile as InstanceType<typeof SocietyProfile>;
      sp.kycStatus = 'failed';
      sp.reviewedBy = adminObjectId;
      sp.reviewedAt = now;
      sp.auditTrail.push({
        action: 'rejected',
        performedBy: adminObjectId,
        performedAt: now,
        note: reason ?? 'Rejected by admin',
      });
    }

    if (type !== 'society' && hasAddAuditEntry(profile)) {
      await profile.addAuditEntry(
        `admin_rejected_${type}_application`,
        adminObjectId,
        { previousStatus: currentStatus, newStatus: 'rejected', reason },
        ip
      );
    }

    userDoc.onboardingStatus = 'rejected';
    userDoc.onboardingReviewedAt = now;
    userDoc.onboardingReviewedBy = adminObjectId;
    userDoc.onboardingRejectionReason = reason;
    userDoc.tokenVersion = (userDoc.tokenVersion ?? 0) + 1;

    await Promise.all([profile.save(), userDoc.save()]);

    await logSecurityEvent({
      type: 'suspicious_activity',
      severity: 'medium',
      userId: String(userDoc._id),
      req,
      metadata: {
        action: 'rejected',
        appId: id,
        appType: type,
        adminId,
        reason: reason ?? '',
      },
    });

    sendRejectionEmail(type, userDoc, profile, reason ?? '').catch(() => {
      /* silent */
    });

    const label =
      type === 'agent'
        ? 'Agent'
        : type === 'developer'
        ? 'Developer'
        : 'Society';

    res.status(200).json({
      success: true,
      message: `${label} application rejected.`,
      data: { id, newStatus: 'rejected', reason },
      requestId,
    });
    return;
  }

  // ═══════════════════════════════════════════════════════════
  // ACTION: REQUEST INFO
  // ═══════════════════════════════════════════════════════════
  if (action === 'request_info') {
    profile.status = 'info_required';
    profile.infoRequiredReason = reason;
    profile.rejectionReason = undefined;

    if (type === 'society') {
      const sp = profile as InstanceType<typeof SocietyProfile>;
      sp.reviewedBy = adminObjectId;
      sp.reviewedAt = now;
      sp.auditTrail.push({
        action: 'info_required',
        performedBy: adminObjectId,
        performedAt: now,
        note: reason ?? 'Additional information requested',
      });
    }

    if (type !== 'society' && hasAddAuditEntry(profile)) {
      await profile.addAuditEntry(
        `admin_requested_info_${type}`,
        adminObjectId,
        { previousStatus: currentStatus, newStatus: 'info_required', reason },
        ip
      );
    }

    userDoc.onboardingStatus = 'info_required';
    userDoc.onboardingReviewedAt = now;
    userDoc.onboardingReviewedBy = adminObjectId;
    userDoc.onboardingRejectionReason = reason;
    userDoc.tokenVersion = (userDoc.tokenVersion ?? 0) + 1;

    await Promise.all([profile.save(), userDoc.save()]);

    await logSecurityEvent({
      type: 'admin_action',
      severity: 'low',
      userId: String(userDoc._id),
      req,
      metadata: {
        action: 'info_requested',
        appId: id,
        appType: type,
        adminId,
        reason: reason ?? '',
      },
    });

    sendInfoRequiredEmail(type, userDoc, profile, reason ?? '').catch(() => {
      /* silent */
    });

    res.status(200).json({
      success: true,
      message: 'Additional information requested from applicant.',
      data: { id, newStatus: 'info_required', reason },
      requestId,
    });
    return;
  }
}

