// pages/api/admin/blogs/[id]/index.ts
// 🔒 ENTERPRISE v2.0 - Admin Blog Update & Delete with Cloudinary Cleanup & RBAC

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import dbConnect from '@/lib/db';
import Blog from '@/models/Blog';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import cloudinary, { uploadBuffer } from '@/lib/cloudinary';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { checkPermission } from '@/lib/permissions';
import { rateLimitAdmin } from '@/lib/rateLimit';
import { z } from 'zod';
import { parseBlogImageDataUrl, sanitizeBlogHtml } from '@/lib/blogSecurity';

export const config = {
  api: { bodyParser: { sizeLimit: '15mb' } },
};

const MAX_TIME_MS = 5000;

const UpdateBlogSchema = z.object({
  title: z.string().trim().min(5).max(200).optional(),
  excerpt: z.string().trim().min(10).max(500).optional(),
  content: z.string().trim().min(50).optional(),
  category: z.string().trim().max(100).optional(),
  authorName: z.string().trim().max(120).optional(),
  imageBase64: z.string().optional(),
  image: z.object({ url: z.string().url(), public_id: z.string().min(1).max(500) }).optional(),
  tags: z.array(z.string().trim().max(60)).max(30).optional(),
  status: z.enum(['draft', 'published', 'scheduled']).optional(),
  featured: z.boolean().optional(),
  metaTitle: z.string().max(70).optional().nullable(),
  metaDescription: z.string().max(160).optional().nullable(),
  scheduledFor: z.string().datetime().optional().nullable(),
  enableTOC: z.boolean().optional(),
  allowComments: z.boolean().optional(),
}).strict();

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0] || req.socket.remoteAddress || '0.0.0.0';
  const { id } = req.query;

  if (!id || !mongoose.Types.ObjectId.isValid(id as string)) {
    return res.status(400).json({ success: false, message: 'Invalid blog ID' });
  }

  try {
    await dbConnect();

    const rl = await rateLimitAdmin(req);
    if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

    const session = await getServerSession(req, res, authOptions);
    if (!session?.user) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const admin: any = await User.findById(session.user.id).lean();
    if (!['admin', 'superadmin', 'editor'].includes(admin?.role?.toLowerCase())) {
      return res.status(403).json({ success: false, message: 'Admin access required' });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ GET: VIEW SINGLE BLOG DETAILS
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'GET') {
      if (!checkPermission(admin, 'blog_view_details')) return res.status(403).json({ success: false, message: 'Permission denied' });

      const blog = await Blog.findById(id).lean().maxTimeMS(MAX_TIME_MS);
      if (!blog) return res.status(404).json({ success: false, message: 'Blog not found' });

      return res.status(200).json({ success: true, blog });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ PUT: UPDATE BLOG
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'PUT') {
      if (!checkPermission(admin, 'blog_edit')) return res.status(403).json({ success: false, message: 'Permission denied' });

      const blog: any = await Blog.findById(id);
      if (!blog) return res.status(404).json({ success: false, message: 'Blog not found' });

      const parsedUpdate = UpdateBlogSchema.safeParse(req.body);
      if (!parsedUpdate.success) {
        return res.status(400).json({ success: false, message: 'Invalid blog update', error: parsedUpdate.error.format() });
      }

      const { imageBase64, ...updates } = parsedUpdate.data;
      if (updates.content) updates.content = sanitizeBlogHtml(updates.content);

      // Handle Image Replacement through the centralized validated upload path.
      if (imageBase64) {
        const parsedImage = parseBlogImageDataUrl(imageBase64);
        if (!parsedImage) {
          return res.status(400).json({ success: false, message: 'Invalid blog cover image' });
        }
        const uploadResult = await uploadBuffer(
          parsedImage.buffer,
          parsedImage.filename,
          'blog',
          'image',
          { tags: ['blog-cover'] },
        );
        if (!uploadResult.success || !uploadResult.secureUrl || !uploadResult.publicId) {
          return res.status(500).json({ success: false, message: 'Failed to upload new image' });
        }
        if (blog.image?.public_id) {
          await cloudinary.uploader.destroy(blog.image.public_id).catch(() => undefined);
        }
        updates.image = { url: uploadResult.secureUrl, public_id: uploadResult.publicId };
      }

      (updates as Record<string, unknown>).lastEditedBy = admin._id;
      (updates as Record<string, unknown>).lastEditedAt = new Date();

      // Trigger pre-save hooks by saving document instance instead of findOneAndUpdate
      Object.assign(blog, updates);
      await blog.save();

      SecurityEvent.create({
        eventType: 'admin_blog_updated',
        userId: admin._id,
        severity: 'medium',
        ipAddress: ip,
        metadata: { blogId: id, title: blog.title }
      }).catch(console.error);

      return res.status(200).json({ success: true, message: 'Blog updated successfully', blog });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ DELETE: SOFT OR PERMANENT
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'DELETE') {
      const { permanent = 'false' } = req.query;

      if (!checkPermission(admin, permanent === 'true' ? 'blog_permanent_delete' : 'blog_delete')) {
        return res.status(403).json({ success: false, message: 'Permission denied' });
      }

      const blog: any = await Blog.findById(id);
      if (!blog) return res.status(404).json({ success: false, message: 'Blog not found' });

      if (permanent === 'true') {
        // Superadmin ONLY for permanent delete
        if (admin.role !== 'superadmin') return res.status(403).json({ success: false, message: 'SuperAdmin required' });

        if (blog.image?.public_id) {
          await cloudinary.uploader.destroy(blog.image.public_id).catch(console.error);
        }

        await Blog.findByIdAndDelete(id);

        SecurityEvent.create({
          eventType: 'admin_blog_hard_deleted',
          userId: admin._id,
          severity: 'critical',
          ipAddress: ip,
          metadata: { blogId: id, title: blog.title }
        }).catch(console.error);

        return res.status(200).json({ success: true, message: 'Blog permanently deleted' });
      } 

      // Soft Delete
      blog.isDeleted = true;
      blog.deletedAt = new Date();
      blog.status = 'draft'; // Take offline
      await blog.save();

      SecurityEvent.create({
        eventType: 'admin_blog_soft_deleted',
        userId: admin._id,
        severity: 'high',
        ipAddress: ip,
        metadata: { blogId: id, title: blog.title }
      }).catch(console.error);

      return res.status(200).json({ success: true, message: 'Blog moved to trash', blog });
    }

    return res.status(405).json({ success: false, message: 'Method not allowed' });
  } catch (error: any) {
    console.error('Admin Blog Action Error:', error);
    return res.status(500).json({ success: false, message: 'Internal Server Error' });
  }
}

// pages/api/admin/blogs/[id]/restore.ts
// 🔒 ENTERPRISE v2.0 - Admin Blog Restore with RBAC & Audit Trail

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import dbConnect from '@/lib/db';
import Blog from '@/models/Blog';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { checkPermission } from '@/lib/permissions';
import { rateLimitAdmin } from '@/lib/rateLimit';

const MAX_TIME_MS = 5000;

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0] || req.socket.remoteAddress || '0.0.0.0';

  if (req.method !== 'PATCH') {
    res.setHeader('Allow', ['PATCH']);
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  // Validate ID
  const { id } = req.query;
  if (!id || !mongoose.Types.ObjectId.isValid(id as string)) {
    return res.status(400).json({ success: false, message: 'Invalid blog ID format' });
  }

  try {
    await dbConnect();

    // 1. Rate Limiting
    const rl = await rateLimitAdmin(req);
    if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

    // 2. Authentication & Authorization
    const session = await getServerSession(req, res, authOptions);
    if (!session?.user) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const admin: any = await User.findById(session.user.id).select('role permissions').lean();
    if (!['admin', 'superadmin', 'editor'].includes(admin?.role?.toLowerCase())) {
      return res.status(403).json({ success: false, message: 'Admin access required' });
    }

    // 3. Permission Check
    if (!checkPermission(admin, 'blog_restore')) {
      return res.status(403).json({ success: false, message: 'Permission denied' });
    }

    // 4. Fetch Blog
    const blog: any = await Blog.findById(id).maxTimeMS(MAX_TIME_MS);
    if (!blog) {
      return res.status(404).json({ success: false, message: 'Blog not found' });
    }

    if (!blog.isDeleted) {
      return res.status(400).json({ success: false, message: 'Blog is already active' });
    }

    // 5. Restore Blog
    blog.isDeleted = false;
    blog.deletedAt = null;
    blog.deletedBy = undefined; // Clear the previous delete tracker
    blog.status = 'draft'; // Safely default to draft to prevent accidental publish
    blog.lastEditedBy = admin._id;
    blog.lastEditedAt = new Date();

    await blog.save();

    // 6. Audit Log
    SecurityEvent.create({
      eventType: 'admin_blog_restored',
      userId: admin._id,
      severity: 'medium',
      ipAddress: ip,
      metadata: { 
        blogId: id,
        title: blog.title 
      }
    }).catch(console.error);

    return res.status(200).json({
      success: true,
      message: 'Blog restored successfully (moved to drafts)',
      blog: {
        _id: blog._id,
        isDeleted: blog.isDeleted,
        status: blog.status
      },
    });

  } catch (error: any) {
    console.error('Blog Restore Error:', error);
    return res.status(500).json({ success: false, message: 'Internal Server Error' });
  }
}

// pages/api/admin/blogs/[id]/status.ts
// 🔒 ENTERPRISE v2.0 - Admin Blog Status Toggle with RBAC & Audit Trail

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import dbConnect from '@/lib/db';
import Blog from '@/models/Blog';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { checkPermission } from '@/lib/permissions';
import { rateLimitAdmin } from '@/lib/rateLimit';
import { z } from 'zod';

const MAX_TIME_MS = 5000;

// ═══════════════════════════════════════════════════════════════
// 🔒 ZOD SCHEMAS
// ═══════════════════════════════════════════════════════════════

const ObjectIdSchema = z.string().regex(/^[a-fA-F0-9]{24}$/, 'Invalid ID format');
const StatusSchema = z.object({
  status: z.enum(['draft', 'published', 'scheduled'])
});

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0] || req.socket.remoteAddress || '0.0.0.0';

  if (req.method !== 'PATCH') {
    res.setHeader('Allow', ['PATCH']);
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  // Validate ID
  const { id } = req.query;
  const idResult = ObjectIdSchema.safeParse(id);
  if (!idResult.success) {
    return res.status(400).json({ success: false, message: 'Invalid blog ID format' });
  }

  const blogId = idResult.data;

  try {
    await dbConnect();

    // 1. Rate Limiting
    const rl = await rateLimitAdmin(req);
    if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

    // 2. Authentication & Authorization
    const session = await getServerSession(req, res, authOptions);
    if (!session?.user) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const admin: any = await User.findById(session.user.id).select('role permissions').lean();
    if (!['admin', 'superadmin', 'editor'].includes(admin?.role?.toLowerCase())) {
      return res.status(403).json({ success: false, message: 'Admin access required' });
    }

    // 3. Permission Check
    if (!checkPermission(admin, 'blog_edit')) {
      return res.status(403).json({ success: false, message: 'Permission denied' });
    }

    // 4. Validate Body
    const parsed = StatusSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({ success: false, message: 'Invalid status provided' });
    }

    const { status } = parsed.data;

    // 5. Fetch Blog
    const blog: any = await Blog.findById(blogId).maxTimeMS(MAX_TIME_MS);
    if (!blog) {
      return res.status(404).json({ success: false, message: 'Blog not found' });
    }

    if (blog.isDeleted) {
      return res.status(400).json({ success: false, message: 'Cannot update status of a deleted blog' });
    }

    const oldStatus = blog.status;

    // 6. Update Status
    blog.status = status;
    blog.lastEditedBy = admin._id;
    blog.lastEditedAt = new Date();

    if (status === 'published' && oldStatus !== 'published') {
      blog.publishedAt = new Date();
    }

    await blog.save();

    // 7. Audit Log
    SecurityEvent.create({
      eventType: 'admin_blog_status_changed',
      userId: admin._id,
      severity: 'medium',
      ipAddress: ip,
      metadata: { 
        blogId, 
        oldStatus, 
        newStatus: status 
      }
    }).catch(console.error);

    const statusMessages: Record<string, string> = {
      published: 'Blog published successfully',
      draft: 'Blog moved to draft',
      scheduled: 'Blog scheduled successfully',
    };

    return res.status(200).json({
      success: true,
      message: statusMessages[status],
      blog: {
        _id: blog._id,
        status: blog.status,
        publishedAt: blog.publishedAt
      },
    });

  } catch (error: any) {
    console.error('Blog Status Update Error:', error);
    return res.status(500).json({ success: false, message: 'Internal Server Error' });
  }
}

// pages/api/admin/blogs/index.ts
// 🔒 ENTERPRISE v2.0 - Admin Blog Management (List & Create) with RBAC & Zod

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Blog from '@/models/Blog';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import { uploadBuffer } from '@/lib/cloudinary';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { checkPermission } from '@/lib/permissions';
import { rateLimitAdmin } from '@/lib/rateLimit';
import { z } from 'zod';
import { parseBlogImageDataUrl, sanitizeBlogHtml } from '@/lib/blogSecurity';

// Increase body parser limit for base64 images
export const config = {
  api: { bodyParser: { sizeLimit: '15mb' } },
};

const MAX_TIME_MS = 5000;

// ═══════════════════════════════════════════════════════════════
// 🔒 ZOD SCHEMAS
// ═══════════════════════════════════════════════════════════════

const QuerySchema = z.object({
  page: z.coerce.number().min(1).default(1),
  limit: z.coerce.number().min(1).max(100).default(10),
  status: z.enum(['published', 'draft', 'scheduled', 'all']).default('all'),
  category: z.string().optional(),
  search: z.string().max(100).optional(),
  deleted: z.enum(['true', 'false']).default('false'),
  sortBy: z.enum(['createdAt', 'publishedAt', 'views', 'title']).default('createdAt'),
  sortOrder: z.enum(['asc', 'desc']).default('desc'),
  featured: z.enum(['true', 'false']).optional(),
});

const CreateBlogSchema = z.object({
  title: z.string().trim().min(5).max(200),
  excerpt: z.string().trim().min(10).max(500),
  content: z.string().trim().min(50),
  category: z.string(),
  authorName: z.string().optional(), // Will default to admin's name
  imageBase64: z.string().optional(),
  image: z.object({ url: z.string(), public_id: z.string() }).optional(),
  tags: z.array(z.string()).default([]),
  status: z.enum(['draft', 'published', 'scheduled']).default('draft'),
  featured: z.boolean().default(false),
  metaTitle: z.string().max(70).optional(),
  metaDescription: z.string().max(160).optional(),
  scheduledFor: z.string().datetime().optional().nullable(),
  enableTOC: z.boolean().default(true),
  allowComments: z.boolean().default(true),
}).refine(data => data.imageBase64 || data.image, {
  message: 'Image is required (either base64 or URL)',
  path: ['image'],
});

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPERS
// ═══════════════════════════════════════════════════════════════

function escapeRegex(text: string) {
  return text.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&');
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0] || req.socket.remoteAddress || '0.0.0.0';

  try {
    await dbConnect();

    // 1. Rate Limiting
    const rl = await rateLimitAdmin(req);
    if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

    // 2. Authentication & Authorization
    const session = await getServerSession(req, res, authOptions);
    if (!session?.user) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const admin: any = await User.findById(session.user.id).select('role name image permissions').lean();
    if (!['admin', 'superadmin', 'editor'].includes(admin?.role?.toLowerCase())) {
      return res.status(403).json({ success: false, message: 'Admin access required' });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ GET: FETCH ALL BLOGS (Admin View)
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'GET') {
      if (!checkPermission(admin, 'blog_view_list')) {
        return res.status(403).json({ success: false, message: 'Permission denied' });
      }

      const parsed = QuerySchema.safeParse(req.query);
      if (!parsed.success) return res.status(400).json({ success: false, error: parsed.error.format() });

      const { page, limit, status, category, search, deleted, sortBy, sortOrder, featured } = parsed.data;
      const skip = (page - 1) * limit;

      const query: any = {};

      if (deleted === 'true') query.isDeleted = true;
      else query.isDeleted = { $ne: true };

      if (status !== 'all') query.status = status;
      if (category && category !== 'all') query.category = category;
      if (featured === 'true') query.featured = true;

      if (search) {
        const safeSearch = escapeRegex(search);
        query.$or = [
          { title: { $regex: safeSearch, $options: 'i' } },
          { excerpt: { $regex: safeSearch, $options: 'i' } },
        ];
      }

      const sortOptions: any = { [sortBy]: sortOrder === 'asc' ? 1 : -1 };

      const [blogs, total] = await Promise.all([
        Blog.find(query)
          .sort(sortOptions)
          .skip(skip)
          .limit(limit)
          .select('-content -tableOfContents') // Exclude heavy fields
          .lean()
          .maxTimeMS(MAX_TIME_MS),
        Blog.countDocuments(query).maxTimeMS(MAX_TIME_MS),
      ]);

      let counts = null;
      if (page === 1) {
        const [allCount, publishedCount, draftCount, scheduledCount, trashCount] = await Promise.all([
          Blog.countDocuments({ isDeleted: { $ne: true } }),
          Blog.countDocuments({ isDeleted: { $ne: true }, status: 'published' }),
          Blog.countDocuments({ isDeleted: { $ne: true }, status: 'draft' }),
          Blog.countDocuments({ isDeleted: { $ne: true }, status: 'scheduled' }),
          Blog.countDocuments({ isDeleted: true }),
        ]);
        counts = { all: allCount, published: publishedCount, draft: draftCount, scheduled: scheduledCount, trash: trashCount };
      }

      return res.status(200).json({
        success: true,
        blogs,
        pagination: { page, limit, total, totalPages: Math.ceil(total / limit) },
        counts,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ POST: CREATE BLOG
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'POST') {
      if (!checkPermission(admin, 'blog_create')) {
        return res.status(403).json({ success: false, message: 'Permission denied' });
      }

      const parsed = CreateBlogSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ success: false, error: parsed.error.format() });

      const data = parsed.data;
      let finalImage = data.image;

      // Handle base64 cover image through the centralized validated upload path.
      if (data.imageBase64 && !data.image?.url) {
        const parsedImage = parseBlogImageDataUrl(data.imageBase64);
        if (!parsedImage) {
          return res.status(400).json({ success: false, message: 'Invalid blog cover image' });
        }
        const uploadResult = await uploadBuffer(
          parsedImage.buffer,
          parsedImage.filename,
          'blog',
          'image',
          { tags: ['blog-cover'] },
        );
        if (!uploadResult.success || !uploadResult.secureUrl || !uploadResult.publicId) {
          return res.status(500).json({ success: false, message: 'Image upload failed' });
        }
        finalImage = { url: uploadResult.secureUrl, public_id: uploadResult.publicId };
      }

      const { imageBase64: _imageBase64, ...safeData } = data;
      const blog = await Blog.create({
        ...safeData,
        content: sanitizeBlogHtml(data.content),
        image: finalImage,
        authorId: admin._id,
        authorName: data.authorName || admin.name,
        authorAvatar: admin.image,
        source: 'manual',
      });

      SecurityEvent.create({
        eventType: 'admin_blog_created',
        userId: admin._id,
        severity: 'info',
        ipAddress: ip,
        metadata: { blogId: blog._id, title: blog.title }
      }).catch(console.error);

      return res.status(201).json({ success: true, message: 'Blog created successfully', blog });
    }

    return res.status(405).json({ success: false, message: 'Method not allowed' });

  } catch (error: any) {
    console.error('Admin Blog API Error:', error);
    return res.status(500).json({ success: false, message: 'Internal Server Error' });
  }
}

// pages/api/admin/campaign-templates/[id].ts
// 🔒 ENTERPRISE CAMPAIGN TEMPLATE SINGLE API — HIGHRISE.PK
// Security Level: MAXIMUM | Admin Only | Get, Update, Delete
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   GET    → Fetch single template WITH full content
//            (list endpoint excludes content for performance)
//            Also increments usageCount when fetched for apply
//   PUT    → Update template (name, description, category,
//            subject, previewText, content, tags)
//   DELETE → Soft delete template (isDeleted = true)
//
// SECURITY:
//   ✅ requireAdmin() auth guard
//   ✅ rateLimitAdmin() rate limiting
//   ✅ MongoDB ObjectId validation
//   ✅ Input validation + sanitization
//   ✅ HTML content sanitization (DOMPurify)
//   ✅ Content size limit (500KB)
//   ✅ Category whitelist
//   ✅ isSystem guard (cannot delete/edit system templates)
//   ✅ logSecurityEvent audit logging
//   ✅ Security headers + request ID
//   ✅ Generic error messages
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose                                  from 'mongoose';
import DOMPurify                                 from 'isomorphic-dompurify';
import dbConnect                                 from '@/lib/db';
import CampaignTemplate                          from '@/models/CampaignTemplate';
import type { TemplateCategory }                 from '@/models/CampaignTemplate';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ═══════════════════════════════════════════════════════════════
// 🔐 CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_CONTENT_SIZE_BYTES = 500_000;
const MAX_NAME_LENGTH        = 100;
const MAX_DESCRIPTION_LENGTH = 300;
const MAX_SUBJECT_LENGTH     = 200;
const MAX_PREVIEW_LENGTH     = 300;
const MAX_TAG_LENGTH         = 50;
const MAX_TAGS_COUNT         = 10;

const ALLOWED_CATEGORIES: TemplateCategory[] = [
  'welcome',
  'newsletter',
  'property_alert',
  'market_insights',
  'promotion',
  'announcement',
  'custom',
];

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  const cfIp = req.headers['cf-connecting-ip'];
  if (typeof cfIp === 'string') return cfIp.trim();
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('X-XSS-Protection',       '1; mode=block');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
}

function sanitizeText(text: unknown, maxLength: number): string {
  if (!text || typeof text !== 'string') return '';
  return text.replace(/<[^>]*>/g, '').trim().slice(0, maxLength);
}

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function isValidObjectId(id: string): boolean {
  return mongoose.Types.ObjectId.isValid(id) && id.length === 24;
}

function sanitizeHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      'a', 'b', 'br', 'div', 'em', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'hr', 'i', 'img', 'li', 'ol', 'p', 'span', 'strong', 'table',
      'tbody', 'td', 'th', 'thead', 'tr', 'ul', 'blockquote', 'code',
      'pre', 'small', 'sub', 'sup', 'u',
    ],
    ALLOWED_ATTR: [
      'href', 'target', 'rel', 'src', 'alt', 'width', 'height',
      'style', 'class', 'id', 'colspan', 'rowspan', 'align', 'valign',
      'bgcolor', 'border', 'cellpadding', 'cellspacing', 'title',
    ],
    ALLOW_DATA_ATTR: false,
    FORBID_TAGS:     ['script', 'iframe', 'object', 'embed', 'form', 'input'],
    FORBID_ATTR:     ['onerror', 'onload', 'onclick', 'onmouseover', 'onfocus'],
  });
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ─────────────────────────────────────────────
  // STEP 1: Method guard
  // ─────────────────────────────────────────────
  if (!['GET', 'PUT', 'DELETE'].includes(req.method || '')) {
    res.setHeader('Allow', ['GET', 'PUT', 'DELETE']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 2: Rate limit
  // ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: {
        action:   'campaign_template_single_rate_limited',
        endpoint: '/api/admin/campaign-templates/[id]',
        method:   req.method,
      },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 3: Admin auth
  // ─────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  // ─────────────────────────────────────────────
  // STEP 4: Validate ID param
  // ─────────────────────────────────────────────
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    res.status(400).json({
      success: false,
      message: 'Template ID is required',
      requestId,
    });
    return;
  }

  if (!isValidObjectId(id)) {
    await logSecurityEvent({
      type:     'suspicious_activity',
      severity: 'medium',
      userId:   auth.id,
      email:    auth.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        action:      'invalid_template_id',
        attemptedId: id.slice(0, 50),
        method:      req.method,
      },
    });
    res.status(400).json({
      success: false,
      message: 'Invalid template ID',
      requestId,
    });
    return;
  }

  await dbConnect();

  // ═══════════════════════════════════════════════════════════
  // GET → Fetch single template with full content
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'GET') {
    try {
      // Check if this is an "apply" fetch (increments usageCount)
      // vs a plain "view" fetch
      const { apply } = req.query;
      const isApply   = apply === 'true';

      const template = await CampaignTemplate.findOne({
        _id:       id,
        isDeleted: false,
      })
        .select('-__v')
        .populate('createdBy', 'name email')
        .lean() as any;

      if (!template) {
        res.status(404).json({
          success: false,
          message: 'Template not found',
          requestId,
        });
        return;
      }

      // ── Increment usageCount if applying ─────────────────
      if (isApply) {
        await CampaignTemplate.updateOne(
          { _id: id },
          {
            $inc: { usageCount: 1 },
            $set: { lastUsedAt: new Date() },
          }
        );

        await logSecurityEvent({
          type:     'admin_action',
          severity: 'low',
          userId:   auth.id,
          email:    auth.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            action:       'campaign_template_applied',
            templateId:   id,
            templateName: template.name,
          },
        });
      }

      res.status(200).json({
        success:  true,
        template,
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error ? error.message : 'Unknown error';

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:     'campaign_template_fetch_failed',
          templateId: id,
          error:      errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to fetch template',
        requestId,
      });
      return;
    }
  }

  // ═══════════════════════════════════════════════════════════
  // PUT → Update template
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'PUT') {
    try {
      // ── Find template ─────────────────────────────────────
      const template = await CampaignTemplate.findOne({
        _id:       id,
        isDeleted: false,
      });

      if (!template) {
        res.status(404).json({
          success: false,
          message: 'Template not found',
          requestId,
        });
        return;
      }

      // ── Guard: cannot edit system templates ───────────────
      if (template.isSystem) {
        await logSecurityEvent({
          type:     'suspicious_activity',
          severity: 'medium',
          userId:   auth.id,
          email:    auth.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            action:     'system_template_edit_blocked',
            templateId: id,
          },
        });
        res.status(403).json({
          success: false,
          message: 'System templates cannot be edited',
          requestId,
        });
        return;
      }

      const {
        name,
        description,
        category,
        subject,
        previewText,
        content,
        tags,
      } = req.body || {};

      // ── Validate + sanitize fields ────────────────────────
      const updates: Record<string, unknown> = {};

      // Name
      if (name !== undefined) {
        const cleanName = sanitizeText(name, MAX_NAME_LENGTH);
        if (!cleanName || cleanName.length < 3) {
          res.status(400).json({
            success: false,
            message: 'Template name must be at least 3 characters',
            requestId,
          });
          return;
        }

        // Duplicate name check (exclude self)
        const duplicate = await CampaignTemplate.findOne({
          _id:       { $ne: id },
          name:      { $regex: `^${escapeRegex(cleanName)}$`, $options: 'i' },
          isDeleted: false,
        });

        if (duplicate) {
          res.status(409).json({
            success: false,
            message: `A template named "${cleanName}" already exists`,
            requestId,
          });
          return;
        }

        updates.name = cleanName;
      }

      // Description
      if (description !== undefined) {
        const cleanDesc = sanitizeText(description, MAX_DESCRIPTION_LENGTH);
        if (!cleanDesc) {
          res.status(400).json({
            success: false,
            message: 'Description cannot be empty',
            requestId,
          });
          return;
        }
        updates.description = cleanDesc;
      }

      // Category
      if (category !== undefined) {
        const categoryStr = String(category).trim();
        if (!ALLOWED_CATEGORIES.includes(categoryStr as TemplateCategory)) {
          res.status(400).json({
            success: false,
            message: `Invalid category. Allowed: ${ALLOWED_CATEGORIES.join(', ')}`,
            requestId,
          });
          return;
        }
        updates.category = categoryStr;
      }

      // Subject
      if (subject !== undefined) {
        updates.subject = sanitizeText(subject, MAX_SUBJECT_LENGTH);
      }

      // Preview text
      if (previewText !== undefined) {
        updates.previewText = sanitizeText(previewText, MAX_PREVIEW_LENGTH);
      }

      // Content
      if (content !== undefined) {
        if (typeof content !== 'string' || !content.trim()) {
          res.status(400).json({
            success: false,
            message: 'Content cannot be empty',
            requestId,
          });
          return;
        }

        const contentSizeBytes = Buffer.byteLength(content, 'utf8');
        if (contentSizeBytes > MAX_CONTENT_SIZE_BYTES) {
          res.status(400).json({
            success: false,
            message: `Content too large. Maximum is 500KB.`,
            requestId,
          });
          return;
        }

        const cleanContent = sanitizeHtml(content);
        if (!cleanContent.trim()) {
          res.status(400).json({
            success: false,
            message: 'Content is empty after sanitization',
            requestId,
          });
          return;
        }
        updates.content = cleanContent;
      }

      // Tags
      if (tags !== undefined) {
        if (Array.isArray(tags)) {
          updates.tags = tags
            .filter((t: unknown): t is string => typeof t === 'string')
            .map((t) => sanitizeText(t, MAX_TAG_LENGTH))
            .filter((t) => t.length > 0)
            .slice(0, MAX_TAGS_COUNT);
        }
      }

      // ── Nothing to update ─────────────────────────────────
      if (Object.keys(updates).length === 0) {
        res.status(400).json({
          success: false,
          message: 'No valid fields to update',
          requestId,
        });
        return;
      }

      // ── Apply updates ─────────────────────────────────────
      Object.assign(template, updates);
      await template.save();

      // ── Audit log ─────────────────────────────────────────
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:       'campaign_template_updated',
          templateId:   id,
          templateName: template.name,
          updatedFields: Object.keys(updates),
        },
      });

      res.status(200).json({
        success:  true,
        message:  'Template updated successfully',
        template: {
          _id:         template._id,
          name:        template.name,
          description: template.description,
          category:    template.category,
          subject:     template.subject,
          previewText: template.previewText,
          tags:        template.tags,
          usageCount:  template.usageCount,
          updatedAt:   template.updatedAt,
        },
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error ? error.message : 'Unknown error';

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:     'campaign_template_update_failed',
          templateId: id,
          error:      errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to update template',
        requestId,
      });
      return;
    }
  }

  // ═══════════════════════════════════════════════════════════
  // DELETE → Soft delete template
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'DELETE') {
    try {
      const template = await CampaignTemplate.findOne({
        _id:       id,
        isDeleted: false,
      }).lean() as any;

      if (!template) {
        res.status(404).json({
          success: false,
          message: 'Template not found',
          requestId,
        });
        return;
      }

      // ── Guard: cannot delete system templates ─────────────
      if (template.isSystem) {
        await logSecurityEvent({
          type:     'suspicious_activity',
          severity: 'medium',
          userId:   auth.id,
          email:    auth.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            action:     'system_template_delete_blocked',
            templateId: id,
          },
        });
        res.status(403).json({
          success: false,
          message: 'System templates cannot be deleted',
          requestId,
        });
        return;
      }

      // ── Soft delete ───────────────────────────────────────
      await CampaignTemplate.updateOne(
        { _id: id },
        {
          $set: {
            isDeleted: true,
            deletedAt: new Date(),
          },
        }
      );

      // ── Audit log (severity: high — data deletion) ────────
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:       'campaign_template_deleted',
          templateId:   id,
          templateName: template.name,
          category:     template.category,
          usageCount:   template.usageCount,
        },
      });

      res.status(200).json({
        success: true,
        message: 'Template deleted successfully',
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error ? error.message : 'Unknown error';

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:     'campaign_template_delete_failed',
          templateId: id,
          error:      errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to delete template',
        requestId,
      });
      return;
    }
  }
}

// pages/api/admin/campaign-templates/index.ts
// 🔒 ENTERPRISE CAMPAIGN TEMPLATES API — HIGHRISE.PK
// Security Level: MAXIMUM | Admin Only | List & Create
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   GET  → List all templates (with search, category filter,
//           sort by usage/date, pagination)
//   POST → Create new template from campaign content
//
// SECURITY:
//   ✅ requireAdmin() auth guard
//   ✅ rateLimitAdmin() rate limiting
//   ✅ Input validation + sanitization
//   ✅ HTML content size limit (500KB)
//   ✅ DOMPurify sanitization on content
//   ✅ Category whitelist
//   ✅ Tag limits (max 10, max 50 chars each)
//   ✅ logSecurityEvent audit logging
//   ✅ Security headers + request ID
//   ✅ Generic error messages
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import DOMPurify                                 from 'isomorphic-dompurify';
import dbConnect                                 from '@/lib/db';
import CampaignTemplate                          from '@/models/CampaignTemplate';
import type { TemplateCategory }                 from '@/models/CampaignTemplate';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ═══════════════════════════════════════════════════════════════
// 🔐 CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_CONTENT_SIZE_BYTES = 500_000;   // 500 KB
const MAX_NAME_LENGTH        = 100;
const MAX_DESCRIPTION_LENGTH = 300;
const MAX_SUBJECT_LENGTH     = 200;
const MAX_PREVIEW_LENGTH     = 300;
const MAX_TAG_LENGTH         = 50;
const MAX_TAGS_COUNT         = 10;
const MAX_SEARCH_LENGTH      = 100;
const DEFAULT_PAGE_LIMIT     = 20;
const MAX_PAGE_LIMIT         = 100;

const ALLOWED_CATEGORIES: TemplateCategory[] = [
  'welcome',
  'newsletter',
  'property_alert',
  'market_insights',
  'promotion',
  'announcement',
  'custom',
];

const ALLOWED_SORT_OPTIONS = [
  'newest',
  'oldest',
  'most_used',
  'name_asc',
] as const;

type SortOption = typeof ALLOWED_SORT_OPTIONS[number];

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  const cfIp = req.headers['cf-connecting-ip'];
  if (typeof cfIp === 'string') return cfIp.trim();
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('X-XSS-Protection',       '1; mode=block');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
}

function sanitizeText(text: unknown, maxLength: number): string {
  if (!text || typeof text !== 'string') return '';
  return text.replace(/<[^>]*>/g, '').trim().slice(0, maxLength);
}

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function sanitizeHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      'a', 'b', 'br', 'div', 'em', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'hr', 'i', 'img', 'li', 'ol', 'p', 'span', 'strong', 'table',
      'tbody', 'td', 'th', 'thead', 'tr', 'ul', 'blockquote', 'code',
      'pre', 'small', 'sub', 'sup', 'u',
    ],
    ALLOWED_ATTR: [
      'href', 'target', 'rel', 'src', 'alt', 'width', 'height',
      'style', 'class', 'id', 'colspan', 'rowspan', 'align', 'valign',
      'bgcolor', 'border', 'cellpadding', 'cellspacing', 'title',
    ],
    ALLOW_DATA_ATTR: false,
    FORBID_TAGS:     ['script', 'iframe', 'object', 'embed', 'form', 'input'],
    FORBID_ATTR:     ['onerror', 'onload', 'onclick', 'onmouseover', 'onfocus'],
  });
}

function buildSortQuery(sort: SortOption): Record<string, 1 | -1> {
  switch (sort) {
    case 'oldest':    return { createdAt: 1 };
    case 'most_used': return { usageCount: -1, createdAt: -1 };
    case 'name_asc':  return { name: 1 };
    case 'newest':
    default:          return { createdAt: -1 };
  }
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ─────────────────────────────────────────────
  // STEP 1: Method guard
  // ─────────────────────────────────────────────
  if (req.method !== 'GET' && req.method !== 'POST') {
    res.setHeader('Allow', ['GET', 'POST']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 2: Rate limit
  // ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: {
        action:   'campaign_templates_rate_limited',
        endpoint: '/api/admin/campaign-templates',
        method:   req.method,
      },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 3: Admin auth
  // ─────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  await dbConnect();

  // ═══════════════════════════════════════════════════════════
  // GET → List templates
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'GET') {
    try {
      const {
        search   = '',
        category = 'all',
        sort     = 'newest',
        page     = '1',
        limit    = String(DEFAULT_PAGE_LIMIT),
      } = req.query;

      // ── Validate + sanitize params ──────────────────────
      const searchStr   = sanitizeText(String(search), MAX_SEARCH_LENGTH);
      const categoryStr = String(category).trim();
      const sortStr     = String(sort).trim() as SortOption;
      const pageNum     = Math.max(1, parseInt(String(page), 10)  || 1);
      const limitNum    = Math.min(
        MAX_PAGE_LIMIT,
        Math.max(1, parseInt(String(limit), 10) || DEFAULT_PAGE_LIMIT)
      );
      const skip = (pageNum - 1) * limitNum;

      // Validate category
      if (categoryStr !== 'all' && !ALLOWED_CATEGORIES.includes(categoryStr as TemplateCategory)) {
        res.status(400).json({
          success: false,
          message: `Invalid category. Allowed: all, ${ALLOWED_CATEGORIES.join(', ')}`,
          requestId,
        });
        return;
      }

      // Validate sort
      if (!ALLOWED_SORT_OPTIONS.includes(sortStr)) {
        res.status(400).json({
          success: false,
          message: `Invalid sort. Allowed: ${ALLOWED_SORT_OPTIONS.join(', ')}`,
          requestId,
        });
        return;
      }

      // ── Build query ──────────────────────────────────────
      const query: Record<string, unknown> = {
        isDeleted: false,
      };

      if (categoryStr !== 'all') {
        query.category = categoryStr;
      }

      if (searchStr) {
        const escaped = escapeRegex(searchStr);
        query.$or = [
          { name:        { $regex: escaped, $options: 'i' } },
          { description: { $regex: escaped, $options: 'i' } },
          { tags:        { $regex: escaped, $options: 'i' } },
        ];
      }

      const sortQuery = buildSortQuery(sortStr);

      // ── Fetch ────────────────────────────────────────────
      const [templates, total] = await Promise.all([
        CampaignTemplate.find(query)
          .select('-content -__v') // Exclude heavy content from list
          .sort(sortQuery)
          .skip(skip)
          .limit(limitNum)
          .populate('createdBy', 'name email')
          .lean(),
        CampaignTemplate.countDocuments(query),
      ]);

      // ── Category counts (for filter tabs) ────────────────
      const categoryCounts = await CampaignTemplate.aggregate([
        { $match: { isDeleted: false } },
        { $group: { _id: '$category', count: { $sum: 1 } } },
      ]);

      const categoryCountMap: Record<string, number> = { all: total };
      categoryCounts.forEach((c: any) => {
        categoryCountMap[c._id] = c.count;
      });

      res.status(200).json({
        success:   true,
        templates,
        categoryCounts: categoryCountMap,
        pagination: {
          page:       pageNum,
          limit:      limitNum,
          total,
          totalPages: Math.ceil(total / limitNum),
        },
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error ? error.message : 'Unknown error';

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:  'campaign_templates_list_failed',
          error:   errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to fetch templates',
        requestId,
      });
      return;
    }
  }

  // ═══════════════════════════════════════════════════════════
  // POST → Create new template
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'POST') {
    try {
      const {
        name,
        description,
        category = 'custom',
        subject     = '',
        previewText = '',
        content,
        tags        = [],
      } = req.body || {};

      // ── Validate required fields ─────────────────────────

      // Name
      if (!name || typeof name !== 'string' || !name.trim()) {
        res.status(400).json({
          success: false,
          message: 'Template name is required',
          requestId,
        });
        return;
      }

      // Description
      if (!description || typeof description !== 'string' || !description.trim()) {
        res.status(400).json({
          success: false,
          message: 'Template description is required',
          requestId,
        });
        return;
      }

      // Content
      if (!content || typeof content !== 'string' || !content.trim()) {
        res.status(400).json({
          success: false,
          message: 'Template content is required',
          requestId,
        });
        return;
      }

      // ── Content size check ───────────────────────────────
      const contentSizeBytes = Buffer.byteLength(content, 'utf8');
      if (contentSizeBytes > MAX_CONTENT_SIZE_BYTES) {
        res.status(400).json({
          success: false,
          message: `Content too large. Maximum is 500KB. Your content is ${(contentSizeBytes / 1024).toFixed(0)}KB.`,
          requestId,
        });
        return;
      }

      // ── Validate category ────────────────────────────────
      const categoryStr = String(category).trim();
      if (!ALLOWED_CATEGORIES.includes(categoryStr as TemplateCategory)) {
        res.status(400).json({
          success: false,
          message: `Invalid category. Allowed: ${ALLOWED_CATEGORIES.join(', ')}`,
          requestId,
        });
        return;
      }

      // ── Sanitize text fields ─────────────────────────────
      const cleanName        = sanitizeText(name,        MAX_NAME_LENGTH);
      const cleanDescription = sanitizeText(description, MAX_DESCRIPTION_LENGTH);
      const cleanSubject     = sanitizeText(subject,     MAX_SUBJECT_LENGTH);
      const cleanPreviewText = sanitizeText(previewText, MAX_PREVIEW_LENGTH);

      if (cleanName.length < 3) {
        res.status(400).json({
          success: false,
          message: 'Template name must be at least 3 characters',
          requestId,
        });
        return;
      }

      // ── Sanitize HTML content ────────────────────────────
      const cleanContent = sanitizeHtml(content);

      if (!cleanContent.trim()) {
        res.status(400).json({
          success: false,
          message: 'Template content is empty after sanitization',
          requestId,
        });
        return;
      }

      // ── Sanitize tags ────────────────────────────────────
      let cleanTags: string[] = [];
      if (Array.isArray(tags)) {
        cleanTags = tags
          .filter((t: unknown): t is string => typeof t === 'string')
          .map((t) => sanitizeText(t, MAX_TAG_LENGTH))
          .filter((t) => t.length > 0)
          .slice(0, MAX_TAGS_COUNT);
      }

      // ── Duplicate name check ─────────────────────────────
      const existingTemplate = await CampaignTemplate.findOne({
        name:      { $regex: `^${escapeRegex(cleanName)}$`, $options: 'i' },
        isDeleted: false,
      });

      if (existingTemplate) {
        res.status(409).json({
          success: false,
          message: `A template named "${cleanName}" already exists. Please choose a different name.`,
          requestId,
        });
        return;
      }

      // ── Create template ──────────────────────────────────
      const template = await CampaignTemplate.create({
        name:        cleanName,
        description: cleanDescription,
        category:    categoryStr as TemplateCategory,
        subject:     cleanSubject,
        previewText: cleanPreviewText,
        content:     cleanContent,
        tags:        cleanTags,
        createdBy:   auth.id,
        usageCount:  0,
        isSystem:    false,
        isDeleted:   false,
      });

      // ── Audit log ────────────────────────────────────────
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:      'campaign_template_created',
          templateId:  String(template._id),
          name:        cleanName,
          category:    categoryStr,
          contentSize: contentSizeBytes,
        },
      });

      res.status(201).json({
        success:  true,
        message:  'Template saved successfully',
        template: {
          _id:         template._id,
          name:        template.name,
          description: template.description,
          category:    template.category,
          subject:     template.subject,
          previewText: template.previewText,
          tags:        template.tags,
          usageCount:  template.usageCount,
          createdAt:   template.createdAt,
        },
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error ? error.message : 'Unknown error';

      // Handle MongoDB duplicate key
      if (
        typeof error === 'object' &&
        error !== null &&
        'code' in error &&
        (error as any).code === 11000
      ) {
        res.status(409).json({
          success: false,
          message: 'A template with this name already exists',
          requestId,
        });
        return;
      }

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action: 'campaign_template_create_failed',
          error:  errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to save template',
        requestId,
      });
      return;
    }
  }
}

import type { NextApiRequest, NextApiResponse } from "next";
import { z } from "zod";
import dbConnect from "@/lib/dbConnect";
import SecurityEvent from "@/models/SecurityEvent";
import User from "@/models/User";
import City from "@/models/City";
import { requireAuth } from "@/lib/requireAuth";
import { checkPermission } from "@/lib/permissions";
import { rateLimitAdmin } from "@/lib/rateLimit";
import { deleteFile, isHighrisePublicId } from "@/lib/cloudinary";

const MAX_TIME_MS = 5000;
const DEFAULT_LIMIT = 30;
const MAX_LIMIT = 200;

const CityNameSchema = z
  .string()
  .trim()
  .min(2)
  .max(60)
  // letters, spaces, dots, hyphens (e.g. "Dera Ghazi Khan", "Gujrat", "F.B Area")
  .regex(/^[a-zA-Z][a-zA-Z\s.\-()]*$/, "Invalid city name");

const QuerySchema = z.object({
  page: z.coerce.number().int().min(1).max(10000).optional().default(1),
  limit: z.coerce.number().int().min(1).max(MAX_LIMIT).optional().default(DEFAULT_LIMIT),
  search: z.string().trim().max(80).optional().default(""),
  active: z.enum(["all", "true", "false"]).optional().default("all"),
  featured: z.enum(["all", "true", "false"]).optional().default("all"),
});

const CreateSchema = z.object({
  name: CityNameSchema,
  // image is optional; admin can add city first, upload later
  imageUrl: z.string().trim().url().optional().or(z.literal("")).default(""),
  publicId: z.string().trim().max(200).optional().default(""),
  displayOrder: z.coerce.number().int().min(0).max(9999).optional().default(0),
  isActive: z.boolean().optional().default(true),
  isFeaturedOnHomepage: z.boolean().optional().default(false),
});

const UpdateSchema = z.object({
  id: z.string().trim().optional().or(z.literal("")).default(""),
  name: CityNameSchema.optional(),
  imageUrl: z.string().trim().url().optional().or(z.literal("")).default(""),
  publicId: z.string().trim().max(200).optional().default(""),
  clearImage: z.boolean().optional().default(false),
  displayOrder: z.coerce.number().int().min(0).max(9999).optional(),
  isActive: z.boolean().optional(),
  isFeaturedOnHomepage: z.boolean().optional(),
});

const DeleteSchema = z.object({
  id: z.string().trim().optional().or(z.literal("")).default(""),
  name: CityNameSchema.optional(),
  deleteImageOnly: z.boolean().optional().default(false),
});


function isManagedCityImage(imageUrl: string, publicId: string): boolean {
  return (
    imageUrl.startsWith("https://res.cloudinary.com/") &&
    isHighrisePublicId(publicId) &&
    publicId.startsWith("highrise-pk/admin/cities/")
  );
}

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function setSecurityHeaders(res: NextApiResponse, requestId: string) {
  res.setHeader("X-Request-Id", requestId);
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "DENY");
  res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, private");
  res.setHeader("Pragma", "no-cache");
  res.setHeader("Expires", "0");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  res.setHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains; preload");
}

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers["x-forwarded-for"];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || "").split(",")[0]?.trim() || req.socket?.remoteAddress || "0.0.0.0";
}

function getUserAgent(req: NextApiRequest): string {
  return String(req.headers["user-agent"] || "").slice(0, 200);
}

function escapeRegex(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").trim().slice(0, 80);
}

function requireActiveAdminOrThrow(user: any) {
  if (!user) {
    const err: any = new Error("User not found");
    err.statusCode = 401;
    err.code = "USER_NOT_FOUND";
    throw err;
  }

  const role = String(user.role || "user").toLowerCase();
  if (!["admin", "superadmin", "moderator"].includes(role)) {
    const err: any = new Error("Admin access required");
    err.statusCode = 403;
    err.code = "ADMIN_REQUIRED";
    throw err;
  }
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  if (!["GET", "POST", "PATCH", "DELETE"].includes(String(req.method))) {
    res.setHeader("Allow", ["GET", "POST", "PATCH", "DELETE"]);
    return res.status(405).json({ success: false, message: "Method not allowed", requestId });
  }

  const ip = getClientIp(req);
  const ua = getUserAgent(req);

  try {
    await dbConnect();

    const rl = await rateLimitAdmin(req);
    if (!rl.ok) {
      res.setHeader("Retry-After", String(rl.retryAfter || 60));
      return res.status(429).json({
        success: false,
        message: "Too many requests. Please slow down.",
        code: "RATE_LIMITED",
        requestId,
      });
    }

    const auth = await requireAuth(req, res);
    if (!auth) return;

    const admin: any = await User.findById(auth.id)
      .select("role permissions status isDeleted")
      .lean()
      .maxTimeMS(MAX_TIME_MS);

    requireActiveAdminOrThrow(admin);

    if (!checkPermission(admin, "system_manage_settings")) {
      SecurityEvent.create({
        eventType: "permission_denied",
        userId: auth.id,
        metadata: {
          endpoint: "/api/admin/cities",
          permission: "system_manage_settings",
          action: `cities_${String(req.method).toLowerCase()}`,
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "warning",
      }).catch(console.error);

      return res.status(403).json({
        success: false,
        message: "Permission denied",
        code: "PERMISSION_DENIED",
        requestId,
      });
    }

    // -------------------------
    // GET: List all cities (dynamic)
    // -------------------------
    if (req.method === "GET") {
      const parse = QuerySchema.safeParse(req.query);
      if (!parse.success) {
        return res.status(400).json({
          success: false,
          message: "Invalid query parameters",
          code: "VALIDATION_ERROR",
          errors: parse.error.flatten().fieldErrors,
          requestId,
        });
      }

      const { page, limit, search, active, featured } = parse.data;
      const skip = (page - 1) * limit;

      const query: any = {};

      // Backwards compatible: treat missing isActive as active
      if (active === "true") query.$or = [{ isActive: true }, { isActive: { $exists: false } }];
      if (active === "false") query.isActive = false;

      if (featured === "true") query.isFeaturedOnHomepage = true;
      if (featured === "false") query.$or = [{ isFeaturedOnHomepage: false }, { isFeaturedOnHomepage: { $exists: false } }];

      if (search && search.length >= 2) {
        const safe = escapeRegex(search);
        if (safe) query.name = { $regex: safe, $options: "i" };
      }

      const [items, total] = await Promise.all([
        City.find(query)
          .sort({ displayOrder: 1, updatedAt: -1 })
          .skip(skip)
          .limit(limit)
          .lean()
          .maxTimeMS(MAX_TIME_MS),
        City.countDocuments(query).maxTimeMS(MAX_TIME_MS),
      ]);

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: {
          action: "list_cities",
          resultCount: items.length,
          page,
          filters: { active, featured, hasSearch: Boolean(search) },
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "info",
      }).catch(console.error);

      const cities = (items as any[]).map((c) => ({
        _id: c._id,
        name: c.name,
        imageUrl: c?.image?.url || "",
        publicId: c?.image?.publicId || "",
        displayOrder: c?.displayOrder ?? 0,
        isActive: c?.isActive ?? true,
        isFeaturedOnHomepage: Boolean(c?.isFeaturedOnHomepage),
        createdAt: c?.createdAt || null,
        updatedAt: c?.updatedAt || null,
      }));

      return res.status(200).json({
        success: true,
        cities,
        pagination: { page, limit, total, pages: Math.ceil(total / limit) },
        requestId,
      });
    }

    // -------------------------
    // POST: Create city OR upsert by name (add new city)
    // -------------------------
    if (req.method === "POST") {
      const bodyParse = CreateSchema.safeParse(req.body);
      if (!bodyParse.success) {
        return res.status(400).json({
          success: false,
          message: "Invalid request body",
          code: "VALIDATION_ERROR",
          errors: bodyParse.error.flatten().fieldErrors,
          requestId,
        });
      }

      const payload = bodyParse.data;

      if (payload.imageUrl && !isManagedCityImage(payload.imageUrl, payload.publicId)) {
        return res.status(400).json({
          success: false,
          message: "City images must be uploaded through the protected Highrise upload service",
          code: "INVALID_IMAGE_REFERENCE",
          requestId,
        });
      }

      // Case-insensitive match to avoid duplicates like "lahore" vs "Lahore"
      const nameRegex = new RegExp(`^${escapeRegex(payload.name)}$`, "i");

      const update: any = {
        name: payload.name,
        displayOrder: payload.displayOrder,
        isActive: payload.isActive,
        isFeaturedOnHomepage: payload.isFeaturedOnHomepage,
      };

      if (payload.imageUrl) {
        update.image = { url: payload.imageUrl, publicId: payload.publicId || "" };
      }

      const city = await City.findOneAndUpdate(
        { name: nameRegex },
        { $set: update },
        { new: true, upsert: true, setDefaultsOnInsert: true }
      )
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: {
          action: "create_or_upsert_city",
          cityName: payload.name,
          hasImage: Boolean(payload.imageUrl),
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "info",
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: "City saved",
        city,
        requestId,
      });
    }

    // -------------------------
    // PATCH: Update fields (toggle active/featured/order, set/clear image)
    // -------------------------
    if (req.method === "PATCH") {
      const bodyParse = UpdateSchema.safeParse(req.body);
      if (!bodyParse.success) {
        return res.status(400).json({
          success: false,
          message: "Invalid request body",
          code: "VALIDATION_ERROR",
          errors: bodyParse.error.flatten().fieldErrors,
          requestId,
        });
      }

      const payload = bodyParse.data;

      const filter: any = {};
      if (payload.id) filter._id = payload.id;
      else if (payload.name) filter.name = new RegExp(`^${escapeRegex(payload.name)}$`, "i");
      else {
        return res.status(400).json({
          success: false,
          message: "Provide id or name to update",
          code: "MISSING_IDENTIFIER",
          requestId,
        });
      }

      if (payload.imageUrl && !isManagedCityImage(payload.imageUrl, payload.publicId)) {
        return res.status(400).json({
          success: false,
          message: "City images must be uploaded through the protected Highrise upload service",
          code: "INVALID_IMAGE_REFERENCE",
          requestId,
        });
      }

      const previousCity: any = await City.findOne(filter)
        .select("image")
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      const $set: any = {};
      if (payload.name) $set.name = payload.name;
      if (typeof payload.displayOrder === "number") $set.displayOrder = payload.displayOrder;
      if (typeof payload.isActive === "boolean") $set.isActive = payload.isActive;
      if (typeof payload.isFeaturedOnHomepage === "boolean") $set.isFeaturedOnHomepage = payload.isFeaturedOnHomepage;

      if (payload.clearImage) {
        $set.image = { url: "", publicId: "" };
      } else if (payload.imageUrl) {
        $set.image = { url: payload.imageUrl, publicId: payload.publicId || "" };
      }

      const city = await City.findOneAndUpdate(filter, { $set }, { new: true })
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      if (!city) {
        return res.status(404).json({
          success: false,
          message: "City not found",
          code: "NOT_FOUND",
          requestId,
        });
      }

      const previousPublicId = String(previousCity?.image?.publicId || "");
      const nextPublicId = String((city as any)?.image?.publicId || "");
      if (
        previousPublicId &&
        previousPublicId !== nextPublicId &&
        isHighrisePublicId(previousPublicId)
      ) {
        await deleteFile(previousPublicId).catch(() => undefined);
      }

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: {
          action: "update_city",
          cityId: (city as any)?._id?.toString(),
          cityName: (city as any)?.name,
          clearImage: payload.clearImage,
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "info",
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: "City updated",
        city,
        requestId,
      });
    }

    // -------------------------
    // DELETE: Delete city OR remove image only
    // -------------------------
    const bodyParse = DeleteSchema.safeParse(req.body);
    if (!bodyParse.success) {
      return res.status(400).json({
        success: false,
        message: "Invalid request body",
        code: "VALIDATION_ERROR",
        errors: bodyParse.error.flatten().fieldErrors,
        requestId,
      });
    }

    const payload = bodyParse.data;

    const filter: any = {};
    if (payload.id) filter._id = payload.id;
    else if (payload.name) filter.name = new RegExp(`^${escapeRegex(payload.name)}$`, "i");
    else {
      return res.status(400).json({
        success: false,
        message: "Provide id or name to delete",
        code: "MISSING_IDENTIFIER",
        requestId,
      });
    }

    if (payload.deleteImageOnly) {
      const previousCity: any = await City.findOne(filter)
        .select("image")
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      const city = await City.findOneAndUpdate(
        filter,
        { $set: { image: { url: "", publicId: "" } } },
        { new: true }
      )
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      if (!city) {
        return res.status(404).json({
          success: false,
          message: "City not found",
          code: "NOT_FOUND",
          requestId,
        });
      }

      const previousPublicId = String(previousCity?.image?.publicId || "");
      if (previousPublicId && isHighrisePublicId(previousPublicId)) {
        await deleteFile(previousPublicId).catch(() => undefined);
      }

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: { action: "delete_city_image_only", cityId: (city as any)?._id?.toString(), cityName: (city as any)?.name },
        ipAddress: ip,
        userAgent: ua,
        severity: "info",
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: "City image removed",
        city,
        requestId,
      });
    }

    const deleted = await City.findOneAndDelete(filter).lean().maxTimeMS(MAX_TIME_MS);

    if (!deleted) {
      return res.status(404).json({
        success: false,
        message: "City not found",
        code: "NOT_FOUND",
        requestId,
      });
    }

    const deletedPublicId = String((deleted as any)?.image?.publicId || "");
    if (deletedPublicId && isHighrisePublicId(deletedPublicId)) {
      await deleteFile(deletedPublicId).catch(() => undefined);
    }

    SecurityEvent.create({
      eventType: "admin_action",
      userId: auth.id,
      metadata: { action: "delete_city", cityId: (deleted as any)?._id?.toString(), cityName: (deleted as any)?.name },
      ipAddress: ip,
      userAgent: ua,
      severity: "warning",
    }).catch(console.error);

    return res.status(200).json({
      success: true,
      message: "City deleted",
      requestId,
    });
  } catch (error: any) {
    console.error("Admin Cities Error:", { requestId, error: error?.message });

    SecurityEvent.create({
      eventType: "system_error",
      userId: null,
      metadata: {
        endpoint: "/api/admin/cities",
        errorCode: error?.code || "UNKNOWN",
      },
      ipAddress: ip,
      userAgent: ua,
      severity: "error",
    }).catch(console.error);

    if (error?.statusCode && error?.code) {
      return res.status(error.statusCode).json({
        success: false,
        message: error.message,
        code: error.code,
        requestId,
      });
    }

    return res.status(500).json({
      success: false,
      message: "Internal server error",
      code: "SERVER_ERROR",
      requestId,
    });
  }
}

// pages/api/admin/comments/[id]/index.ts
// 🔒 ENTERPRISE v2.0 - Admin Comment Moderation with Zod, Audit Trail & Full RBAC

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Comment from '@/models/Comment';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { checkPermission } from '@/lib/permissions';
import { rateLimitAdmin } from '@/lib/rateLimit';
import { z } from 'zod';

// ═══════════════════════════════════════════════════════════════
// 🔒 ENTERPRISE CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TIME_MS = 5000;

const VALID_ACTIONS = ['approve', 'reject', 'spam', 'pending'] as const;
const CONFIRMATION_CODE = 'DELETE-COMMENT-PERMANENTLY';

// ═══════════════════════════════════════════════════════════════
// 🔒 ZOD VALIDATION SCHEMAS
// ═══════════════════════════════════════════════════════════════

const ObjectIdSchema = z.string().regex(/^[a-fA-F0-9]{24}$/, 'Invalid ID format');

const UpdateCommentSchema = z.object({
  action: z.enum(VALID_ACTIONS),
  adminNotes: z.string().trim().max(500).optional(),
});

const DeleteQuerySchema = z.object({
  permanent: z.enum(['true', 'false']).optional().default('false'),
  confirmationCode: z.string().optional(),
});

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY HEADERS + REQUEST ID
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function setSecurityHeaders(res: NextApiResponse, requestId: string) {
  res.setHeader('X-Request-Id', requestId);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
}

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || '').split(',')[0]?.trim() || req.socket?.remoteAddress || '0.0.0.0';
}

function getUserAgent(req: NextApiRequest): string {
  return String(req.headers['user-agent'] || '').slice(0, 200);
}

function requireActiveAdminOrThrow(user: any) {
  if (!user) {
    const err: any = new Error('User not found');
    err.statusCode = 401;
    err.code = 'USER_NOT_FOUND';
    throw err;
  }

  const role = String(user.role || 'user').toLowerCase();
  if (!['admin', 'superadmin', 'moderator'].includes(role)) {
    const err: any = new Error('Admin access required');
    err.statusCode = 403;
    err.code = 'ADMIN_REQUIRED';
    throw err;
  }
}

/**
 * Archive comment data before permanent deletion
 */
async function archiveCommentData(comment: any, deletedBy: string, ip: string, ua: string): Promise<void> {
  try {
    await SecurityEvent.create({
      eventType: 'comment_permanently_deleted',
      severity: 'high',
      userId: deletedBy,
      ipAddress: ip,
      userAgent: ua,
      metadata: {
        commentId: String(comment._id),
        content: comment.content?.slice(0, 100) || '',
        authorName: comment.author?.name || '',
        blogSlug: comment.blogSlug || '',
        status: comment.status,
        likes: comment.likes?.length || 0,
        reports: comment.reportCount || 0,
        createdAt: comment.createdAt,
      },
    });
  } catch (error) {
    console.error('Failed to archive comment data:', error);
  }
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const ip = getClientIp(req);
  const ua = getUserAgent(req);

  // ═══════════════════════════════════════════════════════════════
  // ✅ VALIDATE COMMENT ID
  // ═══════════════════════════════════════════════════════════════

  const { id } = req.query;
  const idResult = ObjectIdSchema.safeParse(id);

  if (!idResult.success) {
    return res.status(400).json({
      success: false,
      message: 'Invalid comment ID format',
      code: 'INVALID_ID',
      requestId,
    });
  }

  const commentId = idResult.data;

  try {
    await dbConnect();

    // ═══════════════════════════════════════════════════════════════
    // ✅ RATE LIMITING
    // ═══════════════════════════════════════════════════════════════

    const rl = await rateLimitAdmin(req);
    if (!rl.ok) {
      res.setHeader('Retry-After', String(rl.retryAfter || 60));
      return res.status(429).json({
        success: false,
        message: 'Too many requests. Please slow down.',
        code: 'RATE_LIMITED',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ AUTHENTICATION & AUTHORIZATION
    // ═══════════════════════════════════════════════════════════════

    const session = (await getServerSession(req, res, authOptions)) as any;

    if (!session?.user) {
      SecurityEvent.create({
        eventType: 'unauthorized_access_attempt',
        severity: 'high',
        ipAddress: ip,
        userAgent: ua,
        metadata: {
          endpoint: `/api/admin/comments/${commentId}`,
          reason: 'No active session',
        },
      }).catch(console.error);

      return res.status(401).json({
        success: false,
        message: 'Authentication required',
        code: 'UNAUTHORIZED',
        requestId,
      });
    }

    const admin: any = await User.findById(session.user.id)
      .select('role permissions status isDeleted')
      .lean()
      .maxTimeMS(MAX_TIME_MS);

    requireActiveAdminOrThrow(admin);

    const isSuperAdmin = String(admin.role).toLowerCase() === 'superadmin';

    // ═══════════════════════════════════════════════════════════════
    // ✅ GET METHOD - VIEW COMMENT DETAILS
    // ═══════════════════════════════════════════════════════════════

    if (req.method === 'GET') {
      const hasPermission = checkPermission(admin, 'comment_view_details');
      if (!hasPermission) {
        SecurityEvent.create({
          eventType: 'permission_denied',
          severity: 'high',
          userId: session.user.id,
          ipAddress: ip,
          userAgent: ua,
          metadata: {
            endpoint: `/api/admin/comments/${commentId}`,
            permission: 'comment_view_details',
          },
        }).catch(console.error);

        return res.status(403).json({
          success: false,
          message: 'Permission denied',
          code: 'PERMISSION_DENIED',
          requestId,
        });
      }

      const comment: any = await Comment.findById(commentId)
        .populate('blogId', 'title slug -_id')
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      if (!comment) {
        return res.status(404).json({
          success: false,
          message: 'Comment not found',
          code: 'NOT_FOUND',
          requestId,
        });
      }

      // Audit log (non-blocking)
      SecurityEvent.create({
        eventType: 'admin_action',
        severity: 'low',
        userId: session.user.id,
        ipAddress: ip,
        userAgent: ua,
        metadata: {
          action: 'view_comment_details',
          commentId,
        },
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: 'Comment found',
        comment,
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ PATCH METHOD - UPDATE COMMENT STATUS
    // ═══════════════════════════════════════════════════════════════

    if (req.method === 'PATCH') {
      const hasPermission = checkPermission(admin, 'comment_moderate');
      if (!hasPermission) {
        SecurityEvent.create({
          eventType: 'permission_denied',
          severity: 'high',
          userId: session.user.id,
          ipAddress: ip,
          userAgent: ua,
          metadata: {
            endpoint: `/api/admin/comments/${commentId}`,
            permission: 'comment_moderate',
          },
        }).catch(console.error);

        return res.status(403).json({
          success: false,
          message: 'Permission denied',
          code: 'PERMISSION_DENIED',
          requestId,
        });
      }

      // Validate request body
      const parseResult = UpdateCommentSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid request body',
          code: 'VALIDATION_ERROR',
          errors: parseResult.error.flatten().fieldErrors,
          requestId,
        });
      }

      const { action, adminNotes } = parseResult.data;

      const comment: any = await Comment.findById(commentId).maxTimeMS(MAX_TIME_MS);

      if (!comment) {
        return res.status(404).json({
          success: false,
          message: 'Comment not found',
          code: 'NOT_FOUND',
          requestId,
        });
      }

      // Status mapping
      const statusMap: Record<string, string> = {
        approve: 'approved',
        reject: 'rejected',
        spam: 'spam',
        pending: 'pending',
      };

      const oldStatus = comment.status;
      const newStatus = statusMap[action];

      // Update comment
      comment.status = newStatus;
      comment.moderatedBy = session.user.id;
      comment.moderatedAt = new Date();

      if (adminNotes) {
        comment.adminNotes = adminNotes;
      }

      // Clear report flags if approved
      if (action === 'approve') {
        comment.isReported = false;
        comment.reportCount = 0;
        comment.reportReasons = [];
      }

      comment.updatedAt = new Date();
      await comment.save();

      const actionMessages: Record<string, string> = {
        approve: 'Comment approved successfully',
        reject: 'Comment rejected',
        spam: 'Comment marked as spam',
        pending: 'Comment moved to pending',
      };

      // Audit log (non-blocking)
      SecurityEvent.create({
        eventType: 'admin_action',
        severity: action === 'spam' ? 'medium' : 'low',
        userId: session.user.id,
        ipAddress: ip,
        userAgent: ua,
        metadata: {
          action: 'moderate_comment',
          commentId,
          oldStatus,
          newStatus,
          moderationAction: action,
        },
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: actionMessages[action],
        comment: {
          _id: comment._id,
          status: comment.status,
          moderatedBy: comment.moderatedBy,
          moderatedAt: comment.moderatedAt,
        },
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ DELETE METHOD - SOFT/PERMANENT DELETE
    // ═══════════════════════════════════════════════════════════════

    if (req.method === 'DELETE') {
      const hasPermission = checkPermission(admin, 'comment_delete');
      if (!hasPermission) {
        SecurityEvent.create({
          eventType: 'permission_denied',
          severity: 'high',
          userId: session.user.id,
          ipAddress: ip,
          userAgent: ua,
          metadata: {
            endpoint: `/api/admin/comments/${commentId}`,
            permission: 'comment_delete',
          },
        }).catch(console.error);

        return res.status(403).json({
          success: false,
          message: 'Permission denied',
          code: 'PERMISSION_DENIED',
          requestId,
        });
      }

      // Validate query params
      const queryResult = DeleteQuerySchema.safeParse(req.query);
      if (!queryResult.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid query parameters',
          code: 'VALIDATION_ERROR',
          requestId,
        });
      }

      const { permanent, confirmationCode } = queryResult.data;

      const comment: any = await Comment.findById(commentId).maxTimeMS(MAX_TIME_MS);

      if (!comment) {
        return res.status(404).json({
          success: false,
          message: 'Comment not found',
          code: 'NOT_FOUND',
          requestId,
        });
      }

      if (permanent === 'true') {
        // ⚠️ PERMANENT DELETE - Requires SuperAdmin + Confirmation
        if (!isSuperAdmin) {
          return res.status(403).json({
            success: false,
            message: 'SuperAdmin access required for permanent deletion',
            code: 'SUPERADMIN_REQUIRED',
            requestId,
          });
        }

        if (confirmationCode !== CONFIRMATION_CODE) {
          SecurityEvent.create({
            eventType: 'suspicious_activity',
            severity: 'high',
            userId: session.user.id,
            ipAddress: ip,
            userAgent: ua,
            metadata: {
              action: 'invalid_confirmation_code',
              commentId,
            },
          }).catch(console.error);

          return res.status(400).json({
            success: false,
            message: `Invalid confirmation code. Please enter "${CONFIRMATION_CODE}" to confirm.`,
            code: 'INVALID_CONFIRMATION',
            requestId,
          });
        }

        // Archive before deletion
        await archiveCommentData(comment, session.user.id, ip, ua);

        // Permanent delete
        await Comment.findByIdAndDelete(commentId).maxTimeMS(MAX_TIME_MS);

        SecurityEvent.create({
          eventType: 'admin_action',
          severity: 'critical',
          userId: session.user.id,
          ipAddress: ip,
          userAgent: ua,
          metadata: {
            action: 'comment_permanently_deleted',
            commentId,
          },
        }).catch(console.error);

        return res.status(200).json({
          success: true,
          message: 'Comment permanently deleted',
          requestId,
        });
      } else {
        // Soft delete
        comment.isDeleted = true;
        comment.deletedAt = new Date();
        comment.deletedBy = session.user.id;
        await comment.save();

        SecurityEvent.create({
          eventType: 'admin_action',
          severity: 'medium',
          userId: session.user.id,
          ipAddress: ip,
          userAgent: ua,
          metadata: {
            action: 'comment_soft_deleted',
            commentId,
          },
        }).catch(console.error);

        return res.status(200).json({
          success: true,
          message: 'Comment deleted',
          comment: {
            _id: comment._id,
            isDeleted: comment.isDeleted,
            deletedAt: comment.deletedAt,
          },
          requestId,
        });
      }
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ METHOD NOT ALLOWED
    // ═══════════════════════════════════════════════════════════════

    res.setHeader('Allow', ['GET', 'PATCH', 'DELETE']);
    return res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
  } catch (error: any) {
    console.error('Admin comment moderation error:', { requestId, error: error?.message });

    SecurityEvent.create({
      eventType: 'system_error',
      severity: 'critical',
      ipAddress: ip,
      userAgent: ua,
      metadata: {
        endpoint: `/api/admin/comments/${commentId}`,
        method: req.method,
        errorCode: error?.code || 'UNKNOWN',
      },
    }).catch(console.error);

    if (error?.statusCode && error?.code) {
      return res.status(error.statusCode).json({
        success: false,
        message: error.message,
        code: error.code,
        requestId,
      });
    }

    return res.status(500).json({
      success: false,
      message: 'Internal server error',
      code: 'SERVER_ERROR',
      requestId,
    });
  }
}

// pages/api/admin/comments/[id]/pin.ts
// 🔒 ENTERPRISE v2.0 - Admin Comment Pinning (Reddit/Discord Style)

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Comment from '@/models/Comment';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { checkPermission } from '@/lib/permissions';
import { rateLimitAdmin } from '@/lib/rateLimit';
import { z } from 'zod';

// ═══════════════════════════════════════════════════════════════
// 🔒 ENTERPRISE CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TIME_MS = 5000;
const MAX_PINNED_PER_BLOG = 3; // Maximum pinned comments per blog post

// ═══════════════════════════════════════════════════════════════
// 🔒 ZOD VALIDATION SCHEMAS
// ═══════════════════════════════════════════════════════════════

const ObjectIdSchema = z.string().regex(/^[a-fA-F0-9]{24}$/, 'Invalid ID format');

const PinCommentSchema = z.object({
  action: z.enum(['pin', 'unpin']),
  reason: z.string().trim().max(200).optional(),
});

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY HEADERS + REQUEST ID
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function setSecurityHeaders(res: NextApiResponse, requestId: string) {
  res.setHeader('X-Request-Id', requestId);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
}

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || '').split(',')[0]?.trim() || req.socket?.remoteAddress || '0.0.0.0';
}

function getUserAgent(req: NextApiRequest): string {
  return String(req.headers['user-agent'] || '').slice(0, 200);
}

function requireActiveAdminOrThrow(user: any) {
  if (!user) {
    const err: any = new Error('User not found');
    err.statusCode = 401;
    err.code = 'USER_NOT_FOUND';
    throw err;
  }

  const role = String(user.role || 'user').toLowerCase();
  if (!['admin', 'superadmin', 'moderator'].includes(role)) {
    const err: any = new Error('Admin access required');
    err.statusCode = 403;
    err.code = 'ADMIN_REQUIRED';
    throw err;
  }
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const ip = getClientIp(req);
  const ua = getUserAgent(req);

  // ═══════════════════════════════════════════════════════════════
  // ✅ METHOD CHECK
  // ═══════════════════════════════════════════════════════════════

  if (req.method !== 'POST' && req.method !== 'PATCH') {
    res.setHeader('Allow', ['POST', 'PATCH']);
    return res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
  }

  // ═══════════════════════════════════════════════════════════════
  // ✅ VALIDATE COMMENT ID
  // ═══════════════════════════════════════════════════════════════

  const { id } = req.query;
  const idResult = ObjectIdSchema.safeParse(id);

  if (!idResult.success) {
    return res.status(400).json({
      success: false,
      message: 'Invalid comment ID format',
      code: 'INVALID_ID',
      requestId,
    });
  }

  const commentId = idResult.data;

  try {
    await dbConnect();

    // ═══════════════════════════════════════════════════════════════
    // ✅ RATE LIMITING
    // ═══════════════════════════════════════════════════════════════

    const rl = await rateLimitAdmin(req);
    if (!rl.ok) {
      res.setHeader('Retry-After', String(rl.retryAfter || 60));
      return res.status(429).json({
        success: false,
        message: 'Too many requests. Please slow down.',
        code: 'RATE_LIMITED',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ AUTHENTICATION & AUTHORIZATION
    // ═══════════════════════════════════════════════════════════════

    const session = (await getServerSession(req, res, authOptions)) as any;

    if (!session?.user) {
      SecurityEvent.create({
        eventType: 'unauthorized_access_attempt',
        severity: 'high',
        ipAddress: ip,
        userAgent: ua,
        metadata: {
          endpoint: `/api/admin/comments/${commentId}/pin`,
          reason: 'No active session',
        },
      }).catch(console.error);

      return res.status(401).json({
        success: false,
        message: 'Authentication required',
        code: 'UNAUTHORIZED',
        requestId,
      });
    }

    const admin: any = await User.findById(session.user.id)
      .select('role permissions status isDeleted')
      .lean()
      .maxTimeMS(MAX_TIME_MS);

    requireActiveAdminOrThrow(admin);

    // ✅ Permission Check
    const hasPermission = checkPermission(admin, 'comment_pin');
    if (!hasPermission) {
      SecurityEvent.create({
        eventType: 'permission_denied',
        severity: 'high',
        userId: session.user.id,
        ipAddress: ip,
        userAgent: ua,
        metadata: {
          endpoint: `/api/admin/comments/${commentId}/pin`,
          permission: 'comment_pin',
        },
      }).catch(console.error);

      return res.status(403).json({
        success: false,
        message: 'Permission denied',
        code: 'PERMISSION_DENIED',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ VALIDATE REQUEST BODY
    // ═══════════════════════════════════════════════════════════════

    const parseResult = PinCommentSchema.safeParse(req.body);
    if (!parseResult.success) {
      return res.status(400).json({
        success: false,
        message: 'Invalid request body',
        code: 'VALIDATION_ERROR',
        errors: parseResult.error.flatten().fieldErrors,
        requestId,
      });
    }

    const { action, reason } = parseResult.data;

    // ═══════════════════════════════════════════════════════════════
    // ✅ FETCH COMMENT
    // ═══════════════════════════════════════════════════════════════

    const comment: any = await Comment.findById(commentId).maxTimeMS(MAX_TIME_MS);

    if (!comment) {
      return res.status(404).json({
        success: false,
        message: 'Comment not found',
        code: 'NOT_FOUND',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ CHECK IF COMMENT IS DELETED
    // ═══════════════════════════════════════════════════════════════

    if (comment.isDeleted) {
      return res.status(400).json({
        success: false,
        message: 'Cannot pin a deleted comment',
        code: 'COMMENT_DELETED',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ HANDLE PIN ACTION
    // ═══════════════════════════════════════════════════════════════

    const now = new Date();

    if (action === 'pin') {
      // Check if already pinned
      if (comment.isPinned) {
        return res.status(400).json({
          success: false,
          message: 'Comment is already pinned',
          code: 'ALREADY_PINNED',
          requestId,
        });
      }

      // Check maximum pinned comments per blog
      const pinnedCount = await Comment.countDocuments({
        blogId: comment.blogId,
        isPinned: true,
        isDeleted: { $ne: true },
      }).maxTimeMS(MAX_TIME_MS);

      if (pinnedCount >= MAX_PINNED_PER_BLOG) {
        return res.status(400).json({
          success: false,
          message: `Maximum ${MAX_PINNED_PER_BLOG} pinned comments per blog post reached. Unpin another comment first.`,
          code: 'MAX_PINNED_REACHED',
          maxAllowed: MAX_PINNED_PER_BLOG,
          currentPinned: pinnedCount,
          requestId,
        });
      }

      // Pin the comment
      comment.isPinned = true;
      comment.pinnedBy = session.user.id;
      comment.pinnedAt = now;
      comment.pinnedReason = reason || 'Highlighted by admin';
      comment.updatedAt = now;

      await comment.save();

      // Audit log
      SecurityEvent.create({
        eventType: 'admin_action',
        severity: 'medium',
        userId: session.user.id,
        ipAddress: ip,
        userAgent: ua,
        metadata: {
          action: 'comment_pinned',
          commentId,
          blogId: String(comment.blogId),
          reason: reason || 'No reason provided',
        },
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: 'Comment pinned successfully',
        comment: {
          _id: comment._id,
          isPinned: comment.isPinned,
          pinnedBy: comment.pinnedBy,
          pinnedAt: comment.pinnedAt,
          pinnedReason: comment.pinnedReason,
        },
        pinnedCount: pinnedCount + 1,
        maxAllowed: MAX_PINNED_PER_BLOG,
        requestId,
      });
    }

    // action === 'unpin'
    if (!comment.isPinned) {
      return res.status(400).json({
        success: false,
        message: 'Comment is not pinned',
        code: 'NOT_PINNED',
        requestId,
      });
    }

    // Unpin the comment
    comment.isPinned = false;
    comment.pinnedBy = undefined;
    comment.pinnedAt = undefined;
    comment.pinnedReason = undefined;
    comment.updatedAt = now;

    await comment.save();

    // Audit log
    SecurityEvent.create({
      eventType: 'admin_action',
      severity: 'low',
      userId: session.user.id,
      ipAddress: ip,
      userAgent: ua,
      metadata: {
        action: 'comment_unpinned',
        commentId,
        blogId: String(comment.blogId),
      },
    }).catch(console.error);

    return res.status(200).json({
      success: true,
      message: 'Comment unpinned successfully',
      comment: {
        _id: comment._id,
        isPinned: comment.isPinned,
      },
      requestId,
    });
  } catch (error: any) {
    console.error('Pin comment error:', { requestId, error: error?.message });

    SecurityEvent.create({
      eventType: 'system_error',
      severity: 'critical',
      ipAddress: ip,
      userAgent: ua,
      metadata: {
        endpoint: `/api/admin/comments/${commentId}/pin`,
        errorCode: error?.code || 'UNKNOWN',
      },
    }).catch(console.error);

    if (error?.statusCode && error?.code) {
      return res.status(error.statusCode).json({
        success: false,
        message: error.message,
        code: error.code,
        requestId,
      });
    }

    return res.status(500).json({
      success: false,
      message: 'Internal server error',
      code: 'SERVER_ERROR',
      requestId,
    });
  }
}

