        ? { ...baseFilter, $or: searchConditions }
        : baseFilter;

    // ── Execute query ─────────────────────────────────────────
    const docs: any[] = await Property.find(filter)
      .select(
        'title city society propertyType listingType price area unit ' +
        'featureImageUrl images gallery slug'
      )
      .sort({ 'trustScore.score': -1, views: -1 })
      .limit(20)
      .lean();

    // ── Map results ───────────────────────────────────────────
    const results: PropertyResult[] = docs.map((doc) => {
      let imageUrl: string | null = null;

      if (Array.isArray(doc.images) && doc.images.length > 0) {
        const primary = doc.images.find((img: any) => img?.isPrimary);
        imageUrl = primary?.url ?? doc.images[0]?.url ?? null;
      }

      if (!imageUrl && doc.featureImageUrl) {
        imageUrl = doc.featureImageUrl;
      }

      if (!imageUrl && Array.isArray(doc.gallery) && doc.gallery.length > 0) {
        imageUrl = doc.gallery[0]?.url ?? null;
      }

      return {
        id:           String(doc._id),
        title:        doc.title        || '',
        city:         doc.city         || '',
        society:      doc.society      || '',
        propertyType: doc.propertyType || '',
        listingType:  doc.listingType  || '',
        price:        doc.price        || 0,
        area:         doc.area         || 0,
        unit:         doc.unit         || '',
        imageUrl,
        slug:         doc.slug         || null,
      };
    });

    // ── Audit log ─────────────────────────────────────────────
    await logSecurityEvent({
      type:      'admin_action',
      severity:  'low',
      userId:    auth.id,
      ip:        String(req.headers['x-forwarded-for'] || req.socket?.remoteAddress || ''),
      userAgent: String(req.headers['user-agent'] || ''),
      metadata:  {
        requestId,
        action:  'property_search',
        query:   rawQuery,
        count:   results.length,
      },
    });

    return res.status(200).json({
      success: true,
      results,
      total:   results.length,
    });

  } catch (err) {
    await logSecurityEvent({
      type:      'system_error',
      severity:  'high',
      userId:    auth.id,
      ip:        String(req.headers['x-forwarded-for'] || req.socket?.remoteAddress || ''),
      userAgent: String(req.headers['user-agent'] || ''),
      metadata:  {
        requestId,
        action: 'property_search_error',
        error:  err instanceof Error ? err.message : 'unknown',
      },
    });

    return res.status(500).json({
      success: false,
      message: 'Search failed — please try again',
    });
  }
}

// pages/api/admin/developers/[developerId]/index.ts
// 🔒 ENTERPRISE v3.0 — Admin Developer Detail & Update
// Fixes: requireAdmin, logSecurityEvent, crypto.randomUUID,
//        correct enum values, tokenVersion++, Project removed (TODO),
//        proper types, dbConnect order, route param [developerId]

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import DeveloperProfile from '@/models/DeveloperProfile';
import User from '@/models/User';
import { requireAdmin } from '@/lib/requireAdmin';
import { rateLimitAdmin } from '@/lib/rateLimit';
import { logSecurityEvent } from '@/lib/security/logSecurityEvent';
import { z } from 'zod';
import { toPrivateKycAssetView } from '@/lib/privateAsset';

// ═══════════════════════════════════════════════════════════════
// 🔒 CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TIME_MS = 5000;

const VALID_STATUSES = [
  'approved', 'rejected', 'pending', 'suspended',
] as const;

const VALID_RISK_LEVELS = [
  'low', 'medium', 'high',
] as const;

// ✅ Locked DeveloperProfile verificationLevel enum
const VALID_VERIFICATION_LEVELS = [
  'not_verified',
  'docs_pending',
  'docs_verified',
  'site_verified',
  'fully_verified',
] as const;

// ═══════════════════════════════════════════════════════════════
// 🔒 TYPES
// ═══════════════════════════════════════════════════════════════

type ValidStatus            = typeof VALID_STATUSES[number];
type ValidRiskLevel = typeof VALID_RISK_LEVELS[number]; // 'low' | 'medium' | 'high'
type ValidVerificationLevel = typeof VALID_VERIFICATION_LEVELS[number];

interface UpdatePayload {
  status?:             ValidStatus;
  highriseScore?:      number;
  onTimeDeliveryRate?: number;
  riskLevel?:          ValidRiskLevel;
  verificationLevel?:  ValidVerificationLevel;
  adminNotes?:         string;
}

interface ChangeRecord {
  before: Partial<UpdatePayload>;
  after:  Partial<UpdatePayload & { isVerified: boolean }>;
}

interface IdentitySummary {
  email?:     string;
  name?:      string;
  createdAt?: Date;
}

// ═══════════════════════════════════════════════════════════════
// 🔒 ZOD SCHEMAS
// ═══════════════════════════════════════════════════════════════

const ObjectIdSchema = z.string().regex(
  /^[a-fA-F0-9]{24}$/,
  'Invalid ID format',
);

const UpdateDeveloperSchema = z.object({
  status:             z.enum(VALID_STATUSES).optional(),
  highriseScore:      z.number().min(0).max(100).optional(),
  onTimeDeliveryRate: z.number().min(0).max(100).optional(),
  riskLevel:          z.enum(VALID_RISK_LEVELS).optional(),
  verificationLevel:  z.enum(VALID_VERIFICATION_LEVELS).optional(),
  adminNotes:         z.string().trim().max(1000).optional(),
}).refine(
  (data) =>
    data.status              !== undefined ||
    data.highriseScore       !== undefined ||
    data.onTimeDeliveryRate  !== undefined ||
    data.riskLevel           !== undefined ||
    data.verificationLevel   !== undefined ||
    data.adminNotes          !== undefined,
  { message: 'At least one field must be provided for update' },
);

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY HEADERS
// ═══════════════════════════════════════════════════════════════

function setSecurityHeaders(
  res:       NextApiResponse,
  requestId: string,
): void {
  res.setHeader('X-Request-Id',              requestId);
  res.setHeader('Content-Type',              'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options',    'nosniff');
  res.setHeader('X-Frame-Options',           'DENY');
  res.setHeader('Cache-Control',             'no-store, no-cache, must-revalidate, private');
  res.setHeader('Referrer-Policy',           'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  res.setHeader('Permissions-Policy',        'geolocation=(), microphone=(), camera=()');
}

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPERS
// ═══════════════════════════════════════════════════════════════

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip ?? '').split(',')[0]?.trim()
    || req.socket?.remoteAddress
    || '0.0.0.0';
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse,
): Promise<void> {

  const requestId = crypto.randomUUID();
  setSecurityHeaders(res, requestId);

  const ip = getClientIp(req);
  const ua = String(req.headers['user-agent'] ?? '').slice(0, 200);

  // ── Method guard ─────────────────────────────────────────────
  if (req.method !== 'GET' && req.method !== 'PUT') {
    res.setHeader('Allow', ['GET', 'PUT']);
    void res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ── Validate route param ─────────────────────────────────────
  // ✅ Route param is [developerId] — matches locked naming convention
  const { developerId } = req.query;
  const idResult = ObjectIdSchema.safeParse(developerId);

  if (!idResult.success) {
    void res.status(400).json({
      success: false,
      message: 'Invalid Developer ID format',
      code:    'INVALID_ID',
      requestId,
    });
    return;
  }

  const developerIdStr = idResult.data;

  // ── DB ───────────────────────────────────────────────────────
  // ✅ dbConnect before ALL queries — including auth
  await dbConnect();

  // ── Rate limit ───────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    res.setHeader('Retry-After', String(rl.retryAfter ?? 60));
    void res.status(429).json({
      success: false,
      message: 'Too many requests. Please slow down.',
      code:    'RATE_LIMITED',
      requestId,
    });
    return;
  }

  // ── Auth ─────────────────────────────────────────────────────
  // ✅ requireAdmin() — replaces getServerSession + User.findById
  //    + requireActiveAdminOrThrow entirely
  const auth = await requireAdmin(req, res);
  if (!auth) return; // requireAdmin already sent 401/403

  // ════════════════════════════════════════════════════════════
  // ✅ GET — Developer detail view
  // ════════════════════════════════════════════════════════════

  if (req.method === 'GET') {
    try {
      const developer = await DeveloperProfile.findById(developerIdStr)
        .populate('user', 'name email createdAt')
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      if (!developer) {
        void res.status(404).json({
          success: false,
          message: 'Developer not found',
          code:    'NOT_FOUND',
          requestId,
        });
        return;
      }

      // ── Identity summary (admin detail view — email acceptable) ─
      const userRef = developer.user as {
        name?:      string;
        email?:     string;
        createdAt?: Date;
      } | null;

      const identitySummary: IdentitySummary = {
        email:     userRef?.email     ? String(userRef.email)     : undefined,
        name:      userRef?.name      ? String(userRef.name)      : undefined,
        createdAt: userRef?.createdAt ?? undefined,
      };

      // ── Audit log ────────────────────────────────────────────
      logSecurityEvent({
        type:      'admin_action',
        severity:  'low',
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:            'admin_view_developer_detail',
          targetDeveloperId: developerIdStr,
          requestId,
        },
      });

      // Sensitive legal/KYC assets are delivered with short-lived signed URLs.
      // Legacy public-only URLs remain visible to admins temporarily and are
      // explicitly flagged so they can be migrated to authenticated delivery.
      const legalDocs = (developer as Record<string, any>).legalDocs;
      if (legalDocs) {
        for (const key of [
          'secpCertificate',
          'ntnCertificate',
          'memorandum',
          'articlesOfAssociation',
          'authorizedPersonCnicFrontImage',
          'authorizedPersonCnicBackImage',
        ]) {
          if (legalDocs[key]) {
            legalDocs[key] = toPrivateKycAssetView(legalDocs[key], {
              allowLegacyAdminUrl: true,
            });
          }
        }
        if (Array.isArray(legalDocs.pastProjects)) {
          legalDocs.pastProjects = legalDocs.pastProjects
            .map((asset: Record<string, unknown>) =>
              toPrivateKycAssetView(asset, { allowLegacyAdminUrl: true }),
            )
            .filter(Boolean);
        }
      }

      void res.status(200).json({
        success: true,
        developer,
        identitySummary,
        requestId,
      });

    } catch (error: unknown) {
      logSecurityEvent({
        type:      'admin_action',
        severity:  'high',
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:            'admin_view_developer_detail_error',
          targetDeveloperId: developerIdStr,
          errorCode:         error instanceof Error ? error.message : 'UNKNOWN',
          requestId,
        },
      });

      void res.status(500).json({
        success: false,
        message: 'Internal server error',
        code:    'SERVER_ERROR',
        requestId,
      });
    }
    return;
  }

  // ════════════════════════════════════════════════════════════
  // ✅ PUT — Update developer
  // ════════════════════════════════════════════════════════════

  if (req.method === 'PUT') {

    // ── Validate body ─────────────────────────────────────────
    const parseResult = UpdateDeveloperSchema.safeParse(req.body);
    if (!parseResult.success) {
      void res.status(400).json({
        success: false,
        message: 'Invalid request body',
        code:    'VALIDATION_ERROR',
        errors:  parseResult.error.flatten().fieldErrors,
        requestId,
      });
      return;
    }

    const {
      status,
      highriseScore,
      onTimeDeliveryRate,
      riskLevel,
      verificationLevel,
      adminNotes,
    }: UpdatePayload = parseResult.data;

    try {
      const developer = await DeveloperProfile.findById(developerIdStr)
        .maxTimeMS(MAX_TIME_MS);

      if (!developer) {
        void res.status(404).json({
          success: false,
          message: 'Developer not found',
          code:    'NOT_FOUND',
          requestId,
        });
        return;
      }

      if (developer.isDeleted) {
        void res.status(400).json({
          success: false,
          message: 'Cannot update a deleted developer. Restore it first.',
          code:    'DEVELOPER_DELETED',
          requestId,
        });
        return;
      }

      // ── Change tracking ───────────────────────────────────
      const changes: ChangeRecord = { before: {}, after: {} };
      let statusUpdated = false;
      let trustUpdated  = false;

      // ── Status update ─────────────────────────────────────
      if (status !== undefined) {
        changes.before.status = developer.status as ValidStatus;
        changes.after.status  = status;
        developer.status      = status;
        statusUpdated         = true;

        if (status === 'approved') {
          developer.isVerified  = true;
          developer.verifiedAt  = new Date();
          changes.after.isVerified = true;

          // ✅ tokenVersion++ forces re-login after role change
          await User.findByIdAndUpdate(
            developer.user,
            {
              $set: { role: 'developer' },
              $inc: { tokenVersion: 1 },   // ← CRITICAL: invalidates old JWT
            },
            { runValidators: true },
          ).maxTimeMS(MAX_TIME_MS);

        } else {
          developer.isVerified = false;
          developer.verifiedAt = undefined;
          changes.after.isVerified = false;
        }

        // TODO: Sync project approval status when Project model is built (Section 5)
        // Project.updateMany({ developerId: developer.user }, {
        //   $set: { developerApprovalStatus: status === 'approved' ? 'approved' : 'pending' }
        // })
      }

      // ── Trust metrics ──────────────────────────────────────
      if (highriseScore !== undefined) {
        changes.before.highriseScore = developer.highriseScore as number;
        changes.after.highriseScore  = highriseScore;
        developer.highriseScore      = highriseScore;
        trustUpdated                 = true;
      }

      if (onTimeDeliveryRate !== undefined) {
        changes.before.onTimeDeliveryRate = developer.onTimeDeliveryRate as number;
        changes.after.onTimeDeliveryRate  = onTimeDeliveryRate;
        developer.onTimeDeliveryRate      = onTimeDeliveryRate;
        trustUpdated                      = true;
      }

      if (riskLevel !== undefined) {
        changes.before.riskLevel = developer.riskLevel as ValidRiskLevel;
        changes.after.riskLevel  = riskLevel;
        developer.riskLevel      = riskLevel;
        trustUpdated             = true;
      }

      if (verificationLevel !== undefined) {
        changes.before.verificationLevel = developer.verificationLevel as ValidVerificationLevel;
        changes.after.verificationLevel  = verificationLevel;
        developer.verificationLevel      = verificationLevel;

        if (verificationLevel !== 'not_verified') {
          developer.lastVerifiedAt = new Date();
        }
        trustUpdated = true;
      }

      if (adminNotes !== undefined) {
        developer.adminNotes = adminNotes;
      }

      // ✅ No manual updatedAt — Mongoose timestamps:true handles it
      await developer.save();

      // ── Audit log ─────────────────────────────────────────
      logSecurityEvent({
        type:      'admin_action',
        severity:  statusUpdated ? 'high' : 'medium',
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:            'admin_update_developer',
          targetDeveloperId: developerIdStr,
          statusUpdated,
          trustUpdated,
          changes,
          requestId,
        },
      });

      // ── Build message ──────────────────────────────────────
      let message = 'Developer updated successfully';
      if (statusUpdated && trustUpdated) {
        message = `Developer ${status} and trust metrics updated`;
      } else if (trustUpdated) {
        message = 'Trust metrics updated successfully';
      } else if (statusUpdated) {
        message = `Developer status updated to ${status}`;
      }

      // ── Response — lean snapshot, no encrypted fields ──────
      // ✅ adminNotes is select:false — must explicitly include in admin response
      const snapshot = await DeveloperProfile.findById(developerIdStr)
        .select({
          companyName:        1,
          slug:               1,
          status:             1,
          isVerified:         1,
          verificationLevel:  1,
          highriseScore:      1,
          onTimeDeliveryRate: 1,
          riskLevel:          1,
          adminNotes:         1,   // select:false field — explicit inclusion required
          updatedAt:          1,
        })
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      void res.status(200).json({
        success: true,
        message,
        developer: snapshot,
        requestId,
      });

    } catch (error: unknown) {
      logSecurityEvent({
        type:      'admin_action',
        severity:  'high',
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:            'admin_update_developer_error',
          targetDeveloperId: developerIdStr,
          errorCode:         error instanceof Error ? error.message : 'UNKNOWN',
          requestId,
        },
      });

      void res.status(500).json({
        success: false,
        message: 'Internal server error',
        code:    'SERVER_ERROR',
        requestId,
      });
    }
  }
}

// pages/api/admin/email-templates/[id].ts

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import EmailTemplate from '@/models/EmailTemplate';
import { requireAdmin } from '@/lib/requireAuth';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  const { id } = req.query;

  await dbConnect();

  // GET - Get single template
  if (req.method === 'GET') {
    try {
      const template = await EmailTemplate.findById(id).lean();

      if (!template) {
        return res.status(404).json({ success: false, message: 'Template not found' });
      }

      return res.status(200).json({ success: true, template });

    } catch (error: any) {
      return res.status(500).json({ success: false, message: 'Server error' });
    }
  }

  // PUT - Update template
  if (req.method === 'PUT') {
    try {
      const { name, subject, message, category, isActive } = req.body;

      const updateData: any = {};
      if (name) updateData.name = name;
      if (subject) updateData.subject = subject;
      if (message) updateData.message = message;
      if (category) updateData.category = category;
      if (typeof isActive === 'boolean') updateData.isActive = isActive;

      const template = await EmailTemplate.findByIdAndUpdate(
        id,
        updateData,
        { new: true }
      );

      if (!template) {
        return res.status(404).json({ success: false, message: 'Template not found' });
      }

      return res.status(200).json({
        success: true,
        message: 'Template updated successfully',
        template,
      });

    } catch (error: any) {
      return res.status(500).json({ success: false, message: 'Server error' });
    }
  }

  // DELETE - Delete template
  if (req.method === 'DELETE') {
    try {
      const template = await EmailTemplate.findByIdAndDelete(id);

      if (!template) {
        return res.status(404).json({ success: false, message: 'Template not found' });
      }

      return res.status(200).json({
        success: true,
        message: 'Template deleted successfully',
      });

    } catch (error: any) {
      return res.status(500).json({ success: false, message: 'Server error' });
    }
  }

  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

// pages/api/admin/email-templates/index.ts

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import EmailTemplate from '@/models/EmailTemplate';
import { requireAdmin } from '@/lib/requireAuth';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  await dbConnect();

  // GET - List templates
  if (req.method === 'GET') {
    try {
      const { category, active } = req.query;

      const query: any = {};

      if (category && category !== 'all') {
        query.category = category;
      }

      if (active === 'true') {
        query.isActive = true;
      }

      const templates = await EmailTemplate.find(query)
        .sort({ createdAt: -1 })
        .lean();

      return res.status(200).json({
        success: true,
        templates,
      });

    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Server error',
        error: error.message,
      });
    }
  }

  // POST - Create template
  if (req.method === 'POST') {
    try {
      const { name, subject, message, category } = req.body;

      if (!name || !subject || !message) {
        return res.status(400).json({
          success: false,
          message: 'Name, subject, and message are required',
        });
      }

      const template = await EmailTemplate.create({
        name,
        subject,
        message,
        category: category || 'other',
        createdBy: 'Admin',
      });

      return res.status(201).json({
        success: true,
        message: 'Template created successfully',
        template,
      });

    } catch (error: any) {
      if (error.code === 11000) {
        return res.status(400).json({
          success: false,
          message: 'Template with this name already exists',
        });
      }
      return res.status(500).json({
        success: false,
        message: 'Server error',
        error: error.message,
      });
    }
  }

  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

// pages/api/admin/emails/index.ts

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Email from '@/models/Email';
import { requireAdmin } from '@/lib/requireAuth';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  await dbConnect();

  // ==========================================
  // 1. GET: List Emails (Normal vs Trash)
  // ==========================================
  if (req.method === 'GET') {
    try {
      const {
        page = '1',
        limit = '20',
        status,
        search,
        sortBy = 'createdAt',
        sortOrder = 'desc',
      } = req.query;

      const pageNum = parseInt(page as string);
      const limitNum = parseInt(limit as string);
      const skip = (pageNum - 1) * limitNum;

      // Build query
      const query: any = {};

      // --- TRASH LOGIC START ---
      if (status === 'trash') {
        // Show only archived emails
        query.isArchived = true;
      } else {
        // Normal list: Show if isArchived is false OR if field doesn't exist
        query.isArchived = { $ne: true };

        // Filter by status (sent/failed/pending) if provided
        if (status && status !== 'all') {
          query.status = status;
        }
      }
      // --- TRASH LOGIC END ---

      if (search && typeof search === 'string' && search.trim()) {
        const searchRegex = { $regex: search.trim(), $options: 'i' };
        query.$or = [
          { to: searchRegex },
          { toName: searchRegex },
          { subject: searchRegex },
        ];
      }

      // Sort
      const sortOptions: any = {};
      sortOptions[sortBy as string] = sortOrder === 'desc' ? -1 : 1;

      // Fetch emails
      const emails = await Email.find(query)
        .sort(sortOptions)
        .skip(skip)
        .limit(limitNum)
        .lean();

      // Get total count for pagination
      const total = await Email.countDocuments(query);

      // Get counts for tabs (Modified to respect isArchived)
      const [allCount, sentCount, failedCount, pendingCount, trashCount] = await Promise.all([
        Email.countDocuments({ isArchived: { $ne: true } }),
        Email.countDocuments({ status: 'sent', isArchived: { $ne: true } }),
        Email.countDocuments({ status: 'failed', isArchived: { $ne: true } }),
        Email.countDocuments({ status: 'pending', isArchived: { $ne: true } }),
        Email.countDocuments({ isArchived: true }), // Trash count
      ]);

      return res.status(200).json({
        success: true,
        emails,
        pagination: {
          page: pageNum,
          limit: limitNum,
          total,
          pages: Math.ceil(total / limitNum),
        },
        counts: {
          all: allCount,
          sent: sentCount,
          failed: failedCount,
          pending: pendingCount,
          trash: trashCount, // Return trash count
        },
      });

    } catch (error: any) {
      console.error('Error fetching emails:', error);
      return res.status(500).json({ 
        success: false, 
        message: 'Server error',
        error: error.message
      });
    }
  }

  // ==========================================
  // 2. DELETE: Soft Delete OR Permanent Delete
  // ==========================================
  if (req.method === 'DELETE') {
    try {
      const { id, type } = req.query; // type can be 'soft' or 'permanent'

      if (!id) {
        return res.status(400).json({ success: false, message: 'Email ID required' });
      }

      if (type === 'permanent') {
        // PERMANENT DELETE (from Trash)
        await Email.findByIdAndDelete(id);
        return res.status(200).json({ success: true, message: 'Email permanently deleted' });
      } else {
        // SOFT DELETE (Move to Trash)
        await Email.findByIdAndUpdate(id, {
          isArchived: true,
          archivedAt: new Date(),
          archivedBy: 'Admin', // You can replace this with actual user session info later
        });
        return res.status(200).json({ success: true, message: 'Email moved to trash' });
      }

    } catch (error: any) {
      console.error('Error deleting email:', error);
      return res.status(500).json({ success: false, message: error.message });
    }
  }

  // ==========================================
  // 3. PATCH: Restore from Trash
  // ==========================================
  if (req.method === 'PATCH') {
    try {
      const { id } = req.query;
      const { action } = req.body;

      if (!id) {
        return res.status(400).json({ success: false, message: 'Email ID required' });
      }

      if (action === 'restore') {
        await Email.findByIdAndUpdate(id, {
          isArchived: false,
          $unset: { archivedAt: 1, archivedBy: 1 },
        });
        return res.status(200).json({ success: true, message: 'Email restored successfully' });
      }

      return res.status(400).json({ success: false, message: 'Invalid action' });

    } catch (error: any) {
      console.error('Error restoring email:', error);
      return res.status(500).json({ success: false, message: error.message });
    }
  }

  // Method not allowed
  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

import type { NextApiRequest, NextApiResponse } from "next";
import { z } from "zod";
import mongoose from "mongoose";
import { v2 as cloudinary } from "cloudinary";
import dbConnect from "@/lib/dbConnect";
import HeroBanner from "@/models/HeroBanner";
import SecurityEvent from "@/models/SecurityEvent";
import User from "@/models/User";
import { requireAuth } from "@/lib/requireAuth";
import { checkPermission } from "@/lib/permissions";
import { rateLimitAdmin } from "@/lib/rateLimit";

const MAX_TIME_MS = 5000;

const UpdateHeroBannerSchema = z.object({
  title: z.string().trim().min(3).max(120),
  subtitle: z.string().trim().max(220).optional().default(""),
  imageUrl: z.string().trim().url(),
  imagePublicId: z.string().trim().optional().or(z.literal("")).default(""),
  mobileImageUrl: z.string().trim().url().optional().or(z.literal("")).default(""),
  mobileImagePublicId: z.string().trim().optional().or(z.literal("")).default(""),
  ctaText: z.string().trim().max(40).optional().default(""),
  ctaLink: z.string().trim().max(500).optional().default(""),
  targetType: z.enum(["internal", "external", "project", "property", "developer"]).default("internal"),
  targetId: z.string().trim().optional().or(z.literal("")).default(""),
  displayOrder: z.coerce.number().int().min(0).max(9999).optional().default(0),
  isActive: z.boolean().optional().default(true),
  isPaidPromotion: z.boolean().optional().default(false),
  sponsorName: z.string().trim().max(120).optional().default(""),
  startDate: z.string().trim().optional().or(z.literal("")).default(""),
  endDate: z.string().trim().optional().or(z.literal("")).default(""),
});

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function setSecurityHeaders(res: NextApiResponse, requestId: string) {
  res.setHeader("X-Request-Id", requestId);
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "DENY");
  res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, private");
  res.setHeader("Pragma", "no-cache");
  res.setHeader("Expires", "0");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  res.setHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains; preload");
}

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers["x-forwarded-for"];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || "").split(",")[0]?.trim() || req.socket?.remoteAddress || "0.0.0.0";
}

function getUserAgent(req: NextApiRequest): string {
  return String(req.headers["user-agent"] || "").slice(0, 200);
}

function requireActiveAdminOrThrow(user: any) {
  if (!user) {
    const err: any = new Error("User not found");
    err.statusCode = 401;
    err.code = "USER_NOT_FOUND";
    throw err;
  }

  const role = String(user.role || "user").toLowerCase();
  if (!["admin", "superadmin", "moderator"].includes(role)) {
    const err: any = new Error("Admin access required");
    err.statusCode = 403;
    err.code = "ADMIN_REQUIRED";
    throw err;
  }
}

function toDateOrNull(value?: string): Date | null {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function configureCloudinary() {
  const cloudName = process.env.CLOUDINARY_CLOUD_NAME;

  const apiKey = process.env.CLOUDINARY_API_KEY;
  const apiSecret = process.env.CLOUDINARY_API_SECRET;

  if (!cloudName || !apiKey || !apiSecret) {
    return false;
  }

  cloudinary.config({
    cloud_name: cloudName,
    api_key: apiKey,
    api_secret: apiSecret,
    secure: true,
  });

  return true;
}

function extractPublicIdFromCloudinaryUrl(url?: string | null): string {
  if (!url) return "";

  try {
    const parsed = new URL(url);
    const uploadIndex = parsed.pathname.indexOf("/upload/");
    if (uploadIndex === -1) return "";

    let publicPath = parsed.pathname.slice(uploadIndex + "/upload/".length);

    // Remove version prefix like v123456789/
    publicPath = publicPath.replace(/^v\d+\//, "");

    // Remove file extension
    publicPath = publicPath.replace(/\.[^.\/]+$/, "");

    return publicPath.replace(/^\/+/, "");
  } catch {
    return "";
  }
}

async function deleteCloudinaryAsset(publicId?: string | null) {
  const id = String(publicId || "").trim();
  if (!id) return;

  if (!configureCloudinary()) {
    console.warn("Cloudinary not configured for deletion. Skipping asset:", id);
    return;
  }

  try {
    await cloudinary.uploader.destroy(id, {
      resource_type: "image",
      invalidate: true,
    });
  } catch (error) {
    console.error("Failed to delete Cloudinary asset:", { publicId: id, error });
  }
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  if (!["GET", "PUT", "DELETE", "PATCH"].includes(req.method || "")) {
    res.setHeader("Allow", ["GET", "PUT", "PATCH", "DELETE"]);
    return res.status(405).json({
      success: false,
      message: "Method not allowed",
      requestId,
    });
  }

  const ip = getClientIp(req);
  const ua = getUserAgent(req);
  const { id } = req.query;

  if (typeof id !== "string" || !mongoose.Types.ObjectId.isValid(id)) {
    return res.status(400).json({
      success: false,
      message: "Invalid banner ID",
      code: "INVALID_ID",
      requestId,
    });
  }

  try {
    await dbConnect();

    const rl = await rateLimitAdmin(req);
    if (!rl.ok) {
      res.setHeader("Retry-After", String(rl.retryAfter || 60));
      return res.status(429).json({
        success: false,
        message: "Too many requests. Please slow down.",
        code: "RATE_LIMITED",
        requestId,
      });
    }

    const auth = await requireAuth(req, res);
    if (!auth) return;

    const admin: any = await User.findById(auth.id)
      .select("role permissions status isDeleted")
      .lean()
      .maxTimeMS(MAX_TIME_MS);

    requireActiveAdminOrThrow(admin);

    if (!checkPermission(admin, "system_manage_settings")) {
      SecurityEvent.create({
        eventType: "permission_denied",
        userId: auth.id,
        metadata: {
          endpoint: `/api/admin/hero-banners/${id}`,
          permission: "system_manage_settings",
          method: req.method,
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "warning",
      }).catch(console.error);

      return res.status(403).json({
        success: false,
        message: "Permission denied",
        code: "PERMISSION_DENIED",
        requestId,
      });
    }

    const existingBanner = await HeroBanner.findById(id).maxTimeMS(MAX_TIME_MS);
    if (!existingBanner) {
      return res.status(404).json({
        success: false,
        message: "Hero banner not found",
        code: "NOT_FOUND",
        requestId,
      });
    }

    if (req.method === "GET") {
      const includeDeleted =
        String(req.query.includeDeleted || "").toLowerCase() === "true";

      if (existingBanner.isDeleted && !includeDeleted) {
        return res.status(404).json({
          success: false,
          message: "Hero banner not found",
          code: "NOT_FOUND",
          requestId,
        });
      }

      return res.status(200).json({
        success: true,
        banner: existingBanner,
        requestId,
      });
    }

    if (req.method === "PATCH") {
      const action = String(req.query.action || req.body?.action || "").toLowerCase();

      if (action === "restore") {
        existingBanner.isDeleted = false;
        existingBanner.deletedAt = null;
        existingBanner.deletedBy = null;
        existingBanner.isActive = true;
        existingBanner.updatedBy = new mongoose.Types.ObjectId(auth.id);
        await existingBanner.save();

        SecurityEvent.create({
          eventType: "admin_action",
          userId: auth.id,
          metadata: {
            action: "restore_hero_banner",
            bannerId: existingBanner._id.toString(),
            title: existingBanner.title,
          },
          ipAddress: ip,
          userAgent: ua,
          severity: "info",
        }).catch(console.error);

        return res.status(200).json({
          success: true,
          message: "Hero banner restored successfully",
          banner: existingBanner,
          requestId,
        });
      }

      if (existingBanner.isDeleted) {
        return res.status(400).json({
          success: false,
          message: "Restore the hero banner from trash before changing its status",
          code: "BANNER_IN_TRASH",
          requestId,
        });
      }

      const nextActiveState = !existingBanner.isActive;
      existingBanner.isActive = nextActiveState;
      existingBanner.updatedBy = new mongoose.Types.ObjectId(auth.id);
      await existingBanner.save();

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: {
          action: "toggle_hero_banner_status",
          bannerId: existingBanner._id.toString(),
          isActive: nextActiveState,
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "info",
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: `Hero banner ${nextActiveState ? "activated" : "deactivated"} successfully`,
        banner: existingBanner,
        requestId,
      });
    }

    if (req.method === "PUT") {
      const bodyParse = UpdateHeroBannerSchema.safeParse(req.body);
      if (!bodyParse.success) {
        return res.status(400).json({
          success: false,
          message: "Invalid request body",
          code: "VALIDATION_ERROR",
          errors: bodyParse.error.flatten().fieldErrors,
          requestId,
        });
      }

      const payload = bodyParse.data;

      if (existingBanner.isDeleted) {
        return res.status(400).json({
          success: false,
          message: "Restore the hero banner from trash before editing it",
          code: "BANNER_IN_TRASH",
          requestId,
        });
      }

      const startDate = toDateOrNull(payload.startDate);
      const endDate = toDateOrNull(payload.endDate);

      const previousImagePublicId =
        existingBanner.imagePublicId ||
        extractPublicIdFromCloudinaryUrl(existingBanner.imageUrl);

      const previousMobileImagePublicId =
        existingBanner.mobileImagePublicId ||
        extractPublicIdFromCloudinaryUrl(existingBanner.mobileImageUrl);

      const nextImagePublicId =
        payload.imagePublicId ||
        extractPublicIdFromCloudinaryUrl(payload.imageUrl);

      const nextMobileImagePublicId =
        payload.mobileImagePublicId ||
        extractPublicIdFromCloudinaryUrl(payload.mobileImageUrl);

      if (payload.startDate && !startDate) {
        return res.status(400).json({
          success: false,
          message: "Invalid start date",
          code: "INVALID_START_DATE",
          requestId,
        });
      }

      if (payload.endDate && !endDate) {
        return res.status(400).json({
          success: false,
          message: "Invalid end date",
          code: "INVALID_END_DATE",
          requestId,
        });
      }

      if (startDate && endDate && startDate > endDate) {
        return res.status(400).json({
          success: false,
          message: "End date must be after start date",
          code: "INVALID_DATE_RANGE",
          requestId,
        });
      }

      existingBanner.title = payload.title;
      existingBanner.subtitle = payload.subtitle;
      existingBanner.imageUrl = payload.imageUrl;
      existingBanner.imagePublicId = nextImagePublicId;
      existingBanner.mobileImageUrl = payload.mobileImageUrl;
      existingBanner.mobileImagePublicId = nextMobileImagePublicId;
      existingBanner.ctaText = payload.ctaText;
      existingBanner.ctaLink = payload.ctaLink;
      existingBanner.targetType = payload.targetType;
      existingBanner.targetId = payload.targetId
        ? new mongoose.Types.ObjectId(payload.targetId)
        : undefined;
      existingBanner.displayOrder = payload.displayOrder;
      existingBanner.isActive = payload.isActive;
      existingBanner.isPaidPromotion = payload.isPaidPromotion;
      existingBanner.sponsorName = payload.sponsorName;
      existingBanner.startDate = startDate;
      existingBanner.endDate = endDate;
      existingBanner.updatedBy = new mongoose.Types.ObjectId(auth.id);

      await existingBanner.save();

      const stalePublicIds = Array.from(
        new Set(
          [
            previousImagePublicId &&
            previousImagePublicId !== nextImagePublicId
              ? previousImagePublicId
              : "",
            previousMobileImagePublicId &&
            previousMobileImagePublicId !== nextMobileImagePublicId
              ? previousMobileImagePublicId
              : "",
          ].filter(Boolean)
        )
      );

      await Promise.all(stalePublicIds.map((publicId) => deleteCloudinaryAsset(publicId)));

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: {
          action: "update_hero_banner",
          bannerId: existingBanner._id.toString(),
          title: existingBanner.title,
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "info",
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: "Hero banner updated successfully",
        banner: existingBanner,
        requestId,
      });
    }

    const permanentDelete =
      String(req.query.permanent || req.body?.permanent || "").toLowerCase() === "true";

    if (!permanentDelete) {
      if (existingBanner.isDeleted) {
        return res.status(200).json({
          success: true,
          message: "Hero banner is already in trash",
          banner: existingBanner,
          requestId,
        });
      }

      existingBanner.isDeleted = true;
      existingBanner.deletedAt = new Date();
      existingBanner.deletedBy = new mongoose.Types.ObjectId(auth.id);
      existingBanner.isActive = false;
      existingBanner.updatedBy = new mongoose.Types.ObjectId(auth.id);
      await existingBanner.save();

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: {
          action: "trash_hero_banner",
          bannerId: existingBanner._id.toString(),
          title: existingBanner.title,
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "warning",
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        message: "Hero banner moved to trash successfully",
        banner: existingBanner,
        requestId,
      });
    }

    const imageIdsToDelete = Array.from(
      new Set(
        [
          existingBanner.imagePublicId ||
            extractPublicIdFromCloudinaryUrl(existingBanner.imageUrl),
          existingBanner.mobileImagePublicId ||
            extractPublicIdFromCloudinaryUrl(existingBanner.mobileImageUrl),
        ].filter(Boolean)
      )
    );

    await HeroBanner.deleteOne({ _id: existingBanner._id }).maxTimeMS(MAX_TIME_MS);

    void Promise.allSettled(
      imageIdsToDelete.map((publicId) => deleteCloudinaryAsset(publicId))
    ).then((results) => {
      const rejectedCount = results.filter(
        (result) => result.status === "rejected"
      ).length;

      if (rejectedCount > 0) {
        console.warn("Cloudinary cleanup finished with errors", {
          requestId,
          bannerId: existingBanner._id.toString(),
          rejectedCount,
        });
      }
    });

    SecurityEvent.create({
      eventType: "admin_action",
      userId: auth.id,
      metadata: {
        action: "permanent_delete_hero_banner",
        bannerId: existingBanner._id.toString(),
        title: existingBanner.title,
      },
      ipAddress: ip,
      userAgent: ua,
      severity: "warning",
    }).catch(console.error);

    return res.status(200).json({
      success: true,
      message: "Hero banner permanently deleted successfully",
      requestId,
    });
  } catch (error: any) {
    console.error("Admin Hero Banner Detail Error:", { requestId, error: error?.message });

    SecurityEvent.create({
      eventType: "system_error",
      userId: null,
      metadata: {
        endpoint: `/api/admin/hero-banners/${id}`,
        errorCode: error?.code || "UNKNOWN",
      },
      ipAddress: ip,
      userAgent: ua,
      severity: "error",
    }).catch(console.error);

    if (error?.statusCode && error?.code) {
      return res.status(error.statusCode).json({
        success: false,
        message: error.message,
        code: error.code,
        requestId,
      });
    }

    return res.status(500).json({
      success: false,
      message: "Internal server error",
      code: "SERVER_ERROR",
      requestId,
    });
  }
}

