            endpoint: "/api/admin/hero-banners",
            permission: "system_manage_settings",
            action: "view_hero_banners",
          },
          ipAddress: ip,
          userAgent: ua,
          severity: "warning",
        }).catch(console.error);

        return res.status(403).json({
          success: false,
          message: "Permission denied",
          code: "PERMISSION_DENIED",
          requestId,
        });
      }

      const parseResult = QuerySchema.safeParse(req.query);
      if (!parseResult.success) {
        return res.status(400).json({
          success: false,
          message: "Invalid query parameters",
          code: "VALIDATION_ERROR",
          errors: parseResult.error.flatten().fieldErrors,
          requestId,
        });
      }

      const { page, limit, status, paid, search } = parseResult.data;
      const skip = (page - 1) * limit;

      const query: any = {};

      if (status === "trash") {
        query.isDeleted = true;
      } else {
        query.isDeleted = false;

        if (status === "active") query.isActive = true;
        if (status === "inactive") query.isActive = false;
      }

      if (paid === "true") query.isPaidPromotion = true;
      if (paid === "false") query.isPaidPromotion = false;

      if (search && search.trim().length >= 2) {
        const safeSearch = escapeRegex(search);
        if (safeSearch) {
          const regex = { $regex: safeSearch, $options: "i" };
          query.$or = [
            { title: regex },
            { subtitle: regex },
            { sponsorName: regex },
            { ctaText: regex },
          ];
        }
      }

      const [banners, total] = await Promise.all([
        HeroBanner.find(query)
          .sort({ displayOrder: 1, createdAt: -1 })
          .skip(skip)
          .limit(limit)
          .lean()
          .maxTimeMS(MAX_TIME_MS),
        HeroBanner.countDocuments(query).maxTimeMS(MAX_TIME_MS),
      ]);

      SecurityEvent.create({
        eventType: "admin_action",
        userId: auth.id,
        metadata: {
          action: "list_hero_banners",
          hasSearch: Boolean(search),
          resultCount: banners.length,
          page,
          filters: {
            status,
            paid,
          },
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "info",
      }).catch(console.error);

      return res.status(200).json({
        success: true,
        banners,
        pagination: {
          page,
          limit,
          total,
          pages: Math.ceil(total / limit),
        },
        requestId,
      });
    }

    if (!checkPermission(admin, "system_manage_settings")) {
      SecurityEvent.create({
        eventType: "permission_denied",
        userId: auth.id,
        metadata: {
          endpoint: "/api/admin/hero-banners",
          permission: "system_manage_settings",
          action: "create_hero_banner",
        },
        ipAddress: ip,
        userAgent: ua,
        severity: "warning",
      }).catch(console.error);

      return res.status(403).json({
        success: false,
        message: "Permission denied",
        code: "PERMISSION_DENIED",
        requestId,
      });
    }

    const bodyParse = CreateHeroBannerSchema.safeParse(req.body);
    if (!bodyParse.success) {
      return res.status(400).json({
        success: false,
        message: "Invalid request body",
        code: "VALIDATION_ERROR",
        errors: bodyParse.error.flatten().fieldErrors,
        requestId,
      });
    }

    const payload = bodyParse.data;
    const startDate = toDateOrNull(payload.startDate);
    const endDate = toDateOrNull(payload.endDate);

    if (payload.startDate && !startDate) {
      return res.status(400).json({
        success: false,
        message: "Invalid start date",
        code: "INVALID_START_DATE",
        requestId,
      });
    }

    if (payload.endDate && !endDate) {
      return res.status(400).json({
        success: false,
        message: "Invalid end date",
        code: "INVALID_END_DATE",
        requestId,
      });
    }

    if (startDate && endDate && startDate > endDate) {
      return res.status(400).json({
        success: false,
        message: "End date must be after start date",
        code: "INVALID_DATE_RANGE",
        requestId,
      });
    }

    const banner = await HeroBanner.create({
      title: payload.title,
      subtitle: payload.subtitle,
      imageUrl: payload.imageUrl,
      imagePublicId: payload.imagePublicId || "",
      mobileImageUrl: payload.mobileImageUrl,
      mobileImagePublicId: payload.mobileImagePublicId || "",
      ctaText: payload.ctaText,
      ctaLink: payload.ctaLink,
      targetType: payload.targetType,
      targetId: payload.targetId || null,
      displayOrder: payload.displayOrder,
      isActive: payload.isActive,
      isPaidPromotion: payload.isPaidPromotion,
      sponsorName: payload.sponsorName,
      startDate,
      endDate,
      impressions: 0,
      clicks: 0,
      createdBy: auth.id,
      updatedBy: auth.id,
    });

    SecurityEvent.create({
      eventType: "admin_action",
      userId: auth.id,
      metadata: {
        action: "create_hero_banner",
        bannerId: banner._id?.toString(),
        title: banner.title,
        isPaidPromotion: banner.isPaidPromotion,
        isActive: banner.isActive,
      },
      ipAddress: ip,
      userAgent: ua,
      severity: "info",
    }).catch(console.error);

    return res.status(201).json({
      success: true,
      message: "Hero banner created successfully",
      banner,
      requestId,
    });
  } catch (error: any) {
    console.error("Admin Hero Banners Error:", { requestId, error: error?.message });

    SecurityEvent.create({
      eventType: "system_error",
      userId: null,
      metadata: {
        endpoint: "/api/admin/hero-banners",
        errorCode: error?.code || "UNKNOWN",
      },
      ipAddress: ip,
      userAgent: ua,
      severity: "error",
    }).catch(console.error);

    if (error?.statusCode && error?.code) {
      return res.status(error.statusCode).json({
        success: false,
        message: error.message,
        code: error.code,
        requestId,
      });
    }

    return res.status(500).json({
      success: false,
      message: "Internal server error",
      code: "SERVER_ERROR",
      requestId,
    });
  }
}

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Media from '@/models/Media';
import cloudinary from '@/lib/cloudinary';
import mongoose from 'mongoose';
import { requireAdmin } from '@/lib/requireAuth';

type MediaResponse = {
  success: boolean;
  message: string;
  media?: any;
  error?: string;
};

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<MediaResponse>
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  const { id } = req.query;

  // Validate ID
  if (!id || !mongoose.Types.ObjectId.isValid(id as string)) {
    return res.status(400).json({ success: false, message: 'Invalid media ID' });
  }

  await dbConnect();

  // GET - Get single media
  if (req.method === 'GET') {
    try {
      const media = await Media.findById(id).populate('uploadedBy', 'name email');

      if (!media) {
        return res.status(404).json({ success: false, message: 'Media not found' });
      }

      return res.status(200).json({ success: true, message: 'Media found', media });
    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Error fetching media',
        error: error.message,
      });
    }
  }

  // PUT - Update media (alt, caption)
  if (req.method === 'PUT') {
    try {
      const { alt, caption } = req.body;

      const media = await Media.findByIdAndUpdate(
        id,
        { alt, caption },
        { new: true, runValidators: true }
      );

      if (!media) {
        return res.status(404).json({ success: false, message: 'Media not found' });
      }

      return res.status(200).json({
        success: true,
        message: 'Media updated successfully',
        media,
      });
    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Error updating media',
        error: error.message,
      });
    }
  }

  // DELETE - Soft delete or permanent delete
  if (req.method === 'DELETE') {
    try {
      const { permanent = 'false' } = req.query;

      const media = await Media.findById(id);

      if (!media) {
        return res.status(404).json({ success: false, message: 'Media not found' });
      }

      if (permanent === 'true') {
        // Permanent delete - also delete from Cloudinary
        try {
          await cloudinary.uploader.destroy(media.publicId, {
            resource_type: media.resourceType,
          });
        } catch (cloudinaryError) {
          console.error('Cloudinary delete error:', cloudinaryError);
          // Continue even if Cloudinary delete fails
        }

        await Media.findByIdAndDelete(id);

        return res.status(200).json({
          success: true,
          message: 'Media permanently deleted',
        });
      } else {
        // Soft delete
        media.isDeleted = true;
        media.deletedAt = new Date();
        await media.save();

        return res.status(200).json({
          success: true,
          message: 'Media moved to trash',
          media,
        });
      }
    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Error deleting media',
        error: error.message,
      });
    }
  }

  // PATCH - Restore from trash
  if (req.method === 'PATCH') {
    try {
      const { action } = req.body;

      if (action === 'restore') {
        const media = await Media.findByIdAndUpdate(
          id,
          { isDeleted: false, deletedAt: null },
          { new: true }
        );

        if (!media) {
          return res.status(404).json({ success: false, message: 'Media not found' });
        }

        return res.status(200).json({
          success: true,
          message: 'Media restored successfully',
          media,
        });
      }

      return res.status(400).json({ success: false, message: 'Invalid action' });
    } catch (error: any) {
      return res.status(500).json({
        success: false,
        message: 'Error restoring media',
        error: error.message,
      });
    }
  }

  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Media from '@/models/Media';
import { requireAdmin } from '@/lib/requireAuth';

type MediaListResponse = {
  success: boolean;
  message?: string;
  media?: any[];
  pagination?: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
  counts?: {
    all: number;
    images: number;
    documents: number;
    trash: number;
  };
  error?: string;
};

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<MediaListResponse>
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  if (req.method !== 'GET') {
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  try {
    await dbConnect();

    const {
      page = '1',
      limit = '24',
      folder,
      type,        // 'image', 'document', 'all'
      search,
      deleted = 'false',
      sortBy = 'createdAt',
      sortOrder = 'desc',
    } = req.query;

    const pageNum = parseInt(page as string);
    const limitNum = parseInt(limit as string);
    const skip = (pageNum - 1) * limitNum;

    // Build query
    const query: any = {};

    // Deleted filter
    if (deleted === 'true') {
      query.isDeleted = true;
    } else {
      query.isDeleted = { $ne: true };
    }

    // Folder filter
    if (folder && folder !== 'all') {
      query.folder = folder;
    }

    // Type filter
    if (type === 'image') {
      query.resourceType = 'image';
    } else if (type === 'document') {
      query.resourceType = 'raw';
    }

    // Search
    if (search) {
      query.$or = [
        { originalName: { $regex: search, $options: 'i' } },
        { alt: { $regex: search, $options: 'i' } },
        { caption: { $regex: search, $options: 'i' } },
      ];
    }

    // Sort
    const sortOptions: any = {};
    sortOptions[sortBy as string] = sortOrder === 'asc' ? 1 : -1;

    // Execute query
    const [media, total] = await Promise.all([
      Media.find(query)
        .sort(sortOptions)
        .skip(skip)
        .limit(limitNum)
        .populate('uploadedBy', 'name email')
        .lean(),
      Media.countDocuments(query),
    ]);

    // Get counts
    const [allCount, imagesCount, documentsCount, trashCount] = await Promise.all([
      Media.countDocuments({ isDeleted: { $ne: true } }),
      Media.countDocuments({ isDeleted: { $ne: true }, resourceType: 'image' }),
      Media.countDocuments({ isDeleted: { $ne: true }, resourceType: 'raw' }),
      Media.countDocuments({ isDeleted: true }),
    ]);

    return res.status(200).json({
      success: true,
      media,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        totalPages: Math.ceil(total / limitNum),
      },
      counts: {
        all: allCount,
        images: imagesCount,
        documents: documentsCount,
        trash: trashCount,
      },
    });
  } catch (error: any) {
    console.error('Error fetching media:', error);
    return res.status(500).json({
      success: false,
      message: 'Error fetching media',
      error: error.message,
    });
  }
}

// pages/api/admin/moderation/developer-heat.ts
import type { NextApiRequest, NextApiResponse } from "next";
import Property from "@/models/Property";
import { requireAdmin } from "@/lib/requireAdmin";
import { computePropertyRisk } from "@/lib/riskEngine";
import { getCachedHeat, setCachedHeat } from "@/lib/riskCache";

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    await requireAdmin(req, res);

    // ✅ Cache first (15 min)
    const heatKey = "developerHeat:30d";
    const cachedHeat = getCachedHeat<any[]>(heatKey);
    if (cachedHeat) {
      return res.status(200).json({
        ok: true,
        sinceDays: 30,
        results: cachedHeat,
        cached: true,
      });
    }

    const since30 = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

    // ✅ Recent non-deleted properties
    const properties = await Property.find({
      createdAt: { $gte: since30 },
      $or: [{ isDeleted: { $ne: true } }, { isDeleted: { $exists: false } }],
    })
      .select("_id createdBy userId ownerId developerId isFlagged status isHidden")
      .lean();

    // Group by developer
    const buckets = new Map<
      string,
      { developerId: string; propertyIds: string[]; flaggedOrHiddenCount: number }
    >();

    for (const p of properties as any[]) {
      const developerId =
        p.createdBy?.toString?.() ||
        p.userId?.toString?.() ||
        p.ownerId?.toString?.() ||
        p.developerId?.toString?.();

      if (!developerId) continue;

      if (!buckets.has(developerId)) {
        buckets.set(developerId, {
          developerId,
          propertyIds: [],
          flaggedOrHiddenCount: 0,
        });
      }

      const b = buckets.get(developerId)!;
      b.propertyIds.push(String(p._id));

      const hidden = p.status === "hidden" || p.isHidden === true;
      if (p.isFlagged || hidden) b.flaggedOrHiddenCount += 1;
    }

    const results: any[] = [];

    for (const b of buckets.values()) {
      // Performance safety: cap per developer scoring
      const sample = b.propertyIds.slice(0, 30);

      const risks = await Promise.all(
        sample.map((pid) => computePropertyRisk(pid, b.developerId).catch(() => null))
      );

      const valid = risks.filter(Boolean) as any[];

      const avgRisk = valid.length
        ? valid.reduce((sum, r) => sum + Number(r.score || 0), 0) / valid.length
        : 0;

      const maxRisk = valid.length ? Math.max(...valid.map((r) => Number(r.score || 0))) : 0;

      results.push({
        developerId: b.developerId,
        properties30d: b.propertyIds.length,
        flaggedOrHidden30d: b.flaggedOrHiddenCount,
        avgRisk: Math.round(avgRisk * 10) / 10,
        maxRisk: Math.round(maxRisk * 10) / 10,
        // ✅ Future rule (admin review): threshold indicator only
        suggestedSuspension: b.flaggedOrHiddenCount >= 3,
      });
    }

    // Worst first
    results.sort(
      (a, b) => b.avgRisk - a.avgRisk || b.flaggedOrHidden30d - a.flaggedOrHidden30d
    );

    // ✅ Save cache
    setCachedHeat(heatKey, results, 15 * 60 * 1000);

    return res.status(200).json({
      ok: true,
      sinceDays: 30,
      results,
      cached: false,
    });
  } catch (err) {
    console.error("developer heat error", err);
    return res.status(500).json({ ok: false, error: "Server error" });
  }
}

// pages/api/admin/moderation/flagged.ts
import type { NextApiRequest, NextApiResponse } from "next";
import mongoose from "mongoose";
import Property from "@/models/Property";
import { requireAdmin } from "@/lib/requireAdmin";
import { computePropertyRisk } from "@/lib/riskEngine";
import { getCachedRisk, setCachedRisk } from "@/lib/riskCache";


export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    await requireAdmin(req, res);

    const { filter = "both", page = "1", limit = "20" } = req.query;

    const pageNum = Math.max(1, parseInt(String(page), 10) || 1);
    const limitNum = Math.min(100, Math.max(5, parseInt(String(limit), 10) || 20));
    const skip = (pageNum - 1) * limitNum;

    const query: any = {
      // Respect soft delete architecture: show flagged/hidden even if not deleted,
      // but never show deleted unless you intentionally want it in this queue.
      $and: [{ $or: [{ isDeleted: { $ne: true } }, { isDeleted: { $exists: false } }] }],
    };

    if (filter === "flagged") query.isFlagged = true;
    if (filter === "hidden") {
      // if your project uses status or isHidden; we support both
      query.$or = [{ status: "hidden" }, { isHidden: true }];
    }
    if (filter === "both") {
      query.$or = [{ isFlagged: true }, { status: "hidden" }, { isHidden: true }];
    }

    const [total, properties] = await Promise.all([
      Property.countDocuments(query),
      Property.find(query)
        .sort({ flaggedAt: -1, updatedAt: -1, createdAt: -1 })
        .skip(skip)
        .limit(limitNum)
        .lean(),
    ]);

    const items = await Promise.all(
      properties.map(async (p: any) => {
        const developerId =
          p.createdBy?.toString?.() ||
          p.userId?.toString?.() ||
          p.ownerId?.toString?.() ||
          p.developerId?.toString?.() ||
          null;

        const cacheKey = `risk:${String(p._id)}:${developerId || "na"}`;
const cached = getCachedRisk<any>(cacheKey);

const risk = cached
  ? cached
  : await computePropertyRisk(String(p._id), developerId);

if (!cached) setCachedRisk(cacheKey, risk, 10 * 60 * 1000);


        return {
          ...p,
          riskScore: risk.score,
          riskLevel: risk.level,
          uniqueIpCount24h: risk.breakdown.uniqueIpCount24h,
          reportsTotal: risk.breakdown.totalReports,
        };
      })
    );

    return res.status(200).json({
      ok: true,
      filter,
      page: pageNum,
      limit: limitNum,
      total,
      totalPages: Math.ceil(total / limitNum),
      items,
    });
  } catch (err: any) {
    console.error("admin moderation flagged error", err);
    return res.status(500).json({ ok: false, error: "Server error" });
  }
}

import type { NextApiRequest, NextApiResponse } from "next";
import crypto from "crypto";
import mongoose from "mongoose";
import dbConnect from "@/lib/dbConnect";
import Property from "@/models/Property";
import AdminAuditLog from "@/models/AdminAuditLog";
import { requireAdmin } from "@/lib/requireAdmin";
import { requireServerSecret } from "@/lib/security/serverSecrets";

type Ok = { ok: true; message: string };
type Err = { ok: false; error: string };

function safeText(v: unknown): string {
  if (typeof v !== "string") return "";
  return v.trim();
}

function hashIp(ip: string) {
  const salt = requireServerSecret(["REPORT_IP_SALT", "NEXTAUTH_SECRET"], "Report IP hash secret");
  return crypto.createHash("sha256").update(`${salt}:${ip}`).digest("hex");
}

export default async function handler(req: NextApiRequest, res: NextApiResponse<Ok | Err>) {
  if (req.method !== "POST") {
    res.setHeader("Allow", "POST");
    return res.status(405).json({ ok: false, error: "Method not allowed" });
  }

  const token = await requireAdmin(req, res);
  if (!token) return;

  try {
    await dbConnect();

    const propertyId = safeText(req.body?.propertyId);
    const note = safeText(req.body?.note);

    if (!propertyId || !mongoose.Types.ObjectId.isValid(propertyId)) {
      return res.status(400).json({ ok: false, error: "Invalid propertyId" });
    }

    const prop = await Property.findById(propertyId).select({ _id: 1, isDeleted: 1, isFlagged: 1 }).lean();
    if (!prop) return res.status(404).json({ ok: false, error: "Property not found" });

    // Restore = undo hide, keep flag optional (we will unflag too for clean slate)
    await Property.updateOne(
      { _id: propertyId },
      {
        $set: {
          isDeleted: false,
          deletedAt: null,
          isFlagged: false,
          flagReason: null,
          flaggedAt: null,
        },
      }
    );

    const ip = (req.headers["x-forwarded-for"] as string)?.split(",")?.[0]?.trim() || req.socket.remoteAddress || "";
    const ipHash = ip ? hashIp(ip) : undefined;

    await AdminAuditLog.create({
      action: "PROPERTY_RESTORE",
      entityType: "property",
      entityId: new mongoose.Types.ObjectId(propertyId),
      adminId: token.id ? new mongoose.Types.ObjectId(token.id) : undefined,
      adminEmail: (token as any)?.email || undefined,
      meta: { note: note || undefined },
      ipHash: ipHash || undefined,
      userAgent: safeText(req.headers["user-agent"]),
    });

    return res.status(200).json({ ok: true, message: "Property restored successfully." });
  } catch (e: any) {
    return res.status(500).json({ ok: false, error: "Server error" });
  }
}

import type { NextApiRequest, NextApiResponse } from "next";
import mongoose from "mongoose";
import crypto from "crypto";
import dbConnect from "@/lib/dbConnect";
import Property from "@/models/Property";
import AdminAuditLog from "@/models/AdminAuditLog";
import { requireAdmin } from "@/lib/requireAdmin";
import { requireServerSecret } from "@/lib/security/serverSecrets";

type Ok = { ok: true; message: string };
type Err = { ok: false; error: string };

function safeText(v: unknown): string {
  if (typeof v !== "string") return "";
  return v.trim();
}

function hashIp(ip: string) {
  const salt = requireServerSecret(["REPORT_IP_SALT", "NEXTAUTH_SECRET"], "Report IP hash secret");
  return crypto.createHash("sha256").update(`${salt}:${ip}`).digest("hex");
}

export default async function handler(req: NextApiRequest, res: NextApiResponse<Ok | Err>) {
  if (req.method !== "POST") {
    res.setHeader("Allow", "POST");
    return res.status(405).json({ ok: false, error: "Method not allowed" });
  }

  const token = await requireAdmin(req, res);
  if (!token) return;

  try {
    await dbConnect();

    const propertyId = safeText(req.body?.propertyId);
    const action = safeText(req.body?.action); 
    const reason = safeText(req.body?.reason);

    if (!propertyId || !mongoose.Types.ObjectId.isValid(propertyId)) {
      return res.status(400).json({ ok: false, error: "Invalid propertyId" });
    }

    const prop = await Property.findById(propertyId).lean();
    if (!prop) {
      return res.status(404).json({ ok: false, error: "Property not found" });
    }

    let update: any = {};
    let auditAction = "";

    switch (action) {
      case "flag":
        update = {
          isFlagged: true,
          flagReason: reason || "Manually flagged by admin",
          flaggedAt: new Date(),
        };
        auditAction = "PROPERTY_FLAG_MANUAL";
        break;

      case "unflag":
        update = {
          isFlagged: false,
          flagReason: null,
          flaggedAt: null,
        };
        auditAction = "PROPERTY_UNFLAG_MANUAL";
        break;

      case "hide":
        update = {
          isDeleted: true,
          deletedAt: new Date(),
          isFlagged: true,
          flagReason: reason || "Manually hidden by admin",
          flaggedAt: new Date(),
        };
        auditAction = "PROPERTY_HIDE_MANUAL";
        break;

      case "restore":
        update = {
          isDeleted: false,
          deletedAt: null,
        };
        auditAction = "PROPERTY_RESTORE_MANUAL";
        break;

      default:
        return res.status(400).json({ ok: false, error: "Invalid action" });
    }

    await Property.updateOne({ _id: propertyId }, { $set: update });

    const ip = (req.headers["x-forwarded-for"] as string)?.split(",")?.[0]?.trim() || req.socket.remoteAddress || "";
    const ipHash = ip ? hashIp(ip) : undefined;

    await AdminAuditLog.create({
      action: auditAction,
      entityType: "property",
      entityId: new mongoose.Types.ObjectId(propertyId),
      adminId: token.id ? new mongoose.Types.ObjectId(token.id) : undefined,
      adminEmail: (token as any)?.email || undefined,
      meta: { reason: reason || undefined },
      ipHash: ipHash || undefined,
      userAgent: safeText(req.headers["user-agent"]),
    });

    return res.status(200).json({ ok: true, message: "Property updated successfully." });

  } catch (e) {
    return res.status(500).json({ ok: false, error: "Server error" });
  }
}

// pages/api/admin/owners/[ownerId]/index.ts
// ═══════════════════════════════════════════════════════════════
// ADMIN — GET OWNER DETAIL - Highrise.pk V6.6.0
// 🔒 Admin Only | Decrypts CNIC (audit-logged) | Full Profile
// ═══════════════════════════════════════════════════════════════
// Returns FULL profile including:
//   → Decrypted CNIC number (AUDIT LOGGED)
//   → Decrypted phone number
//   → All documents with URLs
//   → Full audit trail
//   → Linked User details
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from "next";
import { Types } from "mongoose";
import crypto from "crypto";

import dbConnect from "@/lib/dbConnect";
import { requireAdmin } from "@/lib/requireAdmin";
import { rateLimitAdmin, setRateLimitHeaders, sendRateLimitResponse } from "@/lib/rateLimit";
import { logSecurityEvent } from "@/lib/security/logSecurityEvent";

import OwnerProfile from "@/models/OwnerProfile";
import User from "@/models/User";

// ═══════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════

interface ApiResponse {
  success: boolean;
  message: string;
  requestId: string;
  data?: unknown;
}

// ═══════════════════════════════════════════════════════════════
// SECURITY HEADERS
// ═══════════════════════════════════════════════════════════════

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader("X-Request-Id", requestId);
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("Cache-Control", "no-store, max-age=0");
}

// ═══════════════════════════════════════════════════════════════
// MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
): Promise<void> {
  const requestId =
    typeof req.headers["x-correlation-id"] === "string"
      ? req.headers["x-correlation-id"]
      : crypto.randomUUID();

  setSecurityHeaders(res, requestId);

  // ── Method guard ─────────────────────────────────────────────
  if (req.method !== "GET") {
    res.setHeader("Allow", "GET");
    return void res.status(405).json({
      success: false,
      message: "Method not allowed",
      requestId,
    });
  }

  // ── Rate limiting ────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) {
    return sendRateLimitResponse(res, rl);
  }

  // ── Admin auth ───────────────────────────────────────────────
  const admin = await requireAdmin(req, res);
  if (!admin) return;

  // ── Validate [ownerId] param ─────────────────────────────────
  const { ownerId } = req.query;
  const id = typeof ownerId === "string" ? ownerId : "";
  if (!id || !Types.ObjectId.isValid(id)) {
    return void res.status(400).json({
      success: false,
      message: "Invalid owner profile ID",
      requestId,
    });
  }

  try {
    await dbConnect();

    // Load profile WITH encrypted fields (need to decrypt)
    const profile = await OwnerProfile.findOne({
      _id: new Types.ObjectId(id),
      isDeleted: false,
    })
      .select("+cnicEncrypted +phoneEncrypted")
      .populate("user", "name email profilePictureUrl createdAt lastLoginAt status");

    if (!profile) {
      return void res.status(404).json({
        success: false,
        message: "Owner profile not found",
        requestId,
      });
    }

    // ── Log CNIC decryption (audit trail) ────────────────────────
    await logSecurityEvent({
      type: "admin_action",
      severity: "medium",
      userId: admin.id,
      req,
      metadata: {
        action: "owner_cnic_decrypted",
        profileId: id,
        reason: "Admin viewed owner verification detail",
      },
    });

    // ── Decrypt sensitive data ───────────────────────────────────
    const decryptedCnic = profile.getCNIC();
    const decryptedPhone = profile.getPhone();

    return void res.status(200).json({
      success: true,
      message: "Owner profile retrieved",
      requestId,
      data: {
        id: String(profile._id),
        slug: profile.slug,
        displayName: profile.displayName,
        about: profile.about,

        // Decrypted (admin only)
        cnic: decryptedCnic,
        maskedCnic: profile.getMaskedCNIC(),
        phone: decryptedPhone,
        maskedPhone: profile.getMaskedPhone(),
        email: profile.email,

        city: profile.city,
        address: profile.address,

        // Documents (full URLs for admin verification)
        documents: profile.documents,

        // Status
        status: profile.status,
        verificationLevel: profile.verificationLevel,
        cnicVerified: profile.cnicVerified,
        cnicVerifiedAt: profile.cnicVerifiedAt,
        cnicLockedAt: profile.cnicLockedAt,
        verifiedAt: profile.verifiedAt,
        verifiedBy: profile.verifiedBy,
        submittedForReviewAt: profile.submittedForReviewAt,

        // Rejection
        rejectionReason: profile.rejectionReason,
        rejectedAt: (profile as unknown as { rejectedAt?: Date }).rejectedAt ?? null,
        rejectedBy: (profile as unknown as { rejectedBy?: unknown }).rejectedBy ?? null,

        // Info Required
        infoRequiredReason: profile.infoRequiredReason,
        infoRequiredAt: (profile as unknown as { infoRequiredAt?: Date }).infoRequiredAt ?? null,

        // Suspension
        suspensionReason: profile.suspensionReason,
        suspendedAt: profile.suspendedAt,
        suspendedBy: profile.suspendedBy,

        // Ratings
        ratings: profile.ratings,

        // Audit trail (last 50)
        auditTrail: profile.auditTrail?.slice(-50) ?? [],

        // Metadata
        memberSince: profile.memberSince,
        lastActivityAt: profile.lastActivityAt,
        createdAt: profile.createdAt,
        updatedAt: profile.updatedAt,

        // Linked user (populated)
        user: profile.user,
      },
    });
  } catch (err: unknown) {
    console.error("[admin/owners/[ownerId]] Error:", err);

    await logSecurityEvent({
      type: "admin_action",
      severity: "high",
      userId: admin.id,
      req,
      metadata: {
        action: "owner_detail_fetch_error",
        profileId: id,
        error: err instanceof Error ? err.message : "Unknown",
      },
    }).catch(() => undefined);

    return void res.status(500).json({
      success: false,
      message: "Unable to fetch owner profile",
      requestId,
    });
  }
}

// pages/api/admin/recent-activity.ts

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';

import Property from '@/models/Property';
import Project from '@/models/Projects';
import DeveloperProfile from '@/models/DeveloperProfile';
import Lead from '@/models/Lead';
import User from '@/models/User';
import { requireAdmin } from '@/lib/requireAuth';

interface ActivityItem {
  id: string;
  type: 'property' | 'user' | 'developer' | 'inquiry' | 'project';
  title: string;
  description: string;
  time: string;
  status: 'pending' | 'approved' | 'new' | 'rejected';
  createdAt: Date;
}

type ApiResponse =
  | { success: true; activities: Omit<ActivityItem, 'createdAt'>[] }
  | { success: false; message: string; error?: string };

// Helper: Format time ago
const formatTimeAgo = (date: Date): string => {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);

  if (diffMins < 1) return 'Just now';
  if (diffMins < 60) return `${diffMins} min ago`;
  if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
  if (diffDays < 7) return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;
  return date.toLocaleDateString();
};

// Helper: Map status to activity status
const mapPropertyStatus = (status: string): ActivityItem['status'] => {
  if (status === 'approved') return 'approved';
  if (status === 'rejected') return 'rejected';
  if (status === 'pending') return 'pending';
  return 'new';
};

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  if (req.method !== 'GET') {
    return res
      .status(405)
      .json({ success: false, message: 'Method not allowed' });
  }

  try {
    await dbConnect();

    const activities: ActivityItem[] = [];

    // Fetch recent data in parallel
    const [
      recentProperties,
      recentProjects,
      recentDevelopers,
      recentInquiries,
      recentUsers,
    ] = await Promise.all([
      // Recent properties (last 10)
      Property.find({ isDeleted: false })
        .sort({ createdAt: -1 })
        .limit(5)
        .select('_id title city status createdAt')
        .lean(),

      // Recent projects (last 5)
      Project.find({ isDeleted: { $ne: true } })
        .sort({ createdAt: -1 })
        .limit(5)
        .select('_id projectName city status createdAt')
        .lean(),

      // Recent developer verifications (last 5)
      DeveloperProfile.find()
        .sort({ createdAt: -1 })
        .limit(5)
        .select('_id companyName status createdAt')
        .lean(),

      // Recent inquiries (last 5, property leads only)
      Lead.find({ entityType: 'property', isArchived: false })
        .sort({ createdAt: -1 })
        .limit(5)
        .select('_id name message status createdAt')
        .lean(),

      // Recent users (last 5)
      User.find({ role: { $in: ['user', 'developer'] } })
        .sort({ createdAt: -1 })
        .limit(5)
        .select('_id name email createdAt')
        .lean(),
    ]);

    // Process properties
    recentProperties.forEach((prop: any) => {
      activities.push({
        id: `property-${prop._id}`,
        type: 'property',
        title: prop.status === 'pending' ? 'New Property Listed' : `Property ${prop.status}`,
        description: `${prop.title || 'Untitled'} in ${prop.city || 'Unknown'}`,
        time: formatTimeAgo(new Date(prop.createdAt)),
        status: mapPropertyStatus(prop.status),
        createdAt: new Date(prop.createdAt),
      });
    });

    // Process projects
    recentProjects.forEach((proj: any) => {
      activities.push({
        id: `project-${proj._id}`,
        type: 'project',
        title: proj.status === 'pending' ? 'New Project Submitted' : `Project ${proj.status}`,
        description: `${proj.projectName || 'Untitled'} in ${proj.city || 'Unknown'}`,
        time: formatTimeAgo(new Date(proj.createdAt)),
        status: mapPropertyStatus(proj.status),
        createdAt: new Date(proj.createdAt),
      });
    });

    // Process developers
    recentDevelopers.forEach((dev: any) => {
      activities.push({
        id: `developer-${dev._id}`,
        type: 'developer',
        title: dev.status === 'pending' ? 'Developer Verification Request' : `Developer ${dev.status}`,
        description: dev.companyName || 'Unknown Company',
        time: formatTimeAgo(new Date(dev.createdAt)),
        status: mapPropertyStatus(dev.status),
        createdAt: new Date(dev.createdAt),
      });
    });

    // Process inquiries
    recentInquiries.forEach((inq: any) => {
      activities.push({
        id: `inquiry-${inq._id}`,
        type: 'inquiry',
        title: 'New Inquiry',
        description: `From ${inq.name || 'Anonymous'}: ${(inq.message || '').slice(0, 50)}${(inq.message || '').length > 50 ? '...' : ''}`,
        time: formatTimeAgo(new Date(inq.createdAt)),
        status: inq.status === 'new' ? 'new' : 'pending',
        createdAt: new Date(inq.createdAt),
      });
    });

    // Process users
    recentUsers.forEach((user: any) => {
      activities.push({
        id: `user-${user._id}`,
        type: 'user',
        title: 'New User Registration',
        description: `${user.email || 'Unknown'} joined the platform`,
        time: formatTimeAgo(new Date(user.createdAt)),
        status: 'new',
        createdAt: new Date(user.createdAt),
      });
    });

    // Sort all activities by createdAt (most recent first)
    activities.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());

    // Take only top 10
    const topActivities = activities.slice(0, 10);

    // Remove createdAt from response (we only needed it for sorting)
    const formattedActivities = topActivities.map(({ createdAt, ...rest }) => rest);

    return res.status(200).json({
      success: true,
      activities: formattedActivities,
    });
  } catch (error: any) {
    console.error('Error fetching recent activity:', error);
    return res.status(500).json({
      success: false,
      message: 'Failed to load recent activity',
      error: error?.message || 'Unknown error',
    });
  }
}

// pages/api/admin/reports/[id].ts
// 🔒 ENTERPRISE v2.0 - Single Report View & Status Update with Atomic Operations & Audit Trail

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import Report from '@/models/Report';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import mongoose from 'mongoose';
import { requireAuth } from '@/lib/requireAuth';
import { checkPermission } from '@/lib/permissions';
import { z } from 'zod';
import { rateLimitAdmin } from '@/lib/rateLimit';

// ═══════════════════════════════════════════════════════════════
// 🔒 ENTERPRISE CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TIME_MS = 3000;
const ALLOWED_STATUS = ['open', 'reviewing', 'resolved', 'rejected'] as const;
const MIN_RESOLUTION_NOTES_LENGTH = 10;
const MAX_RESOLUTION_NOTES_LENGTH = 1000;

// ✅ Zod Schema for PATCH Request
const UpdateSchema = z.object({
  status: z.enum(ALLOWED_STATUS),
  resolutionNotes: z.string().trim().min(MIN_RESOLUTION_NOTES_LENGTH).max(MAX_RESOLUTION_NOTES_LENGTH).optional(),
  actionTaken: z.enum(['none', 'warning_sent', 'content_removed', 'user_banned', 'escalated']).optional(),
});

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY HEADERS
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function setSecurityHeaders(res: NextApiResponse, requestId: string) {
  res.setHeader('X-Request-Id', requestId);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
}

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPERS
// ═══════════════════════════════════════════════════════════════

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || '').split(',')[0]?.trim() || req.socket?.remoteAddress || '0.0.0.0';
}

function requireActiveUserOrThrow(user: any) {
  if (!user || user.isDeleted || user.status === 'banned') {
    const err: any = new Error('Account is restricted');
    err.statusCode = 403;
    err.code = 'ACCOUNT_RESTRICTED';
    throw err;
  }
}

function requireAdminRoleOrThrow(user: any) {
  const role = String(user?.role || 'user').toLowerCase();
  if (!['admin', 'superadmin'].includes(role)) {
    const err: any = new Error('Admin access required');
    err.statusCode = 403;
    err.code = 'ADMIN_REQUIRED';
    throw err;
  }
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const ip = getClientIp(req);
  const ua = String(req.headers['user-agent'] || '').slice(0, 200);

  // ═══════════════════════════════════════════════════════════════
  // ✅ VALIDATE REPORT ID
  // ═══════════════════════════════════════════════════════════════

  const id = typeof req.query.id === 'string' ? req.query.id.trim() : '';
  if (!id || !mongoose.Types.ObjectId.isValid(id)) {
    return res.status(400).json({ 
      success: false, 
      message: 'Invalid report ID',
      code: 'INVALID_ID',
      requestId 
    });
  }

  try {
    await dbConnect();

    // ═══════════════════════════════════════════════════════════════
    // ✅ AUTHENTICATION & AUTHORIZATION
    // ═══════════════════════════════════════════════════════════════

    const auth = await requireAuth(req, res);
    if (!auth) return;

    const admin: any = await User.findById(auth.id)
      .select('role status isDeleted permissions')
      .lean()
      .maxTimeMS(MAX_TIME_MS);

    requireActiveUserOrThrow(admin);
    requireAdminRoleOrThrow(admin);

    const isSuperAdmin = String(admin.role).toLowerCase() === 'superadmin';

    // ═══════════════════════════════════════════════════════════════
    // ✅ RATE LIMITING (Applied once for all methods)
    // ═══════════════════════════════════════════════════════════════

    const rlResult = await rateLimitAdmin(req);
    if (!rlResult.ok) {
      res.setHeader('Retry-After', String(rlResult.retryAfter || 60));
      return res.status(429).json({
        success: false,
        message: 'Too many requests. Please slow down.',
        code: 'RATE_LIMITED',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ METHOD: GET - View Report Details
    // ═══════════════════════════════════════════════════════════════

    if (req.method === 'GET') {
      const hasPermission = checkPermission(admin, 'reports.view');
      if (!hasPermission) {
        return res.status(403).json({
          success: false,
          message: 'Permission denied',
          code: 'PERMISSION_DENIED',
          requestId,
        });
      }

      const report: any = await Report.findById(id)
        .select('-__v')
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      if (!report) {
        return res.status(404).json({ 
          success: false, 
          message: 'Report not found',
          code: 'NOT_FOUND',
          requestId 
        });
      }

      // PII Redaction for non-superadmins
      const reportData: any = {
        _id: String(report._id),
        entityType: report.entityType,
        entityId: String(report.entityId),
        reason: report.reason,
        details: report.details,
        reporterUserId: report.reporterUserId ? String(report.reporterUserId) : null,
        reporterEmail: isSuperAdmin ? report.reporterEmail : `${(report.reporterEmail || '').slice(0, 3)}***@***`,
        reporterPhone: isSuperAdmin ? report.reporterPhone : `***${(report.reporterPhone || '').slice(-4)}`,
        status: report.status,
        resolutionNotes: report.resolutionNotes || '',
        actionTaken: report.actionTaken || 'none',
        resolvedBy: report.resolvedBy ? String(report.resolvedBy) : null,
        resolvedAt: report.resolvedAt || null,
        createdAt: report.createdAt,
        updatedAt: report.updatedAt,
      };

      // Audit log (async - non-blocking)
      SecurityEvent.create({
        eventType: 'admin.report.viewed',
        userId: auth.id,
        metadata: { reportId: id },
        ipAddress: ip,
        userAgent: ua,
        severity: 'info',
      }).catch((err) => console.error('Audit failed:', err));

      return res.status(200).json({
        success: true,
        report: reportData,
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ METHOD: PATCH - Update Report Status
    // ═══════════════════════════════════════════════════════════════

    if (req.method === 'PATCH') {
      const hasPermission = checkPermission(admin, 'reports.update');
      if (!hasPermission) {
        return res.status(403).json({
          success: false,
          message: 'Permission denied',
          code: 'PERMISSION_DENIED',
          requestId,
        });
      }

      // Validate input
      const parseResult = UpdateSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid request body',
          code: 'VALIDATION_ERROR',
          errors: parseResult.error.flatten().fieldErrors,
          requestId,
        });
      }

      const { status, resolutionNotes, actionTaken } = parseResult.data;

      // ✅ Atomic Update with $set
      const updatePayload: any = {
        status,
        updatedAt: new Date(),
      };

      if (resolutionNotes) {
        updatePayload.resolutionNotes = resolutionNotes;
      }

      if (actionTaken) {
        updatePayload.actionTaken = actionTaken;
      }

      // If status is 'resolved' or 'rejected', track who resolved it
      if (status === 'resolved' || status === 'rejected') {
        updatePayload.resolvedBy = auth.id;
        updatePayload.resolvedAt = new Date();
      }

      const updated: any = await Report.findByIdAndUpdate(
        id,
        { $set: updatePayload },
        { new: true, runValidators: true }
      )
        .select('-__v')
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      if (!updated) {
        return res.status(404).json({ 
          success: false, 
          message: 'Report not found',
          code: 'NOT_FOUND',
          requestId 
        });
      }

      // Audit log (async - non-blocking)
      SecurityEvent.create({
        eventType: 'admin.report.updated',
        userId: auth.id,
        metadata: {
          reportId: id,
          newStatus: status,
          actionTaken: actionTaken || 'none',
        },
        ipAddress: ip,
        userAgent: ua,
        severity: 'medium',
      }).catch((err) => console.error('Audit failed:', err));

      return res.status(200).json({
        success: true,
        message: 'Report updated successfully',
        report: {
          _id: String(updated._id),
          status: updated.status,
          resolutionNotes: updated.resolutionNotes,
          actionTaken: updated.actionTaken,
          resolvedBy: updated.resolvedBy ? String(updated.resolvedBy) : null,
          resolvedAt: updated.resolvedAt,
          updatedAt: updated.updatedAt,
        },
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ METHOD NOT ALLOWED
    // ═══════════════════════════════════════════════════════════════

    res.setHeader('Allow', ['GET', 'PATCH']);
    return res.status(405).json({ 
      success: false, 
      message: 'Method not allowed',
      requestId 
    });

  } catch (error: any) {
    console.error('Admin report error:', { requestId, error: error?.message });

    if (error?.statusCode && error?.code) {
      return res.status(error.statusCode).json({
        success: false,
        message: error.message,
        code: error.code,
        requestId,
      });
    }

    return res.status(500).json({
      success: false,
      message: 'Internal server error',
      code: 'SERVER_ERROR',
      requestId,
    });
  }
}

// pages/api/admin/reports/index.ts
// 🔒 ENTERPRISE v2.0 - Admin Reports List with RBAC, Rate Limiting, Audit, PII Protection

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import Report from '@/models/Report';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import mongoose from 'mongoose';
import { requireAuth } from '@/lib/requireAuth';
import { checkPermission } from '@/lib/permissions';
import { z } from 'zod';
import { rateLimitAdmin, RateLimitResult } from '@/lib/rateLimit';

// ═══════════════════════════════════════════════════════════════
// 🔒 ENTERPRISE CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TIME_MS = 3000;
const MAX_LIMIT = 100; // Prevent OOM attacks
const DEFAULT_LIMIT = 20;
const DEFAULT_PAGE = 1;

const ALLOWED_STATUS = new Set(['open', 'reviewing', 'resolved', 'rejected']);
const ALLOWED_ENTITY_TYPES = new Set(['property', 'comment', 'user', 'developer']);

// ✅ Zod Schema for Query Validation
const QuerySchema = z.object({
  status: z.enum(['open', 'reviewing', 'resolved', 'rejected', '']).optional().default(''),
  entityType: z.enum(['property', 'comment', 'user', 'developer', '']).optional().default(''),
  page: z.coerce.number().int().min(1).max(10000).optional().default(DEFAULT_PAGE),
  limit: z.coerce.number().int().min(1).max(MAX_LIMIT).optional().default(DEFAULT_LIMIT),
  q: z.string().trim().max(100).optional().default(''),
});

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY HEADERS + REQUEST ID
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function setSecurityHeaders(res: NextApiResponse, requestId: string) {
  res.setHeader('X-Request-Id', requestId);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
}

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPERS
// ═══════════════════════════════════════════════════════════════

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || '').split(',')[0]?.trim() || req.socket?.remoteAddress || '0.0.0.0';
}

function requireActiveUserOrThrow(user: any) {
  if (!user) {
    const err: any = new Error('User not found');
    err.statusCode = 401;
    err.code = 'USER_NOT_FOUND';
    throw err;
  }

  if (user.isDeleted || user.status === 'banned' || user.isActive === false) {
    const err: any = new Error('Account is restricted');
    err.statusCode = 403;
    err.code = 'ACCOUNT_RESTRICTED';
    throw err;
  }
}

function requireAdminRoleOrThrow(user: any) {
  const role = String(user?.role || 'user').toLowerCase();
  if (!['admin', 'superadmin'].includes(role)) {
    const err: any = new Error('Admin access required');
    err.statusCode = 403;
    err.code = 'ADMIN_REQUIRED';
    throw err;
  }
}

// 🔒 PII Redaction for Reports (Hide emails/phones for non-superadmins)
function redactPII(report: any, isSuperAdmin: boolean): any {
  if (isSuperAdmin) return report; // SuperAdmins see everything

  return {
    ...report,
    reporterEmail: report.reporterEmail ? `${report.reporterEmail.slice(0, 3)}***@***` : '',
    reporterPhone: report.reporterPhone ? `***${report.reporterPhone.slice(-4)}` : '',
  };
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).json({ 
      success: false, 
      message: 'Method not allowed',
      requestId 
    });
  }

  const ip = getClientIp(req);
  const ua = String(req.headers['user-agent'] || '').slice(0, 200);

  try {
    await dbConnect();

    // ═══════════════════════════════════════════════════════════════
    // ✅ AUTHENTICATION & AUTHORIZATION
    // ═══════════════════════════════════════════════════════════════

    const auth = await requireAuth(req, res);
    if (!auth) return;

    const admin: any = await User.findById(auth.id)
      .select('role status isDeleted isActive permissions')
      .lean()
      .maxTimeMS(MAX_TIME_MS);

    requireActiveUserOrThrow(admin);
    requireAdminRoleOrThrow(admin);

    const isSuperAdmin = String(admin.role).toLowerCase() === 'superadmin';

    // ✅ Permission Check
    const hasPermission = checkPermission(admin, 'reports.view');
    if (!hasPermission) {
      const err: any = new Error('You do not have permission to view reports');
      err.statusCode = 403;
      err.code = 'PERMISSION_DENIED';
      throw err;
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ RATE LIMITING (Redis-backed with fallback)
    // ═══════════════════════════════════════════════════════════════

    const rateLimitResult = await rateLimitAdmin(req);

if (!rateLimitResult.ok) {
  res.setHeader('Retry-After', String(rateLimitResult.retryAfter || 60));
  return res.status(429).json({
    success: false,
    message: 'Too many requests. Please slow down.',
    code: 'RATE_LIMITED',
    requestId,
  });
}

    // ═══════════════════════════════════════════════════════════════
    // ✅ INPUT VALIDATION (Zod)
    // ═══════════════════════════════════════════════════════════════

    const parseResult = QuerySchema.safeParse(req.query);
    if (!parseResult.success) {
      return res.status(400).json({
        success: false,
        message: 'Invalid query parameters',
        code: 'VALIDATION_ERROR',
        errors: parseResult.error.flatten().fieldErrors,
        requestId,
      });
    }

    const { status, entityType, page, limit, q } = parseResult.data;
    const skip = (page - 1) * limit;

    // ═══════════════════════════════════════════════════════════════
    // ✅ BUILD SECURE QUERY
    // ═══════════════════════════════════════════════════════════════

    const filter: any = {};

    // Filter by status
    if (status && ALLOWED_STATUS.has(status)) {
      filter.status = status;
    }

    // Filter by entity type
    if (entityType && ALLOWED_ENTITY_TYPES.has(entityType)) {
      filter.entityType = entityType;
    } else if (!entityType) {
      // Default to property reports (most common)
      filter.entityType = 'property';
    }

    // Search functionality
    if (q && q.length >= 2) {
      const or: any[] = [];

      // Search by ObjectId (report ID or entity ID)
      if (mongoose.Types.ObjectId.isValid(q)) {
        or.push({ _id: new mongoose.Types.ObjectId(q) });
        or.push({ entityId: new mongoose.Types.ObjectId(q) });
      }

      // Search by reason (exact enum match)
      const reasonMatch = q.toLowerCase().replace(/[^a-z_]/g, '');
      if (reasonMatch) {
        or.push({ reason: { $regex: `^${reasonMatch}`, $options: 'i' } });
      }

      // Search by reporter email (only for superadmin)
      if (isSuperAdmin && q.includes('@')) {
        or.push({ reporterEmail: { $regex: q, $options: 'i' } });
      }

      if (or.length > 0) {
        filter.$or = or;
      }
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ FETCH REPORTS (Optimized with .lean())
    // ═══════════════════════════════════════════════════════════════

    const [total, reports] = await Promise.all([
      Report.countDocuments(filter).maxTimeMS(MAX_TIME_MS),
      Report.find(filter)
        .sort({ createdAt: -1, status: 1 }) // Open reports first
        .skip(skip)
        .limit(limit)
        .select('-__v') // Exclude mongoose internal field
        .lean()
        .maxTimeMS(MAX_TIME_MS),
    ]);

    // ═══════════════════════════════════════════════════════════════
    // ✅ SANITIZE & REDACT OUTPUT
    // ═══════════════════════════════════════════════════════════════

    const sanitizedReports = (reports || []).map((r: any) => {
      const base = {
        _id: String(r._id),
        entityType: r.entityType,
        entityId: String(r.entityId),
        reason: r.reason,
        details: String(r.details || '').slice(0, 500), // Truncate long details
        reporterEmail: r.reporterEmail || '',
        reporterPhone: r.reporterPhone || '',
        reporterUserId: r.reporterUserId ? String(r.reporterUserId) : null,
        status: r.status,
        createdAt: r.createdAt,
        updatedAt: r.updatedAt,
      };

      return redactPII(base, isSuperAdmin);
    });

    // ═══════════════════════════════════════════════════════════════
    // ✅ AUDIT LOG (Async - non-blocking)
    // ═══════════════════════════════════════════════════════════════

    SecurityEvent.create({
      eventType: 'admin.reports.viewed',
      userId: auth.id,
      metadata: {
        filters: { status, entityType, q: q ? '[redacted]' : '' },
        page,
        limit,
        totalResults: total,
      },
      ipAddress: ip,
      userAgent: ua,
      severity: 'info',
    }).catch((err) => console.error('Audit log failed:', err));

    // ═══════════════════════════════════════════════════════════════
    // ✅ RESPONSE
    // ═══════════════════════════════════════════════════════════════

    return res.status(200).json({
      success: true,
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit),
      reports: sanitizedReports,
      requestId,
    });

  } catch (error: any) {
    console.error('Admin reports list error:', { requestId, error: error?.message });

    if (error?.statusCode && error?.code) {
      return res.status(error.statusCode).json({
        success: false,
        message: error.message,
        code: error.code,
        requestId,
      });
    }

    return res.status(500).json({
      success: false,
      message: 'Internal server error',
      code: 'SERVER_ERROR',
      requestId,
    });
  }
}

import type { NextApiRequest, NextApiResponse } from "next";
import dbConnect from "@/lib/dbConnect";
import SecurityEvent from "@/models/SecurityEvent";
import { requireAdmin } from "@/lib/requireAuth";

function toSafeString(v: unknown, max = 120): string {
  const s = typeof v === "string" ? v : "";
  return s.trim().slice(0, max);
}

function toSafeInt(v: unknown, fallback: number, min: number, max: number) {
  const n = Number(v);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, Math.floor(n)));
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "GET") return res.status(405).json({ error: "Method not allowed" });

  const auth = await requireAdmin(req, res);
  if (!auth) return;

  // Security headers (defense-in-depth)
  res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate, proxy-revalidate");
  res.setHeader("Pragma", "no-cache");
  res.setHeader("Expires", "0");

  try {
    await dbConnect();

    const page = toSafeInt(req.query.page, 1, 1, 5000);
    const limit = toSafeInt(req.query.limit, 25, 5, 100);
    const skip = (page - 1) * limit;

    const email = toSafeString(req.query.email, 120).toLowerCase();
    const type = toSafeString(req.query.type, 60);
    const roleFilter = toSafeString(req.query.role, 40);

    const from = toSafeString(req.query.from, 40);
    const to = toSafeString(req.query.to, 40);

    const filter: any = {};

    if (email) filter.email = email;
    if (type && type !== "all") filter.type = type;
    if (roleFilter && roleFilter !== "all") filter.role = roleFilter;

    if (from || to) {
      filter.createdAt = {};
      if (from) {
        const d = new Date(from);
        if (!isNaN(d.getTime())) filter.createdAt.$gte = d;
      }
      if (to) {
        const d = new Date(to);
        if (!isNaN(d.getTime())) filter.createdAt.$lte = d;
      }
      // If invalid dates -> remove
      if (Object.keys(filter.createdAt).length === 0) delete filter.createdAt;
    }

    const [items, total] = await Promise.all([
      SecurityEvent.find(filter)
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(limit)
        .lean(),
      SecurityEvent.countDocuments(filter),
    ]);

    const safeItems = (items || []).map((e: any) => ({
      _id: String(e._id),
      createdAt: e.createdAt,
      type: e.type,
      email: e.email || "",
      role: e.role || "",
      // These are already hashed in your NextAuth logger.
      ipHashShort: typeof e.ip === "string" ? e.ip.slice(0, 10) : "",
      uaHashShort: typeof e.userAgent === "string" ? e.userAgent.slice(0, 10) : "",
      metadata: e.metadata || {},
    }));

    return res.status(200).json({
      success: true,
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit),
      items: safeItems,
    });
  } catch (err: any) {
    console.error("security-events api error:", err);
    return res.status(500).json({ error: "Internal server error" });
  }
}

// pages/api/admin/security/block-ip.ts
// 🔒 ENTERPRISE IP BLOCK MANAGEMENT API — HIGHRISE.PK
// Security Level: MAXIMUM | Admin Only | Global IP Blocklist
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   GET    → List all currently blocked IPs
//   POST   → Add IP to global blocklist
//   DELETE → Remove IP from global blocklist
//
// DESIGN:
//   Blocked IPs stored in MongoDB (SecurityBlockedIP collection)
//   via mongoose model defined inline (no separate file needed
//   since it's a simple key-value store).
//
//   The rateLimit.ts already supports RATE_LIMIT_BLOCKED_IPS
//   env var — but that requires a deploy to update.
//
//   THIS API provides runtime IP blocking that:
//   → Stores blocks in DB (persists across deploys)
//   → Admin can add/remove without code changes
//   → Dashboard shows who blocked what and when
//   → Expiry support (auto-unblock after N hours)
//   → Notes field (reason for block)
//
// INTEGRATION:
//   Blocked IPs from this collection can be checked
//   in middleware or API routes via the
//   isGloballyBlockedIP() helper exported below.
//
// SECURITY:
//   ✅ requireAdmin() auth guard
//   ✅ rateLimitAdmin() rate limiting
//   ✅ IPv4 + IPv6 format validation
//   ✅ Cannot block trusted IPs (127.0.0.1, ::1)
//   ✅ Duplicate block prevention
//   ✅ Audit logging (every block/unblock)
//   ✅ Security headers + request ID
//   ✅ Generic error messages
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose                                  from 'mongoose';
import dbConnect                                 from '@/lib/db';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ═══════════════════════════════════════════════════════════════
// 🔐 INLINE MODEL — SecurityBlockedIP
// Simple collection: one document per blocked IP
// Defined inline (no separate models/ file needed)
// ═══════════════════════════════════════════════════════════════

interface ISecurityBlockedIP {
  _id:        mongoose.Types.ObjectId;
  ip:         string;         // The IP to block
  reason:     string;         // Why it was blocked
  blockedBy:  string;         // Admin user ID who blocked it
  blockedAt:  Date;           // When it was blocked
  expiresAt:  Date | null;    // null = permanent block
  isActive:   boolean;        // quick filter
  notes:      string;         // optional internal notes
  eventCount: number;         // how many security events from this IP
  createdAt:  Date;
  updatedAt:  Date;
}

const SecurityBlockedIPSchema = new mongoose.Schema<ISecurityBlockedIP>(
  {
    ip: {
      type:     String,
      required: true,
      unique:   true,
      trim:     true,
      index:    true,
    },
    reason: {
      type:      String,
      required:  true,
      trim:      true,
      maxlength: 500,
    },
    blockedBy: {
      type:     String,
      required: true,
    },
    blockedAt: {
      type:    Date,
      default: Date.now,
      index:   true,
    },
    expiresAt: {
      type:    Date,
      default: null,
      index:   true,
    },
    isActive: {
      type:    Boolean,
      default: true,
      index:   true,
    },
    notes: {
      type:      String,
      trim:      true,
      maxlength: 1000,
      default:   '',
    },
    eventCount: {
      type:    Number,
      default: 0,
      min:     0,
    },
  },
  { timestamps: true }
);

// TTL index: auto-removes expired blocks
// Only applies when expiresAt is set (not null)
SecurityBlockedIPSchema.index(
  { expiresAt: 1 },
  {
    expireAfterSeconds: 0,
    partialFilterExpression: { expiresAt: { $ne: null } },
  }
);

const SecurityBlockedIP =
  mongoose.models.SecurityBlockedIP ||
  mongoose.model<ISecurityBlockedIP>(
    'SecurityBlockedIP',
    SecurityBlockedIPSchema
  );

// ═══════════════════════════════════════════════════════════════
// 🔐 EXPORTED HELPER
// Use this in middleware or API routes to check
// if an incoming IP is globally blocked.
// ═══════════════════════════════════════════════════════════════

/**
 * Check if an IP is in the global blocklist.
 * Returns true if blocked and block is still active/not expired.
 * Call dbConnect() before using this.
 */
export async function isGloballyBlockedIP(ip: string): Promise<boolean> {
  if (!ip || ip === 'unknown') return false;
  const block = await SecurityBlockedIP.findOne({
    ip,
    isActive: true,
    $or: [
      { expiresAt: null },
      { expiresAt: { $gt: new Date() } },
    ],
  }).lean();
  return !!block;
}

// ═══════════════════════════════════════════════════════════════
// 🔐 CONSTANTS
// ═══════════════════════════════════════════════════════════════

// IPs that can NEVER be blocked
const PROTECTED_IPS = new Set([
  '127.0.0.1',
  '::1',
  'localhost',
  '0.0.0.0',
]);

const MAX_REASON_LENGTH = 500;
const MAX_NOTES_LENGTH  = 1000;
const PAGE_LIMIT        = 50;

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') {
    return forwarded.split(',')[0].trim();
  }
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(
  res: NextApiResponse,
  requestId: string
): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
}

/**
 * Validate IPv4 or IPv6 format.
 * Basic validation — catches obvious bad inputs.
 */
function isValidIP(ip: string): boolean {
  if (!ip || typeof ip !== 'string') return false;
  const trimmed = ip.trim();
  if (trimmed.length > 45) return false;

  // IPv4
  const ipv4 =
    /^(\d{1,3}\.){3}\d{1,3}$/;
  if (ipv4.test(trimmed)) {
    const parts = trimmed.split('.');
    return parts.every((p) => parseInt(p, 10) <= 255);
  }

  // IPv6 (basic check — not full RFC 5952)
  const ipv6 = /^([0-9a-fA-F]{0,4}:){2,7}[0-9a-fA-F]{0,4}$/;
  return ipv6.test(trimmed);
}

function sanitizeText(text: unknown, maxLength: number): string {
  if (!text || typeof text !== 'string') return '';
  return text.replace(/<[^>]*>/g, '').trim().slice(0, maxLength);
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(
    req.headers['user-agent'] || 'unknown'
  ).slice(0, 500);

  // ─────────────────────────────────────────────
  // STEP 1: Method guard
  // ─────────────────────────────────────────────
  if (!['GET', 'POST', 'DELETE'].includes(req.method || '')) {
    res.setHeader('Allow', ['GET', 'POST', 'DELETE']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 2: Rate limit
  // ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: {
        action:   'block_ip_rate_limited',
        endpoint: '/api/admin/security/block-ip',
        method:   req.method,
      },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 3: Admin auth
  // ─────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  await dbConnect();

  // ═══════════════════════════════════════════════════════════
  // GET → List blocked IPs
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'GET') {
    try {
      const {
        page     = '1',
        active   = 'true',
      } = req.query;

      const pageNum = Math.max(
        1,
        parseInt(String(page), 10) || 1
      );
      const skip = (pageNum - 1) * PAGE_LIMIT;

      // Filter: active only OR all
      const filter: Record<string, unknown> =
        active === 'all' ? {} : { isActive: true };

      const [blocks, total] = await Promise.all([
        SecurityBlockedIP.find(filter)
          .sort({ blockedAt: -1 })
          .skip(skip)
          .limit(PAGE_LIMIT)
          .lean(),
        SecurityBlockedIP.countDocuments(filter),
      ]);

      res.status(200).json({
        success: true,
        blocks,
        pagination: {
          page:       pageNum,
          limit:      PAGE_LIMIT,
          total,
          totalPages: Math.ceil(total / PAGE_LIMIT),
        },
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error
        ? error.message
        : 'Unknown error';

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action: 'block_ip_list_failed',
          error:  errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to fetch blocked IPs',
        requestId,
      });
      return;
    }
  }

  // ═══════════════════════════════════════════════════════════
  // POST → Block an IP
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'POST') {
    try {
      const {
        ip,
        reason,
        notes        = '',
        expiresHours = null,  // null = permanent, number = hours
      } = req.body || {};

      // ── Validate IP ───────────────────────
      if (!ip || typeof ip !== 'string') {
        res.status(400).json({
          success: false,
          message: 'IP address is required',
          requestId,
        });
        return;
      }

      const ipClean = ip.trim();

      if (!isValidIP(ipClean)) {
        res.status(400).json({
          success: false,
          message: 'Invalid IP address format',
          requestId,
        });
        return;
      }

      // ── Guard: cannot block protected IPs ─
      if (PROTECTED_IPS.has(ipClean)) {
        await logSecurityEvent({
          type:     'suspicious_activity',
          severity: 'high',
          userId:   auth.id,
          email:    auth.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            action:    'protected_ip_block_attempt',
            targetIP:  ipClean,
          },
        });
        res.status(400).json({
          success: false,
          message: 'This IP address cannot be blocked',
          requestId,
        });
        return;
      }

      // ── Validate reason ───────────────────
      if (!reason || typeof reason !== 'string' || !reason.trim()) {
        res.status(400).json({
          success: false,
          message: 'Block reason is required',
          requestId,
        });
        return;
      }

      const cleanReason = sanitizeText(reason, MAX_REASON_LENGTH);
      if (cleanReason.length < 5) {
        res.status(400).json({
          success: false,
          message: 'Reason must be at least 5 characters',
          requestId,
        });
        return;
      }

      const cleanNotes = sanitizeText(notes, MAX_NOTES_LENGTH);

      // ── Calculate expiry ──────────────────
      let expiresAt: Date | null = null;
      if (expiresHours !== null && expiresHours !== undefined) {
        const hours = parseInt(String(expiresHours), 10);
        if (!isNaN(hours) && hours > 0 && hours <= 8760) {
          // max 1 year
          expiresAt = new Date(
            Date.now() + hours * 60 * 60 * 1000
          );
        }
      }

      // ── Count security events from this IP ─
      // Use ipHash if available — but we'll just count by masked IP
      // since raw IP is not reliably stored
      const eventCount = await SecurityBlockedIP.countDocuments({
        ip: ipClean,
      });

      // ── Create or reactivate block ────────
      const existing = await SecurityBlockedIP.findOne({
        ip: ipClean,
      });

      if (existing) {
        if (existing.isActive) {
          res.status(409).json({
            success: false,
            message: `IP ${ipClean} is already blocked`,
            requestId,
          });
          return;
        }

        // Reactivate expired/deactivated block
        existing.isActive   = true;
        existing.reason     = cleanReason;
        existing.notes      = cleanNotes;
        existing.blockedBy  = auth.id;
        existing.blockedAt  = new Date();
        existing.expiresAt  = expiresAt;
        await existing.save();

        await logSecurityEvent({
          type:     'ip_blocked',
          severity: 'high',
          userId:   auth.id,
          email:    auth.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            action:      'ip_block_reactivated',
            targetIP:    ipClean,
            reason:      cleanReason,
            expiresAt:   expiresAt?.toISOString() || 'permanent',
          },
        });

        res.status(200).json({
          success: true,
          message: `IP ${ipClean} has been blocked`,
          block:   existing,
          requestId,
        });
        return;
      }

      // Create new block
      const block = await SecurityBlockedIP.create({
        ip:         ipClean,
        reason:     cleanReason,
        notes:      cleanNotes,
        blockedBy:  auth.id,
        blockedAt:  new Date(),
        expiresAt,
        isActive:   true,
        eventCount,
      });

      // ── Audit log ─────────────────────────
      await logSecurityEvent({
        type:     'ip_blocked',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:    'ip_blocked',
          targetIP:  ipClean,
          reason:    cleanReason,
          expiresAt: expiresAt?.toISOString() || 'permanent',
          blockId:   String(block._id),
        },
      });

      res.status(201).json({
        success: true,
        message: `IP ${ipClean} has been blocked${
          expiresAt
            ? ` until ${expiresAt.toLocaleString()}`
            : ' permanently'
        }`,
        block,
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error
        ? error.message
        : 'Unknown error';

      // Handle MongoDB duplicate key
      if (
        typeof error === 'object' &&
        error !== null &&
        'code' in error &&
        (error as any).code === 11000
      ) {
        res.status(409).json({
          success: false,
          message: 'This IP is already in the blocklist',
          requestId,
        });
        return;
      }

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action: 'ip_block_failed',
          error:  errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to block IP address',
        requestId,
      });
      return;
    }
  }

  // ═══════════════════════════════════════════════════════════
  // DELETE → Unblock an IP
  // ═══════════════════════════════════════════════════════════
  if (req.method === 'DELETE') {
    try {
      const { ip } = req.body || req.query || {};

      if (!ip || typeof ip !== 'string') {
        res.status(400).json({
          success: false,
          message: 'IP address is required',
          requestId,
        });
        return;
      }

      const ipClean = ip.trim();

      if (!isValidIP(ipClean)) {
        res.status(400).json({
          success: false,
          message: 'Invalid IP address format',
          requestId,
        });
        return;
      }

      // Find and deactivate (soft delete — keep history)
      const block = await SecurityBlockedIP.findOne({
        ip:       ipClean,
        isActive: true,
      });

      if (!block) {
        res.status(404).json({
          success: false,
          message: 'No active block found for this IP',
          requestId,
        });
        return;
      }

      block.isActive = false;
      await block.save();

      // ── Audit log ─────────────────────────
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'medium',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action:   'ip_unblocked',
          targetIP: ipClean,
          blockId:  String(block._id),
        },
      });

      res.status(200).json({
        success: true,
        message: `IP ${ipClean} has been unblocked`,
        requestId,
      });
      return;

    } catch (error: unknown) {
      const errMsg = error instanceof Error
        ? error.message
        : 'Unknown error';

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        email:    auth.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          action: 'ip_unblock_failed',
          error:  errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to unblock IP address',
        requestId,
      });
      return;
    }
  }
}

// pages/api/admin/security/events.ts
// 🔒 ENTERPRISE SECURITY EVENTS API — HIGHRISE.PK
// Security Level: MAXIMUM | Admin Only | Event Viewer
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   GET → Paginated security event list with filters:
//     • severity (low | medium | high | critical | all)
//     • type (specific SecurityEventType or "all")
//     • search (email / masked IP / metadata text)
//     • dateFrom / dateTo
//     • page + limit
//
// SECURITY:
//   ✅ requireAdmin() auth guard
//   ✅ rateLimitAdmin() rate limiting
//   ✅ Input validation + whitelisting
//   ✅ No raw IP exposure (ipRaw not selected)
//   ✅ No sensitive hashed values exposed
//   ✅ logSecurityEvent audit logging on suspicious usage
//   ✅ Security headers + request ID
//   ✅ Generic error messages
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect                                 from '@/lib/db';
import SecurityEvent                             from '@/models/SecurityEvent';
import type { SeverityLevel, SecurityEventType } from '@/models/SecurityEvent';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ═══════════════════════════════════════════════════════════════
// 🔐 CONSTANTS
// ═══════════════════════════════════════════════════════════════

const DEFAULT_LIMIT = 50;
const MAX_LIMIT     = 200;
const MAX_SEARCH_LENGTH = 100;

const ALLOWED_SEVERITIES: (SeverityLevel | 'all')[] = [
  'all',
  'low',
  'medium',
  'high',
  'critical',
];

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') {
    return forwarded.split(',')[0].trim();
  }
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id', requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control', 'no-store, must-revalidate, private');
}

function sanitizeSearch(input: unknown): string {
  if (!input || typeof input !== 'string') return '';
  return input.replace(/[<>'"]/g, '').trim().slice(0, MAX_SEARCH_LENGTH);
}

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ─────────────────────────────────────────────
  // STEP 1: Method guard
  // ─────────────────────────────────────────────
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 2: Rate limit
  // ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: {
        action:   'security_events_rate_limited',
        endpoint: '/api/admin/security/events',
      },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 3: Admin auth
  // ─────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  await dbConnect();

  try {
    const {
      severity = 'all',
      type     = 'all',
      search   = '',
      dateFrom,
      dateTo,
      page     = '1',
      limit    = String(DEFAULT_LIMIT),
    } = req.query;

    // ── Validate severity ─────────────────────
    const severityStr = String(severity).toLowerCase();
    if (!ALLOWED_SEVERITIES.includes(severityStr as any)) {
      res.status(400).json({
        success: false,
        message: `Invalid severity filter`,
        requestId,
      });
      return;
    }

    // ── Validate pagination ───────────────────
    const pageNum  = Math.max(1, parseInt(String(page), 10) || 1);
    const limitNum = Math.min(
      MAX_LIMIT,
      Math.max(1, parseInt(String(limit), 10) || DEFAULT_LIMIT)
    );
    const skip = (pageNum - 1) * limitNum;

    // ── Build query ───────────────────────────
    const query: Record<string, any> = {};

    if (severityStr !== 'all') {
      query.severity = severityStr;
    }

    if (type && type !== 'all') {
      query.type = String(type);
    }

    // Date range
    if (dateFrom || dateTo) {
      query.createdAt = {};
      if (dateFrom) {
        const from = new Date(String(dateFrom));
        if (!isNaN(from.getTime())) {
          query.createdAt.$gte = from;
        }
      }
      if (dateTo) {
        const to = new Date(String(dateTo));
        if (!isNaN(to.getTime())) {
          query.createdAt.$lte = to;
        }
      }
    }

    // Search (email, masked IP, metadata)
    const searchStr = sanitizeSearch(search);
    if (searchStr) {
      const escaped = escapeRegex(searchStr);
      query.$or = [
        { email: { $regex: escaped, $options: 'i' } },
        { ip:    { $regex: escaped, $options: 'i' } },
        { 'metadata.action': { $regex: escaped, $options: 'i' } },
      ];
    }

    // ── Fetch events ──────────────────────────
    const [events, total] = await Promise.all([
      SecurityEvent.find(query)
        .select('-ipRaw -emailHash -ipHash -__v') // hide sensitive fields
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(limitNum)
        .lean(),
      SecurityEvent.countDocuments(query),
    ]);

    res.status(200).json({
      success: true,
      events,
      pagination: {
        page:       pageNum,
        limit:      limitNum,
        total,
        totalPages: Math.ceil(total / limitNum),
      },
      requestId,
    });
    return;

  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';

    await logSecurityEvent({
      type:     'system_error',
      severity: 'high',
      userId:   auth.id,
      email:    auth.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        action: 'security_events_fetch_failed',
        error:  errMsg.slice(0, 200),
      },
    });

    res.status(500).json({
      success: false,
      message: 'Failed to fetch security events',
      requestId,
    });
    return;
  }
}

// pages/api/admin/security/stats.ts
// 🔒 ENTERPRISE SECURITY STATS API — HIGHRISE.PK
// Security Level: MAXIMUM | Admin Only | Dashboard Stats
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   GET → Security dashboard stat cards:
//     • Total events (24h / 7d / 30d)
//     • Events by severity breakdown
//     • Events by type category breakdown
//     • Threat summary (brute force, suspicious, blocked)
//     • Top event types (last 24h)
//     • Hourly trend (last 24h — for chart)
//     • Recent critical events (last 5)
//
// SECURITY:
//   ✅ requireAdmin() auth guard
//   ✅ rateLimitAdmin() rate limiting
//   ✅ No raw PII exposed in any stat
//   ✅ Aggregation only — no documents returned raw
//   ✅ logSecurityEvent audit logging
//   ✅ Security headers + request ID
//   ✅ Generic error messages
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect                                 from '@/lib/db';
import SecurityEvent                             from '@/models/SecurityEvent';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ═══════════════════════════════════════════════════════════════
// 🔐 TYPES
// ═══════════════════════════════════════════════════════════════

interface SeverityBreakdown {
  low:      number;
  medium:   number;
  high:     number;
  critical: number;
}

interface CategoryBreakdown {
  auth:     number;
  account:  number;
  kyc:      number;
  admin:    number;
  security: number;
  system:   number;
  other:    number;
}

interface TopEventType {
  type:  string;
  count: number;
  label: string;
}

interface HourlyPoint {
  hour:     string; // "00" - "23"
  count:    number;
  critical: number;
  high:     number;
}

interface RecentCriticalEvent {
  _id:       string;
  type:      string;
  severity:  string;
  email?:    string;
  ip?:       string;
  metadata?: Record<string, unknown>;
  createdAt: string;
}

interface SecurityStatsResponse {
  success:   boolean;
  stats?:    {
    totals: {
      last24h: number;
      last7d:  number;
      last30d: number;
      allTime: number;
    };
    severity:  SeverityBreakdown;
    category:  CategoryBreakdown;
    topEvents: TopEventType[];
    hourly:    HourlyPoint[];
    threats: {
      bruteForceDetected:    number;
      suspiciousActivity:    number;
      rateLimitExceeded:     number;
      ipBlocked:             number;
      permissionDenied:      number;
      vpnDetected:           number;
    };
    recentCritical: RecentCriticalEvent[];
  };
  message?:  string;
  requestId: string;
}

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') {
    return forwarded.split(',')[0].trim();
  }
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(
  res: NextApiResponse,
  requestId: string
): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
}

/**
 * Map event type string to display label.
 */
function labelForType(type: string): string {
  const map: Record<string, string> = {
    login_success:             'Login Success',
    login_failed:              'Login Failed',
    logout:                    'Logout',
    session_expired:           'Session Expired',
    session_hijack_detected:   'Session Hijack',
    token_invalidated:         'Token Invalidated',
    password_reset_requested:  'Password Reset Request',
    password_reset_completed:  'Password Reset Done',
    password_change:           'Password Changed',
    account_locked:            'Account Locked',
    account_created:           'Account Created',
    account_suspended:         'Account Suspended',
    account_deleted:           'Account Deleted',
    email_verified:            'Email Verified',
    role_change:               'Role Changed',
    kyc_submitted:             'KYC Submitted',
    kyc_approved:              'KYC Approved',
    kyc_rejected:              'KYC Rejected',
    property_created:          'Property Created',
    property_flagged:          'Property Flagged',
    admin_login:               'Admin Login',
    admin_action:              'Admin Action',
    permission_denied:         'Permission Denied',
    system_error:              'System Error',
    bulk_action_performed:     'Bulk Action',
    brute_force_detected:      'Brute Force',
    suspicious_activity:       'Suspicious Activity',
    rate_limit_exceeded:       'Rate Limit Hit',
    vpn_detected:              'VPN Detected',
    geo_anomaly:               'Geo Anomaly',
    ip_blocked:                'IP Blocked',
  };
  return (
    map[type] ??
    type.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase())
  );
}

/**
 * Classify event type into category bucket.
 */
function categoryForType(type: string): keyof CategoryBreakdown {
  if ([
    'login_success', 'login_failed', 'logout',
    'session_expired', 'session_hijack_detected',
    'token_invalidated', 'password_reset_requested',
    'password_reset_completed', 'password_change',
    'account_locked', '2fa_enabled', '2fa_disabled',
    '2fa_success', '2fa_failed', 'admin_login',
  ].includes(type)) return 'auth';

  if ([
    'account_created', 'account_activated',
    'account_suspended', 'account_deleted',
    'email_verified', 'email_changed',
    'role_change', 'permission_granted',
    'permission_revoked',
  ].includes(type)) return 'account';

  if ([
    'kyc_submitted', 'kyc_approved', 'kyc_rejected',
    'kyc_document_uploaded', 'kyc_document_verified',
    'kyc_locked', 'developer_profile_created',
    'agent_profile_created',
  ].includes(type)) return 'kyc';

  if ([
    'admin_action', 'bulk_action_performed',
    'settings_changed', 'database_backup',
    'user_force_logout', 'user_impersonated',
  ].includes(type)) return 'admin';

  if ([
    'brute_force_detected', 'suspicious_activity',
    'rate_limit_exceeded', 'vpn_detected',
    'geo_anomaly', 'ip_blocked', 'permission_denied',
  ].includes(type)) return 'security';

  if ([
    'system_error',
  ].includes(type)) return 'system';

  return 'other';
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<SecurityStatsResponse>
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(
    req.headers['user-agent'] || 'unknown'
  ).slice(0, 500);

  // ─────────────────────────────────────────────
  // STEP 1: Method guard
  // ─────────────────────────────────────────────
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    res.status(405).json({
      success:   false,
      message:   'Method not allowed',
      requestId,
    });
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 2: Rate limit
  // ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: {
        action:   'security_stats_rate_limited',
        endpoint: '/api/admin/security/stats',
      },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 3: Admin auth
  // ─────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  await dbConnect();

  try {
    const now    = new Date();
    const now24h = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    const now7d  = new Date(now.getTime() - 7  * 24 * 60 * 60 * 1000);
    const now30d = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

    // ── Run all queries in parallel ───────────
    const [
      total24h,
      total7d,
      total30d,
      allTime,
      severityAgg,
      typeAgg,
      hourlyAgg,
      threats24h,
      recentCriticalDocs,
    ] = await Promise.all([

      // ── Total counts by window ────────────
      SecurityEvent.countDocuments({ createdAt: { $gte: now24h } }),
      SecurityEvent.countDocuments({ createdAt: { $gte: now7d  } }),
      SecurityEvent.countDocuments({ createdAt: { $gte: now30d } }),
      SecurityEvent.countDocuments({}),

      // ── Severity breakdown (last 30d) ─────
      SecurityEvent.aggregate([
        { $match: { createdAt: { $gte: now30d } } },
        {
          $group: {
            _id:   '$severity',
            count: { $sum: 1 },
          },
        },
      ]),

      // ── Type breakdown (last 24h) ─────────
      SecurityEvent.aggregate([
        { $match: { createdAt: { $gte: now24h } } },
        {
          $group: {
            _id:   '$type',
            count: { $sum: 1 },
          },
        },
        { $sort: { count: -1 } },
        { $limit: 15 },
      ]),

      // ── Hourly trend (last 24h) ───────────
      // Groups by hour bucket, counts total + critical + high
      SecurityEvent.aggregate([
        { $match: { createdAt: { $gte: now24h } } },
        {
          $group: {
            _id: {
              $dateToString: {
                format: '%H',
                date:   '$createdAt',
              },
            },
            count:    { $sum: 1 },
            critical: {
              $sum: {
                $cond: [{ $eq: ['$severity', 'critical'] }, 1, 0],
              },
            },
            high: {
              $sum: {
                $cond: [{ $eq: ['$severity', 'high'] }, 1, 0],
              },
            },
          },
        },
        { $sort: { _id: 1 } },
      ]),

      // ── Threat-specific counts (last 24h) ─
      SecurityEvent.aggregate([
        {
          $match: {
            createdAt: { $gte: now24h },
            type: {
              $in: [
                'brute_force_detected',
                'suspicious_activity',
                'rate_limit_exceeded',
                'ip_blocked',
                'permission_denied',
                'vpn_detected',
              ],
            },
          },
        },
        {
          $group: {
            _id:   '$type',
            count: { $sum: 1 },
          },
        },
      ]),

      // ── Recent critical events (last 5) ───
      SecurityEvent.find({
        severity: { $in: ['high', 'critical'] },
      })
        .select('-ipRaw -emailHash -ipHash -__v')
        .sort({ createdAt: -1 })
        .limit(5)
        .lean(),
    ]);

    // ── Build severity breakdown ───────────────
    const severity: SeverityBreakdown = {
      low:      0,
      medium:   0,
      high:     0,
      critical: 0,
    };
    for (const row of severityAgg) {
      const key = row._id as keyof SeverityBreakdown;
      if (key in severity) severity[key] = row.count;
    }

    // ── Build category breakdown from type agg ─
    const category: CategoryBreakdown = {
      auth:     0,
      account:  0,
      kyc:      0,
      admin:    0,
      security: 0,
      system:   0,
      other:    0,
    };

    const topEvents: TopEventType[] = [];
    for (const row of typeAgg) {
      const cat = categoryForType(row._id as string);
      category[cat] += row.count;
      topEvents.push({
        type:  row._id as string,
        count: row.count,
        label: labelForType(row._id as string),
      });
    }

    // ── Build hourly trend ─────────────────────
    // Fill all 24 hours (0-23) even if no events
    const hourlyMap = new Map<string, HourlyPoint>();
    for (let h = 0; h < 24; h++) {
      const hr = String(h).padStart(2, '0');
      hourlyMap.set(hr, { hour: hr, count: 0, critical: 0, high: 0 });
    }
    for (const row of hourlyAgg) {
      const hr = String(row._id).padStart(2, '0');
      hourlyMap.set(hr, {
        hour:     hr,
        count:    row.count,
        critical: row.critical,
        high:     row.high,
      });
    }
    const hourly = Array.from(hourlyMap.values()).sort(
      (a, b) => parseInt(a.hour) - parseInt(b.hour)
    );

    // ── Build threats breakdown ────────────────
    const threatMap = new Map<string, number>();
    for (const row of threats24h) {
      threatMap.set(row._id as string, row.count);
    }
    const threats = {
      bruteForceDetected: threatMap.get('brute_force_detected') ?? 0,
      suspiciousActivity: threatMap.get('suspicious_activity')  ?? 0,
      rateLimitExceeded:  threatMap.get('rate_limit_exceeded')  ?? 0,
      ipBlocked:          threatMap.get('ip_blocked')           ?? 0,
      permissionDenied:   threatMap.get('permission_denied')    ?? 0,
      vpnDetected:        threatMap.get('vpn_detected')         ?? 0,
    };

    // ── Build recent critical list ─────────────
    const recentCritical: RecentCriticalEvent[] = (
      recentCriticalDocs as any[]
    ).map((ev) => ({
      _id:       String(ev._id),
      type:      ev.type       || 'unknown',
      severity:  ev.severity   || 'high',
      email:     ev.email      || undefined,
      ip:        ev.ip         || undefined,
      metadata:  ev.metadata   || undefined,
      createdAt: ev.createdAt
        ? new Date(ev.createdAt).toISOString()
        : new Date().toISOString(),
    }));

    res.status(200).json({
      success: true,
      stats: {
        totals: {
          last24h: total24h,
          last7d:  total7d,
          last30d: total30d,
          allTime,
        },
        severity,
        category,
        topEvents,
        hourly,
        threats,
        recentCritical,
      },
      requestId,
    });
    return;

  } catch (error: unknown) {
    const errMsg = error instanceof Error
      ? error.message
      : 'Unknown error';

    await logSecurityEvent({
      type:     'system_error',
      severity: 'high',
      userId:   auth.id,
      email:    auth.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        action: 'security_stats_fetch_failed',
        error:  errMsg.slice(0, 200),
      },
    });

    res.status(500).json({
      success:   false,
      message:   'Failed to fetch security stats',
      requestId,
    });
    return;
  }
}

// pages/api/admin/subscribers/[id].ts

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import NewsletterSubscriber from '@/models/NewsletterSubscriber';
import { requireAdmin } from '@/lib/requireAuth';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  await dbConnect();

  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return res.status(400).json({
      success: false,
      message: 'Subscriber ID is required',
    });
  }

  // GET - Get single subscriber
  if (req.method === 'GET') {
    try {
      const subscriber = await NewsletterSubscriber.findById(id).lean();

      if (!subscriber) {
        return res.status(404).json({
          success: false,
          message: 'Subscriber not found',
        });
      }

      return res.status(200).json({
        success: true,
        subscriber,
      });
    } catch (error: any) {
      console.error('Error fetching subscriber:', error);
      return res.status(500).json({
        success: false,
        message: 'Error fetching subscriber',
        error: error.message,
      });
    }
  }

  // PUT - Update subscriber
  if (req.method === 'PUT') {
    try {
      const { name, status, tags } = req.body;

      const subscriber = await NewsletterSubscriber.findById(id);

      if (!subscriber) {
        return res.status(404).json({
          success: false,
          message: 'Subscriber not found',
        });
      }

      // Update fields
      if (name !== undefined) subscriber.name = name;
      if (status !== undefined) {
        subscriber.status = status;
        if (status === 'unsubscribed') {
          subscriber.unsubscribedAt = new Date();
        } else if (status === 'active') {
          subscriber.unsubscribedAt = undefined;
        }
      }
      if (tags !== undefined) subscriber.tags = tags;

      await subscriber.save();

      return res.status(200).json({
        success: true,
        message: 'Subscriber updated successfully',
        subscriber,
      });
    } catch (error: any) {
      console.error('Error updating subscriber:', error);
      return res.status(500).json({
        success: false,
        message: 'Error updating subscriber',
        error: error.message,
      });
    }
  }

  // DELETE - Delete subscriber
  if (req.method === 'DELETE') {
    try {
      const subscriber = await NewsletterSubscriber.findByIdAndDelete(id);

      if (!subscriber) {
        return res.status(404).json({
          success: false,
          message: 'Subscriber not found',
        });
      }

      return res.status(200).json({
        success: true,
        message: 'Subscriber deleted successfully',
      });
    } catch (error: any) {
      console.error('Error deleting subscriber:', error);
      return res.status(500).json({
        success: false,
        message: 'Error deleting subscriber',
        error: error.message,
      });
    }
  }

  return res.status(405).json({
    success: false,
    message: 'Method not allowed',
  });
}

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import NewsletterSubscriber from '@/models/NewsletterSubscriber';
import { requireAdmin } from '@/lib/requireAuth';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const auth = await requireAdmin(req, res);
  if (!auth) return;
  if (req.method !== 'GET') {
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  await dbConnect();

  try {
    const { status = 'all', page = '1', limit = '50' } = req.query;

    const query: any = {};
    if (status !== 'all') {
      query.status = status;
    }

    const pageNum = parseInt(page as string);
    const limitNum = parseInt(limit as string);
    const skip = (pageNum - 1) * limitNum;

    const [subscribers, total, activeCount, unsubscribedCount] = await Promise.all([
      NewsletterSubscriber.find(query)
        .sort({ subscribedAt: -1 })
        .skip(skip)
        .limit(limitNum)
        .lean(),
      NewsletterSubscriber.countDocuments(query),
      NewsletterSubscriber.countDocuments({ status: 'active' }),
      NewsletterSubscriber.countDocuments({ status: 'unsubscribed' }),
    ]);

    return res.status(200).json({
      success: true,
      subscribers,
      stats: {
        total: activeCount + unsubscribedCount,
        active: activeCount,
        unsubscribed: unsubscribedCount,
      },
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        totalPages: Math.ceil(total / limitNum),
      },
    });

  } catch (error: any) {
    console.error('Error fetching subscribers:', error);
    return res.status(500).json({
      success: false,
      message: 'Error fetching subscribers',
      error: error.message,
    });
  }
}

// pages/api/admin/units/[id].ts
import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import dbConnect from '@/lib/dbConnect';
import Unit from '@/models/Unit';
import { requireAdmin } from '@/lib/requireAdmin';
import {
  rateLimitAdmin,
  sendRateLimitResponse,
  setRateLimitHeaders,
} from '@/lib/rateLimit';
import { logSecurityEvent } from '@/lib/security/logSecurityEvent';
import { logAdminAction } from '@/lib/logAdminAction';
import { syncUnitTypeBreakdown } from '@/lib/units/syncUnitTypeBreakdown';
import { z } from 'zod';

// ════════════════════════════════════════════════════
// ZOD SCHEMAS
// ════════════════════════════════════════════════════

const AdminUnitUpdateSchema = z.object({
  // Visibility & verification
  isPublished:    z.boolean().optional(),
  isVerified:     z.boolean().optional(),
  isFeatured:     z.boolean().optional(),
  isHotDeal:      z.boolean().optional(),
  isPriceDropped: z.boolean().optional(),

  // Status override (admin can change any status)
  status: z.enum([
    'available',
    'reserved',
    'sold',
    'on_hold',
    'cancelled',
  ]).optional(),

  // Price override
  price:          z.number().min(0).optional(),
  previousPrice:  z.number().min(0).optional(),
  priceLabel:     z.string().max(100).optional(),

  // Admin notes
  adminNotes:     z.string().max(2000).optional(),

  // Reason (required for destructive actions)
  reason:         z.string().max(500).optional(),
});

const AdminTrashSchema = z.object({
  reason: z.string().min(5).max(500),
});

const AdminRestoreSchema = z.object({
  reason: z.string().min(5).max(500).optional(),
});

// ════════════════════════════════════════════════════
// HANDLER
// ════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // ── ID guard ──
  const { id } = req.query;
  if (!id || typeof id !== 'string') {
    return res.status(400).json({ success: false, message: 'Unit ID is required' });
  }
  if (!mongoose.isValidObjectId(id)) {
    return res.status(400).json({ success: false, message: 'Invalid unit ID' });
  }

  // ── Admin guard ──
  const admin = await requireAdmin(req, res);
  if (!admin) return;

  // ── Rate limit ──
  const rl = await rateLimitAdmin(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) return sendRateLimitResponse(res, rl);

  // ── DB ──
  await dbConnect();

  // ════════════════════════════════════════════════════
  // GET — Single unit full detail (admin view)
  // ════════════════════════════════════════════════════
  if (req.method === 'GET') {
    try {
      const unit = await Unit.findById(id)
        .populate('projectId',  'projectName slug city area status developerId')
        .populate('developerId', 'companyName email slug status')
        .lean() as Record<string, unknown> | null;

      if (!unit) {
        return res.status(404).json({
          success: false,
          message: 'Unit not found',
        });
      }

      // Admin sees ALL fields including soft-deleted
      return res.status(200).json({
        success: true,
        data: { unit },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'medium',
        userId:   admin.id,
        metadata: {
          action: 'admin_unit_fetch_failed',
          unitId: id,
          reason: error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ════════════════════════════════════════════════════
  // PATCH — Admin update unit
  // ════════════════════════════════════════════════════
  if (req.method === 'PATCH') {
    try {
      // Zod validation
      const parsed = AdminUnitUpdateSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid request data',
          errors: parsed.error.flatten().fieldErrors,
        });
      }

      const updates = parsed.data;

      // Find existing unit (including deleted — admin can restore)
      const existingUnit = await Unit.findById(id).lean() as {
        _id:        mongoose.Types.ObjectId;
        projectId:  mongoose.Types.ObjectId;
        developerId: mongoose.Types.ObjectId;
        unitNumber?: string;
        unitType?:  string;
        status?:    string;
        price?:     number;
        isPublished?: boolean;
        isVerified?:  boolean;
        isFeatured?:  boolean;
        isDeleted?:   boolean;
      } | null;

      if (!existingUnit) {
        return res.status(404).json({
          success: false,
          message: 'Unit not found',
        });
      }

      // ── Build update payload ──
      const updateData: Record<string, unknown> = {};
      const changedFields: string[] = [];

      if (updates.isPublished !== undefined) {
        updateData.isPublished = updates.isPublished;
        changedFields.push('isPublished');
      }
      if (updates.isVerified !== undefined) {
        updateData.isVerified = updates.isVerified;
        // Auto-publish when verified
        if (updates.isVerified && !existingUnit.isPublished) {
          updateData.isPublished = true;
          changedFields.push('isPublished');
        }
        changedFields.push('isVerified');
      }
      if (updates.isFeatured !== undefined) {
        updateData.isFeatured = updates.isFeatured;
        changedFields.push('isFeatured');
      }
      if (updates.isHotDeal !== undefined) {
        updateData.isHotDeal = updates.isHotDeal;
        changedFields.push('isHotDeal');
      }
      if (updates.isPriceDropped !== undefined) {
        updateData.isPriceDropped = updates.isPriceDropped;
        changedFields.push('isPriceDropped');
      }
      if (updates.status !== undefined) {
        updateData.status = updates.status;
        updateData.lastStatusChangedAt = new Date();
        changedFields.push('status');
      }
      if (updates.price !== undefined) {
        // Capture previous price before overwrite
        if (existingUnit.price && existingUnit.price !== updates.price) {
          updateData.previousPrice = existingUnit.price;
        }
        updateData.price = updates.price;
        changedFields.push('price');
      }
      if (updates.previousPrice !== undefined) {
        updateData.previousPrice = updates.previousPrice;
        changedFields.push('previousPrice');
      }
      if (updates.priceLabel !== undefined) {
        updateData.priceLabel = updates.priceLabel;
        changedFields.push('priceLabel');
      }
      if (updates.adminNotes !== undefined) {
        updateData.adminNotes = updates.adminNotes;
        changedFields.push('adminNotes');
      }

      if (changedFields.length === 0) {
        return res.status(400).json({
          success: false,
          message: 'No valid fields provided to update',
        });
      }

      // ── Apply update ──
      const updated = await Unit.findByIdAndUpdate(
        id,
        { $set: updateData },
        { new: true, runValidators: false }
      ).lean();

      // ── Sync project breakdown ──
      syncUnitTypeBreakdown(String(existingUnit.projectId)).catch(() => {
        // Silent
      });

      // ── Determine audit severity ──
      const severity =
        updates.isVerified === false ||
        updates.status === 'cancelled'
          ? 'medium'
          : 'low';

      // ── Security event ──
      await logSecurityEvent({
        type:     'admin_action',
        severity,
        userId:   admin.id,
        metadata: {
          action:        'admin_unit_updated',
          unitId:        id,
          unitNumber:    existingUnit.unitNumber,
          projectId:     String(existingUnit.projectId),
          changedFields,
          reason:        updates.reason,
        },
      });

      // ── Admin audit log ──
      await logAdminAction({
        action:      'unit_updated' as any,
        entityType:  'unit' as any,
        adminId:     admin.id,
        adminEmail:  admin.email,
        entityId:    id,
        entityLabel: existingUnit.unitNumber,
        previousValue: JSON.stringify({
          status:      existingUnit.status,
          isPublished: existingUnit.isPublished,
          isVerified:  existingUnit.isVerified,
          price:       existingUnit.price,
        }),
        newValue: JSON.stringify(updateData),
        reason:   updates.reason,
        meta: {
          changedFields,
          projectId: String(existingUnit.projectId),
        },
        ip:        req.headers['x-forwarded-for']?.toString() ?? '',
        userAgent: req.headers['user-agent'] ?? '',
      });

      return res.status(200).json({
        success: true,
        message: 'Unit updated successfully',
        data: {
          unitId:        id,
          changedFields,
          unit:          updated,
        },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   admin.id,
        metadata: {
          action: 'admin_unit_update_failed',
          unitId: id,
          reason: error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ════════════════════════════════════════════════════
  // DELETE — Soft delete (trash) unit
  // ════════════════════════════════════════════════════
  if (req.method === 'DELETE') {
    try {
      // Zod validation
      const parsed = AdminTrashSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: 'A reason is required to delete a unit',
          errors: parsed.error.flatten().fieldErrors,
        });
      }

      const { reason } = parsed.data;

      // Find unit
      const unit = await Unit.findOne({
        _id:       new mongoose.Types.ObjectId(id),
        isDeleted: { $ne: true },
      }).lean() as {
        _id:        mongoose.Types.ObjectId;
        projectId:  mongoose.Types.ObjectId;
        developerId: mongoose.Types.ObjectId;
        unitNumber?: string;
        status?:    string;
      } | null;

      if (!unit) {
        return res.status(404).json({
          success: false,
          message: 'Unit not found or already deleted',
        });
      }

      // Soft delete
      await Unit.findByIdAndUpdate(id, {
        $set: {
          isDeleted:  true,
          deletedAt:  new Date(),
          isPublished: false,
        },
      });

      // Sync project breakdown
      syncUnitTypeBreakdown(String(unit.projectId)).catch(() => {
        // Silent
      });

      // Security event
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'high',
        userId:   admin.id,
        metadata: {
          action:     'admin_unit_trashed',
          unitId:     id,
          unitNumber: unit.unitNumber,
          projectId:  String(unit.projectId),
          reason,
        },
      });

      // Admin audit log
      await logAdminAction({
        action:      'unit_deleted' as any,
        entityType:  'unit' as any,
        adminId:     admin.id,
        adminEmail:  admin.email,
        entityId:    id,
        entityLabel: unit.unitNumber,
        previousValue: unit.status,
        newValue:    'deleted',
        reason,
        ip:        req.headers['x-forwarded-for']?.toString() ?? '',
        userAgent: req.headers['user-agent'] ?? '',
      });

      return res.status(200).json({
        success: true,
        message: 'Unit deleted successfully',
        data: { unitId: id },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   admin.id,
        metadata: {
          action: 'admin_unit_trash_failed',
          unitId: id,
          reason: error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ════════════════════════════════════════════════════
  // PUT — Restore soft-deleted unit
  // ════════════════════════════════════════════════════
  if (req.method === 'PUT') {
    try {
      // Zod validation
      const parsed = AdminRestoreSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid request data',
          errors: parsed.error.flatten().fieldErrors,
        });
      }

      const { reason } = parsed.data;

      // Find deleted unit
      const unit = await Unit.findOne({
        _id:       new mongoose.Types.ObjectId(id),
        isDeleted: true,
      }).lean() as {
        _id:        mongoose.Types.ObjectId;
        projectId:  mongoose.Types.ObjectId;
        unitNumber?: string;
      } | null;

      if (!unit) {
        return res.status(404).json({
          success: false,
          message: 'Unit not found or not deleted',
        });
      }

      // Restore — unpublished by default (admin must re-review)
      await Unit.findByIdAndUpdate(id, {
        $set: {
          isDeleted:   false,
          deletedAt:   null,
          isPublished: false,
        },
      });

      // Sync project breakdown
      syncUnitTypeBreakdown(String(unit.projectId)).catch(() => {
        // Silent
      });

      // Security event
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'medium',
        userId:   admin.id,
        metadata: {
          action:     'admin_unit_restored',
          unitId:     id,
          unitNumber: unit.unitNumber,
          projectId:  String(unit.projectId),
          reason,
        },
      });

      // Admin audit log
      await logAdminAction({
        action:      'unit_restored' as any,
        entityType:  'unit' as any,
        adminId:     admin.id,
        adminEmail:  admin.email,
        entityId:    id,
        entityLabel: unit.unitNumber,
        previousValue: 'deleted',
        newValue:    'restored',
        reason,
        ip:        req.headers['x-forwarded-for']?.toString() ?? '',
        userAgent: req.headers['user-agent'] ?? '',
      });

      return res.status(200).json({
        success: true,
        message: 'Unit restored successfully',
        data: { unitId: id },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   admin.id,
        metadata: {
          action: 'admin_unit_restore_failed',
          unitId: id,
          reason: error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ── Method not allowed ──
  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

// pages/api/admin/units/index.ts
import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import dbConnect from '@/lib/dbConnect';
import Unit from '@/models/Unit';
import { requireAdmin } from '@/lib/requireAdmin';
import {
  rateLimitAdmin,
  sendRateLimitResponse,
  setRateLimitHeaders,
} from '@/lib/rateLimit';
import { logSecurityEvent } from '@/lib/security/logSecurityEvent';
import { logAdminAction } from '@/lib/logAdminAction';
import { z } from 'zod';

// ════════════════════════════════════════════════════
// ZOD SCHEMAS
// ════════════════════════════════════════════════════

const BulkActionSchema = z.object({
  action: z.enum([
    'publish',
    'unpublish',
    'verify',
    'unverify',
    'feature',
    'unfeature',
    'trash',
    'restore',
  ]),
  unitIds: z.array(z.string().min(24).max(24)).min(1).max(50),
  reason:  z.string().max(500).optional(),
});

// ════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════

function buildAdminUnitFilter(
  query: NextApiRequest['query']
): Record<string, unknown> {
  const filter: Record<string, unknown> = {};

  // Deleted filter — default shows non-deleted only
  const showDeleted = query.deleted === 'true';
  const showAll     = query.all === 'true';
  if (!showAll) {
    filter.isDeleted = showDeleted ? true : { $ne: true };
  }

  // Status filter
  const status = typeof query.status === 'string' ? query.status : '';
  const validStatuses = ['available', 'reserved', 'sold', 'on_hold', 'cancelled'];
  if (status && validStatuses.includes(status)) {
    filter.status = status;
  }

  // Category filter
  const category = typeof query.category === 'string' ? query.category : '';
  if (category && ['residential', 'commercial'].includes(category)) {
    filter.category = category;
  }

  // Unit type filter
  const unitType = typeof query.unitType === 'string' ? query.unitType : '';
  if (unitType) filter.unitType = unitType;

  // Published filter
  const published = typeof query.published === 'string' ? query.published : '';
  if (published === 'true')  filter.isPublished = true;
  if (published === 'false') filter.isPublished = false;

  // Verified filter
  const verified = typeof query.verified === 'string' ? query.verified : '';
  if (verified === 'true')  filter.isVerified = true;
  if (verified === 'false') filter.isVerified = false;

  // Featured filter
  const featured = typeof query.featured === 'string' ? query.featured : '';
  if (featured === 'true') filter.isFeatured = true;

  // Project filter
  const projectId = typeof query.projectId === 'string' ? query.projectId : '';
  if (projectId && mongoose.isValidObjectId(projectId)) {
    filter.projectId = new mongoose.Types.ObjectId(projectId);
  }

  // Developer filter
  const developerId = typeof query.developerId === 'string' ? query.developerId : '';
  if (developerId && mongoose.isValidObjectId(developerId)) {
    filter.developerId = new mongoose.Types.ObjectId(developerId);
  }

  // City filter (denormalized on unit)
  const city = typeof query.city === 'string' ? query.city.trim() : '';
  if (city) filter.city = { $regex: new RegExp(city.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i') };

  // Price range
  const minPrice = typeof query.minPrice === 'string' ? Number(query.minPrice) : NaN;
  const maxPrice = typeof query.maxPrice === 'string' ? Number(query.maxPrice) : NaN;
  if (Number.isFinite(minPrice) || Number.isFinite(maxPrice)) {
    const priceFilter: Record<string, number> = {};
    if (Number.isFinite(minPrice) && minPrice >= 0) priceFilter.$gte = minPrice;
    if (Number.isFinite(maxPrice) && maxPrice >= 0) priceFilter.$lte = maxPrice;
    if (Object.keys(priceFilter).length > 0) filter.price = priceFilter;
  }

  // Date range
  const from = typeof query.from === 'string' ? query.from : '';
  const to   = typeof query.to   === 'string' ? query.to   : '';
  if (from || to) {
    const dateFilter: Record<string, Date> = {};
    if (from) {
      const d = new Date(from);
      if (!isNaN(d.getTime())) dateFilter.$gte = d;
    }
    if (to) {
      const d = new Date(to);
      if (!isNaN(d.getTime())) dateFilter.$lte = d;
    }
    if (Object.keys(dateFilter).length > 0) filter.createdAt = dateFilter;
  }

  // Text search
  const q = typeof query.q === 'string' ? query.q.trim().slice(0, 60) : '';
  if (q) {
    const safe = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const rx = new RegExp(safe, 'i');
    filter.$or = [
      { unitNumber:   rx },
      { title:        rx },
      { unitType:     rx },
      { unitTypeName: rx },
      { tower:        rx },
      { floorName:    rx },
    ];
  }

  return filter;
}

// ════════════════════════════════════════════════════
// HANDLER
// ════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // ── Admin guard ──
  const admin = await requireAdmin(req, res);
  if (!admin) return;

  // ── Rate limit ──
  const rl = await rateLimitAdmin(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) return sendRateLimitResponse(res, rl);

  // ── DB ──
  await dbConnect();

  // ════════════════════════════════════════════════════
  // GET — List all units with filters + stats
  // ════════════════════════════════════════════════════
  if (req.method === 'GET') {
    try {
      // Pagination
      const page  = Math.max(1, parseInt(String(req.query.page  ?? '1'),  10) || 1);
      const limit = Math.min(100, Math.max(1, parseInt(String(req.query.limit ?? '50'), 10) || 50));
      const skip  = (page - 1) * limit;

      // Sort
      const sortField = String(req.query.sortBy ?? 'createdAt');
      const sortDir   = String(req.query.sortOrder ?? 'desc') === 'asc' ? 1 : -1;
      const allowedSortFields = new Set([
        'createdAt', 'updatedAt', 'price',
        'area', 'unitNumber', 'floorNumber',
        'status', 'views', 'inquiryCount',
      ]);
      const sort: Record<string, 1 | -1> = {
        [allowedSortFields.has(sortField) ? sortField : 'createdAt']: sortDir as 1 | -1,
      };

      // Filter
      const filter = buildAdminUnitFilter(req.query);

      // Execute in parallel
      const [units, totalCount, statsAgg] = await Promise.all([

        Unit.find(filter)
          .select([
            '_id', 'projectId', 'developerId',
            'unitNumber', 'title', 'unitType', 'unitTypeName',
            'category', 'status', 'isPublished', 'isVerified',
            'isFeatured', 'isHotDeal', 'isPriceDropped',
            'price', 'area', 'areaUnit',
            'bedrooms', 'bathrooms',
            'floorNumber', 'floorName', 'tower',
            'isCorner', 'facing',
            'images',
            'views', 'inquiryCount',
            'isDeleted', 'deletedAt',
            'createdAt', 'updatedAt',
          ].join(' '))
          .populate('projectId', 'projectName slug city')
          .populate('developerId', 'companyName email')
          .sort(sort)
          .skip(skip)
          .limit(limit)
          .lean(),

        Unit.countDocuments(filter),

        // Platform-wide unit stats (admin overview)
        Unit.aggregate([
          { $match: { isDeleted: { $ne: true } } },
          {
            $group: {
              _id:            null,
              totalUnits:     { $sum: 1 },
              availableUnits: { $sum: { $cond: [{ $eq: ['$status', 'available'] }, 1, 0] } },
              reservedUnits:  { $sum: { $cond: [{ $eq: ['$status', 'reserved'] }, 1, 0] } },
              soldUnits:      { $sum: { $cond: [{ $eq: ['$status', 'sold'] }, 1, 0] } },
              onHoldUnits:    { $sum: { $cond: [{ $eq: ['$status', 'on_hold'] }, 1, 0] } },
              publishedUnits: { $sum: { $cond: [{ $eq: ['$isPublished', true] }, 1, 0] } },
              verifiedUnits:  { $sum: { $cond: [{ $eq: ['$isVerified', true] }, 1, 0] } },
              featuredUnits:  { $sum: { $cond: [{ $eq: ['$isFeatured', true] }, 1, 0] } },
              deletedUnits:   { $sum: { $cond: [{ $eq: ['$isDeleted', true] }, 1, 0] } },
              totalViews:     { $sum: '$views' },
              totalInquiries: { $sum: '$inquiryCount' },
              avgPrice:       { $avg: '$price' },
              minPrice:       { $min: '$price' },
              maxPrice:       { $max: '$price' },
            },
          },
        ]).option({ maxTimeMS: 3000 }),
      ]);

      const stats = statsAgg?.[0] ?? {
        totalUnits: 0, availableUnits: 0, reservedUnits: 0,
        soldUnits: 0, onHoldUnits: 0, publishedUnits: 0,
        verifiedUnits: 0, featuredUnits: 0, deletedUnits: 0,
        totalViews: 0, totalInquiries: 0,
        avgPrice: 0, minPrice: 0, maxPrice: 0,
      };

      const totalPages = Math.max(1, Math.ceil(totalCount / limit));

      return res.status(200).json({
        success: true,
        data: {
          units,
          pagination: {
            page,
            limit,
            totalCount,
            totalPages,
            hasMore: page < totalPages,
          },
          stats,
        },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   admin.id,
        metadata: {
          action: 'admin_units_list_failed',
          reason: error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ════════════════════════════════════════════════════
  // POST — Bulk action on multiple units
  // ════════════════════════════════════════════════════
  if (req.method === 'POST') {
    try {
      // Zod validation
      const parsed = BulkActionSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid request data',
          errors: parsed.error.flatten().fieldErrors,
        });
      }

      const { action, unitIds, reason } = parsed.data;

      // Validate all IDs are valid ObjectIds
      const invalidIds = unitIds.filter((id) => !mongoose.isValidObjectId(id));
      if (invalidIds.length > 0) {
        return res.status(400).json({
          success: false,
          message: `Invalid unit IDs: ${invalidIds.join(', ')}`,
        });
      }

      const objectIds = unitIds.map((id) => new mongoose.Types.ObjectId(id));

      // Build update based on action
      let updateData: Record<string, unknown> = {};
      let filterExtra: Record<string, unknown> = {};

      switch (action) {
        case 'publish':
          updateData = { isPublished: true };
          filterExtra = { isDeleted: { $ne: true } };
          break;

        case 'unpublish':
          updateData = { isPublished: false };
          filterExtra = { isDeleted: { $ne: true } };
          break;

        case 'verify':
          updateData = { isVerified: true, isPublished: true };
          filterExtra = { isDeleted: { $ne: true } };
          break;

        case 'unverify':
          updateData = { isVerified: false };
          filterExtra = { isDeleted: { $ne: true } };
          break;

        case 'feature':
          updateData = { isFeatured: true };
          filterExtra = { isDeleted: { $ne: true } };
          break;

        case 'unfeature':
          updateData = { isFeatured: false };
          filterExtra = { isDeleted: { $ne: true } };
          break;

        case 'trash':
          updateData = {
            isDeleted: true,
            deletedAt: new Date(),
          };
          filterExtra = { isDeleted: { $ne: true } };
          break;

        case 'restore':
          updateData = {
            isDeleted: false,
            deletedAt: null,
          };
          filterExtra = { isDeleted: true };
          break;

        default:
          return res.status(400).json({
            success: false,
            message: 'Invalid action',
          });
      }

      // Execute bulk update
      const result = await Unit.updateMany(
        {
          _id: { $in: objectIds },
          ...filterExtra,
        },
        { $set: updateData }
      );

      // Audit log
      await logSecurityEvent({
        type:     'bulk_action_performed',
        severity: action === 'trash' ? 'high' : 'medium',
        userId:   admin.id,
        metadata: {
          action:        `admin_units_bulk_${action}`,
          unitIds,
          unitCount:     unitIds.length,
          affectedCount: result.modifiedCount,
          reason,
        },
      });

      await logAdminAction({
        action:      'bulk_action_performed' as any,
        entityType:  'unit' as any,
        adminId:     admin.id,
        adminEmail:  admin.email,
        entityLabel: `${result.modifiedCount} units`,
        newValue:    action,
        reason,
        meta: {
          unitIds,
          bulkAction:    action,
          affectedCount: result.modifiedCount,
        },
        ip:        req.headers['x-forwarded-for']?.toString() ?? '',
        userAgent: req.headers['user-agent'] ?? '',
      });

      return res.status(200).json({
        success: true,
        message: `Bulk ${action} completed successfully`,
        data: {
          action,
          requestedCount: unitIds.length,
          affectedCount:  result.modifiedCount,
        },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   admin.id,
        metadata: {
          action: 'admin_units_bulk_action_failed',
          reason: error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ── Method not allowed ──
  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

// pages/api/agent/profile.ts
// ═══════════════════════════════════════════════════════════════
// AGENT PROFILE API (PRIVATE) — Highrise.pk
// 🔒 ENTERPRISE-GRADE | Session Only | No Public Access
// ═══════════════════════════════════════════════════════════════
//
// GET    → Read own AgentProfile (private)
// PATCH  → Update own profile (whitelisted fields only)
// DELETE → Soft delete own profile
//
// POST removed — profile creation is via /api/onboarding/business
// Phone is immutable — KYC-linked, change requires admin
// Status/verification fields are admin-only
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from "next";
import { Types } from "mongoose";

import dbConnect from "@/lib/dbConnect";
import { requireAuth } from "@/lib/requireAuth";
import { rateLimitApi, rateLimitApiWrite } from "@/lib/rateLimit";
import { logSecurityEvent } from "@/lib/security/logSecurityEvent";

import AgentProfile from "@/models/AgentProfile";
import User from "@/models/User";

// ═══════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════

interface ApiResponse {
  success: boolean;
  message?: string;
  requestId: string;
  profile?: Record<string, unknown> | null;
}

// Lean shape for the profile ownership check
interface ProfileOwnershipLean {
  _id: Types.ObjectId;
  user: Types.ObjectId;
  status: string;
  isDeleted: boolean;
}

// Valid enums — must match AgentProfile schema exactly
const VALID_AGENT_TYPES   = ["individual", "agency", "freelance"] as const;
const VALID_AGENCY_SIZES  = ["solo", "small", "medium", "large"] as const;
const VALID_SPECIALIZATIONS = [
  "residential", "commercial", "plots", "rental", "all",
] as const;

type AgentTypeValue        = typeof VALID_AGENT_TYPES[number];
type AgentSizeValue        = typeof VALID_AGENCY_SIZES[number];
type SpecializationValue   = typeof VALID_SPECIALIZATIONS[number];

// ═══════════════════════════════════════════════════════════════
// SECURITY HEADERS
// ═══════════════════════════════════════════════════════════════

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader("X-Request-Id", requestId);
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "DENY");
  res.setHeader("Referrer-Policy", "same-origin");
  res.setHeader(
    "Permissions-Policy",
    "geolocation=(), microphone=(), camera=()"
  );
  res.setHeader("Cache-Control", "no-store, max-age=0");
  res.setHeader("Pragma", "no-cache");
}

// ═══════════════════════════════════════════════════════════════
// SANITIZATION HELPERS
// ═══════════════════════════════════════════════════════════════

function safeText(v: unknown, max = 120): string {
  return String(v ?? "").trim().slice(0, max);
}

function safeUrl(v: unknown): string {
  const s = String(v ?? "").trim().slice(0, 500);
  if (!s) return "";
  if (!/^https?:\/\//i.test(s)) return "";   // Reject non-http URLs
  return s;
}

function safeStringArray(v: unknown, maxItems = 20, maxLen = 80): string[] {
  if (!Array.isArray(v)) return [];
  return v
    .map((x) => String(x ?? "").trim().slice(0, maxLen))
    .filter(Boolean)
    .slice(0, maxItems);
}

function safeBoolean(v: unknown): boolean | undefined {
  if (v === true || v === "true")  return true;
  if (v === false || v === "false") return false;
  return undefined;
}

function safeInt(v: unknown, min: number, max: number): number | undefined {
  const n = Number(v);
  if (!Number.isFinite(n)) return undefined;
  return Math.max(min, Math.min(max, Math.floor(n)));
}

function isValidEnum<T extends string>(
  v: unknown,
  values: readonly T[]
): v is T {
  return typeof v === "string" && (values as readonly string[]).includes(v);
}

// ═══════════════════════════════════════════════════════════════
// SELECT FIELDS — returned to agent (no encrypted fields)
// ═══════════════════════════════════════════════════════════════

const AGENT_SELECT_FIELDS = [
  "_id",
  "slug",
  "displayName",
  "tagline",
  "about",
  "agentType",
  "agencyName",
  "agencySize",
  "email",
  "city",
  "operatingCities",
  "specializations",
  "languages",
  "experience",
  "serviceAreas",
  "socialLinks",
  "businessHours",
  "isAvailable",
  "availabilityNote",
  "status",
  "verificationLevel",
  "badges",
  "isPremium",
  "isFeatured",
  "trustScore",
  "ratings",
  "stats",
  // V6.8.11: Documents (profile, cover, license, cnic for admin, logo)
  "documents.profilePhoto",
  "documents.coverPhoto",
  // V6.8.11: Agency logo (top-level field for agency accounts)
  "agencyLogo",
  // V6.8.11: Office verification (address, city, coordinates)
  // Critical for edit page to show existing office location on map
  "officeVerification",
  "memberSince",
  "createdAt",
  "updatedAt",
].join(" ");

// ═══════════════════════════════════════════════════════════════
// CNIC GATE
// ═══════════════════════════════════════════════════════════════

interface UserLean {
  _id: Types.ObjectId;
  role: string;
  status: string;
  isDeleted: boolean;
  isVerified?: boolean;         // ✅ Correct field (was: isEmailVerified)
  cnicLockedAt?: Date | null;   // ✅ Correct field (was: cnicLocked boolean)
  cnicHash?: string | null;
  cnicEnc?: string | null;
  cnicVerified?: boolean;
}

function hasCnicVerified(user: UserLean): boolean {
  // V6.8.11 FIX: Field name is cnicLockedAt (Date), not cnicLocked (boolean)
  // Also check for cnicVerified as alternate approval signal
  return (
    Boolean(user.cnicLockedAt) &&
    Boolean(user.cnicHash) &&
    Boolean(user.cnicEnc)
  );
}

function requireCnicForAgent(): boolean {
  // Default: true — opt out only via env flag
  return process.env.REQUIRE_CNIC_FOR_AGENT_ONBOARDING !== "0";
}

// ═══════════════════════════════════════════════════════════════
// MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
): Promise<void> {
  // ── Correlation ID ───────────────────────────────────────────
  const requestId =
    typeof req.headers["x-correlation-id"] === "string"
      ? req.headers["x-correlation-id"]
      : crypto.randomUUID();

  setSecurityHeaders(res, requestId);

  // ── Method guard ─────────────────────────────────────────────
  const ALLOWED_METHODS = ["GET", "PATCH", "DELETE"];
  if (!ALLOWED_METHODS.includes(req.method ?? "")) {
    res.setHeader("Allow", ALLOWED_METHODS.join(", "));
    return void res.status(405).json({
      success: false,
      message: `Method ${req.method ?? "unknown"} not allowed. POST removed — use /api/onboarding/business to create a profile.`,
      requestId,
    });
  }

  // ── Rate limiting ────────────────────────────────────────────
  const isWrite = req.method === "PATCH" || req.method === "DELETE";
  const rl = isWrite
    ? await rateLimitApiWrite(req)
    : await rateLimitApi(req);

  if (!rl.ok) {
    res.setHeader("Retry-After", String(rl.retryAfter ?? 60));
    return void res.status(429).json({
      success: false,
      message: "Too many requests. Please try again shortly.",
      requestId,
    });
  }

  // ── Authentication ───────────────────────────────────────────
  const auth = await requireAuth(req, res);
  if (!auth) return; // requireAuth already sent 401

  try {
    await dbConnect();

    // ── Fetch user for CNIC gate + status check ──────────────────
    // V6.8.11 FIX: Use correct field names + force include select:false fields
    // cnicHash and cnicEnc have select:false in schema — need + prefix
    const dbUser = await User.findById(auth.id)
      .select("_id role status isDeleted isVerified cnicLockedAt cnicVerified +cnicHash +cnicEnc")
      .lean<UserLean>();

    if (!dbUser || dbUser.isDeleted) {
      return void res.status(401).json({
        success: false,
        message: "Unauthorized",
        requestId,
      });
    }

    if (dbUser.status !== "active") {
      return void res.status(403).json({
        success: false,
        message: "Account is not active.",
        requestId,
      });
    }

    const isAdmin = dbUser.role === "admin";

    // ════════════════════════════════════════════════════════════
    // GET — Read own AgentProfile
    // ════════════════════════════════════════════════════════════
    if (req.method === "GET") {
      const profile = await AgentProfile.findOne({
        user: new Types.ObjectId(auth.id),
        isDeleted: false,
      })
        .select(AGENT_SELECT_FIELDS)
        .lean();

      return void res.status(200).json({
        success: true,
        profile: (profile as Record<string, unknown>) ?? null,
        requestId,
      });
    }

    // ════════════════════════════════════════════════════════════
    // PATCH — Update own profile (whitelisted fields only)
    // ════════════════════════════════════════════════════════════
    if (req.method === "PATCH") {
      // CNIC gate for writes
      if (requireCnicForAgent() && !isAdmin) {
        if (!hasCnicVerified(dbUser)) {
          await logSecurityEvent({
            type:     "permission_denied",
            severity: "medium",
            userId:   auth.id,
            req,
            metadata: {
              reason:   "Agent profile update attempted without CNIC verification",
              endpoint: "/api/agent/profile",
            },
          });
          return void res.status(403).json({
            success: false,
            message:
              "CNIC verification is required to update your agent profile.",
            requestId,
          });
        }
      }

      // Fetch profile — confirm ownership
      const profile = await AgentProfile.findOne({
        user: new Types.ObjectId(auth.id),
        isDeleted: false,
      })
        .select("_id user status isDeleted")
        .lean<ProfileOwnershipLean>();

      if (!profile) {
        return void res.status(404).json({
          success: false,
          message:
            "Agent profile not found. Submit onboarding at /api/onboarding/business first.",
          requestId,
        });
      }

      // Suspended agents cannot update their own profile
      if (profile.status === "suspended") {
        return void res.status(403).json({
          success: false,
          message:
            "Your agent profile is suspended. Contact support.",
          requestId,
        });
      }

      // ── Build safe update object ───────────────────────────────
      const body = req.body as Record<string, unknown>;
      const updates: Record<string, unknown> = {};

      // Text fields
      if ("displayName" in body) {
        const v = safeText(body.displayName, 100);
        if (v) updates.displayName = v;
      }
      if ("tagline" in body) {
        updates.tagline = safeText(body.tagline, 200);
      }
      if ("about" in body) {
        updates.about = safeText(body.about, 2000);
      }
      if ("agencyName" in body) {
        updates.agencyName = safeText(body.agencyName, 150);
      }
      if ("availabilityNote" in body) {
        updates.availabilityNote = safeText(body.availabilityNote, 200);
      }
      if ("city" in body) {
        const v = safeText(body.city, 60);
        if (v) updates.city = v;
      }

      // Enum fields
      if ("agentType" in body) {
        if (isValidEnum(body.agentType, VALID_AGENT_TYPES)) {
          updates.agentType = body.agentType;
        }
      }
      if ("agencySize" in body) {
        if (isValidEnum(body.agencySize, VALID_AGENCY_SIZES)) {
          updates.agencySize = body.agencySize;
        }
      }

      // Boolean fields
      if ("isAvailable" in body) {
        const v = safeBoolean(body.isAvailable);
        if (v !== undefined) updates.isAvailable = v;
      }

      // Array fields
      if ("operatingCities" in body) {
        updates.operatingCities = safeStringArray(body.operatingCities, 20, 60);
      }
      if ("languages" in body) {
        updates.languages = safeStringArray(body.languages, 10, 40);
      }
      if ("specializations" in body) {
        if (Array.isArray(body.specializations)) {
          updates.specializations = (body.specializations as unknown[])
            .filter((s): s is SpecializationValue =>
              isValidEnum(s, VALID_SPECIALIZATIONS)
            )
            .slice(0, 5);
        }
      }

      // Experience sub-document (partial update)
      if ("experience" in body && typeof body.experience === "object" && body.experience !== null) {
        const exp = body.experience as Record<string, unknown>;
        const expUpdate: Record<string, unknown> = {};

        const years = safeInt(exp.years, 0, 50);
        if (years !== undefined) expUpdate["experience.years"] = years;

        // totalDeals and totalValue are system-managed — not user-editable
        if (Object.keys(expUpdate).length > 0) {
          Object.assign(updates, expUpdate);
        }
      }

      // serviceAreas sub-document (partial update)
      if ("serviceAreas" in body && typeof body.serviceAreas === "object" && body.serviceAreas !== null) {
        const sa = body.serviceAreas as Record<string, unknown>;
        if ("cities" in sa) {
          updates["serviceAreas.cities"] = safeStringArray(sa.cities, 20, 60);
        }
        if ("localities" in sa) {
          updates["serviceAreas.localities"] = safeStringArray(
            sa.localities, 50, 80
          );
        }
      }

      // socialLinks sub-document
      if ("socialLinks" in body && typeof body.socialLinks === "object" && body.socialLinks !== null) {
        const sl = body.socialLinks as Record<string, unknown>;
        const socialFields = [
          "facebook", "instagram", "linkedin",
          "youtube", "twitter", "tiktok", "website",
        ] as const;

        for (const field of socialFields) {
          if (field in sl) {
            const url = safeUrl(sl[field]);
            updates[`socialLinks.${field}`] = url;
          }
        }
      }

      // businessHours sub-document
      if ("businessHours" in body && typeof body.businessHours === "object" && body.businessHours !== null) {
        const bh = body.businessHours as Record<string, unknown>;
        if ("weekdays" in bh) {
          updates["businessHours.weekdays"] = safeText(bh.weekdays, 50);
        }
        if ("weekends" in bh) {
          updates["businessHours.weekends"] = safeText(bh.weekends, 50);
        }
      }

      // Document photo fields (Cloudinary — must be valid https URLs)
      if ("profilePhotoUrl" in body) {
        const url = safeUrl(body.profilePhotoUrl);
        if (url) {
          updates["documents.profilePhoto.url"]       = url;
          updates["documents.profilePhoto.uploadedAt"] = new Date();
        }
      }
      if ("profilePhotoPublicId" in body) {
        const pid = safeText(body.profilePhotoPublicId, 200);
        if (pid) updates["documents.profilePhoto.publicId"] = pid;
      }
      if ("coverPhotoUrl" in body) {
        const url = safeUrl(body.coverPhotoUrl);
        if (url) {
          updates["documents.coverPhoto.url"]       = url;
          updates["documents.coverPhoto.uploadedAt"] = new Date();
        }
      }
      if ("coverPhotoPublicId" in body) {
        const pid = safeText(body.coverPhotoPublicId, 200);
        if (pid) updates["documents.coverPhoto.publicId"] = pid;
      }

      // V6.8.11: Agency logo (top-level field, agency accounts only)
      if ("agencyLogoUrl" in body) {
        const url = safeUrl(body.agencyLogoUrl);
        if (url) {
          updates["agencyLogo.url"] = url;
        }
      }
      if ("agencyLogoPublicId" in body) {
        const pid = safeText(body.agencyLogoPublicId, 200);
        if (pid) updates["agencyLogo.publicId"] = pid;
      }

      // V6.8.25: Office verification — FIXED for subdocument coordinates
      // Instead of dot-notation (which fails for nested subdocs),
      // fetch existing officeVerification and merge, then set entire object
      if ("officeVerification" in body && typeof body.officeVerification === "object" && body.officeVerification !== null) {
        const ov = body.officeVerification as Record<string, unknown>;

        // Fetch current officeVerification to merge with (preserves other fields)
        // This ensures we don't lose photos, verifiedAt, etc.
        const currentAgent = await AgentProfile.findById(profile._id)
          .select("officeVerification")
          .lean<{ officeVerification?: Record<string, unknown> }>();

        const currentOffice = currentAgent?.officeVerification ?? {};

        // Build the merged officeVerification object
        const mergedOffice: Record<string, unknown> = {
          ...currentOffice,
          isActive: true,
        };

        if ("address" in ov) {
          const addr = safeText(ov.address, 500);
          if (addr) mergedOffice.address = addr;
        }
        if ("city" in ov) {
          const city = safeText(ov.city, 60);
          if (city) mergedOffice.city = city;
        }

        // V6.8.25 KEY FIX: Coordinates from interactive map picker
        // Set as complete object, not dot-notation nested field
        if ("coordinates" in ov && typeof ov.coordinates === "object" && ov.coordinates !== null) {
          const coords = ov.coordinates as Record<string, unknown>;
          const lat = Number(coords.latitude);
          const lng = Number(coords.longitude);

          // Validate coordinates
          if (
            Number.isFinite(lat) && Number.isFinite(lng) &&
            lat >= -90 && lat <= 90 &&
            lng >= -180 && lng <= 180
          ) {
            // Set entire coordinates object (not dot-notation)
            mergedOffice.coordinates = {
              latitude: lat,
              longitude: lng,
            };
          }
        }

        // Set entire officeVerification object at once
        // This bypasses the subdocument dot-notation issue
        updates["officeVerification"] = mergedOffice;
      }

      // Guard — nothing to update
      if (Object.keys(updates).length === 0) {
        return void res.status(400).json({
          success: false,
          message: "No valid fields provided for update.",
          requestId,
        });
      }

      // Apply update
      const updated = await AgentProfile.findByIdAndUpdate(
        profile._id,
        { $set: updates },
        { new: true, runValidators: true }
      )
        .select(AGENT_SELECT_FIELDS)
        .lean();

      // Audit log
      await logSecurityEvent({
        type:     "kyc_document_uploaded",
        severity: "low",
        userId:   auth.id,
        req,
        metadata: {
          action:    "agent_profile_updated",
          profileId: String(profile._id),
          fields:    Object.keys(updates),
        },
      });

      return void res.status(200).json({
        success: true,
        message: "Profile updated successfully.",
        profile: (updated as Record<string, unknown>) ?? null,
        requestId,
      });
    }

    // ════════════════════════════════════════════════════════════
    // DELETE — Soft delete own profile
    // ════════════════════════════════════════════════════════════
    if (req.method === "DELETE") {
      const profile = await AgentProfile.findOne({
        user: new Types.ObjectId(auth.id),
        isDeleted: false,
      })
        .select("_id user status isDeleted")
        .lean<ProfileOwnershipLean>();

      if (!profile) {
        return void res.status(404).json({
          success: false,
          message: "Agent profile not found.",
          requestId,
        });
      }

      // Cannot delete an approved profile directly
      // Must go through admin suspension first (enterprise policy)
      if (profile.status === "approved" && !isAdmin) {
        return void res.status(403).json({
          success: false,
          message:
            "Approved agent profiles cannot be self-deleted. Please contact support.",
          requestId,
        });
      }

      const now = new Date();

      // Soft delete AgentProfile
      await AgentProfile.updateOne(
        { _id: profile._id },
        {
          $set: {
            isDeleted:      true,
            deletedAt:      now,
            deletedBy:      new Types.ObjectId(auth.id),
            deletionReason: "self_deleted",
            status:         "suspended",   // closest valid enum value
          },
        }
      );

      // V6.8.0: Full capability cleanup + role downgrade (Session 3 pattern)
      // - isVerifiedAgent: false      → revoke capability
      // - agentVerificationStatus     → reset to "none"
      // - agentProfileId              → unlink from AgentProfile
      // - agentListingCount           → reset counter
      // - role: "user"                → downgrade (backward compat)
      // - tokenVersion++              → force re-login
      await User.updateOne(
        { _id: new Types.ObjectId(auth.id) },
        {
          $set: {
            role:                    "user",
            isVerifiedAgent:         false,
            agentVerificationStatus: "none",
            agentProfileId:          null,
            agentListingCount:       0,
          },
          $inc: { tokenVersion: 1 },
        }
      );

      await logSecurityEvent({
        type:     "account_deleted",
        severity: "medium",
        userId:   auth.id,
        req,
        metadata: {
          action:                    "agent_profile_self_deleted",
          profileId:                 String(profile._id),
          roleFrom:                  "agent",
          roleTo:                    "user",
          capabilitiesRevoked:       ["isVerifiedAgent", "agentProfileId", "agentListingCount"],
          agentVerificationStatus:   "none",
        },
      });

      return void res.status(200).json({
        success: true,
        message:
          "Agent profile deleted. Your account has been downgraded. Please log in again.",
        requestId,
      });
    }
  } catch (error: unknown) {
    const message =
      error instanceof Error ? error.message : "Unexpected error occurred";

    console.error("[AgentProfile] Unhandled error:", error);

    await logSecurityEvent({
      type:     "system_error",
      severity: "high",
      userId:   auth?.id,
      req,
      metadata: {
        error:    message,
        endpoint: "/api/agent/profile",
        method:   req.method,
      },
    }).catch(() => {});

    return void res.status(500).json({
      success: false,
      message: "An unexpected error occurred. Please try again.",
      requestId,
    });
  }
}

