interface GeminiMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
}
/**
 * 🔐 ENTERPRISE AI CHAT ENDPOINT
 * 
 * Security Features:
 * ├── Authentication required
 * ├── Rate limiting (15 req/min global, 10/hour per user, 30/day)
