// ✅ Disposable email domains (same as send-signup-code)
const DISPOSABLE_EMAIL_DOMAINS = new Set([
  "mailinator.com",
  "10minutemail.com",
  "guerrillamail.com",
  "tempmail.com",
  "temp-mail.org",
  "yopmail.com",
  "getnada.com",
  "dispostable.com",
  "sharklasers.com",
  "trashmail.com",
  "moakt.com",
  "mintemail.com",
  "maildrop.cc",
  "inboxkitten.com",
  "fakeinbox.com",
  "throwawaymail.com",
  "bultoc.com",
]);

const SUSPICIOUS_DOMAIN_PATTERNS = [
  "tempmail",
  "temp-mail",
  "10min",
  "guerrilla",
  "throwaway",
  "trashmail",
  "maildrop",
  "fakeinbox",
];

