// ═══════════════════════════════════════════════════════════════
// 🔐 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const requestId = getRequestId(req);
  setSecurityHeaders(res, requestId);

  if (req.method !== "POST") {
    return sendError(res, 405, "Method not allowed", requestId, "METHOD_NOT_ALLOWED");
  }

  const ip = getClientIp(req);
  const userAgent = String(req.headers["user-agent"] || "").slice(0, 200);

  try {
    // ═══════════════════════════════════════════════════════════
    // STEP 1: Rate Limiting (Enterprise)
    // ═══════════════════════════════════════════════════════════
    const rateLimitResult = await rateLimitResendCode(req);
    if (!rateLimitResult.ok) {
      res.setHeader("Retry-After", rateLimitResult.retryAfter || 60);

      await logResendAttempt({
        ip,
        userAgent,
        action: "rate_limited",
        success: false,
        reason: "Too many resend attempts",
        requestId,
      });

      // ✅ Still use generic success (anti-enumeration)
      return sendSuccess(res, requestId);
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 2: Connect to Database
    // ═══════════════════════════════════════════════════════════
    await dbConnect();

    // ═══════════════════════════════════════════════════════════
    // STEP 3: Extract and Validate Input
    // ═══════════════════════════════════════════════════════════
    const email = normalizeEmail(req.body?.email || "");
    const turnstileToken = String(req.body?.turnstileToken || "").trim();

    if (!email) {
      await logResendAttempt({
        ip,
        userAgent,
        action: "missing_email",
        success: false,
        reason: "Email not provided",
        requestId,
      });
      return sendSuccess(res, requestId); // Generic response
    }

    if (!isValidEmail(email)) {
      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "invalid_email",
        success: false,
        reason: "Invalid email format",
        requestId,
      });
      return sendSuccess(res, requestId);
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 4: Disposable Email Check
    // ═══════════════════════════════════════════════════════════
    if (isDisposableEmail(email)) {
      await SignupCode.deleteMany({ email, codeType: SIGNUP_CODE_TYPE }).catch(() => {});

      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "disposable_email",
        success: false,
        reason: "Disposable email blocked",
        requestId,
      });

      return sendSuccess(res, requestId);
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 5: Turnstile CAPTCHA Verification
    // ═══════════════════════════════════════════════════════════
    if (!turnstileToken) {
      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "captcha_missing",
        success: false,
        reason: "No captcha token",
        requestId,
      });

      return sendError(
        res,
        400,
        "Please complete the security verification",
        requestId,
        "CAPTCHA_REQUIRED"
      );
    }

    const captchaValid = await verifyTurnstile(turnstileToken, ip);
    if (!captchaValid) {
      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "captcha_failed",
        success: false,
        reason: "Captcha verification failed",
        requestId,
      });

      return sendError(
        res,
        400,
        "Security verification failed. Please try again.",
        requestId,
        "CAPTCHA_FAILED"
      );
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 6: Check if User Already Exists (Anti-Enumeration)
    // ═══════════════════════════════════════════════════════════
    const existingUser = await User.findOne({
      email,
      isDeleted: { $ne: true },
    })
      .select("_id")
      .lean();

    if (existingUser) {
      await SignupCode.deleteMany({ email, codeType: SIGNUP_CODE_TYPE }).catch(() => {});

      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "user_exists",
        success: true,
        reason: "User already exists",
        requestId,
      });

      return sendSuccess(res, requestId);
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 7: Fetch Existing Signup Code
    // ═══════════════════════════════════════════════════════════
    const existingCode = await SignupCode.findOne({
      email,
      codeType: SIGNUP_CODE_TYPE,
      isVerified: false,
      expiresAt: { $gt: new Date() },
    })
      .sort({ updatedAt: -1, createdAt: -1 })
      .lean();

    if (!existingCode) {
      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "no_pending_signup",
        success: false,
        reason: "No pending signup found",
        requestId,
      });

      // ✅ Generic response (don't reveal no signup exists)
      return sendSuccess(res, requestId);
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 8: Check Resend Count Limit
    // ═══════════════════════════════════════════════════════════
    const resendCount = Number((existingCode as any).resendCount || 0);
    if (resendCount >= MAX_RESENDS_PER_SESSION) {
      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "max_resends_exceeded",
        success: false,
        reason: `Exceeded ${MAX_RESENDS_PER_SESSION} resends`,
        requestId,
      });

      return sendError(
        res,
        429,
        "Maximum resend limit reached. Please start a new signup.",
        requestId,
        "MAX_RESENDS_EXCEEDED"
      );
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 9: Enforce Cooldown Between Resends
    // ═══════════════════════════════════════════════════════════
    const lastResentAt = (existingCode as any).lastResentAt;
    if (lastResentAt) {
      const timeSinceLastResend = Date.now() - new Date(lastResentAt).getTime();
      const cooldownMs = MIN_RESEND_INTERVAL_SECONDS * 1000;

      if (timeSinceLastResend < cooldownMs) {
        const remainingSeconds = Math.ceil((cooldownMs - timeSinceLastResend) / 1000);

        await logResendAttempt({
          email,
          ip,
          userAgent,
          action: "cooldown_active",
          success: false,
          reason: `Must wait ${remainingSeconds}s`,
          requestId,
        });

        return sendError(
          res,
          429,
          `Please wait ${remainingSeconds} seconds before requesting another code.`,
          requestId,
          "COOLDOWN_ACTIVE"
        );
      }
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 10: Generate New OTP
    // ═══════════════════════════════════════════════════════════
    const newCode = generateSecureOTP();
    const newCodeHash = hashOtp(email, newCode);
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60 * 1000);

    // ═══════════════════════════════════════════════════════════
    // STEP 11: Atomically rotate the pending signup code
    // ═══════════════════════════════════════════════════════════
    const now = new Date();
    const cooldownBefore = new Date(
      now.getTime() - MIN_RESEND_INTERVAL_SECONDS * 1000
    );
    const ipHash = hashIp(ip);

    const previousCode = await SignupCode.findOneAndUpdate(
      {
        _id: (existingCode as any)._id,
        email,
        codeType: SIGNUP_CODE_TYPE,
        isVerified: false,
        expiresAt: { $gt: now },
        resendCount: { $lt: MAX_RESENDS_PER_SESSION },
        $or: [
          { lastResentAt: { $exists: false } },
          { lastResentAt: null },
          { lastResentAt: { $lte: cooldownBefore } },
        ],
      },
      {
        $set: {
          code: newCodeHash,
          expiresAt,
          attempts: 0,
          lastAttemptAt: null,
          lastResentAt: now,
          "meta.ipHash": ipHash,
          "meta.userAgent": userAgent,
          "meta.requestId": requestId,
          "meta.reason": "resend",
          "meta.codeAlgo": "hmac-sha256",
          "meta.pwAlgo": "aes-256-gcm",
        },
        $inc: { resendCount: 1 },
      },
      { new: false, runValidators: true }
    );

    if (!previousCode) {
      return sendError(
        res,
        429,
        "Please wait before requesting another verification code.",
        requestId,
        "RESEND_NOT_AVAILABLE"
      );
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 12: Send Verification Email
    // ═══════════════════════════════════════════════════════════
    const emailSent = await sendVerificationEmail(email, newCode);

    if (!emailSent) {
      // Restore the previous usable code only when this request still owns
      // the rotation. This avoids destroying a newer concurrent resend.
      await SignupCode.updateOne(
        {
          _id: (previousCode as any)._id,
          code: newCodeHash,
          codeType: SIGNUP_CODE_TYPE,
        },
        {
          $set: {
            code: String((previousCode as any).code || ""),
            expiresAt: (previousCode as any).expiresAt,
            attempts: Number((previousCode as any).attempts || 0),
            lastAttemptAt: (previousCode as any).lastAttemptAt || null,
            resendCount: Number((previousCode as any).resendCount || 0),
            lastResentAt: (previousCode as any).lastResentAt || null,
            meta: (previousCode as any).meta || {},
          },
        }
      ).catch(() => {});

      await logResendAttempt({
        email,
        ip,
        userAgent,
        action: "email_failed",
        success: false,
        reason: "Failed to send email; previous code restored",
        requestId,
      });

      return sendSuccess(res, requestId);
    }

    // ═══════════════════════════════════════════════════════════
    // STEP 13: Success
    // ═══════════════════════════════════════════════════════════
    await logResendAttempt({
      email,
      ip,
      userAgent,
      action: "code_resent",
      success: true,
      reason: `Resend count: ${resendCount + 1}`,
      requestId,
    });

    return sendSuccess(res, requestId);
  } catch (error: any) {
    await logResendAttempt({
      ip,
      userAgent,
      action: "server_error",
      success: false,
      reason: error.message,
      requestId,
    });

    return sendError(
      res,
      500,
      "Unable to process your request. Please try again.",
      requestId,
      "SERVER_ERROR"
    );
  }
}

