// ─── Check unsubscribe status ─────────────────────────────────

/**
 * Returns true if the recipient has unsubscribed
 * and the sequence is configured to stop on unsubscribe.
 */
async function isUnsubscribed(
  enrollment:       any,
  stopOnUnsubscribe: boolean
): Promise<boolean> {
  if (!stopOnUnsubscribe) return false;

  if (enrollment.recipientType === 'subscriber') {
    const sub: any = await NewsletterSubscriber.findOne({
      email: enrollment.email,
    })
      .select('status')
      .lean();

    return sub?.status === 'unsubscribed' || sub?.status === 'bounced';
  }

  if (enrollment.recipientType === 'lead') {
    const lead: any = await Lead.findById(enrollment.recipientId)
      .select('emailOptOut')
      .lean();

    return lead?.emailOptOut === true;
  }

  return false;
}

// ─── Process single enrollment ────────────────────────────────

interface ProcessResult {
  status:  'sent' | 'skipped' | 'completed' | 'cancelled' | 'failed';
  reason?: string;
}

async function processEnrollment(
  enrollment:   any,
  sequence:     any,
  requestId:    string
): Promise<ProcessResult> {

  const stepIndex  = enrollment.currentStep - 1;
  const step       = sequence.steps[stepIndex];

  // Step not found — sequence may have changed
  if (!step) {
    return { status: 'completed', reason: 'step_not_found' };
  }

  // ── Check unsubscribe ───────────────────────────────────────
  const unsubscribed = await isUnsubscribed(
    enrollment,
    sequence.stopOnUnsubscribe !== false
  );

  if (unsubscribed) {
    return { status: 'cancelled', reason: 'unsubscribed' };
  }

  // ── Fetch recipient record for merge tags ───────────────────
  let recipientRecord: any = null;

  try {
    if (enrollment.recipientType === 'subscriber') {
      recipientRecord = await NewsletterSubscriber.findOne({
        email: enrollment.email,
      })
        .select('name email status')
        .lean();
    } else {
      recipientRecord = await Lead.findById(enrollment.recipientId)
        .select(
          'name email phone status temperature leadScore leadType ' +
          'source budget projectSnapshot propertySnapshot createdAt ' +
          'emailOptOut'
        )
        .lean();
    }
  } catch {
    // Non-fatal — proceed with enrollment data
  }

  // ── Build unsubscribe URL ───────────────────────────────────
  let unsubscribeUrl = `${SITE_URL}/unsubscribe`;

  if (enrollment.recipientType === 'subscriber' && recipientRecord?.unsubscribeToken) {
    unsubscribeUrl = `${SITE_URL}/api/newsletter/unsubscribe?token=${recipientRecord.unsubscribeToken}`;
  } else if (enrollment.recipientType === 'lead' && recipientRecord?.emailUnsubscribeToken) {
    unsubscribeUrl = `${SITE_URL}/api/leads/unsubscribe?token=${recipientRecord.emailUnsubscribeToken}`;
  }

  // ── Build merge tag data ────────────────────────────────────
  const tagData = buildMergeTagData(enrollment, recipientRecord, unsubscribeUrl);

  // ── Resolve sender for this step ───────────────────────────
  const fromName  = step.fromName  || sequence.defaultFromName  || DEFAULT_FROM_NAME;
  const fromEmail = step.fromEmail || sequence.defaultFromEmail || DEFAULT_FROM_EMAIL;
  const replyTo   = step.replyTo   || sequence.defaultReplyTo   || '';

  // ── Personalize subject + content ──────────────────────────
  const personalizedSubject = replaceMergeTags(step.subject, tagData);
  const personalizedContent = replaceMergeTags(step.content, tagData);

  // ── Build final HTML ────────────────────────────────────────
  const finalHtml = wrapEmailContent(
    personalizedContent,
    personalizedSubject,
    step.previewText || '',
    unsubscribeUrl
  );

  // ── Send email ──────────────────────────────────────────────
  try {
    await transporter.sendMail({
      from:    buildFromHeader(fromName, fromEmail),
      to:      enrollment.email,
      replyTo: replyTo || undefined,
      subject: personalizedSubject,
      html:    finalHtml,
      headers: {
        'X-Automation-Sequence': String(sequence._id),
        'X-Automation-Step':     String(enrollment.currentStep),
        'X-Enrollment-Id':       String(enrollment._id),
        'List-Unsubscribe':      `<${unsubscribeUrl}>`,
        'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click',
      },
    });

    return { status: 'sent' };

  } catch (sendErr) {
    const errMsg = (sendErr instanceof Error ? sendErr.message : String(sendErr)).toLowerCase();

    // Detect hard bounces
    const isBounce =
      errMsg.includes('550') ||
      errMsg.includes('no such user') ||
      errMsg.includes('does not exist') ||
      errMsg.includes('recipient address rejected') ||
      errMsg.includes('invalid_email');

    if (isBounce) {
      return { status: 'cancelled', reason: 'bounce' };
    }

    return { status: 'failed', reason: errMsg.slice(0, 200) };
  }
}

// ─── Main Handler ─────────────────────────────────────────────

export default async function handler(
  req:  NextApiRequest,
  res:  NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'cron').slice(0, 500);

  // ── Method guard ─────────────────────────────────────────────
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    res.status(405).json({ success: false, message: 'Method not allowed' });
    return;
  }

  // ── Rate limit ───────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    sendRateLimitResponse(res, rl);
    return;
  }

  // ── Auth: cron secret OR admin session ───────────────────────
  const authType = await authenticateRequest(req, res);
  if (!authType) return; // requireAdmin already sent 401

  try {
    await dbConnect();

    const now = new Date();

    // ── Fetch due enrollments ─────────────────────────────────
    // Due = nextSendAt <= now AND status = active
    const dueEnrollments: any[] = await AutomationEnrollment.find({
      status:     'active',
      nextSendAt: { $lte: now },
    })
      .sort({ nextSendAt: 1 }) // Oldest due first
      .limit(BATCH_SIZE)
      .lean();

    if (dueEnrollments.length === 0) {
      res.status(200).json({
        success:   true,
        message:   'No enrollments due',
        processed: 0,
        requestId,
      });
      return;
    }

    // ── Fetch all unique sequences needed ─────────────────────
    const sequenceIds = [
      ...new Set(dueEnrollments.map((e) => String(e.sequenceId))),
    ];

    const sequences: any[] = await AutomationSequence.find({
      _id: { $in: sequenceIds },
    }).lean();

    const sequenceMap = new Map<string, any>(
      sequences.map((s) => [String(s._id), s])
    );

    // ── Process stats ─────────────────────────────────────────
    let sentCount      = 0;
    let completedCount = 0;
    let cancelledCount = 0;
    let failedCount    = 0;
    let skippedCount   = 0;

    // ── Process each enrollment ───────────────────────────────
    for (const enrollment of dueEnrollments) {
      try {
        const sequence = sequenceMap.get(String(enrollment.sequenceId));

        // Sequence deleted or archived — cancel enrollment
        if (!sequence || sequence.status === 'archived') {
          await AutomationEnrollment.updateOne(
            { _id: enrollment._id },
            {
              $set: {
                status:       'cancelled',
                cancelledAt:  now,
                cancelReason: 'sequence_unavailable',
              },
            }
          );
          cancelledCount++;
          continue;
        }

        // ── Process this enrollment ─────────────────────────
        const result = await processEnrollment(enrollment, sequence, requestId);

        if (result.status === 'sent') {
          sentCount++;

          // Determine next step
          const totalSteps  = sequence.steps.length;
          const isLastStep  = enrollment.currentStep >= totalSteps;

          if (isLastStep) {
            // All steps complete — mark enrollment as completed
            await AutomationEnrollment.updateOne(
              { _id: enrollment._id },
              {
                $set: {
                  status:      'completed',
                  completedAt: now,
                  nextSendAt:  null,
                },
                $push: {
                  stepsCompleted: {
                    stepNumber: enrollment.currentStep,
                    sentAt:     now,
                  },
                },
              }
            );

            // Update sequence stats
            await AutomationSequence.updateOne(
              { _id: enrollment.sequenceId },
              {
                $inc: {
                  'stats.completedCount': 1,
                  'stats.activeCount':   -1,
                  'stats.emailsSent':     1,
                },
              }
            );

            completedCount++;

          } else {
            // Advance to next step
            const nextStepIndex = enrollment.currentStep; // 0-based = current step number
            const nextStep      = sequence.steps[nextStepIndex];
            const delayMs       = (nextStep.delayDays || 0) * 24 * 60 * 60 * 1000;
            const nextSendAt    = new Date(now.getTime() + delayMs);

            await AutomationEnrollment.updateOne(
              { _id: enrollment._id },
              {
                $set: {
                  currentStep: enrollment.currentStep + 1,
                  nextSendAt,
                  failedSteps: [], // Reset failed attempts on success
                },
                $push: {
                  stepsCompleted: {
                    stepNumber: enrollment.currentStep,
                    sentAt:     now,
                  },
                },
              }
            );

            // Update sequence email sent count
            await AutomationSequence.updateOne(
              { _id: enrollment.sequenceId },
              { $inc: { 'stats.emailsSent': 1 } }
            );
          }

        } else if (result.status === 'cancelled') {
          // Unsubscribe or bounce — cancel enrollment
          await AutomationEnrollment.updateOne(
            { _id: enrollment._id },
            {
              $set: {
                status:       'cancelled',
                cancelledAt:  now,
                cancelReason: result.reason || 'cancelled',
                nextSendAt:   null,
              },
            }
          );

          // Handle bounce — mark subscriber/lead
          if (result.reason === 'bounce') {
            if (enrollment.recipientType === 'subscriber') {
              await NewsletterSubscriber.updateOne(
                { email: enrollment.email },
                { $set: { status: 'bounced' } }
              );
            } else {
              await Lead.updateOne(
                { _id: enrollment.recipientId },
                { $set: { emailOptOut: true, emailOptOutAt: now } }
              );
            }
          }

          await AutomationSequence.updateOne(
            { _id: enrollment.sequenceId },
            {
              $inc: {
                'stats.cancelledCount': 1,
                'stats.activeCount':   -1,
              },
            }
          );

          cancelledCount++;

        } else if (result.status === 'failed') {
          failedCount++;

          // Increment failed attempt for this step
          const failedSteps = enrollment.failedSteps || [];
          const stepFails   = failedSteps.filter(
            (f: any) => f.stepNumber === enrollment.currentStep
          ).length;

          if (stepFails >= MAX_STEP_RETRIES - 1) {
            // Max retries reached — mark enrollment as failed
            await AutomationEnrollment.updateOne(
              { _id: enrollment._id },
              {
                $set: {
                  status:     'failed',
                  failedAt:   now,
                  nextSendAt: null,
                },
                $push: {
                  failedSteps: {
                    stepNumber: enrollment.currentStep,
                    failedAt:   now,
                    reason:     result.reason,
                  },
                },
              }
            );

            await AutomationSequence.updateOne(
              { _id: enrollment.sequenceId },
              {
                $inc: {
                  'stats.failedCount': 1,
                  'stats.activeCount': -1,
                },
              }
            );

          } else {
            // Schedule retry in 2 hours
            const retryAt = new Date(now.getTime() + 2 * 60 * 60 * 1000);

            await AutomationEnrollment.updateOne(
              { _id: enrollment._id },
              {
                $set:  { nextSendAt: retryAt },
                $push: {
                  failedSteps: {
                    stepNumber: enrollment.currentStep,
                    failedAt:   now,
                    reason:     result.reason,
                  },
                },
              }
            );
          }

        } else {
          // 'skipped' — should not occur in processor but handle gracefully
          skippedCount++;
        }

        // Small delay between sends to avoid SMTP rate limits
        await sleep(BATCH_DELAY_MS);

      } catch (enrollmentErr) {
        // Per-enrollment error — log and continue
        console.error(
          `[Automation Process] Enrollment ${enrollment._id} failed:`,
          enrollmentErr instanceof Error
            ? enrollmentErr.message
            : enrollmentErr
        );
        failedCount++;
      }
    }

    // ── Audit log ─────────────────────────────────────────────
    await logSecurityEvent({
      type:     'bulk_action_performed',
      severity: 'low',
      ip:       clientIP,
      userAgent,
      metadata: {
        requestId,
        action:     'automation_process_run',
        triggeredBy: authType,
        processed:  dueEnrollments.length,
        sent:       sentCount,
        completed:  completedCount,
        cancelled:  cancelledCount,
        failed:     failedCount,
        skipped:    skippedCount,
      },
    });

    // ── Response ──────────────────────────────────────────────
    res.status(200).json({
      success: true,
      message: `Processed ${dueEnrollments.length} enrollment${dueEnrollments.length !== 1 ? 's' : ''}`,
      stats: {
        processed:  dueEnrollments.length,
        sent:       sentCount,
        completed:  completedCount,
        cancelled:  cancelledCount,
        failed:     failedCount,
        skipped:    skippedCount,
      },
      requestId,
    });
    return;

  } catch (err) {
    await logSecurityEvent({
      type:     'system_error',
      severity: 'high',
      ip:       clientIP,
      userAgent,
      metadata: {
        requestId,
        action: 'automation_process_error',
        error:  err instanceof Error ? err.message : 'unknown',
      },
    });

    res.status(500).json({
      success: false,
      message: 'Automation processor failed',
      requestId,
    });
    return;
  }
}

// pages/api/automation/sequences/[id]/enroll.ts
// ═══════════════════════════════════════════════════════════════
// MANUAL ENROLLMENT API — POST
// Admin only — rate limited — full security
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   Manually enroll one or more recipients into a sequence.
//   Used for 'manual' trigger sequences OR admin override.
//
// BODY:
//   {
//     recipients: [
//       {
//         recipientId:   string,   // Subscriber._id or Lead._id
//         recipientType: 'subscriber' | 'lead',
//         email:         string,
//         name:          string,
//       }
//     ]
//   }
//
// RULES:
//   - Sequence must be 'active'
//   - Max 500 recipients per request
//   - Skips already-active enrollments (if skipIfAlreadyActive)
//   - Respects daily enrollment cap
//   - Returns count of enrolled vs skipped
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose                                  from 'mongoose';
import dbConnect                                 from '@/lib/db';
import AutomationSequence                        from '@/models/AutomationSequence';
import AutomationEnrollment                      from '@/models/AutomationEnrollment';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ─── Constants ────────────────────────────────────────────────

const MAX_RECIPIENTS_PER_REQUEST = 500;
const EMAIL_REGEX = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{1,63}$/;

// ─── Helpers ──────────────────────────────────────────────────

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  const cfIp = req.headers['cf-connecting-ip'];
  if (typeof cfIp === 'string') return cfIp.trim();
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('X-XSS-Protection',       '1; mode=block');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
}

function isValidEmail(email: string): boolean {
  return EMAIL_REGEX.test(String(email || '').trim().toLowerCase());
}

// ─── Main Handler ─────────────────────────────────────────────

export default async function handler(
  req:  NextApiRequest,
  res:  NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ── Method guard ─────────────────────────────────────────────
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ── Rate limit ───────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: { requestId, action: 'automation_manual_enroll' },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ── Auth guard ───────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  // ── Validate sequence ID ─────────────────────────────────────
  const { id } = req.query;

  if (!id || typeof id !== 'string' || !mongoose.Types.ObjectId.isValid(id)) {
    await logSecurityEvent({
      type:     'suspicious_activity',
      severity: 'medium',
      userId:   auth.id,
      ip:       clientIP,
      userAgent,
      metadata: {
        requestId,
        action:     'automation_enroll_invalid_id',
        providedId: String(id).slice(0, 50),
      },
    });
    res.status(400).json({
      success: false,
      message: 'Invalid sequence ID',
      requestId,
    });
    return;
  }

  try {
    await dbConnect();

    // ── Fetch sequence ────────────────────────────────────────
    const sequence: any = await AutomationSequence.findById(id).lean();

    if (!sequence) {
      res.status(404).json({
        success: false,
        message: 'Sequence not found',
        requestId,
      });
      return;
    }

    // ── Sequence must be active ───────────────────────────────
    if (sequence.status !== 'active') {
      res.status(400).json({
        success: false,
        message: `Cannot enroll into a sequence with status "${sequence.status}". Sequence must be active.`,
        requestId,
      });
      return;
    }

    // ── Sequence must have steps ──────────────────────────────
    if (!sequence.steps || sequence.steps.length === 0) {
      res.status(400).json({
        success: false,
        message: 'Sequence has no steps configured',
        requestId,
      });
      return;
    }

    // ── Validate recipients array ─────────────────────────────
    const { recipients } = req.body || {};

    if (!Array.isArray(recipients) || recipients.length === 0) {
      res.status(400).json({
        success: false,
        message: 'recipients must be a non-empty array',
        requestId,
      });
      return;
    }

    if (recipients.length > MAX_RECIPIENTS_PER_REQUEST) {
      res.status(400).json({
        success: false,
        message: `Maximum ${MAX_RECIPIENTS_PER_REQUEST} recipients per request`,
        requestId,
      });
      return;
    }

    // ── Validate each recipient ───────────────────────────────
    for (let i = 0; i < recipients.length; i++) {
      const r = recipients[i];

      if (!r || typeof r !== 'object') {
        res.status(400).json({
          success: false,
          message: `Invalid recipient at index ${i}`,
          requestId,
        });
        return;
      }

      if (!r.recipientId || typeof r.recipientId !== 'string') {
        res.status(400).json({
          success: false,
          message: `Missing recipientId at index ${i}`,
          requestId,
        });
        return;
      }

      if (!['subscriber', 'lead'].includes(r.recipientType)) {
        res.status(400).json({
          success: false,
          message: `Invalid recipientType at index ${i}. Must be "subscriber" or "lead"`,
          requestId,
        });
        return;
      }

      if (!r.email || !isValidEmail(r.email)) {
        res.status(400).json({
          success: false,
          message: `Invalid email at index ${i}`,
          requestId,
        });
        return;
      }
    }

    // ── Daily cap check ───────────────────────────────────────
    const startOfDay = new Date();
    startOfDay.setHours(0, 0, 0, 0);

    const todayCount = await AutomationEnrollment.countDocuments({
      sequenceId: id,
      enrolledAt: { $gte: startOfDay },
    });

    const remainingCap = (sequence.maxEnrollmentsPerDay || 500) - todayCount;

    if (remainingCap <= 0) {
      res.status(429).json({
        success: false,
        message: `Daily enrollment cap of ${sequence.maxEnrollmentsPerDay} reached for this sequence. Try again tomorrow.`,
        requestId,
      });
      return;
    }

    // Trim recipients to remaining cap
    const recipientsToProcess = recipients.slice(0, remainingCap);
    const skippedDueToCap     = recipients.length - recipientsToProcess.length;

    // ── Process enrollments ───────────────────────────────────
    const now        = new Date();
    const step1      = sequence.steps[0];
    const delayMs    = (step1.delayDays || 0) * 24 * 60 * 60 * 1000;
    const nextSendAt = new Date(now.getTime() + delayMs);

    let enrolledCount = 0;
    let skippedCount  = skippedDueToCap;
    const skippedEmails: string[] = [];
    const failedEmails:  string[] = [];

    for (const recipient of recipientsToProcess) {
      try {
        const email = String(recipient.email).trim().toLowerCase();

        // ── Check existing active enrollment ──────────────────
        if (sequence.skipIfAlreadyActive) {
          const existing = await AutomationEnrollment.findOne({
            sequenceId:  id,
            recipientId: String(recipient.recipientId),
            status:      'active',
          })
            .select('_id')
            .lean();

          if (existing) {
            skippedCount++;
            skippedEmails.push(email);
            continue;
          }
        }

        // ── Create enrollment ─────────────────────────────────
        await AutomationEnrollment.create({
          sequenceId:    new mongoose.Types.ObjectId(id),
          recipientId:   String(recipient.recipientId),
          recipientType: recipient.recipientType,
          email,
          name:          String(recipient.name || '').trim().slice(0, 120),
          currentStep:   1,
          status:        'active',
          nextSendAt,
          enrolledAt:    now,
          stepsCompleted: [],
          failedSteps:   [],
        });

        enrolledCount++;

      } catch (recipientErr) {
        // Per-recipient error — continue with others
        const email = String(recipient?.email || 'unknown');
        failedEmails.push(email);
        console.error(
          `[Automation Enroll] Failed for ${email}:`,
          recipientErr instanceof Error ? recipientErr.message : recipientErr
        );
      }
    }

    // ── Update sequence stats ─────────────────────────────────
    if (enrolledCount > 0) {
      await AutomationSequence.updateOne(
        { _id: id },
        {
          $inc: {
            'stats.totalEnrolled': enrolledCount,
            'stats.activeCount':   enrolledCount,
          },
        }
      );
    }

    // ── Audit log ─────────────────────────────────────────────
    await logSecurityEvent({
      type:     'bulk_action_performed',
      severity: 'low',
      userId:   auth.id,
      ip:       clientIP,
      userAgent,
      metadata: {
        requestId,
        action:       'automation_manual_enrollment',
        sequenceId:   String(id),
        sequenceName: sequence.name,
        requested:    recipients.length,
        enrolled:     enrolledCount,
        skipped:      skippedCount,
        failed:       failedEmails.length,
      },
    });

    // ── Response ──────────────────────────────────────────────
    res.status(200).json({
      success: true,
      message: `Enrolled ${enrolledCount} recipient${enrolledCount !== 1 ? 's' : ''} successfully`,
      stats: {
        requested: recipients.length,
        enrolled:  enrolledCount,
        skipped:   skippedCount,
        failed:    failedEmails.length,
      },
      skippedEmails: skippedEmails.slice(0, 20),   // Show first 20
      failedEmails:  failedEmails.slice(0, 20),
      requestId,
    });
    return;

  } catch (err) {
    await logSecurityEvent({
      type:     'system_error',
      severity: 'high',
      userId:   auth.id,
      ip:       clientIP,
      userAgent,
      metadata: {
        requestId,
        action: 'automation_enroll_error',
        error:  err instanceof Error ? err.message : 'unknown',
      },
    });

    res.status(500).json({
      success: false,
      message: 'Failed to process enrollments',
      requestId,
    });
    return;
  }
}

// pages/api/automation/sequences/[id]/index.ts
// ═══════════════════════════════════════════════════════════════
// AUTOMATION SEQUENCE SINGLE — GET / PUT / DELETE
// Admin only — rate limited — full security
// ═══════════════════════════════════════════════════════════════
// GET    → Fetch single sequence with full steps + enrollment stats
// PUT    → Update sequence (draft/paused only for most fields)
//          Status transitions: draft→active, active→paused, etc.
// DELETE → Soft archive (status → archived)
//          Cannot delete active sequences with live enrollments
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose                                  from 'mongoose';
import DOMPurify                                 from 'isomorphic-dompurify';
import dbConnect                                 from '@/lib/db';
import AutomationSequence                        from '@/models/AutomationSequence';
import AutomationEnrollment                      from '@/models/AutomationEnrollment';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ─── Constants ────────────────────────────────────────────────

const MAX_NAME_LENGTH       = 150;
const MAX_DESC_LENGTH       = 1000;
const MAX_SUBJECT_LENGTH    = 200;
const MAX_PREVIEW_LENGTH    = 300;
const MAX_CONTENT_LENGTH    = 500_000;
const MAX_FROM_NAME_LENGTH  = 150;
const MAX_FROM_EMAIL_LENGTH = 200;
const MAX_STEPS             = 20;

const ALLOWED_TRIGGERS = [
  'subscriber_joined',
  'lead_created',
  'lead_status_changed',
  'manual',
] as const;

const ALLOWED_STATUSES = [
  'draft',
  'active',
  'paused',
  'archived',
] as const;

const ALLOWED_RECIPIENT_TYPES = [
  'subscribers',
  'leads',
  'both',
] as const;

// Valid status transitions
// archived is a terminal state — cannot transition out
const STATUS_TRANSITIONS: Record<string, string[]> = {
  draft:    ['active', 'archived'],
  active:   ['paused', 'archived'],
  paused:   ['active', 'archived'],
  archived: [],  // terminal — no transitions allowed
};

const EMAIL_REGEX = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{1,63}$/;

// ─── Helpers ──────────────────────────────────────────────────

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  const cfIp = req.headers['cf-connecting-ip'];
  if (typeof cfIp === 'string') return cfIp.trim();
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('X-XSS-Protection',       '1; mode=block');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
}

function sanitizeText(text: string, maxLength: number): string {
  if (!text || typeof text !== 'string') return '';
  return text.replace(/<[^>]*>/g, '').trim().slice(0, maxLength);
}

function sanitizeHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      'a', 'b', 'br', 'div', 'em', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'hr', 'i', 'img', 'li', 'ol', 'p', 'span', 'strong', 'table',
      'tbody', 'td', 'th', 'thead', 'tr', 'ul', 'blockquote', 'code',
      'pre', 'small', 'sub', 'sup', 'u',
    ],
    ALLOWED_ATTR: [
      'href', 'target', 'rel', 'src', 'alt', 'width', 'height',
      'style', 'class', 'id', 'colspan', 'rowspan', 'align', 'valign',
      'bgcolor', 'border', 'cellpadding', 'cellspacing', 'title',
    ],
    ALLOW_DATA_ATTR: false,
    FORBID_TAGS:     ['script', 'iframe', 'object', 'embed', 'form', 'input'],
    FORBID_ATTR:     ['onerror', 'onload', 'onclick', 'onmouseover', 'onfocus'],
  });
}

function validateEmail(email: string): boolean {
  if (!email) return true;
  return EMAIL_REGEX.test(email.trim().toLowerCase());
}

function sanitizeStep(raw: any, stepIndex: number): {
  stepNumber:  number;
  delayDays:   number;
  subject:     string;
  previewText: string;
  content:     string;
  fromName:    string;
  fromEmail:   string;
  replyTo:     string;
} | null {
  if (!raw || typeof raw !== 'object') return null;

  const subject = sanitizeText(String(raw.subject || ''), MAX_SUBJECT_LENGTH);
  if (!subject) return null;

  const content = sanitizeHtml(String(raw.content || ''));
  if (!content.trim()) return null;

  const delayDays = Math.max(
    0,
    Math.min(365, parseInt(String(raw.delayDays ?? 0), 10) || 0)
  );

  const fromEmail = String(raw.fromEmail || '').trim().toLowerCase();
  if (fromEmail && !validateEmail(fromEmail)) return null;

  return {
    stepNumber:  stepIndex + 1,
    delayDays,
    subject,
    previewText: sanitizeText(String(raw.previewText || ''), MAX_PREVIEW_LENGTH),
    content,
    fromName:    sanitizeText(String(raw.fromName   || ''), MAX_FROM_NAME_LENGTH),
    fromEmail,
    replyTo:     sanitizeText(String(raw.replyTo    || ''), MAX_FROM_EMAIL_LENGTH),
  };
}

// ─── Main Handler ─────────────────────────────────────────────

export default async function handler(
  req:  NextApiRequest,
  res:  NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ── Method guard ─────────────────────────────────────────────
  if (!['GET', 'PUT', 'DELETE'].includes(req.method || '')) {
    res.setHeader('Allow', ['GET', 'PUT', 'DELETE']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ── Rate limit ───────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: { requestId, action: 'automation_sequence_single' },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ── Auth guard ───────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  // ── Validate ID ───────────────────────────────────────────────
  const { id } = req.query;

  if (!id || typeof id !== 'string' || !mongoose.Types.ObjectId.isValid(id)) {
    await logSecurityEvent({
      type:     'suspicious_activity',
      severity: 'medium',
      userId:   auth.id,
      ip:       clientIP,
      userAgent,
      metadata: {
        requestId,
        action:     'automation_invalid_id',
        providedId: String(id).slice(0, 50),
      },
    });
    res.status(400).json({
      success: false,
      message: 'Invalid sequence ID',
      requestId,
    });
    return;
  }

  await dbConnect();

  // ════════════════════════════════════════════════════════════
  // GET — Fetch single sequence
  // ════════════════════════════════════════════════════════════
  if (req.method === 'GET') {
    try {
      const sequence: any = await AutomationSequence.findById(id).lean();

      if (!sequence) {
        res.status(404).json({
          success: false,
          message: 'Sequence not found',
          requestId,
        });
        return;
      }

      // Fetch live enrollment breakdown for this sequence
      const [
        activeEnrollments,
        completedEnrollments,
        cancelledEnrollments,
        failedEnrollments,
      ] = await Promise.all([
        AutomationEnrollment.countDocuments({ sequenceId: id, status: 'active'    }),
        AutomationEnrollment.countDocuments({ sequenceId: id, status: 'completed' }),
        AutomationEnrollment.countDocuments({ sequenceId: id, status: 'cancelled' }),
        AutomationEnrollment.countDocuments({ sequenceId: id, status: 'failed'    }),
      ]);

      // Recent enrollments (last 10) for preview
      const recentEnrollments: any[] = await AutomationEnrollment.find({
        sequenceId: id,
      })
        .sort({ enrolledAt: -1 })
        .limit(10)
        .select('email name status currentStep enrolledAt nextSendAt recipientType')
        .lean();

      res.status(200).json({
        success: true,
        sequence,
        enrollmentStats: {
          active:    activeEnrollments,
          completed: completedEnrollments,
          cancelled: cancelledEnrollments,
          failed:    failedEnrollments,
          total:
            activeEnrollments +
            completedEnrollments +
            cancelledEnrollments +
            failedEnrollments,
        },
        recentEnrollments,
        requestId,
      });
      return;

    } catch (err) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action: 'automation_sequence_fetch_error',
          error:  err instanceof Error ? err.message : 'unknown',
        },
      });
      res.status(500).json({
        success: false,
        message: 'Failed to fetch sequence',
        requestId,
      });
      return;
    }
  }

  // ════════════════════════════════════════════════════════════
  // PUT — Update sequence
  // ════════════════════════════════════════════════════════════
  if (req.method === 'PUT') {
    try {
      const sequence: any = await AutomationSequence.findById(id);

      if (!sequence) {
        res.status(404).json({
          success: false,
          message: 'Sequence not found',
          requestId,
        });
        return;
      }

      // Cannot edit archived sequences
      if (sequence.status === 'archived') {
        res.status(400).json({
          success: false,
          message: 'Cannot edit an archived sequence. Create a new one instead.',
          requestId,
        });
        return;
      }

      const body = req.body || {};

      // ── Name ────────────────────────────────────────────────
      if (body.name !== undefined) {
        const name = sanitizeText(String(body.name), MAX_NAME_LENGTH);
        if (!name || name.length < 3) {
          res.status(400).json({
            success: false,
            message: 'Sequence name must be at least 3 characters',
            requestId,
          });
          return;
        }
        sequence.name = name;
      }

      // ── Description ─────────────────────────────────────────
      if (body.description !== undefined) {
        sequence.description = sanitizeText(
          String(body.description),
          MAX_DESC_LENGTH
        );
      }

      // ── Trigger (only changeable on draft) ──────────────────
      if (body.trigger !== undefined) {
        if (sequence.status !== 'draft') {
          res.status(400).json({
            success: false,
            message: 'Trigger can only be changed while sequence is in draft status',
            requestId,
          });
          return;
        }
        const trigger = String(body.trigger);
        if (!ALLOWED_TRIGGERS.includes(trigger as any)) {
          res.status(400).json({
            success: false,
            message: `Invalid trigger. Must be one of: ${ALLOWED_TRIGGERS.join(', ')}`,
            requestId,
          });
          return;
        }
        sequence.trigger = trigger;
      }

      // ── Recipient type (only changeable on draft) ────────────
      if (body.recipientType !== undefined) {
        if (sequence.status !== 'draft') {
          res.status(400).json({
            success: false,
            message: 'Recipient type can only be changed while sequence is in draft status',
            requestId,
          });
          return;
        }
        const recipientType = String(body.recipientType);
        if (!ALLOWED_RECIPIENT_TYPES.includes(recipientType as any)) {
          res.status(400).json({
            success: false,
            message: `Invalid recipientType. Must be: ${ALLOWED_RECIPIENT_TYPES.join(', ')}`,
            requestId,
          });
          return;
        }
        sequence.recipientType = recipientType;
      }

      // ── Status transition ────────────────────────────────────
      if (body.status !== undefined) {
        const newStatus = String(body.status);

        if (!ALLOWED_STATUSES.includes(newStatus as any)) {
          res.status(400).json({
            success: false,
            message: `Invalid status. Must be one of: ${ALLOWED_STATUSES.join(', ')}`,
            requestId,
          });
          return;
        }

        const allowedNext = STATUS_TRANSITIONS[sequence.status] || [];
        if (!allowedNext.includes(newStatus)) {
          res.status(400).json({
            success: false,
            message: `Cannot transition from "${sequence.status}" to "${newStatus}"`,
            requestId,
          });
          return;
        }

        // Cannot activate with no steps
        if (newStatus === 'active' && sequence.steps.length === 0) {
          res.status(400).json({
            success: false,
            message: 'Cannot activate a sequence with no steps',
            requestId,
          });
          return;
        }

        sequence.status = newStatus;
      }

      // ── Steps ────────────────────────────────────────────────
      if (body.steps !== undefined) {
        if (!Array.isArray(body.steps)) {
          res.status(400).json({
            success: false,
            message: 'Steps must be an array',
            requestId,
          });
          return;
        }

        if (body.steps.length > MAX_STEPS) {
          res.status(400).json({
            success: false,
            message: `Maximum ${MAX_STEPS} steps allowed`,
            requestId,
          });
          return;
        }

        const cleanSteps = body.steps
          .map((s: any, i: number) => sanitizeStep(s, i))
          .filter(Boolean);

        // If currently active, must have at least 1 step
        if (sequence.status === 'active' && cleanSteps.length === 0) {
          res.status(400).json({
            success: false,
            message: 'An active sequence must have at least one step',
            requestId,
          });
          return;
        }

        sequence.steps = cleanSteps;
      }

      // ── Trigger filters ──────────────────────────────────────
      if (body.triggerFilters !== undefined) {
        const rawFilters = body.triggerFilters || {};
        sequence.triggerFilters = {
          leadStatuses:
            Array.isArray(rawFilters.leadStatuses)
              ? rawFilters.leadStatuses
                  .filter((s: unknown) => typeof s === 'string')
                  .slice(0, 20)
              : [],
          leadCities:
            Array.isArray(rawFilters.leadCities)
              ? rawFilters.leadCities
                  .filter((s: unknown) => typeof s === 'string')
                  .slice(0, 30)
              : [],
          leadSources:
            Array.isArray(rawFilters.leadSources)
              ? rawFilters.leadSources
                  .filter((s: unknown) => typeof s === 'string')
                  .slice(0, 20)
              : [],
          leadTypes:
            Array.isArray(rawFilters.leadTypes)
              ? rawFilters.leadTypes
                  .filter((s: unknown) => typeof s === 'string')
                  .slice(0, 20)
              : [],
          fromStatus:
            typeof rawFilters.fromStatus === 'string'
              ? sanitizeText(rawFilters.fromStatus, 60)
              : '',
          toStatus:
            typeof rawFilters.toStatus === 'string'
              ? sanitizeText(rawFilters.toStatus, 60)
              : '',
          subscriberSources:
            Array.isArray(rawFilters.subscriberSources)
              ? rawFilters.subscriberSources
                  .filter((s: unknown) => typeof s === 'string')
                  .slice(0, 20)
              : [],
        };
      }

      // ── Default sender ───────────────────────────────────────
      if (body.defaultFromName !== undefined) {
        sequence.defaultFromName = sanitizeText(
          String(body.defaultFromName),
          MAX_FROM_NAME_LENGTH
        );
      }

      if (body.defaultFromEmail !== undefined) {
        const email = String(body.defaultFromEmail || '').trim().toLowerCase();
        if (email && !validateEmail(email)) {
          res.status(400).json({
            success: false,
            message: 'Invalid default sender email',
            requestId,
          });
          return;
        }
        sequence.defaultFromEmail = email;
      }

      if (body.defaultReplyTo !== undefined) {
        const replyTo = String(body.defaultReplyTo || '').trim().toLowerCase();
        if (replyTo && !validateEmail(replyTo)) {
          res.status(400).json({
            success: false,
            message: 'Invalid default reply-to email',
            requestId,
          });
          return;
        }
        sequence.defaultReplyTo = replyTo;
      }

      // ── Safety settings ──────────────────────────────────────
      if (body.maxEnrollmentsPerDay !== undefined) {
        sequence.maxEnrollmentsPerDay = Math.max(
          1,
          Math.min(10_000, parseInt(String(body.maxEnrollmentsPerDay), 10) || 500)
        );
      }

      if (body.skipIfAlreadyActive !== undefined) {
        sequence.skipIfAlreadyActive = Boolean(body.skipIfAlreadyActive);
      }

      if (body.stopOnUnsubscribe !== undefined) {
        sequence.stopOnUnsubscribe = Boolean(body.stopOnUnsubscribe);
      }

      // ── Track who updated ────────────────────────────────────
      sequence.updatedBy = new mongoose.Types.ObjectId(auth.id);

      await sequence.save();

      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action:     'automation_sequence_updated',
          sequenceId: String(sequence._id),
          newStatus:  sequence.status,
          stepCount:  sequence.steps.length,
        },
      });

      res.status(200).json({
        success:  true,
        message:  'Sequence updated successfully',
        sequence,
        requestId,
      });
      return;

    } catch (err) {
      const errMsg = err instanceof Error ? err.message : 'unknown';

      // Surface Mongoose validation errors cleanly
      if (
        errMsg.includes('Cannot activate') ||
        errMsg.includes('All steps must') ||
        errMsg.includes('Maximum 20')
      ) {
        res.status(400).json({
          success: false,
          message: errMsg,
          requestId,
        });
        return;
      }

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action: 'automation_sequence_update_error',
          error:  errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to update sequence',
        requestId,
      });
      return;
    }
  }

  // ════════════════════════════════════════════════════════════
  // DELETE — Archive sequence
  // ════════════════════════════════════════════════════════════
  if (req.method === 'DELETE') {
    try {
      const sequence: any = await AutomationSequence.findById(id);

      if (!sequence) {
        res.status(404).json({
          success: false,
          message: 'Sequence not found',
          requestId,
        });
        return;
      }

      // Already archived
      if (sequence.status === 'archived') {
        res.status(400).json({
          success: false,
          message: 'Sequence is already archived',
          requestId,
        });
        return;
      }

      // Check for active enrollments before archiving
      const activeEnrollments = await AutomationEnrollment.countDocuments({
        sequenceId: id,
        status:     'active',
      });

      if (activeEnrollments > 0) {
        // Warn but allow — cancel active enrollments first
        await AutomationEnrollment.updateMany(
          { sequenceId: id, status: 'active' },
          {
            $set: {
              status:      'cancelled',
              cancelledAt: new Date(),
              cancelReason: 'sequence_archived',
            },
          }
        );

        // Update sequence stats
        await AutomationSequence.updateOne(
          { _id: id },
          {
            $inc: {
              'stats.cancelledCount': activeEnrollments,
              'stats.activeCount':    -activeEnrollments,
            },
          }
        );
      }

      // Archive the sequence
      sequence.status    = 'archived';
      sequence.updatedBy = new mongoose.Types.ObjectId(auth.id);
      await sequence.save();

      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action:              'automation_sequence_archived',
          sequenceId:          String(sequence._id),
          cancelledEnrollments: activeEnrollments,
        },
      });

      res.status(200).json({
        success: true,
        message: activeEnrollments > 0
          ? `Sequence archived. ${activeEnrollments} active enrollment${activeEnrollments !== 1 ? 's' : ''} cancelled.`
          : 'Sequence archived successfully',
        cancelledEnrollments: activeEnrollments,
        requestId,
      });
      return;

    } catch (err) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action: 'automation_sequence_archive_error',
          error:  err instanceof Error ? err.message : 'unknown',
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to archive sequence',
        requestId,
      });
      return;
    }
  }
}

// pages/api/automation/sequences/index.ts
// ═══════════════════════════════════════════════════════════════
// AUTOMATION SEQUENCES API — LIST & CREATE
// Admin only — rate limited — full security
// ═══════════════════════════════════════════════════════════════
// GET  → List all sequences with stats + pagination
// POST → Create new automation sequence
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose                                  from 'mongoose';
import DOMPurify                                 from 'isomorphic-dompurify';
import dbConnect                                 from '@/lib/db';
import AutomationSequence                        from '@/models/AutomationSequence';
import AutomationEnrollment                      from '@/models/AutomationEnrollment';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';

// ─── Constants ────────────────────────────────────────────────

const MAX_NAME_LENGTH        = 150;
const MAX_DESC_LENGTH        = 1000;
const MAX_SUBJECT_LENGTH     = 200;
const MAX_PREVIEW_LENGTH     = 300;
const MAX_CONTENT_LENGTH     = 500_000;
const MAX_FROM_NAME_LENGTH   = 150;
const MAX_FROM_EMAIL_LENGTH  = 200;
const MAX_STEPS              = 20;
const DEFAULT_PAGE_LIMIT     = 20;
const MAX_PAGE_LIMIT         = 100;

const ALLOWED_TRIGGERS = [
  'subscriber_joined',
  'lead_created',
  'lead_status_changed',
  'manual',
] as const;

const ALLOWED_STATUSES = ['draft', 'active', 'paused', 'archived'] as const;

const ALLOWED_RECIPIENT_TYPES = [
  'subscribers',
  'leads',
  'both',
] as const;

const EMAIL_REGEX = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{1,63}$/;

// ─── Helpers ──────────────────────────────────────────────────

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  const cfIp = req.headers['cf-connecting-ip'];
  if (typeof cfIp === 'string') return cfIp.trim();
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('X-XSS-Protection',       '1; mode=block');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
}

function sanitizeText(text: string, maxLength: number): string {
  if (!text || typeof text !== 'string') return '';
  return text.replace(/<[^>]*>/g, '').trim().slice(0, maxLength);
}

function sanitizeHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      'a', 'b', 'br', 'div', 'em', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'hr', 'i', 'img', 'li', 'ol', 'p', 'span', 'strong', 'table',
      'tbody', 'td', 'th', 'thead', 'tr', 'ul', 'blockquote', 'code',
      'pre', 'small', 'sub', 'sup', 'u',
    ],
    ALLOWED_ATTR: [
      'href', 'target', 'rel', 'src', 'alt', 'width', 'height',
      'style', 'class', 'id', 'colspan', 'rowspan', 'align', 'valign',
      'bgcolor', 'border', 'cellpadding', 'cellspacing', 'title',
    ],
    ALLOW_DATA_ATTR:  false,
    FORBID_TAGS:      ['script', 'iframe', 'object', 'embed', 'form', 'input'],
    FORBID_ATTR:      ['onerror', 'onload', 'onclick', 'onmouseover', 'onfocus'],
  });
}

function validateEmail(email: string): boolean {
  if (!email) return true; // empty is allowed (optional field)
  return EMAIL_REGEX.test(email.trim().toLowerCase());
}

/**
 * Validate and sanitize a single step object from request body.
 * Returns cleaned step or null if invalid.
 */
function sanitizeStep(raw: any, stepIndex: number): {
  stepNumber:  number;
  delayDays:   number;
  subject:     string;
  previewText: string;
  content:     string;
  fromName:    string;
  fromEmail:   string;
  replyTo:     string;
} | null {
  if (!raw || typeof raw !== 'object') return null;

  const subject = sanitizeText(String(raw.subject || ''), MAX_SUBJECT_LENGTH);
  // Subject is required
  if (!subject) return null;

  const content = sanitizeHtml(String(raw.content || ''));
  // Content is required
  if (!content.trim()) return null;

  const delayDays = Math.max(
    0,
    Math.min(365, parseInt(String(raw.delayDays ?? 0), 10) || 0)
  );

  const fromEmail = String(raw.fromEmail || '').trim().toLowerCase();
  if (fromEmail && !validateEmail(fromEmail)) return null;

  return {
    stepNumber:  stepIndex + 1,
    delayDays,
    subject,
    previewText: sanitizeText(String(raw.previewText || ''), MAX_PREVIEW_LENGTH),
    content,
    fromName:    sanitizeText(String(raw.fromName   || ''), MAX_FROM_NAME_LENGTH),
    fromEmail,
    replyTo:     sanitizeText(String(raw.replyTo    || ''), MAX_FROM_EMAIL_LENGTH),
  };
}

// ─── Main Handler ─────────────────────────────────────────────

export default async function handler(
  req:  NextApiRequest,
  res:  NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ── Method guard ─────────────────────────────────────────────
  if (req.method !== 'GET' && req.method !== 'POST') {
    res.setHeader('Allow', ['GET', 'POST']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ── Rate limit ───────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:      'rate_limit_exceeded',
      severity:  'medium',
      ip:        clientIP,
      userAgent,
      metadata:  { requestId, action: 'automation_sequences_index' },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ── Auth guard ───────────────────────────────────────────────
  const auth = await requireAdmin(req, res);
  if (!auth) return;

  await dbConnect();

  // ════════════════════════════════════════════════════════════
  // GET — List all sequences
  // ════════════════════════════════════════════════════════════
  if (req.method === 'GET') {
    try {
      const {
        status,
        trigger,
        page  = '1',
        limit = String(DEFAULT_PAGE_LIMIT),
      } = req.query;

      // Pagination
      const pageNum  = Math.max(1, parseInt(String(page),  10) || 1);
      const limitNum = Math.min(
        MAX_PAGE_LIMIT,
        Math.max(1, parseInt(String(limit), 10) || DEFAULT_PAGE_LIMIT)
      );
      const skip = (pageNum - 1) * limitNum;

      // Build filter
      const filter: Record<string, unknown> = {};

      if (status && status !== 'all') {
        const statusStr = String(status);
        if (!ALLOWED_STATUSES.includes(statusStr as any)) {
          res.status(400).json({
            success: false,
            message: 'Invalid status filter',
            requestId,
          });
          return;
        }
        filter.status = statusStr;
      }

      if (trigger && trigger !== 'all') {
        const triggerStr = String(trigger);
        if (!ALLOWED_TRIGGERS.includes(triggerStr as any)) {
          res.status(400).json({
            success: false,
            message: 'Invalid trigger filter',
            requestId,
          });
          return;
        }
        filter.trigger = triggerStr;
      }

      // Fetch sequences + total
      const [sequences, total] = await Promise.all([
        AutomationSequence.find(filter)
          .sort({ createdAt: -1 })
          .skip(skip)
          .limit(limitNum)
          .select('-steps.content') // Exclude heavy content from list
          .lean(),
        AutomationSequence.countDocuments(filter),
      ]);

      // Aggregate summary stats across all sequences
      const [draft, active, paused, archived] = await Promise.all([
        AutomationSequence.countDocuments({ status: 'draft'    }),
        AutomationSequence.countDocuments({ status: 'active'   }),
        AutomationSequence.countDocuments({ status: 'paused'   }),
        AutomationSequence.countDocuments({ status: 'archived' }),
      ]);

      // Total active enrollments across all sequences
      const totalActiveEnrollments = await AutomationEnrollment.countDocuments({
        status: 'active',
      });

      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action: 'automation_sequences_listed',
          count:  sequences.length,
        },
      });

      res.status(200).json({
        success: true,
        sequences,
        stats: {
          total:   draft + active + paused + archived,
          draft,
          active,
          paused,
          archived,
          totalActiveEnrollments,
        },
        pagination: {
          page:       pageNum,
          limit:      limitNum,
          total,
          totalPages: Math.ceil(total / limitNum),
        },
        requestId,
      });
      return;

    } catch (err) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action: 'automation_sequences_list_error',
          error:  err instanceof Error ? err.message : 'unknown',
        },
      });
      res.status(500).json({
        success: false,
        message: 'Failed to fetch sequences',
        requestId,
      });
      return;
    }
  }

  // ════════════════════════════════════════════════════════════
  // POST — Create new sequence
  // ════════════════════════════════════════════════════════════
  if (req.method === 'POST') {
    try {
      const body = req.body || {};

      // ── Required field: name ──────────────────────────────
      const name = sanitizeText(String(body.name || ''), MAX_NAME_LENGTH);
      if (!name || name.length < 3) {
        res.status(400).json({
          success: false,
          message: 'Sequence name is required (minimum 3 characters)',
          requestId,
        });
        return;
      }

      // ── Required field: trigger ───────────────────────────
      const trigger = String(body.trigger || '');
      if (!ALLOWED_TRIGGERS.includes(trigger as any)) {
        res.status(400).json({
          success: false,
          message: `Invalid trigger. Must be one of: ${ALLOWED_TRIGGERS.join(', ')}`,
          requestId,
        });
        return;
      }

      // ── Optional: status (default draft) ─────────────────
      const status = String(body.status || 'draft');
      if (!ALLOWED_STATUSES.includes(status as any)) {
        res.status(400).json({
          success: false,
          message: `Invalid status. Must be one of: ${ALLOWED_STATUSES.join(', ')}`,
          requestId,
        });
        return;
      }

      // ── Optional: recipientType ───────────────────────────
      const recipientType = String(body.recipientType || 'subscribers');
      if (!ALLOWED_RECIPIENT_TYPES.includes(recipientType as any)) {
        res.status(400).json({
          success: false,
          message: `Invalid recipientType. Must be: ${ALLOWED_RECIPIENT_TYPES.join(', ')}`,
          requestId,
        });
        return;
      }

      // ── Optional: description ─────────────────────────────
      const description = sanitizeText(
        String(body.description || ''),
        MAX_DESC_LENGTH
      );

      // ── Optional: steps ───────────────────────────────────
      let cleanSteps: ReturnType<typeof sanitizeStep>[] = [];

      if (Array.isArray(body.steps) && body.steps.length > 0) {
        if (body.steps.length > MAX_STEPS) {
          res.status(400).json({
            success: false,
            message: `Maximum ${MAX_STEPS} steps allowed per sequence`,
            requestId,
          });
          return;
        }

        const sanitized = body.steps
          .map((s: any, i: number) => sanitizeStep(s, i))
          .filter(Boolean);

        cleanSteps = sanitized;
      }

      // ── Validate: cannot activate with empty steps ────────
      if (status === 'active' && cleanSteps.length === 0) {
        res.status(400).json({
          success: false,
          message: 'Cannot activate a sequence with no steps. Add at least one step.',
          requestId,
        });
        return;
      }

      // ── Optional: triggerFilters ──────────────────────────
      const rawFilters = body.triggerFilters || {};
      const triggerFilters = {
        leadStatuses:
          Array.isArray(rawFilters.leadStatuses)
            ? rawFilters.leadStatuses
                .filter((s: unknown) => typeof s === 'string')
                .slice(0, 20)
            : [],
        leadCities:
          Array.isArray(rawFilters.leadCities)
            ? rawFilters.leadCities
                .filter((s: unknown) => typeof s === 'string')
                .slice(0, 30)
            : [],
        leadSources:
          Array.isArray(rawFilters.leadSources)
            ? rawFilters.leadSources
                .filter((s: unknown) => typeof s === 'string')
                .slice(0, 20)
            : [],
        leadTypes:
          Array.isArray(rawFilters.leadTypes)
            ? rawFilters.leadTypes
                .filter((s: unknown) => typeof s === 'string')
                .slice(0, 20)
            : [],
        fromStatus:
          typeof rawFilters.fromStatus === 'string'
            ? sanitizeText(rawFilters.fromStatus, 60)
            : '',
        toStatus:
          typeof rawFilters.toStatus === 'string'
            ? sanitizeText(rawFilters.toStatus, 60)
            : '',
        subscriberSources:
          Array.isArray(rawFilters.subscriberSources)
            ? rawFilters.subscriberSources
                .filter((s: unknown) => typeof s === 'string')
                .slice(0, 20)
            : [],
      };

      // ── Optional: default sender ──────────────────────────
      const defaultFromName  = sanitizeText(
        String(body.defaultFromName  || 'Highrise.pk'),
        MAX_FROM_NAME_LENGTH
      );
      const defaultFromEmail = String(body.defaultFromEmail || '').trim().toLowerCase();
      const defaultReplyTo   = String(body.defaultReplyTo   || '').trim().toLowerCase();

      if (defaultFromEmail && !validateEmail(defaultFromEmail)) {
        res.status(400).json({
          success: false,
          message: 'Invalid default sender email address',
          requestId,
        });
        return;
      }
      if (defaultReplyTo && !validateEmail(defaultReplyTo)) {
        res.status(400).json({
          success: false,
          message: 'Invalid default reply-to email address',
          requestId,
        });
        return;
      }

      // ── Optional: safety settings ─────────────────────────
      const maxEnrollmentsPerDay = Math.max(
        1,
        Math.min(10_000, parseInt(String(body.maxEnrollmentsPerDay || 500), 10) || 500)
      );
      const skipIfAlreadyActive = body.skipIfAlreadyActive !== false;
      const stopOnUnsubscribe   = body.stopOnUnsubscribe   !== false;

      // ── Create sequence ───────────────────────────────────
      const sequence = await AutomationSequence.create({
        name,
        description,
        status,
        trigger,
        recipientType,
        triggerFilters,
        steps:              cleanSteps,
        defaultFromName,
        defaultFromEmail,
        defaultReplyTo,
        maxEnrollmentsPerDay,
        skipIfAlreadyActive,
        stopOnUnsubscribe,
        createdBy:          new mongoose.Types.ObjectId(auth.id),
        stats: {
          totalEnrolled:  0,
          activeCount:    0,
          completedCount: 0,
          cancelledCount: 0,
          failedCount:    0,
          emailsSent:     0,
          totalOpens:     0,
          totalClicks:    0,
        },
      });

      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action:     'automation_sequence_created',
          sequenceId: String(sequence._id),
          trigger,
          status,
          stepCount:  cleanSteps.length,
        },
      });

      res.status(201).json({
        success:  true,
        message:  'Automation sequence created successfully',
        sequence,
        requestId,
      });
      return;

    } catch (err) {
      const errMsg = err instanceof Error ? err.message : 'unknown';

      // Handle Mongoose validation errors cleanly
      if (errMsg.includes('Cannot activate') || errMsg.includes('All steps')) {
        res.status(400).json({
          success: false,
          message: errMsg,
          requestId,
        });
        return;
      }

      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        ip:       clientIP,
        userAgent,
        metadata: {
          requestId,
          action: 'automation_sequence_create_error',
          error:  errMsg.slice(0, 200),
        },
      });

      res.status(500).json({
        success: false,
        message: 'Failed to create sequence',
        requestId,
      });
      return;
    }
  }
}

// pages/api/blogs/[slug].ts
// 🔒 ENTERPRISE v2.0 - Read, Update, Delete Blogs with SEO & Analytics

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Blog from '@/models/Blog';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { rateLimitApi, rateLimitApiWrite } from '@/lib/rateLimit';
import DOMPurify from 'isomorphic-dompurify';

const MAX_TIME_MS = 5000;

function sanitizeHTML(html: string) {
  return DOMPurify.sanitize(html, {
    ADD_TAGS: ['iframe'],
    ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'scrolling'],
  });
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0] || req.socket.remoteAddress || '0.0.0.0';
  const { slug } = req.query;

  if (!slug || typeof slug !== 'string') {
    return res.status(400).json({ success: false, message: 'Invalid slug' });
  }

  try {
    await dbConnect();

    // ═══════════════════════════════════════════════════════════════
    // ✅ GET: FETCH SINGLE BLOG (With SEO & Analytics)
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'GET') {
      const rl = await rateLimitApi(req);
      if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

      const session = await getServerSession(req, res, authOptions);
      const userRole = String(session?.user?.role || '').toLowerCase();
      const isAdmin = userRole === 'admin' || userRole === 'superadmin';

      const query: any = { slug, isDeleted: { $ne: true } };

      // Guests only see published posts
      if (!isAdmin) {
        query.status = 'published';
        query.publishedAt = { $lte: new Date() };
      }

      const blog: any = await Blog.findOne(query)
        .populate('authorId', 'name image bio')
        .populate('relatedPosts', 'title slug image excerpt publishedAt')
        .lean()
        .maxTimeMS(MAX_TIME_MS);

      if (!blog) {
        return res.status(404).json({ success: false, message: 'Blog not found' });
      }

      // Fetch dynamic related posts if none explicitly set
      let relatedPosts = blog.relatedPosts || [];
      if (relatedPosts.length === 0) {
        relatedPosts = await Blog.find({
          _id: { $ne: blog._id },
          status: 'published',
          isDeleted: { $ne: true },
          $or: [{ category: blog.category }, { tags: { $in: blog.tags || [] } }]
        })
        .select('title slug image excerpt publishedAt')
        .limit(3)
        .lean()
        .maxTimeMS(MAX_TIME_MS);
      }

      // Atomic View Tracking (Non-blocking)
      Blog.findByIdAndUpdate(blog._id, { $inc: { views: 1 } }).exec().catch(console.error);

      // JSON-LD SEO Schema generation
      const jsonLd = {
        '@context': 'https://schema.org',
        '@type': 'BlogPosting',
        headline: blog.metaTitle || blog.title,
        image: blog.image?.url,
        datePublished: blog.publishedAt,
        dateModified: blog.updatedAt,
        author: {
          '@type': 'Person',
          name: blog.authorName,
        },
        publisher: {
          '@type': 'Organization',
          name: 'Highrise.pk',
          logo: {
            '@type': 'ImageObject',
            url: 'https://highrise.pk/logo.png', // Replace with actual logo URL
          },
        },
        description: blog.metaDescription || blog.excerpt,
      };

      res.setHeader('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');

      return res.status(200).json({
        success: true,
        blog: { ...blog, content: sanitizeHTML(blog.content || ''), views: (blog.views || 0) + 1 },
        relatedPosts,
        seo: jsonLd
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ PROTECTED METHODS: REQUIRE ADMIN
    // ═══════════════════════════════════════════════════════════════
    const session = await getServerSession(req, res, authOptions);
    if (!session?.user) return res.status(401).json({ success: false, message: 'Unauthorized' });

    const user: any = await User.findById(session.user.id).lean();
    if (!['admin', 'superadmin', 'editor'].includes(user?.role?.toLowerCase())) {
      return res.status(403).json({ success: false, message: 'Forbidden' });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ PUT: UPDATE BLOG
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'PUT') {
      const rl = await rateLimitApiWrite(req);
      if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

      const updates = { ...req.body };

      // Prevent modifying critical fields
      delete updates._id;
      delete updates.views;
      delete updates.commentCount;

      // XSS Sanitization
      if (updates.content) updates.content = sanitizeHTML(updates.content);
      if (updates.excerpt) updates.excerpt = sanitizeHTML(updates.excerpt);

      // Tracking edits
      updates.lastEditedBy = user._id;
      updates.lastEditedAt = new Date();
      updates.$inc = { editCount: 1 };

      if (updates.status === 'published' && !updates.publishedAt) {
        updates.publishedAt = new Date();
      }

      const blog = await Blog.findOneAndUpdate(
        { slug },
        updates,
        { new: true, runValidators: true }
      ).maxTimeMS(MAX_TIME_MS);

      if (!blog) return res.status(404).json({ success: false, message: 'Blog not found' });

      SecurityEvent.create({
        eventType: 'blog_updated',
        userId: user._id,
        severity: 'info',
        ipAddress: ip,
        metadata: { blogId: blog._id, slug }
      }).catch(console.error);

      return res.status(200).json({ success: true, message: 'Blog updated successfully', blog });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ DELETE: SOFT DELETE BLOG
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'DELETE') {
      const rl = await rateLimitApiWrite(req);
      if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

      const blog = await Blog.findOneAndUpdate(
        { slug },
        { 
          isDeleted: true, 
          deletedAt: new Date(), 
          status: 'draft' // Take it offline immediately
        },
        { new: true }
      );

      if (!blog) return res.status(404).json({ success: false, message: 'Blog not found' });

      SecurityEvent.create({
        eventType: 'blog_deleted',
        userId: user._id,
        severity: 'high',
        ipAddress: ip,
        metadata: { blogId: blog._id, slug }
      }).catch(console.error);

      return res.status(200).json({ success: true, message: 'Blog moved to trash' });
    }

    return res.status(405).json({ success: false, message: 'Method not allowed' });

  } catch (error: any) {
    console.error('Blog API Error:', error);
    return res.status(500).json({ success: false, message: 'Internal Server Error' });
  }
}

import type { NextApiRequest, NextApiResponse } from 'next';
import crypto from 'crypto';
import { z } from 'zod';
import DOMPurify from 'isomorphic-dompurify';

import dbConnect from '@/lib/db';
import Blog from '@/models/Blog';
import ApiKey from '@/models/ApiKey';
import SecurityEvent from '@/models/SecurityEvent';
import { rateLimitApiWrite } from '@/lib/rateLimit';

import { v2 as cloudinary } from 'cloudinary';

cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
});

export const config = {
  api: {
    bodyParser: {
      sizeLimit: '10mb',
    },
  },
};

const MAX_TIME_MS = 5000;

const AutoPostSchema = z.object({
  title: z.string().trim().min(10).max(200),
  excerpt: z.string().trim().min(20).max(500),
  content: z.string().trim().min(100).max(50000),
  category: z.enum([
    'Investment',
    'Legal',
    'Guide',
    'Technology',
    'Market Analysis',
    'News',
    'Tips',
    'Lifestyle',
  ]),
  authorName: z.string().trim().min(2).max(100).optional(),
  imageUrl: z.string().url().optional(),
  imageBase64: z.string().optional(),
  tags: z.array(z.string().trim().min(1).max(50)).max(15).optional().default([]),
  publishNow: z.boolean().optional().default(true),
  scheduledFor: z.string().datetime().optional(),
  metaTitle: z.string().trim().max(70).optional(),
  metaDescription: z.string().trim().max(160).optional(),
  aiMetadata: z
    .object({
      model: z.string().trim().max(100),
      generatedAt: z.string().datetime().optional(),
      sources: z.array(z.string().url()).max(20).optional().default([]),
    })
    .optional(),
}).refine(
  (data) => Boolean(data.imageUrl || data.imageBase64),
  {
    message: 'Either imageUrl or imageBase64 is required',
    path: ['imageUrl'],
  }
);

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || '').split(',')[0]?.trim() || req.socket?.remoteAddress || '0.0.0.0';
}

function sanitizeHTML(html: string): string {
  return DOMPurify.sanitize(html, {
    ADD_TAGS: ['iframe'],
    ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'scrolling'],
  });
}

async function validateApiKey(apiKey: string): Promise<any> {

  if (!apiKey) return null;

  const hashedKey = crypto.createHash('sha256').update(apiKey).digest('hex');

  const keyDoc: any = await ApiKey.findOne({

    hashedKey,
    isActive: true,
    permissions: { $in: ['blog:create'] },
    $or: [{ expiresAt: null }, { expiresAt: { $gt: new Date() } }],
  })
    .lean()
    .maxTimeMS(MAX_TIME_MS);

  if (!keyDoc) return null;

  await ApiKey.updateOne(
    { _id: keyDoc._id },
    {
      $set: { lastUsedAt: new Date() },
      $inc: { usageCount: 1 },
    }
  ).maxTimeMS(MAX_TIME_MS);

  return keyDoc;
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  const ip = getClientIp(req);

  res.setHeader('X-Request-Id', requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Frame-Options', 'DENY');

  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    return res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
  }

  try {
    await dbConnect();

    // 1. Rate limit
    const rl = await rateLimitApiWrite(req);
    if (!rl.ok) {
      res.setHeader('Retry-After', String(rl.retryAfter || 60));
      return res.status(429).json({
        success: false,
        message: 'Too many requests',
        code: 'RATE_LIMITED',
        requestId,
      });
    }

    // 2. Validate API key
    const apiKey = String(req.headers['x-api-key'] || '');
    if (!apiKey) {
      return res.status(401).json({
        success: false,
        message: 'API key required. Include X-API-Key header.',
        code: 'API_KEY_REQUIRED',
        requestId,
      });
    }

    const keyDoc: any = await validateApiKey(apiKey);
    if (!keyDoc) {
      SecurityEvent.create({
        eventType: 'blog_auto_post_invalid_api_key',
        severity: 'high',
        ipAddress: ip,
        metadata: { requestId },
      }).catch(console.error);

      return res.status(403).json({
        success: false,
        message: 'Invalid or expired API key',
        code: 'INVALID_API_KEY',
        requestId,
      });
    }

    // 3. Validate body
    const parsed = AutoPostSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({
        success: false,
        message: 'Invalid request body',
        code: 'VALIDATION_ERROR',
        errors: parsed.error.format(),
        requestId,
      });
    }

    const {
      title,
      excerpt,
      content,
      category,
      authorName,
      imageUrl,
      imageBase64,
      tags,
      publishNow,
      scheduledFor,
      metaTitle,
      metaDescription,
      aiMetadata,
    } = parsed.data;

    // 4. Scheduled time safety
    let safeScheduledFor: Date | null = null;
    if (scheduledFor) {
      const scheduledDate = new Date(scheduledFor);
      if (scheduledDate <= new Date()) {
        return res.status(400).json({
          success: false,
          message: 'scheduledFor must be in the future',
          code: 'INVALID_SCHEDULE_TIME',
          requestId,
        });
      }
      safeScheduledFor = scheduledDate;
    }

    // 5. Sanitize content
    const cleanExcerpt = sanitizeHTML(excerpt);
    const cleanContent = sanitizeHTML(content);

    // 6. Image upload
    let image = { url: '', public_id: '' };

    if (imageBase64) {
      const uploadResult = await cloudinary.uploader.upload(imageBase64, {
        folder: 'highrise-pk/blogs',
        transformation: [
          { width: 1200, height: 630, crop: 'fill' },
          { quality: 'auto' },
          { format: 'webp' },
        ],
      });
      image = {
        url: uploadResult.secure_url,
        public_id: uploadResult.public_id,
      };
    } else if (imageUrl) {
      // Optional safety: only allow remote HTTPS images
      if (!imageUrl.startsWith('https://')) {
        return res.status(400).json({
          success: false,
          message: 'Only HTTPS image URLs are allowed',
          code: 'INVALID_IMAGE_URL',
          requestId,
        });
      }

      const uploadResult = await cloudinary.uploader.upload(imageUrl, {
        folder: 'highrise-pk/blogs',
        transformation: [
          { width: 1200, height: 630, crop: 'fill' },
          { quality: 'auto' },
          { format: 'webp' },
        ],
      });
      image = {
        url: uploadResult.secure_url,
        public_id: uploadResult.public_id,
      };
    }

    // 7. Create blog
    const blog = await Blog.create({
      title,
      excerpt: cleanExcerpt,
      content: cleanContent,
      category,
      authorName: authorName || 'AI Writer',
      image,
      tags,
      status: publishNow ? 'published' : safeScheduledFor ? 'scheduled' : 'draft',
      publishedAt: publishNow ? new Date() : null,
      scheduledFor: safeScheduledFor,
      metaTitle: metaTitle || title.slice(0, 70),
      metaDescription: metaDescription || excerpt.slice(0, 160),
      source: 'ai_generated',
      aiMetadata: aiMetadata
        ? {
            model: aiMetadata.model,
            generatedAt: aiMetadata.generatedAt ? new Date(aiMetadata.generatedAt) : new Date(),
            sources: aiMetadata.sources || [],
          }
        : {
            model: 'unknown',
            generatedAt: new Date(),
            sources: [],
          },
      isDeleted: false,
    });

    // 8. Security / audit log
    SecurityEvent.create({
      eventType: 'blog_auto_post_created',
      severity: 'medium',
      ipAddress: ip,
      metadata: {
        requestId,
        blogId: blog._id,
        title: blog.title,
        status: blog.status,
        apiKeyId: keyDoc._id,
        source: 'ai_generated',
      },
    }).catch(console.error);

    return res.status(201).json({
      success: true,
      message: 'Blog post created successfully via AI agent',
      blog: {
        id: blog._id,
        title: blog.title,
        slug: blog.slug,
        status: blog.status,
        url: `https://highrise.pk/blog/${blog.slug}`,
      },
      requestId,
    });
  } catch (error: any) {
    console.error('Error in AI auto-post:', error);

    SecurityEvent.create({
      eventType: 'blog_auto_post_failed',
      severity: 'high',
      ipAddress: ip,
      metadata: {
        requestId,
        errorCode: error?.code || 'UNKNOWN',
      },
    }).catch(console.error);

    return res.status(500).json({
      success: false,
      message: 'Error creating blog post',
      code: 'SERVER_ERROR',
      requestId,
    });
  }
}

// pages/api/blogs/index.ts
// 🔒 ENTERPRISE v2.0 - Blog List & Creation with Full SEO, XSS Protection & RBAC

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/db';
import Blog from '@/models/Blog';
import User from '@/models/User';
import SecurityEvent from '@/models/SecurityEvent';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/pages/api/auth/[...nextauth]';
import { rateLimitApi, rateLimitApiWrite } from '@/lib/rateLimit';
import { z } from 'zod';
import DOMPurify from 'isomorphic-dompurify';

// ═══════════════════════════════════════════════════════════════
// 🔒 ENTERPRISE CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TIME_MS = 5000;
const MAX_LIMIT = 50;
const DEFAULT_LIMIT = 12;

// ═══════════════════════════════════════════════════════════════
// 🔒 ZOD SCHEMAS
// ═══════════════════════════════════════════════════════════════

const GetBlogsSchema = z.object({
  page: z.coerce.number().min(1).default(1),
  limit: z.coerce.number().min(1).max(MAX_LIMIT).default(DEFAULT_LIMIT),
  category: z.string().optional(),
  tag: z.string().optional(),
  search: z.string().max(100).optional(),
  featured: z.enum(['true', 'false']).optional(),
  status: z.enum(['published', 'draft', 'all']).default('published'),
  sort: z.enum(['latest', 'oldest', 'popular', 'featured']).default('latest'),
});

const CreateBlogSchema = z.object({
  title: z.string().trim().min(5).max(200),
  excerpt: z.string().trim().min(10).max(500),
  content: z.string().trim().min(50),
  category: z.string(),
  tags: z.array(z.string()).default([]),
  image: z.object({
    url: z.string().url(),
    public_id: z.string(),
  }),
  status: z.enum(['draft', 'published', 'scheduled']).default('draft'),
  featured: z.boolean().default(false),
  metaTitle: z.string().max(70).optional(),
  metaDescription: z.string().max(160).optional(),
  scheduledFor: z.string().datetime().optional(),
  allowComments: z.boolean().default(true),
});

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPERS
// ═══════════════════════════════════════════════════════════════

function escapeRegex(text: string) {
  return text.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&');
}

function sanitizeHTML(html: string) {
  return DOMPurify.sanitize(html, {
    ADD_TAGS: ['iframe'], // Allow YouTube/maps embeds
    ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'scrolling'],
  });
}

function generateSlug(title: string) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '') + '-' + Math.random().toString(36).slice(2, 8);
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0] || req.socket.remoteAddress || '0.0.0.0';

  try {
    await dbConnect();

    // ═══════════════════════════════════════════════════════════════
    // ✅ GET: FETCH BLOGS (Public)
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'GET') {
      const rl = await rateLimitApi(req);
      if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

      // Edge Caching for fast reads
      res.setHeader('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');

      const parsed = GetBlogsSchema.safeParse(req.query);
      if (!parsed.success) return res.status(400).json({ success: false, error: parsed.error.format() });

      const { page, limit, category, tag, search, featured, status, sort } = parsed.data;
      const skip = (page - 1) * limit;

      // Build Query
      const query: any = { isDeleted: { $ne: true } };

      // Secure Status checking (Guests can ONLY see published)
      const session = await getServerSession(req, res, authOptions);
      const userRole = String(session?.user?.role || '').toLowerCase();
const isAdmin = userRole === 'admin' || userRole === 'superadmin';

      if (!isAdmin || status === 'published') {
        query.status = 'published';
        query.publishedAt = { $lte: new Date() }; // Ensure scheduled posts aren't shown
      } else if (status !== 'all') {
        query.status = status;
      }

      if (category && category !== 'All') query.category = category;
      if (tag) query.tags = { $in: [tag] };
      if (featured === 'true') query.featured = true;

      if (search) {
        const safeSearch = escapeRegex(search);
        query.$or = [
          { title: { $regex: safeSearch, $options: 'i' } },
          { excerpt: { $regex: safeSearch, $options: 'i' } },
        ];
      }

            // Smart Sorting
      let sortQuery: Record<string, 1 | -1> = { publishedAt: -1, createdAt: -1 };

      switch (sort) {
        case 'oldest':
          sortQuery = { publishedAt: 1, createdAt: 1 };
          break;
        case 'popular':
          sortQuery = { views: -1, publishedAt: -1, createdAt: -1 };
          break;
        case 'featured':
          sortQuery = { featured: -1, featuredPriority: -1, publishedAt: -1, createdAt: -1 };
          break;
        case 'latest':
        default:
          sortQuery = { publishedAt: -1, createdAt: -1 };
          break;
      }

      // If explicitly requesting featured=true, ensure featured-first relevance
      if (featured === 'true' && sort !== 'oldest' && sort !== 'popular') {
        sortQuery = { featuredPriority: -1, publishedAt: -1, createdAt: -1 };
      }

      // Execute Queries
      const [blogs, total, categoryCounts] = await Promise.all([
        Blog.find(query)
          .select('-content -tableOfContents -editHistory') // Exclude heavy fields
          .sort(sortQuery)
          .skip(skip)
          .limit(limit)
          .lean()
          .maxTimeMS(MAX_TIME_MS),
        Blog.countDocuments(query).maxTimeMS(MAX_TIME_MS),
        Blog.aggregate([
          {
            $match: {
              status: 'published',
              isDeleted: { $ne: true },
              publishedAt: { $lte: new Date() },
            },
          },
          { $group: { _id: '$category', count: { $sum: 1 } } },
          { $sort: { count: -1 } }
        ]).option({ maxTimeMS: MAX_TIME_MS })
      ]);

      return res.status(200).json({
        success: true,
        blogs,
        sort,
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit),
          hasMore: page * limit < total,
        },
        categories: categoryCounts,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ POST: CREATE BLOG (Admin Only)
    // ═══════════════════════════════════════════════════════════════
    if (req.method === 'POST') {
      const rl = await rateLimitApiWrite(req);
      if (!rl.ok) return res.status(429).json({ success: false, message: 'Too many requests' });

      // 1. Authenticate & Authorize
      const session = await getServerSession(req, res, authOptions);
      if (!session?.user) return res.status(401).json({ success: false, message: 'Unauthorized' });

      const user: any = await User.findById(session.user.id).lean();
      if (!['admin', 'superadmin', 'editor'].includes(user?.role?.toLowerCase())) {
        return res.status(403).json({ success: false, message: 'Forbidden: Admin access required' });
      }

      // 2. Validate Body
      const parsed = CreateBlogSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ success: false, error: parsed.error.format() });
      const data = parsed.data;

      // 3. XSS Protection
      const cleanContent = sanitizeHTML(data.content);
      const cleanExcerpt = sanitizeHTML(data.excerpt);

      // 4. Generate Unique Slug
      let baseSlug = generateSlug(data.title);
      let slugExists = await Blog.exists({ slug: baseSlug });
      while (slugExists) {
        baseSlug = generateSlug(data.title);
        slugExists = await Blog.exists({ slug: baseSlug });
      }

      // 5. Create Blog
      const newBlog = await Blog.create({
        ...data,
        content: cleanContent,
        excerpt: cleanExcerpt,
        slug: baseSlug,
        authorId: user._id,
        authorName: user.name || 'Admin',
        authorAvatar: user.image,
        publishedAt: data.status === 'published' ? new Date() : null,
        scheduledFor: data.scheduledFor ? new Date(data.scheduledFor) : null,
        isDeleted: false,
      });

      // 6. Audit Log
      SecurityEvent.create({
        eventType: 'blog_created',
        userId: user._id,
        severity: 'info',
        ipAddress: ip,
        metadata: { blogId: newBlog._id, title: newBlog.title, status: newBlog.status }
      }).catch(console.error);

      return res.status(201).json({
        success: true,
        message: 'Blog created successfully',
        blog: newBlog,
      });
    }

    return res.status(405).json({ success: false, message: 'Method not allowed' });

  } catch (error: any) {
    console.error('Blog API Error:', error);
    return res.status(500).json({ success: false, message: 'Internal Server Error' });
  }
}

import { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import Blog from '@/models/Blog';

// ─────────────────────────────────────────────────────────────────────────────
// CONFIGURATION
// ─────────────────────────────────────────────────────────────────────────────

const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL || 'https://highrise.pk';
const SITE_NAME = 'Highrise.pk';
const SITE_DESCRIPTION = 'Pakistan\'s premier real estate platform - Expert insights, market trends, legal guides, and investment advice for property buyers, sellers, and investors.';
const FEED_LANGUAGE = 'en-us';
const FEED_TTL = 60; // Minutes before feed should be refreshed
const MAX_ITEMS = 50; // Maximum items in feed

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Escape XML special characters
// ─────────────────────────────────────────────────────────────────────────────

function escapeXml(text: string): string {
  if (!text) return '';
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Strip HTML tags for plain text
// ─────────────────────────────────────────────────────────────────────────────

function stripHtml(html: string): string {
  if (!html) return '';
  return html
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Format date to RFC 822 (RSS standard)
// ─────────────────────────────────────────────────────────────────────────────

function formatRFC822(date: Date): string {
  return date.toUTCString();
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Generate GUID
// ─────────────────────────────────────────────────────────────────────────────

function generateGuid(slug: string): string {
  return `${SITE_URL}/blog/${slug}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN HANDLER
// ─────────────────────────────────────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // Only allow GET
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).end('Method Not Allowed');
  }

  try {
    await dbConnect();

    // Optional category filter
    const { category } = req.query;
    
    // Build query
    const query: Record<string, any> = {
      status: 'published',
      publishedAt: { $lte: new Date() },
    };

    if (category && typeof category === 'string') {
      query.category = new RegExp(`^${category}$`, 'i');
    }

    // Fetch published blogs
    const blogs = await Blog.find(query)
      .sort({ publishedAt: -1 })
      .limit(MAX_ITEMS)
      .select('title slug excerpt content category author authorName publishedAt image readTime tags')
      .populate('authorId', 'name')
      .lean();

    // Get latest publish date for lastBuildDate
    const lastBuildDate = blogs.length > 0 && blogs[0].publishedAt
      ? new Date(blogs[0].publishedAt)
      : new Date();

    // Build RSS XML
    const rssXml = buildRssXml(blogs, lastBuildDate, category as string | undefined);

    // Set headers
    res.setHeader('Content-Type', 'application/xml; charset=utf-8');
    res.setHeader('Cache-Control', 'public, s-maxage=3600, stale-while-revalidate=86400');
    res.setHeader('X-Content-Type-Options', 'nosniff');

    return res.status(200).send(rssXml);

  } catch (error) {
    console.error('RSS Feed Error:', error);
    
    // Return valid XML error
    res.setHeader('Content-Type', 'application/xml; charset=utf-8');
    return res.status(500).send(`<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>Error</title>
    <description>Unable to generate RSS feed</description>
  </channel>
</rss>`);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// BUILD RSS XML
// ─────────────────────────────────────────────────────────────────────────────

function buildRssXml(
  blogs: any[],
  lastBuildDate: Date,
  category?: string
): string {
  const feedTitle = category
    ? `${escapeXml(category)} Articles - ${SITE_NAME}`
    : `${SITE_NAME} Blog`;

  const feedDescription = category
    ? `Latest ${category.toLowerCase()} articles and insights from ${SITE_NAME}`
    : SITE_DESCRIPTION;

  const feedUrl = category
    ? `${SITE_URL}/api/blogs/rss?category=${encodeURIComponent(category)}`
    : `${SITE_URL}/api/blogs/rss`;

  const items = blogs.map((blog) => buildItemXml(blog)).join('\n');

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" 
  xmlns:atom="http://www.w3.org/2005/Atom"
  xmlns:dc="http://purl.org/dc/elements/1.1/"
  xmlns:content="http://purl.org/rss/1.0/modules/content/"
  xmlns:media="http://search.yahoo.com/mrss/">
  <channel>
    <title>${escapeXml(feedTitle)}</title>
    <link>${SITE_URL}/blog</link>
    <description>${escapeXml(feedDescription)}</description>
    <language>${FEED_LANGUAGE}</language>
    <lastBuildDate>${formatRFC822(lastBuildDate)}</lastBuildDate>
    <ttl>${FEED_TTL}</ttl>
    <generator>Highrise.pk Blog Platform</generator>
    <docs>https://www.rssboard.org/rss-specification</docs>
    
    <atom:link href="${escapeXml(feedUrl)}" rel="self" type="application/rss+xml"/>
    
    <image>
      <url>${SITE_URL}/logo.png</url>
      <title>${escapeXml(feedTitle)}</title>
      <link>${SITE_URL}</link>
      <width>144</width>
      <height>144</height>
    </image>
    
    <copyright>Copyright ${new Date().getFullYear()} ${SITE_NAME}. All rights reserved.</copyright>
    <managingEditor>info@highrise.pk (${SITE_NAME} Editorial)</managingEditor>
    <webMaster>tech@highrise.pk (${SITE_NAME} Tech Team)</webMaster>
    
    <category>Real Estate</category>
    <category>Property</category>
    <category>Pakistan</category>
    <category>Investment</category>
    
${items}
  </channel>
</rss>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// BUILD ITEM XML
// ─────────────────────────────────────────────────────────────────────────────

function buildItemXml(blog: any): string {
  const title = escapeXml(blog.title || 'Untitled');
  const link = generateGuid(blog.slug);
  const guid = link;
  
  // Get description (excerpt or stripped content)
  const description = escapeXml(
    blog.excerpt || stripHtml(blog.content || '').substring(0, 300) + '...'
  );
  
  // Full content with CDATA
  const contentEncoded = blog.content
    ? `<content:encoded><![CDATA[${blog.content}]]></content:encoded>`
    : '';
  
  // Author
  const authorName = blog.authorId?.name || blog.authorName || blog.author || 'Highrise Team';
  const authorElement = `<dc:creator>${escapeXml(authorName)}</dc:creator>`;
  
  // Date
  const pubDate = blog.publishedAt
    ? formatRFC822(new Date(blog.publishedAt))
    : formatRFC822(new Date());
  
  // Category
  const categoryElement = blog.category
    ? `<category>${escapeXml(blog.category)}</category>`
    : '';
  
  // Tags as additional categories
  const tagElements = (blog.tags || [])
    .map((tag: string) => `<category>${escapeXml(tag)}</category>`)
    .join('\n      ');
  
  // Featured image
  let mediaElement = '';
  if (blog.image?.url) {
    const imageUrl = escapeXml(blog.image.url);
    mediaElement = `
      <enclosure url="${imageUrl}" type="image/jpeg" length="0"/>
      <media:content url="${imageUrl}" medium="image">
        <media:title>${title}</media:title>
      </media:content>`;
  }
  
  // Read time
  const readTime = blog.readTime || '5 min read';

  return `    <item>
      <title>${title}</title>
      <link>${link}</link>
      <guid isPermaLink="true">${guid}</guid>
      <description>${description}</description>
      ${contentEncoded}
      ${authorElement}
      <pubDate>${pubDate}</pubDate>
      ${categoryElement}
      ${tagElements}
      ${mediaElement}
      <comments>${link}#comments</comments>
    </item>`;
}

import { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import Blog from '@/models/Blog';

// ─────────────────────────────────────────────────────────────────────────────
// CONFIGURATION
// ─────────────────────────────────────────────────────────────────────────────

const DEFAULT_LIMIT = 12;
const MAX_LIMIT = 50;

// ─────────────────────────────────────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────────────────────────────────────

interface SearchFilters {
  query?: string;
  category?: string;
  tags?: string[];
  author?: string;
  dateFrom?: string;
  dateTo?: string;
  sort?: 'relevance' | 'newest' | 'oldest' | 'popular';
  page?: number;
  limit?: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Sanitize search query
// ─────────────────────────────────────────────────────────────────────────────

function sanitizeQuery(query: string): string {
  if (!query) return '';
  // Remove special regex characters, trim, limit length
  return query
    .replace(/[.*+?^${}()|[\]\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 200);
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Parse request params
// ─────────────────────────────────────────────────────────────────────────────

function parseFilters(req: NextApiRequest): SearchFilters {
  const {
    q,
    query,
    category,
    tags,
    author,
    dateFrom,
    dateTo,
    sort = 'relevance',
    page = '1',
    limit = String(DEFAULT_LIMIT),
  } = req.query;

  // Parse tags (can be comma-separated or array)
  let parsedTags: string[] = [];
  if (tags) {
    if (Array.isArray(tags)) {
      parsedTags = tags.map((t) => String(t).trim()).filter(Boolean);
    } else {
      parsedTags = String(tags)
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean);
    }
  }

  return {
    query: sanitizeQuery(String(q || query || '')),
    category: category ? String(category).trim() : undefined,
    tags: parsedTags.length > 0 ? parsedTags : undefined,
    author: author ? String(author).trim() : undefined,
    dateFrom: dateFrom ? String(dateFrom) : undefined,
    dateTo: dateTo ? String(dateTo) : undefined,
    sort: ['relevance', 'newest', 'oldest', 'popular'].includes(String(sort))
      ? (String(sort) as SearchFilters['sort'])
      : 'relevance',
    page: Math.max(1, parseInt(String(page), 10) || 1),
    limit: Math.min(MAX_LIMIT, Math.max(1, parseInt(String(limit), 10) || DEFAULT_LIMIT)),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN HANDLER
// ─────────────────────────────────────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  try {
    await dbConnect();

    const filters = parseFilters(req);
    const { query, category, tags, author, dateFrom, dateTo, sort, page, limit } = filters;

    // ─────────────────────────────────────────────────────────────────────────
    // BUILD QUERY
    // ─────────────────────────────────────────────────────────────────────────

    const matchConditions: Record<string, any> = {
      status: 'published',
      publishedAt: { $lte: new Date() },
    };

    // Text search
    let useTextScore = false;
    if (query && query.length >= 2) {
      // Try text search first, fallback to regex
      try {
        matchConditions.$text = { $search: query };
        useTextScore = true;
      } catch {
        // Fallback to regex search
        const searchRegex = new RegExp(query, 'i');
        matchConditions.$or = [
          { title: searchRegex },
          { excerpt: searchRegex },
          { content: searchRegex },
          { tags: searchRegex },
        ];
      }
    }

    // Category filter
    if (category) {
      matchConditions.category = new RegExp(`^${category.replace(/-/g, '[\\s-]')}$`, 'i');
    }

    // Tags filter
    if (tags && tags.length > 0) {
      matchConditions.tags = {
        $in: tags.map((tag) => new RegExp(tag.replace(/-/g, '[\\s-]'), 'i')),
      };
    }

    // Author filter
    if (author) {
      const authorRegex = new RegExp(author.replace(/-/g, '[\\s-]'), 'i');
      matchConditions.$or = [
        { author: authorRegex },
        { authorName: authorRegex },
      ];
    }

    // Date range filter
    if (dateFrom || dateTo) {
      matchConditions.publishedAt = matchConditions.publishedAt || {};
      if (dateFrom) {
        matchConditions.publishedAt.$gte = new Date(dateFrom);
      }
      if (dateTo) {
        matchConditions.publishedAt.$lte = new Date(dateTo);
      }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // BUILD SORT
    // ─────────────────────────────────────────────────────────────────────────

    let sortOption: Record<string, any> = { publishedAt: -1 };

    switch (sort) {
      case 'relevance':
        if (useTextScore) {
          sortOption = { score: { $meta: 'textScore' }, publishedAt: -1 };
        }
        break;
      case 'newest':
        sortOption = { publishedAt: -1 };
        break;
      case 'oldest':
        sortOption = { publishedAt: 1 };
        break;
      case 'popular':
        sortOption = { views: -1, publishedAt: -1 };
        break;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // EXECUTE QUERY
    // ─────────────────────────────────────────────────────────────────────────

    const skip = ((page || 1) - 1) * (limit || DEFAULT_LIMIT);

    // Build projection
    const projection: Record<string, any> = {
      title: 1,
      slug: 1,
      excerpt: 1,
      category: 1,
      author: 1,
      authorName: 1,
      publishedAt: 1,
      image: 1,
      readTime: 1,
      views: 1,
      tags: 1,
      featured: 1,
    };

    if (useTextScore) {
      projection.score = { $meta: 'textScore' };
    }

    // Get results
    let resultsQuery = Blog.find(matchConditions, projection)
      .sort(sortOption)
      .skip(skip)
      .limit(limit || DEFAULT_LIMIT)
      .lean();

    // Get total count
    const [results, totalCount] = await Promise.all([
      resultsQuery.exec(),
      Blog.countDocuments(matchConditions),
    ]);

    // ─────────────────────────────────────────────────────────────────────────
    // FORMAT RESPONSE
    // ─────────────────────────────────────────────────────────────────────────

    const articles = results.map((article: any) => ({
      _id: article._id.toString(),
      title: article.title,
      slug: article.slug,
      excerpt: article.excerpt || '',
      category: article.category || 'General',
      author: article.authorName || article.author || 'Highrise Team',
      publishedAt: article.publishedAt?.toISOString() || null,
      image: article.image?.url || null,
      readTime: article.readTime || '5 min read',
      views: article.views || 0,
      tags: article.tags || [],
      featured: article.featured || false,
      relevanceScore: article.score || null,
    }));

    const totalPages = Math.ceil(totalCount / (limit || DEFAULT_LIMIT));

    // ─────────────────────────────────────────────────────────────────────────
    // GET FILTER OPTIONS (for UI)
    // ─────────────────────────────────────────────────────────────────────────

    const [categories, popularTags] = await Promise.all([
      Blog.distinct('category', {
        status: 'published',
        publishedAt: { $lte: new Date() },
        category: { $ne: null },
      }),
      Blog.aggregate([
        { $match: { status: 'published', publishedAt: { $lte: new Date() } } },
        { $unwind: '$tags' },
        { $group: { _id: '$tags', count: { $sum: 1 } } },
        { $sort: { count: -1 } },
        { $limit: 20 },
      ]).exec(),
    ]);

    // ─────────────────────────────────────────────────────────────────────────
    // SEND RESPONSE
    // ─────────────────────────────────────────────────────────────────────────

    res.setHeader('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');

    return res.status(200).json({
      success: true,
      query: query || null,
      filters: {
        category: category || null,
        tags: tags || [],
        author: author || null,
        dateFrom: dateFrom || null,
        dateTo: dateTo || null,
      },
      sort,
      pagination: {
        page,
        limit,
        totalCount,
        totalPages,
        hasMore: (page || 1) < totalPages,
      },
      results: articles,
      filterOptions: {
        categories: categories.filter(Boolean).sort(),
        popularTags: popularTags.map((t: any) => ({
          tag: t._id,
          count: t.count,
        })),
      },
    });

  } catch (error) {
    console.error('Blog Search Error:', error);
    return res.status(500).json({
      success: false,
      message: 'Search failed. Please try again.',
    });
  }
}

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import Blog from '@/models/Blog';

type TrendingBlog = {
  _id: string;
  title: string;
  slug: string;
  category: string;
  readTime?: string;
  views?: number;
  commentCount?: number;
  shareCount?: number;
  likeCount?: number;
  trendingScore: number;
  publishedAt?: string | null;
  createdAt?: string | null;
  image?: {
    url?: string;
    public_id?: string;
  };
};

type TrendingResponse =
  | {
      success: true;
      blogs: TrendingBlog[];
    }
  | {
      success: false;
      message: string;
    };

const DEFAULT_LIMIT = 4;
const MAX_LIMIT = 10;

function getRecencyBoost(publishedAt?: Date | string | null) {
  if (!publishedAt) return 0;

  const publishedTime = new Date(publishedAt).getTime();
  if (Number.isNaN(publishedTime)) return 0;

  const now = Date.now();
  const diffDays = Math.floor((now - publishedTime) / (1000 * 60 * 60 * 24));

  if (diffDays <= 7) return 120;
  if (diffDays <= 30) return 60;
  if (diffDays <= 90) return 25;
  return 0;
}

function calculateTrendingScore(post: any) {
  const views = Number(post?.views || 0);
  const commentCount = Number(post?.commentCount || 0);
  const shareCount = Number(post?.shareCount || 0);
  const likeCount = Number(post?.likeCount || 0);
  const recencyBoost = getRecencyBoost(post?.publishedAt || post?.createdAt || null);

  return (
    views * 1 +
    commentCount * 8 +
    shareCount * 12 +
    likeCount * 5 +
    recencyBoost
  );
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<TrendingResponse>
) {
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).json({
      success: false,
      message: 'Method not allowed',
    });
  }

  try {
    await dbConnect();

    const rawLimit = Number(req.query.limit || DEFAULT_LIMIT);
    const limit = Number.isFinite(rawLimit)
      ? Math.min(Math.max(rawLimit, 1), MAX_LIMIT)
      : DEFAULT_LIMIT;

    const now = new Date();
    const last90Days = new Date();
    last90Days.setDate(last90Days.getDate() - 90);

    const baseQuery = {
      status: 'published',
      isDeleted: { $ne: true },
      publishedAt: { $lte: now },
    };

    const candidateBlogs = await Blog.find({
      ...baseQuery,
      publishedAt: { $gte: last90Days, $lte: now },
    })
      .select(
        'title slug category readTime views commentCount shareCount likeCount publishedAt createdAt image'
      )
      .lean();

    const scoredRecentBlogs = (candidateBlogs || [])
      .map((post: any) => ({
        ...post,
        trendingScore: calculateTrendingScore(post),
      }))
      .sort((a, b) => {
        if (b.trendingScore !== a.trendingScore) {
          return b.trendingScore - a.trendingScore;
        }

        const aDate = new Date(a.publishedAt || a.createdAt || 0).getTime();
        const bDate = new Date(b.publishedAt || b.createdAt || 0).getTime();
        return bDate - aDate;
      })
      .slice(0, limit);

    let blogs = scoredRecentBlogs;

    if (scoredRecentBlogs.length < limit) {
      const excludeIds = scoredRecentBlogs.map((post: any) => post._id);

      const fallbackBlogsRaw = await Blog.find({
        ...baseQuery,
        _id: { $nin: excludeIds },
      })
        .sort({ views: -1, publishedAt: -1 })
        .limit(limit - scoredRecentBlogs.length)
        .select(
          'title slug category readTime views commentCount shareCount likeCount publishedAt createdAt image'
        )
        .lean();

      const fallbackBlogs = (fallbackBlogsRaw || []).map((post: any) => ({
        ...post,
        trendingScore: calculateTrendingScore(post),
      }));

      blogs = [...scoredRecentBlogs, ...fallbackBlogs];
    }

    const formattedBlogs: TrendingBlog[] = blogs.map((post: any) => ({
      _id: String(post._id),
      title: post.title || '',
      slug: post.slug || '',
      category: post.category || 'General',
      readTime: post.readTime || '5 min read',
      views: Number(post.views || 0),
      commentCount: Number(post.commentCount || 0),
      shareCount: Number(post.shareCount || 0),
      likeCount: Number(post.likeCount || 0),
      trendingScore: Number(post.trendingScore || 0),
      publishedAt: post.publishedAt ? new Date(post.publishedAt).toISOString() : null,
      createdAt: post.createdAt ? new Date(post.createdAt).toISOString() : null,
      image: post.image
        ? {
            url: post.image.url || '',
            public_id: post.image.public_id || '',
          }
        : undefined,
    }));

    res.setHeader('Cache-Control', 'public, s-maxage=300, stale-while-revalidate=600');

    return res.status(200).json({
      success: true,
      blogs: formattedBlogs,
    });
  } catch (error) {
    console.error('Trending blogs error:', error);
    return res.status(500).json({
      success: false,
      message: 'Failed to fetch trending blogs',
    });
  }
}

