// 🔒 ENTERPRISE v2.0 - Like/Dislike System with Atomic Operations & Guest Tracking

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import dbConnect from '@/lib/db';
import Comment from '@/models/Comment';
import SecurityEvent from '@/models/SecurityEvent';
import { rateLimitComment } from '@/lib/rateLimit';
import { z } from 'zod';
import crypto from 'crypto';

// ═══════════════════════════════════════════════════════════════
// 🔒 ENTERPRISE CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TIME_MS = 5000;
const VALID_ACTIONS = ['like', 'dislike', 'remove'] as const;

// ═══════════════════════════════════════════════════════════════
// 🔒 ZOD VALIDATION SCHEMAS
// ═══════════════════════════════════════════════════════════════

const ObjectIdSchema = z.string().regex(/^[a-fA-F0-9]{24}$/, 'Invalid ID format');

const LikeSchema = z.object({
  action: z.enum(VALID_ACTIONS),
  email: z.string().email('Invalid email address').optional(), // For guest tracking
});

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY HEADERS + REQUEST ID
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function setSecurityHeaders(res: NextApiResponse, requestId: string) {
  res.setHeader('X-Request-Id', requestId);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
}

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip || '').split(',')[0]?.trim() || req.socket?.remoteAddress || '0.0.0.0';
}

function getUserAgent(req: NextApiRequest): string {
  return String(req.headers['user-agent'] || '').slice(0, 200);
}

/**
 * Create unique identifier for guest users (IP + Email hash)
 */
function createGuestIdentifier(ip: string, email?: string): string {
  const source = email ? `${ip}:${email}` : ip;
  return crypto
    .createHash('sha256')
    .update(source)
    .digest('hex')
    .slice(0, 24);
}

/**
 * Convert to mongoose ObjectId
 */
function toObjectId(identifier: string): mongoose.Types.ObjectId {
  const paddedId = identifier.padEnd(24, '0');
  return new mongoose.Types.ObjectId(paddedId);
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const ip = getClientIp(req);
  const ua = getUserAgent(req);

  // ═══════════════════════════════════════════════════════════════
  // ✅ METHOD CHECK
  // ═══════════════════════════════════════════════════════════════

  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    return res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
  }

  // ═══════════════════════════════════════════════════════════════
  // ✅ VALIDATE COMMENT ID
  // ═══════════════════════════════════════════════════════════════

  const { id } = req.query;
  const idResult = ObjectIdSchema.safeParse(id);

  if (!idResult.success) {
    return res.status(400).json({
      success: false,
      message: 'Invalid comment ID format',
      code: 'INVALID_ID',
      requestId,
    });
  }

  const commentId = idResult.data;

  try {
    await dbConnect();

    // ═══════════════════════════════════════════════════════════════
    // ✅ RATE LIMITING
    // ═══════════════════════════════════════════════════════════════

    const rl = await rateLimitComment(req);
    if (!rl.ok) {
      res.setHeader('Retry-After', String(rl.retryAfter || 60));
      return res.status(429).json({
        success: false,
        message: 'Too many requests. Please slow down.',
        code: 'RATE_LIMITED',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ VALIDATE REQUEST BODY
    // ═══════════════════════════════════════════════════════════════

    const parseResult = LikeSchema.safeParse(req.body);
    if (!parseResult.success) {
      return res.status(400).json({
        success: false,
        message: 'Invalid request body',
        code: 'VALIDATION_ERROR',
        errors: parseResult.error.flatten().fieldErrors,
        requestId,
      });
    }

    const { action, email } = parseResult.data;

    // ═══════════════════════════════════════════════════════════════
    // ✅ FETCH COMMENT
    // ═══════════════════════════════════════════════════════════════

    const comment: any = await Comment.findById(commentId).maxTimeMS(MAX_TIME_MS);

    if (!comment) {
      return res.status(404).json({
        success: false,
        message: 'Comment not found',
        code: 'NOT_FOUND',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ CHECK IF COMMENT IS DELETED
    // ═══════════════════════════════════════════════════════════════

    if (comment.isDeleted) {
      return res.status(400).json({
        success: false,
        message: 'Cannot like a deleted comment',
        code: 'COMMENT_DELETED',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ CREATE USER IDENTIFIER
    // ═══════════════════════════════════════════════════════════════

    const guestId = createGuestIdentifier(ip, email);
    const userId = toObjectId(guestId);
    const userIdStr = String(userId);

    // Initialize arrays if they don't exist
    if (!comment.likes) comment.likes = [];
    if (!comment.dislikes) comment.dislikes = [];

    // Convert to strings for comparison
    const likeIds = comment.likes.map((id: any) => String(id));
    const dislikeIds = comment.dislikes.map((id: any) => String(id));

    const hasLiked = likeIds.includes(userIdStr);
    const hasDisliked = dislikeIds.includes(userIdStr);

    // ═══════════════════════════════════════════════════════════════
    // ✅ HANDLE ACTION
    // ═══════════════════════════════════════════════════════════════

    let updateOperation: any = {};
    let message = '';
    let actionTaken = '';

    if (action === 'like') {
      if (hasLiked) {
        // Toggle off (remove like)
        updateOperation = { $pull: { likes: userId } };
        message = 'Like removed';
        actionTaken = 'like_removed';
      } else {
        // Add like (remove dislike if exists)
        updateOperation = {
          $addToSet: { likes: userId },
          $pull: { dislikes: userId },
        };
        message = 'Comment liked';
        actionTaken = 'liked';
      }
    } else if (action === 'dislike') {
      if (hasDisliked) {
        // Toggle off (remove dislike)
        updateOperation = { $pull: { dislikes: userId } };
        message = 'Dislike removed';
        actionTaken = 'dislike_removed';
      } else {
        // Add dislike (remove like if exists)
        updateOperation = {
          $addToSet: { dislikes: userId },
          $pull: { likes: userId },
        };
        message = 'Comment disliked';
        actionTaken = 'disliked';
      }
    } else if (action === 'remove') {
      // Remove both like and dislike
      updateOperation = {
        $pull: {
          likes: userId,
          dislikes: userId,
        },
      };
      message = 'Vote removed';
      actionTaken = 'removed';
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ ATOMIC UPDATE
    // ═══════════════════════════════════════════════════════════════

    const updatedComment: any = await Comment.findByIdAndUpdate(
      commentId,
      updateOperation,
      { new: true }
    )
      .select('likes dislikes')
      .lean()
      .maxTimeMS(MAX_TIME_MS);

    if (!updatedComment) {
      return res.status(404).json({
        success: false,
        message: 'Comment not found',
        code: 'NOT_FOUND',
        requestId,
      });
    }

    // ═══════════════════════════════════════════════════════════════
    // ✅ AUDIT LOG (Non-blocking)
    // ═══════════════════════════════════════════════════════════════

    SecurityEvent.create({
      eventType: 'comment_vote',
      severity: 'low',
      ipAddress: ip,
      userAgent: ua,
      metadata: {
        commentId,
        action: actionTaken,
        previousState: {
          hasLiked,
          hasDisliked,
        },
      },
    }).catch(console.error);

    // ═══════════════════════════════════════════════════════════════
    // ✅ SUCCESS RESPONSE
    // ═══════════════════════════════════════════════════════════════

    const likeCount = updatedComment.likes?.length || 0;
    const dislikeCount = updatedComment.dislikes?.length || 0;

    return res.status(200).json({
      success: true,
      message,
      action: actionTaken,
      stats: {
        likes: likeCount,
        dislikes: dislikeCount,
        netScore: likeCount - dislikeCount,
      },
      userState: {
        hasLiked: updatedComment.likes?.some((id: any) => String(id) === userIdStr) || false,
        hasDisliked: updatedComment.dislikes?.some((id: any) => String(id) === userIdStr) || false,
      },
      requestId,
    });
  } catch (error: any) {
    console.error('Like error:', { requestId, error: error?.message });

    SecurityEvent.create({
      eventType: 'system_error',
      severity: 'critical',
      ipAddress: ip,
      userAgent: ua,
      metadata: {
        endpoint: `/api/comments/${commentId}/like`,
        errorCode: error?.code || 'UNKNOWN',
      },
    }).catch(console.error);

    return res.status(500).json({
      success: false,
      message: 'Internal server error',
      code: 'SERVER_ERROR',
      requestId,
    });
  }
}

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import { z } from 'zod';

import dbConnect from '@/lib/db';
import Comment from '@/models/Comment';
import { rateLimitComment, sendRateLimitResponse } from '@/lib/rateLimit';
import { getOptionalAuth } from '@/lib/optionalAuth';
import { getRequestIp, verifyTurnstileToken } from '@/lib/turnstileServer';

const ReplySchema = z.object({
  content: z.string().trim().min(3).max(1000),
  author: z.object({
    name: z.string().trim().min(2).max(100),
    email: z.string().email(),
  }).optional(),
  guestName: z.string().trim().min(2).max(100).optional(),
  guestEmail: z.string().email().optional(),
  parentReplyId: z.string().regex(/^[a-fA-F0-9]{24}$/).optional(),
  turnstileToken: z.string().optional(),
}).strict();

function sanitize(value: string): string {
  return value.replace(/<[^>]*>?/g, '').replace(/[\u0000-\u001F\u007F-\u009F]/g, '').trim().slice(0, 1000);
}

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'no-store');

  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  const rawId = Array.isArray(req.query.id) ? req.query.id[0] : req.query.id;
  if (!rawId || !mongoose.Types.ObjectId.isValid(rawId)) {
    return res.status(400).json({ success: false, message: 'Invalid comment ID' });
  }

  const rl = await rateLimitComment(req);
  if (!rl.ok) return sendRateLimitResponse(res, rl);

  const parsed = ReplySchema.safeParse(req.body);
  if (!parsed.success) return res.status(422).json({ success: false, message: 'Invalid reply data' });

  const viewer = await getOptionalAuth(req, res);
  const suppliedName = parsed.data.author?.name ?? parsed.data.guestName;
  const suppliedEmail = parsed.data.author?.email ?? parsed.data.guestEmail;

  let author: { name: string; email: string; isAdmin: boolean; isVerifiedBuyer: boolean };
  if (viewer) {
    author = {
      name: viewer.name || suppliedName || 'Highrise User',
      email: viewer.email || suppliedEmail || 'no-email@highrise.pk',
      isAdmin: viewer.role === 'admin' || viewer.role === 'superadmin',
      isVerifiedBuyer: false,
    };
  } else {
    if (!suppliedName || !suppliedEmail || !parsed.data.turnstileToken) {
      return res.status(401).json({ success: false, message: 'Name, email and bot verification are required' });
    }
    const captchaOk = await verifyTurnstileToken(parsed.data.turnstileToken, getRequestIp(req));
    if (!captchaOk) return res.status(400).json({ success: false, message: 'Bot verification failed' });
    author = { name: suppliedName, email: suppliedEmail.toLowerCase(), isAdmin: false, isVerifiedBuyer: false };
  }

  const content = sanitize(parsed.data.content);
  if (content.length < 3) return res.status(400).json({ success: false, message: 'Reply is too short' });

  await dbConnect();
  const comment = await Comment.findById(rawId);
  if (!comment || comment.isDeleted) return res.status(404).json({ success: false, message: 'Comment not found' });
  if (comment.status !== 'approved' && !author.isAdmin) {
    return res.status(404).json({ success: false, message: 'Comment not found' });
  }

  const replies = Array.isArray(comment.replies) ? comment.replies : [];
  if (replies.length >= 100) return res.status(409).json({ success: false, message: 'This discussion has reached its reply limit' });

  let depth = 0;
  let parentReplyId: mongoose.Types.ObjectId | undefined;
  if (parsed.data.parentReplyId) {
    const parent = replies.find((item: any) => String(item?._id) === parsed.data.parentReplyId);
    if (!parent) return res.status(400).json({ success: false, message: 'Parent reply not found' });
    depth = Math.min(Number(parent.depth ?? 0) + 1, 5);
    parentReplyId = new mongoose.Types.ObjectId(parsed.data.parentReplyId);
  }

  comment.replies.push({
    _id: new mongoose.Types.ObjectId(),
    parentReplyId,
    depth,
    author,
    content,
    createdAt: new Date(),
  } as any);
  await comment.save();

  return res.status(201).json({ success: true, message: 'Reply posted successfully' });
}

