function buildEmailHtml(params: EmailBuildParams): string {
  const {
    content,
    subject,
    previewText,
    unsubscribeUrl,
    mergeTagsEnabled,
    recipientData,
  } = params;

  let processedContent = sanitizeEmailHtml(
