      imageUrl: typeof u?.imageUrl === 'string' ? u.imageUrl : '',
    }));
  }

  update.updatedAt = new Date();

  return update;
}

export default async function handler(req: NextApiRequest, res: NextApiResponse<ApiResponse>) {
  setSecurityHeaders(res);

  const method = String(req.method || 'GET').toUpperCase();
  const ip = getClientIp(req);

  // Rate limit
  if (method === 'GET') {
    const rl = bumpRate(`dash:projects:id:get:${ip}`, RL_MAX_GET);
    if (!rl.ok) {
      res.setHeader('Retry-After', String(rl.retryAfterSec));
      return res.status(429).json({ success: false, message: 'Too many requests. Please try again.' });
    }
  } else if (method === 'PUT') {
    const rl = bumpRate(`dash:projects:id:put:ip:${ip}`, RL_MAX_PUT_IP);
    if (!rl.ok) {
      res.setHeader('Retry-After', String(rl.retryAfterSec));
      return res.status(429).json({ success: false, message: 'Too many requests. Please try again.' });
    }
  }

  if (method !== 'GET' && method !== 'PUT') {
    res.setHeader('Allow', ['GET', 'PUT']);
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  const auth = await requireSession(req, res);
  if (!auth.ok) return;

  const id = typeof req.query.id === 'string' ? req.query.id : '';
  if (!id) return res.status(400).json({ success: false, message: 'Project ID is required' });

  if (!mongoose.Types.ObjectId.isValid(id)) {
    return res.status(400).json({ success: false, message: 'Invalid project ID format.' });
  }

  try {
    await dbConnect();

    const gate = await enforceActiveAndCnicIfPossible(auth.userId, auth.isAdmin);
    if (!gate.ok) {
      return res.status(gate.status).json({ success: false, message: gate.message });
    }

    const project: any = await (Project as any)
      .findById(id)
      .select(
        [
          '_id',
          'developerId',
          'projectCategory',
          'projectNature',
          'projectType',
          'projectName',
          'title',
          'tagline',
          'shortDescription',
          'description',
          'city',
          'area',
          'specificLocation',
          'projectStatus',
          'launchDate',
          'developmentProgress',
          'expectedCompletionDate',
          'possessionStartDate',

          'approvalAuthority',
          'isApproved',
          'nocStatus',
          'nocNumber',
          'societyRegistrationNumber',
          'environmentClearance',
          'buildingPlanApproved',

          'totalArea',
          'totalBlocks',
          'totalUnits',
          'unitsSold',
          'unitsAvailable',

          'floorDetails',
          'societyDetails',

          'saleMode',
          'fullPaymentInfo',
          'fullPaymentInfoExtra',
          'installmentPlan',
          'paymentMeta',
          'discountOffers',

          'unitTypeBreakdown',
          'unitPlans',

          'featureImageUrl',
          'featureImagePublicId',
          'images',
          'gallery',
          'progressImages',

          'projectDocuments',
          'buildingFloorPlans',

          'droneVideoUrl',
          'virtualTourUrl',
          'googleMapLink',
          'coordinatesRaw',
          'coordinates',
          'location',

          'completedProjects',
          'constructionUpdates',
          'developmentUpdates',

          'isDeleted',
          'deletedAt',
        ].join(' ')
      )
      .lean();

    if (!project) {
      return res.status(404).json({ success: false, message: 'Project not found' });
    }

    const ownerId = String(project.developerId || '');
    const isOwner = ownerId && ownerId === String(auth.userId);

    // Anti-enumeration
    if (!auth.isAdmin && !isOwner) {
      return res.status(404).json({ success: false, message: 'Project not found' });
    }

    const projectDeleted = project.isDeleted === true || !!project.deletedAt;
    if (projectDeleted && !auth.isAdmin) {
      return res.status(404).json({ success: false, message: 'Project not found' });
    }

    if (method === 'GET') {
      return res.status(200).json({ success: true, project: buildDashboardProjectView(project) });
    }

    // PUT
    const userRL = bumpRate(`dash:projects:id:put:user:${auth.userId}`, RL_MAX_PUT_USER);
    if (!userRL.ok) {
      res.setHeader('Retry-After', String(userRL.retryAfterSec));
      return res.status(429).json({ success: false, message: 'Too many requests. Please try again.' });
    }

    const body = safeJsonBody(req);
    const isFullUpdate = body?.isFullUpdate === true;

    if (!isFullUpdate) {
      return res.status(400).json({ success: false, message: 'Invalid update mode' });
    }

    const allowedUpdate = buildAllowedUpdate(body);

    // Write using native collection update to avoid strict stripping of allowed extra fields
    await (Project as any).collection.updateOne(
      { _id: new mongoose.Types.ObjectId(id) },
      { $set: allowedUpdate }
    );

    const updated: any = await (Project as any)
      .findById(id)
      .select(
        [
          '_id',
          'developerId',
          'projectCategory',
          'projectNature',
          'projectType',
          'projectName',
          'title',
          'tagline',
          'shortDescription',
          'description',
          'city',
          'area',
          'specificLocation',
          'projectStatus',
          'launchDate',
          'developmentProgress',
          'expectedCompletionDate',
          'possessionStartDate',

          'approvalAuthority',
          'isApproved',
          'nocStatus',
          'nocNumber',
          'societyRegistrationNumber',
          'environmentClearance',
          'buildingPlanApproved',

          'totalArea',
          'totalBlocks',
          'totalUnits',
          'unitsSold',
          'unitsAvailable',

          'floorDetails',
          'societyDetails',

          'saleMode',
          'fullPaymentInfo',
          'fullPaymentInfoExtra',
          'installmentPlan',
          'paymentMeta',
          'discountOffers',

          'unitTypeBreakdown',
          'unitPlans',

          'featureImageUrl',
          'featureImagePublicId',
          'images',
          'gallery',
          'progressImages',

          'projectDocuments',
          'buildingFloorPlans',

          'droneVideoUrl',
          'virtualTourUrl',
          'googleMapLink',
          'coordinatesRaw',
          'coordinates',
          'location',

          'completedProjects',
          'constructionUpdates',
          'developmentUpdates',

          'isDeleted',
          'deletedAt',
        ].join(' ')
      )
      .lean();

    return res.status(200).json({
      success: true,
      project: buildDashboardProjectView(updated),
    });
  } catch (err) {
    console.error('Dashboard project [id] error:', err);
    return res.status(500).json({ success: false, message: 'Something went wrong' });
  }
}

