    };

    const emailHtml = adminInquiryNotificationTemplate.html({
      customerName: data.customerName,
      customerEmail: data.customerEmail,
      customerPhone: data.customerPhone ? `***${data.customerPhone.slice(-4)}` : 'Not provided',
      customerMessage: data.customerMessage,
      budget: data.budget || 'Not specified',
      timeline: data.timeline || 'Not specified',
      priority: data.priority,
      propertyTitle: data.propertyTitle,
      propertyLocation: data.propertyLocation,
      propertyPrice: data.propertyPrice,
      propertyUrl: data.propertyUrl,
      propertyOwnerId: data.propertyOwnerId,
      propertyOwnerName: data.propertyOwnerName,
      inquiryTime: new Date().toLocaleString('en-PK', { timeZone: 'Asia/Karachi' }),
      source: data.source || 'Website',
      inquiryId: data.inquiryId,
      dashboardUrl: `${process.env.NEXTAUTH_URL}/admin/inquiries/${data.inquiryId}`,
      ipAddress: data.ipAddress,
    });

    const priorityTag = priorityEmoji[data.priority as keyof typeof priorityEmoji] || '??';
    let subject = `${priorityTag} New Inquiry: ${data.propertyTitle || 'Property'} - ${data.customerName}`;

    await transporter.sendMail({
      from: `"Highrise.pk Alerts" <${process.env.EMAIL_FROM || process.env.EMAIL_USER}>`,
      to: adminEmail,
      subject: subject,
      html: emailHtml,
      priority: data.priority === 'urgent' || data.priority === 'high' ? 'high' : 'normal',
      headers: {
        'X-Inquiry-ID': data.inquiryId,
        'X-Priority': data.priority,
        'X-Entity-Type': 'admin-notification',
      },
    });

    console.log('? Admin notification sent to:', adminEmail);
    return true;
  } catch (error) {
    console.error('? Failed to send admin notification:', error);
    return false;
  }
}

// ???????????????????????????????????????????????????????????????
// ?? MAIN HANDLER
// ???????????????????????????????????????????????????????????????

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
) {
  // Security Headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  const clientIP = getClientIP(req);
  const userAgent = req.headers['user-agent'] || 'unknown';

  try {
    await dbConnect();

    switch (req.method) {
      // ???????????????????????????????????????????????????????????
      // ?? GET: VIEW INQUIRIES (Admin/Agent Only)
      // ???????????????????????????????????????????????????????????
      case 'GET':
        return handleGetInquiries(req, res, clientIP, userAgent);

      // ???????????????????????????????????????????????????????????
      // ?? POST: SUBMIT INQUIRY (Public with Protection)
      // ???????????????????????????????????????????????????????????
      case 'POST':
        return handlePostInquiry(req, res, clientIP, userAgent);

      default:
        res.setHeader('Allow', ['GET', 'POST']);
        return res.status(405).json({
          success: false,
          error: `Method ${req.method} not allowed`,
        });
    }
  } catch (error: any) {
    console.error('? Inquiry API Error:', error);

    await logSecurityEvent({
      eventType: 'system_error',
      severity: 'critical',
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        method: req.method,
        error: error.message,
        errorType: error.name,
      },
    });

    return res.status(500).json({
      success: false,
      error: 'An error occurred. Please try again.',
    });
  }
}

// ???????????????????????????????????????????????????????????????
// ?? GET HANDLER: VIEW INQUIRIES
// ???????????????????????????????????????????????????????????????

async function handleGetInquiries(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
  clientIP: string,
  userAgent: string
) {
  // ?????????????????????????????????????????????
  // STEP 1: RATE LIMITING
  // ?????????????????????????????????????????????
  const rateLimitResult = await rateLimitApi(req);

  if (!rateLimitResult.ok) {
    return res.status(429).json({
      success: false,
      error: 'Too many requests. Please slow down.',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 2: AUTHENTICATION
  // ?????????????????????????????????????????????
  const session = await getServerSession(req, res, authOptions);

  if (!session?.user) {
    await logSecurityEvent({
      eventType: 'unauthorized_access_attempt',
      severity: 'high',
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        method: 'GET',
        reason: 'No session',
      },
    });

    return res.status(401).json({
      success: false,
      error: 'Authentication required',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 3: AUTHORIZATION (Admin/Agent Only)
  // ?????????????????????????????????????????????
  const userRole = session.user.role;
  const allowedRoles = ['admin', 'agent', 'developer'];

  if (!allowedRoles.includes(userRole || '')) {
    await logSecurityEvent({
      eventType: 'unauthorized_access_attempt',
      severity: 'high',
      userId: session.user.id,
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        method: 'GET',
        userRole,
        requiredRoles: allowedRoles,
      },
    });

    return res.status(403).json({
      success: false,
      error: 'Insufficient permissions to view inquiries',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 4: PERMISSION CHECK
  // ?????????????????????????????????????????????
  const hasPermission = await checkPermission(session.user, 'inquiry_view');

  if (!hasPermission) {
    await logSecurityEvent({
      eventType: 'permission_denied',
      severity: 'high',
      userId: session.user.id,
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        permission: 'inquiry_view',
      },
    });

    return res.status(403).json({
      success: false,
      error: 'Permission denied',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 5: PARSE & VALIDATE QUERY PARAMS
  // ?????????????????????????????????????????????
  const {
    status,
    page = '1',
    limit = '10',
    search,
    priority,
    sortBy = 'createdAt',
    sortOrder = 'desc',
  } = req.query;

  const pageNum = Math.max(1, parseInt(page as string) || 1);
  const limitNum = Math.min(100, Math.max(1, parseInt(limit as string) || 10));
  const skip = (pageNum - 1) * limitNum;

  // ?????????????????????????????????????????????
  // STEP 6: BUILD QUERY
  // ?????????????????????????????????????????????
  const query: any = { entityType: 'property', isArchived: false };

  // Status filter
  if (status && status !== 'all') {
    const statusStr = status as string;
    const legacyStatusMap: Record<string, string[]> = {
      new: ['new'],
      pending: ['new', 'qualified', 'proposal_sent'],
      contacted: ['contacted'],
      scheduled: ['site_visit_scheduled'],
      resolved: ['won'],
      closed: ['lost'],
      cancelled: ['lost'],
    };
    const mapped = legacyStatusMap[statusStr];
    query.status = mapped ? { $in: mapped } : statusStr;
  }

  // Priority filter
  if (priority && priority !== 'all') {
    const validPriorities = ['low', 'medium', 'high', 'urgent'];
    if (validPriorities.includes(priority as string)) {
      query.priority = priority;
    }
  }

  // Search (sanitized)
  if (search) {
    const sanitizedSearch = sanitizeSearchQuery(search as string);
    if (sanitizedSearch.length > 0) {
      query.$or = [
        { name: { $regex: sanitizedSearch, $options: 'i' } },
        { email: { $regex: sanitizedSearch, $options: 'i' } },
        { phone: { $regex: sanitizedSearch, $options: 'i' } },
        { 'propertySnapshot.title': { $regex: sanitizedSearch, $options: 'i' } },
        { message: { $regex: sanitizedSearch, $options: 'i' } },
      ];
    }
  }

  // Agent-specific view (only their inquiries)
  if (userRole === 'agent') {
    query['propertySnapshot.ownerId'] = session.user.id;
  }

  // Developer-specific view
  if (userRole === 'developer') {
    query.$or = [
      { 'propertySnapshot.ownerId': session.user.id },
      { developer: session.user.id },
    ];
  }

  // ?????????????????????????????????????????????
  // STEP 7: EXECUTE QUERIES
  // ?????????????????????????????????????????????
  const validSortFields = ['createdAt', 'updatedAt', 'priority', 'status'];
  const sortField = validSortFields.includes(sortBy as string) ? sortBy : 'createdAt';
  const sortDirection = sortOrder === 'asc' ? 1 : -1;

  const baseFilter = { entityType: 'property', isArchived: false };
  const statusFiltersForStats: Record<string, any> = {
    new: { status: 'new' },
    pending: { status: { $in: ['new', 'qualified', 'proposal_sent'] } },
    contacted: { status: 'contacted' },
    scheduled: { status: 'site_visit_scheduled' },
    resolved: { status: 'won' },
    closed: { status: 'lost' },
    cancelled: { status: 'lost' },
  };

  const [
    inquiries,
    total,
    allCount,
    newCount,
    pendingCount,
    contactedCount,
    scheduledCount,
    resolvedCount,
    closedCount,
    cancelledCount,
  ] = await Promise.all([
    Lead.find(query)
      .populate('property', 'title price slug images location')
      .sort({ [sortField as string]: sortDirection })
      .skip(skip)
      .limit(limitNum)
      .lean(),
    Lead.countDocuments(query),
    Lead.countDocuments(baseFilter),
    Lead.countDocuments({ ...baseFilter, ...statusFiltersForStats.new }),
    Lead.countDocuments({ ...baseFilter, ...statusFiltersForStats.pending }),
    Lead.countDocuments({ ...baseFilter, ...statusFiltersForStats.contacted }),
    Lead.countDocuments({ ...baseFilter, ...statusFiltersForStats.scheduled }),
    Lead.countDocuments({ ...baseFilter, ...statusFiltersForStats.resolved }),
    Lead.countDocuments({ ...baseFilter, ...statusFiltersForStats.closed }),
    Lead.countDocuments({ ...baseFilter, ...statusFiltersForStats.cancelled }),
  ]);

  // ?????????????????????????????????????????????
  // STEP 8: AUDIT LOG
  // ?????????????????????????????????????????????
  await logSecurityEvent({
    eventType: 'admin_action',
    severity: 'low',
    userId: session.user.id,
    ipAddress: clientIP,
    userAgent,
    metadata: {
      action: 'view_inquiries',
      resultCount: inquiries.length,
      filters: { status, priority, search: search ? 'present' : 'none' },
    },
  });

  // ?????????????????????????????????????????????
  // STEP 9: SUCCESS RESPONSE
  // ?????????????????????????????????????????????
  const totalPages = Math.ceil(total / limitNum);

  return res.status(200).json({
    success: true,
    data: inquiries as any,
    pagination: {
      page: pageNum,
      limit: limitNum,
      total,
      totalPages,
      hasNextPage: pageNum < totalPages,
      hasPrevPage: pageNum > 1,
    },
    stats: {
      all: allCount,
      new: newCount,
      pending: pendingCount,
      contacted: contactedCount,
      scheduled: scheduledCount,
      resolved: resolvedCount,
      closed: closedCount,
      cancelled: cancelledCount,
    },
  });
}

// ???????????????????????????????????????????????????????????????
// ?? POST HANDLER: SUBMIT INQUIRY
// ???????????????????????????????????????????????????????????????

async function handlePostInquiry(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
  clientIP: string,
  userAgent: string
) {
  // ?????????????????????????????????????????????
  // STEP 1: RATE LIMITING (Strict)
  // ?????????????????????????????????????????????
  const rateLimitResult = await rateLimitInquiry(req);

  if (!rateLimitResult.ok) {
    await logSecurityEvent({
      eventType: 'rate_limit_exceeded',
      severity: 'medium',
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        method: 'POST',
        limit: rateLimitResult.limit,
      },
    });

    return res.status(429).json({
      success: false,
      error: 'Too many inquiries. Please wait a few minutes before trying again.',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 2: HONEYPOT CHECK
  // ?????????????????????????????????????????????
  const { website, company } = req.body as InquirySubmission;

  if (website || company) {
    // Bot detected - log and return fake success
    await logSecurityEvent({
      eventType: 'bot_detected',
      severity: 'high',
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        honeypotTriggered: true,
        website: website?.substring(0, 50),
        company: company?.substring(0, 50),
      },
    });

    // Return fake success to confuse bot
    return res.status(201).json({
      success: true,
      message: 'Inquiry submitted successfully!',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 3: PARSE & VALIDATE INPUT
  // ?????????????????????????????????????????????
  const {
    propertyId,
    name,
    email,
    phone,
    message,
    budget,
    timeline,
    preferredContactMethod,
    propertyTitle,
    propertySlug,
    source,
    turnstileToken,
  } = req.body as InquirySubmission;

  // Required fields
  if (!propertyId || !name || !email || !phone || !message) {
    return res.status(400).json({
      success: false,
      error: 'Please fill all required fields: name, email, phone, and message',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 4: TURNSTILE VERIFICATION
  // ?????????????????????????????????????????????
  const turnstileResult = await verifyTurnstile(turnstileToken || '', clientIP);

  if (!turnstileResult.success) {
    await logSecurityEvent({
      eventType: 'captcha_failed',
      severity: 'medium',
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        error: turnstileResult.error,
      },
    });

    return res.status(400).json({
      success: false,
      error: turnstileResult.error || 'CAPTCHA verification failed',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 5: VALIDATE & SANITIZE FIELDS
  // ?????????????????????????????????????????????
  // Name validation
  const sanitizedName = sanitizeInput(name);
  if (sanitizedName.length < 2 || sanitizedName.length > MAX_NAME_LENGTH) {
    return res.status(400).json({
      success: false,
      error: 'Name must be between 2 and 100 characters',
    });
  }

  // Email validation
  const emailValidation = validateEmail(email);
  if (!emailValidation.valid) {
    return res.status(400).json({
      success: false,
      error: emailValidation.error,
    });
  }
  const sanitizedEmail = sanitizeEmail(emailValidation.normalized!);

  // Phone validation
  const phoneValidation = validatePhone(phone);
  if (!phoneValidation.valid) {
    return res.status(400).json({
      success: false,
      error: phoneValidation.error,
    });
  }
  const normalizedPhone = phoneValidation.normalized!;

  // Message validation
  const sanitizedMessage = sanitizeInput(message);
  if (sanitizedMessage.length < MIN_MESSAGE_LENGTH || sanitizedMessage.length > MAX_MESSAGE_LENGTH) {
    return res.status(400).json({
      success: false,
      error: `Message must be between ${MIN_MESSAGE_LENGTH} and ${MAX_MESSAGE_LENGTH} characters`,
    });
  }

  // Budget validation
  if (budget && !VALID_BUDGET_RANGES.includes(budget)) {
    return res.status(400).json({
      success: false,
      error: 'Invalid budget range selected',
    });
  }

  // Timeline validation
  if (timeline && !VALID_TIMELINES.includes(timeline)) {
    return res.status(400).json({
      success: false,
      error: 'Invalid timeline selected',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 6: DUPLICATE CHECK
  // ?????????????????????????????????????????????
  const isDuplicate = await checkDuplicate(sanitizedEmail, normalizedPhone, propertyId);

  if (isDuplicate) {
    await logSecurityEvent({
      eventType: 'duplicate_submission',
      severity: 'low',
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/inquiries',
        email: sanitizedEmail,
        propertyId,
      },
    });

    return res.status(400).json({
      success: false,
      error: 'You have already submitted an inquiry for this property. Our team will contact you soon.',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 7: VERIFY PROPERTY EXISTS
  // ?????????????????????????????????????????????
  let propertyDetails: any = null;
  try {
    propertyDetails = await Property.findById(propertyId)
      .select('title slug price location images propertyType listingType userId ownerName ownerEmail ownerPhone brochureUrl priceListUrl')
      .populate('userId', 'name email phone')
      .lean();

    if (!propertyDetails) {
      return res.status(404).json({
        success: false,
        error: 'Property not found',
      });
    }
  } catch (err) {
    console.error('Property fetch error:', err);
    return res.status(400).json({
      success: false,
      error: 'Invalid property ID',
    });
  }

  // ?????????????????????????????????????????????
  // STEP 8: CALCULATE LEAD PRIORITY
  // ?????????????????????????????????????????????
  const priority = calculateLeadPriority({
    budget,
    timeline,
    messageLength: sanitizedMessage.length,
    hasPhone: true,
  });

  // ?????????????????????????????????????????????
  // STEP 9: CREATE INQUIRY
  // ?????????????????????????????????????????????
  const ownerData = propertyDetails.userId as any;

  const inquiry = await Lead.create({
    name: sanitizedName,
    email: sanitizedEmail,
    phone: normalizedPhone,
    message: sanitizedMessage,
    budget,
    timeline,
    preferredContactMethod: preferredContactMethod || 'phone',
    leadType: 'property_inquiry',
    entityType: 'property',
    property: propertyId,
    propertySnapshot: {
      _id: propertyDetails._id,
      title: propertyTitle || propertyDetails.title,
      slug: propertySlug || propertyDetails.slug,
      city: propertyDetails.location?.city || '',
      society: propertyDetails.location?.society || '',
      price: propertyDetails.price || 0,
      propertyType: propertyDetails.propertyType || '',
      listingType: propertyDetails.listingType || '',
      primaryImage: propertyDetails.images?.[0]?.url || '',
      ownerId: ownerData?._id?.toString() || propertyDetails.userId?.toString(),
      ownerName: ownerData?.name || propertyDetails.ownerName || '',
      ownerEmail: ownerData?.email || propertyDetails.ownerEmail || '',
      ownerPhone: ownerData?.phone || propertyDetails.ownerPhone || '',
    },
    source: 'property_page',
    sourceDetails: {
      url: req.headers.referer || '',
      userAgent,
      ipAddress: clientIP,
      utmSource: source || '',
    },
    status: 'new',
    priority,
    adminStatus: 'pending_review', // New field for admin workflow
    isForwardedToOwner: false, // Track if forwarded
  });

  // ?????????????????????????????????????????????
  // STEP 10: SEND EMAILS (Async)
  // ?????????????????????????????????????????????
  const inquiryId = inquiry._id.toString();

  // Customer auto-response
  sendCustomerAutoResponse({
    customerName: sanitizedName,
    customerEmail: sanitizedEmail,
    propertyTitle: propertyTitle || propertyDetails.title,
    propertyLocation: propertyDetails.location?.address || propertyDetails.location?.city,
    propertyPrice: propertyDetails.price ? `PKR ${propertyDetails.price.toLocaleString()}` : '',
    propertyImage: propertyDetails.images?.[0]?.url,
    propertyUrl: propertySlug ? `https://highrise.pk/property/${propertySlug}` : '',
    inquiryId,
  }).catch(err => console.error('Customer email error:', err));

  // Admin notification (immediate for high priority)
  sendAdminNotification({
    customerName: sanitizedName,
    customerEmail: sanitizedEmail,
    customerPhone: normalizedPhone,
    customerMessage: sanitizedMessage,
    budget,
    timeline,
    priority,
    propertyTitle: propertyTitle || propertyDetails.title,
    propertyLocation: propertyDetails.location?.address || propertyDetails.location?.city,
    propertyPrice: propertyDetails.price ? `PKR ${propertyDetails.price.toLocaleString()}` : '',
    propertyUrl: propertySlug ? `https://highrise.pk/property/${propertySlug}` : '',
    propertyOwnerId: ownerData?._id?.toString(),
    propertyOwnerName: ownerData?.name || propertyDetails.ownerName,
    source: source || 'Website',
    inquiryId,
    ipAddress: clientIP,
  }).catch(err => console.error('Admin notification error:', err));

  // ?????????????????????????????????????????????
  // STEP 11: AUDIT LOG
  // ?????????????????????????????????????????????
  await logSecurityEvent({
    eventType: 'inquiry_submitted',
    severity: 'low',
    ipAddress: clientIP,
    userAgent,
    metadata: {
      inquiryId,
      propertyId,
      priority,
      budget,
      timeline,
      email: sanitizedEmail,
      hasPhone: true,
    },
  });

  // ?????????????????????????????????????????????
  // STEP 12: SUCCESS RESPONSE
  // ?????????????????????????????????????????????
  return res.status(201).json({
    success: true,
    data: [{ id: inquiryId }],
    message: 'Thank you for your inquiry! Our team will review and connect you with the property owner within 24 hours.',
  });
}

// pages/api/leads/[id].ts
// REWRITTEN v2.0 — Session-based auth, fixed $push conflict, rate limiting

import type { NextApiRequest, NextApiResponse } from "next";
import mongoose from "mongoose";
import dbConnect from "@/lib/dbConnect";
import Lead from "@/models/Lead";
import { requireAuth } from "@/lib/requireAuth";
import { rateLimitAdmin, rateLimitDeveloper } from "@/lib/rateLimit";

// ============================================
// TYPES
// ============================================

type TimelineEntry = {
  action: string;
  performedBy: string;
  performedByRole: "admin" | "developer" | "system";
  timestamp: Date;
  notes?: string;
  statusBefore?: string;
  statusAfter?: string;
  metadata?: any;
};

// ============================================
// SECURITY HEADERS
// ============================================

function setSecurityHeaders(res: NextApiResponse) {
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "DENY");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
}

// ============================================
// MAIN HANDLER
// ============================================

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  setSecurityHeaders(res);

  const { method } = req;
  const { id } = req.query;

  // ✅ ObjectId validation (was missing before)
  if (!id || typeof id !== "string" || !mongoose.Types.ObjectId.isValid(id)) {
    return res.status(400).json({
      success: false,
      message: "Invalid lead ID",
    });
  }

  // ✅ Rate limiting BEFORE auth (saves DB calls on abuse)
  // Use developer limit for non-admin roles — applied after auth
  // Global burst protection here
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    res.setHeader("Retry-After", String(rl.retryAfter ?? 60));
    return res.status(429).json({
      success: false,
      message: `Too many requests. Please try again in ${rl.retryAfter ?? 60} seconds.`,
    });
  }

  // ✅ Authenticate via session JWT — no more query param trust
  const authToken = await requireAuth(req, res);
  if (!authToken) return; // requireAuth already sent error response

  // ✅ Only admin and developer allowed on this endpoint
  if (!["admin", "developer"].includes(authToken.role)) {
    return res.status(403).json({
      success: false,
      message: "Access denied",
    });
  }

  await dbConnect();

  switch (method) {
    case "GET":
      return handleGet(req, res, id, authToken);

    case "PATCH":
      return handlePatch(req, res, id, authToken);

    case "DELETE":
      return handleDelete(req, res, id, authToken);

    default:
      res.setHeader("Allow", ["GET", "PATCH", "DELETE"]);
      return res.status(405).json({
        success: false,
        message: `Method ${method} Not Allowed`,
      });
  }
}

// ============================================
// 📖 GET - Get Single Lead + View Tracking
// ============================================

async function handleGet(
  req: NextApiRequest,
  res: NextApiResponse,
  id: string,
  authToken: Awaited<ReturnType<typeof requireAuth>> & {}
) {
  try {
    const userRole = authToken!.role;
    const userEmail = authToken!.email || "";

    const lead = await Lead.findById(id).lean() as any;

    if (!lead) {
      return res.status(404).json({
        success: false,
        message: "Lead not found",
      });
    }

    // ✅ RBAC — developer can only view their own leads
    if (userRole === "developer") {
      const isOwner =
        lead.developerSnapshot?.email === userEmail ||
        lead.assignedTo === userEmail ||
        lead.assignedToUserId?.toString() === authToken!.id;

      if (!isOwner) {
        return res.status(403).json({
          success: false,
          message: "You are not allowed to view this lead",
        });
      }
    }
    // admin: no further check needed

    // ✅ VIEW TRACKING
    const now = new Date();
    const actorRole: "admin" | "developer" =
      userRole === "developer" ? "developer" : "admin";

    const update: any = {
      $set: {
        lastViewedAt: now,
        lastViewedBy: userEmail,
      },
      $inc: {
        viewCount: 1,
      },
    };

    // First time open — set openedAt only once
    if (!lead.openedAt) {
      update.$set.openedAt = now;
      update.$set.openedBy = userEmail;
      update.$set.openedByRole = actorRole;
    }

    await Lead.updateOne({ _id: id }, update);

    const updatedLead = await Lead.findById(id).lean();

    return res.status(200).json({
      success: true,
      data: updatedLead,
    });
  } catch (error) {
    console.error("GET Lead Error:", error);
    return res.status(500).json({
      success: false,
      message: "Failed to fetch lead",
    });
  }
}

// ============================================
// 🔄 PATCH - Update Lead
// ============================================

async function handlePatch(
  req: NextApiRequest,
  res: NextApiResponse,
  id: string,
  authToken: Awaited<ReturnType<typeof requireAuth>> & {}
) {
  try {
    const userRole = authToken!.role;
    const userEmail = authToken!.email || "";

    const lead = await Lead.findById(id).lean() as any;
    if (!lead) {
      return res.status(404).json({
        success: false,
        message: "Lead not found",
      });
    }

    // ✅ RBAC — developer can only patch their own leads
    if (userRole === "developer") {
      const isOwner =
        lead.developerSnapshot?.email === userEmail ||
        lead.assignedTo === userEmail ||
        lead.assignedToUserId?.toString() === authToken!.id;

      if (!isOwner) {
        return res.status(403).json({
          success: false,
          message: "Unauthorized",
        });
      }
    }

    const actorEmail = userEmail || "system";
    const actorRole: "admin" | "developer" =
      userRole === "developer" ? "developer" : "admin";

    const { status, priority, assignedTo, assignedToRole, notes } = req.body;

    // ✅ Input validation
    const VALID_STATUSES = [
      "new", "contacted", "qualified", "site_visit_scheduled",
      "proposal_sent", "negotiation", "won", "lost", "nurture",
    ];
    const VALID_PRIORITIES = ["low", "medium", "high", "urgent"];

    if (status && !VALID_STATUSES.includes(status)) {
      return res.status(400).json({
        success: false,
        message: "Invalid status value",
      });
    }

    if (priority && !VALID_PRIORITIES.includes(priority)) {
      return res.status(400).json({
        success: false,
        message: "Invalid priority value",
      });
    }

    // ✅ Build $set and $push SEPARATELY to avoid MongoDB conflict
    const $set: any = { lastContactedAt: new Date() };
    const timelineEntries: TimelineEntry[] = [];

    if (status && status !== lead.status) {
      $set.status = status;
      timelineEntries.push({
        action: "status_changed",
        performedBy: actorEmail,
        performedByRole: actorRole,
        timestamp: new Date(),
        statusBefore: lead.status,
        statusAfter: status,
      });
    }

    if (priority && priority !== lead.priority) {
      $set.priority = priority;
      timelineEntries.push({
        action: "priority_changed",
        performedBy: actorEmail,
        performedByRole: actorRole,
        timestamp: new Date(),
      });
    }

    // ✅ Only admin can reassign leads
    if (userRole === "admin" && assignedTo !== undefined) {
      $set.assignedTo = assignedTo || null;
      if (assignedToRole) $set.assignedToRole = assignedToRole;

      timelineEntries.push({
        action: assignedTo ? "assigned" : "unassigned",
        performedBy: actorEmail,
        performedByRole: actorRole,
        timestamp: new Date(),
      });
    }

    if (notes !== undefined) {
      if (typeof notes !== "string" || notes.length > 5000) {
        return res.status(400).json({
          success: false,
          message: "Notes must be a string under 5000 characters",
        });
      }
      $set.notes = notes;
    }

    // ✅ Build update op — $set and $push are separate top-level keys
    const updateOp: any = { $set };
    if (timelineEntries.length > 0) {
      updateOp.$push = { timeline: { $each: timelineEntries } };
    }

    const updated = await Lead.findByIdAndUpdate(id, updateOp, {
      new: true,
      runValidators: true,
    }).lean();

    return res.status(200).json({
      success: true,
      message: "Lead updated successfully",
      data: updated,
    });
  } catch (error) {
    console.error("PATCH Lead Error:", error);
    return res.status(500).json({
      success: false,
      message: "Failed to update lead",
    });
  }
}

// ============================================
// 🗑️ DELETE - Archive Lead (Admin Only)
// ============================================

async function handleDelete(
  req: NextApiRequest,
  res: NextApiResponse,
  id: string,
  authToken: Awaited<ReturnType<typeof requireAuth>> & {}
) {
  try {
    // ✅ Archive is admin-only — verified from session
    if (authToken!.role !== "admin") {
      return res.status(403).json({
        success: false,
        message: "Only admin can archive leads",
      });
    }

    const userEmail = authToken!.email || "admin";

    const archived = await Lead.findByIdAndUpdate(
      id,
      {
        $set: {
          isArchived: true,
          archivedAt: new Date(),
          archivedBy: userEmail,
        },
      },
      { new: true }
    ).lean();

    if (!archived) {
      return res.status(404).json({
        success: false,
        message: "Lead not found",
      });
    }

    return res.status(200).json({
      success: true,
      message: "Lead archived",
      data: archived,
    });
  } catch (error) {
    console.error("DELETE Lead Error:", error);
    return res.status(500).json({
      success: false,
      message: "Failed to archive lead",
    });
  }
}

// pages/api/leads/[id]/email.ts
// REWRITTEN v2.0 — Session-based auth, rate limiting, no error leaks

import type { NextApiRequest, NextApiResponse } from "next";
import mongoose from "mongoose";
import dbConnect from "@/lib/dbConnect";
import Lead from "@/models/Lead";
import Email from "@/models/Email";
import { sendEmail } from "@/lib/email";
import { requireAuth } from "@/lib/requireAuth";
import { rateLimitAdmin, rateLimitApiWrite } from "@/lib/rateLimit";

// ============================================
// SECURITY HEADERS
// ============================================

function setSecurityHeaders(res: NextApiResponse) {
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "DENY");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
}

// ============================================
// MAIN HANDLER
// ============================================

type Data =
  | { success: true; message: string; emailId?: string; emails?: any[] }
  | { success: false; message: string };

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<Data>
) {
  setSecurityHeaders(res);

  const { id } = req.query;

  // ✅ ObjectId validation
  if (!id || typeof id !== "string" || !mongoose.Types.ObjectId.isValid(id)) {
    return res.status(400).json({
      success: false,
      message: "Invalid lead ID",
    });
  }

  // ✅ Method guard early
  if (!["GET", "POST"].includes(req.method || "")) {
    res.setHeader("Allow", ["GET", "POST"]);
    return res.status(405).json({
      success: false,
      message: "Method not allowed",
    });
  }

  // ✅ Rate limiting — stricter for POST (email send) vs GET
  const rl =
    req.method === "POST"
      ? await rateLimitApiWrite(req)   // 30/min — prevents email spam
      : await rateLimitAdmin(req);     // 200/min — read is fine

  if (!rl.ok) {
    res.setHeader("Retry-After", String(rl.retryAfter ?? 60));
    return res.status(429).json({
      success: false,
      message: `Too many requests. Please try again in ${rl.retryAfter ?? 60} seconds.`,
    });
  }

  // ✅ Session-based auth — no more query params
  const authToken = await requireAuth(req, res);
  if (!authToken) return; // requireAuth sent the error

  // ✅ Only admin and developer allowed
  const userRole = authToken.role;
  const userEmail = authToken.email || "";

  if (!["admin", "developer"].includes(userRole)) {
    return res.status(403).json({
      success: false,
      message: "Insufficient permissions",
    });
  }

  try {
    await dbConnect();

    // ✅ Fetch lead
    const lead = await Lead.findById(id);

    if (!lead || lead.isArchived) {
      return res.status(404).json({
        success: false,
        message: "Lead not found",
      });
    }

    // ✅ RBAC — developer can only access their own leads
    if (userRole === "developer") {
      const isOwner =
        lead.developerSnapshot?.email === userEmail ||
        (lead.assignedTo && lead.assignedTo === userEmail) ||
        lead.assignedToUserId?.toString() === authToken.id;

      if (!isOwner) {
        return res.status(403).json({
          success: false,
          message: "Not allowed to access emails for this lead",
        });
      }
    }

    // ==========================================
    // GET — Fetch Email History
    // ==========================================
    if (req.method === "GET") {
      const emails = await Email.find({
        leadId: lead._id,
        isArchived: { $ne: true },
      })
        .sort({ sentAt: -1 })
        .lean();

      return res.status(200).json({
        success: true,
        message: "Emails fetched successfully",
        emails,
      });
    }

    // ==========================================
    // POST — Send New Email
    // ==========================================
    if (req.method === "POST") {
      const { subject, message } = req.body || {};

      // ✅ Input validation
      if (!subject || typeof subject !== "string" || subject.trim().length === 0) {
        return res.status(400).json({
          success: false,
          message: "Subject is required",
        });
      }

      if (!message || typeof message !== "string" || message.trim().length === 0) {
        return res.status(400).json({
          success: false,
          message: "Message is required",
        });
      }

      if (subject.length > 200) {
        return res.status(400).json({
          success: false,
          message: "Subject must be under 200 characters",
        });
      }

      if (message.length > 10000) {
        return res.status(400).json({
          success: false,
          message: "Message must be under 10,000 characters",
        });
      }

      const to = lead.email;
      const toName = lead.name;
      const fromName =
        userRole === "admin"
          ? "Highrise.pk Admin"
          : (lead as any).developerSnapshot?.companyName || "Highrise.pk Developer";

      const htmlBody = `
        <div style="font-family: Arial, sans-serif; color: #333;">
          <p>Assalam-u-Alaikum ${toName || ""},</p>
          <p>${message.replace(/\n/g, "<br/>")}</p>
          <br/>
          <div style="margin-top: 20px; padding-top: 10px; border-top: 1px solid #eee;">
            <p style="font-size: 14px; color: #666;">
              Best regards,<br/>
              <strong>${fromName}</strong><br/>
              ${userEmail}
            </p>
          </div>
        </div>
      `;

      const emailResult = await sendEmail({
        to,
        subject: subject.trim(),
        html: htmlBody,
        fromName,
      });

      const emailDoc = await Email.create({
        to,
        toName,
        from:
          process.env.EMAIL_FROM ||
          process.env.EMAIL_USER ||
          "info@highrise.pk",
        subject: subject.trim(),
        message,
        htmlContent: htmlBody,
        status: emailResult.success ? "sent" : "failed",
        errorMessage: emailResult.success ? "" : "Send failed",
        leadId: lead._id,
        leadName: lead.name,
        sentBy: userEmail,
        sentAt: new Date(),
      });

      // ✅ Timeline update via $push — no conflict with plain fields
      await Lead.findByIdAndUpdate(lead._id, {
        $push: {
          timeline: {
            action: "Email Sent",
            performedBy: userEmail,
            performedByRole: userRole === "admin" ? "admin" : "developer",
            timestamp: new Date(),
            notes: subject.trim(),
            metadata: {
              emailId: emailDoc._id,
              to,
            },
          },
        },
        $set: {
          lastContactedAt: new Date(),
        },
      });

      if (!emailResult.success) {
        return res.status(500).json({
          success: false,
          message: "Email log created but sending failed. Please try again.",
        });
      }

      return res.status(200).json({
        success: true,
        message: "Email sent successfully",
        emailId: emailDoc._id.toString(),
      });
    }
  } catch (error) {
    console.error("Error in lead email API:", error);
    return res.status(500).json({
      success: false,
      message: "Internal server error",
    });
  }
}

