                  ${
                    propertySnapshot?.society || projectSnapshot?.area
                      ? `<tr><td style="padding:4px 0;color:#6b7280;">Area:</td><td style="padding:4px 0;">${
                          propertySnapshot?.society || projectSnapshot?.area
                        }</td></tr>`
                      : ''
                  }
                </table>

                <div style="text-align:center;margin-top:10px;">
                  <a href="${dashboardUrl}" 
                     style="display:inline-block;margin:0 4px 8px 4px;background:#029bba;color:white;padding:10px 18px;text-decoration:none;border-radius:999px;font-size:14px;font-weight:600;">
                    View Lead in Dashboard →
                  </a>
                  <a href="${listingUrl}" 
                     style="display:inline-block;margin:0 4px;background:#f3f4f6;color:#111827;padding:10px 18px;text-decoration:none;border-radius:999px;font-size:14px;font-weight:500;">
                    Open Listing →
                  </a>
                </div>

                <p style="margin-top:16px;font-size:12px;color:#9ca3af;text-align:center;">
                  This email was sent by Highrise.pk lead system. Please respond to the client as soon as possible.
                </p>
              </div>
            </div>
          </body>
          </html>
        `;

        if (developer?.email) {
          await sendEmail({
            to: developer.email,
            subject: `New Lead for ${listingTitle} | Highrise.pk`,
            html,
            fromName: 'Highrise.pk Leads',
          });
        }
      } catch (emailError) {
        console.error('[Leads Email Error]', (emailError as any)?.message || emailError);
        // Email failure should NOT block lead creation
      }

      return res.status(201).json({
        success: true,
        message:
          'Your inquiry has been sent successfully! The developer/agent will contact you soon.',
        data: {
          leadId: lead._id,
          leadScore: lead.leadScore,
          priority: lead.priority,
          status: lead.status,
        },
      });
    } catch (error: any) {
      console.error('[Leads POST Error]', error);
      return res.status(500).json({
        success: false,
        message: 'Server error while submitting lead. Please try again.',
      });
    }
  }

  // ==========================================
  // GET: Fetch Leads (Admin + Developer + Agent)
  // ==========================================
  if (req.method === 'GET') {
    // V6.8.0: Rate limit lead reads (prevents enumeration)
    const rl = await rateLimitAgent(req);
    if (!rl.ok) {
      res.setHeader('Retry-After', String(rl.retryAfter ?? 60));
      return res.status(429).json({
        success: false,
        message: `Too many requests. Retry in ${rl.retryAfter ?? 60} seconds.`,
      });
    }

    await dbConnect();

    try {
      // 🔐 Secure: Get user from NextAuth session
      const session: any = await getServerSession(req, res, authOptions as any);

      if (!session || !session.user) {
        return res.status(401).json({
          success: false,
          message: 'Authentication required',
        });
      }

      const currentEmail = session.user.email || '';
      const currentUserId = (session.user as any).id || (session.user as any)._id || '';
      const currentRole = (session.user as any).role || 'user';

      // V6.8.0: Session 3 capability flag pattern
      const isVerifiedAgent = Boolean((session.user as any).isVerifiedAgent);
      const isVerifiedOwner = Boolean((session.user as any).isVerifiedOwner);

      const {
        developerId,
        projectId,
        status,
        priority,
        source,
        leadType,
        search,
        page = '1',
        limit = '20',
        sortBy = 'createdAt',
        sortOrder = 'desc',
        dateFrom,
        dateTo,
        minScore,
        maxScore,
        isArchived = 'false',
      } = req.query;

      // Archived filter:
      // isArchived = 'true'  -> only archived
      // isArchived = 'false' -> only active (default)
      // isArchived = 'all'   -> no isArchived filter
      const filter: any = {};
      if (isArchived === 'true') {
        filter.isArchived = true;
      } else if (isArchived === 'false') {
        filter.isArchived = false;
      }

      // V6.8.0: Role-based filtering (Session 3 capability flag pattern)
      // Admin: sees everything
      // Agent: role='agent' OR isVerifiedAgent=true (backward compat + new pattern)
      // Developer: role='developer'
      // Owner: isVerifiedOwner=true
      const isAdmin      = currentRole === 'admin';
      const isDeveloper  = currentRole === 'developer';
      const isAgent      = currentRole === 'agent' || isVerifiedAgent;
      const isOwner      = isVerifiedOwner;

      if (isAdmin) {
        // Admin sees all leads, optionally filtered by developerId
        if (developerId) {
          filter['developerSnapshot._id'] = developerId;
        }
      } else if (isDeveloper) {
        // Developer sees only their own project leads
        if (currentEmail) {
          filter.$or = [
            { 'developerSnapshot.email': currentEmail },
            { assignedTo: currentEmail },
            { assignedToUserId: currentUserId },
          ];
        }
      } else if (isAgent) {
        // Agent sees only their property leads (matches by owner email/id)
        if (currentEmail) {
          filter.$or = [
            { 'propertySnapshot.ownerEmail': currentEmail },
            { assignedTo: currentEmail },
            { assignedToUserId: currentUserId },
          ];
        }
      } else if (isOwner) {
        // Owner sees only leads on their own property listings
        if (currentEmail) {
          filter.$or = [
            { 'propertySnapshot.ownerEmail': currentEmail },
            { assignedToUserId: currentUserId },
          ];
        }
      } else {
        // Regular user has no lead access
        return res.status(403).json({
          success: false,
          message: 'Not authorized to view leads',
        });
      }

      if (projectId) {
        filter.project = projectId;
      }

      if (status && status !== 'all') {
        filter.status = { $in: (status as string).split(',') };
      }

      if (priority && priority !== 'all') {
        filter.priority = { $in: (priority as string).split(',') };
      }

      if (source && source !== 'all') {
        filter.source = source;
      }

      if (leadType && leadType !== 'all') {
        filter.leadType = leadType;
      }

      if (search) {
        const searchFilter = {
          $or: [
            { name: { $regex: search, $options: 'i' } },
            { email: { $regex: search, $options: 'i' } },
            { phone: { $regex: search, $options: 'i' } },
            { message: { $regex: search, $options: 'i' } },
          ],
        };

        // ✅ If a role-based $or filter already exists, wrap both in $and
        // so neither overwrites the other. Without this, searching "Ali"
        // would return leads from ALL developers, not just the current one.
        if (filter.$or) {
          filter.$and = [{ $or: filter.$or }, searchFilter];
          delete filter.$or;
        } else {
          filter.$or = searchFilter.$or;
        }
      }

      if (dateFrom || dateTo) {
        filter.createdAt = {};
        if (dateFrom) filter.createdAt.$gte = new Date(dateFrom as string);
        if (dateTo) {
          const endDate = new Date(dateTo as string);
          endDate.setHours(23, 59, 59, 999);
          filter.createdAt.$lte = endDate;
        }
      }

      if (minScore) {
        filter.leadScore = { ...filter.leadScore, $gte: parseInt(minScore as string) };
      }
      if (maxScore) {
        filter.leadScore = { ...filter.leadScore, $lte: parseInt(maxScore as string) };
      }

      const pageNum = parseInt(page as string);
      const limitNum = parseInt(limit as string);
      const skip = (pageNum - 1) * limitNum;

      const sortOptions: any = {};
      sortOptions[sortBy as string] = sortOrder === 'asc' ? 1 : -1;

      const [leads, total] = await Promise.all([
        Lead.find(filter)
          .sort(sortOptions)
          .skip(skip)
          .limit(limitNum)
          .populate('project', 'projectName slug')
          .populate('unit', 'unitNumber floorNumber type')
          .lean(),
        Lead.countDocuments(filter),
      ]);

      const statsFilter = { ...filter };
      delete statsFilter.status;

      const stats = await Lead.aggregate([
        { $match: statsFilter },
        {
          $facet: {
            byStatus: [{ $group: { _id: '$status', count: { $sum: 1 } } }],
            byPriority: [{ $group: { _id: '$priority', count: { $sum: 1 } } }],
            totals: [
              {
                $group: {
                  _id: null,
                  total: { $sum: 1 },
                  avgScore: { $avg: '$leadScore' },
                  totalWon: {
                    $sum: { $cond: [{ $eq: ['$status', 'won'] }, 1, 0] },
                  },
                  totalLost: {
                    $sum: { $cond: [{ $eq: ['$status', 'lost'] }, 1, 0] },
                  },
                  totalRevenue: {
                    $sum: {
                      $cond: [{ $eq: ['$status', 'won'] }, '$conversionValue', 0],
                    },
                  },
                },
              },
            ],
          },
        },
      ]);

      const statusCounts: any = {
        all: 0,
        new: 0,
        contacted: 0,
        qualified: 0,
        site_visit_scheduled: 0,
        proposal_sent: 0,
        negotiation: 0,
        won: 0,
        lost: 0,
        nurture: 0,
      };

      if (stats[0]?.byStatus) {
        stats[0].byStatus.forEach((item: any) => {
          statusCounts[item._id] = item.count;
          statusCounts.all += item.count;
        });
      }

      const priorityCounts: any = {
        low: 0,
        medium: 0,
        high: 0,
        urgent: 0,
      };

      if (stats[0]?.byPriority) {
        stats[0].byPriority.forEach((item: any) => {
          priorityCounts[item._id] = item.count;
        });
      }

      const totals = stats[0]?.totals[0] || {
        total: 0,
        avgScore: 0,
        totalWon: 0,
        totalLost: 0,
        totalRevenue: 0,
      };

      const conversionRate =
        totals.total > 0 ? ((totals.totalWon / totals.total) * 100).toFixed(2) : '0.00';

      return res.status(200).json({
        success: true,
        data: leads,
        stats: {
          ...statusCounts,
          priority: priorityCounts,
          avgScore: Math.round(totals.avgScore || 0),
          conversionRate: parseFloat(conversionRate),
          totalRevenue: totals.totalRevenue || 0,
        },
        pagination: {
          page: pageNum,
          limit: limitNum,
          total,
          totalPages: Math.ceil(total / limitNum),
        },
      });

    } catch (error: any) {
      console.error('[Leads GET Error]', error);
      return res.status(500).json({
        success: false,
        message: 'Server error while fetching leads. Please try again.',
      });
    }
  }

  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

// ========== FILE: pages/api/leads/quick.ts ==========
// Highrise.pk — 1-Click Lead Submission
// V6.9.0 — Social Login Lead Capture
// ═══════════════════════════════════════════════════════════════
// Logic:
//   1. Authenticate user via NextAuth session
//   2. Check if user has phone & isPhoneVerified
//   3. Fetch Property/Project details for snapshot
//   4. Create Lead using Profile data (Pre-filled)
//   5. Return Success → UI shows "Inquiry Sent!"
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import { getServerSession }                     from 'next-auth/next';
import { authOptions }                          from '@/pages/api/auth/[...nextauth]';
import dbConnect                                from '@/lib/dbConnect';
import Lead                                     from '@/models/Lead';
import User                                     from '@/models/User';
import Project                                  from '@/models/Projects';
import Property                                 from '@/models/Property';
import { rateLimitInquiry, sendRateLimitResponse } from '@/lib/rateLimit';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  // ── Rate limit check ───────────────────────────────────────
  const rl = await rateLimitInquiry(req);
  if (!rl.ok) return sendRateLimitResponse(res, rl);

  // ── Auth check ─────────────────────────────────────────────
  const session = await getServerSession(req, res, authOptions);
  if (!session?.user?.id) {
    return res.status(401).json({ success: false, message: 'Authentication required' });
  }

  await dbConnect();

  try {
    const { 
      projectId, 
      propertyId, 
      leadType = 'project_interest',
      message = "Interested in this listing. Please contact me.",
      source = 'direct'
    } = req.body;

    // ── 1. Fetch User Profile for Data ───────────────────────
    const user = await User.findById(session.user.id).lean();
    if (!user || !user.phone || !user.isPhoneVerified) {
      return res.status(403).json({ 
        success: false, 
        message: 'Verified phone number required for quick inquiry.',
        code: 'PHONE_NOT_VERIFIED'
      });
    }

    // ── 2. Determine Entity & Developer ──────────────────────
    let projectSnapshot, propertySnapshot, developerId, developerSnapshot;

    if (projectId) {
      const project: any = await Project.findById(projectId).lean();
      if (!project) return res.status(404).json({ success: false, message: 'Project not found' });
      
      projectSnapshot = {
        _id: project._id,
        projectName: project.projectName,
        slug: project.slug,
        city: project.city,
        area: project.area,
        minPrice: project.minPrice,
        maxPrice: project.maxPrice,
        primaryImage: project.images?.[0]?.url || project.gallery?.[0]?.url,
      };
      developerId = project.developerProfile;
    } else if (propertyId) {
      const property: any = await Property.findById(propertyId).lean();
      if (!property) return res.status(404).json({ success: false, message: 'Property not found' });
      
      propertySnapshot = {
        _id: property._id,
        title: property.title,
        slug: property.slug,
        city: property.city,
        society: property.society,
        price: property.price,
        primaryImage: property.images?.[0]?.url,
      };
      developerId = property.owner;
    } else {
      return res.status(400).json({ success: false, message: 'Entity ID required' });
    }

    // ── 3. Get Developer Snapshot ────────────────────────────
    const developer = await User.findById(developerId).select('companyName email phone logo').lean();
    if (developer) {
      developerSnapshot = {
        _id: developer._id,
        companyName: (developer as any).companyName || 'Verified Partner',
        email: developer.email,
        phone: (developer as any).phone,
        logo: (developer as any).logo,
      };
    }

    // ── 4. CREATE THE LEAD ───────────────────────────────────
    const lead = await Lead.create({
      name: user.name,
      email: user.email,
      phone: user.phone,
      leadType,
      entityType: projectId ? 'project' : 'property',
      project: projectId || undefined,
      projectSnapshot,
      property: propertyId || undefined,
      propertySnapshot,
      developer: developerId,
      developerSnapshot,
      source,
      status: 'new',
      assignedTo: developer?.email,
      assignedToRole: projectId ? 'developer' : 'agent',
      assignedToUserId: developerId,
      // Metadata
      notes: `[Quick Inquiry] User was logged in via social auth.`,
      tags: ['social_lead', 'verified_phone'],
    });

    // Increment inquiry counts
    if (projectId) await Project.findByIdAndUpdate(projectId, { $inc: { inquiries: 1 } });
    else if (propertyId) await Property.findByIdAndUpdate(propertyId, { $inc: { inquiries: 1 } });

    return res.status(201).json({
      success: true,
      message: 'Inquiry sent! The partner will contact you soon.',
      leadId: lead._id
    });

  } catch (error: any) {
    console.error('[QuickLead API Error]', error.message);
    return res.status(500).json({ success: false, message: 'Server error creating lead' });
  }
}

