/**
 * Build "From" header string with optional custom name/email.
 */
function buildFromHeader(fromName?: string, fromEmail?: string): string {
  const name  = (fromName  || '').trim() || DEFAULT_FROM_NAME;
  const email = (fromEmail || '').trim() || DEFAULT_FROM_EMAIL;
  return `"${name.replace(/"/g, '\\"')}" <${email}>`;
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ─────────────────────────────────────────────
  // STEP 1: Method validation
  // ─────────────────────────────────────────────
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 2: Rate limit
  // ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: {
        context:  'newsletter_campaign_send',
        endpoint: '/api/newsletter/campaigns/[id]/send',
      },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 3: Admin authentication
  // ─────────────────────────────────────────────
  const adminToken = await requireAdmin(req, res);
  if (!adminToken) return;

  // ─────────────────────────────────────────────
  // STEP 4: Validate campaign ID
  // ─────────────────────────────────────────────
  const { id } = req.query;

  if (!id || typeof id !== 'string' || !mongoose.Types.ObjectId.isValid(id)) {
    await logSecurityEvent({
      type:     'suspicious_activity',
      severity: 'medium',
      userId:   adminToken.id,
      email:    adminToken.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        context: 'newsletter_campaign_send',
        reason:  'invalid_campaign_id',
        providedId: String(id).slice(0, 50),
      },
    });
    res.status(400).json({
      success: false,
      message: 'Invalid campaign ID',
      requestId,
    });
    return;
  }

  await dbConnect();

  try {
    // ─────────────────────────────────────────────
    // STEP 5: Fetch campaign
    // ─────────────────────────────────────────────
    const campaign = await NewsletterCampaign.findById(id);

    if (!campaign) {
      res.status(404).json({
        success: false,
        message: 'Campaign not found',
        requestId,
      });
      return;
    }

    if (campaign.isDeleted) {
      res.status(400).json({
        success: false,
        message: 'Cannot send a deleted campaign',
        requestId,
      });
      return;
    }

    if (campaign.content && campaign.content.length > MAX_CONTENT_LENGTH) {
      res.status(400).json({
        success: false,
        message: `Content exceeds max size (${MAX_CONTENT_LENGTH} bytes)`,
        requestId,
      });
      return;
    }

    if (!ALLOWED_TEMPLATES.includes(campaign.template)) {
      res.status(400).json({
        success: false,
        message: 'Campaign uses an invalid template',
        requestId,
      });
      return;
    }

    // ─────────────────────────────────────────────
    // STEP 6: Parse request body
    // ─────────────────────────────────────────────
    const { testEmail } = req.body || {};

    // Sender config (Option C — default with override)
    const fromName      = (campaign as any).fromName    || '';
    const fromEmail     = (campaign as any).fromEmail   || '';
    const replyTo       = (campaign as any).replyTo     || '';
    const previewText   = (campaign as any).previewText || '';
    const mergeTagsEnabled = (campaign as any).mergeTagsEnabled !== false;
    const fromHeader    = buildFromHeader(fromName, fromEmail);

    // ═══════════════════════════════════════════════════════════
    // MODE A: TEST EMAIL
    // ═══════════════════════════════════════════════════════════
    if (testEmail) {
      // Support comma-separated emails (up to 5)
      const emails = String(testEmail)
        .split(/[,;\n]/)
        .map((e) => e.trim().toLowerCase())
        .filter((e) => e.length > 0)
        .slice(0, 5);

      const invalid = emails.filter((e) => !isValidEmail(e));
      if (invalid.length > 0) {
        res.status(400).json({
          success: false,
          message: `Invalid email(s): ${invalid.slice(0, 3).join(', ')}`,
          requestId,
        });
        return;
      }

      if (emails.length === 0) {
        res.status(400).json({
          success: false,
          message: 'No valid test emails provided',
          requestId,
        });
        return;
      }

      try {
        // Build test HTML with sample merge tag data
        const htmlContent = buildEmailHtml({
          content:          campaign.content,
          subject:          campaign.subject,
          previewText,
          unsubscribeUrl:   'https://highrise.pk/unsubscribe?test=true',
          mergeTagsEnabled,
          recipientData:    undefined,  // Uses sample data
        });

        // Send to all test emails
        await Promise.all(emails.map((email) =>
          transporter.sendMail({
            from:    fromHeader,
            to:      email,
            replyTo: replyTo || undefined,
            subject: `[TEST] ${campaign.subject}`,
            html:    htmlContent,
            headers: {
              'X-Test-Email':     'true',
              'X-Sent-By-Admin':  adminToken.id,
              'X-Request-Id':     requestId,
              'X-Campaign-Id':    String(campaign._id),
            },
          })
        ));

        await logSecurityEvent({
          type:     'admin_action',
          severity: 'low',
          userId:   adminToken.id,
          email:    adminToken.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            context:    'newsletter_campaign_send',
            action:     'test_emails_sent',
            campaignId: String(campaign._id),
            recipientCount: emails.length,
          },
        });

        res.status(200).json({
          success: true,
          message: `Test email sent to ${emails.length} recipient${emails.length > 1 ? 's' : ''}`,
          count:   emails.length,
          requestId,
        });
        return;
      } catch (error: unknown) {
        const errMsg = error instanceof Error ? error.message : 'Unknown error';

        await logSecurityEvent({
          type:     'system_error',
          severity: 'high',
          userId:   adminToken.id,
          email:    adminToken.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            context:    'newsletter_campaign_send',
            reason:     'test_email_failed',
            campaignId: String(campaign._id),
            error:      errMsg.slice(0, 200),
          },
        });

        res.status(500).json({
          success: false,
          message: 'Failed to send test email',
          requestId,
        });
        return;
      }
    }

    // ═══════════════════════════════════════════════════════════
    // MODE B: PRODUCTION SEND
    // ═══════════════════════════════════════════════════════════

    // ─────────────────────────────────────────────
    // STEP 7: Concurrency lock
    // ─────────────────────────────────────────────
    if (campaign.status === 'sending') {
      await logSecurityEvent({
        type:     'suspicious_activity',
        severity: 'medium',
        userId:   adminToken.id,
        email:    adminToken.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          context:    'newsletter_campaign_send',
          reason:     'duplicate_send_attempted',
          campaignId: String(campaign._id),
        },
      });
      res.status(409).json({
        success: false,
        message: 'Campaign is already being sent. Please wait.',
        requestId,
      });
      return;
    }

    if (campaign.status === 'sent') {
      res.status(400).json({
        success: false,
        message: 'Campaign has already been sent',
        requestId,
      });
      return;
    }

    // Atomic lock
    const lockResult = await NewsletterCampaign.findOneAndUpdate(
      { _id: campaign._id, status: { $in: ['draft', 'scheduled'] } },
      { $set: { status: 'sending' } },
      { new: true }
    );

    if (!lockResult) {
      res.status(409).json({
        success: false,
        message: 'Could not lock campaign for sending. Try again.',
        requestId,
      });
      return;
    }

    // ─────────────────────────────────────────────
    // STEP 8: PHASE 2 — Fetch recipients (multi-source)
    // ─────────────────────────────────────────────
    const recipientSource: RecipientSource = ((campaign as any).recipientSource as RecipientSource) || 'subscribers';
    const leadFilters = sanitizeLeadFilters((campaign as any).leadFilters);

    const fetchResult = await fetchRecipients(recipientSource, leadFilters);
    const { recipients, stats: recipientStats } = fetchResult;

    if (recipients.length === 0) {
      // Restore campaign status
      campaign.status = 'draft';
      await campaign.save();

      res.status(400).json({
        success: false,
        message: 'No recipients match the campaign filters',
        requestId,
      });
      return;
    }

    if (recipients.length > MAX_RECIPIENTS) {
      campaign.status = 'draft';
      await campaign.save();

      await logSecurityEvent({
        type:     'suspicious_activity',
        severity: 'high',
        userId:   adminToken.id,
        email:    adminToken.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          context:    'newsletter_campaign_send',
          reason:     'recipient_limit_exceeded',
          campaignId: String(campaign._id),
          count:      recipients.length,
          limit:      MAX_RECIPIENTS,
        },
      });

      res.status(400).json({
        success: false,
        message: `Recipient count (${recipients.length}) exceeds safety limit (${MAX_RECIPIENTS})`,
        requestId,
      });
      return;
    }

    // ─────────────────────────────────────────────
    // STEP 9: Log bulk send start
    // ─────────────────────────────────────────────
    await logSecurityEvent({
      type:     'bulk_action_performed',
      severity: 'critical',
      userId:   adminToken.id,
      email:    adminToken.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        context:          'newsletter_campaign_send',
        action:           'bulk_send_started',
        campaignId:       String(campaign._id),
        totalRecipients:  recipients.length,
        subscribersCount: recipientStats.subscribersCount,
        leadsCount:       recipientStats.leadsCount,
        duplicatesRemoved: recipientStats.duplicatesRemoved,
        recipientSource,
        mergeTagsEnabled,
      },
    });

    // ─────────────────────────────────────────────
    // STEP 10: A/B Test split (if enabled)
    // ─────────────────────────────────────────────
    const abTest = (campaign as any).abTest;
    const isABTest = !!(abTest?.enabled && abTest?.variantBSubject?.trim());

    // Split recipients into A/B groups
    let recipientsA = recipients;
    let recipientsB: typeof recipients = [];

    if (isABTest) {
      const splitPercent = Math.max(10, Math.min(90, abTest.splitPercent ?? 50));
      const splitIndex   = Math.round(recipients.length * (splitPercent / 100));
      recipientsA = recipients.slice(0, splitIndex);
      recipientsB = recipients.slice(splitIndex);
    }

    // Subject lines per variant
    const subjectA     = campaign.subject;
    const subjectB     = isABTest ? (abTest.variantBSubject as string) : campaign.subject;
    const previewTextB = isABTest && abTest.variantBPreview
      ? (abTest.variantBPreview as string)
      : previewText;

    // ─────────────────────────────────────────────
    // STEP 11: Send in batches with personalization
    // ─────────────────────────────────────────────
    let sentCount   = 0;
    let failedCount = 0;
    const failedEmails: string[] = [];

    // Track bounces per source
    const bouncedSubscriberIds: mongoose.Types.ObjectId[] = [];
    const bouncedLeadIds:       mongoose.Types.ObjectId[] = [];

    // Track successful sends
    const successfulSubscriberIds: mongoose.Types.ObjectId[] = [];
    const successfulLeadIds:       mongoose.Types.ObjectId[] = [];

    // Track A/B variant sent counts
    let variantASentCount = 0;
    let variantBSentCount = 0;

    // Combine A+B into unified array with variant tag for processing
    const recipientsTagged: Array<typeof recipients[0] & { _variant: 'a' | 'b' }> = [
      ...recipientsA.map((r) => ({ ...r, _variant: 'a' as const })),
      ...recipientsB.map((r) => ({ ...r, _variant: 'b' as const })),
    ];

    for (let i = 0; i < recipientsTagged.length; i += BATCH_SIZE) {
      const batch = recipientsTagged.slice(i, i + BATCH_SIZE);

      const batchResults = await Promise.allSettled(
        batch.map(async (recipient) => {
          if (!isValidEmail(recipient.email)) {
            throw new Error('invalid_email');
          }

          const variantLabel = recipient._variant;

          // Select subject + preview for this variant
          const recipientSubject     = variantLabel === 'b' ? subjectB     : subjectA;
          const recipientPreviewText = variantLabel === 'b' ? previewTextB : previewText;

          // ── Generate per-recipient tracking token ──────────────
          const trackingToken = generateTrackingToken();

          // ── Create analytics record BEFORE sending ─────────────
          try {
            await CampaignAnalytics.create({
              campaignId:    campaign._id,
              recipientId:   recipient.id,
              recipientType: recipient.source === 'subscriber' ? 'subscriber' : 'lead',
              email:         recipient.email.toLowerCase().trim(),
              name:          recipient.name || '',
              sentAt:        new Date(),
              token:         trackingToken,
              variant:       variantLabel,   // ← A/B variant stored here
            });
          } catch {
            // non-fatal — still send
          }

          // Build personalized HTML per recipient (with tracking)
          const htmlContent = buildEmailHtml({
            content:          campaign.content,
            subject:          recipientSubject,
            previewText:      recipientPreviewText,
            unsubscribeUrl:   recipient.unsubscribeUrl,
            mergeTagsEnabled,
            recipientData:    recipient,
            campaignId:       String(campaign._id),
            trackingToken,
          });

          // Personalize subject line (merge tags)
          const personalizedSubject = mergeTagsEnabled
            ? replaceMergeTags(recipientSubject, recipientToMergeTagData(recipient))
            : recipientSubject;

          await transporter.sendMail({
            from:    fromHeader,
            to:      recipient.email,
            replyTo: replyTo || undefined,
            subject: personalizedSubject,
            html:    htmlContent,
            headers: {
              'X-Campaign-Id':    String(campaign._id),
              'X-Request-Id':     requestId,
              'X-Recipient-Type': recipient.source,
              'X-AB-Variant':     variantLabel.toUpperCase(),
              'List-Unsubscribe': `<${recipient.unsubscribeUrl}>`,
              'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click',
            },
          });

          return recipient;
        })
      );

      // Process results
      for (let j = 0; j < batchResults.length; j++) {
        const result    = batchResults[j];
        const recipient = batch[j];

        if (result.status === 'fulfilled') {
          sentCount++;

          // Track A/B variant counts
          if (recipient._variant === 'a') variantASentCount++;
          else                            variantBSentCount++;

          // Track successful sends by source
          const objectId = new mongoose.Types.ObjectId(recipient.id);
          if (recipient.source === 'subscriber') {
            successfulSubscriberIds.push(objectId);
          } else {
            successfulLeadIds.push(objectId);
          }
        } else {
          failedCount++;
          failedEmails.push(recipient.email);

          // Detect bounces
          const errMsg = (result.reason?.message || '').toLowerCase();
          if (
            errMsg.includes('bounce') ||
            errMsg.includes('rejected') ||
            errMsg.includes('does not exist') ||
            errMsg.includes('invalid_email') ||
            errMsg.includes('no such user') ||
            errMsg.includes('550')
          ) {
            const objectId = new mongoose.Types.ObjectId(recipient.id);
            if (recipient.source === 'subscriber') {
              bouncedSubscriberIds.push(objectId);
            } else {
              bouncedLeadIds.push(objectId);
            }
          }
        }
      }

      // Delay between batches
      if (i + BATCH_SIZE < recipients.length) {
        await sleep(BATCH_DELAY_MS);
      }
    }

    // ─────────────────────────────────────────────
    // STEP 11: Update bounced records
    // ─────────────────────────────────────────────
    if (bouncedSubscriberIds.length > 0) {
      try {
        await NewsletterSubscriber.updateMany(
          { _id: { $in: bouncedSubscriberIds } },
          { $set: { status: 'bounced' } }
        );
      } catch { /* non-fatal */ }
    }

    if (bouncedLeadIds.length > 0) {
      try {
        // For leads: opt them out (they can be re-engaged later manually)
        await Lead.updateMany(
          { _id: { $in: bouncedLeadIds } },
          {
            $set: {
              emailOptOut:   true,
              emailOptOutAt: new Date(),
            },
          }
        );
      } catch { /* non-fatal */ }
    }

    // ─────────────────────────────────────────────
    // STEP 12: Update sent counters
    // ─────────────────────────────────────────────
    if (successfulSubscriberIds.length > 0) {
      try {
        await NewsletterSubscriber.updateMany(
          { _id: { $in: successfulSubscriberIds } },
          {
            $set: { lastEmailSentAt: new Date() },
            $inc: { emailsSent: 1 },
          }
        );
      } catch { /* non-fatal */ }
    }

    // Leads: track lastContactedAt (marketing communication)
    if (successfulLeadIds.length > 0) {
      try {
        await Lead.updateMany(
          { _id: { $in: successfulLeadIds } },
          { $set: { lastContactedAt: new Date() } }
        );
      } catch { /* non-fatal */ }
    }

    // ─────────────────────────────────────────────
    // STEP 13: Update campaign final status
    // ─────────────────────────────────────────────
    campaign.status = 'sent';
    campaign.sentAt = new Date();
    campaign.recipients = {
      ...campaign.recipients,
      total:    recipients.length,
      sent:     sentCount,
      bounced:  bouncedSubscriberIds.length + bouncedLeadIds.length,
    };

    // Update A/B test status + sent counts
    if (isABTest) {
      (campaign as any).abTest = {
        ...(campaign as any).abTest,
        status:       'testing',
        variantASent: variantASentCount,
        variantBSent: variantBSentCount,
      };
    }

    await campaign.save();

    // ─────────────────────────────────────────────
    // STEP 14: Audit log — success
    // ─────────────────────────────────────────────
    await logSecurityEvent({
      type:     'bulk_action_performed',
      severity: 'critical',
      userId:   adminToken.id,
      email:    adminToken.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        context:           'newsletter_campaign_send',
        action:            'bulk_send_completed',
        campaignId:        String(campaign._id),
        totalRecipients:   recipients.length,
        sentCount,
        failedCount,
        bouncedSubscribers: bouncedSubscriberIds.length,
        bouncedLeads:      bouncedLeadIds.length,
        recipientSource,
        mergeTagsEnabled,
      },
    });

    // ─────────────────────────────────────────────
    // STEP 15: Success response
    // ─────────────────────────────────────────────
    res.status(200).json({
      success: true,
      message: `Campaign sent successfully. Delivered: ${sentCount}, Failed: ${failedCount}`,
      requestId,
      stats: {
        total:              recipients.length,
        sent:               sentCount,
        failed:             failedCount,
        bounced:            bouncedSubscriberIds.length + bouncedLeadIds.length,
        subscribersCount:   recipientStats.subscribersCount,
        leadsCount:         recipientStats.leadsCount,
        duplicatesRemoved:  recipientStats.duplicatesRemoved,
        failedEmails:       failedEmails.slice(0, 10),
      },
    });
    return;
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';

    // Try to mark campaign as failed
    try {
      const failedCampaign = await NewsletterCampaign.findById(id);
      if (failedCampaign && failedCampaign.status === 'sending') {
        failedCampaign.status = 'failed';
        await failedCampaign.save();
      }
    } catch { /* ignore */ }

    await logSecurityEvent({
      type:     'system_error',
      severity: 'high',
      userId:   adminToken.id,
      email:    adminToken.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        context:    'newsletter_campaign_send',
        reason:     'send_failed',
        campaignId: String(id),
        error:      errorMessage.slice(0, 200),
      },
    });

    res.status(500).json({
      success: false,
      message: 'Failed to send campaign. Please try again.',
      requestId,
    });
    return;
  }
}
// ========== END OF FILE ==========

// ========== FILE: pages/api/newsletter/campaigns/auto-save.ts ==========
// 🔒 ENTERPRISE AUTO-SAVE API — HIGHRISE.PK
// Security Level: MAXIMUM | Admin Only | Silent Draft Save
// ═══════════════════════════════════════════════════════════════
// PURPOSE:
//   POST → Silently save campaign draft every 10 seconds
//          from MissionControl editor. Never changes status
//          from non-draft states. Never triggers send.
//
// SECURITY:
//   ✅ requireAdmin() — only admins can auto-save
//   ✅ rateLimitAdmin() — prevents save-flood attacks
//   ✅ ObjectId validation — no NoSQL injection
//   ✅ Status guard — NEVER promotes status (draft only)
//   ✅ Content size limit — prevents memory exhaustion
//   ✅ HTML sanitization — DOMPurify on all content
//   ✅ autoSavedAt timestamp — tracks last save
//   ✅ Silent response — minimal data returned
//   ✅ Audit logging — all saves tracked
//   ✅ Security headers — all responses
//   ✅ Generic errors — no stack trace leaks
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose                                  from 'mongoose';
import DOMPurify                                 from 'isomorphic-dompurify';
import dbConnect                                 from '@/lib/db';
import NewsletterCampaign                        from '@/models/NewsletterCampaign';
import { requireAdmin }                          from '@/lib/requireAuth';
import { rateLimitAdmin, sendRateLimitResponse } from '@/lib/rateLimit';
import { logSecurityEvent }                      from '@/lib/security/logSecurityEvent';
import { sanitizeLeadFilters, type RecipientSource } from '@/lib/recipientEngine';

// ═══════════════════════════════════════════════════════════════
// 🔐 CONSTANTS
// ═══════════════════════════════════════════════════════════════

const MAX_TITLE_LENGTH        = 200;
const MAX_SUBJECT_LENGTH      = 200;
const MAX_CONTENT_LENGTH      = 500_000; // 500 KB
const MAX_PREVIEW_TEXT_LENGTH = 300;
const MAX_FROM_NAME_LENGTH    = 150;
const MAX_FROM_EMAIL_LENGTH   = 200;
const MAX_REPLY_TO_LENGTH     = 200;

const ALLOWED_TEMPLATES = [
  'welcome', 'weekly_update', 'property_alert',
  'market_insights', 'custom',
];

const ALLOWED_SEGMENTS = ['all', 'active', 'new', 'inactive', 'premium'];

// Email validation regex (simple, no ReDoS risk)
const EMAIL_REGEX = /^[^\s@]{1,64}@[^\s@]{1,255}\.[^\s@]{1,63}$/;

// 🆕 PHASE 2 — Recipient source whitelist
const ALLOWED_RECIPIENT_SOURCES: RecipientSource[] = ['subscribers', 'leads', 'both'];

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPERS
// ═══════════════════════════════════════════════════════════════

function makeRequestId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') return forwarded.split(',')[0].trim();
  const cfIp = req.headers['cf-connecting-ip'];
  if (typeof cfIp === 'string') return cfIp.trim();
  return req.socket?.remoteAddress || 'unknown';
}

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id',           requestId);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options',        'DENY');
  res.setHeader('X-XSS-Protection',       '1; mode=block');
  res.setHeader('Referrer-Policy',        'strict-origin-when-cross-origin');
  res.setHeader('Cache-Control',          'no-store, must-revalidate, private');
  res.setHeader('Pragma',                 'no-cache');
}

function sanitizeHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      'a', 'b', 'br', 'div', 'em', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'hr', 'i', 'img', 'li', 'ol', 'p', 'span', 'strong', 'table',
      'tbody', 'td', 'th', 'thead', 'tr', 'ul', 'blockquote', 'code',
      'pre', 'small', 'sub', 'sup', 'u',
    ],
    ALLOWED_ATTR: [
      'href', 'target', 'rel', 'src', 'alt', 'width', 'height',
      'style', 'class', 'id', 'colspan', 'rowspan', 'align', 'valign',
      'bgcolor', 'border', 'cellpadding', 'cellspacing', 'title',
    ],
    ALLOW_DATA_ATTR: false,
    FORBID_TAGS:     ['script', 'iframe', 'object', 'embed', 'form', 'input'],
    FORBID_ATTR:     ['onerror', 'onload', 'onclick', 'onmouseover', 'onfocus'],
  });
}

function sanitizeText(text: string, maxLength: number): string {
  if (!text || typeof text !== 'string') return '';
  return text.replace(/<[^>]*>/g, '').trim().slice(0, maxLength);
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP  = getClientIP(req);
  const userAgent = String(req.headers['user-agent'] || 'unknown').slice(0, 500);

  // ─────────────────────────────────────────────
  // STEP 1: Method guard — POST only
  // ─────────────────────────────────────────────
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 2: Rate limit
  // ─────────────────────────────────────────────
  const rl = await rateLimitAdmin(req);
  if (!rl.ok) {
    await logSecurityEvent({
      type:     'rate_limit_exceeded',
      severity: 'medium',
      ip:       clientIP,
      userAgent,
      metadata: {
        context:  'campaign_auto_save',
        endpoint: '/api/newsletter/campaigns/auto-save',
      },
    });
    sendRateLimitResponse(res, rl);
    return;
  }

  // ─────────────────────────────────────────────
  // STEP 3: Admin authentication
  // ─────────────────────────────────────────────
  const adminToken = await requireAdmin(req, res);
  if (!adminToken) return;

  await dbConnect();

  try {
    const {
      campaignId,
      title,
      subject,
      content,
      template,
      segments,
      previewText,
      fromName,
      fromEmail,
      replyTo,
      // 🆕 Phase 2
      recipientSource,
      leadFilters,
      mergeTagsEnabled,
    } = req.body || {};

    // ─────────────────────────────────────────────
    // STEP 4: Validate campaignId
    // Two modes:
    //   - With ID    → update existing draft
    //   - Without ID → create new draft silently
    // ─────────────────────────────────────────────
    let isNew = false;

    if (campaignId !== undefined && campaignId !== null && campaignId !== '') {
      if (typeof campaignId !== 'string' || !mongoose.Types.ObjectId.isValid(campaignId)) {
        await logSecurityEvent({
          type:     'suspicious_activity',
          severity: 'medium',
          userId:   adminToken.id,
          email:    adminToken.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            context: 'campaign_auto_save',
            reason:  'invalid_campaign_id',
            providedId: String(campaignId).slice(0, 50),
          },
        });
        res.status(400).json({
          success: false,
          message: 'Invalid campaign ID',
          requestId,
        });
        return;
      }
    } else {
      isNew = true;
    }

    // ─────────────────────────────────────────────
    // STEP 5: Sanitize all fields
    // ─────────────────────────────────────────────

    const cleanTitle = title
      ? sanitizeText(String(title), MAX_TITLE_LENGTH)
      : 'Untitled Campaign';

    const cleanSubject = subject
      ? sanitizeText(String(subject), MAX_SUBJECT_LENGTH)
      : '';

    // Content — always HTML from TipTap
    let cleanContent = '';
    if (content && typeof content === 'string') {
      if (content.length > MAX_CONTENT_LENGTH) {
        res.status(400).json({
          success: false,
          message: 'Content exceeds maximum size',
          requestId,
        });
        return;
      }
      cleanContent = sanitizeHtml(content);
    }

    // Template
    const templateId = template && ALLOWED_TEMPLATES.includes(String(template))
      ? String(template)
      : 'custom';

    // Segments
    let cleanSegments: string[] = ['all'];
    if (Array.isArray(segments)) {
      const filtered = segments.filter(
        (s: unknown): s is string => typeof s === 'string' && ALLOWED_SEGMENTS.includes(s)
      );
      if (filtered.length > 0) cleanSegments = filtered;
    }

    // Preview text
    const cleanPreviewText = previewText
      ? sanitizeText(String(previewText), MAX_PREVIEW_TEXT_LENGTH)
      : '';

    // From name
    const cleanFromName = fromName
      ? sanitizeText(String(fromName), MAX_FROM_NAME_LENGTH)
      : '';

    // From email
    let cleanFromEmail = '';
    if (fromEmail && typeof fromEmail === 'string') {
      const trimmed = fromEmail.trim().toLowerCase().slice(0, MAX_FROM_EMAIL_LENGTH);
      if (trimmed && EMAIL_REGEX.test(trimmed)) {
        cleanFromEmail = trimmed;
      }
      // Silent fail on invalid email during auto-save
      // (user is still typing — don't interrupt with errors)
    }

    // Reply-to
    let cleanReplyTo = '';
    if (replyTo && typeof replyTo === 'string') {
      const trimmed = replyTo.trim().toLowerCase().slice(0, MAX_REPLY_TO_LENGTH);
      if (trimmed && EMAIL_REGEX.test(trimmed)) {
        cleanReplyTo = trimmed;
      }
      // Silent fail on invalid email during auto-save
    }

    // 🆕 PHASE 2 — Recipient source
    let cleanRecipientSource: RecipientSource = 'subscribers';
    if (
      typeof recipientSource === 'string' &&
      ALLOWED_RECIPIENT_SOURCES.includes(recipientSource as RecipientSource)
    ) {
      cleanRecipientSource = recipientSource as RecipientSource;
    }

    // 🆕 PHASE 2 — Lead filters
    const cleanLeadFilters = sanitizeLeadFilters(leadFilters);

    // 🆕 PHASE 2 — Merge tags toggle
    const cleanMergeTagsEnabled = mergeTagsEnabled !== false;

    // ─────────────────────────────────────────────
    // STEP 6: Save or create draft
    // ─────────────────────────────────────────────

    const now = new Date();

    if (isNew) {
      // ── CREATE new draft ──────────────────────
      const newCampaign = await NewsletterCampaign.create({
        title:       cleanTitle,
        subject:     cleanSubject,
        content:     cleanContent,
        template:    templateId,
        status:      'draft',          // ALWAYS draft on auto-save
        segments:    cleanSegments,
        previewText: cleanPreviewText,
        fromName:    cleanFromName,
        fromEmail:   cleanFromEmail,
        replyTo:     cleanReplyTo,
        // 🆕 Phase 2
        recipientSource:  cleanRecipientSource,
        leadFilters:      cleanLeadFilters,
        mergeTagsEnabled: cleanMergeTagsEnabled,
        autoSavedAt: now,
        createdBy:   new mongoose.Types.ObjectId(adminToken.id),
        recipients: {
          total:        0,
          sent:         0,
          opened:       0,
          clicked:      0,
          bounced:      0,
          unsubscribed: 0,
        },
      });

      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   adminToken.id,
        email:    adminToken.email,
        ip:       clientIP,
        userAgent,
        metadata: {
          context:    'campaign_auto_save',
          action:     'auto_save_created',
          campaignId: String(newCampaign._id),
        },
      });

      res.status(201).json({
        success:     true,
        campaignId:  String(newCampaign._id),
        autoSavedAt: now.toISOString(),
        requestId,
      });
      return;

    } else {
      // ── UPDATE existing draft ─────────────────
      const campaign = await NewsletterCampaign.findById(campaignId);

      if (!campaign) {
        res.status(404).json({
          success: false,
          message: 'Campaign not found',
          requestId,
        });
        return;
      }

      // 🔒 CRITICAL SECURITY GUARD:
      // Auto-save NEVER promotes status.
      // It ONLY saves drafts.
      // Sent/sending/scheduled campaigns cannot be auto-saved.
      if (!['draft'].includes(campaign.status)) {
        res.status(400).json({
          success: false,
          message: 'Auto-save only works on draft campaigns',
          requestId,
        });
        return;
      }

      // 🔒 OWNERSHIP GUARD:
      // Only the admin who created it OR any admin can save.
      // (All admins are trusted — no per-admin ownership needed)
      if (campaign.isDeleted) {
        res.status(400).json({
          success: false,
          message: 'Cannot auto-save a deleted campaign',
          requestId,
        });
        return;
      }

      // Apply updates
      if (cleanTitle)       campaign.title       = cleanTitle;
      if (cleanSubject !== undefined) campaign.subject = cleanSubject;
      if (cleanContent)     campaign.content     = cleanContent;
      campaign.template    = templateId as any;
      campaign.segments    = cleanSegments;
      (campaign as any).previewText = cleanPreviewText;
      (campaign as any).fromName    = cleanFromName;
      (campaign as any).fromEmail   = cleanFromEmail;
      (campaign as any).replyTo     = cleanReplyTo;
      // 🆕 Phase 2
      (campaign as any).recipientSource  = cleanRecipientSource;
      (campaign as any).leadFilters      = cleanLeadFilters;
      (campaign as any).mergeTagsEnabled = cleanMergeTagsEnabled;
      (campaign as any).autoSavedAt = now;

      await campaign.save();

      // Lightweight audit — no heavy logging on every 10s auto-save
      // Only log once per minute to avoid audit log spam
      const lastSave = (campaign as any).autoSavedAt as Date | null;
      const shouldLog = !lastSave ||
        (now.getTime() - new Date(lastSave).getTime()) > 60_000;

      if (shouldLog) {
        await logSecurityEvent({
          type:     'admin_action',
          severity: 'low',
          userId:   adminToken.id,
          email:    adminToken.email,
          ip:       clientIP,
          userAgent,
          metadata: {
            context:    'campaign_auto_save',
            action:     'auto_save_updated',
            campaignId: String(campaign._id),
          },
        });
      }

      res.status(200).json({
        success:     true,
        campaignId:  String(campaign._id),
        autoSavedAt: now.toISOString(),
        requestId,
      });
      return;
    }

  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';

    await logSecurityEvent({
      type:     'system_error',
      severity: 'high',
      userId:   adminToken.id,
      email:    adminToken.email,
      ip:       clientIP,
      userAgent,
      metadata: {
        context: 'campaign_auto_save',
        action:  'auto_save_failed',
        error:   errMsg.slice(0, 200),
      },
    });

    // Silent failure — don't interrupt user's editing flow
    res.status(500).json({
      success: false,
      message: 'Auto-save failed — your work is not lost, please save manually',
      requestId,
    });
    return;
  }
}
