// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const requestId = makeRequestId();
  setSecurityHeaders(res, requestId);

  const clientIP = getClientIP(req);
  const userAgent = req.headers['user-agent'] || 'unknown';

  // ─────────────────────────────────────────────
  // STEP 1: METHOD VALIDATION
  // ─────────────────────────────────────────────
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).json({
      success: false,
      message: 'Method not allowed',
      requestId,
    });
  }

  try {
    // ─────────────────────────────────────────────
    // STEP 2: RATE LIMITING
    // ─────────────────────────────────────────────
    const rateLimitResult = await rateLimitApi(req);

    if (!rateLimitResult.ok) {
      await logSecurityEvent({
  type: 'rate_limit_exceeded',
  severity: 'warning',
  ip: clientIP,
  userAgent,
  requestId,
  metadata: {
    context: 'newsletter_verify',
    limit: rateLimitResult.limit,
  },
});

      return res.redirect(`${SITE_URL}/newsletter/error?reason=rate_limit`);
    }

    await dbConnect();

    // ─────────────────────────────────────────────
    // STEP 3: GET & VALIDATE TOKEN
    // ─────────────────────────────────────────────
    const token = req.query.token as string;

    if (!token) {
      await logSecurityEvent({
  type: 'suspicious_activity',
  severity: 'warning',
  ip: clientIP,
  userAgent,
  requestId,
  metadata: {
    context: 'newsletter_verify',
    reason: 'missing_token',
  },
});

      return res.redirect(`${SITE_URL}/newsletter/error?reason=missing_token`);
    }

    // Validate token format (prevent injection)
    if (!isValidTokenFormat(token)) {
      await logSecurityEvent({
  type: 'suspicious_activity',
  severity: 'critical',
  ip: clientIP,
  userAgent,
  requestId,
  metadata: {
    context: 'newsletter_verify',
    reason: 'invalid_token_format',
    tokenLength: token?.length,
  },
});

      return res.redirect(`${SITE_URL}/newsletter/error?reason=invalid_token`);
    }

    // ─────────────────────────────────────────────
    // STEP 4: FIND SUBSCRIBER BY TOKEN
    // ─────────────────────────────────────────────
    const subscriber = await NewsletterSubscriber.findOne({
      verificationToken: token,
    })
      .maxTimeMS(MAX_QUERY_TIME_MS)
      .exec();

    if (!subscriber) {
      await logSecurityEvent({
  type: 'suspicious_activity',
  severity: 'warning',
  ip: clientIP,
  userAgent,
  requestId,
  metadata: {
    context: 'newsletter_verify',
    reason: 'token_not_found',
  },
});

      return res.redirect(`${SITE_URL}/newsletter/error?reason=invalid_token`);
    }

    // ─────────────────────────────────────────────
    // STEP 5: CHECK IF ALREADY VERIFIED
    // ─────────────────────────────────────────────
    if (subscriber.status === 'active') {
  await logSecurityEvent({
    type: 'email_verified',
    severity: 'info',
    email: subscriber.email,
    ip: clientIP,
    userAgent,
    requestId,
    metadata: {
      context: 'newsletter_verify',
      reason: 'already_verified',
      subscriberId: subscriber._id.toString(),
    },
  });

  return res.redirect(`${SITE_URL}/newsletter/verified?already=true`);
}

    // ─────────────────────────────────────────────
    // STEP 6: CHECK TOKEN EXPIRY
    // ─────────────────────────────────────────────
    if (
      subscriber.verificationTokenExpires &&
      new Date() > subscriber.verificationTokenExpires
    ) {
      await logSecurityEvent({
  type: 'suspicious_activity',
  severity: 'info',
  email: subscriber.email,
  ip: clientIP,
  userAgent,
  requestId,
  metadata: {
    context: 'newsletter_verify',
    reason: 'token_expired',
    normalizedEmail: subscriber.normalizedEmail,
  },
});

      return res.redirect(`${SITE_URL}/newsletter/error?reason=expired_token&email=${encodeURIComponent(subscriber.email)}`);
    }

    // ─────────────────────────────────────────────
    // STEP 7: VERIFY SUBSCRIBER
    // ─────────────────────────────────────────────
    subscriber.status = 'active';
    subscriber.verifiedAt = new Date();
    subscriber.subscribedAt = new Date();
    subscriber.verificationToken = undefined;
    subscriber.verificationTokenExpires = undefined;

    await subscriber.save();

    // ─────────────────────────────────────────────
    // STEP 8: SEND WELCOME EMAIL
    // ─────────────────────────────────────────────
    try {
      await sendWelcomeEmail(
        subscriber.email,
        subscriber.name || 'Subscriber',
        subscriber.unsubscribeToken
      );
    } catch (emailError) {
      console.error('Failed to send welcome email:', emailError);
      // Don't fail verification if welcome email fails
    }

    // ─────────────────────────────────────────────
    // STEP 8b: AUTOMATION ENROLLMENT (fire & forget)
    // Enroll new verified subscriber into any active
    // 'subscriber_joined' automation sequences.
    // Non-blocking — verification succeeds regardless.
    // ─────────────────────────────────────────────
    try {
      const { enrollRecipient } = await import('@/lib/automation/enrollRecipient');
      enrollRecipient('subscriber_joined', {
        recipientId:   subscriber._id.toString(),
        recipientType: 'subscriber',
        email:         subscriber.email,
        name:          subscriber.name || '',
        leadSource:    subscriber.source || 'website',
      }).catch((enrollErr: unknown) => {
        console.error('[Automation] subscriber_joined enroll failed:',
          enrollErr instanceof Error ? enrollErr.message : enrollErr
        );
      });
    } catch (importErr) {
      // Dynamic import failed — non-fatal
      console.error('[Automation] Failed to import enrollRecipient:', importErr);
    }

    // ─────────────────────────────────────────────
    // STEP 9: LOG SUCCESS
    // ─────────────────────────────────────────────
    await logSecurityEvent({
  type: 'email_verified',
  severity: 'info',
  email: subscriber.email,
  ip: clientIP,
  userAgent,
  requestId,
  metadata: {
    context: 'newsletter_verify',
    normalizedEmail: subscriber.normalizedEmail,
    subscriberId: subscriber._id.toString(),
  },
});

    // ─────────────────────────────────────────────
    // STEP 10: REDIRECT TO SUCCESS PAGE
    // ─────────────────────────────────────────────
    return res.redirect(`${SITE_URL}/newsletter/verified?success=true`);

  } catch (error: any) {
    console.error('❌ Newsletter verification error:', {
      requestId,
      error: error.message,
    });

    await logSecurityEvent({
  type: 'suspicious_activity',
  severity: 'critical',
  ip: clientIP,
  userAgent,
  requestId,
  metadata: {
    context: 'newsletter_verify',
    reason: 'server_error',
    error: error.message,
  },
});

    return res.redirect(`${SITE_URL}/newsletter/error?reason=server_error`);
  }
}

// pages/api/otp/send.ts
// ═══════════════════════════════════════════════════════════════
// OTP SEND API — Highrise.pk V6.4.5+
// POST /api/otp/send
// ═══════════════════════════════════════════════════════════════
// Sends 6-digit OTP to any email for independent verification.
// Used for: company email, authorized person email, etc.
// ═══════════════════════════════════════════════════════════════
// ✅ requireAuth — must be logged in
// ✅ Rate limit: 3 sends per email per hour
// ✅ OTP hashed with HMAC-SHA256 (never stored plaintext)
// ✅ Disposable email rejected
// ✅ Already-verified short-circuit
// ✅ Branded email via sendTransactionalEmail (Resend → SMTP)
// ✅ 10-minute OTP expiry
// ✅ Strict TypeScript — no any, no console.*
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from "next";
import crypto from "crypto";
import dbConnect from "@/lib/dbConnect";
import { requireAuth } from "@/lib/requireAuth";
import { rateLimitApiWrite } from "@/lib/rateLimit";
import { logSecurityEvent } from "@/lib/security/logSecurityEvent";
import { sendTransactionalEmail } from "@/lib/emailProvider";
import { isValidEmail, isDisposableEmail } from "@/lib/email";
import EmailVerification, {
  type EmailVerificationPurpose,
} from "@/models/EmailVerification";
import { z } from "zod";

// ============================================
// CONSTANTS
// ============================================

const OTP_LENGTH        = 6;
const OTP_EXPIRY_MIN    = 10;
const MAX_SENDS_PER_HOUR = 3;
const RESEND_COOLDOWN_SEC = 60;

const VALID_PURPOSES: EmailVerificationPurpose[] = [
  "company_email",
  "authorized_person_email",
  "agent_email",
  "society_email",
  "general",
];

// ============================================
// TYPES
// ============================================

interface ApiResponse {
  success:          boolean;
  message:          string;
  alreadyVerified?: boolean;
  expiresInMinutes?: number;
  cooldownSeconds?:  number;
  requestId:        string;
}

// ============================================
// ZOD SCHEMA
// ============================================

const SendOtpBodySchema = z.object({
  email:   z.string().trim().toLowerCase().min(5).max(254),
  purpose: z.enum([
    "company_email",
    "authorized_person_email",
    "agent_email",
    "society_email",
    "general",
  ]),
});

