// OTP VERIFY API — Highrise.pk V6.4.5+
// POST /api/otp/verify
// ═══════════════════════════════════════════════════════════════
// Verifies a 6-digit OTP submitted by the user.
// On success: marks email as verified in EmailVerification model.
// ═══════════════════════════════════════════════════════════════
// ✅ requireAuth — must be logged in
// ✅ Constant-time hash comparison (timing attack prevention)
// ✅ Attempt tracking — lockout after 5 wrong attempts
// ✅ Expiry enforcement
// ✅ Single-use — verified record cannot be re-verified
// ✅ Returns remainingAttempts on wrong code
// ✅ Strict TypeScript — no any, no console.*
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from "next";
import crypto from "crypto";
import dbConnect from "@/lib/dbConnect";
import { requireAuth } from "@/lib/requireAuth";
import { rateLimitApiWrite } from "@/lib/rateLimit";
import { logSecurityEvent } from "@/lib/security/logSecurityEvent";
import EmailVerification, {
  type EmailVerificationPurpose,
} from "@/models/EmailVerification";
import { z } from "zod";

// ============================================
// TYPES
// ============================================

interface ApiResponse {
  success:            boolean;
  message:            string;
  verified?:          boolean;
  remainingAttempts?: number;
  requestId:          string;
}

// ============================================
// ZOD SCHEMA
// ============================================

const VerifyOtpBodySchema = z.object({
  email:   z.string().trim().toLowerCase().min(5).max(254),
  purpose: z.enum([
    "company_email",
    "authorized_person_email",
    "agent_email",
    "society_email",
    "general",
  ]),
  code: z
    .string()
    .trim()
    .regex(/^\d{6}$/, "Verification code must be exactly 6 digits"),
});

// ============================================
// HELPERS
// ============================================

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader("X-Request-Id",              requestId);
  res.setHeader("Content-Type",              "application/json; charset=utf-8");
  res.setHeader("X-Content-Type-Options",    "nosniff");
  res.setHeader("X-Frame-Options",           "DENY");
  res.setHeader("Cache-Control",             "no-store, no-cache, must-revalidate, private");
  res.setHeader("Referrer-Policy",           "strict-origin-when-cross-origin");
  res.setHeader("Strict-Transport-Security", "max-age=31536000; includeSubDomains; preload");
}

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers["x-forwarded-for"];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip ?? "").split(",")[0]?.trim() || req.socket?.remoteAddress || "0.0.0.0";
}

/**
 * Hash OTP — must match exactly the same function in send.ts
 */
function hashOtp(email: string, code: string): string {
  const pepper =
    process.env.OTP_PEPPER ??
    process.env.NEXTAUTH_SECRET ??
    "otp_pepper_secure";
  return crypto
    .createHmac("sha256", pepper)
    .update(`highrise:otp:${email.toLowerCase().trim()}:${code}`)
    .digest("hex");
}

/**
 * Constant-time string comparison — prevents timing attacks.
 * Both strings hashed to same length before comparison.
 */
function constantTimeCompare(a: string, b: string): boolean {
  // Ensure both are same length by comparing their SHA-256 hashes
  // This prevents length-based timing leaks
  const ha = crypto.createHash("sha256").update(a).digest();
  const hb = crypto.createHash("sha256").update(b).digest();
  try {
    return crypto.timingSafeEqual(ha, hb);
  } catch {
    return false;
  }
}

// ============================================
// MAIN HANDLER
// ============================================

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
): Promise<void> {
  const requestId = crypto.randomUUID();
  setSecurityHeaders(res, requestId);

  // ── Method guard ──────────────────────────────────────────
  if (req.method !== "POST") {
    res.setHeader("Allow", ["POST"]);
    return void res.status(405).json({
      success: false,
      message: "Method not allowed",
      requestId,
    });
  }

  const ip = getClientIp(req);
  const ua = String(req.headers["user-agent"] ?? "").slice(0, 200);

  // ── Rate limit ────────────────────────────────────────────
  // Stricter than send — prevents brute force on OTP
  const rl = await rateLimitApiWrite(req);
  if (!rl.ok) {
    res.setHeader("Retry-After", String(rl.retryAfter ?? 60));
    return void res.status(429).json({
      success: false,
      message: "Too many requests. Please try again later.",
      requestId,
    });
  }

  // ── Auth ──────────────────────────────────────────────────
  const auth = await requireAuth(req, res);
  if (!auth) return;

  // ── DB ────────────────────────────────────────────────────
  await dbConnect();

  // ── Validate body ─────────────────────────────────────────
  const bodyResult = VerifyOtpBodySchema.safeParse(req.body ?? {});
  if (!bodyResult.success) {
    return void res.status(400).json({
      success: false,
      message: bodyResult.error.issues[0]?.message ?? "Invalid request body.",
      requestId,
    });
  }

  const { email, purpose, code } = bodyResult.data;

  try {
    // ── Check if already verified ───────────────────────────
    // Short-circuit — idempotent response
    const alreadyVerified = await EmailVerification.isVerified(email, purpose);
    if (alreadyVerified) {
      return void res.status(200).json({
        success:  true,
        message:  "Email is already verified.",
        verified: true,
        requestId,
      });
    }

    // ── Find pending record ─────────────────────────────────
    // findPending() includes select:false otpHash field
    const record = await EmailVerification.findPending(email, purpose);

    if (!record) {
      logSecurityEvent({
        type:      "admin_action",
        severity:  "low",
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:  "otp_verify_no_record",
          email,
          purpose,
          requestId,
        },
      });

      return void res.status(400).json({
        success: false,
        message: "No verification code found for this email. Please request a new code.",
        requestId,
      });
    }

    // ── Check expiry ─────────────────────────────────────────
    if (new Date(record.expiresAt).getTime() < Date.now()) {
      // Delete expired record
      await EmailVerification.deleteOne({ _id: record._id });

      return void res.status(400).json({
        success: false,
        message: "Verification code has expired. Please request a new code.",
        requestId,
      });
    }

    // ── Check max attempts ───────────────────────────────────
    if (record.attempts >= record.maxAttempts) {
      // Delete locked record — force new OTP request
      await EmailVerification.deleteOne({ _id: record._id });

      logSecurityEvent({
        type:      "admin_action",
        severity:  "medium",
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:   "otp_max_attempts_exceeded",
          email,
          purpose,
          attempts: record.attempts,
          requestId,
        },
      });

      return void res.status(400).json({
        success: false,
        message: "Too many incorrect attempts. Please request a new verification code.",
        requestId,
      });
    }

    // ── Compute hash of submitted code ───────────────────────
    const submittedHash = hashOtp(email, code);
    const storedHash    = record.otpHash;

    // ── Constant-time comparison ─────────────────────────────
    const isMatch = constantTimeCompare(submittedHash, storedHash);

    if (!isMatch) {
      // Increment attempts
      const newAttempts = record.attempts + 1;
      const remaining   = record.maxAttempts - newAttempts;

      await EmailVerification.updateOne(
        { _id: record._id },
        {
          $inc: { attempts: 1 },
          $set: { updatedAt: new Date() },
        }
      );

      // If last attempt used → delete (force new OTP)
      if (remaining <= 0) {
        await EmailVerification.deleteOne({ _id: record._id });

        logSecurityEvent({
          type:      "admin_action",
          severity:  "medium",
          userId:    auth.id,
          ip,
          userAgent: ua,
          metadata:  {
            action:  "otp_max_attempts_reached",
            email,
            purpose,
            requestId,
          },
        });

        return void res.status(400).json({
          success:            false,
          message:            "Too many incorrect attempts. Please request a new verification code.",
          remainingAttempts:  0,
          requestId,
        });
      }

      logSecurityEvent({
        type:      "admin_action",
        severity:  "low",
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:    "otp_wrong_code",
          email,
          purpose,
          attempts:  newAttempts,
          remaining,
          requestId,
        },
      });

      return void res.status(400).json({
        success:           false,
        message:           remaining === 1
          ? "Incorrect code. 1 attempt remaining before lockout."
          : `Incorrect code. ${remaining} attempts remaining.`,
        remainingAttempts: remaining,
        requestId,
      });
    }

    // ── ✅ CODE MATCHES — Mark as verified ───────────────────
    await EmailVerification.updateOne(
      { _id: record._id },
      {
        $set: {
          verified:   true,
          verifiedAt: new Date(),
          // Clear sensitive hash after successful verification
          // (Cannot clear select:false field this way — it stays but is
          //  never returned by normal queries anyway)
          updatedAt:  new Date(),
        },
      }
    );

    // ── Log success ──────────────────────────────────────────
    logSecurityEvent({
      type:      "admin_action",
      severity:  "low",
      userId:    auth.id,
      ip,
      userAgent: ua,
      metadata:  {
        action:  "otp_verified",
        email,
        purpose,
        requestId,
      },
    });

    return void res.status(200).json({
      success:  true,
      message:  "Email verified successfully! ✅",
      verified: true,
      requestId,
    });

  } catch (err: unknown) {
    logSecurityEvent({
      type:      "admin_action",
      severity:  "high",
      userId:    auth.id,
      ip,
      userAgent: ua,
      metadata:  {
        action:  "otp_verify_error",
        email,
        purpose,
        error:   err instanceof Error ? err.message : "Unknown",
        requestId,
      },
    });

    return void res.status(500).json({
      success: false,
      message: "An error occurred. Please try again.",
      requestId,
    });
  }
}

// pages/api/owner/leads.ts
// GET   → leads for owner's properties
// PATCH → update lead status/priority

import type { NextApiRequest, NextApiResponse } from "next";
import { getServerSession } from "next-auth/next";
import { authOptions }      from "@/pages/api/auth/[...nextauth]";
import dbConnect            from "@/lib/dbConnect";
import Property             from "@/models/Property";
import { rateLimitApi, sendRateLimitResponse }        from "@/lib/rateLimit";
import mongoose             from "mongoose";

interface SessionUser {
  id:                        string;
  role:                      string;
  isVerifiedOwner?:          boolean;
  ownerVerificationStatus?:  string;
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse,
): Promise<void> {
  const rl = await rateLimitApi(req);
  if (!rl.ok) {
    sendRateLimitResponse(res, rl);
    return;
  }

  const session = await getServerSession(req, res, authOptions);
  const user    = session?.user as SessionUser | undefined;

  if (!user?.id) {
    res.status(401).json({ error: "Authentication required" });
    return;
  }
  if (user.role !== "admin" && !user.isVerifiedOwner) {
    res.status(403).json({
      error: "Verified owner access required. Please complete owner verification.",
      code:  "OWNER_NOT_VERIFIED",
    });
    return;
  }

  try {
    await dbConnect();

    // ── GET ────────────────────────────────────────────────────────────────
    if (req.method === "GET") {
      // Get owner's property IDs first
      const ownerPropertyIds = await Property.find({
        owner:     user.id,
        isDeleted: false,
      })
        .select("_id")
        .lean<{ _id: mongoose.Types.ObjectId }[]>();

      const propertyIds = ownerPropertyIds.map((p) => p._id);

      // Try to fetch from Lead/Inquiry model
      // Graceful degradation if model doesn't exist yet
      try {
        // Dynamic import to avoid crash if model missing
        const Lead = mongoose.models["Lead"] ??
          mongoose.models["Inquiry"] ??
          null;

        if (!Lead) {
          // Lead model not yet built — return empty with 200
          res.status(200).json({
            success:    true,
            data:       [],
            stats:      { all: 0, new: 0, contacted: 0, qualified: 0, won: 0, conversionRate: 0 },
            pagination: { page: 1, limit: 12, total: 0, totalPages: 0 },
            _info:      "Lead model not yet available. Check back after Session 4.",
          });
          return;
        }

        const {
          page     = "1",
          limit    = "12",
          status   = "all",
          priority = "all",
          search   = "",
        } = req.query as Record<string, string>;

        const pageNum  = Math.max(1, parseInt(page, 10));
        const limitNum = Math.min(50, Math.max(1, parseInt(limit, 10)));
        const skip     = (pageNum - 1) * limitNum;

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const query: Record<string, any> = {
          "propertySnapshot._id": { $in: propertyIds },
          isArchived: false,
        };

        if (status !== "all")   query["status"]   = status;
        if (priority !== "all") query["priority"]  = priority;
        if (search?.trim()) {
          const rx = new RegExp(search.trim(), "i");
          query["$or"] = [
            { name:    rx },
            { phone:   rx },
            { email:   rx },
          ];
        }

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const [leads, total, statsAgg] = await Promise.all([
          (Lead as mongoose.Model<any>).find(query).sort({ createdAt: -1 }).skip(skip).limit(limitNum).lean(),
          (Lead as mongoose.Model<any>).countDocuments(query),
          (Lead as mongoose.Model<any>).aggregate([
            { $match: { "propertySnapshot._id": { $in: propertyIds }, isArchived: false } },
            { $group: { _id: "$status", count: { $sum: 1 } } },
          ]),
        ]);

        type StatItem = { _id: string; count: number };
        const sMap = (statsAgg as StatItem[]).reduce<Record<string,number>>(
          (acc, s) => ({ ...acc, [s._id]: s.count }),
          {}
        );

        const allCount = total;
        const wonCount = sMap["won"] ?? 0;

        res.status(200).json({
          success: true,
          data:    leads,
          stats:   {
            all:            allCount,
            new:            sMap["new"]       ?? 0,
            contacted:      sMap["contacted"] ?? 0,
            qualified:      sMap["qualified"] ?? 0,
            won:            wonCount,
            conversionRate: allCount > 0
              ? Math.round((wonCount / allCount) * 100)
              : 0,
          },
          pagination: {
            page:       pageNum,
            limit:      limitNum,
            total,
            totalPages: Math.ceil(total / limitNum),
          },
        });
      } catch {
        // Any error — return empty gracefully
        res.status(200).json({
          success:    true,
          data:       [],
          stats:      { all: 0, new: 0, contacted: 0, qualified: 0, won: 0, conversionRate: 0 },
          pagination: { page: 1, limit: 12, total: 0, totalPages: 0 },
        });
      }
      return;
    }

    // ── PATCH (update lead status/priority) ────────────────────────────────
    if (req.method === "PATCH") {
      const { leadId } = req.query;

      if (!leadId || typeof leadId !== "string" || !mongoose.isValidObjectId(leadId)) {
        res.status(400).json({ error: "Valid lead ID required" });
        return;
      }

      const Lead = mongoose.models["Lead"] ?? mongoose.models["Inquiry"] ?? null;

      if (!Lead) {
        res.status(404).json({ error: "Lead system not yet available" });
        return;
      }

      const { status, priority } = req.body as Record<string, string>;

      const update: Record<string, string> = {};
      if (status)   update["status"]   = status;
      if (priority) update["priority"] = priority;

      if (Object.keys(update).length === 0) {
        res.status(400).json({ error: "No fields to update" });
        return;
      }

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const lead = await (Lead as mongoose.Model<any>).findOneAndUpdate(
        {
          _id:                    leadId,
          "propertySnapshot._id": { $in: await Property.find({ owner: user.id }).distinct("_id") },
        },
        { $set: update },
        { new: true }
      ).lean();

      if (!lead) {
        res.status(404).json({ error: "Lead not found or access denied" });
        return;
      }

      res.status(200).json({ success: true, lead });
      return;
    }

    res.status(405).json({ error: "Method not allowed" });
  } catch (err) {
    const msg = err instanceof Error ? err.message : "Internal server error";
    res.status(500).json({ error: msg });
  }
}

/**
 * pages/api/projects/[id]/index.ts
 * 
 * GET   /api/projects/[id]  → Public project detail (by ObjectId OR slug)
 * PATCH /api/projects/[id]  → Developer content update (owner or admin)
 * PUT   /api/projects/[id]  → 410 Gone (use PATCH)
 * DELETE /api/projects/[id] → 410 Gone (use /trash endpoint)
 * 
 * V5.0.0 — Aligned with Projects.ts model, Unit.ts, requireAuth guards,
 *           Upstash rate limiting, logSecurityEvent, findOne()+save() pattern
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import { z } from 'zod';

import dbConnect from '@/lib/dbConnect';
import Project from '@/models/Projects';
import Unit from '@/models/Unit';
import DeveloperProfile from '@/models/DeveloperProfile';

import {
  requireAuth,
  getClientIp,
} from '@/lib/requireAuth';

import {
  rateLimitApi,
  rateLimitDeveloper,
  setRateLimitHeaders,
  sendRateLimitResponse,
} from '@/lib/rateLimit';

import { logSecurityEvent } from '@/lib/security/logSecurityEvent';
import { getOptionalAuth } from '@/lib/optionalAuth';

import {
  syncUnitTypeBreakdown,
  denormalizeProjectToUnits,
} from '@/lib/units/syncUnitTypeBreakdown';

// ─────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────

type ApiResponse<T = unknown> = {
  success: boolean;
  message?: string;
  code?: string;
  project?: T;
  errors?: Record<string, string[]>;
};

// ─────────────────────────────────────────────
// Zod v4 — PATCH validation schema
// ─────────────────────────────────────────────

const PatchProjectSchema = z.object({
  // Identity
  projectName:      z.string().min(3).max(120).optional(),
  tagline:          z.string().max(200).optional(),
  shortDescription: z.string().max(500).optional(),
  description:      z.string().max(10000).optional(),

  // Category & nature
  projectCategory: z.enum([
    'highrise', 'society', 'mixed_use',
    'commercial_plaza', 'townhouse', 'gated_community',
  ]).optional(),
  projectNature: z.enum(['residential', 'commercial', 'mixed']).optional(),

  // Location
  city:             z.string().max(80).optional(),
  area:             z.string().max(120).optional(),
  specificLocation: z.string().max(200).optional(),
  googleMapLink:    z.string().url().optional().or(z.literal('')),
  coordinates: z.object({
    lat: z.number().min(-90).max(90),
    lng: z.number().min(-180).max(180),
  }).optional(),

  // Pricing
  minPrice: z.number().min(0).optional(),
  maxPrice: z.number().min(0).optional(),
  priceRangeText: z.string().max(100).optional(),

  // Timeline
  launchDate:             z.string().optional(),
  expectedCompletionDate: z.string().optional(),
  possessionStartDate:    z.string().optional(),
  developmentProgress:    z.number().min(0).max(100).optional(),

  // Units summary (manual override before sync)
  totalUnits:      z.number().int().min(0).optional(),

  // Media
  featureImageUrl: z.string().url().optional(),
  images: z.array(z.object({
    url:       z.string().url(),
    isPrimary: z.boolean().optional(),
    caption:   z.string().max(200).optional(),
  })).max(30).optional(),

  // Legal
  legalDocs: z.array(z.object({
    title: z.string().max(100),
    url:   z.string().url(),
    type:  z.string().max(50).optional(),
  })).max(10).optional(),

  // Installment plan
  installmentPlan: z.object({
    available:          z.boolean().optional(),
    downPaymentPercent: z.number().min(0).max(100).optional(),
    monthlyInstallment: z.number().min(0).optional(),
    installmentMonths:  z.number().int().min(0).optional(),
    handoverPercent:    z.number().min(0).max(100).optional(),
  }).optional(),

  // Submit for review (draft → pending)
  submitForReview: z.boolean().optional(),
}).strict();

type PatchBody = z.infer<typeof PatchProjectSchema>;

// ─────────────────────────────────────────────
// Security headers
// ─────────────────────────────────────────────

function setSecurityHeaders(res: NextApiResponse): void {
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=86400; includeSubDomains');
  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
}

// ─────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────

function normalizeId(id: string | string[] | undefined): string {
  if (Array.isArray(id)) return String(id[0] ?? '').trim();
  return String(id ?? '').trim();
}

function isValidObjectId(id: string): boolean {
  return mongoose.Types.ObjectId.isValid(id) && /^[a-fA-F0-9]{24}$/.test(id);
}

/**
 * Resolve project by ObjectId OR slug.
 * Returns the Mongoose document (not lean) for save() pattern.
 */
async function resolveProject(identifier: string, includeDeleted = false) {
  const filter: Record<string, unknown> = includeDeleted
    ? {}
    : { isDeleted: { $ne: true } };

  if (isValidObjectId(identifier)) {
    const byId = await Project.findOne({ _id: identifier, ...filter })
      .maxTimeMS(3000);
    if (byId) return byId;
  }

  return Project.findOne({ slug: identifier, ...filter }).maxTimeMS(3000);
}

/**
 * Check if a project is publicly visible.
 * V5.0.0 status enum: draft | pending | verified | rejected
 */
function isPubliclyVisible(project: InstanceType<typeof Project>): boolean {
  return project.isVerified === true || project.status === 'verified';
}

/**
 * Primary image: featureImageUrl → first isPrimary image → first image.
 */
function getPrimaryImage(project: InstanceType<typeof Project>): string | null {
  const p = project as unknown as {
    featureImageUrl?: string;
    images?: Array<{ url: string; isPrimary?: boolean }>;
  };
  if (p.featureImageUrl) return p.featureImageUrl;
  if (Array.isArray(p.images) && p.images.length > 0) {
    const primary = p.images.find((img) => img.isPrimary);
    return primary?.url ?? p.images[0]?.url ?? null;
  }
  return null;
}

/**
 * Strip developer contact details from profile for public responses.
 * Managed marketplace: Highrise is the first point of contact.
 */
function sanitizeDevProfileForPublic(
  profile: Record<string, unknown> | null | undefined,
): Record<string, unknown> | null {
  if (!profile || typeof profile !== 'object') return null;
  const safe = { ...profile };
  // Never expose contact channels publicly — Highrise team is first contact
  delete safe.contactNumber;
  delete safe.whatsappNumber;
  delete safe.officialEmail;
  delete safe.ceoPhone;
  return safe;
}

/**
 * Format price in Pakistani convention: Crore / Lac / Thousand
 */
function formatPKR(amount: number): string {
  if (amount >= 10_000_000) return `${(amount / 10_000_000).toFixed(2)} Crore`;
  if (amount >= 100_000)    return `${(amount / 100_000).toFixed(2)} Lac`;
  if (amount >= 1_000)      return `${(amount / 1_000).toFixed(1)}K`;
  return String(amount);
}

// ─────────────────────────────────────────────
// Main handler
// ─────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
): Promise<void> {
  setSecurityHeaders(res);

  const method = (req.method ?? 'GET').toUpperCase();

  // ── Deprecated methods ──────────────────────
  if (method === 'PUT') {
    res.setHeader('Allow', ['GET', 'PATCH']);
    return void res.status(410).json({
      success: false,
      message: 'PUT is deprecated. Use PATCH for partial updates.',
      code: 'METHOD_DEPRECATED',
    });
  }

  if (method === 'DELETE') {
    res.setHeader('Allow', ['GET', 'PATCH']);
    return void res.status(410).json({
      success: false,
      message: 'DELETE via this endpoint is deprecated. Use POST /api/projects/[id]/trash',
      code: 'METHOD_DEPRECATED',
    });
  }

  if (method !== 'GET' && method !== 'PATCH') {
    res.setHeader('Allow', ['GET', 'PATCH']);
    return void res.status(405).json({
      success: false,
      message: 'Method not allowed',
      code: 'METHOD_NOT_ALLOWED',
    });
  }

  // ── Rate limit ──────────────────────────────
  const rl = await (method === 'PATCH'
    ? rateLimitDeveloper(req)
    : rateLimitApi(req));

  setRateLimitHeaders(res, rl);

  if (!rl.ok) {
    return void sendRateLimitResponse(res, rl);
  }

  // ── Resolve identifier ──────────────────────
  const idOrSlug = normalizeId(req.query.id as string | string[] | undefined);
  if (!idOrSlug) {
    return void res.status(400).json({
      success: false,
      message: 'Project ID or slug is required.',
      code: 'MISSING_IDENTIFIER',
    });
  }

  await dbConnect();

  if (method === 'GET')   return void handleGet(req, res, idOrSlug);
  if (method === 'PATCH') return void handlePatch(req, res, idOrSlug);
}

// ─────────────────────────────────────────────
// GET — Public project detail
// ─────────────────────────────────────────────

async function handleGet(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
  idOrSlug: string,
): Promise<void> {
  // Optional auth — non-blocking (preview for owner/admin)
  const optionalAuth = await getOptionalAuth(req);
  const viewerId   = optionalAuth?.id ?? null;
  const viewerRole = optionalAuth?.role ?? 'user';
  const isAdmin    = viewerRole === 'admin';

  // Resolve without deleted docs for public GET
  const project = await resolveProject(idOrSlug, false);

  if (!project) {
    // Anti-enumeration: always 404, never 403
    return void res.status(404).json({
      success: false,
      message: 'Project not found.',
      code: 'NOT_FOUND',
    });
  }

  // Project.developerId is the canonical authenticated User reference.
  const projectDeveloperStr = String(
    (project as unknown as { developerId: mongoose.Types.ObjectId }).developerId ?? '',
  );
  const isOwner = viewerId ? projectDeveloperStr === viewerId : false;

  const publicAllowed = isPubliclyVisible(project);

  // Gate non-public to owner/admin only (anti-enumeration 404)
  if (!publicAllowed && !isAdmin && !isOwner) {
    return void res.status(404).json({
      success: false,
      message: 'Project not found.',
      code: 'NOT_FOUND',
    });
  }

  // Increment view count (fire-and-forget for public, not owner/admin)
  if (publicAllowed && !isAdmin && !isOwner) {
    Project.updateOne(
      { _id: project._id },
      { $inc: { views: 1 } },
    ).exec().catch(() => undefined);

    res.setHeader('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');
  } else {
    res.setHeader('Cache-Control', 'no-store, max-age=0');
  }

  // Get developer profile (for badge + company name)
  const developerProfile = await DeveloperProfile.findOne({
    user: project.developerId,
  })
    .select(
      isAdmin || isOwner
        ? 'companyName logo establishedYear verificationLevel completedProjectsCount ceoName email socialLinks'
        : 'companyName logo establishedYear verificationLevel completedProjectsCount',
    )
    .lean();

  // Unit counts for public summary
  const unitCounts = await Unit.aggregate([
    {
      $match: {
        projectId: project._id,
        isDeleted: { $ne: true },
        ...(isAdmin || isOwner ? {} : { isPublished: true }),
      },
    },
    {
      $group: {
        _id: '$status',
        count: { $sum: 1 },
      },
    },
  ]);

  const unitCountMap: Record<string, number> = {};
  for (const row of unitCounts) {
    unitCountMap[String(row._id)] = Number(row.count);
  }

  // Badge metadata
  const badgeLabels: Record<string, string> = {
    new_entrant: 'New Entrant',
    emerging:    'Emerging Developer',
    trusted:     'Trusted Builder',
    premium:     'Premium Developer',
  };
  const badgeEmojis: Record<string, string> = {
    new_entrant: '🆕',
    emerging:    '⭐',
    trusted:     '🏆',
    premium:     '💎',
  };

  const proj = project as unknown as Record<string, unknown> & {
    developerBadge?: string;
    minPrice?: number;
    maxPrice?: number;
  };

  const badge = String(proj.developerBadge ?? 'new_entrant');

  // Price formatting
  const priceFormatted = {
    min: proj.minPrice ? formatPKR(Number(proj.minPrice)) : null,
    max: proj.maxPrice ? formatPKR(Number(proj.maxPrice)) : null,
  };

  // Sanitize developer profile for public
  const safeDevProfile = isAdmin || isOwner
    ? developerProfile
    : sanitizeDevProfileForPublic(
        developerProfile as Record<string, unknown> | null,
      );

  // Owner/admin get extra fields
  const adminFields: Record<string, unknown> = {};
  if (isAdmin || isOwner) {
    const adminProj = project as unknown as Record<string, unknown>;
    adminFields.rejectionReason = adminProj.rejectionReason ?? null;
    adminFields.verifiedBy      = adminProj.verifiedBy ?? null;
    adminFields.verifiedAt      = adminProj.verifiedAt ?? null;
    adminFields.badgeNotes      = adminProj.badgeNotes ?? null;
  }

  const projectObject = project.toObject() as Record<string, unknown>;
  if (!isAdmin && !isOwner) {
    delete projectObject.developerId;
    delete projectObject.verifiedBy;
    delete projectObject.rejectionReason;
    delete projectObject.badgeNotes;
    delete projectObject.legalDocs;
  }

  return void res.status(200).json({
    success: true,
    project: {
      ...projectObject,
      developerProfile:  safeDevProfile,
      primaryImage:      getPrimaryImage(project),
      badge,
      badgeLabel:        badgeLabels[badge] ?? badge,
      badgeEmoji:        badgeEmojis[badge] ?? '',
      priceFormatted,
      unitLiveCounts:    unitCountMap,
      // UI hint: contact goes through Highrise (managed marketplace)
      contactViaHighrise: true,
      ...adminFields,
    },
  });
}

// ─────────────────────────────────────────────
// PATCH — Developer content update
// ─────────────────────────────────────────────

async function handlePatch(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
  idOrSlug: string,
): Promise<void> {
  res.setHeader('Cache-Control', 'no-store, max-age=0');

  // ── Auth: must be logged in ─────────────────
  const authResult = await requireAuth(req, res);
  if (!authResult) return;

  const userId  = authResult.id;
  const role    = authResult.role;
  const ip      = getClientIp(req);
  const isAdmin = role === 'admin';
  const isDev   = role === 'developer';

  // Only developer or admin can PATCH projects
  if (!isAdmin && !isDev) {
    return void res.status(403).json({
      success: false,
      message: 'Only developers or admins can update projects.',
      code: 'FORBIDDEN',
    });
  }

  // ── Resolve project ─────────────────────────
  const project = await resolveProject(idOrSlug, true);

  if (!project) {
    return void res.status(404).json({
      success: false,
      message: 'Project not found.',
      code: 'NOT_FOUND',
    });
  }

  // ── Ownership check ─────────────────────────
  const projectDeveloperStr = String(
    (project as unknown as { developerId: mongoose.Types.ObjectId }).developerId ?? '',
  );

  // Anti-enumeration: non-owners get 404 not 403
  if (!isAdmin && projectDeveloperStr !== userId) {
    return void res.status(404).json({
      success: false,
      message: 'Project not found.',
      code: 'NOT_FOUND',
    });
  }

  // ── Block updates on deleted projects (non-admin) ──
  const proj = project as unknown as { isDeleted?: boolean };
  if (proj.isDeleted && !isAdmin) {
    return void res.status(410).json({
      success: false,
      message: 'This project has been deleted and cannot be updated.',
      code: 'PROJECT_DELETED',
    });
  }

  // ── Developer profile check ─────────────────
  // Developer must have an approved profile to update projects
  if (isDev) {
    const devProfile = await DeveloperProfile.findOne({ user: userId })
      .select('status')
      .lean();

    if (!devProfile || devProfile.status !== 'approved') {
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'medium',
        userId,
        ip,
        metadata: {
          action:   'project_patch_blocked',
          reason:   'developer_profile_not_approved',
          projectId: String(project._id),
        },
        req,
      });

      return void res.status(403).json({
        success: false,
        message: 'Your developer profile must be approved before updating projects.',
        code: 'PROFILE_NOT_APPROVED',
      });
    }
  }

  // ── Parse + validate body ───────────────────
  let body: unknown;
  try {
    body = typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
  } catch {
    return void res.status(400).json({
      success: false,
      message: 'Invalid JSON body.',
      code: 'INVALID_JSON',
    });
  }

  const parsed = PatchProjectSchema.safeParse(body);
  if (!parsed.success) {
    return void res.status(422).json({
      success: false,
      message:  'Validation failed.',
      code:     'VALIDATION_ERROR',
      errors:   parsed.error.flatten().fieldErrors as Record<string, string[]>,
    });
  }

  const data: PatchBody = parsed.data;

  // ── Status transition: submitForReview ──────
  // Developer can move draft → pending by setting submitForReview: true
  // Admin content edits do NOT change status
  const currentStatus = String(
    (project as unknown as { status: string }).status ?? 'draft',
  );

  const allowedStatusTransitions: Record<string, string[]> = {
    draft:    ['pending'],
    rejected: ['pending'], // re-submit after rejection
  };

  let newStatus: string | undefined;

  if (data.submitForReview === true && !isAdmin) {
    const allowed = allowedStatusTransitions[currentStatus] ?? [];
    if (allowed.includes('pending')) {
      newStatus = 'pending';
    } else {
      return void res.status(409).json({
        success: false,
        message: `Cannot submit for review. Current status is '${currentStatus}'.`,
        code: 'INVALID_STATUS_TRANSITION',
      });
    }
  }

  // ── Apply changes via findOne() + save() ────
  // ARCH RULE: never findByIdAndUpdate for mutations

  const { submitForReview: _omit, ...updateFields } = data;

  // Apply each validated field to the document
  for (const [key, value] of Object.entries(updateFields)) {
    if (value !== undefined) {
      (project as unknown as Record<string, unknown>)[key] = value;
    }
  }

  // Apply status transition if applicable
  if (newStatus) {
    (project as unknown as Record<string, unknown>).status = newStatus;
  }

  // Track who last edited (non-admin edits are developer; admin edits noted)
  (project as unknown as Record<string, unknown>).updatedAt = new Date();

  await project.save();

  // ── Post-save sync ──────────────────────────
  // If location/slug/badge changed, push to all child units
  const locationChanged = (
    'city' in updateFields ||
    'area' in updateFields ||
    'projectName' in updateFields
  );

  if (locationChanged) {
    await denormalizeProjectToUnits(String(project._id)).catch(() => undefined);
  }

  // Recalculate unitTypeBreakdown after any project update
  await syncUnitTypeBreakdown(String(project._id)).catch(() => undefined);

  // ── Audit log ───────────────────────────────
  await logSecurityEvent({
    type:     'admin_action',
    severity: 'low',
    userId,
    ip,
    metadata: {
      action:        'project_updated',
      projectId:     String(project._id),
      projectSlug:   String((project as unknown as { slug: string }).slug ?? ''),
      updatedFields: Object.keys(updateFields),
      newStatus:     newStatus ?? currentStatus,
      byRole:        role,
    },
    req,
  });

  // ── Response ────────────────────────────────
  return void res.status(200).json({
    success: true,
    message: newStatus === 'pending'
      ? 'Project submitted for review. Our team will verify it shortly.'
      : 'Project updated successfully.',
    project: {
      _id:       String(project._id),
      slug:      String((project as unknown as { slug: string }).slug ?? ''),
      status:    String((project as unknown as { status: string }).status ?? ''),
      updatedAt: new Date().toISOString(),
    },
  });
}

// pages/api/projects/[id]/payment-plans.ts
import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';
import dbConnect from '@/lib/dbConnect';
import { requireAuth } from '@/lib/requireAuth';
import { getOptionalAuth } from '@/lib/optionalAuth';
import {
  rateLimitApi,
  rateLimitDeveloper,
  sendRateLimitResponse,
  setRateLimitHeaders,
} from '@/lib/rateLimit';
import { logSecurityEvent } from '@/lib/security/logSecurityEvent';
import { z } from 'zod';

// ════════════════════════════════════════════════════
// ZOD SCHEMAS
// ════════════════════════════════════════════════════

const InstallmentBreakdownSchema = z.object({
  label:      z.string().min(1).max(100),
  amount:     z.number().min(0),
  percentage: z.number().min(0).max(100).optional(),
  dueDate:    z.string().max(60).optional(),
  dueAfter:   z.string().max(60).optional(),
  frequency:  z.enum([
    'one_time', 'monthly', 'quarterly',
    'half_yearly', 'yearly', 'on_possession',
  ]).optional(),
  count:      z.number().min(0).max(600).optional(),
  notes:      z.string().max(300).optional(),
});

const PaymentPlanSchema = z.object({
  // Identity
  name:           z.string().min(1).max(200),
  description:    z.string().max(1000).optional(),
  planType:       z.enum([
    'standard', 'easy_installment', 'flexi',
    'down_payment', 'full_payment', 'custom',
  ]),

  // Applicability
  applicableTo:   z.enum([
    'all_units', 'residential', 'commercial',
    'specific_types',
  ]).optional().default('all_units'),
  unitTypes:      z.array(z.string().max(80)).max(20).optional(),

  // Pricing reference
  totalPrice:     z.number().min(0).optional(),
  currency:       z.string().max(10).optional().default('PKR'),

  // Booking & down payment
  bookingAmount:       z.number().min(0).optional(),
  bookingPercent:      z.number().min(0).max(100).optional(),
  downPayment:         z.number().min(0).optional(),
  downPaymentPercent:  z.number().min(0).max(100).optional(),
  downPaymentDueIn:    z.string().max(60).optional(),

  // Installment breakdown
  installments:   z.array(InstallmentBreakdownSchema).max(30).optional(),

  // Possession
  possessionAmount:    z.number().min(0).optional(),
  possessionPercent:   z.number().min(0).max(100).optional(),

  // Plan duration
  planDuration:        z.number().min(0).max(600).optional(),
  planDurationUnit:    z.enum(['months', 'years']).optional(),

  // Discounts
  earlyPaymentDiscount:  z.number().min(0).max(100).optional(),
  fullPaymentDiscount:   z.number().min(0).max(100).optional(),
  bulkBookingDiscount:   z.number().min(0).max(100).optional(),

  // Validity
  validFrom:    z.string().datetime().optional(),
  validUntil:   z.string().datetime().optional(),
  isActive:     z.boolean().optional().default(true),

  // Display
  isDefault:    z.boolean().optional().default(false),
  isFeatured:   z.boolean().optional().default(false),
  order:        z.number().min(0).max(10000).optional(),

  // Legal
  termsAndConditions: z.string().max(5000).optional(),
  disclaimers:        z.string().max(2000).optional(),
});

const UpdatePaymentPlanSchema = PaymentPlanSchema.partial().extend({
  planId: z.string().min(24).max(24),
});

const DeletePaymentPlanSchema = z.object({
  planId: z.string().min(24).max(24),
});

// ════════════════════════════════════════════════════
// HELPERS
// ════════════════════════════════════════════════════

async function verifyProjectOwnership(
  projectId: string,
  authId:    string,
  role:      string
): Promise<{
  ok:      boolean;
  project: Record<string, unknown> | null;
  error?:  string;
  status?: number;
}> {
  const Project = mongoose.models.Project as
    mongoose.Model<mongoose.Document>;

  if (!Project) {
    return { ok: false, project: null, error: 'Something went wrong', status: 500 };
  }

  const projectQuery: Record<string, unknown> = {
    _id:       new mongoose.Types.ObjectId(projectId),
    isDeleted: { $ne: true },
  };

  if (role === 'developer') {
    // Project.developerId is the authenticated User _id across the canonical
    // project creation/dashboard APIs (Project schema ref: User).
    projectQuery.developerId = new mongoose.Types.ObjectId(authId);
  }

  const project = await Project.findOne(projectQuery)
    .select('_id developerId paymentPlans')
    .lean() as Record<string, unknown> | null;

  if (!project) {
    return {
      ok:     false,
      project: null,
      error:  'Project not found or you do not have permission',
      status: 404,
    };
  }

  return { ok: true, project };
}

/**
 * Format price in Pakistani style (Lac/Crore).
 */
function formatPKR(amount: number): string {
  if (!amount || amount <= 0) return 'N/A';
  if (amount >= 10_000_000) {
    const crore = amount / 10_000_000;
    return `PKR ${crore % 1 === 0 ? crore.toFixed(0) : crore.toFixed(2)} Crore`;
  }
  if (amount >= 100_000) {
    const lac = amount / 100_000;
    return `PKR ${lac % 1 === 0 ? lac.toFixed(0) : lac.toFixed(2)} Lac`;
  }
  return `PKR ${amount.toLocaleString()}`;
}

/**
 * Validate installment breakdown sums up correctly.
 */
function validateBreakdownSum(
  plan: z.infer<typeof PaymentPlanSchema>
): string | null {
  if (!plan.totalPrice || plan.totalPrice <= 0) return null;
  if (!plan.installments || plan.installments.length === 0) return null;

  const booking     = plan.bookingAmount ?? 0;
  const downPayment = plan.downPayment ?? 0;
  const possession  = plan.possessionAmount ?? 0;

  let installmentTotal = 0;
  for (const inst of plan.installments) {
    if (inst.count && inst.count > 0) {
      installmentTotal += inst.amount * inst.count;
    } else {
      installmentTotal += inst.amount;
    }
  }

  const grandTotal = booking + downPayment + installmentTotal + possession;
  const diff       = Math.abs(grandTotal - plan.totalPrice);
  const tolerance  = plan.totalPrice * 0.02; // 2% tolerance

  if (diff > tolerance) {
    return `Payment breakdown (${formatPKR(grandTotal)}) differs from total price (${formatPKR(plan.totalPrice)}) by more than 2%. Please review.`;
  }

  return null;
}

// ════════════════════════════════════════════════════
// HANDLER
// ════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // ── ID guard ──
  const { id } = req.query;
  if (!id || typeof id !== 'string') {
    return res.status(400).json({ success: false, message: 'Project ID is required' });
  }
  if (!mongoose.isValidObjectId(id)) {
    return res.status(400).json({ success: false, message: 'Invalid project ID' });
  }

  // ════════════════════════════════════════════════════
  // GET — Public payment plans
  // ════════════════════════════════════════════════════
  if (req.method === 'GET') {
    const rl = await rateLimitApi(req);
    setRateLimitHeaders(res, rl);
    if (!rl.ok) return sendRateLimitResponse(res, rl);

    const viewer = await getOptionalAuth(req);
    await dbConnect();

    try {
      const Project = mongoose.models.Project as
        mongoose.Model<mongoose.Document>;

      if (!Project) {
        return res.status(500).json({ success: false, message: 'Something went wrong' });
      }

      const project = await Project.findOne({
        _id:       new mongoose.Types.ObjectId(id),
        isDeleted: { $ne: true },
      })
        .select('paymentPlans projectName saleMode developerId status verificationStatus isVerified')
        .lean() as {
          _id:           mongoose.Types.ObjectId;
          paymentPlans?: Array<Record<string, unknown>>;
          projectName?:  string;
          saleMode?:     string;
          developerId?:  mongoose.Types.ObjectId;
          status?:       string;
          verificationStatus?: string;
          isVerified?:   boolean;
        } | null;

      if (!project) {
        return res.status(404).json({
          success: false,
          message: 'Project not found',
        });
      }

      const isAdmin = !!viewer && ['admin', 'superadmin'].includes(viewer.role);
      const isOwner = !!viewer && viewer.role === 'developer' && String(project.developerId ?? '') === viewer.id;
      const publicAllowed = project.isVerified === true ||
        (String(project.status ?? '').toLowerCase() === 'verified' &&
         String(project.verificationStatus ?? '').toLowerCase() === 'verified');
      if (!publicAllowed && !isAdmin && !isOwner) {
        return res.status(404).json({ success: false, message: 'Project not found' });
      }

      // Filter: only active plans for public
      const allPlans = (project.paymentPlans ?? []) as Array<Record<string, unknown>>;
      const activePlans = allPlans
        .filter((plan) => (isAdmin || isOwner) ? true : plan.isActive !== false)
        .sort((a, b) => {
          // Default plan first, then by order
          if (a.isDefault && !b.isDefault) return -1;
          if (!a.isDefault && b.isDefault) return 1;
          return ((a.order as number) ?? 0) - ((b.order as number) ?? 0);
        });

      // Check validity dates
      const now = new Date();
      const validPlans = activePlans.filter((plan) => {
        if (isAdmin || isOwner) return true;
        if (plan.validFrom) {
          const from = new Date(plan.validFrom as string);
          if (!isNaN(from.getTime()) && from > now) return false;
        }
        if (plan.validUntil) {
          const until = new Date(plan.validUntil as string);
          if (!isNaN(until.getTime()) && until < now) return false;
        }
        return true;
      });

      // Public clients should not receive internal audit/user references.
      // Owners/admins retain the management fields required by the dashboard.
      const publicPlans = validPlans.map((plan) => {
        if (isAdmin || isOwner) return plan;
        const {
          createdBy: _createdBy,
          updatedBy: _updatedBy,
          __v: _version,
          ...rest
        } = plan;
        return rest;
      });

      res.setHeader('Cache-Control', isAdmin || isOwner ? 'no-store, max-age=0' : 'public, s-maxage=60, stale-while-revalidate=300');

      return res.status(200).json({
        success: true,
        data: {
          paymentPlans: publicPlans,
          saleMode:     project.saleMode ?? 'Both',
          totalPlans:   publicPlans.length,
          hasInstallment: publicPlans.some(
            (p) => p.planType === 'easy_installment' || p.planType === 'flexi' || p.planType === 'standard'
          ),
          hasFullPayment: publicPlans.some(
            (p) => p.planType === 'full_payment' || p.planType === 'down_payment'
          ),
        },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'medium',
        metadata: {
          action:    'project_payment_plans_fetch_failed',
          projectId: id,
          reason:    error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ═══════════════════════════════════════════════════
  // AUTH + RATE LIMIT for mutations
  // ═══════════════════════════════════════════════════
  const auth = await requireAuth(req, res);
  if (!auth) return;

  const role = auth.role as string;
  if (!['developer', 'admin', 'superadmin'].includes(role)) {
    return res.status(403).json({ success: false, message: 'Access denied' });
  }

  const rl = await rateLimitDeveloper(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) return sendRateLimitResponse(res, rl);

  await dbConnect();

  // ════════════════════════════════════════════════════
  // POST — Create new payment plan
  // ════════════════════════════════════════════════════
  if (req.method === 'POST') {
    try {
      // Zod validation
      const parsed = PaymentPlanSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid payment plan data',
          errors:  parsed.error.flatten().fieldErrors,
        });
      }

      const planData = parsed.data;

      // Validate breakdown sum
      const sumWarning = validateBreakdownSum(planData);

      // Verify ownership
      const ownership = await verifyProjectOwnership(id, auth.id, role);
      if (!ownership.ok) {
        return res.status(ownership.status ?? 403).json({
          success: false,
          message: ownership.error ?? 'Access denied',
        });
      }

      const existingPlans = ((ownership.project as any)?.paymentPlans ?? []) as Array<Record<string, unknown>>;

      // Max 10 payment plans per project
      if (existingPlans.length >= 10) {
        return res.status(400).json({
          success: false,
          message: 'Maximum 10 payment plans allowed per project',
        });
      }

      // If this is default, unset other defaults
      const Project = mongoose.models.Project as
        mongoose.Model<mongoose.Document>;

      if (planData.isDefault) {
        await Project.findByIdAndUpdate(id, {
          $set: { 'paymentPlans.$[].isDefault': false },
        });
      }

      // If this is the first plan, make it default
      const newPlan = {
        _id:       new mongoose.Types.ObjectId(),
        ...planData,
        isDefault: planData.isDefault || existingPlans.length === 0,
        order:     planData.order ?? existingPlans.length,
        createdAt: new Date(),
        createdBy: auth.id,
        updatedAt: new Date(),
        updatedBy: auth.id,
      };

      await Project.findByIdAndUpdate(id, {
        $push: { paymentPlans: newPlan },
      });

      // Audit log
      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        metadata: {
          action:    'project_payment_plan_created',
          projectId: id,
          planName:  planData.name,
          planType:  planData.planType,
          planId:    String(newPlan._id),
        },
      });

      return res.status(201).json({
        success: true,
        message: 'Payment plan created successfully',
        data: {
          planId:  newPlan._id,
          plan:    newPlan,
          warning: sumWarning,
        },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'high',
        userId:   auth.id,
        metadata: {
          action:    'project_payment_plan_create_failed',
          projectId: id,
          reason:    error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ════════════════════════════════════════════════════
  // PATCH — Update existing payment plan
  // ════════════════════════════════════════════════════
  if (req.method === 'PATCH') {
    try {
      const parsed = UpdatePaymentPlanSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: 'Invalid data',
          errors:  parsed.error.flatten().fieldErrors,
        });
      }

      const { planId, ...updates } = parsed.data;

      if (!mongoose.isValidObjectId(planId)) {
        return res.status(400).json({
          success: false,
          message: 'Invalid plan ID',
        });
      }

      // Verify ownership
      const ownership = await verifyProjectOwnership(id, auth.id, role);
      if (!ownership.ok) {
        return res.status(ownership.status ?? 403).json({
          success: false,
          message: ownership.error ?? 'Access denied',
        });
      }

      // Check plan exists
      const existingPlans = ((ownership.project as any)?.paymentPlans ?? []) as Array<{ _id: mongoose.Types.ObjectId }>;
      const planExists = existingPlans.some(
        (p) => p._id.toString() === planId
      );

      if (!planExists) {
        return res.status(404).json({
          success: false,
          message: 'Payment plan not found',
        });
      }

      // If setting this as default, unset others first
      const Project = mongoose.models.Project as
        mongoose.Model<mongoose.Document>;

      if (updates.isDefault) {
        await Project.findByIdAndUpdate(id, {
          $set: { 'paymentPlans.$[].isDefault': false },
        });
      }

      // Build positional update
      const setFields: Record<string, unknown> = {};
      const changedFields: string[] = [];

      for (const [key, value] of Object.entries(updates)) {
        if (value !== undefined) {
          setFields[`paymentPlans.$.${key}`] = value;
          changedFields.push(key);
        }
      }

      setFields['paymentPlans.$.updatedAt'] = new Date();
      setFields['paymentPlans.$.updatedBy'] = auth.id;

      const result = await Project.findOneAndUpdate(
        {
          _id:                  new mongoose.Types.ObjectId(id),
          'paymentPlans._id':   new mongoose.Types.ObjectId(planId),
        },
        { $set: setFields },
        { new: true }
      );

      if (!result) {
        return res.status(404).json({
          success: false,
          message: 'Payment plan not found',
        });
      }

      // Validate breakdown if totalPrice or installments changed
      let sumWarning: string | null = null;
      if (updates.totalPrice !== undefined || updates.installments !== undefined) {
        // Re-fetch the updated plan for validation
        const updatedProject = await Project.findById(id)
          .select('paymentPlans')
          .lean() as { paymentPlans?: Array<Record<string, unknown>> } | null;

        const updatedPlan = updatedProject?.paymentPlans?.find(
          (p: any) => p._id.toString() === planId
        );

        if (updatedPlan) {
          sumWarning = validateBreakdownSum(updatedPlan as any);
        }
      }

      await logSecurityEvent({
        type:     'admin_action',
        severity: 'low',
        userId:   auth.id,
        metadata: {
          action:        'project_payment_plan_updated',
          projectId:     id,
          planId,
          changedFields,
        },
      });

      return res.status(200).json({
        success: true,
        message: 'Payment plan updated successfully',
        data: {
          planId,
          changedFields,
          warning: sumWarning,
        },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'medium',
        userId:   auth.id,
        metadata: {
          action:    'project_payment_plan_update_failed',
          projectId: id,
          reason:    error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ════════════════════════════════════════════════════
  // DELETE — Remove payment plan
  // ════════════════════════════════════════════════════
  if (req.method === 'DELETE') {
    try {
      const parsed = DeletePaymentPlanSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          success: false,
          message: 'planId is required',
        });
      }

      const { planId } = parsed.data;

      if (!mongoose.isValidObjectId(planId)) {
        return res.status(400).json({
          success: false,
          message: 'Invalid plan ID',
        });
      }

      // Verify ownership
      const ownership = await verifyProjectOwnership(id, auth.id, role);
      if (!ownership.ok) {
        return res.status(ownership.status ?? 403).json({
          success: false,
          message: ownership.error ?? 'Access denied',
        });
      }

      // Check plan exists
      const existingPlans = ((ownership.project as any)?.paymentPlans ?? []) as Array<{ _id: mongoose.Types.ObjectId; name?: string; isDefault?: boolean }>;
      const planToDelete = existingPlans.find(
        (p) => p._id.toString() === planId
      );

      if (!planToDelete) {
        return res.status(404).json({
          success: false,
          message: 'Payment plan not found',
        });
      }

      // Remove plan
      const Project = mongoose.models.Project as
        mongoose.Model<mongoose.Document>;

      await Project.findByIdAndUpdate(id, {
        $pull: {
          paymentPlans: { _id: new mongoose.Types.ObjectId(planId) },
        },
      });

      // If deleted plan was default, set first remaining as default
      if (planToDelete.isDefault) {
        const remaining = existingPlans.filter(
          (p) => p._id.toString() !== planId
        );
        if (remaining.length > 0) {
          await Project.findOneAndUpdate(
            {
              _id:                new mongoose.Types.ObjectId(id),
              'paymentPlans._id': remaining[0]._id,
            },
            { $set: { 'paymentPlans.$.isDefault': true } }
          );
        }
      }

      await logSecurityEvent({
        type:     'admin_action',
        severity: 'medium',
        userId:   auth.id,
        metadata: {
          action:    'project_payment_plan_deleted',
          projectId: id,
          planId,
          planName:  planToDelete.name,
        },
      });

      return res.status(200).json({
        success: true,
        message: 'Payment plan deleted successfully',
        data: { planId },
      });

    } catch (error: unknown) {
      await logSecurityEvent({
        type:     'system_error',
        severity: 'medium',
        userId:   auth.id,
        metadata: {
          action:    'project_payment_plan_delete_failed',
          projectId: id,
          reason:    error instanceof Error ? error.message : 'Unknown error',
        },
      });
      return res.status(500).json({
        success: false,
        message: 'Something went wrong. Please try again.',
      });
    }
  }

  // ── Method not allowed ──
  return res.status(405).json({ success: false, message: 'Method not allowed' });
}

// pages/api/projects/index.ts
import type { NextApiRequest, NextApiResponse } from 'next';
import type { SortOrder, FilterQuery, PipelineStage } from 'mongoose';
import mongoose from 'mongoose';
import { z } from 'zod';

import dbConnect from '@/lib/dbConnect';
import Project, { IProject, DeveloperBadgeTier } from '@/models/Projects';
import User from '@/models/User';
import DeveloperProfile from '@/models/DeveloperProfile';

import {
  requireAuth,
  requireDeveloper,
  getClientIp,
} from '@/lib/requireAuth';

import {
  rateLimitApi,
  rateLimitPropertyCreate,
  setRateLimitHeaders,
  sendRateLimitResponse,
} from '@/lib/rateLimit';

import { logSecurityEvent } from '@/lib/security/logSecurityEvent';

// ============================================================================
// SECURITY HEADERS
// ============================================================================

function setSecurityHeaders(res: NextApiResponse): void {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader(
    'Permissions-Policy',
    'geolocation=(), microphone=(), camera=(), payment=(), usb=(), interest-cohort=()'
  );
  res.setHeader('X-DNS-Prefetch-Control', 'off');
  res.setHeader(
    'Strict-Transport-Security',
    'max-age=86400; includeSubDomains; preload'
  );
}

// ============================================================================
// CONSTANTS — Enums aligned with Projects model
// ============================================================================

const PROJECT_CATEGORIES = [
  'highrise',
  'society',
  'mixed_use',
  'commercial_plaza',
  'townhouse',
  'gated_community',
] as const;

const PROJECT_NATURES = ['residential', 'commercial', 'mixed'] as const;

const DEVELOPER_BADGES: DeveloperBadgeTier[] = [
  'new_entrant',
  'emerging',
  'trusted',
  'premium',
];

const LISTING_STATUS = ['draft', 'pending', 'verified', 'rejected'] as const;

const VERIFICATION_STATUS = ['pending', 'verified', 'rejected'] as const;

/**
 * Pakistani-friendly budget tiers — what buyers actually search.
 * Maps to PKR ranges for filtering.
 */
const BUDGET_TIERS = {
  under_50L: { min: 0, max: 5_000_000 },
  '50L_to_1Cr': { min: 5_000_000, max: 10_000_000 },
  '1Cr_to_3Cr': { min: 10_000_000, max: 30_000_000 },
  '3Cr_to_5Cr': { min: 30_000_000, max: 50_000_000 },
  above_5Cr: { min: 50_000_000, max: Number.MAX_SAFE_INTEGER },
} as const;

type BudgetTier = keyof typeof BUDGET_TIERS;

const SORT_OPTIONS = {
  newest: { createdAt: -1, _id: -1 },
  oldest: { createdAt: 1, _id: 1 },
  price_asc: { minPrice: 1, _id: -1 },
  price_desc: { maxPrice: -1, _id: -1 },
  popularity: { highriseScore: -1, createdAt: -1 },
  most_viewed: { views: -1, createdAt: -1 },
  most_inquired: { inquiries: -1, createdAt: -1 },
} as const;

type SortKey = keyof typeof SORT_OPTIONS;

// ============================================================================
// HELPERS
// ============================================================================

function getQueryString(q: string | string[] | undefined): string {
  if (!q) return '';
  return Array.isArray(q) ? String(q[0] || '') : String(q || '');
}

function normalizeText(input: string, maxLen: number): string {
  const s = String(input || '').trim();
  if (!s) return '';
  return s.length > maxLen ? s.slice(0, maxLen) : s;
}

function escapeRegExp(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function clampInt(n: number, min: number, max: number): number {
  if (!Number.isFinite(n) || Number.isNaN(n)) return min;
  return Math.max(min, Math.min(max, Math.floor(n)));
}

function parseFloat2(n: string | undefined): number | null {
  if (!n) return null;
  const v = parseFloat(n);
  return Number.isFinite(v) ? v : null;
}

function isValidObjectId(id: string): boolean {
  return /^[a-fA-F0-9]{24}$/.test(id);
}

function parseBool(v: string): boolean | null {
  const s = String(v || '').toLowerCase().trim();
  if (['true', '1', 'yes', 'y', 'on'].includes(s)) return true;
  if (['false', '0', 'no', 'n', 'off'].includes(s)) return false;
  return null;
}

/** base64url helpers (no padding) */
function b64urlEncode(obj: unknown): string {
  const json = JSON.stringify(obj);
  return Buffer.from(json, 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function b64urlDecode<T = unknown>(token: string): T | null {
  try {
    const t = String(token || '').trim();
    if (!t) return null;
    let b64 = t.replace(/-/g, '+').replace(/_/g, '/');
    const pad = b64.length % 4;
    if (pad) b64 += '='.repeat(4 - pad);
    const raw = Buffer.from(b64, 'base64').toString('utf8');
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

type CursorPayload = { createdAt: string; _id: string };

/**
 * Pakistani price formatter — Crore/Lac display.
 */
function formatPricePK(price: number): string {
  if (!price || price <= 0) return 'Price on request';
  if (price >= 10_000_000) return `${(price / 10_000_000).toFixed(2)} Crore`;
  if (price >= 100_000) return `${(price / 100_000).toFixed(2)} Lac`;
  return `Rs ${price.toLocaleString()}`;
}

/**
 * Auto-derive Project.developerBadge tier from developer's completed projects.
 *  0      → new_entrant
 *  1-2    → emerging
 *  3-9    → trusted
 *  10+    → premium
 * Admin can override later via badge.ts endpoint.
 */
function deriveBadgeFromProjectCount(count: number): DeveloperBadgeTier {
  if (count >= 10) return 'premium';
  if (count >= 3) return 'trusted';
  if (count >= 1) return 'emerging';
  return 'new_entrant';
}

/**
 * Cloudinary public_id validation — ensures it's from our account.
 */
function isHighrisePublicId(publicId: string): boolean {
  if (!publicId || typeof publicId !== 'string') return false;
  return /^highrise\//.test(publicId) || /^projects\//.test(publicId);
}

// ============================================================================
// ZOD SCHEMA — POST validation (minimal wizard fields only)
// ============================================================================

const ProjectCreateSchema = z.object({
  // Required wizard fields
  projectName: z
    .string({ message: 'Project name is required' })
    .trim()
    .min(3, 'Project name must be at least 3 characters')
    .max(150, 'Project name cannot exceed 150 characters'),

  projectCategory: z.enum(PROJECT_CATEGORIES, {
    message: 'Invalid project category',
  }),

  projectNature: z.enum(PROJECT_NATURES, {
    message: 'Invalid project nature',
  }),

  city: z
    .string({ message: 'City is required' })
    .trim()
    .min(2, 'City must be at least 2 characters')
    .max(80, 'City cannot exceed 80 characters'),

  area: z
    .string({ message: 'Area is required' })
    .trim()
    .min(2, 'Area must be at least 2 characters')
    .max(120, 'Area cannot exceed 120 characters'),

  // Optional but recommended at create time
  tagline: z.string().trim().max(200).optional(),
  shortDescription: z.string().trim().max(500).optional(),
  specificLocation: z.string().trim().max(300).optional(),

  coordinates: z
    .object({
      lat: z.number().min(-90).max(90),
      lng: z.number().min(-180).max(180),
    })
    .optional(),

  featureImageUrl: z.string().url().max(2048).optional(),
  featureImagePublicId: z.string().max(512).optional(),

  projectType: z.enum(['Residential', 'Commercial', 'Mixed Use']).optional(),
  projectStatus: z
    .enum([
      'Planning',
      'Pre-Launch',
      'Under Development',
      'Launched',
      'Completed',
    ])
    .optional(),
});

type ProjectCreateInput = z.infer<typeof ProjectCreateSchema>;

// ============================================================================
// PUBLIC RESPONSE SANITIZER
// ============================================================================

interface SanitizedProjectCard {
  _id: string;
  slug: string;
  projectName: string;
  tagline?: string;
  shortDescription?: string;
  city: string;
  area: string;
  projectCategory: string;
  projectNature: string;
  projectStatus: string;
  saleMode?: string;

  // Trust & verification
  status: string;
  verificationStatus: string;
  isFeatured?: boolean;
  isVerified?: boolean;
  isTrustedBuilder?: boolean;
  developerBadge?: DeveloperBadgeTier;
  badgeLabel?: string;
  badgeEmoji?: string;

  // Pricing
  minPrice?: number;
  maxPrice?: number;
  priceRangeText?: string;
  startingPriceFormatted?: string;

  // Trust meta
  highriseScore?: number;
  riskLevel?: string;
  deliveryStatus?: string;
  verificationLevel?: string;

  // Media (URLs only — no public_ids)
  primaryImage: string | null;
  featureImageUrl?: string;

  // Developer snapshot (company name only — no internal contacts)
  developerId: string;
  developerName: string;
  developerLogoUrl?: string;

  // Unit type summary (V4.9.8 — auto-aggregated)
  unitTypesCount: number;
  totalUnits?: number;
  unitsAvailable?: number;

  // Geo distance (only present in geo radius searches)
  distanceKm?: number;

  // Timestamps
  createdAt: string;
  updatedAt: string;
}

/**
 * Project document shape from MongoDB lean() — covers fields we project.
 * Avoids unsafe `any` while remaining flexible to schema evolution.
 */
interface LeanProjectDoc {
  _id: mongoose.Types.ObjectId | string;
  slug: string;
  projectName: string;
  tagline?: string;
  shortDescription?: string;
  city: string;
  area: string;
  projectCategory: string;
  projectNature: string;
  projectStatus: string;
  saleMode?: string;
  status: string;
  verificationStatus: string;
  isFeatured?: boolean;
  isVerified?: boolean;
  isTrustedBuilder?: boolean;
  developerBadge?: DeveloperBadgeTier;
  minPrice?: number;
  maxPrice?: number;
  priceRangeText?: string;
  highriseScore?: number;
  riskLevel?: string;
  deliveryStatus?: string;
  verificationLevel?: string;
  featureImageUrl?: string;
  images?: Array<{ url?: string; isPrimary?: boolean }>;
  gallery?: Array<{ url?: string }>;
  developerId?: { _id?: mongoose.Types.ObjectId; name?: string } | string;
  developerProfile?: { name?: string; logoUrl?: string };
  unitTypeBreakdown?: Array<{
    type?: string;
    totalUnits?: number;
    availableUnits?: number;
  }>;
  totalUnits?: number;
  unitsAvailable?: number;
  createdAt: Date;
  updatedAt: Date;
  distanceKm?: number;
}

function sanitizeProjectForPublic(p: LeanProjectDoc): SanitizedProjectCard {
  // Compute primary image (3-tier fallback)
  let primaryImage: string | null = null;
  if (p.featureImageUrl) {
    primaryImage = p.featureImageUrl;
  } else if (Array.isArray(p.images) && p.images.length > 0) {
    const primary = p.images.find((img) => img?.isPrimary);
    primaryImage = primary?.url || p.images[0]?.url || null;
  } else if (Array.isArray(p.gallery) && p.gallery.length > 0) {
    primaryImage = p.gallery[0]?.url || null;
  }

  // Developer name resolution (populate or snapshot fallback)
  let developerName = '';
  let developerIdStr = '';
  if (typeof p.developerId === 'object' && p.developerId) {
    developerName = String(p.developerId.name || '');
    developerIdStr = String(p.developerId._id || '');
  } else if (typeof p.developerId === 'string') {
    developerIdStr = p.developerId;
  }
  if (!developerName && p.developerProfile?.name) {
    developerName = p.developerProfile.name;
  }

  // Badge display helpers
  const badgeLabels: Record<DeveloperBadgeTier, string> = {
    new_entrant: 'New Developer',
    emerging: 'Emerging Builder',
    trusted: 'Trusted Developer',
    premium: 'Premium Developer',
  };
  const badgeEmojis: Record<DeveloperBadgeTier, string> = {
    new_entrant: '🆕',
    emerging: '⭐',
    trusted: '🏆',
    premium: '💎',
  };

  // Unit type breakdown summary
  const unitTypesCount = Array.isArray(p.unitTypeBreakdown)
    ? p.unitTypeBreakdown.length
    : 0;

  return {
    _id: String(p._id),
    slug: p.slug,
    projectName: p.projectName,
    tagline: p.tagline,
    shortDescription: p.shortDescription,
    city: p.city,
    area: p.area,
    projectCategory: p.projectCategory,
    projectNature: p.projectNature,
    projectStatus: p.projectStatus,
    saleMode: p.saleMode,

    status: p.status,
    verificationStatus: p.verificationStatus,
    isFeatured: p.isFeatured,
    isVerified: p.isVerified,
    isTrustedBuilder: p.isTrustedBuilder,
    developerBadge: p.developerBadge,
    badgeLabel: p.developerBadge ? badgeLabels[p.developerBadge] : undefined,
    badgeEmoji: p.developerBadge ? badgeEmojis[p.developerBadge] : undefined,

    minPrice: p.minPrice,
    maxPrice: p.maxPrice,
    priceRangeText: p.priceRangeText,
    startingPriceFormatted:
      typeof p.minPrice === 'number' && p.minPrice > 0
        ? formatPricePK(p.minPrice)
        : undefined,

    highriseScore: p.highriseScore,
    riskLevel: p.riskLevel,
    deliveryStatus: p.deliveryStatus,
    verificationLevel: p.verificationLevel,

    primaryImage,
    featureImageUrl: p.featureImageUrl,

    developerId: developerIdStr,
    developerName,
    developerLogoUrl: p.developerProfile?.logoUrl,

    unitTypesCount,
    totalUnits: p.totalUnits,
    unitsAvailable: p.unitsAvailable,

    distanceKm: p.distanceKm,

    createdAt:
      p.createdAt instanceof Date ? p.createdAt.toISOString() : String(p.createdAt),
    updatedAt:
      p.updatedAt instanceof Date ? p.updatedAt.toISOString() : String(p.updatedAt),
  };
}

// ============================================================================
// HANDLER
// ============================================================================

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  setSecurityHeaders(res);

  if (req.method === 'GET') {
    return handleGet(req, res);
  }

  if (req.method === 'POST') {
    return handlePost(req, res);
  }

  res.setHeader('Allow', 'GET, POST');
  res.status(405).json({
    success: false,
    error: 'METHOD_NOT_ALLOWED',
    message: 'Method not allowed',
  });
  return;
}

// ============================================================================
// GET HANDLER — Public listing with filters
// ============================================================================

async function handleGet(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  // Rate limit (Upstash)
  const rl = await rateLimitApi(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) {
    sendRateLimitResponse(res, rl);
    return;
  }

  try {
    await dbConnect();

    // Optional auth — if admin, allow extra filters
    let isAdmin = false;
    try {
      const adminToken = await requireAuth(req, res);
      if (adminToken && adminToken.role === 'admin') {
        isAdmin = true;
      }
      // If requireAuth sent a 401/403 → res already sent, can't continue
      if (res.writableEnded) return;
    } catch {
      // Public access — no auth needed
      isAdmin = false;
    }

    // Re-check writable (defensive)
    if (res.writableEnded) return;

    // ───────────── Extract query params ─────────────
    const q = req.query;

    const cityValue = normalizeText(getQueryString(q.city), 80);
    const categoryValue = normalizeText(
      getQueryString(q.projectCategory),
      32
    ).toLowerCase();
    const natureValue = normalizeText(
      getQueryString(q.projectNature),
      32
    ).toLowerCase();
    const badgeValue = normalizeText(
      getQueryString(q.developerBadge),
      32
    ).toLowerCase();
    const budgetTierValue = normalizeText(
      getQueryString(q.budgetTier),
      20
    ).toLowerCase();
    const searchValue = normalizeText(getQueryString(q.search), 100);
    const developerIdValue = normalizeText(getQueryString(q.developerId), 32);
    const sortValue = normalizeText(
      getQueryString(q.sort),
      20
    ).toLowerCase() as SortKey;

    const minPriceRaw = parseFloat2(getQueryString(q.minPrice));
    const maxPriceRaw = parseFloat2(getQueryString(q.maxPrice));

    const trustedBool = parseBool(getQueryString(q.trusted));
    const featuredBool = parseBool(getQueryString(q.featured));

    // Geo radius (enterprise standard)
    const nearLat = parseFloat2(getQueryString(q.nearLat));
    const nearLng = parseFloat2(getQueryString(q.nearLng));
    const radiusKm = parseFloat2(getQueryString(q.radiusKm));
    const hasGeoSearch =
      nearLat !== null &&
      nearLng !== null &&
      radiusKm !== null &&
      radiusKm > 0 &&
      radiusKm <= 200;

    // Admin-only filters
    const statusValue = isAdmin
      ? normalizeText(getQueryString(q.status), 16).toLowerCase()
      : '';
    const verificationStatusValue = isAdmin
      ? normalizeText(getQueryString(q.verificationStatus), 16).toLowerCase()
      : '';
    const deletedValue = isAdmin
      ? normalizeText(getQueryString(q.deleted), 10).toLowerCase()
      : '';

    // Pagination
    const limitNum = clampInt(
      parseInt(getQueryString(q.limit) || '24', 10),
      1,
      100
    );
    const pageNum = clampInt(
      parseInt(getQueryString(q.page) || '1', 10),
      1,
      1_000_000
    );
    const skip = (pageNum - 1) * limitNum;
    const cursorToken = normalizeText(getQueryString(q.cursor), 400);

    // ───────────── Build filter ─────────────
    const filter: FilterQuery<IProject> = {};
    const and: FilterQuery<IProject>[] = [];

    // Soft delete gating
    if (isAdmin && deletedValue) {
      if (deletedValue === 'all') {
        // no filter
      } else if (deletedValue === 'true') {
        and.push({ isDeleted: true });
      } else if (deletedValue === 'false') {
        and.push({ isDeleted: { $ne: true } });
      }
    } else {
      and.push({ isDeleted: { $ne: true } });
    }

    // Visibility gating
    if (isAdmin) {
      if (statusValue && (LISTING_STATUS as readonly string[]).includes(statusValue)) {
        and.push({ status: statusValue as typeof LISTING_STATUS[number] });
      }
      if (
        verificationStatusValue &&
        (VERIFICATION_STATUS as readonly string[]).includes(verificationStatusValue)
      ) {
        and.push({
          verificationStatus:
            verificationStatusValue as typeof VERIFICATION_STATUS[number],
        });
      }
    } else {
      // Public: only verified projects + approved developers
      and.push({ status: 'verified' });
      and.push({ verificationStatus: 'verified' });
      and.push({ developerApprovalStatus: 'approved' });
    }

    // City filter (case-insensitive exact)
    if (cityValue) {
      and.push({
        city: { $regex: new RegExp(`^${escapeRegExp(cityValue)}$`, 'i') },
      });
    }

    // Category filter (6 types)
    if (categoryValue && (PROJECT_CATEGORIES as readonly string[]).includes(categoryValue)) {
      and.push({
        projectCategory: categoryValue as typeof PROJECT_CATEGORIES[number],
      });
    }

    // Nature filter (3 types)
    if (natureValue && (PROJECT_NATURES as readonly string[]).includes(natureValue)) {
      and.push({
        projectNature: natureValue as typeof PROJECT_NATURES[number],
      });
    }

    // Developer badge filter (4 tiers)
    if (badgeValue && (DEVELOPER_BADGES as readonly string[]).includes(badgeValue)) {
      and.push({ developerBadge: badgeValue as DeveloperBadgeTier });
    }

    // Trusted-only filter
    if (trustedBool === true) {
      and.push({ isTrustedBuilder: true });
    }

    // Featured-only filter
    if (featuredBool === true) {
      and.push({ isFeatured: true });
    }

    // Budget tier filter (Pakistani context)
    if (budgetTierValue && budgetTierValue in BUDGET_TIERS) {
      const tier = BUDGET_TIERS[budgetTierValue as BudgetTier];
      // Project price overlaps tier range
      and.push({
        $or: [
          {
            minPrice: { $gte: tier.min, $lte: tier.max },
          },
          {
            maxPrice: { $gte: tier.min, $lte: tier.max },
          },
          {
            $and: [
              { minPrice: { $lte: tier.min } },
              { maxPrice: { $gte: tier.max } },
            ],
          },
        ],
      });
    }

    // Manual price range (overrides budget tier if both supplied)
    if (minPriceRaw !== null && minPriceRaw > 0) {
      and.push({ maxPrice: { $gte: minPriceRaw } });
    }
    if (maxPriceRaw !== null && maxPriceRaw > 0) {
      and.push({ minPrice: { $lte: maxPriceRaw } });
    }

    // Developer filter
    if (developerIdValue) {
      if (!isValidObjectId(developerIdValue)) {
        res.status(400).json({
          success: false,
          error: 'INVALID_DEVELOPER_ID',
          message: 'Invalid developerId',
        });
        return;
      }
      and.push({ developerId: new mongoose.Types.ObjectId(developerIdValue) });
    }

    // Text search
    if (searchValue) {
      const safe = escapeRegExp(searchValue);
      const rx = new RegExp(safe, 'i');
      and.push({
        $or: [
          { projectName: rx },
          { city: rx },
          { area: rx },
          { tagline: rx },
        ],
      });
    }

    if (and.length) filter.$and = and;

    // ───────────── Sort selection ─────────────
    const sortKey: SortKey =
      sortValue && sortValue in SORT_OPTIONS ? sortValue : 'newest';
    // Cast to numeric sort spec — required by both .sort() and $geoNear $sort stage
    const sortObj = SORT_OPTIONS[sortKey] as Record<string, 1 | -1>;

    // ───────────── GEO RADIUS SEARCH (special path) ─────────────
    if (hasGeoSearch) {
      // Use $geoNear aggregation — uses 2dsphere index
      const radiusMeters = (radiusKm as number) * 1000;

      const pipeline: PipelineStage[] = [
        {
          $geoNear: {
            near: {
              type: 'Point',
              coordinates: [nearLng as number, nearLat as number],
            },
            distanceField: 'distanceMeters',
            maxDistance: radiusMeters,
            spherical: true,
            query: filter,
          },
        },
        {
          $addFields: {
            distanceKm: { $divide: ['$distanceMeters', 1000] },
          },
        },
        { $sort: sortObj },
        { $skip: skip },
        { $limit: limitNum },
        {
          $lookup: {
            from: 'users',
            localField: 'developerId',
            foreignField: '_id',
            as: 'developerData',
            pipeline: [{ $project: { name: 1 } }],
          },
        },
        {
          $addFields: {
            developerId: {
              $cond: {
                if: { $gt: [{ $size: '$developerData' }, 0] },
                then: { $arrayElemAt: ['$developerData', 0] },
                else: '$developerId',
              },
            },
          },
        },
        { $project: { developerData: 0, distanceMeters: 0 } },
      ];

      const docs = (await Project.aggregate(pipeline).option({
        maxTimeMS: 3000,
      })) as LeanProjectDoc[];

      const projects = docs.map((p) => sanitizeProjectForPublic(p));

      // Cache geo searches briefly (location-specific)
      if (!isAdmin) {
        res.setHeader(
          'Cache-Control',
          'public, s-maxage=15, stale-while-revalidate=60'
        );
      } else {
        res.setHeader('Cache-Control', 'no-store, max-age=0');
      }

      res.status(200).json({
        success: true,
        projects,
        geoSearch: {
          nearLat,
          nearLng,
          radiusKm,
          resultCount: projects.length,
        },
        pagination: {
          mode: 'geo',
          page: pageNum,
          limit: limitNum,
        },
      });
      return;
    }

    // ───────────── CURSOR PAGINATION ─────────────
    let cursorApplied = false;
    if (cursorToken) {
      const parsed = b64urlDecode<CursorPayload>(cursorToken);
      if (!parsed?.createdAt || !parsed?._id) {
        res.status(400).json({
          success: false,
          error: 'INVALID_CURSOR',
          message: 'Invalid cursor',
        });
        return;
      }
      const cAt = new Date(parsed.createdAt);
      if (!Number.isFinite(cAt.getTime()) || !isValidObjectId(parsed._id)) {
        res.status(400).json({
          success: false,
          error: 'INVALID_CURSOR',
          message: 'Invalid cursor payload',
        });
        return;
      }

      const cId = new mongoose.Types.ObjectId(parsed._id);
      const cursorClause: FilterQuery<IProject> = {
        $or: [
          { createdAt: { $lt: cAt } },
          { createdAt: cAt, _id: { $lt: cId } },
        ],
      };

      filter.$and = filter.$and || [];
      filter.$and.push(cursorClause);
      cursorApplied = true;
    }

    // ───────────── Projection ─────────────
    const publicProjection = [
      '_id slug projectName tagline shortDescription',
      'city area projectCategory projectNature projectStatus saleMode',
      'status verificationStatus isFeatured isVerified isTrustedBuilder',
      'developerBadge developerApprovalStatus',
      'minPrice maxPrice priceRangeText',
      'highriseScore riskLevel deliveryStatus verificationLevel',
      'featureImageUrl images.url images.isPrimary gallery.url',
      'developerId developerProfile.name developerProfile.logoUrl',
      'unitTypeBreakdown.type unitTypeBreakdown.totalUnits',
      'unitTypeBreakdown.availableUnits',
      'totalUnits unitsAvailable',
      'createdAt updatedAt',
    ].join(' ');

    const adminExtra = 'isDeleted deletedAt featureImagePublicId';
    const projection = isAdmin
      ? `${publicProjection} ${adminExtra}`
      : publicProjection;

    // ───────────── Execute query ─────────────
    const developerSelect = isAdmin ? 'name email role' : 'name';

    const baseQuery = Project.find(filter)
      .sort(sortObj)
      .select(projection)
      .populate({
        path: 'developerId',
        select: developerSelect,
        model: User,
      })
      .maxTimeMS(2500)
      .lean();

    const rawDocs = cursorApplied
      ? await baseQuery.limit(limitNum + 1)
      : await baseQuery.skip(skip).limit(limitNum);

    const docs = rawDocs as unknown as LeanProjectDoc[];

    let hasMore = false;
    let rows = docs;
    if (cursorApplied && docs.length > limitNum) {
      hasMore = true;
      rows = docs.slice(0, limitNum);
    }

    const projects = rows.map((p) => sanitizeProjectForPublic(p));

    // Next cursor
    let nextCursor: string | null = null;
    if (cursorApplied && projects.length > 0) {
      const last = rows[rows.length - 1];
      const lastCreatedAt =
        last.createdAt instanceof Date
          ? last.createdAt
          : new Date(last.createdAt);
      nextCursor = b64urlEncode({
        createdAt: lastCreatedAt.toISOString(),
        _id: String(last._id),
      } as CursorPayload);
    }

    // Cache headers
    if (!isAdmin) {
      res.setHeader(
        'Cache-Control',
        cursorApplied
          ? 'public, s-maxage=15, stale-while-revalidate=60'
          : 'public, s-maxage=30, stale-while-revalidate=120'
      );
    } else {
      res.setHeader('Cache-Control', 'no-store, max-age=0');
    }

    // Page mode response (includes totals)
    if (!cursorApplied) {
      const total = await Project.countDocuments(filter).maxTimeMS(2500);
      const pages = Math.max(1, Math.ceil(total / limitNum));

      res.status(200).json({
        success: true,
        projects,
        sort: sortKey,
        pagination: {
          mode: 'page',
          page: pageNum,
          limit: limitNum,
          total,
          totalPages: pages,
          hasNext: pageNum < pages,
          hasPrev: pageNum > 1,
        },
        filters: {
          city: cityValue || undefined,
          projectCategory: categoryValue || undefined,
          projectNature: natureValue || undefined,
          developerBadge: badgeValue || undefined,
          budgetTier: budgetTierValue || undefined,
          trusted: trustedBool === true ? true : undefined,
          featured: featuredBool === true ? true : undefined,
          search: searchValue || undefined,
        },
      });
      return;
    }

    // Cursor mode response
    res.status(200).json({
      success: true,
      projects,
      sort: sortKey,
      pagination: {
        mode: 'cursor',
        limit: limitNum,
        nextCursor: hasMore ? nextCursor : null,
        hasMore,
      },
    });
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : 'Unknown error';
    await logSecurityEvent({
      type: 'system_error',
      severity: 'medium',
      ip: getClientIp(req),
      userAgent: req.headers['user-agent'] as string,
      metadata: {
        action: 'projects_list_failed',
        endpoint: '/api/projects',
        method: 'GET',
        reason: errMsg,
      },
    });

    res.status(500).json({
      success: false,
      error: 'INTERNAL_SERVER_ERROR',
      message: 'Failed to fetch projects',
    });
  }
}

// ============================================================================
// POST HANDLER — Developer creates new project (wizard mode)
// ============================================================================

async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  // Rate limit (10/hour — same as property creation intensity)
  const rl = await rateLimitPropertyCreate(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) {
    sendRateLimitResponse(res, rl);
    return;
  }

  // Auth: developer or admin only
  const token = await requireDeveloper(req, res);
  if (!token) return;
  if (res.writableEnded) return;

  try {
    await dbConnect();

    // Parse + validate body
    const bodyRaw = req.body || {};
    const validation = ProjectCreateSchema.safeParse(bodyRaw);

    if (!validation.success) {
      const fieldErrors = validation.error.flatten().fieldErrors;
      res.status(400).json({
        success: false,
        error: 'VALIDATION_ERROR',
        message: 'Invalid project data',
        fieldErrors,
      });
      return;
    }

    const data: ProjectCreateInput = validation.data;

    // Validate Cloudinary public_id (if provided)
    if (data.featureImagePublicId && !isHighrisePublicId(data.featureImagePublicId)) {
      res.status(400).json({
        success: false,
        error: 'INVALID_IMAGE',
        message: 'Feature image must be uploaded via Highrise platform',
      });
      return;
    }

    // ───────────── Developer profile check ─────────────
    // Admin can create on behalf of any developer (future feature)
    // For now: only the developer themselves
    const developerId = token.id;

    const developerProfile = await DeveloperProfile.findOne({
      user: new mongoose.Types.ObjectId(developerId),
      isDeleted: { $ne: true },
    })
      .select(
        'companyName ceoName email logo socialLinks establishedYear ' +
          'completedProjectsCount status verificationLevel slug'
      )
      .lean();

    if (!developerProfile) {
      res.status(403).json({
        success: false,
        error: 'NO_DEVELOPER_PROFILE',
        message:
          'You must create a developer profile before adding projects. Visit /developer/register',
      });
      return;
    }

    // Type-narrow the lean() result
    const profile = developerProfile as unknown as {
      _id: mongoose.Types.ObjectId;
      companyName: string;
      ceoName?: string;
      email: string;
      logo?: { url?: string; public_id?: string };
      socialLinks?: { website?: string };
      establishedYear: number;
      completedProjectsCount: number;
      status: 'draft' | 'pending' | 'approved' | 'rejected' | 'suspended';
      verificationLevel: string;
      slug: string;
    };

    // Block project creation unless developer profile is approved
    if (profile.status !== 'approved' && token.role !== 'admin') {
      res.status(403).json({
        success: false,
        error: 'DEVELOPER_NOT_APPROVED',
        message: `Your developer profile status is "${profile.status}". You can only create projects once approved by Highrise.`,
        developerStatus: profile.status,
      });
      return;
    }

    // ───────────── Duplicate detection ─────────────
    const dupSearch: FilterQuery<IProject> = {
      developerId: new mongoose.Types.ObjectId(developerId),
      projectName: {
        $regex: new RegExp(`^${escapeRegExp(data.projectName)}$`, 'i'),
      },
      city: {
        $regex: new RegExp(`^${escapeRegExp(data.city)}$`, 'i'),
      },
      isDeleted: { $ne: true },
    };

    const duplicate = await Project.findOne(dupSearch)
      .select('_id slug projectName')
      .lean();

    if (duplicate) {
      const dup = duplicate as unknown as {
        _id: mongoose.Types.ObjectId;
        slug: string;
        projectName: string;
      };
      res.status(409).json({
        success: false,
        error: 'DUPLICATE_PROJECT',
        message: `You already have a project named "${dup.projectName}" in ${data.city}. Use a different name or edit the existing project.`,
        existingProject: {
          _id: String(dup._id),
          slug: dup.slug,
        },
      });
      return;
    }

    // ───────────── Build new project document ─────────────
    // Fetch decrypted phone for snapshot (if available)
    // Note: getPhone() is an instance method — we need full document not lean
    let developerPhone: string | undefined;
    try {
      const fullDevDoc = await DeveloperProfile.findById(profile._id);
      if (fullDevDoc) {
        developerPhone = fullDevDoc.getPhone() || undefined;
      }
    } catch {
      // Phone snapshot optional — don't fail project creation
      developerPhone = undefined;
    }

    // Auto-derive badge tier
    const derivedBadge = deriveBadgeFromProjectCount(
      profile.completedProjectsCount || 0
    );

    // Build coordinates + GeoJSON location
    const coords = data.coordinates;
    const projectDoc: Partial<IProject> = {
      developerId: new mongoose.Types.ObjectId(developerId),
      projectName: data.projectName,
      projectCategory: data.projectCategory,
      projectNature: data.projectNature,
      city: data.city,
      area: data.area,
      tagline: data.tagline,
      shortDescription: data.shortDescription,
      specificLocation: data.specificLocation,
      projectType: data.projectType,
      projectStatus: data.projectStatus || 'Planning',

      // Wizard default: draft status — developer continues via PATCH
      status: 'draft',
      verificationStatus: 'pending',
      isVerified: false,
      isFeatured: false,
      isDeleted: false,

      // Auto-derived badge (admin can override later)
      developerBadge: derivedBadge,

      // Developer profile snapshot
      developerProfile: {
        name: profile.companyName,
        ceoName: profile.ceoName,
        officialEmail: profile.email,
        contactNumber: developerPhone,
        website: profile.socialLinks?.website,
        logoUrl: profile.logo?.url,
        logoPublicId: profile.logo?.public_id,
        establishedYear: profile.establishedYear,
        completedProjectsCount: profile.completedProjectsCount,
        developerBadge: derivedBadge,
      },

      // Approval snapshot (publish gating)
      developerApprovalStatus: profile.status === 'approved' ? 'approved' : 'pending',
      developerVerifiedAt: profile.status === 'approved' ? new Date() : undefined,

      // Initial engagement counters
      views: 0,
      inquiries: 0,
      favoriteCount: 0,
      compareCount: 0,
      shareCount: 0,
      averageRating: 0,
      totalReviews: 0,
    };

    // Feature image (if provided)
    if (data.featureImageUrl) {
      projectDoc.featureImageUrl = data.featureImageUrl;
    }
    if (data.featureImagePublicId) {
      projectDoc.featureImagePublicId = data.featureImagePublicId;
    }

    // Coordinates → both legacy + GeoJSON (pre-save hook syncs location)
    if (coords) {
      projectDoc.coordinates = { lat: coords.lat, lng: coords.lng };
    }

    // ───────────── Create project ─────────────
    const created = await Project.create(projectDoc);

    // ───────────── Audit log ─────────────
    await logSecurityEvent({
      type: 'project_created',
      severity: 'low',
      userId: token.id,
      email: token.email,
      role: token.role,
      ip: getClientIp(req),
      userAgent: req.headers['user-agent'] as string,
      metadata: {
        action: 'project_created',
        projectId: String(created._id),
        projectName: created.projectName,
        city: created.city,
        projectCategory: created.projectCategory,
        developerBadge: derivedBadge,
        status: 'draft',
      },
    });

    // ───────────── Response ─────────────
    res.status(201).json({
      success: true,
      message: 'Project created successfully. Continue editing in the wizard.',
      project: {
        _id: String(created._id),
        slug: created.slug,
        projectName: created.projectName,
        city: created.city,
        area: created.area,
        status: created.status,
        developerBadge: created.developerBadge,
        editUrl: `/developer/projects/${created._id}/edit`,
        previewUrl: `/projects/${created.slug}`,
      },
    });
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : 'Unknown error';

    // Duplicate key (MongoDB unique constraint)
    if (
      err instanceof Error &&
      (err.message.includes('E11000') || err.message.includes('duplicate key'))
    ) {
      res.status(409).json({
        success: false,
        error: 'DUPLICATE_KEY',
        message: 'A project with similar details already exists',
      });
      return;
    }

    await logSecurityEvent({
      type: 'system_error',
      severity: 'medium',
      userId: req.headers['x-user-id'] as string,
      ip: getClientIp(req),
      userAgent: req.headers['user-agent'] as string,
      metadata: {
        action: 'project_create_failed',
        endpoint: '/api/projects',
        method: 'POST',
        reason: errMsg,
      },
    });

    res.status(500).json({
      success: false,
      error: 'INTERNAL_SERVER_ERROR',
      message: 'Failed to create project',
    });
  }
}

/**
 * pages/api/projects/my-projects.ts
 *
 * GET /api/projects/my-projects
 *
 * Returns the authenticated developer's own projects (dashboard list).
 * Supports dual pagination (cursor + page), filters, and sort.
 *
 * Access:
 *   - Developer: their own projects only
 *   - Admin: can pass ?developerId=xxx to view any developer's projects
 *
 * V5.0.0 — Aligned with Projects.ts model, requireAuth, Upstash rate limit
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose from 'mongoose';

import dbConnect from '@/lib/dbConnect';
import Project from '@/models/Projects';

import { requireAuth, getClientIp } from '@/lib/requireAuth';
import {
  rateLimitApi,
  setRateLimitHeaders,
  sendRateLimitResponse,
} from '@/lib/rateLimit';

// ─────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────

type ApiResponse = {
  success: boolean;
  message?: string;
  code?: string;
  projects?: unknown[];
  pagination?: Record<string, unknown>;
  cursor?: { next: string | null } | null;
};

type CursorPayload = {
  ts: string;   // ISO timestamp for primary sort field
  _id: string;  // tiebreaker
};

// ─────────────────────────────────────────────
// Security headers
// ─────────────────────────────────────────────

function setSecurityHeaders(res: NextApiResponse): void {
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=86400; includeSubDomains');
  // Dashboard data must never be cached
  res.setHeader('Cache-Control', 'no-store, max-age=0');
}

// ─────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────

function getString(q: string | string[] | undefined): string {
  if (!q) return '';
  return Array.isArray(q) ? String(q[0] ?? '') : String(q);
}

function clampInt(n: number, min: number, max: number): number {
  if (!Number.isFinite(n) || Number.isNaN(n)) return min;
  return Math.max(min, Math.min(max, n));
}

function escapeRegExp(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function isValidObjectId(id: string): boolean {
  return mongoose.Types.ObjectId.isValid(id) && /^[a-fA-F0-9]{24}$/.test(id);
}

function b64urlEncode(obj: CursorPayload): string {
  return Buffer.from(JSON.stringify(obj), 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function b64urlDecode(token: string): CursorPayload | null {
  try {
    const t = String(token).trim();
    if (!t) return null;
    let b64 = t.replace(/-/g, '+').replace(/_/g, '/');
    const pad = b64.length % 4;
    if (pad) b64 += '='.repeat(4 - pad);
    return JSON.parse(Buffer.from(b64, 'base64').toString('utf8')) as CursorPayload;
  } catch {
    return null;
  }
}

/**
 * Primary image: featureImageUrl → first isPrimary → first image
 */
function getPrimaryImage(p: Record<string, unknown>): string | null {
  if (typeof p.featureImageUrl === 'string' && p.featureImageUrl) {
    return p.featureImageUrl;
  }
  if (Array.isArray(p.images) && p.images.length > 0) {
    const imgs = p.images as Array<{ url?: string; isPrimary?: boolean }>;
    const primary = imgs.find((img) => img.isPrimary);
    return primary?.url ?? imgs[0]?.url ?? null;
  }
  return null;
}

// V5.0.0 valid enums — locked
const VALID_CATEGORIES = new Set([
  'highrise', 'society', 'mixed_use',
  'commercial_plaza', 'townhouse', 'gated_community',
]);
const VALID_NATURES  = new Set(['residential', 'commercial', 'mixed']);
const VALID_STATUSES = new Set(['draft', 'pending', 'verified', 'rejected']);

// Badge labels for response enrichment
const BADGE_LABELS: Record<string, string> = {
  new_entrant: '🆕 New Entrant',
  emerging:    '⭐ Emerging',
  trusted:     '🏆 Trusted Builder',
  premium:     '💎 Premium Developer',
};

// ─────────────────────────────────────────────
// Handler
// ─────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
): Promise<void> {
  setSecurityHeaders(res);

  if (req.method !== 'GET') {
    res.setHeader('Allow', 'GET');
    return void res.status(405).json({
      success: false,
      message: 'Method not allowed.',
      code: 'METHOD_NOT_ALLOWED',
    });
  }

  // ── Rate limit ──────────────────────────────
  const rl = await rateLimitApi(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) return void sendRateLimitResponse(res, rl);

  // ── Auth ────────────────────────────────────
  const authResult = await requireAuth(req, res);
  if (!authResult) return; // requireAuth sent 401

  const userId  = authResult.id;
  const role    = authResult.role;
  const isAdmin = role === 'admin';
  const ip      = getClientIp(req);

  // Only developer or admin can access this endpoint
  if (!isAdmin && role !== 'developer') {
    return void res.status(403).json({
      success: false,
      message: 'Only developer accounts can access project listings.',
      code: 'FORBIDDEN',
    });
  }

  await dbConnect();

  // ── Query params ────────────────────────────
  const {
    // Admin-only: view a specific developer's projects
    developerId: devIdParam,

    // Filters
    city,
    projectCategory,
    projectNature,
    status,
    search,
    isFeatured,

    // Deleted-mode (admin only)
    deleted,

    // Sort
    sortBy,
    sortDir,

    // Pagination
    cursor,
    page,
    limit,
  } = req.query;

  // ── Determine whose projects to show ────────
  let targetDeveloperId = userId; // default: own projects

  if (isAdmin && devIdParam) {
    const raw = getString(devIdParam).trim();
    if (!isValidObjectId(raw)) {
      return void res.status(400).json({
        success: false,
        message: 'Invalid developerId.',
        code: 'INVALID_DEVELOPER_ID',
      });
    }
    targetDeveloperId = raw;
  }

  // ── Deleted mode (admin only) ───────────────
  // Owners always see non-deleted only (trash.ts handles trashed view)
  let deletedMode: 'exclude' | 'only' | 'all' = 'exclude';
  if (isAdmin && deleted) {
    const d = getString(deleted).toLowerCase();
    if (d === 'all')   deletedMode = 'all';
    if (d === 'true')  deletedMode = 'only';
    if (d === 'false') deletedMode = 'exclude';
  }

  // ── Pagination ──────────────────────────────
  const limitNum    = clampInt(parseInt(getString(limit) || '20', 10), 1, 100);
  const cursorToken = getString(cursor).trim();
  const pageNum     = clampInt(parseInt(getString(page) || '1', 10), 1, 1_000_000);
  const useCursor   = Boolean(cursorToken);

  // ── Sort ────────────────────────────────────
  // LESSON #65: use Record<string, 1 | -1> not SortOrder
  const sortByVal  = getString(sortBy).toLowerCase();
  const sortDirVal = getString(sortDir).toLowerCase();

  const primarySortField = sortByVal === 'updatedat' ? 'updatedAt' : 'createdAt';
  const dir: 1 | -1      = sortDirVal === 'asc' ? 1 : -1;

  const sort: Record<string, 1 | -1> = {
    [primarySortField]: dir,
    _id: dir, // stable tiebreaker
  };

  // ── Build filter ─────────────────────────────
  // Projects.ts uses developerId as the canonical authenticated User reference.
  const andClauses: Record<string, unknown>[] = [];

  const filter: Record<string, unknown> = {
    developerId: new mongoose.Types.ObjectId(targetDeveloperId),
  };

  // Deleted filter
  if (deletedMode === 'exclude') andClauses.push({ isDeleted: { $ne: true } });
  if (deletedMode === 'only')    andClauses.push({ isDeleted: true });
  // 'all' → no clause

  // City filter
  const cityVal = getString(city).trim().slice(0, 80);
  if (cityVal) {
    andClauses.push({
      city: { $regex: new RegExp(`^${escapeRegExp(cityVal)}$`, 'i') },
    });
  }

  // Category filter — V5.0.0 has 6 categories
  const catVal = getString(projectCategory).toLowerCase().trim();
  if (catVal && VALID_CATEGORIES.has(catVal)) {
    andClauses.push({ projectCategory: catVal });
  }

  // Nature filter
  const natureVal = getString(projectNature).toLowerCase().trim();
  if (natureVal && VALID_NATURES.has(natureVal)) {
    andClauses.push({ projectNature: natureVal });
  }

  // Status filter — V5.0.0 enum only
  const statusVal = getString(status).toLowerCase().trim();
  if (statusVal && VALID_STATUSES.has(statusVal)) {
    andClauses.push({ status: statusVal });
  }

  // Featured filter
  const featuredVal = getString(isFeatured).toLowerCase();
  if (featuredVal === 'true')  andClauses.push({ isFeatured: true });
  if (featuredVal === 'false') andClauses.push({ isFeatured: { $ne: true } });

  // Search canonical Project fields.
  const searchVal = getString(search).trim().slice(0, 100);
  if (searchVal) {
    const rx = new RegExp(escapeRegExp(searchVal), 'i');
    andClauses.push({
      $or: [
        { projectName: rx },
        { city: rx },
        { area: rx },
        { tagline: rx },
      ],
    });
  }

  if (andClauses.length > 0) {
    filter.$and = andClauses;
  }

  // ── Cursor clause ────────────────────────────
  if (useCursor) {
    const parsed = b64urlDecode(cursorToken);

    if (!parsed?.ts || !parsed?._id || !isValidObjectId(parsed._id)) {
      return void res.status(400).json({
        success: false,
        message: 'Invalid or expired cursor.',
        code: 'INVALID_CURSOR',
      });
    }

    const tsDate = new Date(parsed.ts);
    if (!Number.isFinite(tsDate.getTime())) {
      return void res.status(400).json({
        success: false,
        message: 'Invalid cursor timestamp.',
        code: 'INVALID_CURSOR',
      });
    }

    const cursorId = new mongoose.Types.ObjectId(parsed._id);
    const op = dir === -1 ? '$lt' : '$gt';

    const cursorClause = {
      $or: [
        { [primarySortField]: { [op]: tsDate } },
        { [primarySortField]: tsDate, _id: { [op]: cursorId } },
      ],
    };

    const existing = (filter.$and as unknown[]) ?? [];
    filter.$and = [...existing, cursorClause];
  }

  // ── Projection (dashboard cards — least privilege) ──
  // No Cloudinary public_id in list view
  const projection = [
    '_id', 'slug', 'projectName',
    'city', 'area',
    'projectCategory', 'projectNature',
    'status', 'isFeatured', 'isVerified',
    'developerBadge',
    'featureImageUrl',
    'images.url', 'images.isPrimary',
    'minPrice', 'maxPrice', 'priceRangeText',
    'totalUnits',
    'unitTypeBreakdown.availableUnits',
    'unitTypeBreakdown.soldUnits',
    'unitTypeBreakdown.viewCount',
    'unitTypeBreakdown.inquiryCount',
    'developmentProgress',
    'expectedCompletionDate',
    'createdAt', 'updatedAt',
    // Admin/deleted extra fields
    ...(deletedMode !== 'exclude' || isAdmin ? ['isDeleted', 'deletedAt'] : []),
    ...(isAdmin ? ['rejectionReason', 'verifiedAt', 'verifiedBy'] : []),
  ].join(' ');

  // ── Execute query ────────────────────────────
  try {
    const docs = await Project.find(filter)
      .sort(sort)
      .select(projection)
      .limit(useCursor ? limitNum + 1 : limitNum)
      .skip(useCursor ? 0 : (pageNum - 1) * limitNum)
      .maxTimeMS(3000)
      .lean();

    // ── Cursor: detect hasMore ───────────────
    let hasMore = false;
    let rows    = docs;

    if (useCursor && docs.length > limitNum) {
      hasMore = true;
      rows    = docs.slice(0, limitNum);
    }

    // ── Enrich rows ──────────────────────────
    const projects = rows.map((p) => {
      const proj = p as Record<string, unknown>;
      const badge = String(proj.developerBadge ?? 'new_entrant');
      return {
        ...proj,
        primaryImage: getPrimaryImage(proj),
        badgeLabel:   BADGE_LABELS[badge] ?? badge,
        // Price formatting (PKR)
        priceFormatted: formatPriceRange(
          proj.minPrice as number | undefined,
          proj.maxPrice as number | undefined,
        ),
      };
    });

    // ── Build next cursor ────────────────────
    let nextCursor: string | null = null;
    if (useCursor && hasMore && projects.length > 0) {
      const last = projects[projects.length - 1] as Record<string, unknown>;
      const ts   = (primarySortField === 'updatedAt' ? last.updatedAt : last.createdAt) as
        | string
        | Date
        | undefined;

      nextCursor = b64urlEncode({
        ts:  ts ? new Date(ts as string).toISOString() : new Date().toISOString(),
        _id: String(last._id),
      });
    }

    // ── Cursor mode response ─────────────────
    if (useCursor) {
      return void res.status(200).json({
        success: true,
        projects,
        pagination: {
          mode:    'cursor',
          limit:   limitNum,
          hasMore,
          count:   projects.length,
        },
        cursor: { next: hasMore ? nextCursor : null },
      });
    }

    // ── Page mode response ───────────────────
    const total = await Project.countDocuments(filter).maxTimeMS(3000);
    const pages = Math.max(1, Math.ceil(total / limitNum));

    return void res.status(200).json({
      success: true,
      projects,
      pagination: {
        mode:    'page',
        page:    pageNum,
        limit:   limitNum,
        total,
        pages,
        hasNext: pageNum < pages,
        hasPrev: pageNum > 1,
        count:   projects.length,
      },
      cursor: null,
    });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    void ip; // consumed for future audit log

    return void res.status(500).json({
      success: false,
      message: 'Failed to fetch projects.',
      code:    'SERVER_ERROR',
    });
  }
}

// ─────────────────────────────────────────────
// PKR price formatter
// ─────────────────────────────────────────────

function formatPKR(amount: number): string {
  if (amount >= 10_000_000) return `${(amount / 10_000_000).toFixed(2)} Crore`;
  if (amount >= 100_000)    return `${(amount / 100_000).toFixed(2)} Lac`;
  if (amount >= 1_000)      return `${(amount / 1_000).toFixed(1)}K`;
  return String(amount);
}

function formatPriceRange(
  min: number | undefined,
  max: number | undefined,
): string | null {
  if (!min && !max) return null;
  if (min && max)   return `${formatPKR(min)} – ${formatPKR(max)}`;
  if (min)          return `From ${formatPKR(min)}`;
  if (max)          return `Up to ${formatPKR(max)}`;
  return null;
}

