    infrastructure?: number;
    livability?: number;
    overall?: number;
  };
  featuredImage?: string;
  riskAlerts?: Array<{ isResolved: boolean }>;
  isVerifiedByHighrise?: boolean;
  isFeatured?: boolean;
  viewCount?: number;
  developerName?: string;
  launchYear?: number;
  possessionPercentage?: number;
}

// ─── Types ────────────────────────────────────────────────────────────────────

interface SocietyListItem {
  _id: string;
  name: string;
  slug: string;
  city: string;
  areaName: string;
  category: string;
  nocStatus: string;
  approvalAuthority: string;
  overallRiskLevel: string;
  scores: {
    legal: number;
    growth: number;
    possession: number;
    infrastructure: number;
    livability: number;
    overall: number;
  };
  featuredImage?: string;
  activeAlertCount: number;
  isVerifiedByHighrise: boolean;
  isFeatured: boolean;
  viewCount: number;
  developerName?: string;
  launchYear?: number;
  possessionPercentage?: number;
}

interface PaginatedResponse {
  success: boolean;
  data?: {
    societies: SocietyListItem[];
    pagination: {
      page: number;
      limit: number;
      total: number;
      pages: number;
      hasNext: boolean;
      hasPrev: boolean;
    };
    filters: {
      cities: string[];
      authorities: string[];
      nocStatuses: string[];
    };
  };
  error?: string;
  message?: string;
}

// ─── Constants ────────────────────────────────────────────────────────────────

const VALID_SORT_FIELDS = [
  'overallScore',
  'legalScore',
  'growthScore',
  'name',
  'viewCount',
  'createdAt',
  'launchYear',
] as const;

const VALID_NOC_STATUSES = [
  'approved',
  'pending',
  'under_review',
  'illegal',
  'disputed',
  'cancelled',
  'expired',
] as const;

const VALID_RISK_LEVELS = ['safe', 'caution', 'high_risk', 'avoid'] as const;
const VALID_CATEGORIES = [
  'housing_scheme',
  'gated_community',
  'apartment_complex',
  'commercial_zone',
  'mixed_use',
  'industrial_zone',
  'township',
] as const;

const MAX_LIMIT = 50;
const DEFAULT_LIMIT = 20;

// ─── Handler ──────────────────────────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<PaginatedResponse>
): Promise<void> {
  // Method check
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    res.status(405).json({ success: false, error: 'Method not allowed' });
    return;
  }

  // Rate limit (public endpoint — uses API_SEARCH: 60 req/min)
  const rl = await rateLimitSearch(req);
  setRateLimitHeaders(res, rl);

  if (!rl.ok) {
    res.status(429).json({
      success: false,
      error: 'Too many requests. Please try again shortly.',
    });
    return;
  }

  try {
    await dbConnect();

    // ─── Parse Query Params ───────────────────────────────────────────────────

    const {
      search = '',
      city = '',
      nocStatus = '',
      riskLevel = '',
      category = '',
      authority = '',
      isVerified = '',
      isFeatured = '',
      minScore = '',
      sortBy = 'overallScore',
      sortOrder = 'desc',
      page = '1',
      limit = String(DEFAULT_LIMIT),
    } = req.query;

    // Validate + normalize pagination
    const pageNum = Math.max(1, parseInt(String(page), 10) || 1);
    const limitNum = Math.min(MAX_LIMIT, Math.max(1, parseInt(String(limit), 10) || DEFAULT_LIMIT));
    const skip = (pageNum - 1) * limitNum;

    // ─── Build Filter ─────────────────────────────────────────────────────────

    const filter: FilterQuery<Record<string, unknown>> = {
      isPublished: true,
    };

    // Text search (uses text index)
    const searchStr = String(search).trim();
    if (searchStr.length > 0) {
      filter.$text = { $search: searchStr };
    }

    // City filter
    if (city && typeof city === 'string') {
      filter.city = { $regex: `^${escapeRegex(city)}$`, $options: 'i' };
    }

    // NOC status
    if (nocStatus && VALID_NOC_STATUSES.includes(nocStatus as (typeof VALID_NOC_STATUSES)[number])) {
      filter.nocStatus = nocStatus;
    }

    // Risk level
    if (riskLevel && VALID_RISK_LEVELS.includes(riskLevel as (typeof VALID_RISK_LEVELS)[number])) {
      filter.overallRiskLevel = riskLevel;
    }

    // Category
    if (category && VALID_CATEGORIES.includes(category as (typeof VALID_CATEGORIES)[number])) {
      filter.category = category;
    }

    // Approval authority
    if (authority && typeof authority === 'string') {
      filter.approvalAuthority = authority;
    }

    // Verified by Highrise
    if (isVerified === 'true') {
      filter.isVerifiedByHighrise = true;
    }

    // Featured
    if (isFeatured === 'true') {
      filter.isFeatured = true;
    }

    // Minimum overall score
    const minScoreNum = parseInt(String(minScore), 10);
    if (!isNaN(minScoreNum) && minScoreNum > 0 && minScoreNum <= 100) {
      filter['scores.overall'] = { $gte: minScoreNum };
    }

    // ─── Build Sort ───────────────────────────────────────────────────────────

    const sortFieldMap: Record<string, string> = {
      overallScore: 'scores.overall',
      legalScore: 'scores.legal',
      growthScore: 'scores.growth',
      name: 'name',
      viewCount: 'viewCount',
      createdAt: 'createdAt',
      launchYear: 'launchYear',
    };

    const sortField = sortFieldMap[String(sortBy)] || 'scores.overall';
    const sortDir: 1 | -1 = String(sortOrder).toLowerCase() === 'asc' ? 1 : -1;

    const sort: Record<string, 1 | -1> = searchStr.length > 0
      ? { score: { $meta: 'textScore' } as unknown as 1, [sortField]: sortDir }
      : { [sortField]: sortDir };

    // ─── Query Execution ──────────────────────────────────────────────────────

    const projection = searchStr.length > 0
      ? { score: { $meta: 'textScore' } }
      : {};

    const [societies, total, filterOptions] = await Promise.all([
      Society.find(filter, projection)
        .sort(sort)
        .skip(skip)
        .limit(limitNum)
        .select(
          '_id name slug city areaName category nocStatus approvalAuthority ' +
          'overallRiskLevel scores featuredImage riskAlerts ' +
          'isVerifiedByHighrise isFeatured viewCount developerName ' +
          'launchYear possessionPercentage'
        )
        .lean(),
      Society.countDocuments(filter),
      // Filter options for UI dropdowns
      Society.aggregate([
        { $match: { isPublished: true } },
        {
          $group: {
            _id: null,
            cities: { $addToSet: '$city' },
            authorities: { $addToSet: '$approvalAuthority' },
            nocStatuses: { $addToSet: '$nocStatus' },
          },
        },
      ]),
    ]);

    // ─── Increment search count (fire-and-forget) ────────────────────────────

    if (searchStr.length > 0 && societies.length > 0) {
      const ids = (societies as unknown as Array<{ _id: unknown }>).map((s) => s._id);
      Society.updateMany(
        { _id: { $in: ids } },
        { $inc: { searchCount: 1 } }
      ).catch(() => {
        // silent — non-critical
      });
    }

    // ─── Transform results ────────────────────────────────────────────────────

    const transformed: SocietyListItem[] = (societies as unknown as SocietyDoc[]).map(
      (society) => {
        const activeAlertCount = Array.isArray(society.riskAlerts)
          ? society.riskAlerts.filter((a) => !a.isResolved).length
          : 0;

        return {
          _id: String(society._id),
          name: society.name,
          slug: society.slug,
          city: society.city,
          areaName: society.areaName,
          category: society.category,
          nocStatus: society.nocStatus,
          approvalAuthority: society.approvalAuthority,
          overallRiskLevel: society.overallRiskLevel,
          scores: {
            legal: society.scores?.legal ?? 0,
            growth: society.scores?.growth ?? 0,
            possession: society.scores?.possession ?? 0,
            infrastructure: society.scores?.infrastructure ?? 0,
            livability: society.scores?.livability ?? 0,
            overall: society.scores?.overall ?? 0,
          },
          featuredImage: society.featuredImage,
          activeAlertCount,
          isVerifiedByHighrise: Boolean(society.isVerifiedByHighrise),
          isFeatured: Boolean(society.isFeatured),
          viewCount: society.viewCount ?? 0,
          developerName: society.developerName,
          launchYear: society.launchYear,
          possessionPercentage: society.possessionPercentage,
        };
      }
    );

    const opts = filterOptions[0] ?? { cities: [], authorities: [], nocStatuses: [] };

    // ─── Response ─────────────────────────────────────────────────────────────

    // Cache for 60 seconds (public data)
    res.setHeader('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');

    res.status(200).json({
      success: true,
      data: {
        societies: transformed,
        pagination: {
          page: pageNum,
          limit: limitNum,
          total,
          pages: Math.ceil(total / limitNum),
          hasNext: pageNum * limitNum < total,
          hasPrev: pageNum > 1,
        },
        filters: {
          cities: (opts.cities ?? []).filter(Boolean).sort(),
          authorities: (opts.authorities ?? []).filter(Boolean).sort(),
          nocStatuses: (opts.nocStatuses ?? []).filter(Boolean).sort(),
        },
      },
    });
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : 'Unknown error';

    await logSecurityEvent({
      type: 'system_error',
      severity: 'medium',
      ip: getClientIp(req),
      req,
      metadata: {
        endpoint: '/api/societies',
        method: 'GET',
        errorMessage: `Society listing failed: ${errorMessage}`,
      },
    }).catch(() => {
      // silent
    });

    res.status(500).json({
      success: false,
      error: 'Failed to fetch societies. Please try again.',
    });
  }
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// pages/api/society/plots.ts
// Highrise.pk — Society Portal: Plot Inventory API
// GET   → return plotInventory array for own society
// POST  → add new plot inventory entry
// PATCH → update existing entry by size key
// DELETE→ remove entry by size key
// NO console.* | NO as any | NO findByIdAndUpdate

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import SocietyProfile from '@/models/SocietyProfile';
import type { IPlotInventory, SocietyPlotSize } from '@/models/SocietyProfile';
import { requireSociety } from '@/lib/requireAuth';
import { z } from 'zod';
import mongoose from 'mongoose';
import type { Types } from 'mongoose';

// ─── Response types ───────────────────────────────────────────────────────────

interface ApiResponse {
  success: boolean;
  plots?: IPlotInventory[];
  message?: string;
  errors?: Record<string, string[]>;
}

// ─── Plot size enum ───────────────────────────────────────────────────────────

const PLOT_SIZE_VALUES = [
  '3_marla', '4_marla', '5_marla', '6_marla', '7_marla',
  '8_marla', '10_marla', '12_marla', '1_kanal', '1_kanal_4_marla',
  '2_kanal', 'commercial', 'other',
] as const;

// ─── Validation schemas ───────────────────────────────────────────────────────

const PlotEntrySchema = z.object({
  size: z.enum(PLOT_SIZE_VALUES),
  totalPlots: z.number().int().min(0).max(100000),
  availablePlots: z.number().int().min(0).max(100000),
  pricePerMarla: z.number().min(0).optional(),
  pricePerSqFt: z.number().min(0).optional(),
}).refine(
  (d) => d.availablePlots <= d.totalPlots,
  { message: 'Available plots cannot exceed total plots.', path: ['availablePlots'] }
);

const PatchPlotSchema = z.object({
  size: z.enum(PLOT_SIZE_VALUES),                         // identifies which entry
  totalPlots: z.number().int().min(0).max(100000).optional(),
  availablePlots: z.number().int().min(0).max(100000).optional(),
  pricePerMarla: z.number().min(0).optional(),
  pricePerSqFt: z.number().min(0).optional(),
});

const DeletePlotSchema = z.object({
  size: z.enum(PLOT_SIZE_VALUES),
});

// ─── Handler ──────────────────────────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
): Promise<void> {
  const authResult = await requireSociety(req, res);
  if (!authResult) return;

  await dbConnect();

  const userId = new mongoose.Types.ObjectId(authResult.id);

  // ── GET ───────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const profile = await SocietyProfile
      .findOne({ userId })
      .select('plotInventory')
      .lean<{ plotInventory: IPlotInventory[] }>();

    if (!profile) {
      res.status(404).json({ success: false, message: 'Society profile not found.' });
      return;
    }

    res.status(200).json({ success: true, plots: profile.plotInventory });
    return;
  }

  // ── POST — add new entry ─────────────────────────────────────────────────
  if (req.method === 'POST') {
    const parsed = PlotEntrySchema.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({
        success: false,
        message: 'Validation failed.',
        errors: parsed.error.flatten().fieldErrors as Record<string, string[]>,
      });
      return;
    }

    const profile = await SocietyProfile.findOne({ userId });
    if (!profile) {
      res.status(404).json({ success: false, message: 'Society profile not found.' });
      return;
    }

    // Reject duplicate size entries
    const exists = profile.plotInventory.some((p) => p.size === parsed.data.size);
    if (exists) {
      res.status(409).json({
        success: false,
        message: `A plot entry for size "${parsed.data.size}" already exists. Use PATCH to update it.`,
      });
      return;
    }

    profile.plotInventory.push(parsed.data as IPlotInventory);
    profile.auditTrail.push({
      action: 'updated',
      performedBy: userId,
      performedAt: new Date(),
      note: `Plot inventory entry added: ${parsed.data.size}`,
    });

    await profile.save();

    res.status(201).json({ success: true, plots: profile.plotInventory });
    return;
  }

  // ── PATCH — update existing entry ────────────────────────────────────────
  if (req.method === 'PATCH') {
    const parsed = PatchPlotSchema.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({
        success: false,
        message: 'Validation failed.',
        errors: parsed.error.flatten().fieldErrors as Record<string, string[]>,
      });
      return;
    }

    const profile = await SocietyProfile.findOne({ userId });
    if (!profile) {
      res.status(404).json({ success: false, message: 'Society profile not found.' });
      return;
    }

    const entry = profile.plotInventory.find((p) => p.size === parsed.data.size);
    if (!entry) {
      res.status(404).json({
        success: false,
        message: `No plot inventory entry found for size "${parsed.data.size}".`,
      });
      return;
    }

    // Apply partial updates
    if (parsed.data.totalPlots !== undefined) entry.totalPlots = parsed.data.totalPlots;
    if (parsed.data.availablePlots !== undefined) entry.availablePlots = parsed.data.availablePlots;
    if (parsed.data.pricePerMarla !== undefined) entry.pricePerMarla = parsed.data.pricePerMarla;
    if (parsed.data.pricePerSqFt !== undefined) entry.pricePerSqFt = parsed.data.pricePerSqFt;

    // Validate constraint after update
    if (entry.availablePlots > entry.totalPlots) {
      res.status(400).json({
        success: false,
        message: 'Available plots cannot exceed total plots.',
      });
      return;
    }

    profile.auditTrail.push({
      action: 'updated',
      performedBy: userId,
      performedAt: new Date(),
      note: `Plot inventory updated: ${parsed.data.size}`,
    });

    await profile.save();

    res.status(200).json({ success: true, plots: profile.plotInventory });
    return;
  }

  // ── DELETE — remove entry ─────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    const parsed = DeletePlotSchema.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({
        success: false,
        message: 'Validation failed.',
        errors: parsed.error.flatten().fieldErrors as Record<string, string[]>,
      });
      return;
    }

    const profile = await SocietyProfile.findOne({ userId });
    if (!profile) {
      res.status(404).json({ success: false, message: 'Society profile not found.' });
      return;
    }

    const before = profile.plotInventory.length;
    profile.plotInventory = profile.plotInventory.filter(
      (p) => p.size !== parsed.data.size
    ) as IPlotInventory[];

    if (profile.plotInventory.length === before) {
      res.status(404).json({
        success: false,
        message: `No plot entry found for size "${parsed.data.size}".`,
      });
      return;
    }

    profile.auditTrail.push({
      action: 'updated',
      performedBy: userId,
      performedAt: new Date(),
      note: `Plot inventory entry removed: ${parsed.data.size}`,
    });

    await profile.save();

    res.status(200).json({ success: true, plots: profile.plotInventory });
    return;
  }

  res.status(405).json({ success: false, message: 'Method not allowed.' });
}

// pages/api/society/profile.ts
// Highrise.pk — Society Portal: Own Profile API
// GET  → return own SocietyProfile (requireSociety guard)
// PATCH → update allowed fields only (findOne + save)
// NO console.* | NO as any | NO findByIdAndUpdate | NO plain CNIC

import type { NextApiRequest, NextApiResponse } from 'next';
import dbConnect from '@/lib/dbConnect';
import SocietyProfile from '@/models/SocietyProfile';
import type { ISocietyProfile, SocietyAmenity } from '@/models/SocietyProfile';
import { requireSociety } from '@/lib/requireAuth';
import type { AuthToken } from '@/lib/requireAuth';
import { z } from 'zod';
import mongoose from 'mongoose';

// ─── Lean shape ───────────────────────────────────────────────────────────────

interface SocietyProfileLean {
  _id: mongoose.Types.ObjectId;
  userId: mongoose.Types.ObjectId;
  status: string;
  infoRequiredReason?: string;
  rejectionReason?: string;
  suspensionReason?: string;
  societyName: string;
  registeredName: string;
  slug: string;
  city: string;
  areaName: string;
  fullAddress: string;
  authority: string;
  nocNumber: string;
  nocIssuanceDate?: Date;
  nocExpiryDate?: Date;
  totalAreaAcres?: number;
  launchYear?: number;
  authorizedPersonName: string;
  authorizedPersonDesignation: string;
  authorizedPersonPhone: string;
  authorizedPersonEmail: string;
  ntcNumber?: string;
  fbrNtn?: string;
  strn?: string;
  bankAccountTitle?: string;
  bankName?: string;
  officePhone: string;
  officeEmail: string;
  websiteUrl?: string;
  blocks: Array<{
    _id: mongoose.Types.ObjectId;
    name: string;
    totalPlots: number;
    availablePlots: number;
    plotSizes: string[];
    possessionStatus: string;
    launchYear?: number;
    completionYear?: number;
  }>;
  plotInventory: Array<{
    size: string;
    totalPlots: number;
    availablePlots: number;
    pricePerMarla?: number;
    pricePerSqFt?: number;
  }>;
  amenities: string[];
  installmentPlans: Array<{
    _id: mongoose.Types.ObjectId;
    planName: string;
    durationMonths: number;
    downPaymentPercent: number;
    monthlyInstallmentPercent?: number;
    quarterlyInstallmentPercent?: number;
    halfYearlyInstallmentPercent?: number;
    balloonPaymentPercent?: number;
    isInterestFree: boolean;
    notes?: string;
  }>;
  kycDocuments: Array<{
    _id: mongoose.Types.ObjectId;
    type: string;
    title: string;
    url: string;
    uploadedAt: Date;
  }>;
  cnicVerified: boolean;
  nocVerified: boolean;
  kycStatus: string;
  trustScore: number;
  badges: string[];
  submittedAt?: Date;
  verifiedAt?: Date;
  createdAt: Date;
  updatedAt: Date;
}

// ─── Response type ────────────────────────────────────────────────────────────

interface ApiResponse {
  success: boolean;
  profile?: SocietyProfileLean;
  message?: string;
  errors?: Record<string, string[]>;
}

// ─── PATCH validation schema ──────────────────────────────────────────────────

const AMENITY_VALUES = [
  'mosque', 'school', 'hospital', 'park', 'community_center',
  'commercial_area', 'security_gate', 'cctv', 'underground_electricity',
  'gas', 'water_supply', 'sewerage', 'gymnasium', 'swimming_pool',
  'sports_complex', 'cinema', 'food_court', 'playground', 'jogging_track',
  'library', 'graveyard', 'car_parking', 'visitor_parking',
  'fire_station', 'police_post',
] as const;

const PatchSchema = z.object({
  officePhone: z.string().min(10).max(20).optional(),
  officeEmail: z.string().email().max(200).optional(),
  websiteUrl: z.string().url().max(500).optional().or(z.literal('')),
  amenities: z.array(z.enum(AMENITY_VALUES)).max(25).optional(),
  bankAccountTitle: z.string().max(200).optional(),
  bankName: z.string().max(100).optional(),
}).strict();

type PatchBody = z.infer<typeof PatchSchema>;

// ─── Handler ──────────────────────────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
): Promise<void> {
  // ── Auth ──────────────────────────────────────────────────────────────────
  const authResult = await requireSociety(req, res);
  if (!authResult) return;

  await dbConnect();

  // ── GET ───────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const profile = await SocietyProfile
      .findOne({ userId: new mongoose.Types.ObjectId(authResult.id) })
      .lean<SocietyProfileLean>();

    if (!profile) {
      res.status(404).json({ success: false, message: 'Society profile not found.' });
      return;
    }

    res.status(200).json({ success: true, profile });
    return;
  }

  // ── PATCH ─────────────────────────────────────────────────────────────────
  if (req.method === 'PATCH') {
    const parsed = PatchSchema.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({
        success: false,
        message: 'Validation failed.',
        errors: parsed.error.flatten().fieldErrors as Record<string, string[]>,
      });
      return;
    }

    const data: PatchBody = parsed.data;

    // findOne + save (Rule: never findByIdAndUpdate for mutations)
    const profile = await SocietyProfile.findOne({
      userId: new mongoose.Types.ObjectId(authResult.id),
    });

    if (!profile) {
      res.status(404).json({ success: false, message: 'Society profile not found.' });
      return;
    }

    // Apply only allowed fields
    if (data.officePhone !== undefined) profile.officePhone = data.officePhone;
    if (data.officeEmail !== undefined) profile.officeEmail = data.officeEmail;
    if (data.websiteUrl !== undefined) profile.websiteUrl = data.websiteUrl || undefined;
    if (data.amenities !== undefined) {
      profile.amenities = data.amenities as SocietyAmenity[];
    }
    if (data.bankAccountTitle !== undefined) profile.bankAccountTitle = data.bankAccountTitle;
    if (data.bankName !== undefined) profile.bankName = data.bankName;

    // Audit trail entry for self-update
    profile.auditTrail.push({
      action: 'updated',
      performedBy: new mongoose.Types.ObjectId(authResult.id),
      performedAt: new Date(),
      note: 'Profile updated by society admin via portal.',
    });

    await profile.save();

    // Return lean result (no encrypted fields — toJSON transform strips them)
    const updated = await SocietyProfile
      .findOne({ userId: new mongoose.Types.ObjectId(authResult.id) })
      .lean<SocietyProfileLean>();

    res.status(200).json({ success: true, profile: updated ?? undefined });
    return;
  }

  res.status(405).json({ success: false, message: 'Method not allowed.' });
}

