import type { NextApiRequest, NextApiResponse } from 'next';
import mongoose, { type SortOrder } from 'mongoose';

import dbConnect from '@/lib/dbConnect';
import Unit from '@/models/Unit';
import { getOptionalAuth } from '@/lib/optionalAuth';
import {
  rateLimitApi,
  sendRateLimitResponse,
  setRateLimitHeaders,
} from '@/lib/rateLimit';
import { logSecurityEvent } from '@/lib/security/logSecurityEvent';

type AuthedSession = {
  id: string;
  email: string;
  role: string;
} | null;

// =============================
// Security headers
// =============================
function setSecurityHeaders(res: NextApiResponse) {
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader(
    'Permissions-Policy',
    'geolocation=(), microphone=(), camera=(), payment=(), usb=(), interest-cohort=()'
  );
  res.setHeader('X-DNS-Prefetch-Control', 'off');
  res.setHeader('Strict-Transport-Security', 'max-age=86400; includeSubDomains; preload');
  res.setHeader('Vary', 'Accept-Encoding');
}

// =============================
// Helpers
// =============================
function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  const first = (ip || '').split(',')[0]?.trim();
  return first || (req.socket?.remoteAddress || '0.0.0.0');
}

// bumpRate removed — using Upstash rateLimitApi() instead

function normalizeString(v: any, maxLen = 80) {
  if (typeof v !== 'string') return '';
  const s = v.trim();
  if (!s) return '';
  return s.length > maxLen ? s.slice(0, maxLen) : s;
}

function clampInt(v: any, def: number, min: number, max: number) {
  const n = Number(v);
  if (!Number.isFinite(n)) return def;
  return Math.max(min, Math.min(max, Math.trunc(n)));
}

function parseBool(v: any): boolean | null {
  const s = String(v ?? '').toLowerCase().trim();
  if (['true', '1', 'yes', 'y', 'on'].includes(s)) return true;
  if (['false', '0', 'no', 'n', 'off'].includes(s)) return false;
  return null;
}

function isValidObjectId(id: string): boolean {
  return /^[a-fA-F0-9]{24}$/.test(id);
}

function isAdminSession(session: AuthedSession): boolean {
  if (!session) return false;
  const role = String(session.role || '').toLowerCase();
  return role === 'admin' || role === 'superadmin';
}

function computePublicAllowed(project: any): boolean {
  const status = String(project?.status || '').toLowerCase();
  const verificationStatus = String(project?.verificationStatus || '').toLowerCase();

  return (
    project?.isVerified === true ||
    (status === 'verified' && verificationStatus === 'verified')
  );
}

/**
 * Cursor payload for stable sort: createdAt desc, _id desc
 * base64url (no padding)
 */
type CursorPayload = { createdAt: string; _id: string };

function b64urlEncode(obj: any): string {
  const json = JSON.stringify(obj);
  return Buffer.from(json, 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function b64urlDecode<T = any>(token: string): T | null {
  try {
    const t = String(token || '').trim();
    if (!t) return null;

    let b64 = t.replace(/-/g, '+').replace(/_/g, '/');
    const pad = b64.length % 4;
    if (pad) b64 += '='.repeat(4 - pad);

    const raw = Buffer.from(b64, 'base64').toString('utf8');
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

// =============================
// Handler
// =============================
export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  setSecurityHeaders(res);

  if (req.method !== 'GET') {
    res.setHeader('Allow', 'GET');
    return res.status(405).json({ success: false, message: 'Method not allowed' });
  }

  // Optional auth: public inventory remains crawlable; owner/admin previews are DB-validated.
  const auth = await getOptionalAuth(req);

  // ── Rate limit (Upstash) ──
  const rl = await rateLimitApi(req);
  setRateLimitHeaders(res, rl);
  if (!rl.ok) return sendRateLimitResponse(res, rl);

  const projectIdRaw = req.query.projectId;
  const projectId = typeof projectIdRaw === 'string' ? projectIdRaw.trim() : '';
  if (!projectId || !isValidObjectId(projectId)) {
    return res.status(400).json({ success: false, message: 'Invalid project ID' });
  }

  // ✅ Reuse ObjectId instance (performance + consistency)
  const projectObjectId = new mongoose.Types.ObjectId(projectId);

  try {
    await dbConnect();

    // ── Session from requireAuth (already verified above) ──
    const isAdmin = !!auth && ['admin', 'superadmin'].includes(String(auth.role));
    const actorId = auth && isValidObjectId(auth.id) ? auth.id : '';

    // ── Load project for gating (registry pattern) ──
    const Project = mongoose.models.Project as mongoose.Model<mongoose.Document>;
    if (!Project) {
      return res.status(500).json({ success: false, message: 'Something went wrong' });
    }

    const project = await Project
      .findById(projectId)
      .select('_id developerId status verificationStatus isVerified isDeleted deletedAt')
      .maxTimeMS(2500)
      .lean() as {
        _id: mongoose.Types.ObjectId;
        developerId?: mongoose.Types.ObjectId;
        status?: string;
        verificationStatus?: string;
        isVerified?: boolean;
        isDeleted?: boolean;
        deletedAt?: Date;
      } | null;

    // Safe 404 (anti-enumeration)
    if (!project) return res.status(404).json({ success: false, message: 'Not found' });

    const projectDeleted = project.isDeleted === true || !!project.deletedAt;
    if (projectDeleted && !isAdmin) {
      return res.status(404).json({ success: false, message: 'Not found' });
    }

    const isOwner = actorId ? String(project.developerId) === actorId : false;
    const publicAllowed = computePublicAllowed(project);

    if (!publicAllowed && !(isAdmin || isOwner)) {
      // Do not leak existence
      return res.status(404).json({ success: false, message: 'Not found' });
    }

    // ===== Query params (validated) =====
    const category = normalizeString(req.query.category, 24);
    const unitType = normalizeString(req.query.unitType, 32);
    const status = normalizeString(req.query.status, 24);
    const q = normalizeString(req.query.q, 60);

    const floorNumber = normalizeString(req.query.floorNumber, 12);
    const bedrooms = normalizeString(req.query.bedrooms, 12);

    const minPrice = normalizeString(req.query.minPrice, 20);
    const maxPrice = normalizeString(req.query.maxPrice, 20);

    const isCorner = parseBool(req.query.isCorner);
    const isFeatured = parseBool(req.query.isFeatured);

    // ===== Dual pagination (LOCKED) =====
     const limit = clampInt(req.query.limit, 50, 1, 100);
    const page = clampInt(req.query.page, 1, 1, 1_000_000);
    const cursor = normalizeString(req.query.cursor, 600);
    const mode: 'page' | 'cursor' = cursor ? 'cursor' : 'page';

    // Sort allowlist (public-safe)
    const sortBy = normalizeString(req.query.sortBy, 24) || 'createdAt';
    const sortOrder = (normalizeString(req.query.sortOrder, 8) || 'desc').toLowerCase();

    const allowedSortFields = new Set(['unitNumber', 'floorNumber', 'price', 'area', 'createdAt']);
    const sortField = allowedSortFields.has(sortBy) ? sortBy : 'createdAt';
    const dir: SortOrder = sortOrder === 'asc' ? 1 : -1;

    // Enterprise: cursor mode ONLY supported for createdAt sort (stable, no-skip)
    if (mode === 'cursor' && sortField !== 'createdAt') {
      return res.status(400).json({
        success: false,
        message: 'Cursor mode supports sortBy=createdAt only.',
        code: 'CURSOR_SORT_UNSUPPORTED',
      });
    }

    // Stable sort with tie-breaker for cursor safety
    const sort: Record<string, SortOrder> =
      sortField === 'createdAt'
        ? { createdAt: dir, _id: dir }
        : { [sortField]: dir, createdAt: -1, _id: -1 };

    // ===== Base filter =====
    const filter: any = {
      projectId: projectObjectId,
      isDeleted: { $ne: true },
    };

    // Never expose draft/unpublished unit inventory to ordinary visitors.
    if (!isAdmin && !isOwner) filter.isPublished = true;

    // Optional filters (validated)
    if (category) filter.category = category;
    if (unitType) filter.unitType = unitType;

    // Status allowlist
    if (status) {
      const s = status.toLowerCase();
      const allowedStatuses = new Set(['available', 'reserved', 'sold', 'on_hold']);
      if (!allowedStatuses.has(s)) {
        return res.status(400).json({ success: false, message: 'Invalid status' });
      }
      filter.status = s;
    }

    if (floorNumber) {
      const fn = Number(floorNumber);
      if (Number.isFinite(fn)) filter.floorNumber = Math.trunc(fn);
    }

    if (bedrooms) {
      const bd = Number(bedrooms);
      if (Number.isFinite(bd)) filter.bedrooms = Math.trunc(bd);
    }

    if (isCorner === true) filter.isCorner = true;
    if (isFeatured === true) filter.isFeatured = true;

    if (minPrice || maxPrice) {
      const mp = minPrice ? Number(minPrice) : NaN;
      const xp = maxPrice ? Number(maxPrice) : NaN;
      filter.price = {};
      if (Number.isFinite(mp)) filter.price.$gte = Math.max(0, mp);
      if (Number.isFinite(xp)) filter.price.$lte = Math.max(0, xp);
      if (Object.keys(filter.price).length === 0) delete filter.price;
    }

    // Text search (safe regex)
    if (q) {
      const safe = q.slice(0, 60).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const rx = new RegExp(safe, 'i');

      // Enterprise: schema-safe fields for unit search (no assumptions like title/slug)
      filter.$or = [
        { unitNumber: rx },
        { unitType: rx },
        { unitTypeName: rx },
        { category: rx },
        { floorName: rx },
        { tower: rx },
      ];
    }

    // ===== Cursor mode apply (createdAt desc, _id desc) =====
    let cursorApplied = false;

    if (mode === 'cursor') {
      const parsed = b64urlDecode<CursorPayload>(cursor);
      if (!parsed?.createdAt || !parsed?._id) {
        return res.status(400).json({ success: false, message: 'Invalid cursor' });
      }

      const createdAtDate = new Date(parsed.createdAt);
      if (!Number.isFinite(createdAtDate.getTime()) || !isValidObjectId(parsed._id)) {
        return res.status(400).json({ success: false, message: 'Invalid cursor' });
      }

      const cursorObjectId = new mongoose.Types.ObjectId(parsed._id);

      // For DESC (default) sort by createdAt/_id, fetch next after cursor:
      // (createdAt < cursorCreatedAt) OR (createdAt == cursorCreatedAt AND _id < cursorId)
      // For ASC we reverse comparisons.
      const isAsc = dir === 1;
      const clause = isAsc
        ? {
            $or: [
              { createdAt: { $gt: createdAtDate } },
              { createdAt: createdAtDate, _id: { $gt: cursorObjectId } },
            ],
          }
        : {
            $or: [
              { createdAt: { $lt: createdAtDate } },
              { createdAt: createdAtDate, _id: { $lt: cursorObjectId } },
            ],
          };

      filter.$and = filter.$and || [];
      filter.$and.push(clause);
      cursorApplied = true;
    }

    // ===== Least-privilege projection (public-safe) =====
    // Avoid leaking internal fields or Cloudinary public ids
    const projection = [
      '_id',
      'projectId',
      'unitType',
      'unitTypeName',
      'unitNumber',
      'slug',
      'title',
      'status',
      'isPublished',
      'price',
      'pricePerUnit',
      'area',
      'areaUnit',
      'bedrooms',
      'bathrooms',
      'floorNumber',
      'floorName',
      'tower',
      'isCorner',
      'isFeatured',
      'images.url',
      'createdAt',
      'updatedAt',
    ].join(' ');

    // ===== Execute query =====
    const query = (Unit as any)
      .find(filter)
      .select(projection)
      .sort(sort)
      .maxTimeMS(2500)
      .lean();

    let units: any[] = [];
    let hasMore = false;

    if (cursorApplied) {
      const rows = await query.limit(limit + 1);
      hasMore = rows.length > limit;
      units = hasMore ? rows.slice(0, limit) : rows;
    } else {
      const skip = (page - 1) * limit;
      units = await query.skip(skip).limit(limit);
    }

    // ===== Stats (project-wide, not filtered by current search; safe for UI) =====
    // Only compute lightweight aggregation; no user data.
    const statsAgg = await (Unit as any).aggregate([
      {
         $match: {
          projectId: projectObjectId,
          isDeleted: { $ne: true },
          ...(!isAdmin && !isOwner ? { isPublished: true } : {}),
        },
      },
      {
        $group: {
          _id: null,
          totalUnits: { $sum: 1 },
          availableUnits: { $sum: { $cond: [{ $eq: ['$status', 'available'] }, 1, 0] } },
          reservedUnits: { $sum: { $cond: [{ $eq: ['$status', 'reserved'] }, 1, 0] } },
          soldUnits: { $sum: { $cond: [{ $eq: ['$status', 'sold'] }, 1, 0] } },
          onHoldUnits: { $sum: { $cond: [{ $eq: ['$status', 'on_hold'] }, 1, 0] } },
          minPrice: { $min: '$price' },
          maxPrice: { $max: '$price' },
          minArea: { $min: '$area' },
          maxArea: { $max: '$area' },
        },
      },
    ]).option({ maxTimeMS: 2500 });

    const stats =
      statsAgg?.[0] || {
        totalUnits: 0,
        availableUnits: 0,
        reservedUnits: 0,
        soldUnits: 0,
        onHoldUnits: 0,
        minPrice: 0,
        maxPrice: 0,
        minArea: 0,
        maxArea: 0,
      };

    // ===== Groupings (based on returned page only) =====
    const unitsByFloor = units.reduce((acc: any, unit: any) => {
      const floor = unit.floorNumber ?? 'unknown';
      if (!acc[floor]) acc[floor] = [];
      acc[floor].push({
        _id: unit._id,
        unitNumber: unit.unitNumber,
        status: unit.status,
        unitType: unit.unitType,
        price: unit.price,
        area: unit.area,
        bedrooms: unit.bedrooms,
        isCorner: unit.isCorner,
      });
      return acc;
    }, {});

    const unitsByType = units.reduce((acc: any, unit: any) => {
      const t = unit.unitType || unit.unitTypeName || 'other';
      if (!acc[t]) acc[t] = { total: 0, available: 0, reserved: 0, sold: 0 };
      acc[t].total++;
      if (unit.status === 'available') acc[t].available++;
      else if (unit.status === 'reserved') acc[t].reserved++;
      else if (unit.status === 'sold') acc[t].sold++;
      return acc;
    }, {});

    // ===== Next cursor (only cursor mode) =====
    let nextCursor: string | null = null;
    if (cursorApplied && units.length > 0) {
      const last: any = units[units.length - 1];
      const payload: CursorPayload = {
        createdAt: new Date(last.createdAt).toISOString(),
        _id: String(last._id),
      };
      nextCursor = b64urlEncode(payload);
    }

    // Cache policy:
    // - Public allowed: short cache
    // - Admin/owner preview or non-public access: no-store
    if (publicAllowed && !(isAdmin || isOwner)) {
      res.setHeader(
        'Cache-Control',
        cursorApplied
          ? 'public, s-maxage=15, stale-while-revalidate=60'
          : 'public, s-maxage=30, stale-while-revalidate=120'
      );
    } else {
      res.setHeader('Cache-Control', 'no-store, max-age=0');
    }

    // Page totals only in page mode (cursor avoids count)
    if (!cursorApplied) {
      const totalCount = await (Unit as any).countDocuments(filter).maxTimeMS(2500);
      const totalPages = Math.max(1, Math.ceil(totalCount / limit));

      return res.status(200).json({
        success: true,
        units,
        stats,
        unitsByFloor,
        unitsByType,
        pagination: {
          mode: 'page',
          page,
          limit,
          totalCount,
          totalPages,
          hasMore: page * limit < totalCount,
        },
        cursor: null,
      });
    }

    return res.status(200).json({
      success: true,
      units,
      stats,
      unitsByFloor,
      unitsByType,
      pagination: {
        mode: 'cursor',
        limit,
        hasMore,
      },
      cursor: {
        next: hasMore ? nextCursor : null,
      },
    });
  } catch (error: unknown) {
    await logSecurityEvent({
      type: 'system_error',
      severity: 'medium',
      userId: auth?.id,
      metadata: {
        action: 'units_by_project_fetch_failed',
        projectId: typeof projectId === 'string' ? projectId : 'unknown',
        reason: error instanceof Error ? error.message : 'Unknown error',
      },
    });
    return res.status(500).json({
      success: false,
      message: 'Something went wrong. Please try again.',
    });
  }
}

// pages/api/upload/delete.ts

import type { NextApiRequest, NextApiResponse } from 'next';
import cloudinary, { isHighrisePublicId, isHighriseFolderPublicId } from '@/lib/cloudinary';
import { requireAuth } from '@/lib/requireAuth';
import { rateLimitApiWrite } from '@/lib/rateLimit';
import SecurityEvent from '@/models/SecurityEvent';
import { checkPermission } from '@/lib/permissions';
import dbConnect from '@/lib/dbConnect';

/**
 * 🗑️ ENTERPRISE FILE DELETE ENDPOINT
 * 
 * Security Features:
 * ├── Authentication required (requireAuth)
 * ├── Rate limiting (write operations tier)
 * ├── Ownership verification (via Cloudinary tags)
 * ├── Admin override capability
 * ├── Public ID validation & sanitization
 * ├── Resource type whitelist
 * ├── Cloudinary metadata verification
 * ├── CDN cache invalidation
 * ├── Comprehensive audit logging
 * ├── Unauthorized attempt tracking
 * └── Safe error handling (no info leakage)
 * 
 * @route DELETE/POST /api/upload/delete
 * @access Authenticated users only (own files) or Admin
 * @permission file_delete (for admin override)
 */

// ═══════════════════════════════════════════════════════════════
// 🔒 TYPE DEFINITIONS
// ═══════════════════════════════════════════════════════════════

interface DeleteRequest {
  publicId: string;
  resourceType?: 'image' | 'raw' | 'video';
}

interface ApiResponse {
  success: boolean;
  message?: string;
  result?: any;
}

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY CONSTANTS
// ═══════════════════════════════════════════════════════════════

const ALLOWED_RESOURCE_TYPES = ['image', 'raw', 'video'] as const;
const MAX_PUBLIC_ID_LENGTH = 500;

// Public ID patterns to block (security)
const DANGEROUS_PUBLIC_ID_PATTERNS = [
  /\.\./,           // Path traversal
  /<script/i,       // XSS
  /javascript:/i,   // XSS
  /data:/i,         // Data URI
  /vbscript:/i,     // VBScript
  /%00/,            // Null byte
];

// ═══════════════════════════════════════════════════════════════
// 🛠️ HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════

/**
 * Extract client IP address
 */
function getClientIP(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (typeof forwarded === 'string') {
    return forwarded.split(',')[0].trim();
  }
  const cfIp = req.headers['cf-connecting-ip'];
  if (typeof cfIp === 'string') return cfIp.trim();

  return req.socket?.remoteAddress || 'unknown';
}

/**
 * Validate and sanitize public ID
 */
function validatePublicId(publicId: string): { valid: boolean; error?: string } {
  if (!publicId || typeof publicId !== 'string') {
    return { valid: false, error: 'Public ID must be a non-empty string' };
  }

  if (publicId.length > MAX_PUBLIC_ID_LENGTH) {
    return { valid: false, error: 'Public ID exceeds maximum length' };
  }

  // Check for dangerous patterns
  for (const pattern of DANGEROUS_PUBLIC_ID_PATTERNS) {
    if (pattern.test(publicId)) {
      return { valid: false, error: 'Public ID contains invalid characters' };
    }
  }

  // Must belong to one of the canonical Highrise-managed Cloudinary folders.
  if (!isHighrisePublicId(publicId)) {
    return { valid: false, error: 'Invalid public ID format' };
  }

  return { valid: true };
}

/**
 * Validate resource type
 */
function validateResourceType(type: any): type is 'image' | 'raw' | 'video' {
  return ALLOWED_RESOURCE_TYPES.includes(type);
}

/**
 * Log security event
 */
async function logSecurityEvent(data: {
  eventType: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  userId?: string;
  ipAddress: string;
  userAgent: string;
  metadata?: Record<string, any>;
}): Promise<void> {
  try {
    await SecurityEvent.create({
      ...data,
      timestamp: new Date()
    });
  } catch (error) {
    console.error('Failed to log security event:', error);
  }
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
) {
  // Security Headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  const clientIP = getClientIP(req);
  const userAgent = req.headers['user-agent'] || 'unknown';

  // =========================================
  // 🔒 STEP 1: METHOD VALIDATION
  // =========================================
  if (req.method !== 'DELETE' && req.method !== 'POST') {
    res.setHeader('Allow', ['DELETE', 'POST']);
    return res.status(405).json({ 
      success: false, 
      message: 'Method not allowed' 
    });
  }

  try {
    // =========================================
    // 💾 STEP 2: DATABASE CONNECTION
    // =========================================
    await dbConnect();

    // =========================================
    // 🛡️ STEP 3: RATE LIMITING
    // =========================================
    const rateLimitResult = await rateLimitApiWrite(req);

    if (!rateLimitResult.ok) {
      await logSecurityEvent({
        eventType: 'rate_limit_exceeded',
        severity: 'medium',
        ipAddress: clientIP,
        userAgent,
        metadata: {
          endpoint: '/api/upload/delete',
          limit: rateLimitResult.limit,
          retryAfter: rateLimitResult.retryAfter
        }
      });

      return res.status(429).json({ 
        success: false, 
        message: 'Too many requests. Please slow down.' 
      });
    }

    // =========================================
    // 🔐 STEP 4: AUTHENTICATION
    // =========================================
    const auth = await requireAuth(req, res);
    if (!auth) return; // requireAuth already sent response

    // =========================================
    // 📝 STEP 5: VALIDATE REQUEST BODY
    // =========================================
    const { publicId, resourceType = 'image' }: DeleteRequest = req.body;
    const deliveryType = isHighriseFolderPublicId(publicId, 'kyc') ? 'authenticated' : 'upload';

    // Validate Public ID
    const publicIdValidation = validatePublicId(publicId);
    if (!publicIdValidation.valid) {
      await logSecurityEvent({
        eventType: 'invalid_input',
        severity: 'medium',
        userId: auth.id,
        ipAddress: clientIP,
        userAgent,
        metadata: {
          endpoint: '/api/upload/delete',
          error: publicIdValidation.error,
          publicId: publicId?.substring(0, 100) // Log partial for debugging
        }
      });

      return res.status(400).json({ 
        success: false, 
        message: publicIdValidation.error || 'Invalid public ID' 
      });
    }

    // Validate Resource Type
    if (!validateResourceType(resourceType)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid resource type. Must be: image, raw, or video'
      });
    }

    // =========================================
    // 🔍 STEP 6: FETCH CLOUDINARY METADATA
    // =========================================
    let resource: any = null;

    try {
      resource = await cloudinary.api.resource(publicId, {
        resource_type: resourceType,
        image_metadata: false,
        colors: false,
        phash: false,
        type: deliveryType,
      });
    } catch (cloudinaryError: any) {
      // File not found in Cloudinary
      if (cloudinaryError?.error?.http_code === 404) {
        // Return success for idempotency (file already deleted/doesn't exist)
        await logSecurityEvent({
          eventType: 'file_delete_not_found',
          severity: 'low',
          userId: auth.id,
          ipAddress: clientIP,
          userAgent,
          metadata: {
            publicId,
            resourceType
          }
        });

        return res.status(200).json({ 
          success: true, 
          message: 'File already deleted or does not exist' 
        });
      }

      // Other Cloudinary errors
      console.error('Cloudinary API error:', cloudinaryError);

      await logSecurityEvent({
        eventType: 'cloudinary_error',
        severity: 'high',
        userId: auth.id,
        ipAddress: clientIP,
        userAgent,
        metadata: {
          endpoint: '/api/upload/delete',
          publicId,
          error: cloudinaryError.message
        }
      });

      return res.status(500).json({
        success: false,
        message: 'Failed to verify file ownership'
      });
    }

    // =========================================
    // 🛡️ STEP 7: OWNERSHIP VERIFICATION
    // =========================================
    const userTags = resource?.tags || [];
    const isOwner = userTags.includes(`user_${auth.id}`);

    // requireAuth already resolved the current DB-backed role.
    const userRole = String(auth.role || 'user').toLowerCase();
    const isAdmin = userRole === 'admin' || userRole === 'superadmin';

    // Determine if deletion is allowed
    let deleteAllowed = isOwner || isAdmin;
    let deleteReason = isOwner ? 'owner' : isAdmin ? 'admin_override' : 'unauthorized';

    if (!deleteAllowed) {
      // Log unauthorized deletion attempt
      await logSecurityEvent({
        eventType: 'unauthorized_access_attempt',
        severity: 'high',
        userId: auth.id,
        ipAddress: clientIP,
        userAgent,
        metadata: {
          endpoint: '/api/upload/delete',
          publicId,
          resourceType,
          reason: 'Ownership mismatch',
          userRole,
          resourceTags: userTags
        }
      });

      return res.status(403).json({ 
        success: false, 
        message: 'Forbidden: You do not have permission to delete this file' 
      });
    }

    // =========================================
    // 🔑 STEP 8: ADMIN PERMISSION CHECK (if admin override)
    // =========================================
    if (isAdmin && !isOwner) {
  const hasPermission = checkPermission(
    {
      id: auth.id,
      role: userRole,
    },
    'file_delete_any',
  );

  if (!hasPermission) {
        await logSecurityEvent({
          eventType: 'permission_denied',
          severity: 'high',
          userId: auth.id,
          ipAddress: clientIP,
          userAgent,
          metadata: {
            endpoint: '/api/upload/delete',
            publicId,
            permission: 'file_delete_any'
          }
        });

        return res.status(403).json({
          success: false,
          message: 'Insufficient permissions to delete other users files'
        });
      }
    }

    // =========================================
    // 🗑️ STEP 9: DELETE FROM CLOUDINARY
    // =========================================
    const deleteResult = await cloudinary.uploader.destroy(publicId, {
      resource_type: resourceType,
      invalidate: true, // Clear CDN cache
      type: deliveryType,
    });

    if (deleteResult.result === 'ok' || deleteResult.result === 'not found') {
      // =========================================
      // 📝 STEP 10: AUDIT LOGGING (SUCCESS)
      // =========================================
      await logSecurityEvent({
        eventType: 'file_deleted',
        severity: isAdmin && !isOwner ? 'medium' : 'low',
        userId: auth.id,
        ipAddress: clientIP,
        userAgent,
        metadata: {
          publicId,
          resourceType,
          deleteReason,
          cloudinaryResult: deleteResult.result,
          fileSize: resource?.bytes || 0,
          format: resource?.format || 'unknown'
        }
      });

      return res.status(200).json({ 
        success: true, 
        message: 'File deleted successfully' 
      });
    }

    // Unexpected Cloudinary response
    await logSecurityEvent({
      eventType: 'file_delete_failed',
      severity: 'medium',
      userId: auth.id,
      ipAddress: clientIP,
      userAgent,
      metadata: {
        publicId,
        resourceType,
        cloudinaryResult: deleteResult
      }
    });

    return res.status(400).json({ 
      success: false, 
      message: 'Failed to delete file',
      result: deleteResult 
    });

  } catch (error: any) {
    // =========================================
    // 🚨 ERROR HANDLING
    // =========================================
    console.error('❌ Delete API Error:', error);

    await logSecurityEvent({
      eventType: 'system_error',
      severity: 'critical',
      ipAddress: clientIP,
      userAgent,
      metadata: {
        endpoint: '/api/upload/delete',
        error: error.message,
        errorType: error.name
      }
    });

    return res.status(500).json({ 
      success: false, 
      message: 'An error occurred while deleting the file' 
    });
  }
}

// pages/api/upload/index.ts
// 🔒 ENTERPRISE v3.0 — Centralized File Upload (Serverless-Safe)
// Single file per request. Browser → Buffer → Cloudinary (no disk writes).
// Pattern: disable bodyParser → parse multipart in memory → uploadBuffer()
// ═══════════════════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import crypto from 'crypto';
import dbConnect from '@/lib/dbConnect';
import cloudinary, {
  UPLOAD_FOLDER_MAP,
  FOLDERS,
  uploadBuffer,
  validateFile,
  getResourceType,
  getMimeTypeFromExtension,
  isHighrisePublicId,
  getSignedUrl,
} from '@/lib/cloudinary';
import { requireAuth, requirePermission } from '@/lib/requireAuth';
import { rateLimitApiWrite } from '@/lib/rateLimit';
import { logSecurityEvent } from '@/lib/security/logSecurityEvent';

// ═══════════════════════════════════════════════════════════════
// 🔒 NEXT.JS CONFIG — disable body parser (we parse raw stream)
// ═══════════════════════════════════════════════════════════════

export const config = {
  api: { bodyParser: false },
};

// ═══════════════════════════════════════════════════════════════
// 🔒 CONSTANTS
// ═══════════════════════════════════════════════════════════════

// Max raw body size — formidable removed, we enforce this manually
const MAX_BODY_SIZE = 10 * 1024 * 1024; // 10MB hard ceiling

const ADMIN_ONLY_UPLOAD_FOLDERS = new Set([
  'trusted-partners',
  'cities',
  'hero-banners-desktop',
  'hero-banners-mobile',
]);

// Allowed folder query params — single source of truth: UPLOAD_FOLDER_MAP
type UploadFolderParam = keyof typeof UPLOAD_FOLDER_MAP;

// ═══════════════════════════════════════════════════════════════
// 🔒 TYPES
// ═══════════════════════════════════════════════════════════════

interface UploadResponseData {
  url:      string;
  publicId: string;
  format:   string;
  size:     number;
  width?:   number;
  height?:  number;
}

interface ApiResponse {
  success:   boolean;
  data?:     UploadResponseData;
  error?:    string;
  code?:     string;
  requestId: string;
}

// Parsed multipart result (in memory — no disk)
interface ParsedFile {
  buffer:   Buffer;
  filename: string;
  mimeType: string;
  size:     number;
}

// ═══════════════════════════════════════════════════════════════
// 🔒 SECURITY HEADERS
// ═══════════════════════════════════════════════════════════════

function setSecurityHeaders(res: NextApiResponse, requestId: string): void {
  res.setHeader('X-Request-Id',              requestId);
  res.setHeader('Content-Type',              'application/json; charset=utf-8');
  res.setHeader('X-Content-Type-Options',    'nosniff');
  res.setHeader('X-Frame-Options',           'DENY');
  res.setHeader('Cache-Control',             'no-store');
  res.setHeader('Referrer-Policy',           'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=86400; includeSubDomains; preload');
  res.setHeader('Permissions-Policy',        'geolocation=(), microphone=(), camera=()');
}

// ═══════════════════════════════════════════════════════════════
// 🔒 HELPERS
// ═══════════════════════════════════════════════════════════════

function getClientIp(req: NextApiRequest): string {
  const xf = req.headers['x-forwarded-for'];
  const ip = Array.isArray(xf) ? xf[0] : xf;
  return (ip ?? '').split(',')[0]?.trim()
    || req.socket?.remoteAddress
    || '0.0.0.0';
}

function sanitizeFilename(raw: string): string {
  const name = (raw ?? '').split(/[\\/]/).pop() ?? 'file';
  return name
    .replace(/[^a-zA-Z0-9._-]/g, '_')
    .replace(/\.{2,}/g, '.')
    .replace(/^\./, '_')
    .slice(0, 100)
    || 'unnamed_file';
}

// ═══════════════════════════════════════════════════════════════
// 🔒 IN-MEMORY MULTIPART PARSER
// Replaces formidable entirely. No disk writes. No temp files.
// Parses Content-Type: multipart/form-data directly from raw stream.
// ═══════════════════════════════════════════════════════════════

function parseMultipart(req: NextApiRequest): Promise<ParsedFile> {
  return new Promise((resolve, reject) => {
    const contentType = req.headers['content-type'] ?? '';

    // Extract boundary from Content-Type header
    const boundaryMatch = contentType.match(/boundary=([^\s;]+)/);
    if (!boundaryMatch?.[1]) {
      reject(new Error('Missing multipart boundary'));
      return;
    }

    const boundary = boundaryMatch[1];
    const chunks: Buffer[] = [];
    let totalSize = 0;

    req.on('data', (chunk: Buffer) => {
      totalSize += chunk.length;
      if (totalSize > MAX_BODY_SIZE) {
        req.destroy();
        reject(new Error('FILE_TOO_LARGE'));
        return;
      }
      chunks.push(chunk);
    });

    req.on('error', reject);

    req.on('end', () => {
      try {
        const body = Buffer.concat(chunks);
        const parsed = parseMultipartBuffer(body, boundary);
        resolve(parsed);
      } catch (err: unknown) {
        reject(err instanceof Error ? err : new Error('Multipart parse failed'));
      }
    });
  });
}

// Pure Buffer multipart parser — no external deps
function parseMultipartBuffer(body: Buffer, boundary: string): ParsedFile {
  const boundaryBuf = Buffer.from(`--${boundary}`);
  const CRLF        = Buffer.from('\r\n');
  const CRLFCRLF    = Buffer.from('\r\n\r\n');

  // Find all boundary positions
  const parts: { start: number; end: number }[] = [];
  let searchPos = 0;

  while (searchPos < body.length) {
    const boundaryPos = body.indexOf(boundaryBuf, searchPos);
    if (boundaryPos === -1) break;

    const afterBoundary = boundaryPos + boundaryBuf.length;

    // Check for final boundary (--)
    if (body[afterBoundary] === 0x2D && body[afterBoundary + 1] === 0x2D) break;

    // Skip CRLF after boundary
    const contentStart = afterBoundary + CRLF.length;

    // Find next boundary
    const nextBoundaryPos = body.indexOf(boundaryBuf, contentStart);
    if (nextBoundaryPos === -1) break;

    // End of this part (trim trailing CRLF before next boundary)
    const contentEnd = nextBoundaryPos - CRLF.length;

    parts.push({ start: contentStart, end: contentEnd });
    searchPos = nextBoundaryPos;
  }

  if (parts.length === 0) {
    throw new Error('No parts found in multipart body');
  }

  // Find the "file" field part
  for (const part of parts) {
    const partContent = body.slice(part.start, part.end);
    const headerEnd   = partContent.indexOf(CRLFCRLF);

    if (headerEnd === -1) continue;

    const headerSection = partContent.slice(0, headerEnd).toString('utf8');
    const fileData      = partContent.slice(headerEnd + CRLFCRLF.length);

    // Must be a file field (has filename=)
    if (!headerSection.includes('filename=')) continue;

    // Parse Content-Disposition
    // Fix: \b word boundary + non-greedy *? prevents matching "name=" inside "filename="
    const dispositionMatch = headerSection.match(
      /Content-Disposition:[^\r\n]*?\bname="([^"]+)"(?:[^\r\n]*?filename="([^"]*)")?/i
    );
    const fieldName = dispositionMatch?.[1] ?? '';
    const rawFilename = dispositionMatch?.[2] ?? 'upload';

    // Must be the "file" field
    if (fieldName !== 'file') continue;

    // Parse Content-Type
    const ctMatch   = headerSection.match(/Content-Type:\s*([^\r\n]+)/i);
    const mimeType  = ctMatch?.[1]?.trim().toLowerCase() ?? 'application/octet-stream';

    const filename = sanitizeFilename(rawFilename);

    return {
      buffer:   fileData,
      filename,
      mimeType,
      size:     fileData.length,
    };
  }

  throw new Error('No file field found. Use field name "file".');
}

// ═══════════════════════════════════════════════════════════════
// 🚀 MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>,
): Promise<void> {

  const requestId = crypto.randomUUID();
  setSecurityHeaders(res, requestId);

  const ip = getClientIp(req);
  const ua = String(req.headers['user-agent'] ?? '').slice(0, 200);

  // ── Method guard ─────────────────────────────────────────────
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    res.status(405).json({
      success: false,
      error:   'Method not allowed',
      code:    'METHOD_NOT_ALLOWED',
      requestId,
    });
    return;
  }

  // ── Validate folder query param ───────────────────────────────
  // Folder comes from query string — never from form body (security boundary)
  // Single source of truth: UPLOAD_FOLDER_MAP from lib/cloudinary.ts
  const folderParam = String(req.query['folder'] ?? 'general').toLowerCase().trim();

  if (!(folderParam in UPLOAD_FOLDER_MAP)) {
    res.status(400).json({
      success: false,
      error:   `Invalid folder. Allowed: ${Object.keys(UPLOAD_FOLDER_MAP).join(', ')}`,
      code:    'INVALID_FOLDER',
      requestId,
    });
    return;
  }

  // Resolve to internal Cloudinary folder path
  const folderKey    = UPLOAD_FOLDER_MAP[folderParam as UploadFolderParam];
  const folderPath   = FOLDERS[folderKey];

  // ── Rate limit ───────────────────────────────────────────────
  const rl = await rateLimitApiWrite(req);
  if (!rl.ok) {
    res.setHeader('Retry-After', String(rl.retryAfter ?? 60));
    res.status(429).json({
      success: false,
      error:   'Too many uploads. Please slow down.',
      code:    'RATE_LIMITED',
      requestId,
    });
    return;
  }

  // ── Auth / authorization ─────────────────────────────────────
  // Admin-managed marketing assets use the same server-side upload path as
  // normal assets, but require the same permission as their admin APIs.
  const auth = ADMIN_ONLY_UPLOAD_FOLDERS.has(folderParam)
    ? await requirePermission(req, res, 'system_manage_settings')
    : await requireAuth(req, res);
  if (!auth) return;

  // ── DB ───────────────────────────────────────────────────────
  await dbConnect();

  try {
    // ── Parse multipart (in memory — no disk, no formidable) ───
    let parsed: ParsedFile;
    try {
      parsed = await parseMultipart(req);
    } catch (parseErr: unknown) {
      const msg = parseErr instanceof Error ? parseErr.message : 'Parse failed';

      if (msg === 'FILE_TOO_LARGE') {
        res.status(400).json({
          success: false,
          error:   `File too large. Maximum: ${MAX_BODY_SIZE / 1024 / 1024}MB`,
          code:    'FILE_TOO_LARGE',
          requestId,
        });
        return;
      }

      res.status(400).json({
        success: false,
        error:   msg || 'Invalid form data. Use multipart/form-data with field name "file".',
        code:    'PARSE_ERROR',
        requestId,
      });
      return;
    }

    const { buffer, filename, mimeType, size } = parsed;

    // ── Determine file category from folder ───────────────────
    // 'documents' → kyc folder → category: 'kyc'
    // everything else → category: 'image'
    const fileCategory = folderParam === 'documents' ? 'kyc' : 'image';

    // ── Validate file (mime + extension + size + magic bytes) ─
    // validateFile() from lib/cloudinary.ts — single source of truth
    const validation = validateFile(
      { name: filename, type: mimeType, size, buffer },
      fileCategory,
    );

    if (!validation.valid) {
      await logSecurityEvent({
        type:      'property_flagged',   // closest valid SecurityEventType for suspicious upload
        severity:  'high',
        userId:    auth.id,
        ip,
        userAgent: ua,
        metadata:  {
          action:           'upload_invalid_file',
          reason:           validation.error,
          declaredMimeType: mimeType,
          filename,
          folder:           folderParam,
          requestId,
        },
      });

      res.status(400).json({
        success: false,
        error:   validation.error ?? 'Invalid file type or content',
        code:    'INVALID_FILE',
        requestId,
      });
      return;
    }

    // ── Determine resource type for Cloudinary ────────────────
    const resourceType = getResourceType(mimeType);

    // ── Build Cloudinary upload options ───────────────────────
    // We call cloudinary.uploader.upload_stream directly here
    // because uploadBuffer() from lib/cloudinary.ts applies
    // folder-specific transformations (avatar crop, property resize, etc.)
    // but we need folderKey-aware options from getUploadOptions().
    // Using uploadBuffer() is the correct pattern:

    const uploadResult = await uploadBuffer(
      buffer,
      filename,
      folderKey,
      fileCategory,
      { tags: [folderParam, `user_${auth.id}`] },
    );

    if (!uploadResult.success || !uploadResult.publicId) {
      res.status(500).json({
        success: false,
        error:   uploadResult.error ?? 'Upload to Cloudinary failed',
        code:    'CLOUDINARY_ERROR',
        requestId,
      });
      return;
    }

    // ── Defense: verify returned publicId belongs to our folders
    if (!isHighrisePublicId(uploadResult.publicId)) {
      res.status(500).json({
        success: false,
        error:   'Upload routing error',
        code:    'ROUTING_ERROR',
        requestId,
      });
      return;
    }

    // ── Audit log ─────────────────────────────────────────────
    await logSecurityEvent({
      type:      'property_updated',  // valid SecurityEventType for file operations
      severity:  'low',
      userId:    auth.id,
      ip,
      userAgent: ua,
      metadata:  {
        action:    'file_uploaded',
        folder:    folderParam,
        folderPath,
        format:    uploadResult.format,
        size:      uploadResult.size,
        publicId:  uploadResult.publicId,
        requestId,
      },
    });

    // ── Success ───────────────────────────────────────────────
    res.status(200).json({
      success: true,
      data: {
        // KYC assets use authenticated delivery. Return a short-lived URL for
        // immediate preview; callers persist publicId as the durable reference.
        url:      folderParam === 'documents'
          ? getSignedUrl(uploadResult.publicId, 15 * 60)
          : (uploadResult.secureUrl ?? uploadResult.url ?? ''),
        publicId: uploadResult.publicId,
        format:   uploadResult.format   ?? '',
        size:     uploadResult.size     ?? 0,
        width:    uploadResult.width,
        height:   uploadResult.height,
      },
      requestId,
    });

  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Internal server error';

    await logSecurityEvent({
      type:      'property_flagged',
      severity:  'high',
      userId:    auth.id,
      ip,
      userAgent: ua,
      metadata:  {
        action:    'upload_error',
        folder:    folderParam,
        error:     message,
        requestId,
      },
    });

    res.status(500).json({
      success: false,
      error:   'Upload failed. Please try again.',
      code:    'SERVER_ERROR',
      requestId,
    });
  }
}

// ========== FILE: pages/api/user/request-phone-otp.ts ==========
// Highrise.pk — Request Phone OTP for verification
// V6.9.0 — Social Login Lead Capture
// ═══════════════════════════════════════════════════════════════
// Flow:
//   1. User logged in via Google/Facebook (no phone yet)
//   2. Calls this endpoint with their phone number
//   3. We generate 6-digit OTP, hash it, store in User doc
//   4. Send OTP via console log (dev) or SMS service (prod)
//   5. Frontend shows OTP input → calls verify-phone-otp.ts
// ═══════════════════════════════════════════════════════════════

import type { NextApiRequest, NextApiResponse } from 'next';
import { getServerSession }                     from 'next-auth/next';
import { authOptions }                          from '@/pages/api/auth/[...nextauth]';
import dbConnect                                from '@/lib/dbConnect';
import User                                     from '@/models/User';
import { rateLimitApi, sendRateLimitResponse }  from '@/lib/rateLimit';
import bcrypt                                   from 'bcryptjs';

// ─── Types ────────────────────────────────────────────────────

interface ApiResponse {
  success: boolean;
  message: string;
  retryAfter?: number; // seconds until next OTP allowed
}

// ─── Constants ────────────────────────────────────────────────

const OTP_EXPIRY_MINUTES    = 10;
const OTP_RESEND_COOLDOWN_S = 60;   // 1 minute between sends
const OTP_MAX_ATTEMPTS      = 5;    // max wrong guesses per OTP
const BCRYPT_ROUNDS         = 10;   // lighter than password (OTP is short-lived)

// ─── Phone Normalizer ─────────────────────────────────────────

function normalizePakistaniPhone(raw: string): string | null {
  const digits = raw.replace(/\D/g, '');

  // +923xxxxxxxxx  (12 digits starting with 92)
  if (digits.startsWith('92') && digits.length === 12) {
    return `+${digits}`;
  }
  // 03xxxxxxxxx  (11 digits starting with 0)
  if (digits.startsWith('0') && digits.length === 11) {
    return `+92${digits.slice(1)}`;
  }
  // 3xxxxxxxxx  (10 digits starting with 3)
  if (digits.startsWith('3') && digits.length === 10) {
    return `+92${digits}`;
  }

  return null; // invalid
}

// ─── OTP Generator ────────────────────────────────────────────

function generateOtp(): string {
  // 6-digit numeric OTP
  return Math.floor(100000 + Math.random() * 900000).toString();
}

// ─── SMS Sender (stub — replace with Twilio/Jazz/Telenor) ─────

async function sendOtpViaSms(phone: string, otp: string): Promise<void> {
  if (process.env.NODE_ENV !== 'production') {
    // Development: log to console
    console.log(`[OTP DEV] Phone: ${phone} | OTP: ${otp}`);
    return;
  }

  // ── Production: plug in your SMS provider here ──────────────
  // Example with Twilio:
  //
  // const twilio = require('twilio')(
  //   process.env.TWILIO_ACCOUNT_SID,
  //   process.env.TWILIO_AUTH_TOKEN
  // );
  // await twilio.messages.create({
  //   body: `Your Highrise.pk verification code is: ${otp}. Valid for ${OTP_EXPIRY_MINUTES} minutes.`,
  //   from: process.env.TWILIO_PHONE_NUMBER,
  //   to: phone,
  // });
  //
  // ── OR use Pakistan SMS gateway (Jazz, Ufone, etc.) ─────────
  // They provide REST APIs — replace above with their endpoint

  console.log(`[OTP PROD] Would send to ${phone}: ${otp}`);
}

// ─── Main Handler ─────────────────────────────────────────────

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
): Promise<void> {

  // ── Only POST allowed ──────────────────────────────────────
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    res.status(405).json({
      success: false,
      message: 'Method not allowed',
    });
    return;
  }

  // ── Rate limit ─────────────────────────────────────────────
  const rl = await rateLimitApi(req);
  if (!rl.ok) {
    sendRateLimitResponse(res, rl);
    return;
  }

  // ── Auth check ─────────────────────────────────────────────
  const session = await getServerSession(req, res, authOptions);

  if (!session?.user?.id) {
    res.status(401).json({
      success: false,
      message: 'You must be logged in to verify your phone.',
    });
    return;
  }

  // ── Input validation ───────────────────────────────────────
  const { phone } = req.body as { phone?: string };

  if (!phone || typeof phone !== 'string') {
    res.status(400).json({
      success: false,
      message: 'Phone number is required.',
    });
    return;
  }

  const normalizedPhone = normalizePakistaniPhone(phone.trim());

  if (!normalizedPhone) {
    res.status(400).json({
      success: false,
      message: 'Please enter a valid Pakistani mobile number (e.g. 0300-1234567).',
    });
    return;
  }

  // ── Connect DB ─────────────────────────────────────────────
  await dbConnect();

  try {

    // ── Fetch user ─────────────────────────────────────────
    const user = await User.findById(session.user.id).select(
      'phone isPhoneVerified phoneOtpLastSentAt phoneOtpAttempts phoneOtpExpiresAt'
    );

    if (!user) {
      res.status(404).json({
        success: false,
        message: 'User not found.',
      });
      return;
    }

    // ── Already verified check ─────────────────────────────
    if (user.isPhoneVerified && user.phone === normalizedPhone) {
      res.status(200).json({
        success: true,
        message: 'This phone number is already verified.',
      });
      return;
    }

    // ── Phone already taken by another user ────────────────
    const phoneExists = await User.findOne({
      phone:           normalizedPhone,
      isPhoneVerified: true,
      _id:             { $ne: session.user.id },
    }).select('_id').lean();

    if (phoneExists) {
      res.status(409).json({
        success: false,
        message: 'This phone number is already registered to another account.',
      });
      return;
    }

    // ── Resend cooldown check ──────────────────────────────
    if (user.phoneOtpLastSentAt) {
      const secondsSinceLast =
        (Date.now() - new Date(user.phoneOtpLastSentAt).getTime()) / 1000;

      if (secondsSinceLast < OTP_RESEND_COOLDOWN_S) {
        const retryAfter = Math.ceil(OTP_RESEND_COOLDOWN_S - secondsSinceLast);
        res.status(429).json({
          success:    false,
          message:    `Please wait ${retryAfter} seconds before requesting another OTP.`,
          retryAfter,
        });
        return;
      }
    }

    // ── Generate OTP ───────────────────────────────────────
    const otp       = generateOtp();
    const otpHash   = await bcrypt.hash(otp, BCRYPT_ROUNDS);
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60 * 1000);

    // ── Save to DB ─────────────────────────────────────────
    await User.findByIdAndUpdate(session.user.id, {
      $set: {
        // Store phone immediately (unverified)
        // isPhoneVerified stays false until OTP confirmed
        phone:              normalizedPhone,
        phoneOtpHash:       otpHash,
        phoneOtpExpiresAt:  expiresAt,
        phoneOtpLastSentAt: new Date(),
        phoneOtpAttempts:   0, // reset attempts on new OTP
      },
    });

    // ── Send OTP ───────────────────────────────────────────
    await sendOtpViaSms(normalizedPhone, otp);

    // ── Success response ───────────────────────────────────
    res.status(200).json({
      success: true,
      message: `Verification code sent to ${normalizedPhone}. Valid for ${OTP_EXPIRY_MINUTES} minutes.`,
    });

  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Server error';
    console.error('[request-phone-otp]', message);
    res.status(500).json({
      success: false,
      message: 'Failed to send OTP. Please try again.',
    });
  }
}
