              ) : null}

              {/* Grid */}
              <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-8">
                {restPosts.map((post, index) => (
                  <motion.div
                    key={post._id}
                    initial={{ opacity: 0, y: 16 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.35, delay: index * 0.04 }}
                  >
                    <Link href={`/blog/${post.slug}`}>
                      <Card className="overflow-hidden hover:shadow-xl transition-all duration-300 cursor-pointer group h-full flex flex-col border-gray-200">
                        <div className="h-52 overflow-hidden relative">
                          <img
                            src={
                              post.image?.url ||
                              'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=800'
                            }
                            alt={post.title}
                            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                          />

                          {post.featured ? (
                            <div className="absolute top-3 left-3 px-2.5 py-1 bg-amber-500 text-white text-xs font-semibold rounded-lg flex items-center gap-1">
                              <Sparkles className="w-3 h-3" />
                              Featured
                            </div>
                          ) : null}
                        </div>

                        <div className="p-6 flex flex-col flex-1">
                          <span className="inline-block px-3 py-1 text-xs font-medium rounded-full mb-3 self-start bg-[#029bba]/10 text-[#029bba]">
                            {post.category}
                          </span>

                          <h3 className="text-xl font-bold text-gray-900 mb-3 line-clamp-2 group-hover:text-[#029bba] transition-colors">
                            {post.title}
                          </h3>

                          <p className="text-gray-600 mb-4 line-clamp-3 flex-1">
                            {post.excerpt}
                          </p>

                          {post.tags && post.tags.length > 0 ? (
                            <div className="flex flex-wrap gap-1 mb-4">
                              {post.tags.slice(0, 3).map((tag) => (
                                <span
                                  key={tag}
                                  className="text-xs px-2 py-1 bg-gray-100 text-gray-600 rounded-md"
                                >
                                  #{tag}
                                </span>
                              ))}
                            </div>
                          ) : null}

                          <div className="flex items-center justify-between text-sm text-gray-500 pt-4 border-t border-gray-100">
                            <div className="flex items-center gap-3">
                              <div className="flex items-center">
                                <User className="w-4 h-4 mr-1" />
                                <span>{post.authorName || post.author || 'Highrise Team'}</span>
                              </div>
                              <div className="flex items-center">
                                <Clock className="w-4 h-4 mr-1" />
                                <span>{post.readTime || '5 min read'}</span>
                              </div>
                            </div>
                            <div className="flex items-center">
                              <Eye className="w-4 h-4 mr-1" />
                              <span>{post.views || 0}</span>
                            </div>
                          </div>

                          <div className="flex items-center text-xs text-gray-400 mt-2">
                            <Calendar className="w-3 h-3 mr-1" />
                            <span>{formatDate(post.publishedAt || post.createdAt)}</span>
                          </div>
                        </div>
                      </Card>
                    </Link>
                  </motion.div>
                ))}
              </div>

              {/* Pagination */}
              {pagination && pagination.totalPages > 1 ? (
                <div className="flex flex-wrap justify-center items-center gap-2">
                  <button
                    disabled={currentPage === 1}
                    onClick={() => setCurrentPage(currentPage - 1)}
                    className="px-4 py-2.5 rounded-xl border border-gray-300 text-gray-700 font-medium disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50 transition-colors"
                  >
                    Previous
                  </button>

                  <div className="flex items-center gap-1">
                    {Array.from({ length: pagination.totalPages }, (_, i) => i + 1)
                      .filter((page) => {
                        return (
                          page === 1 ||
                          page === pagination.totalPages ||
                          Math.abs(page - currentPage) <= 1
                        );
                      })
                      .map((page, idx, arr) => (
                        <React.Fragment key={page}>
                          {idx > 0 && arr[idx - 1] !== page - 1 && (
                            <span className="px-2 text-gray-400">...</span>
                          )}
                          <button
                            onClick={() => setCurrentPage(page)}
                            className={`w-10 h-10 rounded-xl font-medium transition-all ${
                              currentPage === page
                                ? 'bg-[#029bba] text-white shadow-lg'
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                            }`}
                          >
                            {page}
                          </button>
                        </React.Fragment>
                      ))}
                  </div>

                  <button
                    disabled={!pagination.hasMore}
                    onClick={() => setCurrentPage(currentPage + 1)}
                    className="px-4 py-2.5 rounded-xl border border-gray-300 text-gray-700 font-medium disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50 transition-colors"
                  >
                    Next
                  </button>
                </div>
              ) : null}
            </div>
          )}
            </div>

            {/* Sidebar */}
            <aside className="lg:col-span-4 space-y-6">
              {/* Category Info Card */}
              {categoryMeta && (
                <Card className="p-6 border-gray-200 shadow-sm">
                  <div className="flex items-start gap-4 mb-4">
                    {categoryMeta.icon && (() => {
                      try {
                        const LucideIcons = require('lucide-react');
                        const IconComponent = LucideIcons[categoryMeta.icon];
                        return IconComponent ? (
                          <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${categoryMeta.color.gradient} flex items-center justify-center shrink-0`}>
                            <IconComponent className="w-6 h-6 text-white" />
                          </div>
                        ) : null;
                      } catch (err) {
                        return null;
                      }
                    })()}
                    <div>
                      <h3 className="font-bold text-gray-900 text-lg mb-1 flex items-center gap-2">
                        {categoryMeta.name}
                        <span className="text-xl">{categoryMeta.emoji}</span>
                      </h3>
                      {categoryMeta.group && (() => {
                        const groupMeta = getCategoryGroup(categoryMeta.group);
                        return (
                          <p className="text-xs text-gray-500">
                            {groupMeta.emoji} {groupMeta.name}
                          </p>
                        );
                      })()}
                    </div>
                  </div>
                  <p className="text-sm text-gray-600 leading-relaxed">
                    {categoryMeta.description}
                  </p>
                  {categoryMeta.seoKeywords && categoryMeta.seoKeywords.length > 0 && (
                    <div className="mt-4 pt-4 border-t border-gray-100">
                      <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
                        Related Topics
                      </p>
                      <div className="flex flex-wrap gap-1.5">
                        {categoryMeta.seoKeywords.slice(0, 5).map((keyword) => (
                          <span
                            key={keyword}
                            className="text-xs px-2 py-1 bg-gray-100 text-gray-600 rounded-md"
                          >
                            {keyword}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </Card>
              )}

              {/* Related Categories */}
              {relatedCategories.length > 0 && (
                <Card className="p-6 border-gray-200 shadow-sm">
                  <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2">
                    Related Categories
                  </h3>
                  <div className="space-y-3">
                    {relatedCategories.map((relCat) => {
                      let IconComponent = null;
                      try {
                        const LucideIcons = require('lucide-react');
                        IconComponent = LucideIcons[relCat.icon];
                      } catch (err) {
                        // Icon not found
                      }

                      return (
                        <Link
                          key={relCat.slug}
                          href={`/blog/category/${relCat.slug}`}
                          className="group flex items-start gap-3 rounded-xl border border-gray-100 p-3 transition-all hover:border-cyan-200 hover:bg-cyan-50/50"
                        >
                          {IconComponent && (
                            <div className={`mt-0.5 rounded-lg bg-gradient-to-br ${relCat.color.gradient} p-2 shrink-0`}>
                              <IconComponent className="w-4 h-4 text-white" />
                            </div>
                          )}
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                              <span className="text-sm font-semibold text-gray-900 group-hover:text-cyan-600">
                                {relCat.name}
                              </span>
                              <span className="text-xs">{relCat.emoji}</span>
                            </div>
                            <p className="line-clamp-2 text-xs leading-relaxed text-gray-600">
                              {relCat.description}
                            </p>
                          </div>
                          <ChevronRight className="w-4 h-4 text-gray-400 transition-transform group-hover:translate-x-0.5 group-hover:text-cyan-600 shrink-0 mt-1" />
                        </Link>
                      );
                    })}
                  </div>
                </Card>
              )}

              {/* Quick Navigation */}
              <Card className="p-6 border-gray-200 shadow-sm">
                <h3 className="font-bold text-gray-900 mb-4">Quick Navigation</h3>
                <div className="space-y-2">
                  <Link
                    href="/blog"
                    className="block px-4 py-2.5 rounded-xl bg-gray-50 hover:bg-gray-100 text-sm font-medium text-gray-700 transition-colors"
                  >
                    All Blog Articles
                  </Link>
                  <Link
                    href="/blog/search"
                    className="block px-4 py-2.5 rounded-xl bg-gray-50 hover:bg-gray-100 text-sm font-medium text-gray-700 transition-colors"
                  >
                    Advanced Search
                  </Link>
                </div>
              </Card>
            </aside>
          </div>
        </section>
      </div>
    </>
  );
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useRouter } from 'next/router';
import Head from 'next/head';
import Link from 'next/link';
import Image from 'next/image';
import { motion } from 'framer-motion';
import {
  Search,
  X,
  Filter,
  Calendar,
  Clock,
  Eye,
  Tag,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Loader2,
  SlidersHorizontal,
  TrendingUp,
  User,
  Hash,
  ArrowRight,
  FileText,
} from 'lucide-react';
import toast from 'react-hot-toast';

// ─────────────────────────────────────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────────────────────────────────────

interface SearchResult {
  _id: string;
  title: string;
  slug: string;
  excerpt: string;
  category: string;
  author: string;
  publishedAt: string | null;
  image: string | null;
  readTime: string;
  views: number;
  tags: string[];
  featured: boolean;
  relevanceScore: number | null;
}

interface SearchResponse {
  success: boolean;
  query: string | null;
  filters: {
    category: string | null;
    tags: string[];
    author: string | null;
    dateFrom: string | null;
    dateTo: string | null;
  };
  sort: string;
  pagination: {
    page: number;
    limit: number;
    totalCount: number;
    totalPages: number;
    hasMore: boolean;
  };
  results: SearchResult[];
  filterOptions: {
    categories: string[];
    popularTags: Array<{ tag: string; count: number }>;
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// CONSTANTS
// ─────────────────────────────────────────────────────────────────────────────

const SORT_OPTIONS = [
  { value: 'relevance', label: 'Most Relevant' },
  { value: 'newest', label: 'Newest First' },
  { value: 'oldest', label: 'Oldest First' },
  { value: 'popular', label: 'Most Popular' },
];

// Grouped categories for better UX
const CATEGORY_GROUPS = [
  {
    label: '🏠 Property Guides',
    categories: ['Buying Guide', 'Selling Guide', 'Renting Guide', 'First-Time Buyers'],
  },
  {
    label: '💰 Investment & Finance',
    categories: ['Investment', 'Investment Tips', 'ROI Analysis', 'Real Estate Finance', 'Mortgage & Loans'],
  },
  {
    label: '📊 Market & Analysis',
    categories: ['Market Analysis', 'Market Trends', 'Price Trends', 'Market News', 'Industry Reports'],
  },
  {
    label: '⚖️ Legal & Documentation',
    categories: ['Legal', 'Legal Guide', 'Property Laws', 'Documentation', 'Taxation', 'Verification'],
  },
  {
    label: '🏙️ City & Area Guides',
    categories: ['Karachi', 'Lahore', 'Islamabad', 'Rawalpindi', 'Faisalabad', 'Multan', 'Peshawar', 'Quetta', 'City Guide', 'Area Guide', 'Society Reviews'],
  },
  {
    label: '🏗️ Projects & Developers',
    categories: ['New Projects', 'Project Reviews', 'Developer News', 'Under Construction', 'Upcoming Projects'],
  },
  {
    label: '🏡 Property Types',
    categories: ['Apartments', 'Houses', 'Plots', 'Commercial', 'Offices', 'Shops', 'Farmhouses', 'Penthouses'],
  },
  {
    label: '🎨 Lifestyle & Living',
    categories: ['Lifestyle', 'Home Decor', 'Interior Design', 'Architecture', 'Smart Homes', 'Renovation', 'Maintenance'],
  },
  {
    label: '📰 News & Updates',
    categories: ['News', 'Government Policies', 'CPEC Updates', 'Infrastructure', 'Economy'],
  },
  {
    label: '💡 Tips & Advice',
    categories: ['Tips', 'Expert Advice', 'How-To Guides', 'Checklist', 'FAQs'],
  },
  {
    label: '🔧 Technology',
    categories: ['Technology', 'PropTech', 'Virtual Tours', 'Online Transactions'],
  },
  {
    label: '📋 Others',
    categories: ['Opinion', 'Interview', 'Success Stories', 'General'],
  },
];

const DEBOUNCE_MS = 400;

// ─────────────────────────────────────────────────────────────────────────────
// MAIN COMPONENT
// ─────────────────────────────────────────────────────────────────────────────

export default function BlogSearchPage() {
  const router = useRouter();

  // ─────────────────────────────────────────────────────────────────────────
  // STATE
  // ─────────────────────────────────────────────────────────────────────────

  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [selectedSort, setSelectedSort] = useState('relevance');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [currentPage, setCurrentPage] = useState(1);

  const [results, setResults] = useState<SearchResult[]>([]);
  const [pagination, setPagination] = useState({
    totalCount: 0,
    totalPages: 0,
    hasMore: false,
  });
  const [filterOptions, setFilterOptions] = useState<{
    categories: string[];
    popularTags: Array<{ tag: string; count: number }>;
  }>({ categories: [], popularTags: [] });

  const [isLoading, setIsLoading] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [showFilters, setShowFilters] = useState(false);

  // ─────────────────────────────────────────────────────────────────────────
  // SYNC URL PARAMS ON MOUNT
  // ─────────────────────────────────────────────────────────────────────────

  useEffect(() => {
    if (!router.isReady) return;

    const { q, category, tags, sort, dateFrom: df, dateTo: dt, page } = router.query;

    if (q) setSearchQuery(String(q));
    if (category) setSelectedCategory(String(category));
    if (tags) {
      const tagArray = Array.isArray(tags) ? tags : String(tags).split(',');
      setSelectedTags(tagArray.filter(Boolean));
    }
    if (sort && SORT_OPTIONS.some((s) => s.value === sort)) {
      setSelectedSort(String(sort));
    }
    if (df) setDateFrom(String(df));
    if (dt) setDateTo(String(dt));
    if (page) setCurrentPage(parseInt(String(page), 10) || 1);

    setIsInitialLoad(false);
  }, [router.isReady, router.query]);

  // ─────────────────────────────────────────────────────────────────────────
  // SEARCH FUNCTION
  // ─────────────────────────────────────────────────────────────────────────

  const performSearch = useCallback(async () => {
    setIsLoading(true);

    try {
      const params = new URLSearchParams();
      
      if (searchQuery.trim()) params.set('q', searchQuery.trim());
      if (selectedCategory) params.set('category', selectedCategory);
      if (selectedTags.length > 0) params.set('tags', selectedTags.join(','));
      if (selectedSort !== 'relevance') params.set('sort', selectedSort);
      if (dateFrom) params.set('dateFrom', dateFrom);
      if (dateTo) params.set('dateTo', dateTo);
      if (currentPage > 1) params.set('page', String(currentPage));

      const response = await fetch(`/api/blogs/search?${params.toString()}`);
      const data: SearchResponse = await response.json();

      if (data.success) {
        setResults(data.results);
        setPagination({
          totalCount: data.pagination.totalCount,
          totalPages: data.pagination.totalPages,
          hasMore: data.pagination.hasMore,
        });
        setFilterOptions(data.filterOptions);
      } else {
        toast.error('Search failed. Please try again.');
      }
    } catch (error) {
      console.error('Search error:', error);
      toast.error('Search failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [searchQuery, selectedCategory, selectedTags, selectedSort, dateFrom, dateTo, currentPage]);

  // ─────────────────────────────────────────────────────────────────────────
  // DEBOUNCED SEARCH
  // ─────────────────────────────────────────────────────────────────────────

  useEffect(() => {
    if (isInitialLoad) return;

    const timer = setTimeout(() => {
      performSearch();

      // Update URL
      const params = new URLSearchParams();
      if (searchQuery.trim()) params.set('q', searchQuery.trim());
      if (selectedCategory) params.set('category', selectedCategory);
      if (selectedTags.length > 0) params.set('tags', selectedTags.join(','));
      if (selectedSort !== 'relevance') params.set('sort', selectedSort);
      if (dateFrom) params.set('dateFrom', dateFrom);
      if (dateTo) params.set('dateTo', dateTo);
      if (currentPage > 1) params.set('page', String(currentPage));

      const queryString = params.toString();
      const newUrl = queryString ? `/blog/search?${queryString}` : '/blog/search';
      
      router.replace(newUrl, undefined, { shallow: true });
    }, DEBOUNCE_MS);

    return () => clearTimeout(timer);
  }, [searchQuery, selectedCategory, selectedTags, selectedSort, dateFrom, dateTo, currentPage, isInitialLoad]);

  // Initial search on mount
  useEffect(() => {
    if (!isInitialLoad) return;
    const timer = setTimeout(() => {
      performSearch();
    }, 100);
    return () => clearTimeout(timer);
  }, [isInitialLoad]);

  // ─────────────────────────────────────────────────────────────────────────
  // HANDLERS
  // ─────────────────────────────────────────────────────────────────────────

  const handleTagToggle = (tag: string) => {
    setSelectedTags((prev) =>
      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
    );
    setCurrentPage(1);
  };

  const handleClearFilters = () => {
    setSearchQuery('');
    setSelectedCategory('');
    setSelectedTags([]);
    setSelectedSort('relevance');
    setDateFrom('');
    setDateTo('');
    setCurrentPage(1);
  };

  const hasActiveFilters = useMemo(() => {
    return (
      searchQuery.trim() !== '' ||
      selectedCategory !== '' ||
      selectedTags.length > 0 ||
      dateFrom !== '' ||
      dateTo !== ''
    );
  }, [searchQuery, selectedCategory, selectedTags, dateFrom, dateTo]);

  // ─────────────────────────────────────────────────────────────────────────
  // FORMAT DATE
  // ─────────────────────────────────────────────────────────────────────────

  const formatDate = (dateString: string | null) => {
    if (!dateString) return '';
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    });
  };

  // ─────────────────────────────────────────────────────────────────────────
  // SEO
  // ─────────────────────────────────────────────────────────────────────────

  const pageTitle = searchQuery
    ? `Search: "${searchQuery}" | Highrise.pk Blog`
    : 'Search Articles | Highrise.pk Blog';

  const pageDescription = searchQuery
    ? `Search results for "${searchQuery}" - Find expert real estate articles, guides, and insights on Highrise.pk`
    : 'Search our collection of real estate articles, market insights, legal guides, and investment advice for Pakistan property market.';

  // ─────────────────────────────────────────────────────────────────────────
  // RENDER
  // ─────────────────────────────────────────────────────────────────────────

  return (
    <>
      <Head>
        <title>{pageTitle}</title>
        <meta name="description" content={pageDescription} />
        <meta name="robots" content="noindex, follow" />
        <link rel="canonical" href="https://highrise.pk/blog/search" />
      </Head>

      <div className="min-h-screen bg-gray-50">
        {/* ─────────────────────────────────────────────────────────────────── */}
        {/* HEADER */}
        {/* ─────────────────────────────────────────────────────────────────── */}
        <section className="bg-gradient-to-br from-slate-900 via-slate-800 to-cyan-900 text-white">
          <div className="container mx-auto px-4 py-12">
            {/* Breadcrumb */}
            <nav className="flex items-center gap-2 text-sm text-white/70 mb-6">
              <Link href="/" className="hover:text-white transition-colors">
                Home
              </Link>
              <span>/</span>
              <Link href="/blog" className="hover:text-white transition-colors">
                Blog
              </Link>
              <span>/</span>
              <span className="text-white">Search</span>
            </nav>

            <div className="max-w-3xl">
              <h1 className="text-3xl md:text-4xl font-bold mb-4">
                Search Articles
              </h1>
              <p className="text-white/80 text-lg mb-8">
                Find expert insights on real estate, market trends, legal guides, and more
              </p>

              {/* Search Input */}
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => {
                    setSearchQuery(e.target.value);
                    setCurrentPage(1);
                  }}
                  placeholder="Search for articles, topics, keywords..."
                  className="w-full pl-12 pr-12 py-4 rounded-xl bg-white text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-cyan-400 shadow-lg text-lg"
                  autoFocus
                />
                {searchQuery && (
                  <button
                    onClick={() => {
                      setSearchQuery('');
                      setCurrentPage(1);
                    }}
                    className="absolute right-4 top-1/2 -translate-y-1/2 p-1 rounded-full hover:bg-gray-100 transition-colors"
                  >
                    <X className="w-5 h-5 text-gray-400" />
                  </button>
                )}
              </div>
            </div>
          </div>
        </section>

        {/* ─────────────────────────────────────────────────────────────────── */}
        {/* MAIN CONTENT */}
        {/* ─────────────────────────────────────────────────────────────────── */}
        <section className="container mx-auto px-4 py-8">
          <div className="flex flex-col lg:flex-row gap-8">
            {/* ─────────────────────────────────────────────────────────────── */}
            {/* FILTERS SIDEBAR */}
            {/* ─────────────────────────────────────────────────────────────── */}
            <aside className="lg:w-72 flex-shrink-0">
              {/* Mobile Filter Toggle */}
              <button
                onClick={() => setShowFilters(!showFilters)}
                className="lg:hidden w-full flex items-center justify-between px-4 py-3 bg-white rounded-xl border border-gray-200 shadow-sm mb-4"
              >
                <span className="flex items-center gap-2 font-medium text-gray-900">
                  <SlidersHorizontal className="w-5 h-5" />
                  Filters
                  {hasActiveFilters && (
                    <span className="px-2 py-0.5 bg-cyan-100 text-cyan-700 text-xs rounded-full">
                      Active
                    </span>
                  )}
                </span>
                <ChevronDown
                  className={`w-5 h-5 text-gray-500 transition-transform ${
                    showFilters ? 'rotate-180' : ''
                  }`}
                />
              </button>

              {/* Filters Panel */}
              <div className={`${showFilters ? 'block' : 'hidden'} lg:block`}>
                <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6 space-y-6 lg:sticky lg:top-24">
                    <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6 space-y-6 lg:sticky lg:top-24">
                      {/* Filter Header */}
                      <div className="flex items-center justify-between">
                        <h3 className="font-bold text-gray-900 flex items-center gap-2">
                          <Filter className="w-4 h-4" />
                          Filters
                        </h3>
                        {hasActiveFilters && (
                          <button
                            onClick={handleClearFilters}
                            className="text-sm text-cyan-600 hover:text-cyan-700 font-medium"
                          >
                            Clear all
                          </button>
                        )}
                      </div>

                      {/* Sort */}
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Sort By
                        </label>
                        <select
