            <aside className="space-y-8">
              {/* Related Tags */}
              {relatedTags.length > 0 && (
                <RelatedTagsWidget tags={relatedTags} currentTag={tag} />
              )}

              {/* Newsletter CTA */}
              <NewsletterWidget />
            </aside>
          </div>
        </section>
      </main>
    </>
  );
}

