            >
              Create Account
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // ─── Redirecting other roles ────────────────────────────────
  if (isAdmin || userRole === 'agent' || userRole === 'developer' || userRole === 'society') {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
