import DeveloperLayout from "@/components/developer/DeveloperLayout";

// ============================================
// TYPES
// ============================================

interface Lead {
  _id: string;
  name: string;
  email: string;
  phone: string;
  message?: string;
  leadType:
    | "project_interest"
    | "call_back"
    | "site_visit"
    | "brochure_download"
    | "payment_plan"
    | "general_inquiry";
  projectSnapshot: {
    _id: string;
    projectName: string;
    slug?: string;
    city: string;
    area?: string;
    minPrice?: number;
    maxPrice?: number;
    primaryImage?: string;
  };
  developerSnapshot: {
    _id: string;
    companyName: string;
    email: string;
  };
  leadScore: number;
  priority: "low" | "medium" | "high" | "urgent";
  status:
    | "new"
    | "contacted"
    | "qualified"
    | "site_visit_scheduled"
    | "proposal_sent"
    | "negotiation"
    | "won"
    | "lost"
    | "nurture";
  source: string;
  temperature?: "cold" | "warm" | "hot" | "burning";
  scheduledVisit?: string;
  followUpDate?: string;
  lastContactedAt?: string;
  notes?: string;
  tags?: string[];
  isArchived: boolean;
  createdAt: string;
  updatedAt: string;
}

interface LeadsStats {
  all: number;
  new: number;
  contacted: number;
  qualified: number;
  won: number;
  lost: number;
  avgScore: number;
  conversionRate: number;
