                <LeadTypeIcon className="w-4 h-4 shrink-0 text-gray-400" />
                {leadTypeCfg?.label ?? lead.leadType}
              </div>
              <div className="flex items-center gap-2 text-sm text-gray-600">
                <Shield className="w-4 h-4 shrink-0 text-gray-400" />
