    _id:                    p._id ?? "",
    projectName:            p.projectName ?? "",
    projectType:            (p.projectType ?? "") as CompletedProject["projectType"],
    city:                   p.city ?? "",
    area:                   p.area ?? "",
    location:               p.location ?? "",
    startYear:              p.startYear?.toString() ?? "",
