    status:                 (p.status ?? "") as CompletedProject["status"],
    delayReason:            p.delayReason ?? "",
    expectedResolutionDate: p.expectedResolutionDate ?? "",
    totalUnits:             p.totalUnits?.toString() ?? "",
    totalPlots:             p.totalPlots?.toString() ?? "",
    totalArea:              p.totalArea ?? "",
