        </form>
      </div>

      {/* Sticky Save Bar */}
      <div className={`fixed bottom-0 left-0 right-0 z-40 transition-all duration-300 ${
        hasChanges ? "translate-y-0 opacity-100" : "translate-y-full opacity-0 pointer-events-none"
      }`}>
