  // Discount offers
  const [advanceDiscountEnabled,          setAdvanceDiscountEnabled]          = useState(false);
  const [advanceDiscountMonths,           setAdvanceDiscountMonths]           = useState('');
  const [advanceDiscountPercent,          setAdvanceDiscountPercent]          = useState('');
