import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import Head from 'next/head';
import { useRouter } from 'next/router';
import Link from 'next/link';
import {
  Building2,
  Search,
  Filter,
  Plus,
  MoreVertical,
  Edit3,
  Trash2,
  ChevronLeft,
  ChevronRight,
  AlertTriangle,
  RefreshCw,
} from 'lucide-react';
import DeveloperLayout from '@/components/developer/DeveloperLayout';
import { useDeveloperContext } from '@/components/developer/DeveloperContext';

// ─────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────

type UnitStatus = 'available' | 'reserved' | 'sold' | 'on_hold' | 'cancelled';

interface Unit {
  _id: string;
  unitNumber: string;
  floorNumber: number;
  floorName?: string;
  category: string;
  unitType: string;
  price: number;
  areaSqft?: number;
  areaMarla?: number;
  status: UnitStatus;
  bedrooms?: number;
}

interface ProjectStats {
  totalUnits: number;
  availableUnits: number;
  reservedUnits: number;
  soldUnits: number;
  onHoldUnits: number;
  minPrice: number;
  maxPrice: number;
}

interface ProjectInfo {
  _id: string;
  projectName: string;
  city: string;
  area: string;
}

interface UnitsApiResponse {
  success: boolean;
  units?: Unit[];
  stats?: ProjectStats;
  project?: ProjectInfo;
  totalPages?: number;
  currentPage?: number;
  totalCount?: number;
  message?: string;
}

// ─────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────

const STATUS_COLORS: Record<UnitStatus, string> = {
  available: 'bg-green-100 text-green-700 border-green-200',
  reserved:  'bg-yellow-100 text-yellow-700 border-yellow-200',
  sold:      'bg-red-100 text-red-700 border-red-200',
  on_hold:   'bg-gray-100 text-gray-700 border-gray-200',
  cancelled: 'bg-gray-50 text-gray-500 border-gray-200',
};

const STATUS_LABELS: Record<UnitStatus, string> = {
  available: 'Available',
  reserved:  'Reserved',
  sold:      'Sold',
  on_hold:   'On Hold',
  cancelled: 'Cancelled',
};

const PAGE_SIZE_OPTIONS = [10, 25, 50, 100] as const;

// ─────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────

function toStr(v: string | string[] | undefined): string {
  if (!v) return '';
  return Array.isArray(v) ? v[0] : v;
}

function formatPrice(n: number): string {
  return `Rs. ${n.toLocaleString('en-PK')}`;
}

// ─────────────────────────────────────────────
// Sub-components
// ─────────────────────────────────────────────

function StatCard({
  label,
  value,
  colorClass,
  borderClass,
}: {
  label: string;
  value: number;
  colorClass: string;
  borderClass: string;
}): React.ReactElement {
  return (
    <div className={`bg-white p-4 rounded-xl border shadow-sm ${borderClass}`}>
      <p className={`text-xs font-semibold uppercase ${colorClass}`}>{label}</p>
      <p className={`text-2xl font-bold mt-1 ${colorClass}`}>{value}</p>
    </div>
  );
}

function UnitsSkeleton(): React.ReactElement {
  return (
    <div className="animate-pulse space-y-3">
      {Array.from({ length: 6 }).map((_, i) => (
        <div key={i} className="h-14 bg-gray-100 rounded-xl" />
      ))}
    </div>
  );
}

// ─────────────────────────────────────────────
// Inline Action Menu (replaces Radix DropdownMenu)
// ─────────────────────────────────────────────

interface ActionMenuProps {
  unitId: string;
  projectId: string;
  openMenuId: string | null;
  setOpenMenuId: (id: string | null) => void;
  confirmDeleteId: string | null;
  setConfirmDeleteId: (id: string | null) => void;
  onDelete: (unitId: string) => void;
  deleting: boolean;
}

function ActionMenu({
  unitId,
  projectId,
  openMenuId,
  setOpenMenuId,
  confirmDeleteId,
  setConfirmDeleteId,
  onDelete,
  deleting,
}: ActionMenuProps): React.ReactElement {
  const menuRef = useRef<HTMLDivElement>(null);
  const isOpen = openMenuId === unitId;
  const isConfirming = confirmDeleteId === unitId;

  // Close on outside click
  useEffect(() => {
    if (!isOpen) return;
    function handleOutside(e: MouseEvent): void {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setOpenMenuId(null);
      }
    }
    document.addEventListener('mousedown', handleOutside);
    return () => document.removeEventListener('mousedown', handleOutside);
  }, [isOpen, setOpenMenuId]);

  // Close on Escape
  useEffect(() => {
    if (!isOpen) return;
    function handleEsc(e: KeyboardEvent): void {
      if (e.key === 'Escape') setOpenMenuId(null);
    }
    document.addEventListener('keydown', handleEsc);
    return () => document.removeEventListener('keydown', handleEsc);
  }, [isOpen, setOpenMenuId]);

  return (
    <div ref={menuRef} className="relative inline-block">
      <button
        type="button"
        onClick={() => setOpenMenuId(isOpen ? null : unitId)}
        className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
        aria-label="Unit actions"
        aria-expanded={isOpen}
      >
        <MoreVertical className="w-4 h-4 text-gray-500" />
      </button>

      {isOpen && (
        <div className="absolute right-0 top-9 z-50 min-w-[160px] bg-white rounded-xl border border-gray-200 shadow-xl p-1.5">
          {/* Edit */}
          <Link
            href={`/developer/projects/${projectId}/units/${unitId}/edit`}
            onClick={() => setOpenMenuId(null)}
            className="flex items-center gap-2 px-3 py-2 text-sm text-gray-700 hover:bg-gray-50 rounded-lg transition-colors"
          >
            <Edit3 className="w-4 h-4" />
            Edit Unit
          </Link>

          {/* Delete — two-step inline confirm */}
          {!isConfirming ? (
            <button
              type="button"
              onClick={() => {
                setOpenMenuId(null);
                setConfirmDeleteId(unitId);
              }}
              className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-red-50 rounded-lg transition-colors"
            >
              <Trash2 className="w-4 h-4" />
              Delete Unit
            </button>
          ) : null}
        </div>
      )}
    </div>
  );
}

// ─────────────────────────────────────────────
// Main Page Component
// ─────────────────────────────────────────────

function UnitsListPage(): React.ReactElement {
  const router = useRouter();
  const { profile } = useDeveloperContext();

  const projectId = useMemo(
    () => toStr(router.query?.id as string | string[] | undefined),
    [router.query?.id]
  );

  // ── Data state ──
  const [loading, setLoading]         = useState(true);
  const [units, setUnits]             = useState<Unit[]>([]);
  const [project, setProject]         = useState<ProjectInfo | null>(null);
  const [stats, setStats]             = useState<ProjectStats | null>(null);
  const [totalPages, setTotalPages]   = useState(1);
  const [totalCount, setTotalCount]   = useState(0);

  // ── Error/Action state ──
  const [fetchError, setFetchError]         = useState<string | null>(null);
  const [deleteError, setDeleteError]       = useState<string | null>(null);
  const [deleteSuccess, setDeleteSuccess]   = useState<string | null>(null);
  const [deleting, setDeleting]             = useState(false);

  // ── UI state ──
  const [openMenuId, setOpenMenuId]         = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  // ── Filters ──
  const [search, setSearch]           = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | UnitStatus>('all');
  const [floorFilter, setFloorFilter] = useState<'all' | string>('all');

  // ── Pagination ──
  const [page, setPage]   = useState(1);
  const [limit, setLimit] = useState<typeof PAGE_SIZE_OPTIONS[number]>(25);

  const abortRef = useRef<AbortController | null>(null);
  const reqSeq   = useRef(0);

  // Unique floors derived from loaded units
  const floors = useMemo(
    () =>
      Array.from(new Set(units.map((u) => u.floorNumber))).sort((a, b) => a - b),
    [units]
  );

  // ─────────────────────────────────────────
  // Fetch Units
  // ─────────────────────────────────────────

  const fetchUnits = useCallback(async (): Promise<void> => {
    if (!projectId) return;

    const seq = ++reqSeq.current;
    abortRef.current?.abort();
    const ac = new AbortController();
    abortRef.current = ac;

    setLoading(true);
    setFetchError(null);

    try {
      const qs = new URLSearchParams();
      qs.set('page', String(page));
      qs.set('limit', String(limit));
      const q = search.trim();
      if (q) qs.set('q', q);
      if (statusFilter !== 'all') qs.set('status', statusFilter);
      if (floorFilter !== 'all') qs.set('floor', floorFilter);

      const res = await fetch(
        `/api/projects/${encodeURIComponent(projectId)}/units?${qs.toString()}`,
        {
          method: 'GET',
          credentials: 'include',
          signal: ac.signal,
        }
      );

      const data: UnitsApiResponse = await res.json().catch(() => ({ success: false }));

      if (seq !== reqSeq.current) return;

      if (!res.ok || !data.success) {
        // Project not found or access denied → redirect
        if (res.status === 403 || res.status === 404) {
          void router.push('/developer/projects');
          return;
        }
        setFetchError(data.message ?? 'Failed to load units. Please try again.');
        setUnits([]);
        setStats(null);
        return;
      }

      setUnits(Array.isArray(data.units) ? data.units : []);
      setStats(data.stats ?? null);
      setProject(data.project ?? null);
      setTotalPages(data.totalPages ?? 1);
      setTotalCount(data.totalCount ?? 0);
    } catch (err: unknown) {
      if (err instanceof Error && err.name === 'AbortError') return;
      if (seq !== reqSeq.current) return;
      setFetchError('Network error. Please check your connection and try again.');
    } finally {
      if (seq === reqSeq.current) setLoading(false);
    }
  }, [projectId, page, limit, search, statusFilter, floorFilter, router]);

  useEffect(() => {
    void fetchUnits();
    return () => abortRef.current?.abort();
  }, [fetchUnits]);

  // ─────────────────────────────────────────
  // Delete Handler — two-step, no confirm()
  // ─────────────────────────────────────────

  const handleDelete = useCallback(
    async (unitId: string): Promise<void> => {
      if (!projectId || deleting) return;

      // Step 1 — first click sets confirmDeleteId (handled in ActionMenu)
      // Step 2 — second click calls this function with confirmed id
      if (confirmDeleteId !== unitId) {
        setConfirmDeleteId(unitId);
        return;
      }

      setDeleting(true);
      setDeleteError(null);
      setDeleteSuccess(null);
      setConfirmDeleteId(null);

      try {
        const res = await fetch(
          `/api/projects/${encodeURIComponent(projectId)}/units/${encodeURIComponent(unitId)}`,
          {
            method: 'DELETE',
            credentials: 'include',
          }
        );

        const data: { success: boolean; message?: string } = await res
          .json()
          .catch(() => ({ success: false }));

        if (res.ok && data.success) {
          setDeleteSuccess('Unit deleted successfully.');

          // Optimistic removal
          setUnits((prev) => prev.filter((u) => u._id !== unitId));
          setTotalCount((prev) => Math.max(0, prev - 1));

          // Optimistic stats update
          setStats((prev) => {
            if (!prev) return prev;
            const deleted = units.find((u) => u._id === unitId);
            if (!deleted) return prev;
            const next = { ...prev, totalUnits: Math.max(0, prev.totalUnits - 1) };
            if (deleted.status === 'available') next.availableUnits = Math.max(0, prev.availableUnits - 1);
            if (deleted.status === 'reserved')  next.reservedUnits  = Math.max(0, prev.reservedUnits - 1);
            if (deleted.status === 'sold')       next.soldUnits      = Math.max(0, prev.soldUnits - 1);
            if (deleted.status === 'on_hold')    next.onHoldUnits    = Math.max(0, prev.onHoldUnits - 1);
            return next;
          });

          // Auto-dismiss success banner
          setTimeout(() => setDeleteSuccess(null), 4000);
        } else {
          setDeleteError(data.message ?? 'Failed to delete unit. Please try again.');
        }
      } catch (err: unknown) {
        setDeleteError(
          err instanceof Error ? err.message : 'An unexpected error occurred.'
        );
      } finally {
        setDeleting(false);
      }
    },
    [projectId, deleting, confirmDeleteId, units]
  );

  // ─────────────────────────────────────────
  // Client-side filter (instant UX on loaded data)
  // Server receives same filters for DB query
  // ─────────────────────────────────────────

  const filteredUnits = useMemo(() => {
    const q = search.trim().toLowerCase();
    return units.filter((unit) => {
      const matchesSearch = !q || unit.unitNumber.toLowerCase().includes(q);
      const matchesStatus = statusFilter === 'all' || unit.status === statusFilter;
      const matchesFloor  = floorFilter === 'all' || unit.floorNumber === Number(floorFilter);
      return matchesSearch && matchesStatus && matchesFloor;
    });
  }, [units, search, statusFilter, floorFilter]);

  // ─────────────────────────────────────────
  // Pagination helpers
  // ─────────────────────────────────────────

  const canPrev = page > 1 && !loading;
  const canNext = page < totalPages && !loading;

  function handlePrev(): void {
    setPage((p) => Math.max(1, p - 1));
  }

  function handleNext(): void {
    setPage((p) => Math.min(totalPages, p + 1));
  }

  // ─────────────────────────────────────────
  // Render — inside DeveloperLayout
  // ─────────────────────────────────────────

  const pageTitle = project
    ? `${project.projectName} — Units | Developer Dashboard`
    : 'Unit Management | Developer Dashboard';

  return (
    <DeveloperLayout>
      <Head>
        <title>{pageTitle}</title>
        <meta name="robots" content="noindex, nofollow" />
      </Head>

      <div className="max-w-7xl mx-auto px-4 py-8 pb-20">

        {/* ── Breadcrumb + Header ── */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <nav className="flex items-center gap-2 text-sm text-gray-500 mb-2">
              <Link href="/developer/dashboard" className="hover:text-[#029bba] transition-colors">
                Dashboard
              </Link>
              <span>/</span>
              <Link href="/developer/projects" className="hover:text-[#029bba] transition-colors">
                Projects
              </Link>
              <span>/</span>
              {project ? (
                <Link
                  href={`/developer/projects/${projectId}/edit`}
                  className="hover:text-[#029bba] transition-colors truncate max-w-[160px]"
                >
                  {project.projectName}
                </Link>
              ) : (
                <span className="truncate max-w-[160px]">Project</span>
              )}
              <span>/</span>
              <span className="text-gray-700 font-medium">Units</span>
            </nav>

            <h1 className="text-2xl font-bold text-[#004063] flex items-center gap-2">
              <Building2 className="w-6 h-6 text-[#029bba]" />
              Unit Management
              {totalCount > 0 && (
                <span className="ml-2 text-sm font-normal text-gray-500">
                  ({totalCount} total)
                </span>
              )}
            </h1>

            {profile?.companyName && (
              <p className="text-sm text-gray-500 mt-1">{profile.companyName}</p>
            )}
          </div>

          <Link
            href={`/developer/projects/${projectId}/units/new`}
            className="inline-flex items-center gap-2 bg-[#029bba] hover:bg-[#027a94] text-white px-5 py-2.5 rounded-xl font-semibold shadow-md transition-colors"
          >
            <Plus className="w-5 h-5" />
            Add New Unit
          </Link>
        </div>

        {/* ── Inline banners ── */}

        {deleteSuccess && (
          <div className="mb-6 bg-[#f0fdf4] border-l-4 border-[#10b981] rounded-xl p-4 flex items-center gap-3">
            <span className="text-[#10b981] font-bold text-lg">✓</span>
            <p className="text-sm text-green-800 font-medium">{deleteSuccess}</p>
          </div>
        )}

        {deleteError && (
          <div className="mb-6 bg-[#fef2f2] border-l-4 border-[#ef4444] rounded-xl p-4 flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-[#ef4444] mt-0.5 shrink-0" />
            <div className="flex-1">
              <p className="text-sm text-red-800 font-medium">{deleteError}</p>
            </div>
            <button
              type="button"
              onClick={() => setDeleteError(null)}
              className="text-red-400 hover:text-red-600 text-lg leading-none"
              aria-label="Dismiss error"
            >
              ×
            </button>
          </div>
        )}

        {/* ── Inline delete confirm banner ── */}
        {confirmDeleteId && (
          <div className="mb-6 bg-[#fef3c7] border-l-4 border-[#f59e0b] rounded-xl p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <AlertTriangle className="w-5 h-5 text-[#f59e0b] shrink-0" />
              <p className="text-sm text-amber-800 font-medium">
                Are you sure you want to delete this unit? This action cannot be undone.
              </p>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              <button
                type="button"
                onClick={() => setConfirmDeleteId(null)}
                className="px-4 py-2 rounded-lg border border-gray-300 bg-white text-sm text-gray-700 hover:bg-gray-50 transition-colors"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => void handleDelete(confirmDeleteId)}
                disabled={deleting}
                className="px-4 py-2 rounded-lg bg-[#ef4444] hover:bg-red-600 text-white text-sm font-semibold transition-colors disabled:opacity-50"
              >
                {deleting ? 'Deleting…' : 'Yes, Delete'}
              </button>
            </div>
          </div>
        )}

        {/* ── Fetch error ── */}
        {fetchError && (
          <div className="mb-6 bg-[#fef2f2] border-l-4 border-[#ef4444] rounded-xl p-4 flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-[#ef4444] mt-0.5 shrink-0" />
            <div className="flex-1">
              <p className="text-sm text-red-800 font-medium">{fetchError}</p>
            </div>
            <button
              type="button"
              onClick={() => void fetchUnits()}
              className="flex items-center gap-1.5 text-sm text-[#029bba] hover:text-[#027a94] font-medium transition-colors"
            >
              <RefreshCw className="w-4 h-4" />
              Retry
            </button>
          </div>
        )}

        {/* ── Stats Cards ── */}
        {stats && !fetchError && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
            <StatCard
              label="Total Units"
              value={stats.totalUnits}
              colorClass="text-gray-700"
              borderClass="border-gray-100"
            />
            <StatCard
              label="Available"
              value={stats.availableUnits}
              colorClass="text-green-700"
              borderClass="border-green-100"
            />
            <StatCard
              label="Sold"
              value={stats.soldUnits}
              colorClass="text-red-700"
              borderClass="border-red-100"
            />
            <StatCard
              label="Reserved"
              value={stats.reservedUnits}
              colorClass="text-yellow-700"
              borderClass="border-yellow-100"
            />
          </div>
        )}

        {/* ── Filters Bar ── */}
        <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-sm mb-6 flex flex-col md:flex-row gap-4 justify-between items-center">
          {/* Search */}
          <div className="relative w-full md:w-80">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search by unit number..."
              value={search}
              onChange={(e) => {
                setPage(1);
                setSearch(e.target.value);
              }}
              className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none transition-all text-sm"
            />
          </div>

          <div className="flex flex-wrap gap-3 w-full md:w-auto">
            {/* Status filter */}
            <div className="relative">
              <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
              <select
                value={statusFilter}
                onChange={(e) => {
                  setPage(1);
                  setStatusFilter(e.target.value as 'all' | UnitStatus);
                }}
                className="pl-10 pr-8 py-2.5 rounded-xl border border-gray-200 focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none text-sm appearance-none bg-white cursor-pointer"
              >
                <option value="all">All Status</option>
                <option value="available">Available</option>
                <option value="sold">Sold</option>
                <option value="reserved">Reserved</option>
                <option value="on_hold">On Hold</option>
                <option value="cancelled">Cancelled</option>
              </select>
            </div>

            {/* Floor filter */}
            <select
              value={floorFilter}
              onChange={(e) => {
                setPage(1);
                setFloorFilter(e.target.value);
              }}
              className="px-4 py-2.5 rounded-xl border border-gray-200 focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none text-sm bg-white cursor-pointer"
            >
              <option value="all">All Floors</option>
              {floors.map((f) => (
                <option key={f} value={String(f)}>
                  {f === 0 ? 'Ground Floor' : `Floor ${f}`}
                </option>
              ))}
            </select>

            {/* Per-page */}
            <select
              value={limit}
              onChange={(e) => {
                setPage(1);
                setLimit(Number(e.target.value) as typeof PAGE_SIZE_OPTIONS[number]);
              }}
              className="px-4 py-2.5 rounded-xl border border-gray-200 focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/20 outline-none text-sm bg-white cursor-pointer"
            >
              {PAGE_SIZE_OPTIONS.map((n) => (
                <option key={n} value={n}>
                  {n} / page
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* ── Data Table ── */}
        <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
          {loading ? (
            <div className="p-6">
              <UnitsSkeleton />
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wide">
                      Unit No
                    </th>
                    <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wide">
                      Floor
                    </th>
                    <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wide">
                      Type / Area
                    </th>
                    <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wide">
                      Price
                    </th>
                    <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wide">
                      Status
                    </th>
                    <th className="px-6 py-4 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">
                      Actions
                    </th>
                  </tr>
                </thead>

                <tbody className="divide-y divide-gray-50">
                  {filteredUnits.length > 0 ? (
                    filteredUnits.map((unit) => (
                      <tr
                        key={unit._id}
                        className={`transition-colors ${
                          confirmDeleteId === unit._id
                            ? 'bg-red-50/60'
                            : 'hover:bg-gray-50/60'
                        }`}
                      >
                        {/* Unit Number */}
                        <td className="px-6 py-4">
                          <span className="font-semibold text-gray-900">
                            {unit.unitNumber}
                          </span>
                        </td>

                        {/* Floor */}
                        <td className="px-6 py-4 text-sm text-gray-600">
                          {unit.floorName
                            ? unit.floorName
                            : unit.floorNumber === 0
                            ? 'Ground'
                            : `Floor ${unit.floorNumber}`}
                        </td>

                        {/* Type + Area */}
                        <td className="px-6 py-4 text-sm text-gray-600">
                          <div className="flex flex-col">
                            <span className="font-medium capitalize">
                              {unit.unitType.replace(/_/g, ' ')}
                            </span>
                            <span className="text-xs text-gray-400">
                              {(unit as unknown as Record<string, unknown>).areaSqft
                                ? `${(unit as unknown as Record<string, unknown>).areaSqft} sqft`
                                : (unit as unknown as Record<string, unknown>).areaMarla
                                ? `${(unit as unknown as Record<string, unknown>).areaMarla} Marla`
                                : '—'}
                            </span>
                          </div>
                        </td>

                        {/* Price */}
                        <td className="px-6 py-4 text-sm font-semibold text-[#029bba]">
                          {formatPrice(unit.price)}
                        </td>

                        {/* Status badge */}
                        <td className="px-6 py-4">
                          <span
                            className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium border ${STATUS_COLORS[unit.status]}`}
                          >
                            {STATUS_LABELS[unit.status]}
                          </span>
                        </td>

                        {/* Actions */}
                        <td className="px-6 py-4 text-right">
                          <ActionMenu
                            unitId={unit._id}
                            projectId={projectId}
                            openMenuId={openMenuId}
                            setOpenMenuId={setOpenMenuId}
                            confirmDeleteId={confirmDeleteId}
                            setConfirmDeleteId={setConfirmDeleteId}
                            onDelete={handleDelete}
                            deleting={deleting}
                          />
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan={6} className="px-6 py-16 text-center">
                        <div className="flex flex-col items-center justify-center">
                          <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                            <Building2 className="w-8 h-8 text-gray-400" />
                          </div>
                          <p className="text-lg font-semibold text-gray-900">
                            No units found
                          </p>
                          <p className="text-sm text-gray-500 mt-1">
                            {search || statusFilter !== 'all' || floorFilter !== 'all'
                              ? 'Try adjusting your filters to see more results.'
                              : 'Get started by adding your first unit to this project.'}
                          </p>
                          {!search && statusFilter === 'all' && floorFilter === 'all' && (
                            <Link
                              href={`/developer/projects/${projectId}/units/new`}
                              className="mt-4 inline-flex items-center gap-2 text-[#029bba] font-semibold hover:underline"
                            >
                              <Plus className="w-4 h-4" />
                              Add First Unit
                            </Link>
                          )}
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* ── Pagination ── */}
        {!loading && !fetchError && totalPages > 1 && (
          <div className="mt-6 flex flex-col sm:flex-row items-center justify-between gap-4">
            {/* Page info */}
            <p className="text-sm text-gray-500">
              Page <span className="font-semibold text-gray-900">{page}</span> of{' '}
              <span className="font-semibold text-gray-900">{totalPages}</span>
              {totalCount > 0 && (
                <> &nbsp;·&nbsp; {totalCount} units total</>
              )}
            </p>

            {/* Prev / Next */}
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={handlePrev}
                disabled={!canPrev}
                className="flex items-center gap-1.5 px-4 py-2 rounded-xl border border-gray-200 bg-white text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft className="w-4 h-4" />
                Previous
              </button>

              {/* Page number pills */}
              <div className="flex items-center gap-1">
                {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => {
                  const pageNum = totalPages <= 5
                    ? i + 1
                    : page <= 3
                    ? i + 1
                    : page >= totalPages - 2
                    ? totalPages - 4 + i
                    : page - 2 + i;
                  return (
                    <button
                      key={pageNum}
                      type="button"
                      onClick={() => setPage(pageNum)}
                      className={`w-9 h-9 rounded-xl text-sm font-medium transition-colors ${
                        pageNum === page
                          ? 'bg-[#029bba] text-white shadow-sm'
                          : 'border border-gray-200 bg-white text-gray-700 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>

              <button
                type="button"
                onClick={handleNext}
                disabled={!canNext}
                className="flex items-center gap-1.5 px-4 py-2 rounded-xl border border-gray-200 bg-white text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
              >
                Next
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>
    </DeveloperLayout>
  );
}

export default UnitsListPage;

// pages/developer/projects/[id]/units/new.tsx

import React, { useCallback, useEffect, useRef, useState, useMemo } from 'react';
import Head from 'next/head';
import { useRouter } from 'next/router';
import {
  Building2,
  ChevronLeft,
  ChevronRight,
  Check,
  AlertTriangle,
  Loader2,
  Plus,
  X,
  DollarSign,
  Home,
  Camera,
  BarChart3,
} from 'lucide-react';
import DeveloperLayout from '@/components/developer/DeveloperLayout';
import { useDeveloperContext } from '@/components/developer/DeveloperContext';

// ─────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────

type UnitCategory = 'residential' | 'commercial';
type ListingType  = 'both' | 'installment' | 'full_payment';
type AreaUnit     = 'Sq.Ft' | 'Sq.Yd' | 'Sq.M';

interface ProjectInfo {
  _id:             string;
  projectName:     string;
  projectCategory: string;
  city:            string;
  area:            string;
}

interface ImageRef {
  url:      string;
  publicId: string;
}

interface InstallmentPlan {
  bookingAmount?:    number;
  downPayment?:      number;
  monthlyAmount?:    number;
  monthlyCount?:     number;
  possessionAmount?: number;
}

interface Charges {
  cornerCharges?:      number;
  floorPremium?:       number;
  parkingCharges?:     number;
  maintenanceAdvance?: number;
}

interface InvestorIntelligence {
  estimatedMonthlyRent?:  number;
  expectedRentalYield?:   number;
  capitalAppreciation?:   string;
  investmentScore?:       string;
}

// ─────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────

const MAX_IMAGES      = 15;
const MAX_IMAGE_BYTES = 5 * 1024 * 1024; // 5MB each

const AREA_UNITS: readonly AreaUnit[] = ['Sq.Ft', 'Sq.Yd', 'Sq.M'];

const RESIDENTIAL_UNIT_TYPES = [
  { value: 'studio',         label: 'Studio Apartment'    },
  { value: 'apartment_1bed', label: '1 Bedroom Apartment' },
  { value: 'apartment_2bed', label: '2 Bedroom Apartment' },
  { value: 'apartment_3bed', label: '3 Bedroom Apartment' },
  { value: 'apartment_4bed', label: '4 Bedroom Apartment' },
  { value: 'penthouse',      label: 'Penthouse'           },
  { value: 'duplex',         label: 'Duplex'              },
] as const;

const COMMERCIAL_UNIT_TYPES = [
  { value: 'shop',       label: 'Shop'       },
  { value: 'office',     label: 'Office'     },
  { value: 'food_court', label: 'Food Court' },
  { value: 'showroom',   label: 'Showroom'   },
  { value: 'warehouse',  label: 'Warehouse'  },
  { value: 'kiosk',      label: 'Kiosk'      },
] as const;

const FACING_OPTIONS = [
  { value: 'north',      label: 'North'      },
  { value: 'south',      label: 'South'      },
  { value: 'east',       label: 'East'       },
  { value: 'west',       label: 'West'       },
  { value: 'north_east', label: 'North-East' },
  { value: 'north_west', label: 'North-West' },
  { value: 'south_east', label: 'South-East' },
  { value: 'south_west', label: 'South-West' },
] as const;

const VIEW_OPTIONS = [
  { value: 'park',     label: 'Park View'     },
  { value: 'road',     label: 'Road View'     },
  { value: 'city',     label: 'City View'     },
  { value: 'garden',   label: 'Garden View'   },
  { value: 'pool',     label: 'Pool View'     },
  { value: 'mosque',   label: 'Mosque View'   },
  { value: 'hills',    label: 'Hills View'    },
  { value: 'open',     label: 'Open View'     },
  { value: 'internal', label: 'Internal View' },
] as const;

const RESIDENTIAL_FEATURES = [
  'Balcony', 'Terrace', 'Walk-in Closet', 'Modular Kitchen',
  'Italian Flooring', 'False Ceiling', 'Smart Home', 'Central AC',
];

const COMMERCIAL_FEATURES = [
  'Display Window', 'Signage Space', 'Storage Room', 'Pantry',
  'Conference Room', 'Reception', 'Washroom', 'Exhaust System',
];

const STEP_LABELS = ['Basic Info', 'Size & Price', 'Features', 'Media & Submit'] as const;

// ─────────────────────────────────────────────
// Tailwind class strings (static — no interpolation)
// ─────────────────────────────────────────────

const INPUT  = 'w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm text-gray-900 outline-none transition focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/10 placeholder:text-gray-400';
const LABEL  = 'block text-sm font-semibold text-[#004063] mb-1.5';
const TOGGLE = 'flex items-center gap-2 cursor-pointer select-none';

// ─────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────

function toStr(v: unknown): string {
  if (!v) return '';
  return Array.isArray(v) ? String(v[0]) : String(v);
}

function clamp(v: string, max: number): string {
  const s = v.trimStart();
  return s.length > max ? s.slice(0, max) : s;
}

function safeNum(v: string): number | undefined {
  const n = Number(v);
  return Number.isFinite(n) && v.trim() !== '' ? n : undefined;
}

// ─────────────────────────────────────────────
// Sub-components
// ─────────────────────────────────────────────

function StepIndicator({
  current,
}: {
  current: number;
}): React.ReactElement {
  return (
    <div className="mb-10">
      <div className="relative flex items-center justify-between">
        {/* Track line */}
        <div className="absolute top-5 left-0 right-0 h-0.5 bg-gray-100 z-0" />

        {STEP_LABELS.map((label, i) => (
          <div key={label} className="relative z-10 flex flex-col items-center gap-2">
            <div
              className={`flex h-10 w-10 items-center justify-center rounded-full font-bold text-sm transition-all duration-300 ${
                i < current
                  ? 'bg-[#10b981] text-white'
                  : i === current
                  ? 'bg-[#029bba] text-white ring-4 ring-[#029bba]/20'
                  : 'bg-gray-100 text-gray-400'
              }`}
            >
              {i < current ? <Check className="h-5 w-5" /> : i + 1}
            </div>
            <span
              className={`hidden md:block text-xs font-semibold uppercase tracking-wide ${
                i <= current ? 'text-gray-700' : 'text-gray-400'
              }`}
            >
              {label}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

function SectionCard({
  title,
  subtitle,
  icon,
  children,
}: {
  title:     string;
  subtitle?: string;
  icon?:     React.ReactElement;
  children:  React.ReactNode;
}): React.ReactElement {
  return (
    <div className="rounded-2xl border border-gray-100 bg-white shadow-sm overflow-hidden">
      <div className="flex items-center gap-3 border-b border-gray-100 bg-gray-50 px-6 py-4">
        {icon && (
          <div className="rounded-lg bg-teal-50 p-2 text-[#029bba]">
            {icon}
          </div>
        )}
        <div>
          <h3 className="text-base font-bold text-[#004063]">{title}</h3>
          {subtitle && (
            <p className="text-xs text-gray-500 mt-0.5">{subtitle}</p>
          )}
        </div>
      </div>
      <div className="p-6">{children}</div>
    </div>
  );
}

function FeatureToggle({
  label,
  active,
  onToggle,
}: {
  label:    string;
  active:   boolean;
  onToggle: () => void;
}): React.ReactElement {
  return (
    <button
      type="button"
      onClick={onToggle}
      className={`px-4 py-2 rounded-full text-sm font-medium transition-all border ${
        active
          ? 'bg-[#029bba] text-white border-[#029bba]'
          : 'bg-white text-gray-600 border-gray-200 hover:border-[#029bba] hover:text-[#029bba]'
      }`}
    >
      {active && <Check className="inline h-3 w-3 mr-1" />}
      {label}
    </button>
  );
}

function CheckField({
  id,
  label,
  checked,
  onChange,
}: {
  id:       string;
  label:    string;
  checked:  boolean;
  onChange: (v: boolean) => void;
}): React.ReactElement {
  return (
    <label htmlFor={id} className={TOGGLE}>
      <input
        id={id}
        type="checkbox"
        checked={checked}
        onChange={(e) => onChange(e.target.checked)}
        className="h-4 w-4 rounded border-gray-300 text-[#029bba] focus:ring-[#029bba]"
      />
      <span className="text-sm text-gray-700">{label}</span>
    </label>
  );
}

// ─────────────────────────────────────────────
// Main Page
// ─────────────────────────────────────────────

export default function AddUnitPage(): React.ReactElement {
  const router    = useRouter();
  const { profile } = useDeveloperContext();
  const projectId = toStr(router.query.id);

  // ── Page state ──
  const [pageLoading, setPageLoading] = useState(true);
  const [pageError,   setPageError]   = useState<string | null>(null);
  const [project,     setProject]     = useState<ProjectInfo | null>(null);

  // ── Approved status guard ─────────────────────────────────
  // Only approved developers can add units
  useEffect(() => {
    if (!profile) return;
    if (profile.status !== 'approved') {
      void router.replace('/developer/dashboard');
    }
  }, [profile, router]);

  // ── Form state ──
  const [currentStep,     setCurrentStep]     = useState(0);
  const [isSubmitting,    setIsSubmitting]     = useState(false);
  const [uploadProgress,  setUploadProgress]   = useState<string | null>(null);
  const [formError,       setFormError]        = useState<string | null>(null);
  const [stepError,       setStepError]        = useState<string | null>(null);

  // STEP 1 — Basic Info
  const [unitNumber,  setUnitNumber]  = useState('');
  const [category,    setCategory]    = useState<UnitCategory>('residential');
  const [unitType,    setUnitType]    = useState('');
  const [floorNumber, setFloorNumber] = useState('');
  const [floorName,   setFloorName]   = useState('');
  const [tower,       setTower]       = useState('');
  const [wing,        setWing]        = useState('');

  // STEP 2 — Size & Price
  const [area,            setArea]            = useState('');
  const [areaUnit,        setAreaUnit]        = useState<AreaUnit>('Sq.Ft');
  const [coveredArea,     setCoveredArea]     = useState('');
  const [balconyArea,     setBalconyArea]     = useState('');
  const [price,           setPrice]           = useState('');
  const [priceNegotiable, setPriceNegotiable] = useState(false);
  const [listingType,     setListingType]     = useState<ListingType>('both');
  const [installmentPlan, setInstallmentPlan] = useState<InstallmentPlan>({});
  const [charges,         setCharges]         = useState<Charges>({});

  // Commercial size
  const [frontWidth,  setFrontWidth]  = useState('');
  const [depth,       setDepth]       = useState('');

  // STEP 3 — Features
  // Residential
  const [bedrooms,       setBedrooms]       = useState('');
  const [bathrooms,      setBathrooms]      = useState('');
  const [balconies,      setBalconies]      = useState('');
  const [servantQuarter, setServantQuarter] = useState(false);
  const [storeRoom,      setStoreRoom]      = useState(false);
  const [laundryArea,    setLaundryArea]    = useState(false);
  const [finishingLevel, setFinishingLevel] = useState('');

  // Commercial
  const [washroom,      setWashroom]      = useState('');
  const [hasMezzanine,  setHasMezzanine]  = useState(false);
  const [mezzanineArea, setMezzanineArea] = useState('');

  // Position & view (shared)
  const [isCorner,     setIsCorner]     = useState(false);
  const [facing,       setFacing]       = useState('');
  const [view,         setView]         = useState('');
  const [isParkFacing, setIsParkFacing] = useState(false);
  const [isRoadFacing, setIsRoadFacing] = useState(false);

  // Parking (shared)
  const [parkingIncluded, setParkingIncluded] = useState(false);
  const [parkingSpaces,   setParkingSpaces]   = useState('');
  const [parkingType,     setParkingType]     = useState('');

  // Feature tags & investor
  const [features,             setFeatures]             = useState<string[]>([]);
  const [investorIntelligence, setInvestorIntelligence] = useState<InvestorIntelligence>({});

  // STEP 4 — Media
  const [localImages,    setLocalImages]    = useState<File[]>([]);
  const [localFloorPlan, setLocalFloorPlan] = useState<File | null>(null);
  const [virtualTourUrl, setVirtualTourUrl] = useState('');
  const [videoUrl,       setVideoUrl]       = useState('');
  const [shortDescription, setShortDescription] = useState('');
  const [description,      setDescription]      = useState('');

  const abortRef = useRef<AbortController | null>(null);

  // ─────────────────────────────────────────
  // Derived
  // ─────────────────────────────────────────

  const pricePerUnit = useMemo(() => {
    const p = Number(price);
    const a = Number(area);
    if (!p || !a || a <= 0) return 0;
    return Math.round(p / a);
  }, [price, area]);

  const unitTypeOptions = useMemo(
    () => category === 'residential' ? RESIDENTIAL_UNIT_TYPES : COMMERCIAL_UNIT_TYPES,
    [category]
  );

  const autoRentalYield = useMemo(() => {
    const rent  = investorIntelligence.estimatedMonthlyRent;
    const p     = Number(price);
    if (!rent || !p) return null;
    return ((rent * 12) / p * 100).toFixed(2);
  }, [investorIntelligence.estimatedMonthlyRent, price]);

  // ─────────────────────────────────────────
  // Fetch Project Meta
  // ─────────────────────────────────────────

  useEffect(() => {
    if (!projectId) return;

    async function fetchProject(): Promise<void> {
      setPageLoading(true);
      setPageError(null);
      try {
        const res  = await fetch(
          `/api/projects/${encodeURIComponent(projectId)}`,
          { method: 'GET', credentials: 'include' }
        );
        const data = await res.json().catch(() => ({}));

        if (!res.ok || !data.success) {
          if (res.status === 403 || res.status === 404) {
            void router.push('/developer/projects');
            return;
          }
          setPageError(data.message ?? 'Could not load project info.');
          return;
        }
        setProject(data.project as ProjectInfo);
      } catch (err: unknown) {
        setPageError(
          err instanceof Error ? err.message : 'Network error. Please retry.'
        );
      } finally {
        setPageLoading(false);
      }
    }

    void fetchProject();
    return () => abortRef.current?.abort();
  }, [projectId, router]);

  // ─────────────────────────────────────────
  // Feature tag toggle
  // ─────────────────────────────────────────

  const toggleFeature = useCallback((f: string): void => {
    setFeatures((prev) =>
      prev.includes(f) ? prev.filter((x) => x !== f) : [...prev, f]
    );
  }, []);

  // ─────────────────────────────────────────
  // Step validation
  // ─────────────────────────────────────────

  const validateStep = (step: number): string | null => {
    if (step === 0) {
      if (!unitNumber.trim()) return 'Unit Number is required.';
      if (!unitType)          return 'Unit Type is required.';
    }
    if (step === 1) {
      if (!area || Number(area) <= 0)   return 'Area is required.';
      if (!price || Number(price) <= 0) return 'Price is required.';
    }
    return null;
  };

  const handleNext = (): void => {
    const err = validateStep(currentStep);
    if (err) { setStepError(err); return; }
    setStepError(null);
    setCurrentStep((p) => Math.min(p + 1, STEP_LABELS.length - 1));
  };

  const handlePrev = (): void => {
    setStepError(null);
    setCurrentStep((p) => Math.max(p - 1, 0));
  };

  const goToStep = (step: number): void => {
    if (step >= currentStep) return;
    setStepError(null);
    setCurrentStep(step);
  };

  // ─────────────────────────────────────────
  // Image handlers
  // ─────────────────────────────────────────

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>): void => {
    const files = Array.from(e.target.files ?? []);
    const valid = files
      .filter((f) => f.size <= MAX_IMAGE_BYTES)
      .slice(0, MAX_IMAGES - localImages.length);
    setLocalImages((prev) => [...prev, ...valid].slice(0, MAX_IMAGES));
    e.target.value = '';
  };

  const removeImage = (index: number): void => {
    setLocalImages((prev) => prev.filter((_, i) => i !== index));
  };

  // ─────────────────────────────────────────
  // Upload helper
  // ─────────────────────────────────────────

  const uploadFile = async (file: File, folder: string): Promise<ImageRef | null> => {
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res  = await fetch(`/api/upload?folder=${folder}`, {
        method: 'POST',
        credentials: 'include',
        body: fd,
      });
      const data = await res.json().catch(() => ({}));
      if (data.success) {
        return {
          url:      data.data.url      as string,
          publicId: data.data.publicId as string,
        };
      }
      return null;
    } catch {
      return null;
    }
  };

  // ─────────────────────────────────────────
  // Submit — two-phase
  // ─────────────────────────────────────────

  const handleSubmit = async (e: React.FormEvent): Promise<void> => {
    e.preventDefault();
    if (isSubmitting) return;

    const err = validateStep(0) ?? validateStep(1);
    if (err) { setFormError(err); return; }

    setFormError(null);
    setIsSubmitting(true);

    try {
      // Phase 1 — upload images
      const uploadedImages: ImageRef[] = [];
      for (let i = 0; i < localImages.length; i++) {
        setUploadProgress(`Uploading image ${i + 1} of ${localImages.length}...`);
        const ref = await uploadFile(localImages[i], 'projects');
        if (ref) uploadedImages.push(ref);
      }

      // Phase 1b — upload floor plan
      let floorPlanRef: ImageRef | null = null;
      if (localFloorPlan) {
        setUploadProgress('Uploading floor plan...');
        floorPlanRef = await uploadFile(localFloorPlan, 'projects');
      }

      // Phase 2 — POST JSON payload
      setUploadProgress('Creating unit record...');

      const payload: Record<string, unknown> = {
        // Basic
        unitNumber:  clamp(unitNumber, 40),
        category,
        unitType:    clamp(unitType, 40),
        floorNumber: safeNum(floorNumber),
        floorName:   floorName ? clamp(floorName, 60)   : undefined,
        tower:       tower     ? clamp(tower, 40)        : undefined,
        wing:        wing      ? clamp(wing, 40)         : undefined,

        // Size
        area:        Number(area),
        areaUnit,
        coveredArea: coveredArea ? Number(coveredArea)   : undefined,
        balconyArea: balconyArea ? Number(balconyArea)   : undefined,

        // Price
        price:           Number(price),
        priceNegotiable,
        listingType,
        installmentPlan,
        charges,

        // Residential features
        ...(category === 'residential' ? {
          bedrooms:       bedrooms       ? Number(bedrooms)       : undefined,
          bathrooms:      bathrooms      ? Number(bathrooms)      : undefined,
          balconies:      balconies      ? Number(balconies)      : undefined,
          servantQuarter,
          storeRoom,
          laundryArea,
        } : {}),

        // Commercial features
        ...(category === 'commercial' ? {
          washroom:     washroom     || undefined,
          frontWidth:   frontWidth   ? Number(frontWidth)   : undefined,
          depth:        depth        ? Number(depth)        : undefined,
          hasMezzanine,
          mezzanineArea: mezzanineArea ? Number(mezzanineArea) : undefined,
        } : {}),

        // Shared features
        finishingLevel: finishingLevel || undefined,
        isCorner,
        facing:         facing         || undefined,
        view:           view           || undefined,
        isParkFacing,
        isRoadFacing,
        parkingIncluded,
        parkingSpaces:  parkingSpaces  ? Number(parkingSpaces) : undefined,
        parkingType:    parkingType    || undefined,
        features:       features.length > 0 ? features : undefined,

        // Investor intelligence
        investorIntelligence,

        // Media
        images:        uploadedImages,
        floorPlan:     floorPlanRef   ?? undefined,
        virtualTourUrl: virtualTourUrl ? virtualTourUrl.trim() : undefined,
        videoUrl:       videoUrl       ? videoUrl.trim()       : undefined,

        // Descriptions
        shortDescription: shortDescription ? clamp(shortDescription, 200) : undefined,
        description:      description      ? clamp(description, 5000)     : undefined,
      };

      const res  = await fetch(
        `/api/projects/${encodeURIComponent(projectId)}/units`,
        {
          method:  'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify(payload),
        }
      );
      const data = await res.json().catch(() => ({}));

      if (!res.ok || !data.success) {
        setFormError(data.message ?? 'Failed to create unit. Please try again.');
        return;
      }

      void router.push(
        `/developer/projects/${encodeURIComponent(projectId)}/units`
      );

    } catch (err: unknown) {
      setFormError(
        err instanceof Error ? err.message : 'An unexpected error occurred.'
      );
    } finally {
      setIsSubmitting(false);
      setUploadProgress(null);
    }
  };

  // ─────────────────────────────────────────
  // Loading
  // ─────────────────────────────────────────

  // Redirect spinner — non-approved developer
  if (profile && profile.status !== 'approved') {
    return (
      <DeveloperLayout>
        <div className="min-h-screen bg-[#f8f9fa] flex items-center justify-center">
          <div className="w-8 h-8 border-4 border-[#029bba] border-t-transparent rounded-full animate-spin" />
        </div>
      </DeveloperLayout>
    );
  }

  if (pageLoading) {
    return (
      <DeveloperLayout>
        <Head>
          <title>Add Unit | Developer Dashboard</title>
          <meta name="robots" content="noindex, nofollow" />
        </Head>
        <div className="flex h-96 items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-[#029bba]" />
        </div>
      </DeveloperLayout>
    );
  }

  // ─────────────────────────────────────────
  // Page error
  // ─────────────────────────────────────────

  if (pageError || !project) {
    return (
      <DeveloperLayout>
        <Head>
          <title>Add Unit | Developer Dashboard</title>
          <meta name="robots" content="noindex, nofollow" />
        </Head>
        <div className="mx-auto mt-20 max-w-md rounded-2xl border border-red-100 bg-white p-8 text-center shadow-sm">
          <AlertTriangle className="mx-auto mb-4 h-12 w-12 text-red-400" />
          <h2 className="text-xl font-bold text-[#004063]">Project Not Found</h2>
          <p className="mt-2 text-sm text-gray-500">
            {pageError ?? 'This project does not exist or access was denied.'}
          </p>
          <button
            type="button"
            onClick={() => void router.push('/developer/projects')}
            className="mt-6 w-full rounded-xl bg-[#029bba] py-2.5 text-sm font-bold text-white hover:bg-[#027a94] transition-colors"
          >
            Back to Projects
          </button>
        </div>
      </DeveloperLayout>
    );
  }

  // ─────────────────────────────────────────
  // Main render
  // ─────────────────────────────────────────

  return (
    <DeveloperLayout>
      <Head>
        <title>Add Unit — {project.projectName} | Highrise.pk</title>
        <meta name="robots" content="noindex, nofollow" />
      </Head>

      <div className="mx-auto max-w-4xl px-4 py-8 pb-24">

        {/* Breadcrumb */}
        <nav className="mb-6 flex items-center gap-2 text-sm text-gray-500">
          <button
            type="button"
            onClick={() => void router.back()}
            className="flex items-center gap-1 hover:text-[#029bba] transition-colors"
          >
            <ChevronLeft className="h-4 w-4" /> Back
          </button>
          <span>/</span>
          <span className="text-gray-400 truncate max-w-[140px]">
            {project.projectName}
          </span>
          <span>/</span>
          <span className="font-semibold text-gray-700">Add Unit</span>
        </nav>

        {/* Title */}
        <div className="mb-8">
          <h1 className="text-2xl font-bold text-[#004063]">Add New Unit</h1>
          <p className="mt-1 text-sm text-gray-500">
            {project.projectName} &middot; {project.city}, {project.area}
            {profile?.companyName && (
              <span className="ml-2 text-gray-400">· {profile.companyName}</span>
            )}
          </p>
        </div>

        {/* Step indicator */}
        <StepIndicator current={currentStep} />

        {/* Step error banner */}
        {stepError && (
          <div className="mb-6 flex items-center gap-3 rounded-xl border-l-4 border-[#f59e0b] bg-[#fef3c7] p-4">
            <AlertTriangle className="h-5 w-5 shrink-0 text-[#f59e0b]" />
            <p className="text-sm font-medium text-amber-800">{stepError}</p>
          </div>
        )}

        {/* Form error banner */}
        {formError && (
          <div className="mb-6 flex items-start gap-3 rounded-xl border-l-4 border-[#ef4444] bg-[#fef2f2] p-4">
            <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-[#ef4444]" />
            <p className="flex-1 text-sm font-medium text-red-800">{formError}</p>
            <button
              type="button"
              onClick={() => setFormError(null)}
              aria-label="Dismiss"
              className="text-lg leading-none text-red-300 hover:text-red-500"
            >
              ×
            </button>
          </div>
        )}

        <form onSubmit={(e) => void handleSubmit(e)} className="space-y-6">

          {/* ════════════════════════════════════
              STEP 1 — Basic Information
          ════════════════════════════════════ */}
          {currentStep === 0 && (
            <SectionCard
              title="Basic Information"
              subtitle="Unit identity and classification"
              icon={<Building2 className="h-4 w-4" />}
            >
              <div className="grid gap-5 md:grid-cols-2">

                {/* Unit Number */}
                <div>
                  <label className={LABEL}>
                    Unit Number <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    required
                    value={unitNumber}
                    onChange={(e) => setUnitNumber(clamp(e.target.value, 40))}
                    className={INPUT}
                    placeholder="e.g. A-301, SH-05, OF-12"
                  />
                  <p className="mt-1 text-xs text-gray-400">
                    Unique identifier for this unit within the project.
                  </p>
                </div>

                {/* Floor Number */}
                <div>
                  <label className={LABEL}>Floor Number</label>
                  <input
                    type="number"
                    value={floorNumber}
                    onChange={(e) => setFloorNumber(e.target.value)}
                    className={INPUT}
                    placeholder="e.g. 3 (0 = Ground)"
                    min="-5"
                    max="200"
                  />
                </div>

                {/* Category */}
                <div>
                  <label className={LABEL}>
                    Category <span className="text-red-500">*</span>
                  </label>
                  <select
                    value={category}
                    onChange={(e) => {
                      setCategory(e.target.value as UnitCategory);
                      setUnitType('');
                      setFeatures([]);
                    }}
                    className={INPUT}
                  >
                    <option value="residential">Residential</option>
                    <option value="commercial">Commercial</option>
                  </select>
                </div>

                {/* Unit Type */}
                <div>
                  <label className={LABEL}>
                    Unit Type <span className="text-red-500">*</span>
                  </label>
                  <select
                    required
                    value={unitType}
                    onChange={(e) => setUnitType(e.target.value)}
                    className={INPUT}
                  >
                    <option value="">Select unit type</option>
                    {unitTypeOptions.map((t) => (
                      <option key={t.value} value={t.value}>
                        {t.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Floor Name */}
                <div>
                  <label className={LABEL}>Floor Name</label>
                  <input
                    type="text"
                    value={floorName}
                    onChange={(e) => setFloorName(clamp(e.target.value, 60))}
                    className={INPUT}
                    placeholder="e.g. Ground Floor, Mezzanine"
                  />
                </div>

                {/* Tower / Block */}
                <div>
                  <label className={LABEL}>Tower / Block</label>
                  <input
                    type="text"
                    value={tower}
                    onChange={(e) => setTower(clamp(e.target.value, 40))}
                    className={INPUT}
                    placeholder="e.g. Tower A, Block B"
                  />
                </div>

                {/* Wing */}
                <div>
                  <label className={LABEL}>Wing</label>
                  <input
                    type="text"
                    value={wing}
                    onChange={(e) => setWing(clamp(e.target.value, 40))}
                    className={INPUT}
                    placeholder="e.g. East Wing, North Wing"
                  />
                </div>
              </div>
            </SectionCard>
          )}

          {/* ════════════════════════════════════
              STEP 2 — Size & Price
          ════════════════════════════════════ */}
          {currentStep === 1 && (
            <div className="space-y-6">

              {/* Size */}
              <SectionCard
                title="Dimensions"
                subtitle="Define unit measurements"
                icon={<Home className="h-4 w-4" />}
              >
                <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">

                  {/* Total Area */}
                  <div>
                    <label className={LABEL}>
                      Total Area <span className="text-red-500">*</span>
                    </label>
                    <div className="flex gap-2">
                      <input
                        type="number"
                        required
                        min="1"
                        value={area}
                        onChange={(e) => setArea(e.target.value)}
                        className={`${INPUT} flex-1`}
                        placeholder="e.g. 1200"
                      />
                      <select
                        value={areaUnit}
                        onChange={(e) => setAreaUnit(e.target.value as AreaUnit)}
                        className="w-24 rounded-xl border border-gray-200 bg-white px-2 py-3 text-sm outline-none focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/10"
                      >
                        {AREA_UNITS.map((u) => (
                          <option key={u} value={u}>{u}</option>
                        ))}
                      </select>
                    </div>
                  </div>

                  {/* Covered Area */}
                  <div>
                    <label className={LABEL}>Covered Area</label>
                    <input
                      type="number"
                      value={coveredArea}
                      onChange={(e) => setCoveredArea(e.target.value)}
                      className={INPUT}
                      placeholder="e.g. 1100"
                    />
                  </div>

                  {/* Balcony Area */}
                  <div>
                    <label className={LABEL}>Balcony / Terrace Area</label>
                    <input
                      type="number"
                      value={balconyArea}
                      onChange={(e) => setBalconyArea(e.target.value)}
                      className={INPUT}
                      placeholder="e.g. 100"
                    />
                  </div>

                  {/* Commercial — Front Width & Depth */}
                  {category === 'commercial' && (
                    <>
                      <div>
                        <label className={LABEL}>Front Width (ft)</label>
                        <input
                          type="number"
                          value={frontWidth}
                          onChange={(e) => setFrontWidth(e.target.value)}
                          className={INPUT}
                          placeholder="e.g. 20"
                        />
                      </div>
                      <div>
                        <label className={LABEL}>Depth (ft)</label>
                        <input
                          type="number"
                          value={depth}
                          onChange={(e) => setDepth(e.target.value)}
                          className={INPUT}
                          placeholder="e.g. 40"
                        />
                      </div>
                    </>
                  )}
                </div>
              </SectionCard>

              {/* Pricing */}
              <SectionCard
                title="Pricing"
                subtitle="Price, payment option and installment plan"
                icon={<DollarSign className="h-4 w-4" />}
              >
                <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">

                  {/* Price */}
                  <div>
                    <label className={LABEL}>
                      Price (PKR) <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="number"
                      required
                      min="1"
                      value={price}
                      onChange={(e) => setPrice(e.target.value)}
                      className={INPUT}
                      placeholder="e.g. 8500000"
                    />
                  </div>

                  {/* Price per unit */}
                  <div>
                    <label className={LABEL}>Price per {areaUnit}</label>
                    <input
                      type="text"
                      readOnly
                      value={
                        pricePerUnit
                          ? `Rs. ${pricePerUnit.toLocaleString('en-PK')}`
                          : 'Auto-calculated'
                      }
                      className={`${INPUT} bg-gray-50 text-gray-500 cursor-not-allowed`}
                    />
                  </div>

                  {/* Payment option */}
                  <div>
                    <label className={LABEL}>Payment Option</label>
                    <select
                      value={listingType}
                      onChange={(e) => setListingType(e.target.value as ListingType)}
                      className={INPUT}
                    >
                      <option value="both">Both (Installment & Cash)</option>
                      <option value="installment">Installment Only</option>
                      <option value="full_payment">Cash Only</option>
                    </select>
                  </div>
                </div>

                {/* Negotiable toggle */}
                <div className="mt-4">
                  <CheckField
                    id="negotiable"
                    label="Price is negotiable"
                    checked={priceNegotiable}
                    onChange={setPriceNegotiable}
                  />
                </div>

                {/* Installment plan */}
                {(listingType === 'installment' || listingType === 'both') && (
                  <div className="mt-6 rounded-xl border border-blue-100 bg-blue-50 p-5">
                    <h4 className="mb-4 text-sm font-bold text-blue-900">
                      Installment Plan
                    </h4>
                    <div className="grid gap-4 md:grid-cols-3">
                      {(
                        [
                          { key: 'bookingAmount',    label: 'Booking Amount'   },
                          { key: 'downPayment',      label: 'Down Payment'     },
                          { key: 'monthlyAmount',    label: 'Monthly Amount'   },
                          { key: 'monthlyCount',     label: 'No. of Months'    },
                          { key: 'possessionAmount', label: 'On Possession'    },
                        ] as Array<{ key: keyof InstallmentPlan; label: string }>
                      ).map(({ key, label }) => (
                        <div key={key}>
                          <label className={LABEL}>{label}</label>
                          <input
                            type="number"
                            value={installmentPlan[key] ?? ''}
                            onChange={(e) =>
                              setInstallmentPlan((p) => ({
                                ...p,
                                [key]: Number(e.target.value) || 0,
                              }))
                            }
                            className={INPUT}
                            placeholder="0"
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Additional charges */}
                <div className="mt-6 rounded-xl border border-gray-100 bg-gray-50 p-5">
                  <h4 className="mb-4 text-sm font-bold text-gray-700">
                    Additional Charges (for True Cost Calculator)
                  </h4>
                  <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                    {(
                      [
                        { key: 'cornerCharges',      label: 'Corner Charges'      },
                        { key: 'floorPremium',       label: 'Floor Premium'       },
                        { key: 'parkingCharges',     label: 'Parking Charges'     },
                        { key: 'maintenanceAdvance', label: 'Maintenance Advance' },
                      ] as Array<{ key: keyof Charges; label: string }>
                    ).map(({ key, label }) => (
                      <div key={key}>
                        <label className={LABEL}>{label}</label>
                        <input
                          type="number"
                          value={charges[key] ?? ''}
                          onChange={(e) =>
                            setCharges((p) => ({
                              ...p,
                              [key]: Number(e.target.value) || 0,
                            }))
                          }
                          className={INPUT}
                          placeholder="0"
                        />
                      </div>
                    ))}
                  </div>
                </div>
              </SectionCard>
            </div>
          )}

          {/* ════════════════════════════════════
              STEP 3 — Features
          ════════════════════════════════════ */}
          {currentStep === 2 && (
            <div className="space-y-6">

              {/* Residential specifics */}
              {category === 'residential' && (
                <SectionCard
                  title="Residential Features"
                  subtitle="Rooms, amenities and finishing"
                  icon={<Home className="h-4 w-4" />}
                >
                  <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-4">
                    {/* Bedrooms */}
                    <div>
                      <label className={LABEL}>Bedrooms</label>
                      <select
                        value={bedrooms}
                        onChange={(e) => setBedrooms(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        {[0, 1, 2, 3, 4, 5, 6].map((n) => (
                          <option key={n} value={n}>{n}</option>
                        ))}
                      </select>
                    </div>

                    {/* Bathrooms */}
                    <div>
                      <label className={LABEL}>Bathrooms</label>
                      <select
                        value={bathrooms}
                        onChange={(e) => setBathrooms(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        {[1, 2, 3, 4, 5, 6].map((n) => (
                          <option key={n} value={n}>{n}</option>
                        ))}
                      </select>
                    </div>

                    {/* Balconies */}
                    <div>
                      <label className={LABEL}>Balconies</label>
                      <select
                        value={balconies}
                        onChange={(e) => setBalconies(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        {[0, 1, 2, 3, 4].map((n) => (
                          <option key={n} value={n}>{n}</option>
                        ))}
                      </select>
                    </div>

                    {/* Finishing */}
                    <div>
                      <label className={LABEL}>Finishing Level</label>
                      <select
                        value={finishingLevel}
                        onChange={(e) => setFinishingLevel(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        <option value="grey_structure">Grey Structure</option>
                        <option value="standard">Standard</option>
                        <option value="premium">Premium</option>
                        <option value="luxury">Luxury</option>
                      </select>
                    </div>
                  </div>

                  {/* Toggles */}
                  <div className="mt-6 flex flex-wrap gap-6">
                    <CheckField
                      id="servant"
                      label="Servant Quarter"
                      checked={servantQuarter}
                      onChange={setServantQuarter}
                    />
                    <CheckField
                      id="store"
                      label="Store Room"
                      checked={storeRoom}
                      onChange={setStoreRoom}
                    />
                    <CheckField
                      id="laundry"
                      label="Laundry Area"
                      checked={laundryArea}
                      onChange={setLaundryArea}
                    />
                  </div>

                  {/* Feature tags */}
                  <div className="mt-6">
                    <label className={LABEL}>Additional Features</label>
                    <div className="flex flex-wrap gap-2">
                      {RESIDENTIAL_FEATURES.map((f) => (
                        <FeatureToggle
                          key={f}
                          label={f}
                          active={features.includes(f)}
                          onToggle={() => toggleFeature(f)}
                        />
                      ))}
                    </div>
                  </div>
                </SectionCard>
              )}

              {/* Commercial specifics */}
              {category === 'commercial' && (
                <SectionCard
                  title="Commercial Features"
                  subtitle="Shop / Office specifications"
                  icon={<Building2 className="h-4 w-4" />}
                >
                  <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">

                    {/* Washroom */}
                    <div>
                      <label className={LABEL}>Washroom</label>
                      <select
                        value={washroom}
                        onChange={(e) => setWashroom(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        <option value="none">None</option>
                        <option value="private">Private</option>
                        <option value="shared">Shared</option>
                      </select>
                    </div>

                    {/* Finishing */}
                    <div>
                      <label className={LABEL}>Finishing Level</label>
                      <select
                        value={finishingLevel}
                        onChange={(e) => setFinishingLevel(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        <option value="grey_structure">Grey Structure</option>
                        <option value="standard">Standard</option>
                        <option value="premium">Premium</option>
                        <option value="luxury">Luxury</option>
                      </select>
                    </div>
                  </div>

                  {/* Mezzanine */}
                  <div className="mt-5 flex flex-wrap items-center gap-6">
                    <CheckField
                      id="mezzanine"
                      label="Has Mezzanine"
                      checked={hasMezzanine}
                      onChange={setHasMezzanine}
                    />
                    {hasMezzanine && (
                      <div className="flex items-center gap-2">
                        <label className="text-sm text-gray-600 whitespace-nowrap">
                          Mezzanine Area:
                        </label>
                        <input
                          type="number"
                          value={mezzanineArea}
                          onChange={(e) => setMezzanineArea(e.target.value)}
                          className="w-28 rounded-xl border border-gray-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-[#029bba] focus:ring-2 focus:ring-[#029bba]/10"
                          placeholder="Sq.Ft"
                        />
                      </div>
                    )}
                  </div>

                  {/* Feature tags */}
                  <div className="mt-6">
                    <label className={LABEL}>Additional Features</label>
                    <div className="flex flex-wrap gap-2">
                      {COMMERCIAL_FEATURES.map((f) => (
                        <FeatureToggle
                          key={f}
                          label={f}
                          active={features.includes(f)}
                          onToggle={() => toggleFeature(f)}
                        />
                      ))}
                    </div>
                  </div>
                </SectionCard>
              )}

              {/* Position & View */}
              <SectionCard
                title="Position & View"
                subtitle="Unit location attributes within the building"
                icon={<Home className="h-4 w-4" />}
              >
                <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">
                  <div>
                    <label className={LABEL}>Facing Direction</label>
                    <select
                      value={facing}
                      onChange={(e) => setFacing(e.target.value)}
                      className={INPUT}
                    >
                      <option value="">Select</option>
                      {FACING_OPTIONS.map((o) => (
                        <option key={o.value} value={o.value}>{o.label}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className={LABEL}>View</label>
                    <select
                      value={view}
                      onChange={(e) => setView(e.target.value)}
                      className={INPUT}
                    >
                      <option value="">Select</option>
                      {VIEW_OPTIONS.map((o) => (
                        <option key={o.value} value={o.value}>{o.label}</option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="mt-5 flex flex-wrap gap-6">
                  <CheckField
                    id="corner"
                    label="Corner Unit"
                    checked={isCorner}
                    onChange={setIsCorner}
                  />
                  <CheckField
                    id="parkfacing"
                    label="Park Facing"
                    checked={isParkFacing}
                    onChange={setIsParkFacing}
                  />
                  <CheckField
                    id="roadfacing"
                    label="Road Facing"
                    checked={isRoadFacing}
                    onChange={setIsRoadFacing}
                  />
                </div>
              </SectionCard>

              {/* Parking */}
              <SectionCard
                title="Parking"
                subtitle="Parking allocation for this unit"
                icon={<Home className="h-4 w-4" />}
              >
                <div className="mb-4">
                  <CheckField
                    id="parking"
                    label="Parking Included"
                    checked={parkingIncluded}
                    onChange={setParkingIncluded}
                  />
                </div>

                {parkingIncluded && (
                  <div className="grid gap-5 md:grid-cols-2">
                    <div>
                      <label className={LABEL}>Number of Spaces</label>
                      <select
                        value={parkingSpaces}
                        onChange={(e) => setParkingSpaces(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        {[1, 2, 3, 4, 5].map((n) => (
                          <option key={n} value={n}>{n}</option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className={LABEL}>Parking Type</label>
                      <select
                        value={parkingType}
                        onChange={(e) => setParkingType(e.target.value)}
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        <option value="covered">Covered</option>
                        <option value="open">Open</option>
                        <option value="basement">Basement</option>
                      </select>
                    </div>
                  </div>
                )}
              </SectionCard>

              {/* Investor Intelligence */}
              <SectionCard
                title="Investor Intelligence"
                subtitle="Help investors make data-driven decisions"
                icon={<BarChart3 className="h-4 w-4" />}
              >
                <div className="rounded-xl border border-green-100 bg-gradient-to-br from-green-50 to-emerald-50 p-5">
                  <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-4">

                    {/* Monthly Rent */}
                    <div>
                      <label className={LABEL}>Est. Monthly Rent (PKR)</label>
                      <input
                        type="number"
                        value={investorIntelligence.estimatedMonthlyRent ?? ''}
                        onChange={(e) =>
                          setInvestorIntelligence((p) => ({
                            ...p,
                            estimatedMonthlyRent: Number(e.target.value) || 0,
                          }))
                        }
                        className={INPUT}
                        placeholder="e.g. 45000"
                      />
                    </div>

                    {/* Rental Yield */}
                    <div>
                      <label className={LABEL}>Rental Yield (%)</label>
                      <input
                        type="number"
                        step="0.1"
                        value={investorIntelligence.expectedRentalYield ?? ''}
                        onChange={(e) =>
                          setInvestorIntelligence((p) => ({
                            ...p,
                            expectedRentalYield: Number(e.target.value) || 0,
                          }))
                        }
                        className={INPUT}
                        placeholder="e.g. 6.5"
                      />
                      {autoRentalYield && (
                        <p className="mt-1 text-xs text-green-700 font-medium">
                          Auto-calc: {autoRentalYield}%
                        </p>
                      )}
                    </div>

                    {/* Capital Appreciation */}
                    <div>
                      <label className={LABEL}>Capital Appreciation</label>
                      <input
                        type="text"
                        value={investorIntelligence.capitalAppreciation ?? ''}
                        onChange={(e) =>
                          setInvestorIntelligence((p) => ({
                            ...p,
                            capitalAppreciation: clamp(e.target.value, 80),
                          }))
                        }
                        className={INPUT}
                        placeholder="e.g. 20-25% in 2 years"
                      />
                    </div>

                    {/* Investment Score */}
                    <div>
                      <label className={LABEL}>Investment Score</label>
                      <select
                        value={investorIntelligence.investmentScore ?? ''}
                        onChange={(e) =>
                          setInvestorIntelligence((p) => ({
                            ...p,
                            investmentScore: e.target.value,
                          }))
                        }
                        className={INPUT}
                      >
                        <option value="">Select</option>
                        <option value="low">Low</option>
                        <option value="medium">Medium</option>
                        <option value="high">High</option>
                        <option value="excellent">Excellent</option>
                      </select>
                    </div>
                  </div>
                </div>
              </SectionCard>
            </div>
          )}

          {/* ════════════════════════════════════
              STEP 4 — Media & Submit
          ════════════════════════════════════ */}
          {currentStep === 3 && (
            <div className="space-y-6">

              {/* Images */}
              <SectionCard
                title="Unit Photos"
                subtitle={`Upload up to ${MAX_IMAGES} photos · 5MB each`}
                icon={<Camera className="h-4 w-4" />}
              >
                <div className="flex flex-wrap gap-3 mb-4">
                  {localImages.map((file, idx) => (
                    <div key={idx} className="relative group">
                      <div className="flex h-24 w-24 items-center justify-center rounded-xl border border-gray-200 bg-gray-50">
                        <Camera className="h-7 w-7 text-gray-300" />
                      </div>
                      <p className="mt-1 w-24 truncate text-center text-[10px] text-gray-400">
                        {file.name}
                      </p>
                      <button
                        type="button"
                        onClick={() => removeImage(idx)}
                        className="absolute -right-2 -top-2 flex h-5 w-5 items-center justify-center rounded-full bg-red-500 text-white opacity-0 shadow transition-opacity group-hover:opacity-100"
                        aria-label="Remove image"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </div>
                  ))}

                  {localImages.length < MAX_IMAGES && (
                    <label className="flex h-24 w-24 cursor-pointer flex-col items-center justify-center rounded-xl border-2 border-dashed border-gray-200 transition-all hover:border-[#029bba] hover:bg-teal-50">
                      <Plus className="h-6 w-6 text-gray-400" />
                      <span className="mt-1 text-[10px] font-bold uppercase text-gray-400">
                        Add Photo
                      </span>
                      <input
                        type="file"
                        multiple
                        accept="image/*"
                        className="hidden"
                        onChange={handleImageSelect}
                      />
                    </label>
                  )}
                </div>
                <p className="text-xs text-gray-400">
                  {localImages.length} / {MAX_IMAGES} photos selected
                </p>
              </SectionCard>

              {/* Floor Plan & URLs */}
              <SectionCard
                title="Floor Plan & Media Links"
                subtitle="Optional but strongly recommended"
                icon={<Camera className="h-4 w-4" />}
              >
                <div className="grid gap-5 md:grid-cols-2">

                  {/* Floor plan */}
                  <div>
                    <label className={LABEL}>Floor Plan Image</label>
                    <label className="flex h-14 w-full cursor-pointer items-center justify-center gap-2 rounded-xl border-2 border-dashed border-gray-200 transition-all hover:border-[#029bba] hover:bg-teal-50">
                      <span className="text-sm text-gray-500">
                        {localFloorPlan ? localFloorPlan.name : 'Select floor plan'}
                      </span>
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={(e) =>
                          setLocalFloorPlan(e.target.files?.[0] ?? null)
                        }
                      />
                    </label>
                  </div>

                  {/* Virtual tour */}
                  <div>
                    <label className={LABEL}>Virtual Tour URL</label>
                    <input
                      type="url"
                      value={virtualTourUrl}
                      onChange={(e) => setVirtualTourUrl(clamp(e.target.value, 400))}
                      className={INPUT}
                      placeholder="Matterport / YouTube link"
                    />
                  </div>

                  {/* Video */}
                  <div>
                    <label className={LABEL}>Video URL</label>
                    <input
                      type="url"
                      value={videoUrl}
                      onChange={(e) => setVideoUrl(clamp(e.target.value, 400))}
                      className={INPUT}
                      placeholder="YouTube / Vimeo link"
                    />
                  </div>
                </div>
              </SectionCard>

              {/* Descriptions */}
              <SectionCard
                title="Description"
                subtitle="Describe this unit to potential buyers"
                icon={<Home className="h-4 w-4" />}
              >
                <div className="space-y-5">
                  <div>
                    <label className={LABEL}>Short Description</label>
                    <input
                      type="text"
                      value={shortDescription}
                      onChange={(e) =>
                        setShortDescription(clamp(e.target.value, 200))
                      }
                      className={INPUT}
                      placeholder="Brief one-liner shown in search results"
                      maxLength={200}
                    />
                    <p className="mt-1 text-xs text-gray-400">
                      {shortDescription.length} / 200 characters
                    </p>
                  </div>
                  <div>
                    <label className={LABEL}>Full Description</label>
                    <textarea
                      value={description}
                      onChange={(e) =>
                        setDescription(clamp(e.target.value, 5000))
                      }
                      className={`${INPUT} min-h-[160px] resize-y`}
                      placeholder="Detailed description of the unit..."
                      maxLength={5000}
                    />
                    <p className="mt-1 text-xs text-gray-400">
                      {description.length} / 5000 characters
                    </p>
                  </div>
                </div>
              </SectionCard>

              {/* Review Summary */}
              <div className="rounded-2xl border border-[#029bba]/20 bg-gradient-to-br from-[#f0fbff] to-white p-6">
                <h3 className="mb-4 text-base font-bold text-[#004063]">
                  Unit Summary
                </h3>
                <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
                  {[
                    {
                      label: 'Unit Number',
                      value: unitNumber || '—',
                    },
                    {
                      label: 'Type',
                      value:
                        unitTypeOptions.find((t) => t.value === unitType)
                          ?.label ?? '—',
                    },
                    {
                      label: 'Area',
                      value: area ? `${area} ${areaUnit}` : '—',
                    },
                    {
                      label: 'Price',
                      value: price
                        ? `Rs. ${Number(price).toLocaleString('en-PK')}`
                        : '—',
                    },
                  ].map(({ label, value }) => (
                    <div
                      key={label}
                      className="rounded-xl border border-gray-100 bg-white p-4"
                    >
                      <p className="text-xs text-gray-400 uppercase font-semibold">
                        {label}
                      </p>
                      <p className="mt-1 font-bold text-[#004063] truncate">
                        {value}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* ════════════════════════════════════
              Navigation Buttons
          ════════════════════════════════════ */}
          <div className="flex items-center justify-between border-t border-gray-100 pt-6">

            {/* Previous */}
            {currentStep > 0 ? (
              <button
                type="button"
                onClick={handlePrev}
                disabled={isSubmitting}
                className="flex items-center gap-2 rounded-xl border border-gray-200 px-6 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50 disabled:opacity-50 transition-colors"
              >
                <ChevronLeft className="h-4 w-4" /> Previous
              </button>
            ) : (
              <button
                type="button"
                onClick={() => void router.back()}
                className="flex items-center gap-2 rounded-xl border border-gray-200 px-6 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50 transition-colors"
              >
                <ChevronLeft className="h-4 w-4" /> Cancel
              </button>
            )}

            {/* Next / Submit */}
            {currentStep < STEP_LABELS.length - 1 ? (
              <button
                type="button"
                onClick={handleNext}
                className="flex items-center gap-2 rounded-xl bg-[#004063] px-8 py-3 text-sm font-bold text-white hover:bg-[#002d46] transition-colors"
              >
                Next Step <ChevronRight className="h-4 w-4" />
              </button>
            ) : (
              <button
                type="submit"
                disabled={isSubmitting}
                className="flex items-center gap-2 rounded-xl bg-[#029bba] px-8 py-3 text-sm font-bold text-white shadow-lg shadow-[#029bba]/20 hover:bg-[#027a94] disabled:cursor-not-allowed disabled:opacity-50 transition-all"
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    {uploadProgress ?? 'Processing...'}
                  </>
                ) : (
                  <>
                    <Check className="h-4 w-4" />
                    Create Unit
                  </>
                )}
              </button>
            )}
          </div>
        </form>
      </div>
    </DeveloperLayout>
  );
}

// pages/developer/projects/index.tsx
// ═══════════════════════════════════════════════════════════════
// DEVELOPER PROJECTS LIST — Highrise.pk V6.4.5
// Enterprise-grade project listing with stat cards + filters.
// ═══════════════════════════════════════════════════════════════
// ✅ 4 stat cards (Total/Active/Pending/Rejected) click-to-filter
// ✅ Grid / List view toggle
// ✅ Active filter pills with XCircle dismiss
// ✅ Search + type + sort filters
// ✅ Inline delete confirmation (no window.confirm)
// ✅ Better empty states (context-aware messaging)
// ✅ fetch() only — no apiClient
// ✅ No banned patterns
// ✅ TypeScript strict — no any
// ═══════════════════════════════════════════════════════════════

import React, {
  useState,
  useEffect,
  useCallback,
  useMemo,
} from "react";
import Head from "next/head";
import Link from "next/link";
import { useRouter } from "next/router";
import {
  Building2,
  Plus,
  Search,
  Edit,
  ExternalLink,
  LayoutGrid,
  LayoutList,
  MapPin,
