import DeveloperLayout from "@/components/developer/DeveloperLayout";
import { useDeveloperContext } from "@/components/developer/DeveloperContext";

// ============================================
// TYPES
// ============================================

interface Project {
  _id: string;
  slug?: string;
  projectName: string;
  city: string;
  areaName?: string;
  area?: string;
  projectCategory?: string;
  projectNature?: string;
  verificationStatus?: string;
  status?: string;
  featureImageUrl?: string;
  primaryImage?: string;
  isFeatured?: boolean;
  completedProjectsCount?: number;
  activeProjectsCount?: number;
  unitCount?: number;
  createdAt?: string;
}

interface ProjectsApiResponse {
  success: boolean;
  message?: string;
  projects?: Project[];
  pagination?: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

type ViewMode = "grid" | "list";
type SortOption =
  | "newest"
  | "oldest"
  | "name_asc"
  | "name_desc";

// ============================================
// CONSTANTS
// ============================================

const PAGE_LIMIT = 12;

const STATUS_CONFIG: Record<
  string,
  { label: string; color: string; bg: string; border: string; icon: React.ComponentType<{ className?: string }> }
> = {
  approved: {
    label: "Approved",
    color: "text-green-700",
    bg: "bg-green-100",
    border: "border-green-200",
    icon: CheckCircle2,
  },
  verified: {
    label: "Verified",
    color: "text-green-700",
    bg: "bg-green-100",
    border: "border-green-200",
    icon: CheckCircle2,
  },
  pending: {
    label: "Pending",
    color: "text-amber-700",
    bg: "bg-amber-100",
    border: "border-amber-200",
    icon: Clock,
  },
  rejected: {
    label: "Rejected",
    color: "text-red-700",
    bg: "bg-red-100",
    border: "border-red-200",
    icon: XCircle,
  },
  draft: {
    label: "Draft",
    color: "text-gray-600",
