          <div className="mb-4 flex items-center gap-3 text-sm text-gray-500">
            <span className="flex items-center gap-1">
              <MapPin className="h-3.5 w-3.5" />
              {dev.city ?? 'Pakistan'}
            </span>
            <span className="h-1 w-1 rounded-full bg-gray-300" />
