  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <>
      <Head>
        <title>My Properties | Highrise.pk</title>
        <meta
          name="description"
          content="Manage your property listings on Highrise.pk"
        />
        <meta name="robots" content="noindex, nofollow" />
