      {/* ── Banner ────────────────────────────────────────────────────────── */}
      {banner && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[130] animate-fadeIn">
          <div
            className={`flex items-center gap-3 px-5 py-3 rounded-xl shadow-xl border-l-4 ${
              banner.type === "success"
