              </div>

              {/* Filter toggle (mobile) */}
              <button
                onClick={() => setShowFilters(v => !v)}
                className={`sm:hidden flex items-center gap-2 px-4 py-2.5 rounded-xl border text-sm font-medium transition-colors ${
