        </section>
      </div>
    </>
  );
}

// ─── Sub-Component: FAQ Item ──────────────────────────────────────────────────

interface FaqItemProps {
  question: string;
  answer: string;
}

function FaqItem({ question, answer }: FaqItemProps): React.ReactElement {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div
      className={`bg-white rounded-2xl border-2 overflow-hidden transition-all ${
        isOpen ? 'border-[#029bba] shadow-md' : 'border-gray-200'
      }`}
    >
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="w-full px-5 py-4 flex items-center justify-between gap-3 text-left hover:bg-gray-50 transition-colors"
      >
        <span className="font-semibold text-gray-900 text-sm md:text-base">{question}</span>
        <ChevronRight
          className={`w-5 h-5 flex-shrink-0 transition-transform duration-200 ${
            isOpen ? 'rotate-90 text-[#029bba]' : 'text-gray-400'
          }`}
        />
      </button>
      {isOpen && (
        <div className="px-5 pb-4 pt-1 text-sm text-gray-700 leading-relaxed border-t border-gray-100">
          {answer}
        </div>
      )}
    </div>
  );
}

// pages/tools/price-estimator.tsx
import React, { useState, useEffect, useRef, useCallback } from 'react';
import Head from 'next/head';
import Link from 'next/link';
import {
  DollarSign, MapPin, Building2, Home, Maximize, TrendingUp,
  TrendingDown, Minus, AlertTriangle, CheckCircle, XCircle,
  Loader2, Search, Calculator, Banknote, ChevronRight,
  ArrowRight, Info, Sparkles, Award, Activity, Shield,
  BadgeCheck, ArrowDown, ArrowUp, ShieldCheck, X,
  HelpCircle, Lightbulb,
} from 'lucide-react';

// ─── Types ────────────────────────────────────────────────────────────────────

type ListingType = 'sale' | 'rent';
type PropertyType =
  | 'House'
  | 'Apartment'
  | 'Upper Portion'
  | 'Lower Portion'
  | 'Residential Plot'
  | 'Commercial Plot'
  | 'Office'
  | 'Shop';

type AreaUnit = 'Marla' | 'Kanal' | 'Sq Ft' | 'Sq Yd';

interface EstimateInput {
  city: string;
  area: string;
  society?: string;
  propertyType: PropertyType;
  listingType: ListingType;
  size: number;
  sizeUnit: AreaUnit;
  bedrooms?: number;
  askingPrice?: number;
}

interface ComparableProperty {
  _id: string;
  title: string;
  price: number;
  size: number;
  sizeUnit: string;
  bedrooms?: number;
  daysAgo: number;
  slug?: string;
}

interface EstimateResult {
  fairPriceMin: number;
  fairPriceMax: number;
  fairPriceMedian: number;
  pricePerUnit: number;
  pricePerUnitLabel: string;
  verdict: 'underpriced' | 'fair' | 'slightly_high' | 'overpriced' | 'no_data';
  verdictMessage: string;
  confidence: 'low' | 'medium' | 'high';
  comparableCount: number;
  comparables: ComparableProperty[];
  marketTrend?: {
    direction: 'up' | 'down' | 'stable';
    percentage: number;
    period: string;
  };
  asking?: {
    amount: number;
    deviationPercent: number;
    suggestion: string;
  };
  insights: string[];
}

interface CityOption {
  name: string;
  propertyCount?: number;
}

// ─── Constants ────────────────────────────────────────────────────────────────

const POPULAR_CITIES = [
  'Lahore', 'Islamabad', 'Karachi', 'Rawalpindi', 'Faisalabad',
  'Multan', 'Peshawar', 'Quetta', 'Gujranwala', 'Sialkot',
];

const PROPERTY_TYPES: { id: PropertyType; label: string; icon: React.ReactElement }[] = [
  { id: 'House', label: 'House', icon: <Home className="w-4 h-4" /> },
  { id: 'Apartment', label: 'Apartment / Flat', icon: <Building2 className="w-4 h-4" /> },
  { id: 'Upper Portion', label: 'Upper Portion', icon: <Building2 className="w-4 h-4" /> },
  { id: 'Lower Portion', label: 'Lower Portion', icon: <Building2 className="w-4 h-4" /> },
  { id: 'Residential Plot', label: 'Residential Plot', icon: <Maximize className="w-4 h-4" /> },
  { id: 'Commercial Plot', label: 'Commercial Plot', icon: <Maximize className="w-4 h-4" /> },
  { id: 'Office', label: 'Office', icon: <Building2 className="w-4 h-4" /> },
  { id: 'Shop', label: 'Shop', icon: <Building2 className="w-4 h-4" /> },
];

const SIZE_UNITS: { id: AreaUnit; label: string }[] = [
  { id: 'Marla', label: 'Marla' },
  { id: 'Kanal', label: 'Kanal' },
  { id: 'Sq Ft', label: 'Sq Ft' },
  { id: 'Sq Yd', label: 'Sq Yd' },
];

// ─── Helpers ──────────────────────────────────────────────────────────────────

function formatPKR(amount: number): string {
  if (amount >= 10_000_000) return `Rs ${(amount / 10_000_000).toFixed(2)} Cr`;
  if (amount >= 100_000) return `Rs ${(amount / 100_000).toFixed(2)} Lac`;
  return `Rs ${amount.toLocaleString()}`;
}

function getVerdictConfig(verdict: EstimateResult['verdict']): {
  label: string;
  color: string;
  bg: string;
  border: string;
  icon: React.ReactElement;
} {
  switch (verdict) {
    case 'underpriced':
      return {
        label: 'Underpriced — Great Deal',
        color: 'text-[#10b981]',
        bg: 'bg-[#f0fdf4]',
        border: 'border-[#10b981]',
        icon: <ArrowDown className="w-6 h-6" />,
      };
    case 'fair':
      return {
        label: 'Fair Price',
        color: 'text-[#10b981]',
        bg: 'bg-[#f0fdf4]',
        border: 'border-[#10b981]',
        icon: <CheckCircle className="w-6 h-6" />,
      };
    case 'slightly_high':
      return {
        label: 'Slightly Above Market',
        color: 'text-[#f59e0b]',
        bg: 'bg-[#fef3c7]',
        border: 'border-[#f59e0b]',
        icon: <AlertTriangle className="w-6 h-6" />,
      };
    case 'overpriced':
      return {
        label: 'Overpriced',
        color: 'text-[#ef4444]',
        bg: 'bg-[#fef2f2]',
        border: 'border-[#ef4444]',
        icon: <ArrowUp className="w-6 h-6" />,
      };
    default:
      return {
        label: 'Insufficient Data',
        color: 'text-gray-600',
        bg: 'bg-gray-50',
        border: 'border-gray-300',
        icon: <Info className="w-6 h-6" />,
      };
  }
}

